#include <stdio.h>
#include <stdlib.h>
#include <signal.h>
#include <pigpio.h>

#define ADS1115_ADDRESS 0x48
#define ADS1115_CONVERT 0x00
#define ADS1115_CONFIG 0x01
#define ADS1115_DR_128SPS 0x80
#define ADS1115_PGA_4_096V 0x20
#define ADS1115_MUX_SINGLE_0 0x04

volatile sig_atomic_t stop;

void handle_sigint(int signum) {
    stop = 1;
}

int main() {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Failed to initialize pigpio\n");
        return EXIT_FAILURE;
    }

    if (signal(SIGINT, handle_sigint) == SIG_ERR) {
        fprintf(stderr, "Failed to set signal handler\n");
        gpioTerminate();
        return EXIT_FAILURE;
    }

    int i2c_handle = i2cOpen(1, ADS1115_ADDRESS, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Failed to open I2C device\n");
        gpioTerminate();
        return EXIT_FAILURE;
    }

    uint16_t config = ADS1115_DR_128SPS | ADS1115_PGA_4_096V | ADS1115_MUX_SINGLE_0;
    if (i2cWriteI2CBlockData(i2c_handle, ADS1115_CONFIG, &config, 2) != 2) {
        fprintf(stderr, "Failed to write configuration to ADS1115\n");
        i2cClose(i2c_handle);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    while (!stop) {
        uint16_t raw_data;
        if (i2cReadI2CBlockData(i2c_handle, ADS1115_CONVERT, &raw_data, 2) != 2) {
            fprintf(stderr, "Failed to read data from ADS1115\n");
            break;
        }

        int16_t data = (raw_data >> 8) | (raw_data << 8);
        float voltage = data * 4.096 / 32768.0;
        float current = voltage / 0.04;

        printf("Current: %.2f A\n", current);

        gpioDelay(500000); // 500ms
    }

    i2cClose(i2c_handle);
    gpioTerminate();

    return EXIT_SUCCESS;
}

#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <pigpio.h>
#include <errno.h>

#define FLAME_SENSOR_GPIO 4
#define FLAME_SENSOR_SPI_CHANNEL 0
#define FLAME_SENSOR_SPI_SPEED 1000000
#define FLAME_SENSOR_FILE "flame_data.csv"
#define FLAME_SENSOR_MIN_TEMP 10
#define FLAME_SENSOR_MAX_TEMP 40

int main(int argc, char *argv[]) {
    FILE *file;
    int spi_fd, gpio_fd, flame_detected, temp;
    time_t rawtime;
    struct tm *timeinfo;
    char buffer[80];

    // Initialize GPIO and SPI
    gpio_fd = gpioInitialise();
    if (gpio_fd < 0) {
        fprintf(stderr, "Failed to initialize GPIO: %s\n", strerror(errno));
        return EXIT_FAILURE;
    }

    spi_fd = spiOpen(0, FLAME_SENSOR_SPI_CHANNEL, FLAME_SENSOR_SPI_SPEED);
    if (spi_fd < 0) {
        fprintf(stderr, "Failed to open SPI: %s\n", strerror(errno));
        gpioTerminate();
        return EXIT_FAILURE;
    }

    // Open file for logging
    file = fopen(FLAME_SENSOR_FILE, "a");
    if (file == NULL) {
        fprintf(stderr, "Failed to open file: %s\n", strerror(errno));
        spiClose(spi_fd);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    // Set up GPIO for input
    if (gpioSetMode(FLAME_SENSOR_GPIO, PI_INPUT) != 0) {
        fprintf(stderr, "Failed to set GPIO mode: %s\n", strerror(errno));
        fclose(file);
        spiClose(spi_fd);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    // Main loop
    while (1) {
        // Read flame sensor digital output
        flame_detected = gpioRead(FLAME_SENSOR_GPIO);

        // Read flame sensor analog output
        temp = spiTransfer(spi_fd, 0x01, 0x00, 0x00);

        // Map ADC value to temperature
        temp = (temp * (FLAME_SENSOR_MAX_TEMP - FLAME_SENSOR_MIN_TEMP) / 1023) + FLAME_SENSOR_MIN_TEMP;

        // Get current time
        time(&rawtime);
        timeinfo = localtime(&rawtime);
        strftime(buffer, sizeof(buffer), "%Y-%m-%d %H:%M:%S", timeinfo);

        // Log data to file
        fprintf(file, "%s,%d,%d\n", buffer, flame_detected, temp);

        // Flush buffer to file
        fflush(file);

        // Wait for 1 second
        sleep(1);
    }

    // Clean up
    fclose(file);
    spiClose(spi_fd);
    gpioTerminate();
    return EXIT_SUCCESS;
}

#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <signal.h>
#include <time.h>
#include <pigpio.h>

#define FLAME_PIN 4
#define TEMP_PIN 0
#define BUZZER_PIN 27
#define FLAME_THRESHOLD 50
#define TEMP_THRESHOLD 60
#define ADC_CHANNEL 0
#define ADC_ADDRESS 0x48
#define ADC_GAIN 0x02
#define ADC_SPS 0x07
#define ADC_CONFIGURATION 0x8583
#define LOG_FILE "fire_log.txt"

volatile sig_atomic_t running = 1;
time_t last_flame_time = 0;
FILE *log_file;

void handle_sigint(int signum) {
    running = 0;
}

void isr_callback(int gpio, int level, uint32_t tick) {
    if (level == 0 && tick - last_flame_time >= FLAME_THRESHOLD) {
        last_flame_time = tick;
        printf("Flame detected!\n");
        if (log_file) {
            time_t now = time(NULL);
            fprintf(log_file, "Flame detected at %s\n", ctime(&now));
            fflush(log_file);
        }
    }
}

int main() {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Failed to initialize pigpio\n");
        return 1;
    }

    signal(SIGINT, handle_sigint);

    if (gpioSetISRFunc(FLAME_PIN, 0, 0, isr_callback) < 0) {
        fprintf(stderr, "Failed to set ISR function for flame sensor\n");
        gpioTerminate();
        return 1;
    }

    if (gpioSetMode(BUZZER_PIN, PI_OUTPUT) < 0) {
        fprintf(stderr, "Failed to set mode for buzzer\n");
        gpioTerminate();
        return 1;
    }

    if ((log_file = fopen(LOG_FILE, "a")) == NULL) {
        fprintf(stderr, "Failed to open log file\n");
        gpioTerminate();
        return 1;
    }

    int i2c_handle = i2cOpen(1, ADC_ADDRESS, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Failed to open I2C handle\n");
        fclose(log_file);
        gpioTerminate();
        return 1;
    }

    uint16_t config = ADC_CONFIGURATION | ADC_GAIN | ADC_SPS;
    if (i2cWriteByteData(i2c_handle, 1, config) < 0) {
        fprintf(stderr, "Failed to write configuration to ADC\n");
        i2cClose(i2c_handle);
        fclose(log_file);
        gpioTerminate();
        return 1;
    }

    while (running) {
        int16_t temp = i2cReadWordData(i2c_handle, ADC_CHANNEL);
        if (temp < 0) {
            fprintf(stderr, "Failed to read temperature from ADC\n");
            continue;
        }

        float voltage = (float)temp / 32768.0 * 4.096;
        float temperature = voltage / 0.01;

        if (temperature > TEMP_THRESHOLD) {
            printf("Temperature above threshold: %.2f°C\n", temperature);
            if (log_file) {
                time_t now = time(NULL);
                fprintf(log_file, "Temperature above threshold at %s: %.2f°C\n", ctime(&now), temperature);
                fflush(log_file);
            }
        }

        gpioDelay(100000); // 100ms delay
    }

    gpioWrite(BUZZER_PIN, 0);
    gpioSetISRFunc(FLAME_PIN, 0, 0, NULL);
    i2cClose(i2c_handle);
    fclose(log_file);
    gpioTerminate();

    return 0;
}

#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <stdbool.h>
#include <string.h>
#include <time.h>
#include <unistd.h>
#include <fcntl.h>
#include <signal.h>
#include <sys/ioctl.h>
#include <sys/time.h>
#include <sys/stat.h>
#include <linux/spi/spidev.h>
#include <gpiod.h>

#define DEFAULT_THRESHOLD 5.0
#define DEFAULT_SENSITIVITY 0.1
#define SPI_SPEED 1000000
#define SPI_MODE 0
#define SPI_BITS 8
#define ADC_CHANNEL 0
#define FAN_PIN 18

static bool running = true;
static float threshold = DEFAULT_THRESHOLD;
static float sensitivity = DEFAULT_SENSITIVITY;
static int spi_fd = -1;
static struct gpiod_chip *gpio_chip = NULL;
static struct gpiod_line *fan_line = NULL;

static void cleanup() {
    if (spi_fd != -1) close(spi_fd);
    if (gpio_chip) gpiod_chip_close(gpio_chip);
    if (fan_line) gpiod_line_release(fan_line);
}

static void handle_signal(int signum) {
    running = false;
}

static float read_current() {
    uint8_t tx[3] = {0x01, 0x80, 0x00};
    uint8_t rx[3];
    struct spi_ioc_transfer tr = {
        .tx_buf = (unsigned long)tx,
        .rx_buf = (unsigned long)rx,
        .len = sizeof(tx),
        .speed_hz = SPI_SPEED,
        .delay_usecs = 0,
        .bits_per_word = SPI_BITS,
        .cs_change = 0,
        .pad = 0
    };
    if (ioctl(spi_fd, SPI_IOC_MESSAGE(1), &tr) < 0) {
        perror("SPI transfer failed");
        exit(EXIT_FAILURE);
    }
    int value = ((rx[1] & 0x03) << 8) | rx[2];
    return (value / 1024.0) * sensitivity;
}

static void log_current(float current) {
    time_t now = time(NULL);
    struct tm *t = localtime(&now);
    char timestamp[20];
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%dT%H:%M:%S", t);
    printf("%s Current: %.2f A\n", timestamp, current);
    FILE *file = fopen("current_log.txt", "a");
    if (file) {
        fprintf(file, "%s Current: %.2f A\n", timestamp, current);
        fclose(file);
    }
}

int main(int argc, char *argv[]) {
    atexit(cleanup);
    signal(SIGINT, handle_signal);
    signal(SIGTERM, handle_signal);

    spi_fd = open("/dev/spidev0.0", O_RDWR);
    if (spi_fd < 0) {
        perror("Failed to open SPI device");
        exit(EXIT_FAILURE);
    }

    gpio_chip = gpiod_chip_open_by_name("gpiochip4");
    if (!gpio_chip) {
        gpio_chip = gpiod_chip_open(0);
    }
    if (!gpio_chip) {
        perror("Failed to open GPIO chip");
        exit(EXIT_FAILURE);
    }

    fan_line = gpiod_chip_get_line(gpio_chip, FAN_PIN);
    if (!fan_line) {
        perror("Failed to get FAN GPIO line");
        exit(EXIT_FAILURE);
    }

    gpiod_line_request_output(fan_line, "fan", 0);

    while (running) {
        float current = read_current();
        log_current(current);
        if (current > threshold) {
            gpiod_line_set_value(fan_line, 1);
        } else {
            gpiod_line_set_value(fan_line, 0);
        }
        sleep(1);
    }

    return 0;
}

