#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <pigpio.h>
#include <errno.h>

#define FLAME_SENSOR_GPIO 4
#define ADC_CHANNEL 0
#define ADC_MAX_VALUE 1023
#define TEMPERATURE_MIN 10.0
#define TEMPERATURE_MAX 40.0
#define SPI_SPEED 1000000
#define CSV_FILE_NAME "flame_data.csv"

int main(int argc, char *argv[]) {
    FILE *file;
    int spi_handle;
    uint8_t tx_buffer[3] = {1, 0, 0};
    uint8_t rx_buffer[3];
    float temperature;
    int flame_presence;
    struct timespec sleep_time = {1, 0};

    if (gpioInitialise() < 0) {
        fprintf(stderr, "Failed to initialize pigpio: %s\n", strerror(errno));
        return EXIT_FAILURE;
    }

    spi_handle = spiOpen(0, 0, SPI_SPEED);
    if (spi_handle < 0) {
        fprintf(stderr, "Failed to open SPI handle: %s\n", strerror(errno));
        gpioTerminate();
        return EXIT_FAILURE;
    }

    file = fopen(CSV_FILE_NAME, "a");
    if (!file) {
        fprintf(stderr, "Failed to open CSV file: %s\n", strerror(errno));
        spiClose(spi_handle);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    while (1) {
        clock_nanosleep(CLOCK_MONOTONIC, 0, &sleep_time, NULL);

        tx_buffer[1] = (ADC_CHANNEL << 4) | 0x08;
        if (spiXfer(spi_handle, tx_buffer, rx_buffer, 3) < 0) {
            fprintf(stderr, "Failed to perform SPI transfer: %s\n", strerror(errno));
            continue;
        }

        flame_presence = gpioRead(FLAME_SENSOR_GPIO);
        temperature = (rx_buffer[1] << 8 | rx_buffer[2]) * (TEMPERATURE_MAX - TEMPERATURE_MIN) / ADC_MAX_VALUE + TEMPERATURE_MIN;

        if (flame_presence < 0 || temperature < TEMPERATURE_MIN || temperature > TEMPERATURE_MAX) {
            fprintf(stderr, "Sensor error: flame_presence = %d, temperature = %.2f\n", flame_presence, temperature);
            continue;
        }

        fprintf(file, "%ld,%d,%.2f\n", time(NULL), flame_presence, temperature);
        fflush(file);
    }

    fclose(file);
    spiClose(spi_handle);
    gpioTerminate();
    return EXIT_SUCCESS;
}

#include <stdio.h>
