#define I2C_ADDR 0x04
#define CO_THRESHOLD 25
#define LOG_FILE "co_log.txt"
#define ALERT_FILE "alert_log.txt"

volatile sig_atomic_t stop = 0;

void signal_handler(int signum) {
    stop = 1;
}

int main() {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Failed to initialize pigpio\n");
        return EXIT_FAILURE;
    }

    if (signal(SIGINT, signal_handler) == SIG_ERR || signal(SIGTERM, signal_handler) == SIG_ERR) {
        fprintf(stderr, "Failed to set signal handler\n");
        gpioTerminate();
        return EXIT_FAILURE;
    }

    int i2c = i2cOpen(1, I2C_ADDR, 0);
    if (i2c < 0) {
        fprintf(stderr, "Failed to open I2C device\n");
        gpioTerminate();
        return EXIT_FAILURE;
    }

    FILE *log_file = fopen(LOG_FILE, "w");
    if (log_file == NULL) {
        fprintf(stderr, "Failed to open log file\n");
        gpioTerminate();
        i2cClose(i2c);
        return EXIT_FAILURE;
    }

    FILE *alert_file = fopen(ALERT_FILE, "w");
    if (alert_file == NULL) {
        fprintf(stderr, "Failed to open alert file\n");
        gpioTerminate();
        i2cClose(i2c);
        fclose(log_file);
        return EXIT_FAILURE;
    }

    while (!stop) {
        uint8_t buffer[4];
        if (i2cReadFile(i2c, buffer, sizeof(buffer)) != sizeof(buffer)) {
            fprintf(stderr, "Failed to read from I2C device\n");
            break;
        }

        int co_level = (buffer[1] << 8) | buffer[0];
        if (co_level > CO_THRESHOLD) {
            fprintf(alert_file, "CO level above threshold: %d PPM\n", co_level);
        }

        fprintf(log_file, "CO level: %d PPM\n", co_level);
        sleep(5);
    }

    fclose(alert_file);
    fclose(log_file);
    i2cClose(i2c);
    gpioTerminate();

    return EXIT_SUCCESS;
}

