#include <pigpio.h>
#include <gpiod.h>

#define SPI_CHANNEL 0
#define SPI_SPEED 500000
#define ADC_CHANNELS 2
#define SAMPLES_PER_CHANNEL 100
#define SAMPLE_INTERVAL 1000 // 1 ms
#define RMS_THRESHOLD 0.7
#define LED_PIN 27

FILE *log_file;
uint8_t spi_mode = 0;
uint8_t spi_bits = 8;
uint8_t spi_lsb = 0;
uint8_t spi_msb = 1;
uint8_t spi_delay = 0;
int spi_fd = -1;
int led_fd = -1;

void cleanup() {
    if (spi_fd != -1) spiClose(spi_fd);
    if (led_fd != -1) gpioWrite(led_fd, 0);
    if (log_file) fclose(log_file);
}

void sigint_handler(int signum) {
    cleanup();
    exit(0);
}

float calculate_rms(int *samples, int count) {
    float sum = 0.0;
    for (int i = 0; i < count; i++) {
        sum += samples[i] * samples[i];
    }
    return sqrt(sum / count);
}

int main() {
    signal(SIGINT, sigint_handler);

    if ((spi_fd = spiOpen(SPI_CHANNEL, SPI_SPEED, spi_mode)) < 0) {
        fprintf(stderr, "Failed to open SPI channel\n");
        return -1;
    }

    if ((led_fd = gpioOpen(LED_PIN, PI_OUTPUT)) < 0) {
        fprintf(stderr, "Failed to open LED pin\n");
        return -1;
    }

    if ((log_file = fopen("audio_events.csv", "w")) == NULL) {
        fprintf(stderr, "Failed to open log file\n");
        return -1;
    }

    fprintf(log_file, "Timestamp,Mic1 RMS,Mic2 RMS\n");

    int samples[ADC_CHANNELS][SAMPLES_PER_CHANNEL];
    struct timespec start_time, current_time;
    clock_gettime(CLOCK_MONOTONIC, &start_time);

    while (1) {
        for (int channel = 0; channel < ADC_CHANNELS; channel++) {
            for (int i = 0; i < SAMPLES_PER_CHANNEL; i++) {
                samples[channel][i] = spiReadByte(spi_fd);
            }
        }

        float mic1_rms = calculate_rms(samples[0], SAMPLES_PER_CHANNEL);
        float mic2_rms = calculate_rms(samples[1], SAMPLES_PER_CHANNEL);

        clock_gettime(CLOCK_MONOTONIC, &current_time);
        long elapsed_ms = (current_time.tv_sec - start_time.tv_sec) * 1000 +
                           (current_time.tv_nsec - start_time.tv_nsec) / 1000000;

        fprintf(log_file, "%ld,%f,%f\n", elapsed_ms, mic1_rms, mic2_rms);

        if (mic1_rms > RMS_THRESHOLD || mic2_rms > RMS_THRESHOLD) {
            gpioWrite(led_fd, 1);
            usleep(500000);
            gpioWrite(led_fd, 0);
        }

        usleep(SAMPLE_INTERVAL);
    }

    cleanup();
    return 0;
}

