#include <stdio.h>
#include <stdlib.h>
#include <signal.h>
#include <pigpio.h>

#define MLX91204_VOLTAGE_MIN 0.5
#define MLX91204_VOLTAGE_MAX 4.5
#define MLX91204_CURRENT_MAX 100.0
#define MLX91204_THRESHOLD 50.0
#define ADS1115_ADDRESS 0x48
#define ADS1115_CHANNEL_A0 0x40
#define ADS1115_CONVERSION_RATE 128 // 128 samples per second

volatile sig_atomic_t stop = 0;

void signal_handler(int signum) {
    stop = 1;
}

int main() {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialization failed\n");
        return EXIT_FAILURE;
    }

    signal(SIGINT, signal_handler);

    int i2c = gpioI2COpen(1, ADS1115_ADDRESS);
    if (i2c < 0) {
        fprintf(stderr, "I2C bus read failed\n");
        gpioTerminate();
        return EXIT_FAILURE;
    }

    int led = 17;
    gpioSetMode(led, PI_OUTPUT);

    float current_buffer[100] = {0};
    int buffer_index = 0;
    float current_sum = 0;
    float current_avg = 0;

    while (!stop) {
        uint16_t raw = 0;
        if (gpioI2CReadDevice(i2c, ADS1115_CHANNEL_A0, &raw) < 0) {
            fprintf(stderr, "I2C bus read failed\n");
            break;
        }

        float voltage = (raw * 4.096) / 32768.0; // 4.096V reference
        float current = (voltage - MLX91204_VOLTAGE_MIN) / (MLX91204_VOLTAGE_MAX - MLX91204_VOLTAGE_MIN) * MLX91204_CURRENT_MAX;

        current_buffer[buffer_index] = current;
        current_sum -= current_buffer[buffer_index];
        current_sum += current;
        buffer_index = (buffer_index + 1) % 100;
        current_avg = current_sum / 100.0;

        if (current_avg > MLX91204_THRESHOLD) {
            gpioWrite(led, PI_HIGH);
        } else {
            gpioWrite(led, PI_LOW);
        }

        usleep(100000); // 10Hz
    }

    gpioI2CWriteClose(i2c);
    gpioTerminate();
    return EXIT_SUCCESS;
}

#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <pigpio.h>

#define I2C_BUS 1
#define I2C_ADDRESS 0x29
#define CLEAR_REG 0x14
#define RED_REG 0x16
#define GREEN_REG 0x18
#define BLUE_REG 0x1A
#define ATIME_REG 0x01
#define CONTROL_REG 0x0F
#define ENABLE_REG 0x00
#define ENABLE_PON 0x01
#define ENABLE_AEN 0x02
#define GAIN_4X 0x01
#define INTEGRATION_TIME_2_4MS 0xFF
#define ID_REG 0x12
#define ID_VALUE 0x44
#define COLOR_LOG_FILE "color_log.csv"
#define COLOR_LOG_HEADER "Timestamp, Clear, Red, Green, Blue\n"
#define COLOR_LOG_FORMAT "%s, %u, %u, %u, %u\n"

volatile sig_atomic_t running = 1;

void sig_handler(int signum) {
    running = 0;
}

int main() {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Failed to initialize pigpio\n");
        return EXIT_FAILURE;
    }

    if (signal(SIGINT, sig_handler) == SIG_ERR || signal(SIGTERM, sig_handler) == SIG_ERR) {
        fprintf(stderr, "Failed to set signal handler\n");
        gpioTerminate();
        return EXIT_FAILURE;
    }

    int i2c_handle = gpioI2COpen(I2C_BUS, I2C_ADDRESS, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Failed to open I2C bus\n");
        gpioTerminate();
        return EXIT_FAILURE;
    }

    uint8_t id_reg_data[1] = {ID_REG};
    uint8_t id_value[1];
    if (gpioI2CReadDevice(i2c_handle, id_reg_data, 1, id_value, 1) != 1) {
        fprintf(stderr, "Failed to read ID register\n");
        gpioI2CWriteByte(i2c_handle, ENABLE_REG, 0);
        gpioI2CClose(i2c_handle);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    if ((id_value[0] & 0x0F) != ID_VALUE) {
        fprintf(stderr, "Invalid ID value\n");
        gpioI2CWriteByte(i2c_handle, ENABLE_REG, 0);
        gpioI2CClose(i2c_handle);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    uint8_t atime_reg_data[2] = {ATIME_REG, INTEGRATION_TIME_2_4MS};
    if (gpioI2CWriteDevice(i2c_handle, atime_reg_data, 2) != 2) {
        fprintf(stderr, "Failed to write ATIME register\n");
        gpioI2CWriteByte(i2c_handle, ENABLE_REG, 0);
        gpioI2CClose(i2c_handle);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    uint8_t control_reg_data[2] = {CONTROL_REG, GAIN_4X};
    if (gpioI2CWriteDevice(i2c_handle, control_reg_data, 2) != 2) {
        fprintf(stderr, "Failed to write CONTROL register\n");
        gpioI2CWriteByte(i2c_handle, ENABLE_REG, 0);
        gpioI2CClose(i2c_handle);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    uint8_t enable_reg_data[2] = {ENABLE_REG, ENABLE_PON | ENABLE_AEN};
    if (gpioI2CWriteDevice(i2c_handle, enable_reg_data, 2) != 2) {
        fprintf(stderr, "Failed to write ENABLE register\n");
        gpioI2CWriteByte(i2c_handle, ENABLE_REG, 0);
        gpioI2CClose(i2c_handle);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    FILE *log_file = fopen(COLOR_LOG_FILE, "a");
    if (log_file == NULL) {
        fprintf(stderr, "Failed to open color log file\n");
        gpioI2CWriteByte(i2c_handle, ENABLE_REG, 0);
        gpioI2CClose(i2c_handle);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    if (ftell(log_file) == 0) {
        if (fputs(COLOR_LOG_HEADER, log_file) == EOF) {
            fprintf(stderr, "Failed to write color log header\n");
            fclose(log_file);
            gpioI2CWriteByte(i2c_handle, ENABLE_REG, 0);
            gpioI2CClose(i2c_handle);
            gpioTerminate();
            return EXIT_FAILURE;
        }
    }

    time_t rawtime;
    struct tm *timeinfo;
    char buffer[20];
    uint16_t clear, red, green, blue;

    while (running) {
        time(&rawtime);
        timeinfo = localtime(&rawtime);
        strftime(buffer, sizeof(buffer), "%Y-%m-%d %H:%M:%S", timeinfo);

        uint8_t clear_reg_data[1] = {CLEAR_REG};
        if (gpioI2CReadDevice(i2c_handle, clear_reg_data, 1, (uint8_t *)&clear, 2) != 2) {
            fprintf(stderr, "Failed to read CLEAR register\n");
            continue;
        }

        uint8_t red_reg_data[1] = {RED_REG};
        if (gpioI2CReadDevice(i2c_handle, red_reg_data, 1, (uint8_t *)&red, 2) != 2) {
            fprintf(stderr, "Failed to read RED register\n");
            continue;
        }

        uint8_t green_reg_data[1] = {GREEN_REG};
        if (gpioI2CReadDevice(i2c_handle, green_reg_data, 1, (uint8_t *)&green, 2) != 2) {
            fprintf(stderr, "Failed to read GREEN register\n");
            continue;
        }

        uint8_t blue_reg_data[1] = {BLUE_REG};
        if (gpioI2CReadDevice(i2c_handle, blue_reg_data, 1, (uint8_t *)&blue, 2) != 2) {
            fprintf(stderr, "Failed to read BLUE register\n");
            continue;
        }

        if (fprintf(log_file, COLOR_LOG_FORMAT, buffer, clear, red, green, blue) < 0) {
            fprintf(stderr, "Failed to write color log entry\n");
            fclose(log_file);
            gpioI2CWriteByte(i2c_handle, ENABLE_REG, 0);
            gpioI2CClose(i2c_handle);
            gpioTerminate();
            return EXIT_FAILURE;
        }

        fflush(log_file);
    }

    fclose(log_file);
    gpioI2CWriteByte(i2c_handle, ENABLE_REG, 0);
    gpioI2CClose(i2c_handle);
    gpioTerminate();
    return EXIT_SUCCESS;
}

#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <stdbool.h>
#include <string.h>
#include <unistd.h>
#include <fcntl.h>
#include <signal.h>
#include <sys/ioctl.h>
#include <linux/spi/spidev.h>
#include <gpiod.h>

#define SPI_CHANNEL 0
#define SPI_SPEED 500000
#define MCP3008_CS 8
#define SAMPLE_INTERVAL 5

static int spi_fd;
static struct gpiod_line *cs_line;

void cleanup() {
    gpiod_line_set_value(cs_line, 1);
    close(spi_fd);
    gpiod_line_release(cs_line);
}

void handle_sigint(int signum) {
    cleanup();
    exit(0);
}

uint16_t read_adc(int channel) {
    uint8_t tx[3] = {1, 0x04 | (channel & 0x07), 0};
    uint8_t rx[3];

    gpiod_line_set_value(cs_line, 0);
    write(spi_fd, tx, sizeof(tx));
    read(spi_fd, rx, sizeof(rx));
    gpiod_line_set_value(cs_line, 1);

    return ((rx[1] << 8) | rx[2]) & 0x03FF;
}

float map_value(uint16_t value, uint16_t in_min, uint16_t in_max, float out_min, float out_max) {
    return (value - in_min) * (out_max - out_min) / (in_max - in_min) + out_min;
}

int main() {
    struct spi_ioc_transfer tr = {
        .tx_buf = 0,
        .rx_buf = 0,
        .len = 3,
        .speed_hz = SPI_SPEED,
        .cs_change = 1,
    };

    signal(SIGINT, handle_sigint);
    signal(SIGTERM, handle_sigint);

    spi_fd = open("/dev/spidev0.0", O_RDWR);
    if (spi_fd < 0) {
        perror("Failed to open SPI device");
        return -1;
    }

    cs_line = gpiod_line_request_output("MCP3008", MCP3008_CS, 1);
    if (!cs_line) {
        perror("Failed to request GPIO line");
        return -1;
    }

    FILE *log_file = fopen("moisture_log.csv", "w");
    if (!log_file) {
        perror("Failed to open log file");
        return -1;
    }

    fprintf(log_file, "Timestamp,Moisture1,Moisture2\n");

    while (true) {
        uint16_t value1 = read_adc(0);
        uint16_t value2 = read_adc(1);

        float moisture1 = map_value(value1, 0, 1023, 0, 100);
        float moisture2 = map_value(value2, 0, 1023, 0, 100);

        time_t now = time(NULL);
        struct tm *t = localtime(&now);

        fprintf(log_file, "%d-%02d-%02d %02d:%02d:%02d,%f,%f\n",
                t->tm_year + 1900, t->tm_mon + 1, t->tm_mday,
                t->tm_hour, t->tm_min, t->tm_sec, moisture1, moisture2);

        fflush(log_file);
        sleep(SAMPLE_INTERVAL);
    }

    fclose(log_file);
    cleanup();
    return 0;
}

#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
