#include <linux/spi/spidev.h>
#include <gpiod.h>

#define SPI_CHANNEL 0
#define SPI_SPEED 500000
#define ADC_CHANNEL 0
#define CURRENT_THRESHOLD 10000
#define MOTOR_SHUTDOWN_PIN 17
#define LOG_FILE "current_log.csv"

int spi_fd, adc_fd;
struct gpiod_chip *chip;
struct gpiod_line_request request;
struct gpiod_line *line;

void cleanup() {
    gpiod_line_release(line);
    gpiod_chip_close(chip);
    close(spi_fd);
    close(adc_fd);
}

int main() {
    atexit(cleanup);

    // Open SPI and ADC devices
    spi_fd = open("/dev/spidev0.0", O_RDWR);
    adc_fd = open("/dev/spidev0.1", O_RDWR);
    if (spi_fd < 0 || adc_fd < 0) {
        perror("Failed to open SPI/ADC devices");
        return EXIT_FAILURE;
    }

    // Configure SPI and ADC
    // ...

    // Open GPIO chip and request lines
    chip = gpiod_chip_open("/dev/gpiochip0");
    if (!chip) {
        perror("Failed to open GPIO chip");
        return EXIT_FAILURE;
    }

    line = gpiod_chip_get_line(chip, MOTOR_SHUTDOWN_PIN);
    if (!line) {
        perror("Failed to get GPIO line");
        return EXIT_FAILURE;
    }

    request.consumer = "current_sensor";
    request.request_type = GPIO_LINE_REQUEST_OUTPUT;
    if (gpiod_line_request(line, &request)) {
        perror("Failed to request GPIO line");
        return EXIT_FAILURE;
    }

    // Open log file
    FILE *log_file = fopen(LOG_FILE, "a");
    if (!log_file) {
        perror("Failed to open log file");
        return EXIT_FAILURE;
    }

    // Log header
    fprintf(log_file, "timestamp,current_in_Amperes\n");

    // Main loop
    while (true) {
        // Read ADC value
        uint16_t adc_value;
        // ...

        // Convert ADC value to voltage and current
        float voltage = adc_value * 3.3 / 1024;
        float current = (voltage - 0.05) / 0.1;

        // Check if current exceeds threshold
        if (current > CURRENT_THRESHOLD) {
            // Disable motor
            gpiod_line_set_value(line, 0);

            // Log event
            fprintf(log_file, "%ld,%f\n", time(NULL), current);

            // Wait for 1 second
            sleep(1);

            // Re-enable motor
            gpiod_line_set_value(line, 1);
        }

        // Log current reading
        fprintf(log_file, "%ld,%f\n", time(NULL), current);

        // Wait for 1 second
        sleep(1);
    }

    fclose(log_file);
    return EXIT_SUCCESS;
}

