#define LOG_FILE_NAME "pressure_log.csv"
#define HEADER_ROW "timestamp,pressure_kPa\n"

static FILE *log_file;
static int i2c_handle;
static volatile sig_atomic_t stop_requested = 0;

void signal_handler(int signum) {
    stop_requested = 1;
}

int main() {
    struct timespec sleep_time = {1, 0}; // 1 second
    uint16_t raw_value;
    float pressure_kPa;
    char timestamp[26];
    time_t now;
    struct tm *gmtm_now;
    int read_failures = 0;

    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    log_file = fopen(LOG_FILE_NAME, "w");
    if (!log_file) {
        fprintf(stderr, "Failed to open log file: %s\n", LOG_FILE_NAME);
        return EXIT_FAILURE;
    }
    fprintf(log_file, HEADER_ROW);

    i2c_handle = piI2COpen(1, SENSOR_ADDRESS);
    if (i2c_handle < 0) {
        fprintf(stderr, "Failed to open I2C bus: %d\n", i2c_handle);
        fclose(log_file);
        return EXIT_FAILURE;
    }

    while (!stop_requested) {
        if (piI2CReadReg16(i2c_handle, PRESSURE_REGISTER, &raw_value) < 0) {
            fprintf(stderr, "Failed to read from register 0x%02X: %d\n", PRESSURE_REGISTER, piI2CError(i2c_handle));
            read_failures++;
            if (read_failures > 5) {
                fprintf(stderr, "Too many read failures, exiting...\n");
                break;
            }
            continue;
        }
        read_failures = 0;

        pressure_kPa = (raw_value / 65535.0) * 500.0;

        now = time(NULL);
        gmtm_now = gmtime(&now);
        strftime(timestamp, sizeof(timestamp), "%Y-%m-%dT%H:%M:%SZ", gmtm_now);

        fprintf(log_file, "%s,%.2f\n", timestamp, pressure_kPa);
        fflush(log_file);

        nanosleep(&sleep_time, NULL);
    }

    piI2CClose(i2c_handle);
    fclose(log_file);
    gpioTerminate();

    return EXIT_SUCCESS;
}

#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <pigpio.h>

#define MLX91209_VCC 3.3
#define MLX91209_ZERO_CURRENT_MIDPOINT (MLX91209_VCC / 2)
#define MLX91209_SENSITIVITY 0.066 // mV/A
#define ADC_MAX 1024
#define SAMPLE_INTERVAL 100 // ms
#define OVERCURRENT_THRESHOLD 10 // A

int main() {
    FILE *log_file;
    int spi_handle, adc_value, gpio_handle;
    float current;
    struct timespec sleep_time = {0, SAMPLE_INTERVAL * 1000000};

    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Failed to initialize pigpio\n");
        return EXIT_FAILURE;
    }

    // Open SPI handle
    spi_handle = spiOpen(0, 1000000, 0);
    if (spi_handle < 0) {
        fprintf(stderr, "Failed to open SPI handle\n");
        gpioTerminate();
        return EXIT_FAILURE;
    }

    // Open log file
    log_file = fopen("current_log.txt", "a");
    if (!log_file) {
        fprintf(stderr, "Failed to open log file\n");
        spiClose(spi_handle);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    // Set up GPIO27 for motor shutdown
    gpio_handle = gpioOpen(27, 0);
    if (gpio_handle < 0) {
        fprintf(stderr, "Failed to open GPIO27\n");
        fclose(log_file);
        spiClose(spi_handle);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    while (1) {
        // Send start bit and single-ended channel configuration byte
        uint8_t tx_buffer[3] = {0x01, 0x00, 0x00};
        uint8_t rx_buffer[3];
        spiXfer(spi_handle, tx_buffer, rx_buffer, 3);

        // Extract 10-bit ADC value from response
        adc_value = (rx_buffer[1] << 8) | rx_buffer[2];
        if (adc_value < 0 || adc_value > ADC_MAX) {
            fprintf(stderr, "Invalid ADC value: %d\n", adc_value);
            continue;
        }

        // Convert ADC value to voltage and current
        float voltage = adc_value * MLX91209_VCC / ADC_MAX;
        current = (voltage - MLX91209_ZERO_CURRENT_MIDPOINT) / MLX91209_SENSITIVITY;

        // Log current with timestamp
        time_t now = time(NULL);
        char timestamp[26];
        ctime_r(&now, timestamp);
        timestamp[strcspn(timestamp, "\n")] = 0;
        fprintf(log_file, "%s, %.2fA\n", timestamp, current);
        fflush(log_file);

        // Check for overcurrent
        if (current > OVERCURRENT_THRESHOLD) {
            gpioWrite(27, 1);
            fprintf(log_file, "%s, OVERCURRENT\n", timestamp);
            fclose(log_file);
            spiClose(spi_handle);
            gpioTerminate();
            return EXIT_SUCCESS;
        }

        // Sleep for SAMPLE_INTERVAL ms
        nanosleep(&sleep_time, NULL);
    }

    // Cleanup on exit
    fclose(log_file);
    spiClose(spi_handle);
    gpioWrite(27, 0);
    gpioTerminate();
    return EXIT_SUCCESS;
}

