#define SPI_BITS 8
#define SPI_CS 8
#define SPI_DIN 10
#define SPI_DOUT 9
#define SPI_CLK 11

#define ADC_CHANNEL 0
#define ADC_MAX 1023
#define PPM_MIN 0
#define PPM_MAX 5000
#define PPM_ALARM 1000

volatile sig_atomic_t running = 1;

void sig_handler(int signum) {
    running = 0;
}

int main() {
    FILE *log_file;
    struct tm *timeinfo;
    time_t rawtime;
    char buffer[80];
    uint8_t tx[3] = {0x01, 0x80, 0x00};
    uint8_t rx[3];
    int adc_value, ppm_value;
    int spi_handle, gpio_handle;

    if ((gpio_handle = gpioInitialise()) < 0) {
        fprintf(stderr, "Failed to initialize pigpio: %d\n", gpio_handle);
        return EXIT_FAILURE;
    }

    if ((spi_handle = spiOpen(SPI_CHANNEL, SPI_SPEED, SPI_MODE, SPI_BITS)) < 0) {
        fprintf(stderr, "Failed to open SPI channel: %d\n", spi_handle);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    if ((log_file = fopen("methane_log.txt", "a")) == NULL) {
        fprintf(stderr, "Failed to open log file\n");
        spiClose(spi_handle);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    signal(SIGINT, sig_handler);
    signal(SIGTERM, sig_handler);

    while (running) {
        if (spiXfer(spi_handle, tx, rx, 3) != 3) {
            fprintf(stderr, "Failed to read from SPI channel\n");
            continue;
        }

        adc_value = ((rx[1] & 0x03) << 8) | rx[2];
        ppm_value = (adc_value * (PPM_MAX - PPM_MIN)) / ADC_MAX + PPM_MIN;

        time(&rawtime);
        timeinfo = localtime_r(&rawtime, buffer);
        strftime(buffer, sizeof(buffer), "%Y-%m-%dT%H:%M:%S%z", timeinfo);
        fprintf(log_file, "%s %d\n", buffer, ppm_value);

        if (ppm_value > PPM_ALARM) {
            fprintf(stderr, "Methane concentration exceeds alarm threshold: %d PPM\n", ppm_value);
        }
    }

    fclose(log_file);
    spiClose(spi_handle);
    gpioTerminate();

    return EXIT_SUCCESS;
}

