#define PRESSURE_SENSOR_ADDRESS 0x48
#define PRESSURE_SENSOR_CHANNEL 0
#define PRESSURE_SENSOR_OFFSET_VOLTAGE 0.5
#define PRESSURE_SENSOR_SENSITIVITY 0.1
#define PRESSURE_MIN 0
#define PRESSURE_MAX 100
#define LOG_FILE "pressure_log.txt"

volatile sig_atomic_t stop = 0;

void signal_handler(int signum) {
    stop = 1;
}

int main() {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Failed to initialize pigpio library\n");
        return EXIT_FAILURE;
    }

    if (gpioSetSignalFunc(SIGINT, signal_handler) < 0) {
        fprintf(stderr, "Failed to set signal handler\n");
        gpioTerminate();
        return EXIT_FAILURE;
    }

    if (i2cOpen(PRESSURE_SENSOR_ADDRESS, 1) < 0) {
        fprintf(stderr, "Failed to open I2C bus\n");
        gpioTerminate();
        return EXIT_FAILURE;
    }

    FILE *log_file = fopen(LOG_FILE, "w");
    if (log_file == NULL) {
        fprintf(stderr, "Failed to open log file\n");
        gpioTerminate();
        return EXIT_FAILURE;
    }

    while (!stop) {
        uint16_t raw_value;
        float voltage, pressure;

        if (i2cReadDevice(PRESSURE_SENSOR_ADDRESS, &raw_value, sizeof(raw_value)) < 0) {
            fprintf(stderr, "Failed to read from sensor\n");
            break;
        }

        voltage = raw_value * 3.3 / 65536;
        pressure = (voltage - PRESSURE_SENSOR_OFFSET_VOLTAGE) / PRESSURE_SENSOR_SENSITIVITY;

        if (pressure >= PRESSURE_MIN && pressure <= PRESSURE_MAX) {
            time_t now = time(NULL);
            struct tm *time_info = localtime(&now);
            char timestamp[20];
            strftime(timestamp, sizeof(timestamp), "%Y-%m-%dT%H:%M:%S", time_info);

            fprintf(log_file, "%s Pressure: %.2f kPa\n", timestamp, pressure);
            fflush(log_file);
        } else {
            fprintf(stderr, "Invalid pressure reading: %.2f kPa\n", pressure);
        }

        sleep(1);
    }

    fclose(log_file);
    i2cClose(PRESSURE_SENSOR_ADDRESS);
    gpioTerminate();

    return EXIT_SUCCESS;
}

