#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <stdbool.h>
#include <string.h>
#include <unistd.h>
#include <fcntl.h>
#include <time.h>
#include <signal.h>
#include <libgpiod.h>
#include <sys/ioctl.h>
#include <linux/spi/spidev.h>

#define SPI_DEVICE "/dev/spidev0.0"
#define GPIO_CHIP 4
#define GPIO_CS 8
#define ADC_CHANNEL 0
#define VREF 3.3
#define TMP36_MIN_VOLTAGE 0.0
#define TMP36_MAX_VOLTAGE 0.85
#define TMP36_MIN_TEMP -40
#define TMP36_MAX_TEMP 125
#define LOG_FILE "temperature_log.csv"
#define LOG_INTERVAL 1

static gpiod_chip *chip;
static gpiod_line *cs_line;
static int spi_fd;
static FILE *log_file;

void cleanup() {
    if (log_file) fclose(log_file);
    if (cs_line) gpiod_line_release(cs_line);
    if (chip) gpiod_chip_close(chip);
    if (spi_fd >= 0) close(spi_fd);
}

void handle_signal(int signum) {
    cleanup();
    exit(signum);
}

uint16_t read_adc() {
    uint8_t tx[3] = {1, (ADC_CHANNEL << 4), 0};
    uint8_t rx[3];
    struct spi_ioc_transfer tr = {
        .tx_buf = (unsigned long)tx,
        .rx_buf = (unsigned long)rx,
        .len = sizeof(tx),
        .speed_hz = 1000000,
        .bits_per_word = 8,
        .cs_change = 1,
    };
    if (ioctl(spi_fd, SPI_IOC_MESSAGE(1), &tr) < 0) {
        perror("SPI transfer failed");
        exit(EXIT_FAILURE);
    }
    return (rx[1] << 8) | rx[2];
}

float convert_to_voltage(uint16_t adc_value) {
    return (float)adc_value / 4095 * VREF;
}

float convert_to_celsius(float voltage) {
    return (voltage - 0.5) / 0.01;
}

void log_temperature(float temperature) {
    time_t now = time(NULL);
    struct tm *t = localtime(&now);
    fprintf(log_file, "%04d-%02d-%02d %02d:%02d:%02d,%f\n",
            t->tm_year + 1900, t->tm_mon + 1, t->tm_mday,
            t->tm_hour, t->tm_min, t->tm_sec, temperature);
    fflush(log_file);
}

int main() {
    atexit(cleanup);
    signal(SIGINT, handle_signal);
