    if (!log_file) {
        printf("Failed to open log file\n");
        cleanup();
        return -1;
    }

    while (1) {
        uint8_t tx[3] = {0x01, 0x00, 0x00};
        uint8_t rx[3];

        gpioSetMode(SPI_CS, PI_OUTPUT);
        gpioWrite(SPI_CS, PI_LOW);

        spiXfer(spi_fd, tx, rx, 3);

        gpioWrite(SPI_CS, PI_HIGH);

        int16_t x = (rx[1] << 8) | rx[2];
        int16_t y = (rx[1] << 8) | rx[2];
        int16_t z = (rx[1] << 8) | rx[2];

        float g = sqrt(x*x + y*y + z*z) / 1000.0;

        time_t now = time(NULL);
        struct tm *t = localtime(&now);

        fprintf(log_file, "%d-%02d-%02d %02d:%02d:%02d, %d, %d, %d, %.2f\n",
                t->tm_year + 1900, t->tm_mon + 1, t->tm_mday,
                t->tm_hour, t->tm_min, t->tm_sec,
                x, y, z, g);

        if (g > ACCEL_MAX_G) {
            fprintf(log_file, "IMPACT DETECTED\n");
        }

        fflush(log_file);
        usleep(1000000 / 100); // 100 Hz
    }

    cleanup();
    return 0;
}

