#define SI1172_ADDRESS 0x49
#define SI1172_CMD_REG 0xC0
#define SI1172_FIFO_REG 0xC1
#define SI1172_DATA_REG 0xC4

volatile sig_atomic_t stop = 0;

void signal_handler(int signum) {
    stop = 1;
}

int main() {
    FILE *log_file;
    int i2c_handle;
    uint8_t buffer[2];
    uint16_t raw_ir, raw_red;
    time_t current_time;
    struct tm *time_info;
    char timestamp[20];

    if ((i2c_handle = i2cOpen(1, SI1172_ADDRESS, 0)) < 0) {
        printf("Failed to open I2C bus 1.\n");
        return EXIT_FAILURE;
    }

    if ((log_file = fopen("biometric_log.csv", "w")) == NULL) {
        printf("Failed to open log file.\n");
        i2cClose(i2c_handle);
        return EXIT_FAILURE;
    }

    fprintf(log_file, "Timestamp,HR,SpO2,Error\n");

    signal(SIGINT, signal_handler);

    while (!stop) {
        // Trigger measurement
        buffer[0] = SI1172_CMD_REG;
        buffer[1] = 0x01;
        if (i2cWriteByteData(i2c_handle, buffer[0], buffer[1]) < 0) {
            fprintf(log_file, "%s,0,0,1\n", "Error writing command register");
            continue;
        }

        // Read raw IR and RED values
        buffer[0] = SI1172_FIFO_REG;
        if (i2cReadByteData(i2c_handle, buffer[0], buffer, 2) < 0) {
            fprintf(log_file, "%s,0,0,1\n", "Error reading FIFO register");
            continue;
        }

        raw_ir = (buffer[0] << 8) | buffer[1];
        buffer[0] = SI1172_DATA_REG;
        if (i2cReadByteData(i2c_handle, buffer[0], buffer, 2) < 0) {
            fprintf(log_file, "%s,0,0,1\n", "Error reading data register");
            continue;
        }

        raw_red = (buffer[0] << 8) | buffer[1];

        // Log timestamp, raw IR and RED values, and error flag
        current_time = time(NULL);
        time_info = localtime(&current_time);
        strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", time_info);
        fprintf(log_file, "%s,%d,%d,0\n", timestamp, raw_ir, raw_red);

        fflush(log_file);
        sleep(1);
    }

    fclose(log_file);
    i2cClose(i2c_handle);
    pigpioTerminate();
    return EXIT_SUCCESS;
}

