#define SPI_CHANNEL 0
#define SPI_SPEED 1000000
#define ADC_CHANNEL 0
#define FLOW_MIN 0.0
#define FLOW_MAX 5.0

FILE *log_file;
bool running = true;

void signal_handler(int signum) {
    if (signum == SIGINT || signum == SIGTERM) {
        running = false;
    }
}

void error_exit(const char *msg) {
    fprintf(stderr, "%s: %s\n", msg, strerror(errno));
    exit(EXIT_FAILURE);
}

void write_log(const char *timestamp, float flow_rate) {
    fprintf(log_file, "%s,%.2f\n", timestamp, flow_rate);
    fflush(log_file);
}

int main() {
    struct timespec ts;
    char timestamp[32];
    float flow_rate;
    uint32_t adc_value;
    int spi_fd;

    if (clock_gettime(CLOCK_REALTIME, &ts) == -1) {
        error_exit("Failed to get time");
    }

    if (strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", gmtime(&ts.tv_sec)) == 0) {
        error_exit("Failed to format timestamp");
    }

    sprintf(timestamp + strlen(timestamp), ".%06ld", ts.tv_nsec / 1000);

    if ((log_file = fopen("flow_log.csv", "a")) == NULL) {
        error_exit("Failed to open log file");
    }

    if (signal(SIGINT, signal_handler) == SIG_ERR || signal(SIGTERM, signal_handler) == SIG_ERR) {
        error_exit("Failed to set signal handler");
    }

    if ((spi_fd = spiOpen(SPI_CHANNEL, SPI_SPEED, 0)) < 0) {
        error_exit("Failed to open SPI");
    }

    if (gpioInitialise() < 0) {
        error_exit("Failed to initialize pigpio");
    }

    while (running) {
        if ((adc_value = spiTransfer(spi_fd, ADC_CHANNEL << 8)) == 0 || adc_value == 0x7fff) {
            fprintf(stderr, "Sensor error: ADC value is 0x%X\n", adc_value);
            continue;
        }

        flow_rate = (float)adc_value / 1024.0 * (FLOW_MAX - FLOW_MIN) + FLOW_MIN;

        if (flow_rate < FLOW_MIN || flow_rate > FLOW_MAX) {
            fprintf(stderr, "Flow rate out of range: %.2f L/min\n", flow_rate);
            continue;
        }

        write_log(timestamp, flow_rate);

        if (clock_gettime(CLOCK_REALTIME, &ts) == -1) {
            error_exit("Failed to get time");
        }

        if (strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", gmtime(&ts.tv_sec)) == 0) {
            error_exit("Failed to format timestamp");
        }

        sprintf(timestamp + strlen(timestamp), ".%06ld", ts.tv_nsec / 1000);
    }

    gpioTerminate();
    spiClose(spi_fd);
    fclose(log_file);

    return EXIT_SUCCESS;
}

