        printf("Failed to open SPI channel\n");
        gpioTerminate();
        return 1;
    }

    int mic1 = spiOpen(SPI_CHANNEL, SPI_SPEED, 0);
    if (mic1 < 0) {
        printf("Failed to open SPI channel for microphone 1\n");
        spiClose(spi);
        gpioTerminate();
        return 1;
    }

    int mic2 = spiOpen(SPI_CHANNEL, SPI_SPEED, 0);
