#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <pigpio.h>
#include <errno.h>

#define SPI_CHANNEL 0
#define SPI_SPEED 500000
#define ADC_CHANNEL 0
#define LOG_FILE "moisture_log.txt"
#define SAMPLE_INTERVAL 60

volatile sig_atomic_t running = 1;

void signal_handler(int signum) {
    running = 0;
}

int main() {
    FILE *log_file;
    uint8_t tx_buffer[3] = {1, 0x40 | (ADC_CHANNEL << 4), 0};
    uint8_t rx_buffer[3];
    int spi_handle;
    int adc_value;
    struct timespec sleep_time = {SAMPLE_INTERVAL, 0};

    if (signal(SIGINT, signal_handler) == SIG_ERR || signal(SIGTERM, signal_handler) == SIG_ERR) {
        fprintf(stderr, "Failed to set signal handlers: %s\n", strerror(errno));
        return EXIT_FAILURE;
    }

    if ((spi_handle = spiOpen(0, SPI_CHANNEL, SPI_SPEED)) < 0) {
        fprintf(stderr, "Failed to open SPI device: %s\n", strerror(errno));
        return EXIT_FAILURE;
    }

    if ((log_file = fopen(LOG_FILE, "a")) == NULL) {
        fprintf(stderr, "Failed to open log file: %s\n", strerror(errno));
        spiClose(spi_handle);
        return EXIT_FAILURE;
    }

    while (running) {
        clock_nanosleep(CLOCK_MONOTONIC, 0, &sleep_time, NULL);

        tx_buffer[1] = 0x40 | (ADC_CHANNEL << 4);
        if (spiXfer(spi_handle, tx_buffer, rx_buffer, sizeof(tx_buffer)) != sizeof(tx_buffer)) {
            fprintf(stderr, "Failed to read from ADC: %s\n", strerror(errno));
            break;
        }

        adc_value = ((rx_buffer[1] & 0x0F) << 8) | rx_buffer[2];
        if (adc_value < 0 || adc_value > 1023) {
            fprintf(stderr, "Invalid ADC value: %d\n", adc_value);
            break;
        }

        time_t now = time(NULL);
        struct tm *utc_time = gmtime(&now);
        if (utc_time == NULL) {
            fprintf(stderr, "Failed to get UTC time: %s\n", strerror(errno));
            break;
        }

        if (fprintf(log_file, "%04d-%02d-%02dT%02d:%02d:%02dZ,%d\n",
                    utc_time->tm_year + 1900, utc_time->tm_mon + 1, utc_time->tm_mday,
                    utc_time->tm_hour, utc_time->tm_min, utc_time->tm_sec,
                    adc_value) < 0) {
            fprintf(stderr, "Failed to write to log file: %s\n", strerror(errno));
            break;
        }

        fflush(log_file);
    }

    fclose(log_file);
    spiClose(spi_handle);
    gpioTerminate();

    return EXIT_SUCCESS;
}

#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <unistd.h>
#include <fcntl.h>
#include <time.h>
#include <signal.h>
#include <libgpiod.h>
#include <sys/ioctl.h>
#include <linux/spi/spidev.h>

#define SPI_CHANNEL 0
#define SPI_SPEED 1000000
#define SPI_MODE 0
#define SPI_BITS 8
#define SPI_DELAY 0
#define SPI_CS 0

#define Buzzer_PIN 18
#define ADC_CHANNEL 0

FILE *log_file;
int spi_fd, buzzer_fd;
float temperature = 25.0;

void cleanup() {
    gpiod_set_value(buzzer_fd, 0);
    fclose(log_file);
    gpiod_ctxless_close();
}

void sigint_handler(int signum) {
    cleanup();
    exit(0);
}

int main() {
    struct sigaction action;
    memset(&action, 0, sizeof(action));
    action.sa_handler = sigint_handler;
    sigaction(SIGINT, &action, NULL);

    gpiod_chip *chip = gpiod_chip_open("/dev/gpiochip0");
    buzzer_fd = gpiod_chip_get_line(chip, Buzzer_PIN)->fd;
    gpiod_line_request_output(gpiod_chip_get_line(chip, Buzzer_PIN), "buzzer", 0);

    spi_fd = open("/dev/spidev0.0", O_RDWR);
    if (spi_fd < 0) {
        perror("Failed to open SPI device");
        return 1;
    }

    struct spi_ioc_transfer spi[1];
    memset(spi, 0, sizeof(spi));
    spi[0].tx_buf = (unsigned long)&spi_tx;
    spi[0].rx_buf = (unsigned long)&spi_rx;
    spi[0].len = 3;
    spi[0].speed_hz = SPI_SPEED;
    spi[0].delay_usecs = SPI_DELAY;
    spi[0].bits_per_word = SPI_BITS;
    spi[0].cs_change = 0;

    int ret = ioctl(spi_fd, SPI_IOC_MESSAGE(1), spi);
    if (ret < 0) {
        perror("SPI transfer failed");
        return 1;
    }

    log_file = fopen("flame_log.txt", "w");
    if (!log_file) {
        perror("Failed to open log file");
        return 1;
    }

    while (1) {
        // Read temperature from file
        FILE *temp_file = fopen("ambient_temp.txt", "r");
        if (temp_file) {
            fscanf(temp_file, "%f", &temperature);
            fclose(temp_file);
        }

        // Read ADC value
        uint16_t adc_value = spi_rx[1] << 8 | spi_rx[2];
        if (adc_value < 0 || adc_value > 1023) {
            fprintf(stderr, "Invalid ADC value: %d\n", adc_value);
            continue;
        }

        // Compute voltage and compensated voltage
        float voltage = adc_value / 1023.0;
        float compensated_voltage = voltage + (temperature - 25.0) * 0.001;

        // Log the reading
        time_t now = time(NULL);
        struct tm *t = localtime(&now);
        fprintf(log_file, "%d-%02d-%02d %02d:%02d:%02d,%d,%.3f,%.3f,%.1f,%d\n",
                t->tm_year + 1900, t->tm_mon + 1, t->tm_mday,
                t->tm_hour, t->tm_min, t->tm_sec,
                adc_value, voltage, compensated_voltage, temperature,
                compensated_voltage > 1.0);

        // Check for flame
        int flame_detected = compensated_voltage > 1.0;
        gpiod_set_value(buzzer_fd, flame_detected);

        // Wait for next sample
        usleep(500000);
    }

    cleanup();
    return 0;
}

#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <pigpio.h>
#include <cJSON.h>

#define SPI_CHANNEL 0
#define SPI_SPEED 1000000
#define SPI_MODE 0
#define SPI_FLAGS 0
#define ADC_CHANNEL 0
#define LED_PIN 17
#define WATER_LEVEL_HIGH 75
#define WATER_LEVEL_LOW 70
#define JSON_FILE "water_levels.json"
#define READ_INTERVAL 5

int main(int argc, char *argv[]) {
    int spi_handle, led_handle;
    uint8_t tx[3] = {0x01, 0x80 | ADC_CHANNEL << 4, 0x00};
    uint8_t rx[3];
    float water_level;
    cJSON *root, *entry;
    time_t now;
    struct tm *timeinfo;
    char buffer[20];
    int running = 1;

    if ((spi_handle = spiOpen(SPI_CHANNEL, SPI_SPEED, SPI_MODE, SPI_FLAGS)) < 0) {
        fprintf(stderr, "Failed to open SPI channel: %s\n", gpioErrStr(spi_handle));
        return EXIT_FAILURE;
    }

    if ((led_handle = gpioOpen(LED_PIN, PI_OUTPUT)) < 0) {
        fprintf(stderr, "Failed to open LED pin: %s\n", gpioErrStr(led_handle));
        return EXIT_FAILURE;
    }

    gpioWrite(led_handle, PI_OFF);

    root = cJSON_CreateArray();
    if (!root) {
        fprintf(stderr, "Failed to create JSON array\n");
        return EXIT_FAILURE;
    }

    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    while (running) {
        if (spiXfer(spi_handle, tx, rx, 3) < 0) {
            fprintf(stderr, "SPI transfer error: %s\n", gpioErrStr(spiXfer(spi_handle, tx, rx, 3)));
            continue;
        }

        water_level = ((rx[1] & 0x03) << 8) | rx[2];
        water_level = (water_level / 1023) * 100;

        entry = cJSON_CreateObject();
        if (!entry) {
            fprintf(stderr, "Failed to create JSON object\n");
            continue;
        }

        time(&now);
        timeinfo = localtime(&now);
        strftime(buffer, sizeof(buffer), "%Y-%m-%dT%H:%M:%S", timeinfo);
        cJSON_AddStringToObject(entry, "timestamp", buffer);
        cJSON_AddNumberToObject(entry, "water_level", water_level);
        cJSON_AddItemToArray(root, entry);

        if (water_level > WATER_LEVEL_HIGH) {
            gpioWrite(led_handle, PI_ON);
        } else if (water_level < WATER_LEVEL_LOW) {
            gpioWrite(led_handle, PI_OFF);
        }

        sleep(READ_INTERVAL);
    }

    gpioTerminate();
    spiClose(spi_handle);
    cJSON_Delete(root);
    return EXIT_SUCCESS;
}

void signal_handler(int signum) {
    running = 0;
}

#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <unistd.h>
#include <signal.h>
#include <pigpio.h>
#include <errno.h>

#define SPI_CHANNEL 0
#define SPI_SPEED 500000
#define MCP3008_CHANNEL 0
#define AWM7300V_LSB 0.0025 // 2.5mV per LPM
#define CSV_FILENAME "airflow_log.csv"
#define SAMPLE_INTERVAL_MS 100

volatile sig_atomic_t running = 1;

void signal_handler(int signum) {
    running = 0;
}

int main() {
    FILE *file;
    int spi_handle, adc_value;
    float flow_rate;
    char timestamp[26];
    struct timespec sleep_time = {0, SAMPLE_INTERVAL_MS * 1000000};

    if (gpioInitialise() < 0) {
        fprintf(stderr, "Failed to initialize pigpio: %s\n", strerror(errno));
        return EXIT_FAILURE;
    }

    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    spi_handle = spiOpen(SPI_CHANNEL, SPI_SPEED, 0);
    if (spi_handle < 0) {
        fprintf(stderr, "Failed to open SPI channel: %s\n", strerror(errno));
        gpioTerminate();
        return EXIT_FAILURE;
    }

    file = fopen(CSV_FILENAME, "a");
    if (!file) {
        fprintf(stderr, "Failed to open file: %s\n", strerror(errno));
        spiClose(spi_handle);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    if (fseek(file, 0, SEEK_END) != 0) {
        fprintf(stderr, "Failed to seek file: %s\n", strerror(errno));
        fclose(file);
        spiClose(spi_handle);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    if (ftell(file) == 0) {
        fprintf(file, "timestamp,flow_rate_lpm\n");
    }

    while (running) {
        clock_gettime(CLOCK_REALTIME, &sleep_time);
        sleep_time.tv_sec += sleep_time.tv_nsec / 1000000000;
        sleep_time.tv_nsec %= 1000000000;

        adc_value = spiTransfer(spi_handle, MCP3008_CHANNEL << 6);
        if (adc_value < 0) {
            fprintf(stderr, "Failed to read from SPI: %s\n", strerror(errno));
            break;
        }

        flow_rate = (adc_value >> 4) * AWM7300V_LSB;

        clock_gettime(CLOCK_REALTIME, &sleep_time);
        strftime(timestamp, sizeof(timestamp), "%Y-%m-%dT%H:%M:%S", gmtime(&sleep_time.tv_sec));
        fprintf(file, "%s,%f\n", timestamp, flow_rate);

        nanosleep(&sleep_time, NULL);
    }

    fclose(file);
    spiClose(spi_handle);
    gpioTerminate();

    return EXIT_SUCCESS;
}

#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <pigpio.h>
#include <errno.h>

#define SPI_CHANNEL 0
#define ADC_CHANNEL 0
#define MIN_RAW 300
#define MAX_RAW 700
#define MOISTURE_THRESHOLD 30
#define LOG_FREQUENCY 60
#define EMAIL "recipient@example.com"
#define MSMTP_CONFIG "/path/to/msmtp.conf"

volatile sig_atomic_t running = 1;

void signal_handler(int signum) {
    running = 0;
}

int main(int argc, char *argv[]) {
    if (argc != 8) {
        fprintf(stderr, "Usage: %s <spi_channel> <adc_channel> <min_raw> <max_raw> <moisture_threshold> <log_frequency> <email> <msmtp_config>\n", argv[0]);
        return EXIT_FAILURE;
    }

    SPI_CHANNEL = atoi(argv[1]);
    ADC_CHANNEL = atoi(argv[2]);
    MIN_RAW = atoi(argv[3]);
    MAX_RAW = atoi(argv[4]);
    MOISTURE_THRESHOLD = atoi(argv[5]);
    LOG_FREQUENCY = atoi(argv[6]);
    EMAIL = argv[7];
    MSMTP_CONFIG = argv[8];

    if (signal(SIGINT, signal_handler) == SIG_ERR || signal(SIGTERM, signal_handler) == SIG_ERR) {
        fprintf(stderr, "Could not set signal handler\n");
        return EXIT_FAILURE;
    }

    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return EXIT_FAILURE;
    }

    int spi_fd = spiOpen(SPI_CHANNEL, 500000, 0);
    if (spi_fd < 0) {
        fprintf(stderr, "Could not open SPI channel\n");
        gpioTerminate();
        return EXIT_FAILURE;
    }

    FILE *log_file = fopen("plant_data.txt", "a");
    if (!log_file) {
        fprintf(stderr, "Could not open log file\n");
        spiClose(spi_fd);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    while (running) {
        int raw = spiTransfer(spi_fd, ADC_CHANNEL << 8);
        if (raw < 0) {
            fprintf(stderr, "ADC read failed: %s\n", strerror(errno));
            continue;
        }

        float moisture_percent = (raw - MIN_RAW) * 100.0 / (MAX_RAW - MIN_RAW);
        if (moisture_percent < 0) {
            moisture_percent = 0;
        } else if (moisture_percent > 100) {
            moisture_percent = 100;
        }

        time_t now = time(NULL);
        struct tm *time_info = localtime(&now);
        char timestamp[20];
        strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", time_info);

        fprintf(log_file, "%s, %.2f\n", timestamp, moisture_percent);

        if (moisture_percent < MOISTURE_THRESHOLD) {
            char command[256];
            snprintf(command, sizeof(command), "echo 'Soil moisture is below threshold' | msmtp -a default -t %s < %s", EMAIL, MSMTP_CONFIG);
            FILE *pipe = popen(command, "r");
            if (!pipe) {
                fprintf(stderr, "Could not open pipe for command\n");
                continue;
            }

            int status = pclose(pipe);
            if (status != 0) {
                fprintf(stderr, "Command failed with status %d\n", status);
            }
        }

        sleep(LOG_FREQUENCY);
    }

    fclose(log_file);
    spiClose(spi_fd);
    gpioTerminate();

    return EXIT_SUCCESS;
}

#include <stdio.h>
