#define SPI_MODE 0
#define SPI_CS 8
#define ADC_CHANNEL 0
#define LOG_FILE "soil_moisture.log"
#define SAMPLE_INTERVAL 1

void log_sample(time_t timestamp, uint16_t raw_value, float moisture_percentage) {
    FILE *file = fopen(LOG_FILE, "a");
    if (file == NULL) {
        printf("Failed to open log file\n");
        return;
    }
    fprintf(file, "%ld %d %f\n", timestamp, raw_value, moisture_percentage);
    fclose(file);
}

void handle_sigint(int signum) {
    printf("Caught signal, exiting...\n");
    gpioTerminate();
    exit(0);
}

int main(int argc, char *argv[]) {
    signal(SIGINT, handle_sigint);
    signal(SIGTERM, handle_sigint);

    if (gpioInitialise() < 0) {
        printf("Failed to initialize pigpio\n");
        return 1;
    }

    int spi_handle = spiOpen(SPI_CHANNEL, SPI_SPEED, SPI_MODE);
    if (spi_handle < 0) {
        printf("Failed to open SPI channel\n");
        gpioTerminate();
        return 1;
    }

    int sample_interval = (argc > 1) ? atoi(argv[1]) : SAMPLE_INTERVAL;
    while (1) {
        uint16_t raw_value = spiTransfer(spi_handle, ADC_CHANNEL << 8);
        float moisture_percentage = (float)raw_value / 1023.0 * 100.0;
        moisture_percentage = (moisture_percentage < 0) ? 0 : (moisture_percentage > 100) ? 100 : moisture_percentage;

        time_t timestamp = time(NULL);
        log_sample(timestamp, raw_value, moisture_percentage);

        sleep(sample_interval);
    }

    spiClose(spi_handle);
    gpioTerminate();
    return 0;
