#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <stdbool.h>
#include <string.h>
#include <unistd.h>
#include <fcntl.h>
#include <signal.h>
#include <sys/ioctl.h>
#include <sys/types.h>
#include <sys/stat.h>
#include <linux/spi/spidev.h>
#include <gpiod.h>

#define SPI_DEVICE "/dev/spidev0.0"
#define SPI_SPEED 1000000
#define SPI_MODE 0
#define SPI_BITS 8
#define DRY_VALUE 700
#define WET_VALUE 300

static int spi_fd = -1;
static bool running = true;

static void cleanup(int signum) {
    running = false;
    if (spi_fd != -1) {
        close(spi_fd);
    }
    exit(signum);
}

static int open_spi_device() {
    int fd = open(SPI_DEVICE, O_RDWR);
    if (fd < 0) {
        perror("Failed to open SPI device");
        return -1;
    }
    return fd;
}

static void close_spi_device() {
    if (spi_fd != -1) {
        close(spi_fd);
    }
}

static void spi_transfer(uint8_t *tx, uint8_t *rx, size_t len) {
    struct spi_ioc_transfer tr = {
        .tx_buf = (unsigned long)tx,
        .rx_buf = (unsigned long)rx,
        .len = len,
        .speed_hz = SPI_SPEED,
        .bits_per_word = SPI_BITS,
        .cs_change = 0,
        .delay_usecs = 0,
        .tx_nbits = 0,
        .rx_nbits = 0,
    };
    if (ioctl(spi_fd, SPI_IOC_MESSAGE(1), &tr) < 0) {
        perror("SPI transfer failed");
        exit(EXIT_FAILURE);
    }
}

static uint16_t read_adc_channel(uint8_t channel) {
    uint8_t tx[3] = {1, (channel << 6), 0};
    uint8_t rx[3] = {0, 0, 0};
    spi_transfer(tx, rx, 3);
    return ((rx[1] & 0x0f) << 8) | rx[2];
}

static float calculate_moisture_percentage(uint16_t adc_value) {
    float percentage = (adc_value - WET_VALUE) / (float)(DRY_VALUE - WET_VALUE) * 100.0;
    return percentage < 0 ? 0 : (percentage > 100 ? 100 : percentage);
}

int main() {
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = cleanup;
    sigaction(SIGINT, &sa, NULL);
    sigaction(SIGTERM, &sa, NULL);

    spi_fd = open_spi_device();
    if (spi_fd < 0) {
        return EXIT_FAILURE;
    }

    while (running) {
        uint16_t adc_value = read_adc_channel(0);
        float moisture_percentage = calculate_moisture_percentage(adc_value);
        printf("ADC value: %d, Moisture: %.2f%%\n", adc_value, moisture_percentage);
        sleep(5);
    }

    close_spi_device();
    return EXIT_SUCCESS;
}

#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <pigpio.h>
#include <spi.h>

#define ADC_CHANNEL 0
#define ADC_MAX 1023
#define ADC_VOLTAGE_MAX 3.3
#define PRESSURE_MIN 10
#define PRESSURE_MAX 150
#define PRESSURE_VOLTAGE_MIN 0.5
#define PRESSURE_VOLTAGE_MAX 4.5

volatile sig_atomic_t stop = 0;

void signal_handler(int signum) {
    stop = 1;
}

int main() {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Failed to initialize pigpio\n");
        return EXIT_FAILURE;
    }

    if (spiOpen(0, 500000, 0) < 0) {
        fprintf(stderr, "Failed to open SPI bus\n");
        gpioTerminate();
        return EXIT_FAILURE;
    }

    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    while (!stop) {
        uint16_t adc_value = spiReadadc(ADC_CHANNEL);
        if (adc_value == 0 || adc_value == ADC_MAX) {
            printf("Sensor is not present or is stuck at %sV\n", adc_value == 0 ? "0" : "3.3");
            continue;
        }

        float voltage = (float)adc_value / ADC_MAX * ADC_VOLTAGE_MAX;
        if (voltage < PRESSURE_VOLTAGE_MIN || voltage > PRESSURE_VOLTAGE_MAX) {
            printf("ADC value out of range: %d\n", adc_value);
            continue;
        }

        float pressure = (voltage - PRESSURE_VOLTAGE_MIN) / (PRESSURE_VOLTAGE_MAX - PRESSURE_VOLTAGE_MIN) * (PRESSURE_MAX - PRESSURE_MIN) + PRESSURE_MIN;
        time_t now = time(NULL);
        struct tm *timeinfo = localtime(&now);
        char buffer[20];
        strftime(buffer, sizeof(buffer), "%Y-%m-%dT%H:%M:%S", timeinfo);
        printf("%s Pressure: %.2f kPa\n", buffer, pressure);

        sleep(1);
    }

    spiClose(0);
    gpioTerminate();
    return EXIT_SUCCESS;
}

#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <stdbool.h>
#include <string.h>
#include <time.h>
#include <unistd.h>
#include <signal.h>
#include <libgpiod.h>
#include <sys/ioctl.h>
#include <linux/spi/spidev.h>

#define SPI_CHANNEL 0
#define SPI_SPEED 1000000
#define SPI_MODE 0
#define MIN_ADC_VALUE 300
#define MAX_ADC_VALUE 700

static gpiod_chip *chip;
static gpiod_line *spi_ce0;
static int spi_fd;

void cleanup() {
    if (spi_ce0) gpiod_line_release(spi_ce0);
    if (chip) gpiod_chip_close(chip);
    if (spi_fd >= 0) close(spi_fd);
}

void sig_handler(int signum) {
    printf("Caught signal %d, exiting...\n", signum);
    cleanup();
    exit(0);
}

int main() {
    struct sigaction action;
    memset(&action, 0, sizeof(struct sigaction));
    action.sa_handler = sig_handler;
    sigaction(SIGINT, &action, NULL);
    sigaction(SIGTERM, &action, NULL);

    chip = gpiod_chip_open("/dev/gpiochip0");
    if (!chip) {
        fprintf(stderr, "Failed to open GPIO chip\n");
        return 1;
    }

    spi_ce0 = gpiod_chip_get_line(chip, 8);
    if (!spi_ce0) {
        fprintf(stderr, "Failed to get SPI CE0 line\n");
        cleanup();
        return 1;
    }

    if (gpiod_line_request_output(spi_ce0, "spi_ce0", 0) < 0) {
        fprintf(stderr, "Failed to request SPI CE0 line as output\n");
        cleanup();
        return 1;
    }

    spi_fd = open("/dev/spidev0.0", O_RDWR);
    if (spi_fd < 0) {
        fprintf(stderr, "Failed to open SPI device\n");
        cleanup();
        return 1;
    }

    struct spi_ioc_transfer xfer = {
        .tx_buf = 0,
        .rx_buf = 0,
        .len = 3,
        .speed_hz = SPI_SPEED,
        .delay_usecs = 0,
        .bits_per_word = 8,
        .cs_change = 0,
    };

    uint8_t tx[3] = {1, (1 << 6) | (SPI_CHANNEL << 3), 0};
    uint8_t rx[3];

    while (true) {
        time_t now = time(NULL);
        struct tm *t = localtime(&now);
        printf("%02d:%02d:%02d ", t->tm_hour, t->tm_min, t->tm_sec);

        gpiod_line_set_value(spi_ce0, 1);
        if (ioctl(spi_fd, SPI_IOC_MESSAGE(1), &xfer) < 0) {
            fprintf(stderr, "Failed to send SPI message\n");
            cleanup();
            return 1;
        }
        gpiod_line_set_value(spi_ce0, 0);

        rx[2] = tx[1] = 0;
        gpiod_line_set_value(spi_ce0, 1);
        if (ioctl(spi_fd, SPI_IOC_MESSAGE(1), &xfer) < 0) {
            fprintf(stderr, "Failed to receive SPI message\n");
            cleanup();
            return 1;
        }
        gpiod_line_set_value(spi_ce0, 0);

        int adc_value = (rx[1] << 8) | rx[2];
        if (adc_value == 0 || adc_value == 1023) {
            fprintf(stderr, "ADC value stuck at 0 or 1023, check wiring\n");
            cleanup();
            return 1;
        }

        float moisture_percent = (adc_value - MIN_ADC_VALUE) * 100.0 / (MAX_ADC_VALUE - MIN_ADC_VALUE);
        printf("Moisture: %.2f%%\n", moisture_percent);

        sleep(5);
    }

    cleanup();
    return 0;
}

#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <string.h>
#include <unistd.h>
#include <fcntl.h>
#include <sys/ioctl.h>
#include <linux/spi/spidev.h>
#include <signal.h>

#define SPI_CHANNEL 0
#define SPI_MODE 0
#define SPI_BITS_PER_WORD 8
#define SPI_SPEED 1000000
#define SPI_DEVICE "/dev/spidev0.0"

volatile sig_atomic_t stop = 0;

void signal_handler(int signum) {
    stop = 1;
}

int main() {
    int spi_fd;
    uint8_t tx[3] = {0x01, 0x80, 0x00};
    uint8_t rx[3];
    int moisture_percentage;

    if ((spi_fd = open(SPI_DEVICE, O_RDWR)) < 0) {
        perror("Failed to open SPI device");
        return EXIT_FAILURE;
    }

    struct spi_ioc_transfer spi[1] = {
        {
            .tx_buf = (unsigned long)tx,
            .rx_buf = (unsigned long)rx,
            .len = sizeof(tx),
            .speed_hz = SPI_SPEED,
            .bits_per_word = SPI_BITS_PER_WORD,
            .cs_change = 0,
            .delay_usecs = 0,
            .pad = 0
        }
    };

    if (ioctl(spi_fd, SPI_IOC_WR_MODE, &SPI_MODE) < 0) {
        perror("Failed to set SPI mode");
        close(spi_fd);
        return EXIT_FAILURE;
    }

    if (ioctl(spi_fd, SPI_IOC_WR_BITS_PER_WORD, &SPI_BITS_PER_WORD) < 0) {
        perror("Failed to set SPI bits per word");
        close(spi_fd);
        return EXIT_FAILURE;
    }

    if (ioctl(spi_fd, SPI_IOC_WR_MAX_SPEED_HZ, &SPI_SPEED) < 0) {
        perror("Failed to set SPI speed");
        close(spi_fd);
        return EXIT_FAILURE;
    }

    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    while (!stop) {
        if (ioctl(spi_fd, SPI_IOC_MESSAGE(1), spi) < 0) {
            perror("Failed to send SPI message");
            close(spi_fd);
            return EXIT_FAILURE;
        }

        // Extract the 10-bit result from the response
        moisture_percentage = ((rx[1] & 0x0F) << 8) | rx[2];
        moisture_percentage = (moisture_percentage * 100) / 1023;

        // Clamp the moisture percentage to the 0-100 range
        if (moisture_percentage < 0) {
            moisture_percentage = 0;
        } else if (moisture_percentage > 100) {
            moisture_percentage = 100;
        }

        printf("Moisture: %d%%\n", moisture_percentage);

        sleep(5);
    }

    close(spi_fd);
    return EXIT_SUCCESS;
}

