#define ADC_CHANNELS 4
#define ADC_REF_VOLTAGE 3.3
#define SAMPLE_INTERVAL 1

static bool running = true;

void signal_handler(int signum) {
    running = false;
}

int main() {
    struct gpiod_chip *chip;
    struct gpiod_line_request request;
    struct spi_ioc_transfer tr;
    uint8_t tx[3] = {1, 0, 0};
    uint8_t rx[3];
    int spi_fd, adc_fd;
    FILE *log_file;

    // Set up signal handler
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Open SPI device
    spi_fd = open("/dev/spidev0.0", O_RDWR);
    if (spi_fd < 0) {
        perror("Failed to open SPI device");
        return -1;
    }

    // Set up SPI device
    memset(&tr, 0, sizeof(tr));
    tr.tx_buf = (unsigned long)tx;
    tr.rx_buf = (unsigned long)rx;
    tr.len = sizeof(tx);
    tr.delay_usecs = 0;
    tr.speed_hz = SPI_SPEED;
    tr.bits_per_word = 8;
    if (ioctl(spi_fd, SPI_IOC_MESSAGE(1), &tr) < 0) {
        perror("Failed to set up SPI device");
        close(spi_fd);
        return -1;
    }

    // Open ADC device
    adc_fd = open("/dev/mcp3008", O_RDONLY);
    if (adc_fd < 0) {
        perror("Failed to open ADC device");
        close(spi_fd);
        return -1;
    }

    // Set up GPIO chip and line
    chip = gpiod_chip_open_by_name("gpiochip0");
    if (!chip) {
        perror("Failed to open GPIO chip");
        close(spi_fd);
        close(adc_fd);
        return -1;
    }
    memset(&request, 0, sizeof(request));
    request.consumer = "MCP3008";
    request.request_type = GPIO_REQUEST_OUTPUT;
    if (gpiod_chip_get_line(chip, SPI_CS, &request) < 0) {
        perror("Failed to get GPIO line");
        gpiod_chip_close(chip);
        close(spi_fd);
        close(adc_fd);
        return -1;
    }
    if (gpiod_line_request(chip, SPI_CS, &request) < 0) {
        perror("Failed to request GPIO line");
        gpiod_chip_close(chip);
        close(spi_fd);
        close(adc_fd);
        return -1;
    }

    // Open log file
    log_file = fopen("environmental_data.csv", "w");
    if (!log_file) {
        perror("Failed to open log file");
        gpiod_line_release(chip, SPI_CS);
        gpiod_chip_close(chip);
        close(spi_fd);
        close(adc_fd);
        return -1;
    }

    // Log CSV header
    fprintf(log_file, "Timestamp,Voltage0,Voltage1,Voltage2,Voltage3\n");

    while (running) {
        // Sample ADC channels
        for (int channel = 0; channel < ADC_CHANNELS; channel++) {
            tx[1] = (1 << 7) | (channel << 4);
            if (ioctl(spi_fd, SPI_IOC_MESSAGE(1), &tr) < 0) {
                perror("Failed to read ADC channel");
                fclose(log_file);
                gpiod_line_release(chip, SPI_CS);
                gpiod_chip_close(chip);
                close(spi_fd);
                close(adc_fd);
                return -1;
            }
            uint16_t value = (rx[1] << 8) | rx[2];
            float voltage = ADC_REF_VOLTAGE * value / 1024.0;
            fprintf(log_file, "%ld,%f,%f,%f,%f\n", time(NULL), voltage, voltage, voltage, voltage);
        }

        // Wait for next sample
        sleep(SAMPLE_INTERVAL);
    }

    // Clean up
    fclose(log_file);
    gpiod_line_release(chip, SPI_CS);
    gpiod_chip_close(chip);
    close(spi_fd);
    close(adc_fd);

    return 0;
}

