#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <signal.h>
#include <time.h>
#include <pigpio.h>

#define SPI_CHANNEL 0
#define SPI_SPEED 1000000
#define SPI_MODE 0
#define SPI_CE0 8
#define MOSI 10
#define MISO 9
#define SCLK 11
#define VH400_CHANNEL 0
#define WATER_PUMP 17
#define LOW_THRESHOLD 300
#define HIGH_THRESHOLD 600
#define LOG_CAPACITY 20

typedef struct {
    time_t timestamp;
    uint16_t moisture;
    int pump_state;
} LogEntry;

LogEntry log_buffer[LOG_CAPACITY];
int log_head = 0;
int log_tail = 0;
int log_count = 0;

void log_entry(time_t timestamp, uint16_t moisture, int pump_state) {
    log_buffer[log_head].timestamp = timestamp;
    log_buffer[log_head].moisture = moisture;
    log_buffer[log_head].pump_state = pump_state;
    log_head = (log_head + 1) % LOG_CAPACITY;
    if (log_count < LOG_CAPACITY) {
        log_count++;
    } else {
        log_tail = (log_tail + 1) % LOG_CAPACITY;
    }
}

void print_log() {
    printf("Log:\n");
    for (int i = 0; i < log_count; i++) {
        int index = (log_tail + i) % LOG_CAPACITY;
        printf("%ld: Moisture: %d, Pump: %d\n", log_buffer[index].timestamp, log_buffer[index].moisture, log_buffer[index].pump_state);
    }
}

void signal_handler(int signum) {
    gpioWrite(WATER_PUMP, 0);
    gpioTerminate();
    exit(signum);
}

void timer_callback(unsigned int timer) {
    static time_t last_sample = 0;
    time_t now = time(NULL);
    if (now - last_sample < 5) {
        return;
    }
    last_sample = now;

    uint8_t tx[3] = {1, VH400_CHANNEL << 4, 0};
    uint8_t rx[3];
    int result = spiXfer(SPI_CHANNEL, tx, rx, 3);
    if (result < 0) {
        printf("SPI transfer failed: %s\n", strerror(-result));
        return;
    }

    uint16_t moisture = ((rx[1] & 3) << 8) | rx[2];
    int pump_state = (moisture < LOW_THRESHOLD) ? 1 : (moisture > HIGH_THRESHOLD) ? 0 : log_buffer[log_head - 1].pump_state;
    log_entry(now, moisture, pump_state);
    gpioWrite(WATER_PUMP, pump_state);

    print_log();
}

int main() {
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    if (gpioInitialise() < 0) {
        printf("pigpio initialization failed\n");
        return 1;
    }

    if (spiOpen(SPI_CHANNEL, SPI_SPEED, SPI_MODE, SPI_CE0, MOSI, MISO, SCLK) < 0) {
        printf("SPI open failed\n");
        gpioTerminate();
        return 1;
    }

    if (gpioSetMode(WATER_PUMP, PI_OUTPUT) < 0) {
        printf("GPIO mode set failed\n");
        spiClose(SPI_CHANNEL);
        gpioTerminate();
        return 1;
    }

    unsigned int timer = gpioSetTimerFunc(5000, timer_callback, 0);
    if (timer == 0) {
        printf("Timer setup failed\n");
        spiClose(SPI_CHANNEL);
        gpioTerminate();
        return 1;
    }

    while (1) {
        gpioSleep(PI_TIME_RELATIVE, 0, 1000000);
    }

    return 0;
}

