#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <pigpio.h>
#include <errno.h>

#define SPI_CHANNEL 0
#define SPI_SPEED 1000000
#define SPI_MODE 0
#define VREF 3.3
#define NUM_CHANNELS 3
#define LOG_FILE "analog_log.csv"

static int spi_handle = -1;
static FILE *log_file = NULL;

void close_spi_and_log() {
    if (spi_handle != -1) {
        spiClose(spi_handle);
    }
    if (log_file != NULL) {
        fclose(log_file);
    }
    gpioTerminate();
}

void handle_sigint(int signum) {
    close_spi_and_log();
    exit(EXIT_SUCCESS);
}

int main() {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Failed to initialize pigpio: %s\n", strerror(errno));
        return EXIT_FAILURE;
    }

    atexit(close_spi_and_log);
    signal(SIGINT, handle_sigint);

    spi_handle = spiOpen(SPI_CHANNEL, SPI_SPEED, SPI_MODE);
    if (spi_handle < 0) {
        fprintf(stderr, "Failed to open SPI channel: %s\n", strerror(errno));
        return EXIT_FAILURE;
    }

    log_file = fopen(LOG_FILE, "w");
    if (log_file == NULL) {
        fprintf(stderr, "Failed to open log file: %s\n", strerror(errno));
        return EXIT_FAILURE;
    }

    fprintf(log_file, "Timestamp,Channel,Voltage\n");

    uint8_t tx_buf[3] = {0x01, 0x00, 0x00};
    uint8_t rx_buf[3];

    while (1) {
        for (int channel = 0; channel < NUM_CHANNELS; channel++) {
            tx_buf[1] = (0x08 | (channel << 4));
            int ret = spiXfer(spi_handle, tx_buf, rx_buf, 3);
            if (ret < 0) {
                fprintf(stderr, "SPI transfer failed: %s\n", strerror(errno));
                continue;
            }

            uint16_t reading = ((rx_buf[1] & 0x03) << 8) | rx_buf[2];
            float voltage = VREF * reading / 1024.0;

            time_t now = time(NULL);
            struct tm *timeinfo = gmtime(&now);
            char timestamp[20];
            strftime(timestamp, sizeof(timestamp), "%FT%TZ", timeinfo);

            fprintf(log_file, "%s,%d,%.2f\n", timestamp, channel, voltage);
        }

        sleep(500);
    }

    return EXIT_SUCCESS;
}

