#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <stdbool.h>
#include <string.h>
#include <unistd.h>
#include <fcntl.h>
#include <signal.h>
#include <sys/ioctl.h>
#include <linux/i2c.h>
#include <linux/i2c-dev.h>
#include <gpiod.h>

#define I2C_BUS "/dev/i2c-1"
#define I2C_ADDRESS 0x48
#define ADC_CHANNEL 0
#define RELAY_PIN 17
#define DOOR_SENSOR_PIN 27
#define BASELINE_SAMPLES 10
#define TRIGGER_THRESHOLD_PERCENT 80
#define EVENT_LOG_FILE "/var/log/door_events.log"

static int i2c_fd;
static struct gpiod_chip *chip;
static struct gpiod_line *line;
static bool running = true;

static void cleanup() {
    gpiod_line_set_value(line, 0);
    gpiod_chip_close(chip);
    close(i2c_fd);
}

static void sig_handler(int signum) {
    running = false;
}

static int read_adc() {
    struct i2c_rdwr_ioctl_data packets;
    struct i2c_msg messages[2];
    uint8_t reg = ADC_CHANNEL;
    uint16_t value;

    messages[0].addr = I2C_ADDRESS;
    messages[0].flags = 0;
    messages[0].len = 1;
    messages[0].buf = &reg;

    messages[1].addr = I2C_ADDRESS;
    messages[1].flags = I2C_M_RD;
    messages[1].len = 2;
    messages[1].buf = (uint8_t *)&value;

    packets.msgs = messages;
    packets.nmsgs = 2;

    if (ioctl(i2c_fd, I2C_RDWR, &packets) < 0) {
        perror("Failed to read ADC");
        return -1;
    }

    return value;
}

static void log_event(const char *message) {
    FILE *file = fopen(EVENT_LOG_FILE, "a");
    if (file) {
        fprintf(file, "%ld: %s\n", time(NULL), message);
        fclose(file);
    }
}

int main() {
    struct sigaction action;
    int baseline_sum = 0;
    int trigger_threshold;
    int adc_value;

    memset(&action, 0, sizeof(action));
    action.sa_handler = sig_handler;
    sigaction(SIGINT, &action, NULL);
    sigaction(SIGTERM, &action, NULL);

    atexit(cleanup);

    i2c_fd = open(I2C_BUS, O_RDWR);
    if (i2c_fd < 0) {
        perror("Failed to open I2C bus");
        return EXIT_FAILURE;
    }

    chip = gpiod_chip_open_by_name("gpiochip0");
    if (!chip) {
        perror("Failed to open GPIO chip");
        return EXIT_FAILURE;
    }

    line = gpiod_chip_get_line(chip, RELAY_PIN);
    if (!line) {
        perror("Failed to get relay line");
        return EXIT_FAILURE;
    }

    gpiod_line_request_output(line, "relay", 0);

    line = gpiod_chip_get_line(chip, DOOR_SENSOR_PIN);
    if (!line) {
        perror("Failed to get door sensor line");
        return EXIT_FAILURE;
    }

    gpiod_line_request_input(line);

    for (int i = 0; i < BASELINE_SAMPLES; i++) {
        adc_value = read_adc();
        if (adc_value < 0) {
            return EXIT_FAILURE;
        }
        baseline_sum += adc_value;
        usleep(50000); // 50 ms
    }

    trigger_threshold = baseline_sum / BASELINE_SAMPLES * TRIGGER_THRESHOLD_PERCENT / 100;

    while (running) {
        adc_value = read_adc();
        if (adc_value < 0) {
            continue;
        }

        if (adc_value < trigger_threshold) {
            gpiod_line_set_value(line, 1);
            usleep(3000000); // 3 seconds
            gpiod_line_set_value(line, 0);

            int door_open = gpiod_line_get_value(line);
            if (door_open) {
                log_event("door opened");
            } else {
                log_event("door not opened");
            }
        }

        usleep(200000); // 200 ms
    }

    return EXIT_SUCCESS;
}

#include <stdio.h>
