#include <linux/spi/spidev.h>
#include <gpiod.h>

#define SPI_SPEED 1000000
#define SPI_MODE 0
#define SPI_BITS 8
#define MCP3008_CHANNEL 0
#define LOG_FILE "soil_moisture_log.csv"
#define LOG_INTERVAL 5

int spi_fd[3] = {0};
int gpiod_fd[3] = {0};

void close_spi() {
    for (int i = 0; i < 3; i++) {
        if (spi_fd[i] > 0) close(spi_fd[i]);
        if (gpiod_fd[i] > 0) close(gpiod_fd[i]);
    }
}

void write_log_header() {
    FILE *file = fopen(LOG_FILE, "w");
    if (file == NULL) {
        perror("Failed to open log file");
        exit(EXIT_FAILURE);
    }
    fprintf(file, "timestamp,sensor1,sensor2,sensor3\n");
    fclose(file);
}

void write_log(int sensor1, int sensor2, int sensor3) {
    FILE *file = fopen(LOG_FILE, "a");
    if (file == NULL) {
        perror("Failed to open log file");
        exit(EXIT_FAILURE);
    }
    fprintf(file, "%ld,%d,%d,%d\n", time(NULL), sensor1, sensor2, sensor3);
    fclose(file);
}

int read_mcp3008(int chip, int channel) {
    uint8_t tx[3] = {0x01, (0x08 | channel) << 4, 0x00};
    uint8_t rx[3] = {0, 0, 0};
    struct spi_ioc_transfer tr = {
        .tx_buf = (unsigned long)tx,
        .rx_buf = (unsigned long)rx,
        .len = sizeof(tx),
        .speed_hz = SPI_SPEED,
        .delay_usecs = 0,
        .bits_per_word = SPI_BITS,
    };
    if (ioctl(spi_fd[chip], SPI_IOC_MESSAGE(1), &tr) < 0) {
        perror("Failed to read from MCP3008");
        return -1;
    }
    return ((rx[1] & 0x03) << 8) | rx[2];
}

int main() {
    atexit(close_spi);
    signal(SIGINT, exit);
    signal(SIGTERM, exit);

    for (int i = 0; i < 3; i++) {
        spi_fd[i] = open("/dev/spidev0.0", O_RDWR);
        if (spi_fd[i] < 0) {
            perror("Failed to open SPI device");
            exit(EXIT_FAILURE);
        }
        gpiod_fd[i] = gpiod_chip_open_by_name("gpiochip0");
        if (gpiod_fd[i] < 0) {
            perror("Failed to open GPIO chip");
            exit(EXIT_FAILURE);
        }
        struct gpiod_line_request req = {
            .consumer = "MCP3008 CS",
            .request_type = GPIOD_LINE_REQUEST_OUTPUT,
            .default_value = 1,
        };
        gpiod_chip_request_line(gpiod_fd[i], 8 + i, &req);
    }

    write_log_header();

    while (true) {
        for (int i = 0; i < 3; i++) {
            gpiod_chip_set_line_value(gpiod_fd[i], 8 + i, 0);
            int value = read_mcp3008(i, MCP3008_CHANNEL);
            gpiod_chip_set_line_value(gpiod_fd[i], 8 + i, 1);
            if (value < 0) value = -1;
            write_log(value, value, value);
        }
        sleep(LOG_INTERVAL);
    }

    return 0;
}

