        if (ioctl(spi_fd, SPI_IOC_MESSAGE(3), tx) == 3) {
            value = (rx[1] << 8) | rx[2];
            break;
        }
    }
    return value;
}

int main(int argc, char *argv[]) {
    int opt;
    while ((opt = getopt(argc, argv, "t:d:s:")) != -1) {
        switch (opt) {
            case 't':
                threshold = atoi(optarg);
                break;
            case 'd':
                duration = atoi(optarg);
                break;
            case 's':
                interval = atoi(optarg);
                break;
            default:
                fprintf(stderr, "Usage: %s [-t threshold] [-d duration] [-s interval]\n", argv[0]);
                exit(EXIT_FAILURE);
        }
    }

    if (gpioInitialise() < 0) {
        fprintf(stderr, "Failed to initialize pigpio\n");
        exit(EXIT_FAILURE);
    }

    atexit(terminate);

    signal(SIGINT, terminate);
    signal(SIGTERM, terminate);

    spi_fd = open(SPI_DEVICE, O_RDWR);
    if (spi_fd < 0) {
        fprintf(stderr, "Failed to open SPI device\n");
        exit(EXIT_FAILURE);
    }

    if (ioctl(spi_fd, SPI_IOC_WR_MODE, &SPI_MODE) < 0 ||
        ioctl(spi_fd, SPI_IOC_WR_MAX_SPEED_HZ, &SPI_SPEED) < 0) {
        fprintf(stderr, "Failed to configure SPI\n");
        exit(EXIT_FAILURE);
    }

    gpioSetMode(GPIO_MCP3008, PI_OUTPUT);
    gpioSetMode(GPIO_PUMP, PI_OUTPUT);

    while (1) {
        int moisture = read_moisture();
        int percentage = (moisture - 200) * 100 / (800 - 200);
        percentage = percentage < 0 ? 0 : (percentage > 100 ? 100 : percentage);

        time_t now = time(NULL);
        struct tm *timeinfo = localtime(&now);
        char buffer[80];
        strftime(buffer, sizeof(buffer), "%Y-%m-%d %H:%M:%S", timeinfo);

        printf("%s Moisture: %d%%\n", buffer, percentage);

        if (percentage < threshold) {
            gpioWrite(GPIO_PUMP, 1);
            sleep(duration);
            gpioWrite(GPIO_PUMP, 0);
        }

        sleep(interval);
    }

    return 0;
}

#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <pigpio.h>
#include <errno.h>

#define ADC_CHANNEL 0
#define SAMPLE_INTERVAL 10000 // 10 ms
#define THRESHOLD_MARGIN 0.2
#define LOG_FILE "/var/log/sound_events.log"

static volatile sig_atomic_t running = 1;
static uint8_t spi_channel = 0;
static uint8_t adc_channel = 0;
static float ema = 0.0;
static FILE *log_file = NULL;

void signal_handler(int signum) {
    running = 0;
}

int main(int argc, char *argv[]) {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Failed to initialize pigpio: %s\n", strerror(errno));
        return EXIT_FAILURE;
    }

    if ((log_file = fopen(LOG_FILE, "a")) == NULL) {
        fprintf(stderr, "Failed to open log file: %s\n", strerror(errno));
        gpioTerminate();
        return EXIT_FAILURE;
    }

    if (signal(SIGINT, signal_handler) == SIG_ERR || signal(SIGTERM, signal_handler) == SIG_ERR) {
        fprintf(stderr, "Failed to set signal handler: %s\n", strerror(errno));
        fclose(log_file);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    if (spiOpen(spi_channel, 1000000, 0) < 0) {
        fprintf(stderr, "Failed to open SPI channel: %s\n", strerror(errno));
        fclose(log_file);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    while (running) {
        uint16_t raw_value = spiTransfer(spi_channel, adc_channel << 8);
        float value = raw_value / 1024.0;

        if (ema == 0.0) {
            ema = value;
        } else {
            ema = ema + THRESHOLD_MARGIN * (value - ema);
        }

        if (value > ema) {
            time_t now = time(NULL);
            struct tm *timeinfo = localtime(&now);
            char timestamp[20];
            strftime(timestamp, sizeof(timestamp), "%Y-%m-%dT%H:%M:%S", timeinfo);

            fprintf(log_file, "%s: %.3f\n", timestamp, value);
            fflush(log_file);
        }

        gpioDelay(SAMPLE_INTERVAL);
    }

    fclose(log_file);
    spiClose(spi_channel);
    gpioTerminate();
    return EXIT_SUCCESS;
}

#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <unistd.h>
#include <fcntl.h>
#include <signal.h>
#include <sys/ioctl.h>
#include <linux/i2c-dev.h>
#include <libgpiod.h>

#define I2C_BUS "/dev/i2c-1"
#define PCF8591_ADDRESS 0x48
#define SAMPLE_INTERVAL 100000 /* 100 ms */

static int i2c_fd = -1;

void cleanup(int exit_code) {
    if (i2c_fd != -1) {
        close(i2c_fd);
    }
    exit(exit_code);
}

void handle_sigint(int signum) {
    printf("\nInterrupt signal received, exiting...\n");
    cleanup(1);
}

int main() {
    struct gpiod_chip *chip;
    struct gpiod_line_request request;
    struct sigaction sa;
    int ret;

    /* Set up signal handler for graceful exit */
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = handle_sigint;
    sigaction(SIGINT, &sa, NULL);

    /* Open I2C bus */
    i2c_fd = open(I2C_BUS, O_RDWR);
    if (i2c_fd < 0) {
        perror("Failed to open I2C bus");
        cleanup(1);
    }

    /* Set up GPIO line for I2C SCL */
    chip = gpiod_chip_open_by_name("i2c-1");
    if (!chip) {
        perror("Failed to open GPIO chip");
        cleanup(1);
    }

    memset(&request, 0, sizeof(request));
    request.consumer = "PCF8591";
    request.request_type = GPIO_LINE_REQUEST_DIRECTION_OUTPUT;
    request.flags = GPIO_LINE_REQUEST_FLAG_OPEN_DRAIN;

    ret = gpiod_chip_request_line(chip, 5, &request);
    if (ret < 0) {
        perror("Failed to request GPIO line");
        cleanup(1);
    }

    /* Set up PCF8591 ADC */
    ret = ioctl(i2c_fd, I2C_SLAVE, PCF8591_ADDRESS);
    if (ret < 0) {
        perror("Failed to set I2C address");
        cleanup(1);
    }

    /* Configure ADC for single-ended mode on channel 0 */
    uint8_t config_byte = 0x40; /* AIN0, single-ended, no analog output */
    ret = write(i2c_fd, &config_byte, 1);
    if (ret < 0) {
        perror("Failed to write configuration byte");
        cleanup(1);
    }

    /* Discard previous conversion result */
    uint8_t dummy_byte;
    ret = read(i2c_fd, &dummy_byte, 1);
    if (ret < 0) {
        perror("Failed to read dummy byte");
        cleanup(1);
    }

    /* Main loop */
    while (1) {
        ret = read(i2c_fd, &dummy_byte, 1);
        if (ret < 0) {
            perror("Failed to read sample");
            cleanup(1);
        }

        printf("Sample: %d\n", (int)dummy_byte);

        /* Wait for next sample */
        usleep(SAMPLE_INTERVAL);
    }

    cleanup(0);
}

#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <unistd.h>
#include <signal.h>
#include <syslog.h>
#include <pigpio.h>
#include <i2c/smbus.h>

#define I2C_BUS 1
#define I2C_ADDRESS 0x48
#define ADC_CHANNEL 0
#define GPIO_SHUTDOWN 27
#define SAMPLES 10
#define THRESHOLD 500

volatile sig_atomic_t stop = 0;

void signal_handler(int signum) {
    stop = 1;
}

int main() {
    int i2c_handle, adc_value, voltage, magnetic_field;
    int buffer[SAMPLES];
    int buffer_index = 0;
    int sum = 0;
    int average;

    openlog("Hall-effect sensor", LOG_PID, LOG_USER);

    if ((i2c_handle = i2c_open(I2C_BUS, I2C_ADDRESS)) < 0) {
        syslog(LOG_ERR, "Failed to open I2C bus");
        closelog();
        return EXIT_FAILURE;
    }

    if (gpioInitialise() < 0) {
        syslog(LOG_ERR, "Failed to initialize pigpio");
        i2c_close(i2c_handle);
        closelog();
        return EXIT_FAILURE;
    }

    if (gpioSetMode(GPIO_SHUTDOWN, PI_OUTPUT) < 0) {
        syslog(LOG_ERR, "Failed to set GPIO mode");
        gpioTerminate();
        i2c_close(i2c_handle);
        closelog();
        return EXIT_FAILURE;
    }

    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    while (!stop) {
        if ((adc_value = i2c_readWordData(i2c_handle, ADC_CHANNEL)) < 0) {
            syslog(LOG_ERR, "Failed to read ADC value");
            continue;
        }

        voltage = (adc_value >> 4) * 3.3 / 4096;
        if (voltage < 0 || voltage > 3.3) {
            syslog(LOG_ERR, "Invalid voltage reading");
            continue;
        }

        magnetic_field = (voltage - 2.5) / 1.4 * 1000;
        buffer[buffer_index] = magnetic_field;
        buffer_index = (buffer_index + 1) % SAMPLES;
        sum -= buffer[buffer_index];
        sum += magnetic_field;
        average = sum / SAMPLES;

        if (average > THRESHOLD) {
            gpioWrite(GPIO_SHUTDOWN, PI_HIGH);
            syslog(LOG_INFO, "Motor shutdown due to high magnetic field: %d Gauss", average);
        }

        syslog(LOG_INFO, "Magnetic field: %d Gauss", magnetic_field);
    }

    gpioWrite(GPIO_SHUTDOWN, PI_LOW);
    gpioTerminate();
    i2c_close(i2c_handle);
    closelog();

    return EXIT_SUCCESS;
}

#include <stdio.h>
