#include <pigpio.h>

#define SPI_CHANNEL 0
#define SPI_SPEED 1000000
#define SPI_MODE 0
#define ADC_CHANNEL 0
#define WATERING_THRESHOLD 300
#define WATERING_DURATION 10
#define READ_INTERVAL 60
#define PUMP_GPIO 18
#define LOG_FILE "watering_events.txt"

volatile sig_atomic_t running = 1;

void signal_handler(int signum) {
    running = 0;
}

int main() {
    FILE *log_file;
    int spi_fd, adc_value, pump_fd;
    struct timespec sleep_time = {0, 100000000}; // 0.1 seconds

    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    if ((spi_fd = spiOpen(SPI_CHANNEL, SPI_SPEED, SPI_MODE)) < 0) {
        fprintf(stderr, "Failed to open SPI channel\n");
        return EXIT_FAILURE;
    }

    if ((pump_fd = gpioOpen(PUMP_GPIO, PI_OUTPUT)) < 0) {
        fprintf(stderr, "Failed to open GPIO pin %d\n", PUMP_GPIO);
        spiClose(spi_fd);
        return EXIT_FAILURE;
    }

    log_file = fopen(LOG_FILE, "a");
    if (!log_file) {
        fprintf(stderr, "Failed to open log file\n");
        spiClose(spi_fd);
        gpioClose(pump_fd);
        return EXIT_FAILURE;
    }

    while (running) {
        adc_value = spiXfer(spi_fd, ADC_CHANNEL << 8, 0x0000);
        if (adc_value < 0) {
            fprintf(stderr, "SPI communication error\n");
            break;
        }

        if (adc_value < WATERING_THRESHOLD) {
            gpioWrite(pump_fd, PI_HIGH);
            clock_nanosleep(CLOCK_MONOTONIC, 0, &sleep_time, NULL);
            gpioWrite(pump_fd, PI_LOW);
            clock_nanosleep(CLOCK_MONOTONIC, 0, &sleep_time, NULL);
            fprintf(log_file, "%ld, %d\n", time(NULL), adc_value);
            fflush(log_file);
        }

        clock_nanosleep(CLOCK_MONOTONIC, 0, &sleep_time, NULL);
    }

    fclose(log_file);
    gpioClose(pump_fd);
    spiClose(spi_fd);

    return EXIT_SUCCESS;
}

