volatile sig_atomic_t stop = 0;

void sigint_handler(int signum) {
    stop = 1;
}

int main() {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Failed to initialize pigpio\n");
        return EXIT_FAILURE;
    }

    signal(SIGINT, sigint_handler);

    int spi_handle = spiOpen(SPI_CHANNEL, SPI_SPEED, 0);
    if (spi_handle < 0) {
        fprintf(stderr, "Failed to open SPI channel\n");
        gpioTerminate();
        return EXIT_FAILURE;
    }

    while (!stop) {
        uint8_t tx_buffer[3] = {1, 0x80 | (ADC_CHANNEL >> 4), ADC_CHANNEL << 4};
        uint8_t rx_buffer[3];

        if (spiXfer(spi_handle, tx_buffer, rx_buffer, sizeof(tx_buffer)) != sizeof(tx_buffer)) {
            fprintf(stderr, "Failed to read from ADC\n");
            continue;
        }

        uint16_t adc_value = ((uint16_t)rx_buffer[1] << 8) | rx_buffer[2];
        float intensity_level = (float)adc_value / ADC_MAX * RAIN_INTENSITY_MAX;

        time_t now = time(NULL);
        struct tm *time_info = localtime(&now);
        char time_str[20];
        strftime(time_str, sizeof(time_str), "%Y-%m-%d %H:%M:%S", time_info);

        printf("%s: ADC value: %d, Intensity level: %.2f\n", time_str, adc_value, intensity_level);

        sleep(1);
    }

    spiClose(spi_handle);
    gpioTerminate();

    return EXIT_SUCCESS;
}

