#define DEFAULT_THRESHOLD 100.0
#define LED_PIN 17
#define ADC_ADDRESS 0x48
#define ADC_CHANNEL 0
#define ADC_GAIN GAIN_4_096

volatile sig_atomic_t stop = false;

void handle_signal(int signum) {
    stop = true;
}

int main(int argc, char *argv[]) {
    float threshold = DEFAULT_THRESHOLD;
    float gauss;
    int i2c_handle;
    int led_handle;
    int result;

    if (argc > 1) {
        threshold = atof(argv[1]);
    }

    signal(SIGINT, handle_signal);
    signal(SIGTERM, handle_signal);

    if ((i2c_handle = i2cOpen(1, ADC_ADDRESS, 0)) < 0) {
        fprintf(stderr, "Failed to open I2C bus 1\n");
        return EXIT_FAILURE;
    }

    if ((led_handle = gpioInitialise()) < 0) {
        fprintf(stderr, "Failed to initialize GPIO\n");
        i2cClose(i2c_handle);
        return EXIT_FAILURE;
    }

    gpioSetMode(led_handle, LED_PIN, PI_OUTPUT);

    while (!stop) {
        result = i2cReadReg16(i2c_handle, ADC_CHANNEL);
        if (result < 0) {
            fprintf(stderr, "Failed to read from ADC\n");
            break;
        }

        gauss = (result * 0.001) / ADC_GAIN;

        printf("Magnetic field strength: %.2f Gauss\n", gauss);

        if (gauss > threshold) {
            gpioWrite(led_handle, LED_PIN, PI_HIGH);
            usleep(50000); // 50 ms on
            gpioWrite(led_handle, LED_PIN, PI_LOW);
            usleep(50000); // 50 ms off
            usleep(500000); // 1 second
        }

        usleep(100000); // 100 ms delay
    }

    gpioWrite(led_handle, LED_PIN, PI_OFF);
    gpioTerminate();
    i2cClose(i2c_handle);

    return EXIT_SUCCESS;
}

#include <stdio.h>
