#define RELAY_PIN 17
#define ADC_CHANNEL 0
#define ADC_MAX 1023
#define MOISTURE_LOW_THRESHOLD 30
#define MOISTURE_HIGH_THRESHOLD 35
#define MQTT_TOPIC "soil_moisture"
#define MQTT_SERVER "localhost"
#define SPI_SPEED 1000000

int relay_state = 0;
int mqtt_connected = 0;
int adc_value = 0;
int pump_on = 0;

void signal_handler(int signum) {
    gpioWrite(RELAY_PIN, 0);
    mosquitto_disconnect(NULL);
    pigpioTerminate();
    exit(0);
}

void mqtt_callback(struct mosquitto *mosq, void *obj, const struct mosquitto_message *msg) {
    if (strcmp(msg->topic, "pump_control") == 0) {
        if (strcmp((char *)msg->payload, "pump_on") == 0) {
            pump_on = 1;
        } else if (strcmp((char *)msg->payload, "pump_off") == 0) {
            pump_on = 0;
        }
    }
}

void publish_moisture(int value) {
    char payload[10];
    sprintf(payload, "%d", value);
    mosquitto_publish(NULL, NULL, MQTT_TOPIC, strlen(payload), payload, 0, false);
}

int main() {
    struct mosquitto *mosq = NULL;
    int spi_fd;

    openlog("soil_moisture", LOG_PID, LOG_USER);
    syslog(LOG_INFO, "Starting soil_moisture program");

    mosquitto_lib_init();

    mosq = mosquitto_new(NULL, true, NULL);
    if (!mosq) {
        syslog(LOG_ERR, "Failed to create mosquitto client");
        closelog();
        return 1;
    }

    mosquitto_connect_callback_set(mosq, mqtt_callback);
    if (mosquitto_connect(mosq, MQTT_SERVER, 1883, 60) != MOSQ_ERR_SUCCESS) {
        syslog(LOG_ERR, "Failed to connect to MQTT server");
        mosquitto_destroy(mosq);
        closelog();
        return 1;
    }

    if (mosquitto_subscribe(mosq, NULL, "pump_control", 0) != MOSQ_ERR_SUCCESS) {
        syslog(LOG_ERR, "Failed to subscribe to MQTT topic");
        mosquitto_destroy(mosq);
        closelog();
        return 1;
    }

    mosquitto_loop_start(mosq);

    if (gpioInitialise() < 0) {
        syslog(LOG_ERR, "Failed to initialize pigpio");
        mosquitto_disconnect(mosq);
        mosquitto_destroy(mosq);
        closelog();
        return 1;
    }

    if ((spi_fd = spiOpen(0, 0, SPI_SPEED)) < 0) {
        syslog(LOG_ERR, "Failed to open SPI device");
        gpioTerminate();
        mosquitto_disconnect(mosq);
        mosquitto_destroy(mosq);
        closelog();
        return 1;
    }

    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    gpioSetMode(RELAY_PIN, PI_OUTPUT);
    gpioWrite(RELAY_PIN, 0);

    while (1) {
        adc_value = spiTransfer(spi_fd, ADC_CHANNEL << 8);
        adc_value = (adc_value >> 4) & 0x3ff;

        if (adc_value < 0 || adc_value > ADC_MAX) {
            syslog(LOG_ERR, "Invalid ADC value: %d", adc_value);
            continue;
        }

        int moisture_percent = (adc_value * 100) / ADC_MAX;

        if (moisture_percent < MOISTURE_LOW_THRESHOLD) {
            if (relay_state == 0) {
                gpioWrite(RELAY_PIN, 1);
                relay_state = 1;
                syslog(LOG_INFO, "Relay activated");
            }
        } else if (moisture_percent > MOISTURE_HIGH_THRESHOLD) {
            if (relay_state == 1) {
                gpioWrite(RELAY_PIN, 0);
                relay_state = 0;
                syslog(LOG_INFO, "Relay deactivated");
            }
        }

        if (pump_on) {
            gpioWrite(RELAY_PIN, 1);
        }

        publish_moisture(moisture_percent);

        sleep(60);
    }

    mosquitto_disconnect(mosq);
    mosquitto_destroy(mosq);
    gpioTerminate();
    spiClose(spi_fd);
    closelog();

    return 0;
}

