static void handle_sigint(int signum) {
    close_spi();
    exit(0);
}

int main(void) {
    struct spi_ioc_transfer spi_xfer;
    uint8_t tx_buf[3] = {0x01, ADC_CHANNEL << 4, 0x00};
    uint8_t rx_buf[3];
    uint16_t raw_value;
    double voltage;
    struct sigaction sa;

    memset(&spi_xfer, 0, sizeof(spi_xfer));
    spi_xfer.tx_buf = (unsigned long)tx_buf;
    spi_xfer.rx_buf = (unsigned long)rx_buf;
    spi_xfer.len = sizeof(tx_buf);
    spi_xfer.delay_usecs = SPI_DELAY;
    spi_xfer.speed_hz = SPI_SPEED;
    spi_xfer.bits_per_word = SPI_BITS;

    if ((spi_fd = open(SPI_DEVICE, O_RDWR)) < 0) {
        fprintf(stderr, "Failed to open SPI device: %s\n", strerror(errno));
        return EXIT_FAILURE;
    }

    if (ioctl(spi_fd, SPI_IOC_WR_MODE, &SPI_MODE) < 0) {
        fprintf(stderr, "Failed to set SPI mode: %s\n", strerror(errno));
        close_spi();
        return EXIT_FAILURE;
    }

    if (ioctl(spi_fd, SPI_IOC_WR_BITS_PER_WORD, &SPI_BITS) < 0) {
        fprintf(stderr, "Failed to set SPI bits per word: %s\n", strerror(errno));
        close_spi();
        return EXIT_FAILURE;
    }

    if (ioctl(spi_fd, SPI_IOC_WR_MAX_SPEED_HZ, &SPI_SPEED) < 0) {
        fprintf(stderr, "Failed to set SPI speed: %s\n", strerror(errno));
        close_spi();
        return EXIT_FAILURE;
    }

    sa.sa_handler = handle_sigint;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) < 0) {
        fprintf(stderr, "Failed to set up signal handler: %s\n", strerror(errno));
        close_spi();
        return EXIT_FAILURE;
    }

    while (true) {
        if (ioctl(spi_fd, SPI_IOC_MESSAGE(1), &spi_xfer) < 0) {
            fprintf(stderr, "Failed to send SPI message: %s\n", strerror(errno));
            close_spi();
            return EXIT_FAILURE;
        }

        raw_value = (rx_buf[1] << 8) | rx_buf[2];
        voltage = raw_value * VREF / 1024.0;

        printf("Raw value: %d, Voltage: %.2f V\n", raw_value, voltage);

        usleep(SAMPLE_INTERVAL);
    }

    close_spi();
    return EXIT_SUCCESS;
}

