        spiClose(SPI_CHANNEL);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    while (!stop) {
        uint16_t adc_value;
        int retry_count = 3;

        while (retry_count--) {
            adc_value = spiTransfer16(SPI_CHANNEL, 0x0000 | ADC_CHANNEL) & 0x0FFF;
            if (adc_value != 0xFFFF) break;
        }

        if (adc_value == 0xFFFF) {
