        fprintf(log_file, "%s,%f,%d\n", buffer, co2_ppm, gpioRead(FAN_GPIO));

        // Activate fan if CO2 level exceeds 700 ppm
        if (co2_ppm > 700) {
            gpioWrite(FAN_GPIO, PI_HIGH);
        } else {
            gpioWrite(FAN_GPIO, PI_LOW);
        }

        sleep(SAMPLE_INTERVAL);
    }

    // Clean up
    fclose(log_file);
    spiClose(spi_fd);
    gpioTerminate();

    return EXIT_SUCCESS;
}

#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <unistd.h>
#include <signal.h>
#include <time.h>
#include <gpiod.h>
#include <sys/ioctl.h>
#include <linux/spi/spidev.h>

#define SPI_CHANNEL 0
#define SPI_SPEED 1000000
#define PROXIMITY_THRESHOLD 20
#define DEBOUNCE_DELAY 1
#define POLLING_INTERVAL 100
#define RELAY_PIN 17
#define SENSOR_PIN 18

static int spi_fd, relay_fd, proximity_fd;
static FILE *log_file;
static struct timespec last_trigger_time;

static void cleanup() {
    if (spi_fd >= 0) close(spi_fd);
    if (relay_fd >= 0) gpiod_close(relay_fd);
    if (proximity_fd >= 0) gpiod_close(proximity_fd);
    if (log_file) fclose(log_file);
}

static void sigint_handler(int signum) {
    cleanup();
    exit(EXIT_SUCCESS);
}

static int open_spi() {
    int ret;
    struct spi_ioc_transfer xfer = {
        .tx_buf = 0,
        .rx_buf = 0,
        .len = 3,
        .speed_hz = SPI_SPEED,
        .bits_per_word = 8,
    };

    spi_fd = open("/dev/spidev0.0", O_RDWR);
    if (spi_fd < 0) return -1;

    ret = ioctl(spi_fd, SPI_IOC_MESSAGE(1), &xfer);
    if (ret < 0) {
        close(spi_fd);
        return -1;
    }

    return 0;
}

static int read_adc() {
    unsigned char tx[3] = {0x01, 0x80, 0x00};
    unsigned char rx[3];
    int ret;

    ret = write(spi_fd, tx, 3);
    if (ret != 3) return -1;

    ret = read(spi_fd, rx, 3);
    if (ret != 3) return -1;

    return (rx[1] << 8) | rx[2];
}

static int open_relay() {
    relay_fd = gpiod_open_line("gpiochip0", RELAY_PIN, GPIOD_LINE_REQUEST_DIRECTION_OUTPUT);
    if (!relay_fd) return -1;

    return 0;
}

static int open_proximity() {
    proximity_fd = gpiod_open_line("gpiochip0", SENSOR_PIN, GPIOD_LINE_REQUEST_DIRECTION_INPUT);
    if (!proximity_fd) return -1;

    return 0;
}

static int check_proximity() {
    struct gpiod_line_event event;
    int ret;

    ret = gpiod_line_event_read(proximity_fd, &event);
    if (ret < 0) return -1;

    return event.level;
}

static int should_trigger() {
    struct timespec now, diff;
    int proximity;

    clock_gettime(CLOCK_MONOTONIC, &now);
    if (clock_gettime(CLOCK_MONOTONIC, &now) == -1) return -1;

    if (now.tv_sec - last_trigger_time.tv_sec < DEBOUNCE_DELAY) return 0;

    proximity = check_proximity();
    if (proximity < 0) return -1;

    if (proximity < PROXIMITY_THRESHOLD) {
        clock_gettime(CLOCK_MONOTONIC, &last_trigger_time);
        return 1;
    }

    return 0;
}

static int trigger_relay() {
    int ret;

    ret = gpiod_set_line_value(relay_fd, 1);
    if (ret < 0) return -1;

    ret = gpiod_set_line_value(relay_fd, 0);
    if (ret < 0) return -1;

    return 0;
}

static int log_event() {
    time_t rawtime;
    struct tm *timeinfo;
    char buffer[80];

    time(&rawtime);
    timeinfo = localtime(&rawtime);

    strftime(buffer, sizeof(buffer), "%Y-%m-%d %H:%M:%S", timeinfo);
    fprintf(log_file, "%s: Door opened\n", buffer);

    return 0;
}

int main() {
    int ret;

    signal(SIGINT, sigint_handler);

    ret = open_spi();
    if (ret < 0) {
        fprintf(stderr, "Failed to open SPI\n");
        return EXIT_FAILURE;
    }

    ret = open_relay();
    if (ret < 0) {
        fprintf(stderr, "Failed to open relay\n");
        return EXIT_FAILURE;
    }

    ret = open_proximity();
    if (ret < 0) {
        fprintf(stderr, "Failed to open proximity sensor\n");
        return EXIT_FAILURE;
    }

    log_file = fopen("door_events.log", "a");
    if (!log_file) {
        fprintf(stderr, "Failed to open log file\n");
        return EXIT_FAILURE;
    }

    while (1) {
        ret = should_trigger();
        if (ret < 0) {
            fprintf(stderr, "Failed to check proximity\n");
            break;
        }

        if (ret > 0) {
            ret = trigger_relay();
            if (ret < 0) {
                fprintf(stderr, "Failed to trigger relay\n");
                break;
            }

            ret = log_event();
            if (ret < 0) {
                fprintf(stderr, "Failed to log event\n");
                break;
            }
        }

        usleep(POLLING_INTERVAL * 1000);
    }

    cleanup();
    return EXIT_FAILURE;
}

#include <stdio.h>
