#define LOG_FILE "irrigation.log"
#define PWM_PIN 17
#define SPI_CHANNEL 0
#define SPI_SPEED 1000000
#define ADC_CHANNELS 3
#define PWM_FREQ 100
#define PWM_RANGE 100

void log_data(const char *data) {
    FILE *file = fopen(LOG_FILE, "a");
    if (file) {
        fprintf(file, "%s\n", data);
        fclose(file);
    }
}

void signal_handler(int signum) {
    gpioPWM(PWM_PIN, 0);
    gpioTerminate();
    exit(signum);
}

int main() {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialization failed\n");
        return EXIT_FAILURE;
    }

    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    int spi = spiOpen(SPI_CHANNEL, SPI_SPEED, 0);
    if (spi < 0) {
        fprintf(stderr, "SPI open failed\n");
        gpioTerminate();
        return EXIT_FAILURE;
    }

    FILE *log_file = fopen(LOG_FILE, "w");
    if (!log_file) {
        fprintf(stderr, "Log file open failed\n");
        spiClose(spi);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    gpioSetPWMfrequency(PWM_PIN, PWM_FREQ);
    gpioSetPWMrange(PWM_PIN, PWM_RANGE);

    uint8_t buffer[3] = {0x01, 0x80, 0x00}; // MCP3008 single-ended command bytes
    uint16_t adc_values[ADC_CHANNELS];
    int total = 0;
    int count = 0;

    while (1) {
        for (int i = 0; i < ADC_CHANNELS; i++) {
            buffer[1] = 0x80 | (i << 4);
            if (spiXfer(spi, buffer, buffer, 3) != 3) {
                fprintf(stderr, "SPI transfer failed\n");
                continue;
            }
            adc_values[i] = (buffer[1] << 8) | buffer[2];
            total += adc_values[i];
            count++;
        }

        if (count > 0) {
            int average = total / count;
            int duty_cycle = PWM_RANGE - (PWM_RANGE * average) / 1023;
            gpioPWM(PWM_PIN, duty_cycle);

            char log_entry[256];
            time_t now = time(NULL);
            strftime(log_entry, sizeof(log_entry), "%Y-%m-%d %H:%M:%S", localtime(&now));
            sprintf(log_entry + strlen(log_entry), " ADC: %d %d %d Avg: %d Val: %d", adc_values[0], adc_values[1], adc_values[2], average, duty_cycle);
            log_data(log_entry);
        }

        total = 0;
        count = 0;
        sleep(5);
    }

    fclose(log_file);
    spiClose(spi);
    gpioTerminate();
    return EXIT_SUCCESS;
}

