#define SPI_CHANNEL 0
#define SPI_SPEED 1000000
#define SPI_MODE 0
#define SPI_CS 8
#define SPI_MAX_RETRIES 5

volatile sig_atomic_t stop = 0;

void signal_handler(int signum) {
    stop = 1;
}

int main() {
    FILE *file;
    int spi_fd, adc_value, moisture_percentage, retry_count = 0;
    uint8_t tx_buffer[3] = {0x01, 0x80, 0x00}; // Start bit, single-ended mode, channel 0

    if ((spi_fd = spiOpen(SPI_CHANNEL, SPI_SPEED, SPI_MODE)) < 0) {
        printf("Failed to open SPI channel\n");
        return EXIT_FAILURE;
    }

    if ((file = fopen("soil_data.txt", "w")) == NULL) {
        printf("Failed to open soil_data.txt\n");
        spiClose(spi_fd);
        return EXIT_FAILURE;
    }

    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    while (!stop) {
        retry_count = 0;
        while (retry_count < SPI_MAX_RETRIES) {
            if (spiXfer(spi_fd, tx_buffer, NULL, 3) < 0) {
                printf("SPI communication failed, retrying...\n");
                retry_count++;
                usleep(1000 * 1000 * (1 << retry_count)); // Exponential backoff
            } else {
                break;
            }
        }

        if (retry_count >= SPI_MAX_RETRIES) {
            printf("SPI communication failed persistently, skipping reading\n");
            fprintf(file, "Error: SPI communication failed\n");
        } else {
            adc_value = (tx_buffer[1] << 8) | tx_buffer[2];
            if (adc_value < 0 || adc_value > 1023) {
                printf("Invalid ADC value: %d\n", adc_value);
                fprintf(file, "Error: Invalid ADC value\n");
            } else {
                moisture_percentage = (adc_value * 100) / 1023;
                time_t now = time(NULL);
                struct tm *t = localtime(&now);
                char timestamp[20];
                strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", t);
                fprintf(file, "%s Soil Moisture: %d%%\n", timestamp, moisture_percentage);
                printf("%s Soil Moisture: %d%%\n", timestamp, moisture_percentage);
            }
        }

        fclose(file);
        file = fopen("soil_data.txt", "a");
        sleep(5);
    }

    fclose(file);
    spiClose(spi_fd);
    return EXIT_SUCCESS;
}

#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <stdbool.h>
#include <string.h>
#include <unistd.h>
#include <signal.h>
#include <libgpiod.h>
#include <sys/stat.h>
#include <sys/types.h>
#include <sys/wait.h>
#include <sys/ioctl.h>
#include <sys/mman.h>
#include <fcntl.h>
#include <linux/spi/spidev.h>

#define TRIG_PIN 23
#define ECHO_PIN 24
#define VOLUME_PIN 18
#define LDR_PIN 0
#define SPI_DEVICE "/dev/spidev0.0"
#define PWM_DEVICE "/sys/class/pwm/pwm0"

#define MIN_FREQ 220
#define MAX_FREQ 880

volatile sig_atomic_t running = true;

void handle_sigint(int signum) {
    running = false;
}

int main() {
    struct gpiod_chip *chip;
    struct gpiod_line_request request;
    struct gpiod_line *trig_line, *echo_line, *volume_line;
    int spi_fd, pwm_fd;
    uint8_t tx[3] = {0x01, 0x80, 0x00};
    uint8_t rx[3];
    uint32_t distance, ldr_value;
    float freq, volume;
    char buf[256];

    chip = gpiod_chip_open("/dev/gpiochip0");
    trig_line = gpiod_chip_get_line(chip, TRIG_PIN);
    echo_line = gpiod_chip_get_line(chip, ECHO_PIN);
    volume_line = gpiod_chip_get_line(chip, VOLUME_PIN);

    gpiod_line_request_input(trig_line, "TRIG");
    gpiod_line_request_input(echo_line, "ECHO");
    gpiod_line_request_output(volume_line, "VOLUME", 0);

    spi_fd = open(SPI_DEVICE, O_RDWR);
    pwm_fd = open(PWM_DEVICE, O_RDWR);

    signal(SIGINT, handle_sigint);

    while (running) {
        // Trigger the sensor
        gpiod_line_set_value(trig_line, 1);
        usleep(10);
        gpiod_line_set_value(trig_line, 0);

        // Wait for the echo
        while (gpiod_line_get_value(echo_line) == 0);
        struct timespec start, end;
        clock_gettime(CLOCK_MONOTONIC, &start);
        while (gpiod_line_get_value(echo_line) == 1);
        clock_gettime(CLOCK_MONOTONIC, &end);

        // Calculate the distance
        distance = (end.tv_sec - start.tv_sec) * 1000000 + (end.tv_nsec - start.tv_nsec) / 1000;
        distance /= 58;

        // Map the distance to a frequency
        freq = MIN_FREQ + (MAX_FREQ - MIN_FREQ) * (distance / 100.0);

        // Write the frequency to the PWM
        snprintf(buf, sizeof(buf), "frequency=%.0f\n", freq);
        write(pwm_fd, buf, strlen(buf));

        // Read the LDR value
        ioctl(spi_fd, SPI_IOC_MESSAGE(1), &tx);
        read(spi_fd, rx, 3);
        ldr_value = (rx[1] << 8) | rx[2];

        // Map the LDR value to a volume
        volume = (float)ldr_value / 4095.0;

        // Write the volume to the PWM
        snprintf(buf, sizeof(buf), "duty_cycle=%.0f\n", volume * 100.0);
        write(pwm_fd, buf, strlen(buf));
    }

    gpiod_line_release(trig_line);
    gpiod_line_release(echo_line);
    gpiod_line_release(volume_line);
    gpiod_chip_close(chip);
    close(spi_fd);
    close(pwm_fd);

    return 0;
}

