#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <pigpio.h>
#include <spi.h>

#define FAN_PIN 18
#define AQI_THRESHOLD 100
#define SPI_CHANNEL 0
#define SPI_SPEED 1000000
#define SPI_MODE 0
#define SPI_RETRIES 3
#define LOG_FILE "air_quality.log"

static int spi_fd = -1;
static FILE *log_fd = NULL;
static int fan_on = 0;

void log_aqi(int aqi) {
    time_t now = time(NULL);
    struct tm *t = localtime(&now);
    fprintf(log_fd, "%d-%02d-%02d %02d:%02d:%02d AQI: %d\n", 
            t->tm_year + 1900, t->tm_mon + 1, t->tm_mday, 
            t->tm_hour, t->tm_min, t->tm_sec, aqi);
    fflush(log_fd);
}

void fan_control(int aqi) {
    if (aqi > AQI_THRESHOLD && !fan_on) {
        gpioWrite(FAN_PIN, 1);
        fan_on = 1;
    } else if (aqi <= AQI_THRESHOLD && fan_on) {
        gpioWrite(FAN_PIN, 0);
        fan_on = 0;
    }
}

void shutdown(int signum) {
    if (fan_on) {
        gpioWrite(FAN_PIN, 0);
    }
    if (spi_fd != -1) {
        spiClose(spi_fd);
    }
    if (log_fd != NULL) {
        fclose(log_fd);
    }
    gpioTerminate();
    exit(signum);
}

int main() {
    signal(SIGINT, shutdown);
    signal(SIGTERM, shutdown);

    if (gpioInitialise() < 0) {
        fprintf(stderr, "Failed to initialize pigpio\n");
        return EXIT_FAILURE;
    }

    if ((spi_fd = spiOpen(SPI_CHANNEL, SPI_SPEED, SPI_MODE)) < 0) {
        fprintf(stderr, "Failed to open SPI channel\n");
        gpioTerminate();
        return EXIT_FAILURE;
    }

    if ((log_fd = fopen(LOG_FILE, "a")) == NULL) {
        fprintf(stderr, "Failed to open log file\n");
        spiClose(spi_fd);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    gpioSetMode(FAN_PIN, PI_OUTPUT);
    gpioWrite(FAN_PIN, 0);

    while (1) {
        int aqi = 0;
        int retry = 0;
        while (retry++ < SPI_RETRIES) {
            uint8_t tx[] = {0x01, 0x08, 0x00};
            uint8_t rx[3];
            if (spiXfer(spi_fd, tx, rx, sizeof(tx)) == sizeof(tx)) {
                int value = (rx[1] << 8) | rx[2];
                aqi = (value * 500) / 1023;
                break;
            }
            sleep(1);
        }
        if (retry == SPI_RETRIES) {
            fprintf(stderr, "Failed to read AQI, re-initializing SPI\n");
            spiClose(spi_fd);
            if ((spi_fd = spiOpen(SPI_CHANNEL, SPI_SPEED, SPI_MODE)) < 0) {
                fprintf(stderr, "Failed to re-initialize SPI\n");
                shutdown(EXIT_FAILURE);
            }
            continue;
        }
        log_aqi(aqi);
        fan_control(aqi);
        sleep(5);
    }

    shutdown(EXIT_SUCCESS);
}

#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <string.h>
#include <unistd.h>
#include <fcntl.h>
#include <sys/ioctl.h>
#include <linux/spi/spidev.h>
#include <gpiod.h>

#define SPI_CHANNEL 0
#define SPI_SPEED 1000000
#define SPI_MODE 0
#define SPI_BITS_PER_WORD 8
#define ADC_CHANNEL 0
#define ADC_CONVERSION 0x01
#define ADC_CHANNEL_SELECT 0x80
#define ADC_RESULT_MASK 0x03
#define ADC_RESULT_SHIFT 8
#define LOG_FILE "alcohol_log.txt"

int spi_fd, gpio_fd;
struct spi_ioc_transfer spi_xfer;
uint8_t tx[3] = {ADC_CONVERSION, (ADC_CHANNEL << 4) | ADC_CHANNEL_SELECT, 0x00};
uint8_t rx[3];

void close_spi() {
    close(spi_fd);
}

void close_gpio() {
    gpiochip_close(gpio_fd);
}

void handle_sigint(int signum) {
    close_spi();
    close_gpio();
    exit(0);
}

int main() {
    struct gpiod_chip *chip;
    struct gpiod_line_request request;
    struct timespec ts;
    int adc_value, ppm, retry_count;

    // Open SPI device
    spi_fd = open("/dev/spidev0.0", O_RDWR);
    if (spi_fd < 0) {
        perror("Failed to open SPI device");
        return -1;
    }

    // Set SPI parameters
    spi_xfer.tx_buf = (unsigned long)tx;
    spi_xfer.rx_buf = (unsigned long)rx;
    spi_xfer.len = sizeof(tx);
    spi_xfer.delay_usecs = 0;
    spi_xfer.speed_hz = SPI_SPEED;
    spi_xfer.bits_per_word = SPI_BITS_PER_WORD;
    spi_xfer.cs_change = 0;
    spi_xfer.pad = 0;

    // Set SPI mode
    if (ioctl(spi_fd, SPI_IOC_WR_MODE, &SPI_MODE) < 0) {
        perror("Failed to set SPI mode");
        close_spi();
        return -1;
    }

    // Open GPIO chip
    gpio_fd = gpiochip_open_by_name("gpio");
    if (gpio_fd < 0) {
        perror("Failed to open GPIO chip");
        close_spi();
        return -1;
    }

    // Request GPIO line
    memset(&request, 0, sizeof(request));
    request.consumer = "alcohol_sensor";
    request.line_offset = 8;
    request.flags = GPIO_LINE_REQUEST_DIRECTION_INPUT;
    if (gpiod_chip_line_request(chip, &request) < 0) {
        perror("Failed to request GPIO line");
        close_spi();
        close_gpio();
        return -1;
    }

    // Set up signal handler for graceful shutdown
    signal(SIGINT, handle_sigint);
    signal(SIGTERM, handle_sigint);

    // Main loop
    while (1) {
        // Read ADC value
        retry_count = 0;
        while (retry_count < 3) {
            if (ioctl(spi_fd, SPI_IOC_MESSAGE(1), &spi_xfer) < 0) {
                perror("Failed to read ADC value");
                retry_count++;
                usleep(100000);
                continue;
            }
            adc_value = ((rx[1] & ADC_RESULT_MASK) << ADC_RESULT_SHIFT) | rx[2];
            break;
        }
        if (retry_count == 3) {
            printf("Failed to read ADC value after 3 retries\n");
            continue;
        }

        // Convert ADC value to PPM
        ppm = (adc_value * 0.5) - 10.0;

        // Log reading
        ts.tv_sec = time(NULL);
        ts.tv_nsec = 0;
        printf("%ld.%09ld %d PPM\n", ts.tv_sec, ts.tv_nsec, ppm);
        FILE *log_file = fopen(LOG_FILE, "a");
        if (log_file) {
            fprintf(log_file, "%ld.%09ld %d PPM\n", ts.tv_sec, ts.tv_nsec, ppm);
            fclose(log_file);
        }

        // Classify reading
        if (ppm > 50) {
            printf("Alcohol detected! Limit exceeded.\n");
        } else if (ppm < 20) {
            printf("Sobriety confirmed.\n");
        } else {
            printf("Alcohol level within acceptable range.\n");
        }

        // Wait for 1 second
        sleep(1);
    }

    // Clean up
    close_spi();
    close_gpio();
    return 0;
}

