    signal(SIGINT, handle_sigint);
    signal(SIGTERM, handle_sigint);

    pump_pin = PUMP_PIN;
    spi_channel = SPI_CHANNEL;
    spi_speed = SPI_SPEED;
    spi_mode = SPI_MODE;
    soil_moisture_threshold = SOIL_MOISTURE_THRESHOLD;

    if ((log_file = fopen(LOG_FILE, "a")) == NULL) {
        fprintf(stderr, "Failed to open log file\n");
        gpioTerminate();
        return 1;
    }

    if (gpioSetMode(pump_pin, PI_OUTPUT) < 0) {
        fprintf(stderr, "Failed to set pump pin mode\n");
        fclose(log_file);
        gpioTerminate();
        return 1;
    }

    if (gpioSetPullUpDown(pump_pin, PI_PUD_OFF) < 0) {
        fprintf(stderr, "Failed to set pump pin pull-up/down\n");
        fclose(log_file);
        gpioTerminate();
        return 1;
    }

    if (spiOpen(spi_channel, spi_speed, spi_mode) < 0) {
        fprintf(stderr, "Failed to open SPI channel\n");
        fclose(log_file);
        gpioTerminate();
        return 1;
    }

    while (1) {
        uint16_t soil_moisture = spiRead(spi_channel);
        if (soil_moisture < 0) {
            log_message("Failed to read soil moisture");
            continue;
        }

        log_message("Soil moisture reading");
        if (soil_moisture < soil_moisture_threshold) {
            pump_on();
        } else {
            pump_off();
        }

        sleep(60);
    }

    fclose(log_file);
    gpioTerminate();
    return 0;
}

#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <pigpio.h>
#include <math.h>

#define MOTOR1_ENABLE 18
#define MOTOR1_DIRECTION 23
#define MOTOR2_ENABLE 24
#define MOTOR2_DIRECTION 25
#define SPI_CHANNEL 0
#define MCP3008_CS 8
#define POT1_CHANNEL 0
#define POT2_CHANNEL 1
#define MIN_SPEED 50
#define MAX_SPEED 255

void cleanup() {
    gpioTerminate();
}

int main() {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return EXIT_FAILURE;
    }

    atexit(cleanup);

    signal(SIGINT, cleanup);
    signal(SIGTERM, cleanup);

    int pot1 = spiOpen(SPI_CHANNEL, 1000000, 0);
    if (pot1 < 0) {
        fprintf(stderr, "Failed to open SPI channel for potentiometer 1\n");
        return EXIT_FAILURE;
    }

    int pot2 = spiOpen(SPI_CHANNEL, 1000000, 0);
    if (pot2 < 0) {
        fprintf(stderr, "Failed to open SPI channel for potentiometer 2\n");
        return EXIT_FAILURE;
    }

    gpioSetMode(MOTOR1_ENABLE, PI_OUTPUT);
    gpioSetMode(MOTOR1_DIRECTION, PI_OUTPUT);
    gpioSetMode(MOTOR2_ENABLE, PI_OUTPUT);
    gpioSetMode(MOTOR2_DIRECTION, PI_OUTPUT);

    while (1) {
        uint16_t pot1_value = spiTransfer(pot1, 0x0000, 0x0000);
        uint16_t pot2_value = spiTransfer(pot2, 0x0000, 0x0000);

        float speed_factor1 = log10((float)pot1_value / 1023.0) * (MAX_SPEED - MIN_SPEED) + MIN_SPEED;
        float speed_factor2 = log10((float)pot2_value / 1023.0) * (MAX_SPEED - MIN_SPEED) + MIN_SPEED;

        gpioPWM(MOTOR1_ENABLE, speed_factor1);
        gpioWrite(MOTOR1_DIRECTION, 1);

        gpioPWM(MOTOR2_ENABLE, speed_factor2);
        gpioWrite(MOTOR2_DIRECTION, 0);

        sleep(2);

        gpioPWM(MOTOR1_ENABLE, MIN_SPEED);
        gpioPWM(MOTOR2_ENABLE, MIN_SPEED);

        sleep(5);
    }

    return EXIT_SUCCESS;
}

#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <signal.h>
#include <pigpio.h>

#define LED_PIN 17
#define SPI_CHANNEL 0
#define SPI_SPEED 500000
#define ADC_CHANNEL 0
#define DEBOUNCE_TIME 10

volatile sig_atomic_t stop = 0;

void signal_handler(int signum) {
    stop = 1;
}

int main() {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Failed to initialize pigpio\n");
        return EXIT_FAILURE;
    }

    if (signal(SIGINT, signal_handler) == SIG_ERR) {
        fprintf(stderr, "Failed to set signal handler\n");
        gpioTerminate();
        return EXIT_FAILURE;
    }

    if (gpioSetMode(LED_PIN, PI_OUTPUT) < 0) {
        fprintf(stderr, "Failed to set LED pin mode\n");
        gpioTerminate();
        return EXIT_FAILURE;
    }

    int spi_handle = spiOpen(SPI_CHANNEL, SPI_SPEED, 0);
    if (spi_handle < 0) {
        fprintf(stderr, "Failed to open SPI channel\n");
        gpioTerminate();
        return EXIT_FAILURE;
    }

    int16_t samples[2] = {0, 0};
    int16_t ambient_level = 0;
    int16_t noise_threshold = 0;

    // Calibrate for 5 seconds
    for (int i = 0; i < 50; ++i) {
        if (stop) {
            break;
        }
        sleep(100);
        ambient_level += spiXfer(spi_handle, samples, 2);
    }
    ambient_level /= 50;
    noise_threshold = ambient_level * 1.1;

    int debounce_counter = 0;
    while (!stop) {
        sleep(10);
        int16_t current_level = spiXfer(spi_handle, samples, 2);
        if (current_level > noise_threshold) {
            if (debounce_counter >= DEBOUNCE_TIME) {
                gpioWrite(LED_PIN, PI_HIGH);
                debounce_counter = 0;
            } else {
                debounce_counter++;
            }
        } else {
            debounce_counter = 0;
            gpioWrite(LED_PIN, PI_LOW);
        }
    }

    spiClose(spi_handle);
    gpioTerminate();
    return EXIT_SUCCESS;
}

#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <pigpio.h>
#include <unistd.h>

#define SPI_CHANNEL 0
#define SPI_SPEED 1000000
#define ADC_CHANNEL 0
#define LOG_FILE "airflow_log.txt"
#define SLPM_MIN 0
#define SLPM_MAX 200
#define VOLT_MIN 0.5
#define VOLT_MAX 4.5

volatile sig_atomic_t stop = 0;

void signal_handler(int signum) {
    stop = 1;
}

int main() {
    FILE *log_file;
    int spi_handle;
    float voltage, airflow;
    time_t rawtime;
    struct tm *timeinfo;
    char buffer[80];

    if (signal(SIGINT, signal_handler) == SIG_ERR) {
        printf("ERROR: Could not set signal handler\n");
        return EXIT_FAILURE;
    }

    if ((spi_handle = spiOpen(0, SPI_SPEED, 0)) < 0) {
        printf("ERROR: Failed to open SPI\n");
        return EXIT_FAILURE;
    }

    if ((log_file = fopen(LOG_FILE, "a")) == NULL) {
        printf("ERROR: Failed to open log file\n");
        spiClose(spi_handle);
        return EXIT_FAILURE;
    }

    while (!stop) {
        if ((voltage = spiRead(spi_handle)) < 0) {
            printf("ERROR: ADC read failed\n");
            continue;
        }

        voltage = voltage * (VOLT_MAX - VOLT_MIN) + VOLT_MIN;
        airflow = (voltage - VOLT_MIN) / (VOLT_MAX - VOLT_MIN) * (SLPM_MAX - SLPM_MIN) + SLPM_MIN;

        time(&rawtime);
        timeinfo = localtime(&rawtime);
        strftime(buffer, sizeof(buffer), "%Y-%m-%d %H:%M:%S", timeinfo);

        fprintf(log_file, "%s: %.2f SLPM\n", buffer, airflow);
        fflush(log_file);
    }

    fclose(log_file);
    spiClose(spi_handle);
    gpioTerminate();

    return EXIT_SUCCESS;
}

#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <string.h>
#include <unistd.h>
#include <fcntl.h>
#include <sys/ioctl.h>
#include <sys/stat.h>
#include <sys/types.h>
#include <sys/wait.h>
#include <sys/time.h>
#include <sys/timex.h>
#include <time.h>
#include <signal.h>
#include <errno.h>
#include <gpiod.h>

#define SPI_DEV "/dev/spidev0.0"
#define SPI_MODE 0
#define SPI_BITS_PER_WORD 8
#define SPI_MAX_SPEED 1000000
#define SPI_CS_GPIO 8
#define SPI_MOSI_GPIO 10
#define SPI_MISO_GPIO 9
#define SPI_SCLK_GPIO 11
#define SAMPLE_PERIOD_NS 1000000
#define ADC_CHANNEL 0
#define ADC_CONFIG_BYTE (0x08 | ADC_CHANNEL << 4)
#define ADC_START_BIT 0x01
#define LOG_FILE_NAME "audio_log.txt"

static int spi_fd = -1;
static int log_fd = -1;
static struct gpiod_chip *spi_chip = NULL;
static struct gpiod_line *spi_line = NULL;

static void cleanup(int exit_code) {
    if (spi_line) {
        gpiod_line_release(spi_line);
    }
    if (spi_chip) {
        gpiod_chip_close(spi_chip);
    }
    if (spi_fd >= 0) {
        close(spi_fd);
    }
    if (log_fd >= 0) {
        close(log_fd);
    }
    exit(exit_code);
}

static void handle_signal(int signum) {
    cleanup(EXIT_FAILURE);
}

static void request_spi_gpios() {
    spi_chip = gpiod_chip_open_by_name("gpiochip0");
    if (!spi_chip) {
        fprintf(stderr, "Failed to open GPIO chip\n");
        cleanup(EXIT_FAILURE);
    }

    spi_line = gpiod_chip_get_line(spi_chip, SPI_CS_GPIO);
    if (!spi_line) {
        fprintf(stderr, "Failed to get SPI CS GPIO line\n");
        cleanup(EXIT_FAILURE);
    }

    if (gpiod_line_request_output(spi_line, "spi_cs", 1) < 0) {
        fprintf(stderr, "Failed to request SPI CS GPIO line as output\n");
        cleanup(EXIT_FAILURE);
    }
}

static void open_spi() {
    spi_fd = open(SPI_DEV, O_RDWR);
    if (spi_fd < 0) {
        fprintf(stderr, "Failed to open SPI device\n");
        cleanup(EXIT_FAILURE);
    }

    uint8_t mode = SPI_MODE;
    if (ioctl(spi_fd, SPI_IOC_WR_MODE, &mode) < 0) {
        fprintf(stderr, "Failed to set SPI mode\n");
        cleanup(EXIT_FAILURE);
    }

    uint8_t bits_per_word = SPI_BITS_PER_WORD;
    if (ioctl(spi_fd, SPI_IOC_WR_BITS_PER_WORD, &bits_per_word) < 0) {
        fprintf(stderr, "Failed to set SPI bits per word\n");
        cleanup(EXIT_FAILURE);
    }

    uint32_t max_speed_hz = SPI_MAX_SPEED;
    if (ioctl(spi_fd, SPI_IOC_WR_MAX_SPEED_HZ, &max_speed_hz) < 0) {
        fprintf(stderr, "Failed to set SPI max speed\n");
        cleanup(EXIT_FAILURE);
    }
}

static void open_log() {
    log_fd = open(LOG_FILE_NAME, O_WRONLY | O_CREAT | O_TRUNC, 0644);
    if (log_fd < 0) {
        fprintf(stderr, "Failed to open log file\n");
        cleanup(EXIT_FAILURE);
    }
}

static void write_log(uint64_t timestamp_ns, uint16_t raw_adc_value) {
    char buffer[21]; // "timestamp_ns|value\n\0"
    int bytes_written = snprintf(buffer, sizeof(buffer), "%llu|%u\n", timestamp_ns, raw_adc_value);
    if (bytes_written < 0 || bytes_written >= sizeof(buffer)) {
        fprintf(stderr, "Failed to format log entry\n");
        cleanup(EXIT_FAILURE);
    }

    if (write(log_fd, buffer, bytes_written) < 0) {
        fprintf(stderr, "Failed to write log entry\n");
        cleanup(EXIT_FAILURE);
    }
}

static void sample_adc() {
    struct timespec sleep_time = {0, SAMPLE_PERIOD_NS};
    uint8_t tx_buf[3] = {ADC_START_BIT, ADC_CONFIG_BYTE, 0x00};
    uint8_t rx_buf[3] = {0};

    while (1) {
        clock_nanosleep(CLOCK_MONOTONIC_RAW, 0, &sleep_time, NULL);

        if (gpiod_line_set_value(spi_line, 0) < 0) {
            fprintf(stderr, "Failed to set SPI CS GPIO line low\n");
            cleanup(EXIT_FAILURE);
        }

        if (write(spi_fd, tx_buf, sizeof(tx_buf)) < 0) {
            fprintf(stderr, "Failed to write to SPI device\n");
            cleanup(EXIT_FAILURE);
        }

        if (read(spi_fd, rx_buf, sizeof(rx_buf)) < 0) {
            fprintf(stderr, "Failed to read from SPI device\n");
            cleanup(EXIT_FAILURE);
        }

        if (gpiod_line_set_value(spi_line, 1) < 0) {
            fprintf(stderr, "Failed to set SPI CS GPIO line high\n");
            cleanup(EXIT_FAILURE);
        }

        uint16_t raw_adc_value = (rx_buf[1] << 8) | rx_buf[2];
        struct timespec now;
        clock_gettime(CLOCK_MONOTONIC_RAW, &now);
        uint64_t timestamp_ns = (uint64_t)now.tv_sec * 1000000000 + now.tv_nsec;

        write_log(timestamp_ns, raw_adc_value);
    }
}

int main() {
    request_spi_gpios();
    open_spi();
    open_log();

    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = handle_signal;
    sigaction(SIGINT, &sa, NULL);
    sigaction(SIGTERM, &sa, NULL);

    sample_adc();

    cleanup(EXIT_SUCCESS);
}

#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <pigpio.h>
#include <errno.h>

#define SPI_CHANNEL 0
#define SPI_SPEED 1000000
#define VREF 3.3
#define ADC_MAX 1023
#define PPM_PER_VOLT 1000.0

volatile sig_atomic_t stop;

void signal_handler(int signum) {
    stop = 1;
}

int main() {
    FILE *log_file;
    int spi_fd, adc_value;
    float voltage, ppm;
    struct timespec ts;

    if ((spi_fd = spiOpen(0, SPI_CHANNEL, SPI_SPEED)) < 0) {
        fprintf(stderr, "Failed to open SPI: %s\n", strerror(errno));
        return EXIT_FAILURE;
    }

    if ((log_file = fopen("gas_log.txt", "a")) == NULL) {
        fprintf(stderr, "Failed to open log file: %s\n", strerror(errno));
        spiClose(spi_fd);
        return EXIT_FAILURE;
    }

    signal(SIGINT, signal_handler);

    while (!stop) {
        for (int i = 0; i < 10; ++i) {
            if ((adc_value = spiTransfer(spi_fd, 0x01, 0x00)) < 0) {
                fprintf(stderr, "SPI transfer failed: %s\n", strerror(errno));
                usleep(100000);
                continue;
            }
            break;
        }

        if (adc_value < 0) {
            fprintf(stderr, "Failed to read ADC value\n");
            continue;
        }

        voltage = (float)adc_value / ADC_MAX * VREF;
        ppm = voltage * PPM_PER_VOLT;

        clock_gettime(CLOCK_REALTIME, &ts);
        fprintf(log_file, "%ld.%09ld, %.2f V, %.2f ppm\n", ts.tv_sec, ts.tv_nsec, voltage, ppm);
        fflush(log_file);

        printf("Voltage: %.2f V, PPM: %.2f ppm\n", voltage, ppm);
        sleep(1);
    }

    fclose(log_file);
    spiClose(spi_fd);
    gpioTerminate();

    return EXIT_SUCCESS;
}

#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <signal.h>
#include <pigpio.h>
#include <math.h>

#define SPI_CHANNEL 0
#define SPI_SPEED 500000
#define SPI_MODE 0
#define SPI_BITS 8
#define SPI_LSBFIRST 0
#define SPI_CS 8
#define SPI_MOSI 10
#define SPI_MISO 9
#define SPI_SCLK 11
#define ADC_CHANNELS 3
#define ACCEL_SENSITIVITY 0.001 // 300 mV/g
#define ACCEL_BIAS 1.5 // 1.5V
#define KALMAN_Q 0.001
#define KALMAN_R 0.01
#define KALMAN_P 1.0

volatile sig_atomic_t stop = 0;

void signal_handler(int signum) {
    stop = 1;
}

typedef struct {
    float x;
    float y;
    float z;
} Vector3D;

typedef struct {
    float q;
    float r;
    float p;
    float x;
    float y;
} KalmanFilter;

void kalman_init(KalmanFilter *filter, float q, float r, float p) {
    filter->q = q;
    filter->r = r;
    filter->p = p;
    filter->x = 0;
    filter->y = 0;
}

float kalman_update(KalmanFilter *filter, float z) {
    float k = filter->p / (filter->p + filter->r);
    filter->x += k * (z - filter->x);
    filter->p = (1 - k) * filter->p + filter->q;
    return filter->x;
}

int main() {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Failed to initialize pigpio\n");
        return EXIT_FAILURE;
    }

    if (gpioSetMode(SPI_CS, PI_OUTPUT) < 0) {
        fprintf(stderr, "Failed to set CS pin mode\n");
        gpioTerminate();
        return EXIT_FAILURE;
    }

    if (gpioSetMode(SPI_MOSI, PI_OUTPUT) < 0) {
        fprintf(stderr, "Failed to set MOSI pin mode\n");
        gpioTerminate();
        return EXIT_FAILURE;
    }

    if (gpioSetMode(SPI_MISO, PI_INPUT) < 0) {
        fprintf(stderr, "Failed to set MISO pin mode\n");
        gpioTerminate();
        return EXIT_FAILURE;
    }

    if (gpioSetMode(SPI_SCLK, PI_OUTPUT) < 0) {
        fprintf(stderr, "Failed to set SCLK pin mode\n");
        gpioTerminate();
        return EXIT_FAILURE;
    }

    if (gpioSetPullUpDown(SPI_MISO, PI_PUD_UP) < 0) {
        fprintf(stderr, "Failed to set MISO pull-up\n");
        gpioTerminate();
        return EXIT_FAILURE;
    }

    if (spiOpen(SPI_CHANNEL, SPI_SPEED, SPI_MODE | SPI_BITS | SPI_LSBFIRST) < 0) {
        fprintf(stderr, "Failed to open SPI channel\n");
        gpioTerminate();
        return EXIT_FAILURE;
    }

    if (gpioSetSignalFunc(SIGINT, signal_handler) < 0) {
        fprintf(stderr, "Failed to set signal handler for SIGINT\n");
        gpioTerminate();
        return EXIT_FAILURE;
    }

    if (gpioSetSignalFunc(SIGTERM, signal_handler) < 0) {
        fprintf(stderr, "Failed to set signal handler for SIGTERM\n");
        gpioTerminate();
        return EXIT_FAILURE;
    }

    KalmanFilter filter[ADC_CHANNELS];
    for (int i = 0; i < ADC_CHANNELS; i++) {
        kalman_init(&filter[i], KALMAN_Q, KALMAN_R, KALMAN_P);
    }

    Vector3D accel;
    while (!stop) {
        for (int i = 0; i < ADC_CHANNELS; i++) {
            uint8_t tx[3] = {0x01, 0x00, 0x00};
            uint8_t rx[3];
            tx[0] |= (1 << i);
            if (spiXfer(SPI_CHANNEL, tx, rx, sizeof(tx)) < 0) {
                fprintf(stderr, "Failed to read from SPI\n");
                gpioTerminate();
                return EXIT_FAILURE;
            }
            int16_t value = (rx[1] << 8) | rx[2];
            float voltage = value * 3.3 / 1024;
            float acceleration = (voltage - ACCEL_BIAS) / ACCEL_SENSITIVITY;
            accel.x = kalman_update(&filter[0], acceleration);
            accel.y = kalman_update(&filter[1], acceleration);
            accel.z = kalman_update(&filter[2], acceleration);
        }
        printf("X: %f, Y: %f, Z: %f\n", accel.x, accel.y, accel.z);
        sleep(1);
    }

    spiClose(SPI_CHANNEL);
    gpioTerminate();
    return EXIT_SUCCESS;
}

#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <signal.h>
#include <gpiod.h>
#include <unistd.h>
#include <time.h>

#define VCC 3.3
#define V_QUIESCENT 1.65
#define SENSITIVITY 0.025
#define SAMPLE_INTERVAL 0.1
#define LOG_FILE "magnetic_log.txt"
#define MIN_B  -100
#define MAX_B  100

volatile sig_atomic_t stop = 0;

void signal_handler(int signum) {
    stop = 1;
}

float calculate_magnetic_field(int digital_value) {
    float voltage = digital_value * VCC / 1.0;
    float magnetic_field = (voltage - V_QUIESCENT) / SENSITIVITY;
    return magnetic_field;
}

int main() {
    struct gpiod_chip *chip;
    struct gpiod_line *line1, *line2, *line3;
    FILE *log_file;
    struct timespec sleep_time = {0, SAMPLE_INTERVAL * 1e9};

    signal(SIGINT, signal_handler);

    chip = gpiod_chip_open("/dev/gpiochip0");
    if (!chip) {
        fprintf(stderr, "Failed to open GPIO chip\n");
        return EXIT_FAILURE;
    }

    line1 = gpiod_chip_get_line(chip, 4);
    if (!line1) {
        fprintf(stderr, "Failed to get line 4\n");
        gpiod_chip_close(chip);
        return EXIT_FAILURE;
    }

    line2 = gpiod_chip_get_line(chip, 17);
    if (!line2) {
        fprintf(stderr, "Failed to get line 17\n");
        gpiod_chip_close(chip);
        gpiod_line_release(line1);
        return EXIT_FAILURE;
    }

    line3 = gpiod_chip_get_line(chip, 27);
    if (!line3) {
        fprintf(stderr, "Failed to get line 27\n");
        gpiod_chip_close(chip);
        gpiod_line_release(line1);
        gpiod_line_release(line2);
        return EXIT_FAILURE;
    }

    if (gpiod_line_request_input(line1, "DRV5055VA_sensor1") < 0) {
        fprintf(stderr, "Failed to request line 4 as input\n");
        gpiod_chip_close(chip);
        gpiod_line_release(line1);
        gpiod_line_release(line2);
        gpiod_line_release(line3);
        return EXIT_FAILURE;
    }

    if (gpiod_line_request_input(line2, "DRV5055VA_sensor2") < 0) {
        fprintf(stderr, "Failed to request line 17 as input\n");
        gpiod_chip_close(chip);
        gpiod_line_release(line1);
        gpiod_line_release(line2);
        gpiod_line_release(line3);
        return EXIT_FAILURE;
    }

    if (gpiod_line_request_input(line3, "DRV5055VA_sensor3") < 0) {
        fprintf(stderr, "Failed to request line 27 as input\n");
        gpiod_chip_close(chip);
        gpiod_line_release(line1);
        gpiod_line_release(line2);
        gpiod_line_release(line3);
        return EXIT_FAILURE;
    }

    log_file = fopen(LOG_FILE, "w");
    if (!log_file) {
        fprintf(stderr, "Failed to open log file\n");
        gpiod_chip_close(chip);
        gpiod_line_release(line1);
        gpiod_line_release(line2);
        gpiod_line_release(line3);
        return EXIT_FAILURE;
    }

    while (!stop) {
        int value1 = gpiod_line_get_value(line1);
        int value2 = gpiod_line_get_value(line2);
        int value3 = gpiod_line_get_value(line3);

        float magnetic_field1 = calculate_magnetic_field(value1);
        float magnetic_field2 = calculate_magnetic_field(value2);
        float magnetic_field3 = calculate_magnetic_field(value3);

        if (magnetic_field1 < MIN_B || magnetic_field1 > MAX_B ||
            magnetic_field2 < MIN_B || magnetic_field2 > MAX_B ||
            magnetic_field3 < MIN_B || magnetic_field3 > MAX_B) {
            fprintf(stderr, "Warning: magnetic field out of range\n");
        }

        fprintf(log_file, "%.2f,%.2f,%.2f\n", magnetic_field1, magnetic_field2, magnetic_field3);
        fflush(log_file);

        nanosleep(&sleep_time, NULL);
    }

    fclose(log_file);
    gpiod_line_release(line1);
    gpiod_line_release(line2);
    gpiod_line_release(line3);
    gpiod_chip_close(chip);

    return EXIT_SUCCESS;
}

#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <pigpio.h>

#define SPI_CHANNEL 0
#define SPI_SPEED 500000
#define SPI_MODE 0
#define ADC_CHANNEL 0
#define PUMP_GPIO 17
#define WATER_THRESHOLD 30

FILE *log_file;

void log_event(const char *message) {
    time_t now = time(NULL);
    char *time_str = ctime(&now);
    time_str[strcspn(time_str, "\n")] = 0;
    fprintf(log_file, "[%s] %s\n", time_str, message);
    fflush(log_file);
}

void pump_control(int state) {
    gpioWrite(PUMP_GPIO, state);
    log_event(state ? "Pump turned ON" : "Pump turned OFF");
}

void signal_handler(int signum) {
    log_event("Program terminated");
    fclose(log_file);
    gpioTerminate();
    exit(signum);
}

int main() {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialization failed\n");
        return EXIT_FAILURE;
    }

    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    log_file = fopen("watering.log", "a");
    if (!log_file) {
        fprintf(stderr, "Failed to open log file\n");
        gpioTerminate();
        return EXIT_FAILURE;
    }

    log_event("Program started");

    gpioSetMode(PUMP_GPIO, PI_OUTPUT);
    pump_control(0);

    while (1) {
        int adc_value;
        if (spiOpen(SPI_CHANNEL, SPI_SPEED, SPI_MODE) < 0) {
            log_event("Failed to open SPI channel");
            continue;
        }

        adc_value = spiTransfer(SPI_CHANNEL, ADC_CHANNEL << 8);
        spiClose(SPI_CHANNEL);

        if (adc_value < 0) {
            log_event("Failed to read ADC value");
            continue;
        }

        int moisture_percent = (1023 - adc_value) * 100 / 1023;
        log_event(moisture_percent < 0 ? "ADC read error" : "Moisture level: %d%%", moisture_percent);

        if (moisture_percent < 0 || moisture_percent >= WATER_THRESHOLD) {
            pump_control(moisture_percent >= WATER_THRESHOLD);
        }

        sleep(60);
    }

    return EXIT_SUCCESS;
}

#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <unistd.h>
#include <fcntl.h>
#include <signal.h>
#include <sys/ioctl.h>
#include <sys/types.h>
#include <sys/stat.h>
#include <linux/spi/spidev.h>
#include <gpiod.h>

#define SPI_CHANNEL 0
#define SPI_SPEED 1000000
#define SPI_MODE SPI_MODE_0
#define SPI_BITS 8
#define SPI_FILE "/dev/spidev0.0"
#define CSV_FILE "sensor_data.csv"

int spi_fd;
int csv_fd;

void cleanup(int signum) {
    close(spi_fd);
    close(csv_fd);
    exit(signum);
}

int main() {
    struct gpiod_chip *chip;
    struct gpiod_line_request request;
    struct spi_ioc_transfer tr;
    uint8_t tx[3], rx[3];
    int16_t value;
    char buffer[256];

    // Open SPI device
    spi_fd = open(SPI_FILE, O_RDWR);
    if (spi_fd < 0) {
        perror("Failed to open SPI device");
        return -1;
    }

    // Set SPI mode, speed, and bits per word
    uint8_t mode = SPI_MODE;
    uint32_t speed = SPI_SPEED;
    uint8_t bits = SPI_BITS;
    if (ioctl(spi_fd, SPI_IOC_WR_MODE, &mode) < 0 ||
        ioctl(spi_fd, SPI_IOC_WR_MAX_SPEED_HZ, &speed) < 0 ||
        ioctl(spi_fd, SPI_IOC_WR_BITS_PER_WORD, &bits) < 0) {
        perror("Failed to set SPI parameters");
        return -1;
    }

    // Open CSV file
    csv_fd = open(CSV_FILE, O_WRONLY | O_CREAT | O_TRUNC, 0644);
    if (csv_fd < 0) {
        perror("Failed to open CSV file");
        return -1;
    }

    // Write CSV header
    write(csv_fd, "Channel,Value\n", 14);

    // Request GPIO line for CE0
    chip = gpiod_chip_open_by_name("gpiochip0");
    if (!chip) {
        perror("Failed to open GPIO chip");
        return -1;
    }
    memset(&request, 0, sizeof(request));
    request.consumer = "MCP3008";
    request.request_type = GPIO_REQUEST_OUTPUT;
    if (gpiod_chip_get_line(chip, 8, &request) < 0) {
        perror("Failed to get GPIO line");
        return -1;
    }
    if (gpiod_line_request(chip, 8, &request) < 0) {
        perror("Failed to request GPIO line");
        return -1;
    }

    // Set up signal handler for graceful exit
    signal(SIGINT, cleanup);

    // Main loop
    while (1) {
        for (int channel = 0; channel < 3; channel++) {
            // Set CE0 high
            if (gpiod_line_set_value(chip, 8, 1) < 0) {
                perror("Failed to set CE0 high");
                return -1;
            }

            // Send command to MCP3008
            tx[0] = 0x01;
            tx[1] = 0x80 | (channel << 4);
            tx[2] = 0x00;
            if (write(spi_fd, tx, 3) != 3 || read(spi_fd, rx, 3) != 3) {
                perror("Failed to read from MCP3008");
                return -1;
            }

            // Set CE0 low
            if (gpiod_line_set_value(chip, 8, 0) < 0) {
                perror("Failed to set CE0 low");
                return -1;
            }

            // Calculate and log value
            value = ((rx[1] & 0x03) << 8) | rx[2];
            sprintf(buffer, "%d,%d\n", channel, value);
            write(csv_fd, buffer, strlen(buffer));
        }

        // Wait for 1 second
        sleep(1);
    }

    // Cleanup
    cleanup(0);
    return 0;
}

#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <mosquitto.h>
#include <cJSON.h>
#include <pigpio.h>

#define GPIO_PIN 17
#define MQTT_BROKER "mqtt.eclipseprojects.io"
#define MQTT_PORT 1883
#define MQTT_CLIENT_ID "rpi_led_control"
#define MQTT_TOPIC "home/led_control"

volatile sig_atomic_t running = 1;
struct mosquitto *mosq = NULL;
int reconnect_delay = 1;

void signal_handler(int signum) {
    running = 0;
}

void message_callback(struct mosquitto *mosq, void *userdata, const struct mosquitto_message *message) {
    if (message->topic && strcmp(message->topic, MQTT_TOPIC) == 0 && message->payloadlen > 0) {
        cJSON *root = cJSON_Parse((char *)message->payload);
        if (root) {
            cJSON *led_state = cJSON_GetObjectItemCaseSensitive(root, "led_state");
            if (led_state && cJSON_IsBool(led_state)) {
                gpioWrite(GPIO_PIN, led_state->valueint);
            }
            cJSON_Delete(root);
        }
    }
}

void reconnect() {
    while (!running && mosquitto_reconnect(mosq) != MOSQ_ERR_SUCCESS) {
        sleep(reconnect_delay);
        if (reconnect_delay < 60) {
            reconnect_delay *= 2;
        }
    }
    reconnect_delay = 1;
}

int main() {
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    if (gpioInitialise() < 0) {
        fprintf(stderr, "Failed to initialize pigpio\n");
        return EXIT_FAILURE;
    }

    mosquitto_lib_init();

    mosq = mosquitto_new(MQTT_CLIENT_ID, true, NULL);
    if (!mosq) {
        fprintf(stderr, "Failed to create mosquitto client\n");
        gpioTerminate();
        return EXIT_FAILURE;
    }

    mosquitto_connect_callback_set(mosq, reconnect);
    mosquitto_message_callback_set(mosq, message_callback);

    if (mosquitto_connect(mosq, MQTT_BROKER, MQTT_PORT, 60) != MOSQ_ERR_SUCCESS) {
        fprintf(stderr, "Failed to connect to MQTT broker\n");
        mosquitto_destroy(mosq);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    if (mosquitto_subscribe(mosq, NULL, MQTT_TOPIC, 0) != MOSQ_ERR_SUCCESS) {
        fprintf(stderr, "Failed to subscribe to MQTT topic\n");
        mosquitto_destroy(mosq);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    gpioSetMode(GPIO_PIN, PI_OUTPUT);
    gpioWrite(GPIO_PIN, 0);

    mosquitto_loop_start(mosq);

    while (running) {
        sleep(1);
    }

    mosquitto_loop_stop(mosq, true);
    mosquitto_destroy(mosq);
    mosquitto_lib_cleanup();
    gpioTerminate();

    return EXIT_SUCCESS;
}

#include <stdio.h>
#include <stdlib.h>
#include <signal.h>
#include <libgpiod.h>

#define SOUND_SENSOR_PIN 17
#define ALARM_LED_PIN 18
#define SOUND_DETECTED 0
#define SOUND_NOT_DETECTED 1
#define BLINK_INTERVAL_MS 100
#define BLINK_DURATION_MS 1000

static struct gpiod_chip *chip;
static struct gpiod_line *sound_sensor_line;
static struct gpiod_line *alarm_led_line;
static int keep_running = 1;

void cleanup_and_exit() {
    gpiod_line_release(sound_sensor_line);
    gpiod_chip_close(chip);
    printf("Exiting...\n");
    exit(0);
}

void signal_handler(int signum) {
    if (signum == SIGINT || signum == SIGTERM) {
        keep_running = 0;
    }
}

int main() {
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    chip = gpiod_chip_open("/dev/gpiochip0");
    if (!chip) {
        fprintf(stderr, "Failed to open GPIO chip\n");
        return EXIT_FAILURE;
    }

    sound_sensor_line = gpiod_chip_get_line(chip, SOUND_SENSOR_PIN);
    if (!sound_sensor_line) {
        fprintf(stderr, "Failed to get line for sound sensor\n");
        cleanup_and_exit();
    }

    alarm_led_line = gpiod_chip_get_line(chip, ALARM_LED_PIN);
    if (!alarm_led_line) {
        fprintf(stderr, "Failed to get line for alarm LED\n");
        cleanup_and_exit();
    }

    if (gpiod_line_request_input(sound_sensor_line, "sound_sensor") < 0) {
        fprintf(stderr, "Failed to request input for sound sensor\n");
        cleanup_and_exit();
    }

    if (gpiod_line_request_output(alarm_led_line, "alarm_led", 0) < 0) {
        fprintf(stderr, "Failed to request output for alarm LED\n");
        cleanup_and_exit();
    }

    while (keep_running) {
        int sound_detected = gpiod_line_get_value(sound_sensor_line);
        printf("Sound detected: %d\n", sound_detected);

        if (sound_detected == SOUND_DETECTED) {
            for (int i = 0; i < BLINK_DURATION_MS / BLINK_INTERVAL_MS && keep_running; i++) {
                gpiod_line_set_value(alarm_led_line, 1);
                usleep(BLINK_INTERVAL_MS * 1000);
                gpiod_line_set_value(alarm_led_line, 0);
                usleep(BLINK_INTERVAL_MS * 1000);
            }
        }

        usleep(BLINK_INTERVAL_MS * 1000);
    }

    cleanup_and_exit();
    return EXIT_SUCCESS;
}

#include <stdio.h>
#include <stdlib.h>
#include <signal.h>
#include <time.h>
#include <libgpiod.h>

volatile sig_atomic_t stop = 0;

void handle_signal(int signum) {
    stop = 1;
}

int main() {
    struct gpiod_chip *chip;
    struct gpiod_line *line;
    struct gpiod_line_event event;
    FILE *logfile;
    struct timespec ts;

    signal(SIGINT, handle_signal);
    signal(SIGTERM, handle_signal);

    chip = gpiod_chip_open("/dev/gpiochip0");
    if (!chip) {
        perror("Failed to open GPIO chip");
        return EXIT_FAILURE;
    }

    line = gpiod_chip_get_line(chip, 17);
    if (!line) {
        perror("Failed to get GPIO line");
        gpiod_chip_close(chip);
        return EXIT_FAILURE;
    }

    if (gpiod_line_request_falling_edge_events(line, "vibration-monitor") < 0) {
        perror("Failed to request falling edge events");
        gpiod_chip_close(chip);
        gpiod_line_release(line);
        return EXIT_FAILURE;
    }

    logfile = fopen("/var/log/vibration_shutdown.log", "a");
    if (!logfile) {
        perror("Failed to open log file");
        gpiod_chip_close(chip);
        gpiod_line_release(line);
        return EXIT_FAILURE;
    }

    while (!stop) {
        if (gpiod_line_event_wait(line, &event) < 0) {
            perror("Failed to wait for event");
            break;
        }

        if (gpiod_line_event_read(line, &event) < 0) {
            perror("Failed to read event");
            break;
        }

        clock_gettime(CLOCK_REALTIME, &ts);
        fprintf(logfile, "Vibration detected at %ld.%09ld\n", ts.tv_sec, ts.tv_nsec);
        fflush(logfile);
        printf("Vibration detected at %ld.%09ld\n", ts.tv_sec, ts.tv_nsec);
        system("sudo shutdown -h now");
    }

    fclose(logfile);
    gpiod_line_release(line);
    gpiod_chip_close(chip);

    return EXIT_SUCCESS;
}

#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <pigpio.h>
#include <errno.h>

#define BMP280_ADDRESS 0x76
#define BMP280_CHIP_ID 0x58
#define BMP280_CTRL_MEAS_REG 0xF4
#define BMP280_PRESSURE_MSB_REG 0xF7
#define BMP280_TEMP_MSB_REG 0xFA
#define BMP280_TEMP_LSB_REG 0xFB
#define BMP280_PRESSURE_LSB_REG 0xFC
#define BMP280_TEMP_OSRS_X1 0x2
#define BMP280_PRESSURE_OSRS_X1 0x2
#define BMP280_MODE_NORMAL 0x3
#define BMP280_SEA_LEVEL_PRESSURE 101325

volatile sig_atomic_t stop = 0;

void signal_handler(int signum) {
    stop = 1;
}

int main() {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Failed to initialize pigpio: %s\n", strerror(errno));
        return EXIT_FAILURE;
    }

    int i2c_handle = gpioI2COpen(1, BMP280_ADDRESS);
    if (i2c_handle < 0) {
        fprintf(stderr, "Failed to open I2C bus: %s\n", strerror(errno));
        gpioTerminate();
        return EXIT_FAILURE;
    }

    uint8_t chip_id;
    if (gpioI2CReadByteData(i2c_handle, 0xD0, &chip_id) < 0) {
        fprintf(stderr, "Failed to read chip ID: %s\n", strerror(errno));
        gpioI2CClose(i2c_handle);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    if (chip_id != BMP280_CHIP_ID) {
        fprintf(stderr, "Invalid chip ID: 0x%02X\n", chip_id);
        gpioI2CClose(i2c_handle);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    FILE *log_file = fopen("altitude_log.txt", "w");
    if (log_file == NULL) {
        fprintf(stderr, "Failed to open log file: %s\n", strerror(errno));
        gpioI2CClose(i2c_handle);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    struct sigaction action;
    memset(&action, 0, sizeof(struct sigaction));
    action.sa_handler = signal_handler;
    sigaction(SIGINT, &action, NULL);
    sigaction(SIGTERM, &action, NULL);

    uint8_t ctrl_meas_data = (BMP280_TEMP_OSRS_X1 << 5) | (BMP280_PRESSURE_OSRS_X1 << 2) | BMP280_MODE_NORMAL;
    if (gpioI2CWriteByteData(i2c_handle, BMP280_CTRL_MEAS_REG, ctrl_meas_data) < 0) {
        fprintf(stderr, "Failed to write control measurement register: %s\n", strerror(errno));
        gpioI2CClose(i2c_handle);
        fclose(log_file);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    while (!stop) {
        uint8_t raw_data[24];
        if (gpioI2CReadData(i2c_handle, raw_data, sizeof(raw_data)) < 0) {
            fprintf(stderr, "Failed to read raw data: %s\n", strerror(errno));
            break;
        }

        int32_t dig_T1 = (raw_data[1] << 8) | raw_data[0];
        int32_t dig_T2 = (raw_data[3] << 8) | raw_data[2];
        int32_t dig_T3 = (raw_data[5] << 8) | raw_data[4];
        int32_t dig_P1 = (raw_data[7] << 8) | raw_data[6];
        int32_t dig_P2 = (raw_data[9] << 8) | raw_data[8];
        int32_t dig_P3 = (raw_data[11] << 8) | raw_data[10];
        int32_t dig_P4 = (raw_data[13] << 8) | raw_data[12];
        int32_t dig_P5 = (raw_data[15] << 8) | raw_data[14];
        int32_t dig_P6 = (raw_data[17] << 8) | raw_data[16];
        int32_t dig_P7 = (raw_data[19] << 8) | raw_data[18];
        int32_t dig_P8 = (raw_data[21] << 8) | raw_data[20];
        int32_t dig_P9 = (raw_data[23] << 8) | raw_data[22];

        int32_t adc_T = (raw_data[3] << 12) | (raw_data[4] << 4) | (raw_data[5] >> 4);
        int32_t adc_P = (raw_data[0] << 12) | (raw_data[1] << 4) | (raw_data[2] >> 4);

        int64_t var1, var2, t_fine;
        var1 = (((adc_T >> 3) - (dig_T1 << 1))) * (dig_T2 >> 11);
        var2 = (((((adc_T >> 4) - (dig_T1)) * ((adc_T >> 4) - (dig_T1))) >> 12) * (dig_T3 >> 14));
        t_fine = var1 + var2;
        float temperature = (t_fine * 5 + 128) >> 8;

        var1 = ((int64_t)t_fine >> 1) - (int64_t)64000;
        var2 = (((var1 >> 2) * (var1 >> 2)) >> 11) * (int64_t)dig_P6;
        var2 = var2 + ((var1 * (int64_t)dig_P5) << 1);
        var2 = (var2 >> 2) + ((int64_t)dig_P4 << 16);
        var1 = (((dig_P3 * (((var1 >> 2) * (var1 >> 2)) >> 13)) >> 3) + ((((int64_t)dig_P2) * var1) >> 2)) >> 31;
        var1 = (int64_t)dig_P1 * (((var1 >> 1) + 32768) >> 15);
        float pressure;
        if (var1 == 0) {
            pressure = 0;
        } else {
            pressure = ((uint64_t)1048576 - adc_P) * 3125;
            pressure = (pressure / var1) * 2;
            var1 = (dig_P9 * (((pressure >> 3) * (pressure >> 3)) >> 13)) >> 12;
            var2 = (dig_P8 * (pressure >> 2)) >> 13;
            pressure = (pressure + ((var1 + var2 + dig_P7) >> 4));
        }

        float altitude = 44330.0f * (1.0f - powf(pressure / BMP280_SEA_LEVEL_PRESSURE, 0.1903f));

        time_t now = time(NULL);
        struct tm *time_info = localtime(&now);
        char timestamp[20];
        strftime(timestamp, sizeof(timestamp), "%FT%T%z", time_info);

        fprintf(log_file, "%s, Temperature: %.2f°C, Pressure: %.2fPa, Altitude: %.2fm\n", timestamp, temperature, pressure, altitude);
        fflush(log_file);
    }

    fclose(log_file);
    gpioI2CClose(i2c_handle);
    gpioTerminate();
    return EXIT_SUCCESS;
}

#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <pigpio.h>
#include <signal.h>

#define SPI_CHANNEL 0
#define SPI_SPEED 500000
#define MCP3008_CHANNEL 0
#define LM35_VOLT_PER_DEGREE 0.010 // 10mV/°C
#define BUFFER_SIZE 120
#define LOG_FILE_NAME "temp_log.dat"

float temp_buffer[BUFFER_SIZE];
int buffer_index = 0;
bool log_to_file = true;
FILE *log_file = NULL;

void close_spi_and_exit(int signum) {
    if (spiOpen(SPI_CHANNEL, 0, 0) >= 0) {
        spiClose(SPI_CHANNEL);
    }
    gpioTerminate();
    exit(signum);
}

void read_temperature() {
    uint8_t tx[3] = {0x01, 0x80 | MCP3008_CHANNEL, 0x00};
    uint8_t rx[3];
    float temperature;

    if (spiXfer(SPI_CHANNEL, tx, rx, 3) < 0) {
        printf("SPI transfer failed\n");
        return;
    }

    temperature = ((rx[1] & 0x03) << 8) | rx[2];
    temperature *= LM35_VOLT_PER_DEGREE;

    printf("Temperature: %.2f °C\n", temperature);

    if (log_to_file && log_file) {
        temp_buffer[buffer_index] = temperature;
        buffer_index = (buffer_index + 1) % BUFFER_SIZE;
        fwrite(temp_buffer, sizeof(float), BUFFER_SIZE, log_file);
        fseek(log_file, 0, SEEK_SET);
    }
}

int main() {
    if (gpioInitialise() < 0) {
        printf("pigpio initialization failed\n");
        return EXIT_FAILURE;
    }

    if ((log_file = fopen(LOG_FILE_NAME, "wb+")) == NULL) {
        printf("Failed to open log file\n");
        log_to_file = false;
    }

    signal(SIGINT, close_spi_and_exit);
    signal(SIGTERM, close_spi_and_exit);

    if (spiOpen(SPI_CHANNEL, SPI_SPEED, 0) < 0) {
        printf("Failed to open SPI channel\n");
        close_spi_and_exit(EXIT_FAILURE);
    }

    while (1) {
        read_temperature();
        sleep(5);
    }

    return EXIT_SUCCESS;
}

#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <fcntl.h>
#include <unistd.h>
#include <signal.h>
#include <sys/ioctl.h>
#include <linux/i2c-dev.h>
#include <sys/types.h>
#include <sys/stat.h>
#include <sys/select.h>
#include <sys/time.h>
#include <sys/mman.h>
#include <sys/io.h>
#include <linux/spi/spidev.h>

#define I2C_BUS "/dev/i2c-1"
#define SPI_BUS "/dev/spidev0.0"
#define BH1750_ADDRESS 0x23
#define MCP3008_CHANNEL 0
#define LOG_FILE "environmental_log.txt"

int i2c_fd, spi_fd;
volatile sig_atomic_t stop;

void signal_handler(int signum) {
    stop = 1;
}

int main() {
    struct sigaction action;
    memset(&action, 0, sizeof(struct sigaction));
    action.sa_handler = signal_handler;
    sigaction(SIGINT, &action, NULL);
    sigaction(SIGTERM, &action, NULL);

    if ((i2c_fd = open(I2C_BUS, O_RDWR)) < 0) {
        perror("Failed to open I2C bus");
        return 1;
    }

    if ((spi_fd = open(SPI_BUS, O_RDWR)) < 0) {
        perror("Failed to open SPI bus");
        return 1;
    }

    if (ioctl(i2c_fd, I2C_SLAVE, BH1750_ADDRESS) < 0) {
        perror("Failed to set I2C address");
        return 1;
    }

    uint8_t spi_mode = SPI_MODE_0;
    uint8_t spi_bits = 8;
    uint32_t spi_speed = 500000;
    uint16_t spi_delay = 0;
    struct spi_ioc_transfer spi_xfer[1];

    memset(spi_xfer, 0, sizeof(spi_xfer));
    spi_xfer[0].tx_buf = (unsigned long)&MCP3008_CHANNEL;
    spi_xfer[0].rx_buf = (unsigned long)NULL;
    spi_xfer[0].len = 1;
    spi_xfer[0].speed_hz = spi_speed;
    spi_xfer[0].delay_usecs = spi_delay;
    spi_xfer[0].bits_per_word = spi_bits;

    if (ioctl(spi_fd, SPI_IOC_MESSAGE(1), &spi_xfer) < 0) {
        perror("Failed to read from SPI");
        return 1;
    }

    while (!stop) {
        time_t rawtime;
        struct tm *timeinfo;
        char buffer[80];

        time(&rawtime);
        timeinfo = localtime(&rawtime);
        strftime(buffer, sizeof(buffer), "%Y-%m-%d %H:%M:%S", timeinfo);

        uint16_t light;
        if (read(i2c_fd, &light, 2) < 0) {
            perror("Failed to read from I2C");
            return 1;
        }

        uint16_t sound;
        if (read(spi_fd, &sound, 2) < 0) {
            perror("Failed to read from SPI");
            return 1;
        }

        FILE *file = fopen(LOG_FILE, "a");
        if (file == NULL) {
            perror("Failed to open log file");
            return 1;
        }

        fprintf(file, "%s, Light: %d, Sound: %d\n", buffer, light, sound);
        fclose(file);

        sleep(1);
    }

    close(i2c_fd);
    close(spi_fd);

    return 0;
}

#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <libgpiod.h>

#define GPIO_PIN 17
#define LOG_FILE "flame_events.log"

static gpiod_chip *chip;
static gpiod_line *line;
static FILE *log_file;
static int running = 1;

static void cleanup() {
    if (line) {
        gpiod_line_release(line);
    }
    if (chip) {
        gpiod_chip_close(chip);
    }
    if (log_file) {
        fclose(log_file);
    }
}

static void sig_handler(int signum) {
    running = 0;
}

int main() {
    struct sigaction action;
    memset(&action, 0, sizeof(struct sigaction));
    action.sa_handler = sig_handler;
    sigaction(SIGINT, &action, NULL);
    sigaction(SIGTERM, &action, NULL);

    atexit(cleanup);

    chip = gpiod_chip_open("/dev/gpiochip0");
    if (!chip) {
        fprintf(stderr, "Failed to open GPIO chip\n");
        return EXIT_FAILURE;
    }

    line = gpiod_chip_get_line(chip, GPIO_PIN);
    if (!line) {
        fprintf(stderr, "Failed to get GPIO line\n");
        return EXIT_FAILURE;
    }

    if (gpiod_line_request_input(line, "flame_sensor") < 0) {
        fprintf(stderr, "Failed to request GPIO line as input\n");
        return EXIT_FAILURE;
    }

    if (gpiod_line_set_flags(line, GPIO_PIN, GPIO_LINE_FLAG_PULL_DOWN) < 0) {
        fprintf(stderr, "Failed to set GPIO line flags\n");
        return EXIT_FAILURE;
    }

    log_file = fopen(LOG_FILE, "w");
    if (!log_file) {
        fprintf(stderr, "Failed to open log file\n");
        return EXIT_FAILURE;
    }

    fprintf(log_file, "timestamp,pin,state\n");

    while (running) {
        struct timespec ts;
        clock_gettime(CLOCK_REALTIME, &ts);
        uint8_t state = gpiod_line_get_value(line);
        fprintf(log_file, "%ld.%09ld,%d,%d\n", ts.tv_sec, ts.tv_nsec, GPIO_PIN, state);
        fflush(log_file);

        if (state) {
            printf("ALARM: Flame detected!\n");
        }

        sleep(1);
    }

    return EXIT_SUCCESS;
}

#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <pigpio.h>
#include <math.h>

#define SPI_CHANNEL 0
#define SPI_SPEED 500000
#define MCP3008_CS 8
#define MCP4725_ADDRESS 0x62
#define MCP4725_BUS 1
#define TMP36_CHANNEL 0
#define TMP36_VOLTAGE 3.3
#define TMP36_OFFSET 0.5
#define TMP36_SCALE 0.01
#define DAC_VOLTAGE_SCALE 4095.0 / TMP36_VOLTAGE
#define LOG_FILE "temperature_log.txt"

void log_temperature(float temperature, float voltage) {
    FILE *file = fopen(LOG_FILE, "a");
    if (file == NULL) {
        printf("Error opening log file\n");
        return;
    }
    time_t now = time(NULL);
    struct tm *t = localtime(&now);
    char timestamp[20];
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", t);
    fprintf(file, "%s, %.2f, %.2f\n", timestamp, temperature, voltage);
    fclose(file);
}

void handle_sigint(int signum) {
    printf("Shutting down...\n");
    gpioTerminate();
    exit(0);
}

int main() {
    if (gpioInitialise() < 0) {
        printf("pigpio initialisation failed\n");
        return 1;
    }

    signal(SIGINT, handle_sigint);

    int spi_handle = spiOpen(SPI_CHANNEL, SPI_SPEED, 0);
    if (spi_handle < 0) {
        printf("SPI initialisation failed\n");
        gpioTerminate();
        return 1;
    }

    int i2c_handle = i2cOpen(MCP4725_BUS, MCP4725_ADDRESS, 0);
    if (i2c_handle < 0) {
        printf("I2C initialisation failed\n");
        spiClose(spi_handle);
        gpioTerminate();
        return 1;
    }

    while (1) {
        uint8_t tx_buffer[3] = {0x40, 0x00, 0x00};
        uint8_t rx_buffer[3];
        spiXfer(spi_handle, tx_buffer, rx_buffer, sizeof(tx_buffer));

        int adc_value = (rx_buffer[1] << 8) | rx_buffer[2];
        float voltage = (float)adc_value / 4095.0 * TMP36_VOLTAGE;
        float temperature = (voltage - TMP36_OFFSET) / TMP36_SCALE;

        float dac_voltage = (temperature - 0) / (50 - 0) * TMP36_VOLTAGE;
        uint16_t dac_value = (uint16_t)(dac_voltage * DAC_VOLTAGE_SCALE);

        tx_buffer[0] = 0x40;
        tx_buffer[1] = (dac_value >> 8) & 0x0F;
        tx_buffer[2] = dac_value & 0xFF;
        i2cWrite(i2c_handle, tx_buffer, sizeof(tx_buffer));

        log_temperature(temperature, dac_voltage);
        printf("Temperature: %.2f°C, DAC voltage: %.2fV\n", temperature, dac_voltage);

        sleep(500);
    }

    i2cClose(i2c_handle);
    spiClose(spi_handle);
    gpioTerminate();
    return 0;
}

#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <pigpio.h>

#define SPI_CHANNEL 0
#define SPI_SPEED 1000000
#define SPI_MODE 0
#define SPI_CS 8
#define ADC_CHANNELS 3
#define SLEEP_INTERVAL 60000000

int main() {
    FILE *log_file;
    uint8_t tx_buffer[3] = {1, 0, 0};
    uint8_t rx_buffer[3];
    int adc_values[ADC_CHANNELS];
    double moisture_percentages[ADC_CHANNELS];
    struct timespec sleep_time = {0, SLEEP_INTERVAL};

    if ((log_file = fopen("soil_data.txt", "a")) == NULL) {
        fprintf(stderr, "Error opening log file.\n");
        return 1;
    }

    if (gpioInitialise() < 0) {
        fprintf(stderr, "Error initializing pigpio.\n");
        return 1;
    }

    int spi_handle = spiOpen(SPI_CHANNEL, SPI_SPEED, SPI_MODE);
    if (spi_handle < 0) {
        fprintf(stderr, "Error opening SPI channel.\n");
        gpioTerminate();
        return 1;
    }

    gpioSetMode(SPI_CS, PI_OUTPUT);

    while (1) {
        for (int i = 0; i < ADC_CHANNELS; i++) {
            tx_buffer[1] = (0x18 | (i << 6));
            spiXfer(spi_handle, tx_buffer, rx_buffer, 3);

            adc_values[i] = ((rx_buffer[1] & 0x0F) << 8) | rx_buffer[2];

            if (adc_values[i] < 0 || adc_values[i] > 1023) {
                fprintf(stderr, "Invalid ADC value for channel %d.\n", i);
                continue;
            }

            moisture_percentages[i] = (1.0 - ((double)adc_values[i] / 1023.0)) * 100.0;
        }

        time_t now = time(NULL);
        struct tm *t = localtime(&now);
        char timestamp[20];
        strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", t);

        for (int i = 0; i < ADC_CHANNELS; i++) {
            fprintf(log_file, "%s Channel %d: %.2f%%\n", timestamp, i, moisture_percentages[i]);
        }

        fflush(log_file);
        nanosleep(&sleep_time, NULL);
    }

    spiClose(spi_handle);
    fclose(log_file);
    gpioTerminate();
    printf("Goodbye!\n");
    return 0;
}

#include <stdio.h>
#include <stdlib.h>
#include <signal.h>
#include <libgpiod.h>

#define NUM_RELAYS 4
#define RELAY_PINS {17, 22, 23, 24}
#define ACTIVE_HIGH 1

static gpiod_chip *chip;
static gpiod_line_bulk lines;
static int relay_pins[NUM_RELAYS] = {17, 22, 23, 24};

static void cleanup_and_exit(void) {
    gpiod_line_set_value_bulk(lines, NUM_RELAYS, 0);
    gpiod_line_release_bulk(lines);
    gpiod_chip_close(chip);
    exit(EXIT_SUCCESS);
}

static void signal_handler(int signum) {
    cleanup_and_exit();
}

int main(void) {
    struct sigaction action;
    action.sa_handler = signal_handler;
    sigemptyset(&action.sa_mask);
    action.sa_flags = 0;
    sigaction(SIGINT, &action, NULL);
    sigaction(SIGTERM, &action, NULL);

    chip = gpiod_chip_open("/dev/gpiochip0");
    if (!chip) {
        fprintf(stderr, "Failed to open GPIO chip\n");
        return EXIT_FAILURE;
    }

    if (gpiod_chip_get_lines(chip, NUM_RELAYS, relay_pins, &lines) < 0) {
        fprintf(stderr, "Failed to get GPIO lines\n");
        gpiod_chip_close(chip);
        return EXIT_FAILURE;
    }

    for (int i = 0; i < NUM_RELAYS; i++) {
        if (gpiod_line_request_output(lines[i], "light_sequencer", ACTIVE_HIGH) < 0) {
            fprintf(stderr, "Failed to request GPIO line %d as output\n", relay_pins[i]);
            cleanup_and_exit();
        }
    }

    while (1) {
        for (int i = 0; i < NUM_RELAYS; i++) {
            gpiod_line_set_value(lines[i], ACTIVE_HIGH);
            sleep(1);
            gpiod_line_set_value(lines[i], 0);
            sleep(1);
        }
    }

    cleanup_and_exit();
    return EXIT_SUCCESS;
}

#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <pigpio.h>
#include <errno.h>

#define ADC_CHANNEL 0
#define ADC_THRESHOLD 500
#define LED_PIN 16
#define SPI_CHIP_SELECT 8
#define SPI_SPEED 1000000
#define DEBOUNCE_DELAY 500

static int spi_fd = -1;
static int led_fd = -1;
static int adc_value = 0;

void cleanup(int signum) {
    if (spi_fd != -1) {
        spiClose(spi_fd);
    }
    if (led_fd != -1) {
        gpioWrite(led_fd, 0);
        gpioTerminate();
    }
    exit(signum);
}

int main() {
    signal(SIGINT, cleanup);

    if (gpioInitialise() < 0) {
        fprintf(stderr, "Failed to initialize pigpio: %s\n", strerror(errno));
        return EXIT_FAILURE;
    }

    if ((spi_fd = spiOpen(0, SPI_CHIP_SELECT, SPI_SPEED)) < 0) {
        fprintf(stderr, "Failed to open SPI: %s\n", strerror(errno));
        gpioTerminate();
        return EXIT_FAILURE;
    }

    if ((led_fd = gpioOpen(LED_PIN, PI_OUTPUT)) < 0) {
        fprintf(stderr, "Failed to open LED: %s\n", strerror(errno));
        cleanup(EXIT_FAILURE);
        return EXIT_FAILURE;
    }

    while (1) {
        if ((adc_value = spiTransfer(spi_fd, ADC_CHANNEL)) < 0) {
            fprintf(stderr, "Failed to read ADC: %s\n", strerror(errno));
            cleanup(EXIT_FAILURE);
            return EXIT_FAILURE;
        }

        if (adc_value > ADC_THRESHOLD) {
            time_t now = time(NULL);
            struct tm *t = localtime(&now);
            char timestamp[20];
            strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", t);

            FILE *log_file = fopen("sound_events.log", "a");
            if (log_file == NULL) {
                fprintf(stderr, "Failed to open log file: %s\n", strerror(errno));
                cleanup(EXIT_FAILURE);
                return EXIT_FAILURE;
            }

            fprintf(log_file, "%s\n", timestamp);
            fclose(log_file);

            gpioWrite(led_fd, 1);
            usleep(DEBOUNCE_DELAY * 1000);
            gpioWrite(led_fd, 0);
        }

        usleep(10000);
    }

    cleanup(EXIT_SUCCESS);
    return EXIT_SUCCESS;
}

#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <stdint.h>
#include <stdbool.h>
#include <time.h>
#include <pigpio.h>
#include <unistd.h>

#define RAIN_SENSOR_CHANNEL 0
#define RAIN_LEVEL_THRESHOLD 5
#define MOTOR_IN1 17
#define MOTOR_IN2 18
#define MOTOR_ENA 27
#define MOTOR_PWM_SPEED 150
#define MOTOR_CLOSE_DURATION 3
#define ADC_MAX 1023
#define RAIN_LEVEL_MAX 10

volatile sig_atomic_t stop_requested = 0;

void signal_handler(int signum) {
    stop_requested = 1;
}

int main() {
    FILE *log_file;
    if ((log_file = fopen("rain_log.txt", "a")) == NULL) {
        fprintf(stderr, "Failed to open log file.\n");
        return EXIT_FAILURE;
    }

    if (gpioInitialise() < 0) {
        fprintf(stderr, "Failed to initialize pigpio.\n");
        fclose(log_file);
        return EXIT_FAILURE;
    }

    if (gpioSetMode(MOTOR_IN1, PI_OUTPUT) < 0 ||
        gpioSetMode(MOTOR_IN2, PI_OUTPUT) < 0 ||
        gpioSetMode(MOTOR_ENA, PI_OUTPUT) < 0) {
        fprintf(stderr, "Failed to set motor GPIO modes.\n");
        gpioTerminate();
        fclose(log_file);
        return EXIT_FAILURE;
    }

    if (gpioSetPWMfrequency(MOTOR_ENA, 1000) < 0) {
        fprintf(stderr, "Failed to set PWM frequency.\n");
        gpioTerminate();
        fclose(log_file);
        return EXIT_FAILURE;
    }

    if (gpioSetPWMrange(MOTOR_ENA, 255) < 0) {
        fprintf(stderr, "Failed to set PWM range.\n");
        gpioTerminate();
        fclose(log_file);
        return EXIT_FAILURE;
    }

    if (gpioSetPWMdutycycle(MOTOR_ENA, MOTOR_PWM_SPEED) < 0) {
        fprintf(stderr, "Failed to set PWM duty cycle.\n");
        gpioTerminate();
        fclose(log_file);
        return EXIT_FAILURE;
    }

    if (signal(SIGINT, signal_handler) == SIG_ERR ||
        signal(SIGTERM, signal_handler) == SIG_ERR) {
        fprintf(stderr, "Failed to set signal handlers.\n");
        gpioTerminate();
        fclose(log_file);
        return EXIT_FAILURE;
    }

    int spi_fd = spiOpen(0, 1000000, 0);
    if (spi_fd < 0) {
        fprintf(stderr, "Failed to open SPI device.\n");
        gpioTerminate();
        fclose(log_file);
        return EXIT_FAILURE;
    }

    uint8_t tx[3] = {0x01, (0x08 | RAIN_SENSOR_CHANNEL) << 4, 0x00};
    uint8_t rx[3];

    while (!stop_requested) {
        if (spiXfer(spi_fd, tx, rx, 3) < 0) {
            fprintf(stderr, "Failed to perform SPI transfer.\n");
            break;
        }

        int adc_value = ((rx[1] & 0x03) << 8) | rx[2];
        float rain_level = (float)adc_value / ADC_MAX * RAIN_LEVEL_MAX;

        time_t now = time(NULL);
        struct tm *time_info = localtime(&now);
        char time_str[20];
        strftime(time_str, sizeof(time_str), "%Y-%m-%d %H:%M:%S", time_info);

        fprintf(log_file, "%s, Rain Level: %.2f\n", time_str, rain_level);
        fflush(log_file);

        if (rain_level >= RAIN_LEVEL_THRESHOLD) {
            gpioWrite(MOTOR_IN1, 1);
            gpioWrite(MOTOR_IN2, 0);
            sleep(MOTOR_CLOSE_DURATION);
            gpioWrite(MOTOR_IN1, 0);
            gpioWrite(MOTOR_IN2, 0);
        } else {
            gpioWrite(MOTOR_IN1, 0);
            gpioWrite(MOTOR_IN2, 1);
            sleep(MOTOR_CLOSE_DURATION);
            gpioWrite(MOTOR_IN1, 0);
            gpioWrite(MOTOR_IN2, 0);
        }
    }

    spiClose(spi_fd);
    gpioTerminate();
    fclose(log_file);

    return EXIT_SUCCESS;
}

#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <signal.h>
#include <time.h>
#include <pigpio.h>

#define LED_PIN 16
#define MIC_PIN 26
#define THRESHOLD 700
#define DEBOUNCE_TIME 50
#define LED_ON_TIME 500

volatile sig_atomic_t stop = 0;

void sigint_handler(int signum) {
    stop = 1;
}

int main() {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialization failed\n");
        return EXIT_FAILURE;
    }

    signal(SIGINT, sigint_handler);

    if (gpioSetMode(LED_PIN, PI_OUTPUT) < 0) {
        fprintf(stderr, "failed to set LED pin mode\n");
        gpioTerminate();
        return EXIT_FAILURE;
    }

    if (gpioSetMode(MIC_PIN, PI_INPUT) < 0) {
        fprintf(stderr, "failed to set microphone pin mode\n");
        gpioTerminate();
        return EXIT_FAILURE;
    }

    struct timespec debounce_timer = {0, 0};
    struct timespec led_timer = {0, 0};

    while (!stop) {
        int adc_value = gpioReadADC(MIC_PIN);
        if (adc_value < 0) {
            fprintf(stderr, "ADC read failed\n");
            gpioTerminate();
            return EXIT_FAILURE;
        }

        if (adc_value > THRESHOLD) {
            if (clock_gettime(CLOCK_MONOTONIC, &debounce_timer) < 0) {
                fprintf(stderr, "clock_gettime failed\n");
                gpioTerminate();
                return EXIT_FAILURE;
            }

            if (debounce_timer.tv_sec == 0 && debounce_timer.tv_nsec >= DEBOUNCE_TIME * 1000000) {
                if (gpioWrite(LED_PIN, PI_HIGH) < 0) {
                    fprintf(stderr, "failed to turn on LED\n");
                    gpioTerminate();
                    return EXIT_FAILURE;
                }

                if (clock_gettime(CLOCK_MONOTONIC, &led_timer) < 0) {
                    fprintf(stderr, "clock_gettime failed\n");
                    gpioTerminate();
                    return EXIT_FAILURE;
                }

                printf("Clap detected at %ld.%09ld\n", led_timer.tv_sec, led_timer.tv_nsec);

                while (led_timer.tv_sec == 0 && led_timer.tv_nsec < LED_ON_TIME * 1000000) {
                    if (clock_gettime(CLOCK_MONOTONIC, &led_timer) < 0) {
                        fprintf(stderr, "clock_gettime failed\n");
                        gpioTerminate();
                        return EXIT_FAILURE;
                    }
                }

                if (gpioWrite(LED_PIN, PI_LOW) < 0) {
                    fprintf(stderr, "failed to turn off LED\n");
                    gpioTerminate();
                    return EXIT_FAILURE;
                }
            }
        }
    }

    gpioTerminate();
    return EXIT_SUCCESS;
}

#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <unistd.h>
#include <fcntl.h>
#include <time.h>
#include <signal.h>
#include <sys/stat.h>
#include <sys/types.h>

#define GPIO17_PATH "/sys/class/gpio/gpio17/value"
#define GPIO17_EXPORT_PATH "/sys/class/gpio/export"
#define GPIO17_UNEXPORT_PATH "/sys/class/gpio/unexport"
#define LOG_FILE "distance_log.txt"

int running = 1;

void signal_handler(int signum) {
    if (signum == SIGINT || signum == SIGTERM) {
        FILE *unexport = fopen(GPIO17_UNEXPORT_PATH, "w");
        if (unexport) {
            fprintf(unexport, "17");
            fclose(unexport);
        }
        running = 0;
    }
}

int main() {
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    FILE *export = fopen(GPIO17_EXPORT_PATH, "w");
    if (!export) {
        perror("Failed to export GPIO17");
        return 1;
    }
    fprintf(export, "17");
    fclose(export);

    FILE *value = fopen(GPIO17_PATH, "r");
    if (!value) {
        perror("Failed to open GPIO17 value");
        return 1;
    }

    while (running) {
        char buffer[2];
        if (fread(buffer, 1, 1, value) != 1) {
            perror("Failed to read GPIO17 value");
            sleep(1);
            continue;
        }

        int voltage = buffer[0] == '0' ? 0 : 3;
        float distance = 26.0 / voltage + 6.0;

        time_t now = time(NULL);
        struct tm *t = localtime(&now);
        char timestamp[20];
        strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", t);

        FILE *log = fopen(LOG_FILE, "a");
        if (log) {
            fprintf(log, "%s: %.2fmm\n", timestamp, distance);
            fclose(log);
        }

        printf("%s: %.2fmm ", timestamp, distance);
        if (distance < 200.0) {
            printf("Feeder Activated\n");
        } else {
            printf("Feeder Idle\n");
        }

        sleep(1);
    }

    fclose(value);
    return 0;
}

#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <stdbool.h>
#include <unistd.h>
#include <fcntl.h>
#include <sys/ioctl.h>
#include <linux/spi/spidev.h>
#include <libgpiod.h>

#define SPI_DEVICE "/dev/spidev0.0"
#define LOG_FILE "soil_moisture.log"
#define PUMP_GPIO 17
#define ADC_CHANNEL 0
#define DRY_VALUE 800
#define WET_VALUE 300
#define MIN_MOISTURE 30

static int spi_fd;
static int log_fd;
static struct gpiod_chip *chip;
static struct gpiod_line *pump_line;

void cleanup() {
    gpiod_line_set_value(pump_line, 0);
    gpiod_line_release(pump_line);
    close(spi_fd);
    close(log_fd);
    gpiod_chip_close(chip);
}

int main() {
    struct spi_ioc_transfer tr = {
        .tx_buf = (unsigned long)tx,
        .rx_buf = (unsigned long)rx,
        .len = 3,
        .cs_change = 1,
        .delay_usecs = 1000,
        .speed_hz = 1000000,
    };

    chip = gpiod_chip_open_by_name("gpiochip0");
    if (!chip) {
        fprintf(stderr, "Failed to open GPIO chip\n");
        return EXIT_FAILURE;
    }

    pump_line = gpiod_chip_get_line(chip, PUMP_GPIO);
    if (!pump_line) {
        fprintf(stderr, "Failed to get pump GPIO line\n");
        return EXIT_FAILURE;
    }

    if (gpiod_line_request_output(pump_line, "pump", 0) < 0) {
        fprintf(stderr, "Failed to request pump GPIO line as output\n");
        return EXIT_FAILURE;
    }

    spi_fd = open(SPI_DEVICE, O_RDWR);
    if (spi_fd < 0) {
        fprintf(stderr, "Failed to open SPI device\n");
        return EXIT_FAILURE;
    }

    log_fd = open(LOG_FILE, O_WRONLY | O_CREAT | O_APPEND, 0644);
    if (log_fd < 0) {
        fprintf(stderr, "Failed to open log file\n");
        return EXIT_FAILURE;
    }

    atexit(cleanup);

    while (true) {
        uint8_t tx[3] = {1, 0x80 | (ADC_CHANNEL << 4), 0};
        uint8_t rx[3];

        if (ioctl(spi_fd, SPI_IOC_MESSAGE(1), &tr) < 0) {
            fprintf(stderr, "Failed to read from ADC\n");
            continue;
        }

        int value = (rx[1] << 8) | rx[2];
        int moisture = (value - WET_VALUE) * 100 / (DRY_VALUE - WET_VALUE);

        if (moisture < MIN_MOISTURE) {
            gpiod_line_set_value(pump_line, 1);
        } else {
            gpiod_line_set_value(pump_line, 0);
        }

        char log_entry[256];
        sprintf(log_entry, "%ld, %d, %s\n", time(NULL), moisture, gpiod_line_get_value(pump_line) ? "ON" : "OFF");
        write(log_fd, log_entry, strlen(log_entry));

        sleep(60);
    }

    return EXIT_SUCCESS;
}

