#include <sys/stat.h>
#include <sys/types.h>
#include <linux/spi/spidev.h>
#include <gpiod.h>

#define SPI_CHANNEL 0
#define SPI_SPEED 1000000
#define SPI_MODE 0
#define SPI_BITS 8
#define ADC_CHANNEL 0
#define DRV5055_QUIESCENT 1650
#define DRV5055_SENSITIVITY 100
#define SAMPLE_INTERVAL 500000 // 500 ms

static int spi_fd = -1;
static int log_fd = -1;
static struct gpiod_chip *chip = NULL;
static struct gpiod_line *line = NULL;

static void cleanup() {
    if (line) {
        gpiod_line_set_value(line, 1);
        gpiod_line_release(line);
    }
    if (chip) {
        gpiod_chip_close(chip);
    }
    if (spi_fd != -1) {
        close(spi_fd);
    }
    if (log_fd != -1) {
        close(log_fd);
    }
}

static void sig_handler(int signum) {
    cleanup();
    exit(signum);
}

int main() {
    struct sigaction action;
    memset(&action, 0, sizeof(action));
    action.sa_handler = sig_handler;
    sigaction(SIGINT, &action, NULL);
    sigaction(SIGTERM, &action, NULL);

    chip = gpiod_chip_open("/dev/gpiochip0");
    if (!chip) {
        fprintf(stderr, "Failed to open GPIO chip\n");
        return EXIT_FAILURE;
    }

    line = gpiod_chip_get_line(chip, 8);
    if (!line) {
        fprintf(stderr, "Failed to get GPIO line\n");
        return EXIT_FAILURE;
    }

    spi_fd = open("/dev/spidev0.0", O_RDWR);
    if (spi_fd < 0) {
        fprintf(stderr, "Failed to open SPI device\n");
        return EXIT_FAILURE;
    }

    struct spi_ioc_transfer xfer = {
        .tx_buf = 0,
        .rx_buf = 0,
        .len = 3,
        .speed_hz = SPI_SPEED,
        .delay_usecs = 0,
        .bits_per_word = SPI_BITS,
        .cs_change = 0,
        .pad = 0
    };

    uint8_t tx[3] = {1, (ADC_CHANNEL << 4), 0};
    uint8_t rx[3];

    log_fd = open("magnetic_log.txt", O_WRONLY | O_CREAT | O_APPEND, 0666);
    if (log_fd < 0) {
        fprintf(stderr, "Failed to open log file\n");
        return EXIT_FAILURE;
    }

    struct timeval tv;
    while (true) {
        gettimeofday(&tv, NULL);
        uint64_t timestamp = tv.tv_sec * 1000000 + tv.tv_usec;

        gpiod_line_set_value(line, 0);
        write(spi_fd, tx, 3);
        read(spi_fd, rx, 3);
        gpiod_line_set_value(line, 1);

        uint16_t adc_value = (rx[1] << 8) | rx[2];
        int32_t vout_mV = (int32_t)adc_value * 3300 / 1023;
        int32_t B_mt = (vout_mV - DRV5055_QUIESCENT) / DRV5055_SENSITIVITY;

        char buffer[256];
        sprintf(buffer, "%llu,%0.2f\n", timestamp, B_mt / 100.0);
        write(log_fd, buffer, strlen(buffer));

        usleep(SAMPLE_INTERVAL);
    }

    cleanup();
    return EXIT_SUCCESS;
}

#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <signal.h>
#include <time.h>
#include <pigpio.h>

#define SPI_CHANNEL 0
#define SPI_SPEED 500000
#define ADC_CHANNEL 0
#define LED_PIN 21
#define THRESHOLD 10.0
#define VCC 3.3
#define SENSITIVITY (2.5 * VCC / 5)

void cleanup(int signum) {
    gpioTerminate();
    exit(signum);
}

int main() {
    FILE *log_file;
    int spi_fd, adc_value;
    float voltage, field_mT;
    struct timespec req, rem;

    req.tv_sec = 0;
    req.tv_nsec = 100000000L; // 100 ms

    if (gpioInitialise() < 0) {
        fprintf(stderr, "Failed to initialize pigpio\n");
        return EXIT_FAILURE;
    }

    signal(SIGINT, cleanup);

    spi_fd = spiOpen(SPI_CHANNEL, SPI_SPEED, 0);
    if (spi_fd < 0) {
        fprintf(stderr, "Failed to open SPI channel\n");
        gpioTerminate();
        return EXIT_FAILURE;
    }

    log_file = fopen("magnetic_log.txt", "a");
    if (!log_file) {
        fprintf(stderr, "Failed to open log file\n");
        spiClose(spi_fd);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    gpioSetMode(LED_PIN, PI_OUTPUT);

    while (1) {
        if (nanosleep(&req, &rem) == -1) {
            fprintf(stderr, "Failed to sleep\n");
            break;
        }

        adc_value = spiTransfer(spi_fd, ADC_CHANNEL << 8, 0);
        if (adc_value < 0) {
            fprintf(stderr, "Failed to read ADC\n");
            break;
        }

        voltage = adc_value * VCC / 1023.0;
        field_mT = (voltage - VCC / 2) * 1000 / SENSITIVITY;

        fprintf(log_file, "%ld %f\n", time(NULL), field_mT);

        if (field_mT > THRESHOLD) {
            gpioWrite(LED_PIN, PI_HIGH);
        } else {
            gpioWrite(LED_PIN, PI_LOW);
        }
    }

    fclose(log_file);
    spiClose(spi_fd);
    gpioTerminate();

    return EXIT_SUCCESS;
}

#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <pigpio.h>
#include <errno.h>

#define SPI_CHANNEL 0
#define SPI_SPEED 1000000
#define SPI_MODE 0
#define ADC_CHANNEL 0
#define LOG_FILE "moisture_log.txt"

static int spi_fd = -1;
static int adc_fd = -1;

void log_message(const char *message) {
    time_t now = time(NULL);
    struct tm *t = localtime(&now);
    char timestamp[20];
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", t);
    FILE *file = fopen(LOG_FILE, "a");
    if (file) {
        fprintf(file, "%s %s\n", timestamp, message);
        fclose(file);
    }
}

void close_spi() {
    if (spi_fd != -1) {
        spiClose(spi_fd);
    }
}

void close_adc() {
    if (adc_fd != -1) {
        close(adc_fd);
    }
}

void close_all() {
    close_spi();
    close_adc();
    gpioTerminate();
}

void handle_sigint(int signum) {
    close_all();
    exit(0);
}

int main() {
    if (gpioInitialise() < 0) {
        log_message("Failed to initialize pigpio");
        return 1;
    }

    struct sigaction action;
    memset(&action, 0, sizeof(action));
    action.sa_handler = handle_sigint;
    sigaction(SIGINT, &action, NULL);

    spi_fd = spiOpen(SPI_CHANNEL, SPI_SPEED, SPI_MODE);
    if (spi_fd < 0) {
        log_message("Failed to open SPI");
        close_all();
        return 1;
    }

    adc_fd = open("/dev/adc", O_RDWR);
    if (adc_fd < 0) {
        log_message("Failed to open ADC");
        close_all();
        return 1;
    }

    while (1) {
        uint8_t tx_buf[3] = {0x01, 0x80 | (ADC_CHANNEL << 4), 0x00};
        uint8_t rx_buf[3];

        if (write(adc_fd, tx_buf, sizeof(tx_buf)) != sizeof(tx_buf)) {
            log_message("Failed to write to ADC");
            continue;
        }

        if (read(adc_fd, rx_buf, sizeof(rx_buf)) != sizeof(rx_buf)) {
            log_message("Failed to read from ADC");
            continue;
        }

        int adc_value = ((rx_buf[1] & 0x03) << 8) | rx_buf[2];
        char message[100];
        sprintf(message, "ADC value: %d", adc_value);
        log_message(message);

        sleep(60);
    }

    close_all();
    return 0;
}

#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <unistd.h>
#include <fcntl.h>
#include <signal.h>
#include <time.h>
#include <libgpiod.h>
#include <sys/ioctl.h>
#include <linux/spi/spidev.h>

#define SPI_CHANNEL 0
#define SPI_SPEED 500000
#define SPI_MODE 0
#define SPI_BITS 8
#define GPIO_PIN 17
#define ADC_CHANNEL 0
#define LOG_FILE "current_log.txt"

int spi_fd, gpio_fd;
FILE *log_file;

void cleanup() {
    if (log_file) fclose(log_file);
    if (spi_fd >= 0) close(spi_fd);
    if (gpio_fd >= 0) gpiod_close(gpio_fd);
}

void sig_handler(int signum) {
    cleanup();
    exit(signum);
}

int main() {
    struct spi_ioc_transfer spi_xfer;
    uint8_t tx_buf[3] = {1, 0x80 | (ADC_CHANNEL << 4), 0};
    uint8_t rx_buf[3];
    float voltage, current;
    struct timespec ts;
    struct gpiod_line_request req;
    struct gpiod_chip *chip;

    signal(SIGINT, sig_handler);
    signal(SIGTERM, sig_handler);

    chip = gpiod_chip_open("/dev/gpiochip0");
    if (!chip) {
        fprintf(stderr, "Failed to open GPIO chip\n");
        return 1;
    }

    gpio_fd = gpiod_chip_get_line(chip, GPIO_PIN);
    if (gpio_fd < 0) {
        fprintf(stderr, "Failed to get GPIO line\n");
        gpiod_chip_close(chip);
        return 1;
    }

    memset(&req, 0, sizeof(req));
    req.consumer = "current_reader";
    req.request_type = GPIO_REQUEST_OUTPUT;
    if (gpiod_line_request(gpio_fd, &req) < 0) {
        fprintf(stderr, "Failed to request GPIO line\n");
        gpiod_chip_close(chip);
        return 1;
    }

    spi_fd = open("/dev/spidev0.0", O_RDWR);
    if (spi_fd < 0) {
        fprintf(stderr, "Failed to open SPI device\n");
        gpiod_chip_close(chip);
        return 1;
    }

    if (ioctl(spi_fd, SPI_IOC_WR_MODE, &SPI_MODE) < 0 ||
        ioctl(spi_fd, SPI_IOC_WR_BITS_PER_WORD, &SPI_BITS) < 0 ||
        ioctl(spi_fd, SPI_IOC_WR_MAX_SPEED_HZ, &SPI_SPEED) < 0) {
        fprintf(stderr, "Failed to configure SPI device\n");
        cleanup();
        return 1;
    }

    log_file = fopen(LOG_FILE, "w");
    if (!log_file) {
        fprintf(stderr, "Failed to open log file\n");
        cleanup();
        return 1;
    }

    while (1) {
        clock_gettime(CLOCK_REALTIME, &ts);
        fprintf(log_file, "%ld.%09ld,", ts.tv_sec, ts.tv_nsec);

        gpiod_line_set_value(gpio_fd, 1);
        usleep(1000);
        gpiod_line_set_value(gpio_fd, 0);

        memset(&spi_xfer, 0, sizeof(spi_xfer));
        spi_xfer.tx_buf = (unsigned long)tx_buf;
        spi_xfer.rx_buf = (unsigned long)rx_buf;
        spi_xfer.len = sizeof(tx_buf);
        spi_xfer.delay_usecs = 0;
        spi_xfer.speed_hz = SPI_SPEED;
        spi_xfer.bits_per_word = SPI_BITS;

        if (ioctl(spi_fd, SPI_IOC_MESSAGE(1), &spi_xfer) < 0) {
            fprintf(stderr, "Failed to read from ADC\n");
            cleanup();
            return 1;
        }

        voltage = ((rx_buf[1] << 8) | rx_buf[2]) * 3.3 / 4096;
        current = voltage / 0.1; // Assuming sensitivity of 100mV/A

        fprintf(log_file, "%.2f\n", current);
        fflush(log_file);
        sleep(1);
    }

    cleanup();
    return 0;
}

#include <stdio.h>
#include <stdlib.h>
