#include <signal.h>
#include <time.h>
#include <pigpio.h>

#define CHANNEL 0
#define FILENAME "current_log.txt"
#define SAMPLE_INTERVAL 100000 // 100 ms

volatile sig_atomic_t stop_flag = 0;

void sigint_handler(int signum) {
    stop_flag = 1;
}

int main() {
    FILE *log_file;
    int spi_handle;
    uint8_t tx[3] = {0x01, 0x80 | (CHANNEL << 4), 0x00};
    uint8_t rx[3];
    float voltage, current;
    time_t rawtime;
    struct tm *timeinfo;
    char buffer[80];

    if (gpioInitialise() < 0) {
        fprintf(stderr, "Failed to initialize pigpio\n");
        return 1;
    }

    signal(SIGINT, sigint_handler);

    spi_handle = spiOpen(0, 1000000, 0);
    if (spi_handle < 0) {
        fprintf(stderr, "Failed to open SPI\n");
        gpioTerminate();
        return 1;
    }

    log_file = fopen(FILENAME, "a");
    if (log_file == NULL) {
        fprintf(stderr, "Failed to open log file\n");
        spiClose(spi_handle);
        gpioTerminate();
        return 1;
    }

    while (!stop_flag) {
        int ret = spiXfer(spi_handle, tx, rx, sizeof(tx));
        if (ret != sizeof(tx)) {
            fprintf(stderr, "SPI transfer error\n");
            continue;
        }

        int code = ((rx[1] & 0x03) << 8) | rx[2];
        voltage = (float)code / 1023.0 * 5.0;

        if (voltage < 0 || voltage > 5.0) {
            fprintf(stderr, "Invalid voltage reading\n");
            continue;
        }

        current = (voltage - 2.5) * (50.0 / 2.5);

        time(&rawtime);
        timeinfo = localtime(&rawtime);
        strftime(buffer, sizeof(buffer), "%Y-%m-%d %H:%M:%S", timeinfo);
        fprintf(log_file, "%s %.2f A\n", buffer, current);
        fflush(log_file);
    }

    fclose(log_file);
    spiClose(spi_handle);
    gpioTerminate();

    return 0;
}

#include <stdio.h>
#include <stdlib.h>
#include <signal.h>
#include <libgpiod.h>
#include <unistd.h>

#define SENSOR1_GPIO 4
#define SENSOR2_GPIO 17
#define SAMPLES 5
#define DEBOUNCE_DELAY 2000

static gpiod_chip *chip;
static gpiod_line *line1, *line2;
static int sensor1_state, sensor2_state;

void cleanup() {
    gpiod_line_release(line1);
    gpiod_line_release(line2);
    gpiod_chip_close(chip);
}

void sigint_handler(int signum) {
    cleanup();
    exit(0);
}

int debounce_read(gpiod_line *line) {
    int count[2] = {0, 0};
    for (int i = 0; i < SAMPLES; i++) {
        int value = gpiod_line_get_value(line);
        count[value]++;
        usleep(DEBOUNCE_DELAY);
    }
    return count[0] > count[1];
}

int main() {
    struct sigaction action;
    action.sa_handler = sigint_handler;
    sigemptyset(&action.sa_mask);
    action.sa_flags = 0;
    sigaction(SIGINT, &action, NULL);

    chip = gpiod_chip_open_by_number(0);
    if (!chip) {
        fprintf(stderr, "Failed to open GPIO chip\n");
        return 1;
    }

    line1 = gpiod_chip_get_line(chip, SENSOR1_GPIO);
    if (!line1) {
        fprintf(stderr, "Failed to get line for GPIO %d\n", SENSOR1_GPIO);
        cleanup();
        return 1;
    }

    line2 = gpiod_chip_get_line(chip, SENSOR2_GPIO);
    if (!line2) {
        fprintf(stderr, "Failed to get line for GPIO %d\n", SENSOR2_GPIO);
        cleanup();
        return 1;
    }

    if (gpiod_line_request_input(line1, "sensor1") < 0) {
        fprintf(stderr, "Failed to request input for GPIO %d\n", SENSOR1_GPIO);
        cleanup();
        return 1;
    }

    if (gpiod_line_request_input(line2, "sensor2") < 0) {
        fprintf(stderr, "Failed to request input for GPIO %d\n", SENSOR2_GPIO);
        cleanup();
        return 1;
    }

    while (1) {
        sensor1_state = debounce_read(line1);
        sensor2_state = debounce_read(line2);

        printf("Sensor 1: %d, Sensor 2: %d\n", sensor1_state, sensor2_state);

        if (sensor1_state && sensor2_state) {
            printf("ALERT: Both sensors detect object\n");
        }

        sleep(1);
    }

    cleanup();
    return 0;
}

