#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <unistd.h>
#include <signal.h>
#include <syslog.h>
#include <libgen.h>
#include <sys/types.h>
#include <sys/stat.h>
#include <fcntl.h>
#include <time.h>
#include <libgpiod.h>
#include <pigpio.h>

#define GPIO_PIN 17
#define DEBOUNCE_TIME 200
#define POLL_INTERVAL 50
#define IMAGE_WIDTH 1280
#define IMAGE_HEIGHT 720
#define IMAGE_FORMAT "jpeg"
#define IMAGE_DIR "/home/pi/security_cam/"
#define IMAGE_PREFIX "image_"
#define IMAGE_SUFFIX ".jpg"
#define IMAGE_TIMESTAMP_FORMAT "%Y%m%dT%H%M%S"
#define LIBCAMERA_STILL "/usr/bin/libcamera-still"

static int running = 1;
static int gpio_fd = -1;
static int camera_pid = -1;

void sig_handler(int signum) {
    running = 0;
}

int main(int argc, char *argv[]) {
    struct sigaction sigact;
    sigact.sa_handler = sig_handler;
    sigemptyset(&sigact.sa_mask);
    sigact.sa_flags = 0;
    sigaction(SIGINT, &sigact, NULL);
    sigaction(SIGTERM, &sigact, NULL);

    openlog(basename(argv[0]), LOG_PID, LOG_USER);

    if (gpioInitialise() < 0) {
        syslog(LOG_ERR, "Failed to initialize pigpio");
        return EXIT_FAILURE;
    }

    gpio_fd = gpiod_open(0, GPIO_PIN, GPIO_LINE_REQUEST_DIRECTION_INPUT);
    if (gpio_fd < 0) {
        syslog(LOG_ERR, "Failed to open GPIO %d", GPIO_PIN);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    gpiod_line_set_flags(gpio_fd, GPIO_LINE_FLAG_BIAS_PULL_DOWN);

    while (running) {
        struct gpiod_line_event event;
        int event_received = gpiod_line_event_wait(gpio_fd, &event);
        if (event_received < 0) {
            syslog(LOG_ERR, "Failed to wait for GPIO event");
            break;
        }

        if (event.event_type == GPIOD_LINE_EVENT_RISING_EDGE) {
            usleep(DEBOUNCE_TIME * 1000);
            int state = gpiod_line_get_value(gpio_fd);
            if (state == 1) {
                char image_path[PATH_MAX];
                time_t now = time(NULL);
                struct tm *timeinfo = localtime(&now);
                strftime(image_path, sizeof(image_path), IMAGE_DIR IMAGE_PREFIX IMAGE_TIMESTAMP_FORMAT IMAGE_SUFFIX, timeinfo);

                struct stat st = {0};
                if (stat(IMAGE_DIR, &st) == -1) {
                    mkdir(IMAGE_DIR, 0700);
                }

                char *args[] = {LIBCAMERA_STILL, "-o", image_path, "--width", "1280", "--height", "720", "--format", "jpeg", NULL};
                camera_pid = fork();
                if (camera_pid == 0) {
                    execvp(LIBCAMERA_STILL, args);
                    syslog(LOG_ERR, "Failed to execute libcamera-still");
                    _exit(EXIT_FAILURE);
                } else if (camera_pid < 0) {
                    syslog(LOG_ERR, "Failed to fork libcamera-still");
                } else {
                    int status;
                    waitpid(camera_pid, &status, 0);
                    if (WIFEXITED(status) && WEXITSTATUS(status) != 0) {
                        syslog(LOG_ERR, "libcamera-still exited with error");
                    } else {
                        syslog(LOG_INFO, "Snapshot saved to %s", image_path);
                    }
                }
            }
        }
    }

    closelog();
    gpioTerminate();
    return EXIT_SUCCESS;
}

