    if (ioctl(fd, VIDIOC_S_FMT, &fmt) < 0) {
        fprintf(stderr, "Failed to set format: %s\n", strerror(errno));
        goto cleanup;
    }

    struct v4l2_requestbuffers req = {
        .count = 1,
        .type = V4L2_BUF_TYPE_VIDEO_CAPTURE,
        .memory = V4L2_MEMORY_MMAP
    };
    if (ioctl(fd, VIDIOC_REQBUFS, &req) < 0) {
        fprintf(stderr, "Failed to request buffers: %s\n", strerror(errno));
        goto cleanup;
    }

    struct v4l2_buffer buf = {
        .type = V4L2_BUF_TYPE_VIDEO_CAPTURE,
        .memory = V4L2_MEMORY_MMAP,
        .index = 0
    };
    if (ioctl(fd, VIDIOC_QUERYBUF, &buf) < 0) {
        fprintf(stderr, "Failed to query buffer: %s\n", strerror(errno));
        goto cleanup;
    }

    void *image = mmap(NULL, buf.length, PROT_READ | PROT_WRITE, MAP_SHARED, fd, buf.m.offset);
    if (image == MAP_FAILED) {
        fprintf(stderr, "Failed to map buffer: %s\n", strerror(errno));
        goto cleanup;
    }

    if (ioctl(fd, VIDIOC_QBUF, &buf) < 0) {
        fprintf(stderr, "Failed to enqueue buffer: %s\n", strerror(errno));
        goto cleanup;
    }

    int frame_number = 0;
    while (1) {
        fd_set fds;
        FD_ZERO(&fds);
        FD_SET(fd, &fds);
        struct timeval timeout = {2, 0};
        int ret = select(fd + 1, &fds, NULL, NULL, &timeout);
        if (ret < 0) {
            fprintf(stderr, "Failed to select: %s\n", strerror(errno));
            goto cleanup;
        } else if (ret == 0) {
            continue;
        }

        if (ioctl(fd, VIDIOC_DQBUF, &buf) < 0) {
            if (errno == EAGAIN) {
                continue;
            } else {
                fprintf(stderr, "Failed to dequeue buffer: %s\n", strerror(errno));
                goto cleanup;
            }
        }

        char filename[256];
        sprintf(filename, IMAGE_NAME, frame_number++);
        FILE *file = fopen(filename, "wb");
        if (!file) {
            fprintf(stderr, "Failed to open file %s: %s\n", filename, strerror(errno));
            goto cleanup;
        }

        fprintf(file, "P5\n%d %d\n255\n", IMAGE_WIDTH, IMAGE_HEIGHT);
        if (fwrite(image, 1, buf.bytesused, file) != buf.bytesused) {
            fprintf(stderr, "Failed to write image data: %s\n", strerror(errno));
            fclose(file);
            goto cleanup;
        }

        fclose(file);
        if (ioctl(fd, VIDIOC_QBUF, &buf) < 0) {
            fprintf(stderr, "Failed to enqueue buffer: %s\n", strerror(errno));
            goto cleanup;
        }
    }

cleanup:
    if (image != MAP_FAILED) {
        munmap(image, buf.length);
    }
    close(fd);
    return EXIT_FAILURE;
}

