#define VIDEO_DEVICE "/dev/video0"
#define FRAME_WIDTH 640
#define FRAME_HEIGHT 480
#define FRAME_SIZE (FRAME_WIDTH * FRAME_HEIGHT * 2) // Assuming YUYV format

int main() {
    int video_fd = open(VIDEO_DEVICE, O_RDWR);
    if (video_fd < 0) {
        perror("Failed to open video device");
        return EXIT_FAILURE;
    }

    struct v4l2_format format;
    memset(&format, 0, sizeof(format));
    format.type = V4L2_BUF_TYPE_VIDEO_CAPTURE;
    format.fmt.pix.width = FRAME_WIDTH;
    format.fmt.pix.height = FRAME_HEIGHT;
    format.fmt.pix.pixelformat = V4L2_PIX_FMT_MJPEG;
    if (ioctl(video_fd, VIDIOC_S_FMT, &format) < 0) {
        perror("Failed to set video format");
        close(video_fd);
        return EXIT_FAILURE;
    }

    struct v4l2_requestbuffers req;
    memset(&req, 0, sizeof(req));
    req.count = 4;
    req.type = V4L2_BUF_TYPE_VIDEO_CAPTURE;
    req.memory = V4L2_MEMORY_MMAP;
    if (ioctl(video_fd, VIDIOC_REQBUFS, &req) < 0) {
        perror("Failed to request buffers");
        close(video_fd);
        return EXIT_FAILURE;
    }

    struct v4l2_buffer buf;
    memset(&buf, 0, sizeof(buf));
    buf.type = V4L2_BUF_TYPE_VIDEO_CAPTURE;
    buf.memory = V4L2_MEMORY_MMAP;
    for (int i = 0; i < req.count; i++) {
        buf.index = i;
        if (ioctl(video_fd, VIDIOC_QUERYBUF, &buf) < 0) {
            perror("Failed to query buffer");
            close(video_fd);
            return EXIT_FAILURE;
        }

        void *frame_buffer = mmap(NULL, buf.length, PROT_READ | PROT_WRITE, MAP_SHARED, video_fd, buf.m.offset);
        if (frame_buffer == MAP_FAILED) {
            perror("Failed to map buffer");
            close(video_fd);
            return EXIT_FAILURE;
        }

        if (ioctl(video_fd, VIDIOC_QBUF, &buf) < 0) {
            perror("Failed to enqueue buffer");
            close(video_fd);
            return EXIT_FAILURE;
        }
    }

    int frame_log_fd = open("frame_log.txt", O_WRONLY | O_CREAT, 0644);
    if (frame_log_fd < 0) {
        perror("Failed to open frame log file");
        close(video_fd);
        return EXIT_FAILURE;
    }

    fd_set fds;
    struct timeval tv;
    tv.tv_sec = 1;
    tv.tv_usec = 0;

    while (1) {
        FD_ZERO(&fds);
        FD_SET(video_fd, &fds);

        int ret = select(video_fd + 1, &fds, NULL, NULL, &tv);
        if (ret < 0) {
            perror("select failed");
            break;
        } else if (ret == 0) {
            continue;
        }

        memset(&buf, 0, sizeof(buf));
        buf.type = V4L2_BUF_TYPE_VIDEO_CAPTURE;
        buf.memory = V4L2_MEMORY_MMAP;
        if (ioctl(video_fd, VIDIOC_DQBUF, &buf) < 0) {
            perror("Failed to dequeue buffer");
            break;
        }

        struct timeval current_time;
        gettimeofday(&current_time, NULL);
        char timestamp[20];
        sprintf(timestamp, "%ld.%06ld\n", current_time.tv_sec, current_time.tv_usec);
        write(frame_log_fd, timestamp, strlen(timestamp));

        if (ioctl(video_fd, VIDIOC_QBUF, &buf) < 0) {
            perror("Failed to enqueue buffer");
            break;
        }
    }

    close(frame_log_fd);
    close(video_fd);
    return EXIT_SUCCESS;
}

