#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <fcntl.h>
#include <signal.h>
#include <errno.h>
#include <sys/ioctl.h>
#include <sys/mman.h>
#include <sys/stat.h>
#include <sys/time.h>
#include <linux/videodev2.h>

#define CLEAR(x) memset(&(x), 0, sizeof(x))

static int fd = -1;
static struct v4l2_format fmt;
static struct v4l2_buffer buf;
static struct v4l2_requestbuffers req;
static enum v4l2_buf_type type;
static unsigned char *mem[4];
static int n_buffers;

static void xioctl(int fh, int request, void *arg) {
    int r = ioctl(fh, request, arg);
    if (r == -1) {
        perror("ioctl");
        exit(EXIT_FAILURE);
    }
}

static void stop_capturing(void) {
    xioctl(fd, VIDIOC_STREAMOFF, &type);
}

static void start_capturing(void) {
    CLEAR(buf);
    buf.type = V4L2_BUF_TYPE_VIDEO_CAPTURE;
    buf.memory = V4L2_MEMORY_MMAP;
    xioctl(fd, VIDIOC_QBUF, &buf);
    type = V4L2_BUF_TYPE_VIDEO_CAPTURE;
    xioctl(fd, VIDIOC_STREAMON, &type);
}

static void uninit_device(void) {
    unsigned int i;
    for (i = 0; i < n_buffers; ++i)
        if (mem[i])
            munmap(mem[i], req.count);
    free(mem);
    stop_capturing();
}

static void init_mmap(void) {
    CLEAR(req);
    req.count = 4;
    req.type = V4L2_BUF_TYPE_VIDEO_CAPTURE;
    req.memory = V4L2_MEMORY_MMAP;
    xioctl(fd, VIDIOC_REQBUFS, &req);
    if (req.count < 2) {
        fprintf(stderr, "Insufficient buffer memory on %s\n", "/dev/video0");
        exit(EXIT_FAILURE);
    }
    mem = calloc(req.count, sizeof(mem[0]));
    if (!mem) {
        fprintf(stderr, "Out of memory\n");
        exit(EXIT_FAILURE);
    }
    for (n_buffers = 0; n_buffers < req.count; ++n_buffers) {
        CLEAR(buf);
        buf.type = V4L2_BUF_TYPE_VIDEO_CAPTURE;
        buf.memory = V4L2_MEMORY_MMAP;
        buf.index = n_buffers;
        xioctl(fd, VIDIOC_QUERYBUF, &buf);
        mem[n_buffers] = mmap(NULL, buf.length, PROT_READ | PROT_WRITE, MAP_SHARED, fd, buf.m.offset);
        if (mem[n_buffers] == MAP_FAILED) {
            perror("mmap");
            exit(EXIT_FAILURE);
        }
    }
}

static void init_device(void) {
    struct v4l2_capability cap;
    if (-1 == xioctl(fd, VIDIOC_QUERYCAP, &cap)) {
        if (EINVAL == errno) {
            fprintf(stderr, "%s is no V4L2 device\n", "/dev/video0");
            exit(EXIT_FAILURE);
        } else {
            perror("VIDIOC_QUERYCAP");
            exit(EXIT_FAILURE);
        }
    }
    if (!(cap.capabilities & V4L2_CAP_VIDEO_CAPTURE)) {
        fprintf(stderr, "%s is no video capture device\n", "/dev/video0");
        exit(EXIT_FAILURE);
    }
    if (!(cap.capabilities & V4L2_CAP_STREAMING)) {
        fprintf(stderr, "%s does not support streaming i/o\n", "/dev/video0");
        exit(EXIT_FAILURE);
    }
    CLEAR(fmt);
    fmt.type = V4L2_BUF_TYPE_VIDEO_CAPTURE;
    fmt.fmt.pix.width = 1920;
    fmt.fmt.pix.height = 1080;
    fmt.fmt.pix.pixelformat = V4L2_PIX_FMT_MJPEG;
    fmt.fmt.pix.field = V4L2_FIELD_NONE;
    xioctl(fd, VIDIOC_S_FMT, &fmt);
    init_mmap();
    start_capturing();
}

static void close_device(void) {
    if (-1 == close(fd))
        perror("close");
    fd = -1;
}

static void open_device(void) {
    fd = open("/dev/video0", O_RDWR);
    if (-1 == fd) {
        perror("open");
        exit(EXIT_FAILURE);
    }
}

static void sig_handler(int signum) {
    if (fd != -1)
        close_device();
    exit(EXIT_SUCCESS);
}

int main(void) {
    struct sigaction sigact;
    sigact.sa_handler = sig_handler;
    sigemptyset(&sigact.sa_mask);
    sigact.sa_flags = 0;
    sigaction(SIGINT, &sigact, NULL);
    sigaction(SIGTERM, &sigact, NULL);
    open_device();
    init_device();
    while (1) {
        fd_set fds;
        struct timeval tv;
        int r;
        FD_ZERO(&fds);
        FD_SET(fd, &fds);
        tv.tv_sec = 2;
        tv.tv_usec = 0;
        r = select(fd + 1, &fds, NULL, NULL, &tv);
        if (-1 == r) {
            if (EINTR == errno)
                continue;
            perror("select");
            return EXIT_FAILURE;
        }
        if (0 == r) {
            fprintf(stderr, "select timeout\n");
            return EXIT_FAILURE;
        }
        if (-1 == read(fd, mem[0], buf.bytesused)) {
            perror("read");
            return EXIT_FAILURE;
        }
        FILE *file = fopen("image.jpg", "wb");
        if (!file) {
            perror("fopen");
            return EXIT_FAILURE;
        }
        if (fwrite(mem[0], 1, buf.bytesused, file) != buf.bytesused) {
            perror("fwrite");
            fclose(file);
            return EXIT_FAILURE;
        }
        fclose(file);
        break;
    }
    uninit_device();
    close_device();
    return EXIT_SUCCESS;
}

