        return 1;
    }

    tilt_up_line = gpiod_chip_get_line(chip, TILT_UP_PIN);
    if (!tilt_up_line) {
        fprintf(stderr, "Failed to get tilt up line\n");
        cleanup();
        return 1;
    }

    tilt_down_line = gpiod_chip_get_line(chip, TILT_DOWN_PIN);
    if (!tilt_down_line) {
        fprintf(stderr, "Failed to get tilt down line\n");
        cleanup();
        return 1;
    }

    if (gpiod_line_request_output(pan_line, "pan", 0) < 0) {
        fprintf(stderr, "Failed to request pan line as output\n");
        cleanup();
        return 1;
    }

    if (gpiod_line_request_output(tilt_line, "tilt", 0) < 0) {
        fprintf(stderr, "Failed to request tilt line as output\n");
        cleanup();
        return 1;
    }

    if (gpiod_line_request_input(pan_up_line, "pan_up") < 0) {
        fprintf(stderr, "Failed to request pan up line as input\n");
        cleanup();
        return 1;
    }

    if (gpiod_line_request_input(pan_down_line, "pan_down") < 0) {
        fprintf(stderr, "Failed to request pan down line as input\n");
        cleanup();
        return 1;
    }

    if (gpiod_line_request_input(tilt_up_line, "tilt_up") < 0) {
        fprintf(stderr, "Failed to request tilt up line as input\n");
        cleanup();
        return 1;
    }

    if (gpiod_line_request_input(tilt_down_line, "tilt_down") < 0) {
        fprintf(stderr, "Failed to request tilt down line as input\n");
        cleanup();
        return 1;
    }

    int pan_pos = 75;
    int tilt_pos = 75;

    while (1) {
        if (gpiod_line_get_value(pan_up_line)) {
            pan_pos = (pan_pos + PAN_STEP <= PAN_MAX) ? pan_pos + PAN_STEP : PAN_MAX;
        }

        if (gpiod_line_get_value(pan_down_line)) {
            pan_pos = (pan_pos - PAN_STEP >= PAN_MIN) ? pan_pos - PAN_STEP : PAN_MIN;
        }

        if (gpiod_line_get_value(tilt_up_line)) {
            tilt_pos = (tilt_pos + TILT_STEP <= TILT_MAX) ? tilt_pos + TILT_STEP : TILT_MAX;
        }

        if (gpiod_line_get_value(tilt_down_line)) {
            tilt_pos = (tilt_pos - TILT_STEP >= TILT_MIN) ? tilt_pos - TILT_STEP : TILT_MIN;
        }

        gpiod_line_set_value(pan_line, (pan_pos * PWM_MAX) / 100);
        gpiod_line_set_value(tilt_line, (tilt_pos * PWM_MAX) / 100);

        usleep(50000); // 50 ms
    }

    cleanup();
    return 0;
}

#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <stdint.h>
#include <fcntl.h>
#include <unistd.h>
#include <sys/ioctl.h>
#include <sys/mman.h>
#include <sys/select.h>
#include <linux/videodev2.h>
#include <jpeglib.h>

#define WIDTH 640
#define HEIGHT 480
#define FRAME_SIZE (WIDTH * HEIGHT * 2)
#define OUTPUT_FILENAME "capture_%s.jpg"

int main() {
    int fd = open("/dev/video0", O_RDWR);
    if (fd < 0) {
        perror("Failed to open /dev/video0");
        return EXIT_FAILURE;
    }

    struct v4l2_format fmt;
    memset(&fmt, 0, sizeof(fmt));
    fmt.type = V4L2_BUF_TYPE_VIDEO_CAPTURE;
    fmt.fmt.pix.width = WIDTH;
    fmt.fmt.pix.height = HEIGHT;
    fmt.fmt.pix.pixelformat = V4L2_PIX_FMT_YUYV;
    fmt.fmt.pix.field = V4L2_FIELD_NONE;

    if (ioctl(fd, VIDIOC_S_FMT, &fmt) < 0) {
        perror("Failed to set format");
        close(fd);
        return EXIT_FAILURE;
    }

    struct v4l2_requestbuffers req;
    memset(&req, 0, sizeof(req));
    req.count = 4;
    req.type = V4L2_BUF_TYPE_VIDEO_CAPTURE;
    req.memory = V4L2_MEMORY_MMAP;

    if (ioctl(fd, VIDIOC_REQBUFS, &req) < 0) {
        perror("Failed to request buffers");
        close(fd);
        return EXIT_FAILURE;
    }

    struct v4l2_buffer buf;
    memset(&buf, 0, sizeof(buf));
    buf.type = V4L2_BUF_TYPE_VIDEO_CAPTURE;
    buf.memory = V4L2_MEMORY_MMAP;

    for (int i = 0; i < req.count; i++) {
        buf.index = i;
        if (ioctl(fd, VIDIOC_QUERYBUF, &buf) < 0) {
            perror("Failed to query buffer");
            close(fd);
            return EXIT_FAILURE;
        }

        void *ptr = mmap(NULL, buf.length, PROT_READ | PROT_WRITE, MAP_SHARED, fd, buf.m.offset);
        if (ptr == MAP_FAILED) {
            perror("Failed to mmap buffer");
            close(fd);
            return EXIT_FAILURE;
        }

        if (ioctl(fd, VIDIOC_QBUF, &buf) < 0) {
            perror("Failed to queue buffer");
            close(fd);
            return EXIT_FAILURE;
        }
    }

    enum v4l2_buf_type type = V4L2_BUF_TYPE_VIDEO_CAPTURE;
    if (ioctl(fd, VIDIOC_STREAMON, &type) < 0) {
        perror("Failed to start streaming");
        close(fd);
        return EXIT_FAILURE;
    }

    struct timeval timeout;
    timeout.tv_sec = 2;
    timeout.tv_usec = 0;

    fd_set fds;
    FD_ZERO(&fds);
    FD_SET(fd, &fds);

    if (select(fd + 1, &fds, NULL, NULL, &timeout) <= 0) {
        perror("Failed to select");
        close(fd);
        return EXIT_FAILURE;
    }

    if (ioctl(fd, VIDIOC_DQBUF, &buf) < 0) {
        perror("Failed to dequeue buffer");
        close(fd);
        return EXIT_FAILURE;
    }

    // TODO: Convert YUYV to RGB24 and apply box blur filter

    struct jpeg_compress_struct cinfo;
    struct jpeg_error_mgr jerr;
    cinfo.err = jpeg_std_error(&jerr);
    jpeg_create_compress(&cinfo);

    char filename[256];
    time_t t = time(NULL);
    struct tm *tm = localtime(&t);
    strftime(filename, sizeof(filename), OUTPUT_FILENAME, tm);

    FILE *file = fopen(filename, "wb");
    if (!file) {
        perror("Failed to open output file");
        close(fd);
        return EXIT_FAILURE;
    }

    jpeg_stdio_dest(&cinfo, file);
    cinfo.image_width = WIDTH;
    cinfo.image_height = HEIGHT;
    cinfo.input_components = 3;
    cinfo.in_color_space = JCS_RGB;

    jpeg_set_defaults(&cinfo);
    jpeg_set_quality(&cinfo, 75, TRUE);

    jpeg_start_compress(&cinfo, TRUE);

    // TODO: Write the RGB24 data to the JPEG file

    jpeg_finish_compress(&cinfo);
    fclose(file);
    jpeg_destroy_compress(&cinfo);

    if (ioctl(fd, VIDIOC_QBUF, &buf) < 0) {
        perror("Failed to queue buffer");
        close(fd);
        return EXIT_FAILURE;
    }

    if (ioctl(fd, VIDIOC_STREAMOFF, &type) < 0) {
        perror("Failed to stop streaming");
        close(fd);
        return EXIT_FAILURE;
    }

    for (int i = 0; i < req.count; i++) {
        if (munmap(mmap_ptrs[i], buf.length) < 0) {
            perror("Failed to munmap buffer");
            close(fd);
            return EXIT_FAILURE;
        }
    }

    close(fd);
    return EXIT_SUCCESS;
}

#include <stdio.h>
#include <stdlib.h>
#include <fcntl.h>
#include <unistd.h>
#include <sys/ioctl.h>
#include <linux/videodev2.h>

int main() {
    int fd = open("/dev/video0", O_RDWR);
    if (fd < 0) {
        perror("Failed to open /dev/video0");
        return EXIT_FAILURE;
    }

    struct v4l2_capability cap;
    if (ioctl(fd, VIDIOC_QUERYCAP, &cap) < 0) {
        perror("Failed to query capabilities");
        close(fd);
        return EXIT_FAILURE;
    }

    struct v4l2_frmsizeenum frmsize;
    frmsize.index = 0;
    while (ioctl(fd, VIDIOC_ENUM_FRAMESIZES, &frmsize) == 0) {
        printf("Supported resolution: %dx%d\n", frmsize.discrete.width, frmsize.discrete.height);
        frmsize.index++;
    }

    struct v4l2_frmivalenum frmival;
    frmival.index = 0;
    while (ioctl(fd, VIDIOC_ENUM_FRAMEINTERVALS, &frmival) == 0) {
        printf("Supported frame rate: %d/%d\n", frmival.discrete.denominator, frmival.discrete.numerator);
        frmival.index++;
    }

    struct v4l2_queryctrl queryctrl;
    queryctrl.id = V4L2_CID_FOCUS_AUTO;
    if (ioctl(fd, VIDIOC_QUERYCTRL, &queryctrl) == 0) {
        printf("Autofocus is supported\n");
    } else {
        printf("Autofocus is not supported\n");
    }

    close(fd);
    return EXIT_SUCCESS;
}

#include <stdio.h>
#include <signal.h>
#include <pigpio.h>

#define PAN_PIN 4
#define TILT_PIN 5
#define UP_PIN 6
#define DOWN_PIN 7
#define LEFT_PIN 8
#define RIGHT_PIN 9
#define PAN_CENTER 1500
#define TILT_CENTER 1500
#define PAN_STEP 10
#define TILT_STEP 10

volatile sig_atomic_t stop = 0;

void sig_handler(int signum) {
    stop = 1;
}

int main() {
    if (gpioInitialise() < 0) {
        printf("Failed to initialize pigpio library\n");
        return 1;
    }

    signal(SIGINT, sig_handler);
    signal(SIGTERM, sig_handler);

    gpioSetMode(PAN_PIN, PI_OUTPUT);
    gpioSetMode(TILT_PIN, PI_OUTPUT);
    gpioSetMode(UP_PIN, PI_INPUT);
    gpioSetMode(DOWN_PIN, PI_INPUT);
    gpioSetMode(LEFT_PIN, PI_INPUT);
    gpioSetMode(RIGHT_PIN, PI_INPUT);

    gpioSetPullUpDown(UP_PIN, PI_PUD_UP);
    gpioSetPullUpDown(DOWN_PIN, PI_PUD_UP);
    gpioSetPullUpDown(LEFT_PIN, PI_PUD_UP);
    gpioSetPullUpDown(RIGHT_PIN, PI_PUD_UP);

    gpioServo(PAN_PIN, PAN_CENTER);
    gpioServo(TILT_PIN, TILT_CENTER);

    printf("Camera pan-tilt system initialized.\n");
    printf("Pan servo on GPIO%d, Tilt servo on GPIO%d\n", PAN_PIN, TILT_PIN);
    printf("Control with UP/DOWN/LEFT/RIGHT buttons\n");
    printf("Center position: Pan %d, Tilt %d\n", PAN_CENTER, TILT_CENTER);

    while (!stop) {
        if (gpioRead(UP_PIN) == 0) {
            int current = gpioGetServoPulsewidth(PAN_PIN);
            int new = current + PAN_STEP;
            if (new > 2000) new = 2000;
            gpioServo(PAN_PIN, new);
        }
        if (gpioRead(DOWN_PIN) == 0) {
            int current = gpioGetServoPulsewidth(PAN_PIN);
            int new = current - PAN_STEP;
            if (new < 1000) new = 1000;
            gpioServo(PAN_PIN, new);
        }
        if (gpioRead(LEFT_PIN) == 0) {
            int current = gpioGetServoPulsewidth(TILT_PIN);
            int new = current + TILT_STEP;
            if (new > 2000) new = 2000;
            gpioServo(TILT_PIN, new);
        }
        if (gpioRead(RIGHT_PIN) == 0) {
            int current = gpioGetServoPulsewidth(TILT_PIN);
            int new = current - TILT_STEP;
            if (new < 1000) new = 1000;
            gpioServo(TILT_PIN, new);
        }
        gpioDelay(50000); // 50 ms delay
    }

    gpioServo(PAN_PIN, 0);
    gpioServo(TILT_PIN, 0);

    gpioTerminate();

    return 0;
}

