#define MOTION_PIN 17
#define MOTION_DEBOUNCE 2
#define MOTION_CAPTURE_DIR "motion_captures"
#define MOTION_CAPTURE_QUALITY 85
#define MOTION_CAPTURE_WIDTH 640
#define MOTION_CAPTURE_HEIGHT 480
#define MOTION_UPLOAD_URL_FORMAT "http://%s:%s/upload"

static bool running = true;
static CURL *curl_handle = NULL;
static gpio_ctx_t *gpio_ctx = NULL;
static camera_manager *camera_manager_instance = NULL;
static camera *camera_instance = NULL;
static stream *stream_instance = NULL;
static framebuffer_allocator *allocator_instance = NULL;
static still_encoder *encoder_instance = NULL;
static window *capture_window = NULL;
static int motion_pin_fd = -1;
static time_t last_motion_time = 0;

static void cleanup(int exit_code) {
    if (motion_pin_fd != -1) {
        gpioTerminate();
    }
    if (curl_handle) {
        curl_easy_cleanup(curl_handle);
    }
    if (camera_instance) {
        camera_manager_instance->destroy_camera(camera_instance);
    }
    if (camera_manager_instance) {
        delete camera_manager_instance;
    }
    if (stream_instance) {
        delete stream_instance;
    }
    if (allocator_instance) {
        delete allocator_instance;
    }
    if (encoder_instance) {
        delete encoder_instance;
    }
    if (capture_window) {
        delete capture_window;
    }
    exit(exit_code);
}

static void handle_signal(int signum) {
    running = false;
}

static void take_snapshot() {
    char filename[256];
    time_t now = time(NULL);
    struct tm *now_tm = localtime(&now);
    strftime(filename, sizeof(filename), "%Y%m%d%H%M%S%z.jpg", now_tm);
    char filepath[512];
    snprintf(filepath, sizeof(filepath), "%s/%s", MOTION_CAPTURE_DIR, filename);
    FILE *file = fopen(filepath, "w");
    if (!file) {
        perror("Failed to open file for writing");
        return;
    }
    encoder_instance->encode(encoder_instance, file);
    fclose(file);
    char timestamp[128];
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%dT%H:%M:%S.%06ldZ", now_tm, (long)(now % 1000000));
    char json_payload[1024];
    snprintf(json_payload, sizeof(json_payload), "{\"filename\":\"%s\",\"timestamp\":\"%s\",\"motion\":true,\"pin\":%d}", filename, timestamp, MOTION_PIN);
    curl_easy_setopt(curl_handle, CURLOPT_POSTFIELDS, json_payload);
    curl_easy_perform(curl_handle);
}

static void motion_detected() {
    time(&last_motion_time);
    take_snapshot();
}

static void check_motion() {
    int level = gpioRead(motion_pin_fd);
    if (level == 0) {
        time_t now = time(NULL);
        if (difftime(now, last_motion_time) >= MOTION_DEBOUNCE) {
            motion_detected();
        }
    }
}

