#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <libgpiod.h>
#include <libcamera.h>

#define GPIO_PIN 17
#define IMAGE_DIR "/home/pi/images"
#define LOG_FILE "/home/pi/motion_capture.log"

static struct libcamera_context *camera_ctx;
static struct gpiod_chip *chip;
static struct gpiod_line *line;
static FILE *log_fd;

void log_event(const char *message) {
    time_t now = time(NULL);
    struct tm *t = localtime(&now);
    char timestamp[20];
    strftime(timestamp, sizeof(timestamp), "%Y%m%d_%H%M%S", t);
    fprintf(log_fd, "[%s] %s\n", timestamp, message);
    fflush(log_fd);
}

void capture_image() {
    time_t now = time(NULL);
    struct tm *t = localtime(&now);
    char filename[50];
    strftime(filename, sizeof(filename), IMAGE_DIR "/%Y%m%d_%H%M%S_%3u.jpg", t);
    char command[100];
    sprintf(command, "libcamera-still -o %s --width 640 --height 480 -q 85 --timeout 2000 --nopreview", filename);
    int ret = system(command);
    if (ret != 0) {
        log_event("Image capture failed");
    } else {
        log_event("Image captured");
    }
}

void handle_signal(int signum) {
    gpiod_line_release(line);
    gpiod_chip_close(chip);
    libcamera_context_destroy(camera_ctx);
    fclose(log_fd);
    exit(signum);
}

int main() {
    log_fd = fopen(LOG_FILE, "a");
    if (!log_fd) {
        fprintf(stderr, "Failed to open log file\n");
        return 1;
    }

    camera_ctx = libcamera_context_create();
    if (!camera_ctx) {
        fprintf(stderr, "Failed to create camera context\n");
        return 1;
    }

    chip = gpiod_chip_open("/dev/gpiochip0");
    if (!chip) {
        fprintf(stderr, "Failed to open GPIO chip\n");
        return 1;
    }

    line = gpiod_chip_get_line(chip, GPIO_PIN);
    if (!line) {
        fprintf(stderr, "Failed to get GPIO line\n");
        return 1;
    }

    struct gpiod_line_request request = {
        .consumer = "motion_sensor",
        .request_type = GPIOD_LINE_REQUEST_DIRECTION_BOTH,
        .flags = GPIOD_LINE_REQUEST_FLAG_BIAS_PULL_UP,
    };

    if (gpiod_line_request(line, &request) < 0) {
        fprintf(stderr, "Failed to request GPIO line\n");
        return 1;
    }

    signal(SIGINT, handle_signal);
    signal(SIGTERM, handle_signal);

    while (1) {
        struct gpiod_line_event event;
        int ret = gpiod_line_event_wait(line, &event);
        if (ret < 0) {
            log_event("Failed to wait for GPIO event");
            continue;
        }

        if (event.event_type == GPIOD_LINE_EVENT_RISING_EDGE) {
            log_event("Motion detected");
            capture_image();
        }
    }

    return 0;
}

