#include <unistd.h>
#include <sys/ioctl.h>
#include <sys/mman.h>
#include <sys/select.h>
#include <linux/videodev2.h>

#define CAMERA_DEVICE "/dev/video0"
#define CROPPED_FILE "cropped.yuv"
#define CROP_X 100
#define CROP_Y 50
#define CROP_WIDTH 200
#define CROP_HEIGHT 150

static int camera_fd;
static struct v4l2_buffer buf;
static uint8_t *buffer;
static int stop_requested = 0;

static void sig_handler(int signum) {
    stop_requested = 1;
}

int main() {
    struct v4l2_capability cap;
    struct v4l2_format fmt;
    struct v4l2_requestbuffers req;
    struct v4l2_buffer buf;
    int ret;

    camera_fd = open(CAMERA_DEVICE, O_RDWR);
    if (camera_fd < 0) {
        perror("Failed to open camera device");
        return EXIT_FAILURE;
    }

    ret = ioctl(camera_fd, VIDIOC_QUERYCAP, &cap);
    if (ret < 0) {
        perror("Failed to query camera capabilities");
        goto cleanup;
    }

    memset(&fmt, 0, sizeof(fmt));
    fmt.type = V4L2_BUF_TYPE_VIDEO_CAPTURE;
    fmt.fmt.pix.width = 640;
    fmt.fmt.pix.height = 480;
    fmt.fmt.pix.pixelformat = V4L2_PIX_FMT_YUYV;
    fmt.fmt.pix.field = V4L2_FIELD_NONE;

    ret = ioctl(camera_fd, VIDIOC_S_FMT, &fmt);
    if (ret < 0) {
        perror("Failed to set format");
        goto cleanup;
    }

    memset(&req, 0, sizeof(req));
    req.count = 1;
    req.type = V4L2_BUF_TYPE_VIDEO_CAPTURE;
    req.memory = V4L2_MEMORY_MMAP;

    ret = ioctl(camera_fd, VIDIOC_REQBUFS, &req);
    if (ret < 0) {
        perror("Failed to request buffers");
        goto cleanup;
    }

    memset(&buf, 0, sizeof(buf));
    buf.type = V4L2_BUF_TYPE_VIDEO_CAPTURE;
    buf.memory = V4L2_MEMORY_MMAP;
    buf.index = 0;

    ret = ioctl(camera_fd, VIDIOC_QUERYBUF, &buf);
    if (ret < 0) {
        perror("Failed to query buffer");
        goto cleanup;
    }

