#include <pigpio.h>

#define PAN_PIN 17
#define TILT_PIN 18
#define PAN_MIN 500
#define PAN_MAX 2500
#define TILT_MIN 500
#define TILT_MAX 2500
#define PAN_CENTER 1500
#define TILT_CENTER 1500
#define ANGLE_STEP 5
#define MAX_ANGLE 180
#define MIN_ANGLE 0

volatile sig_atomic_t stop = 0;

void handle_sigint(int signum) {
    stop = 1;
}

int main() {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Failed to initialize pigpio\n");
        return 1;
    }

    signal(SIGINT, handle_sigint);

    if (gpioSetPWMfrequency(PAN_PIN, 50) < 0) {
        fprintf(stderr, "Failed to set PWM frequency for pan\n");
        gpioTerminate();
        return 1;
    }

    if (gpioSetPWMfrequency(TILT_PIN, 50) < 0) {
        fprintf(stderr, "Failed to set PWM frequency for tilt\n");
        gpioTerminate();
        return 1;
    }

    int pan_angle = 90;
    int tilt_angle = 90;

    gpioSetPWMrange(PAN_PIN, PAN_MAX - PAN_MIN);
    gpioSetPWMrange(TILT_PIN, TILT_MAX - TILT_MIN);

    gpioSetPWMdutycycle(PAN_PIN, PAN_CENTER);
    gpioSetPWMdutycycle(TILT_PIN, TILT_CENTER);

    while (!stop) {
        char input;
        if (scanf("%c", &input) == EOF) {
            break;
        }

        switch (input) {
            case 'q':
                stop = 1;
                break;
            case 'w':
                if (pan_angle < MAX_ANGLE) {
                    pan_angle += ANGLE_STEP;
                    gpioSetPWMdutycycle(PAN_PIN, PAN_MIN + (pan_angle * (PAN_MAX - PAN_MIN)) / MAX_ANGLE);
                }
                break;
            case 's':
                if (pan_angle > MIN_ANGLE) {
                    pan_angle -= ANGLE_STEP;
                    gpioSetPWMdutycycle(PAN_PIN, PAN_MIN + (pan_angle * (PAN_MAX - PAN_MIN)) / MAX_ANGLE);
                }
                break;
            case 'a':
                if (tilt_angle < MAX_ANGLE) {
                    tilt_angle += ANGLE_STEP;
                    gpioSetPWMdutycycle(TILT_PIN, TILT_MIN + (tilt_angle * (TILT_MAX - TILT_MIN)) / MAX_ANGLE);
                }
                break;
            case 'd':
                if (tilt_angle > MIN_ANGLE) {
                    tilt_angle -= ANGLE_STEP;
                    gpioSetPWMdutycycle(TILT_PIN, TILT_MIN + (tilt_angle * (TILT_MAX - TILT_MIN)) / MAX_ANGLE);
                }
                break;
            default:
                break;
        }

        usleep(100000);
    }

    gpioSetPWMdutycycle(PAN_PIN, PAN_CENTER);
    gpioSetPWMdutycycle(TILT_PIN, TILT_CENTER);

    gpioTerminate();

    return 0;
}

