void handle_signal(int signum) {
    stop = 1;
}

void pulse_count_callback(int gpio, uint32_t tick, void *userdata) {
    pulse_count++;
}

int main() {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Failed to initialize pigpio\n");
        return EXIT_FAILURE;
    }

    if (signal(SIGINT, handle_signal) == SIG_ERR || signal(SIGTERM, handle_signal) == SIG_ERR) {
        fprintf(stderr, "Failed to set signal handlers\n");
        gpioTerminate();
        return EXIT_FAILURE;
    }

    if (gpioSetMode(GPIO_PIN, PI_INPUT) < 0) {
        fprintf(stderr, "Failed to set GPIO mode\n");
        gpioTerminate();
        return EXIT_FAILURE;
    }

    if (gpioSetAlertFuncEx(GPIO_PIN, pulse_count_callback, NULL) < 0) {
        fprintf(stderr, "Failed to set alert function\n");
        gpioTerminate();
        return EXIT_FAILURE;
    }

    int i2c_handle = i2cOpen(1, 0x27, 0);
