#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <signal.h>
#include <time.h>
#include <pigpio.h>

#define SENSOR_ADDRESS 0x4C
#define I2C_BUS 1
#define REG_ADDRESS 0x0D
#define LOG_FILE_NAME "depth_log.csv"
#define SAMPLE_INTERVAL 100 // milliseconds

volatile sig_atomic_t stop = 0;

void signal_handler(int signum) {
    stop = 1;
}

int main() {
    FILE *log_file;
    int i2c_handle;
    uint16_t distance;
    struct timespec sleep_time = {0, SAMPLE_INTERVAL * 1000000};

    signal(SIGINT, signal_handler);

    if (gpioInitialise() < 0) {
        fprintf(stderr, "Failed to initialize pigpio\n");
        return EXIT_FAILURE;
    }

    i2c_handle = i2cOpen(I2C_BUS, SENSOR_ADDRESS, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Failed to open I2C bus\n");
        gpioTerminate();
        return EXIT_FAILURE;
    }

    log_file = fopen(LOG_FILE_NAME, "a");
    if (!log_file) {
        fprintf(stderr, "Failed to open log file\n");
        i2cClose(i2c_handle);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    // Write register address
    if (i2cWriteByteData(i2c_handle, REG_ADDRESS) < 0) {
        fprintf(stderr, "Failed to write register address\n");
        fclose(log_file);
        i2cClose(i2c_handle);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    while (!stop) {
        // Read two bytes in big-endian order
        if (i2cReadByteData(i2c_handle, &distance) < 0) {
            fprintf(stderr, "Failed to read distance\n");
            distance = -1;
        }

        // Log timestamped distance
        if (log_file == NULL) {
            log_file = fopen(LOG_FILE_NAME, "a");
            if (!log_file) {
                fprintf(stderr, "Failed to open log file\n");
                i2cClose(i2c_handle);
                gpioTerminate();
                return EXIT_FAILURE;
            }
            fprintf(log_file, "Timestamp,Distance\n");
        }
        fprintf(log_file, "%ld,%d\n", time(NULL), distance);

        // Sleep for the sample interval
        nanosleep(&sleep_time, NULL);
    }

    fclose(log_file);
    i2cClose(i2c_handle);
    gpioTerminate();

    return EXIT_SUCCESS;
}

