#define SI1145_PART_ID 0x45
#define SI1145_COMMAND 0x18
#define SI1145_PROX_DATA 0x22
#define SI1145_AMB_DATA 0x20

volatile sig_atomic_t stop = 0;

void sigint_handler(int signum) {
    stop = 1;
}

int main() {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Failed to initialize pigpio\n");
        return EXIT_FAILURE;
    }

    int i2c_handle = i2cOpen(1, 0x60, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Failed to open I2C bus\n");
        gpioTerminate();
        return EXIT_FAILURE;
    }

    uint8_t part_id;
    if (i2cReadByteData(i2c_handle, SI1145_PART_ID, &part_id) < 0) {
        fprintf(stderr, "Failed to read PART ID\n");
        i2cClose(i2c_handle);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    if (part_id != SI1145_PART_ID) {
        fprintf(stderr, "Invalid PART ID: 0x%02X\n", part_id);
        i2cClose(i2c_handle);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    if (i2cWriteByteData(i2c_handle, SI1145_COMMAND, SI1145_COMMAND) < 0) {
        fprintf(stderr, "Failed to initialize sensor\n");
        i2cClose(i2c_handle);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    FILE *log_file = fopen("biometric_log.txt", "w");
    if (log_file == NULL) {
        fprintf(stderr, "Failed to open log file\n");
        i2cClose(i2c_handle);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    signal(SIGINT, sigint_handler);

    while (!stop) {
        uint16_t prox_data, amb_data;
        if (i2cReadWordData(i2c_handle, SI1145_PROX_DATA, &prox_data) < 0 ||
            i2cReadWordData(i2c_handle, SI1145_AMB_DATA, &amb_data) < 0) {
            fprintf(stderr, "Failed to read sensor data\n");
            continue;
        }

        time_t now = time(NULL);
        struct tm *time_info = localtime(&now);
        char timestamp[20];
        strftime(timestamp, sizeof(timestamp), "%Y-%m-%dT%H:%M:%S", time_info);

        fprintf(log_file, "%s Proximity: %u Ambient: %u\n", timestamp, prox_data, amb_data);

        usleep(500000);
    }

    fclose(log_file);
    i2cClose(i2c_handle);
    gpioTerminate();

    return EXIT_SUCCESS;
}

#include <stdio.h>
#include <stdlib.h>
#include <string.h>
