#include <gpiod.h>
#include <signal.h>

#define SENSOR_LINE 4
#define LED_LINE 17
#define POLL_INTERVAL 100
#define LED_BLINK_DURATION 100
#define LOG_FILE "proximity.log"

static struct gpiod_chip *chip;
static struct gpiod_line *sensor_line;
static struct gpiod_line *led_line;
static int log_file_fd = -1;
static int last_sensor_state = 1;

static void cleanup() {
    if (led_line) gpiod_line_release(led_line);
    if (sensor_line) gpiod_line_release(sensor_line);
    if (chip) gpiod_chip_close(chip);
    if (log_file_fd != -1) close(log_file_fd);
}

static void log_event() {
    time_t now = time(NULL);
    struct tm *utc_time = gmtime(&now);
    char buffer[26];
    strftime(buffer, sizeof(buffer), "%Y-%m-%dT%H:%M:%SZ", utc_time);
    dprintf(log_file_fd, "%s Object detected\n", buffer);
}

static void blink_led() {
    gpiod_line_set_value(led_line, 1);
    usleep(LED_BLINK_DURATION * 1000);
    gpiod_line_set_value(led_line, 0);
}

static void handle_sensor_event() {
    int current_sensor_state = gpiod_line_get_value(sensor_line);
    if (current_sensor_state == 0 && last_sensor_state == 1) {
        log_event();
        blink_led();
    }
    last_sensor_state = current_sensor_state;
}

static void signal_handler(int signum) {
    cleanup();
    exit(signum);
}

int main() {
    struct sigaction action;
    memset(&action, 0, sizeof(action));
    action.sa_handler = signal_handler;
    sigaction(SIGINT, &action, NULL);
    sigaction(SIGTERM, &action, NULL);

    chip = gpiod_chip_open_by_name("gpiochip4");
    if (chip == NULL) {
        chip = gpiod_chip_open_by_name("gpiochip0");
    }
    if (chip == NULL) {
        fprintf(stderr, "Failed to open GPIO chip\n");
        return EXIT_FAILURE;
    }

    sensor_line = gpiod_chip_get_line(chip, SENSOR_LINE);
    if (sensor_line == NULL) {
        fprintf(stderr, "Failed to get sensor line\n");
        cleanup();
        return EXIT_FAILURE;
    }

    led_line = gpiod_chip_get_line(chip, LED_LINE);
    if (led_line == NULL) {
        fprintf(stderr, "Failed to get LED line\n");
        cleanup();
        return EXIT_FAILURE;
    }

    log_file_fd = open(LOG_FILE, O_WRONLY | O_CREAT | O_APPEND, 0644);
    if (log_file_fd == -1) {
        fprintf(stderr, "Failed to open log file\n");
        cleanup();
        return EXIT_FAILURE;
    }

    gpiod_line_request_input(sensor_line, "sensor_input");
    gpiod_line_request_output(led_line, "led_output");

    while (1) {
        handle_sensor_event();
        usleep(POLL_INTERVAL * 1000);
    }

    cleanup();
    return EXIT_SUCCESS;
}

