#define PS1_DATA_LSB 0x19
#define ALS_VIS_DATA_MSB 0x22
#define ALS_VIS_DATA_LSB 0x23
#define COMMAND 0x30
#define ALS_FORCE 0x06
#define PS_FORCE 0x07

volatile sig_atomic_t stop = 0;

void signal_handler(int signum) {
    stop = 1;
}

int main() {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialization failed\n");
        return EXIT_FAILURE;
    }

    int i2c_handle = i2cOpen(1, SI1145_ADDRESS, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Failed to open I2C bus 1\n");
        gpioTerminate();
        return EXIT_FAILURE;
    }

    FILE *log_file = fopen("biometric_data.log", "w");
    if (log_file == NULL) {
        fprintf(stderr, "Failed to open log file\n");
        i2cClose(i2c_handle);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    signal(SIGINT, signal_handler);

    uint8_t part_id;
    if (i2cReadByteData(i2c_handle, PART_ID, &part_id) < 0 || part_id != 0x45) {
        fprintf(stderr, "Failed to read PART_ID or incorrect value\n");
        fclose(log_file);
        i2cClose(i2c_handle);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    if (i2cWriteByteData(i2c_handle, HW_KEY, 0x17) < 0 ||
        i2cWriteByteData(i2c_handle, CH_LIST, 0x0F) < 0 ||
        i2cWriteByteData(i2c_handle, COMMAND, ALS_FORCE) < 0 ||
        i2cWriteByteData(i2c_handle, COMMAND, PS_FORCE) < 0) {
        fprintf(stderr, "Failed to write configuration registers\n");
        fclose(log_file);
        i2cClose(i2c_handle);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    while (!stop) {
        uint16_t ps1_data, als_vis_data;
        if (i2cReadByteData(i2c_handle, PS1_DATA_MSB, (uint8_t *)&ps1_data) < 0 ||
            i2cReadByteData(i2c_handle, PS1_DATA_LSB, (uint8_t *)&ps1_data + 1) < 0 ||
            i2cReadByteData(i2c_handle, ALS_VIS_DATA_MSB, (uint8_t *)&als_vis_data) < 0 ||
            i2cReadByteData(i2c_handle, ALS_VIS_DATA_LSB, (uint8_t *)&als_vis_data + 1) < 0) {
            fprintf(stderr, "Failed to read sensor data\n");
            break;
        }

        time_t now = time(NULL);
        struct tm *time_info = localtime(&now);
        char timestamp[20];
        strftime(timestamp, sizeof(timestamp), "%Y-%m-%dT%H:%M:%S", time_info);

        fprintf(log_file, "%s,%u,%u\n", timestamp, ps1_data, als_vis_data);
        fflush(log_file);
    }

    fclose(log_file);
    i2cClose(i2c_handle);
    gpioTerminate();
    return EXIT_SUCCESS;
}

#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <gpiod.h>

#define TRIGGER_PIN 17
#define ECHO_PIN 27
#define VOLTAGE_DIVIDER_RATIO 2.0
#define MAX_DISTANCE 400
#define MIN_DISTANCE 2
#define WATERING_DISTANCE 15
#define MEASUREMENT_INTERVAL 60
#define TIMEOUT 30

static struct gpiod_chip *chip;
static struct gpiod_line *trigger_line;
static struct gpiod_line *echo_line;
static FILE *log_file;

void cleanup() {
    gpiod_line_release(echo_line);
    gpiod_line_release(trigger_line);
    gpiod_chip_close(chip);
    fclose(log_file);
}

void handle_sigint(int signum) {
    cleanup();
    exit(0);
}

int main() {
    struct timespec start_time, end_time;
    struct timespec timeout = {0, TIMEOUT * 1000 * 1000};
    struct timespec measurement_interval = {MEASUREMENT_INTERVAL, 0};
    int distance;

    chip = gpiod_chip_open("/dev/gpiochip0");
    if (!chip) {
        fprintf(stderr, "Failed to open GPIO chip\n");
        return 1;
    }

    trigger_line = gpiod_chip_get_line(chip, TRIGGER_PIN);
    if (!trigger_line) {
        fprintf(stderr, "Failed to get trigger line\n");
        return 1;
    }

    echo_line = gpiod_chip_get_line(chip, ECHO_PIN);
    if (!echo_line) {
        fprintf(stderr, "Failed to get echo line\n");
        return 1;
    }

    log_file = fopen("distance_log.txt", "w");
    if (!log_file) {
        fprintf(stderr, "Failed to open log file\n");
        return 1;
    }

    signal(SIGINT, handle_sigint);
    signal(SIGTERM, handle_sigint);

    while (1) {
        clock_gettime(CLOCK_MONOTONIC, &start_time);

        gpiod_line_set_value(trigger_line, 1);
        nanosleep(&measurement_interval, NULL);
        gpiod_line_set_value(trigger_line, 0);

        while (gpiod_line_get_value(echo_line) == 0) {
            if (clock_gettime(CLOCK_MONOTONIC, &end_time) == -1 || end_time.tv_sec - start_time.tv_sec > timeout.tv_sec) {
                fprintf(log_file, "%ld.%09ld - Sensor timeout\n", start_time.tv_sec, start_time.tv_nsec);
                break;
            }
        }

        while (gpiod_line_get_value(echo_line) == 1) {
            if (clock_gettime(CLOCK_MONOTONIC, &end_time) == -1 || end_time.tv_sec - start_time.tv_sec > timeout.tv_sec) {
                fprintf(log_file, "%ld.%09ld - Sensor timeout\n", start_time.tv_sec, start_time.tv_nsec);
                break;
            }
        }

        distance = (int)((end_time.tv_sec - start_time.tv_sec) * 34300 / VOLTAGE_DIVIDER_RATIO / 2 * 1000);

        if (distance < MIN_DISTANCE || distance > MAX_DISTANCE) {
            fprintf(log_file, "%ld.%09ld - Invalid distance: %d\n", start_time.tv_sec, start_time.tv_nsec, distance);
        } else {
            fprintf(log_file, "%ld.%09ld - Distance: %d cm\n", start_time.tv_sec, start_time.tv_nsec, distance);
            if (distance < WATERING_DISTANCE) {
                fprintf(log_file, "%ld.%09ld - Time to water the plant!\n", start_time.tv_sec, start_time.tv_nsec);
            }
        }

        fflush(log_file);
        nanosleep(&measurement_interval, NULL);
    }

    cleanup();
    return 0;
}

#include <stdio.h>
