#include <time.h>
#include <pigpio.h>

#define SENSOR_ADDRESS 0x39
#define SENSOR_ID 0xAB
#define PROXIMITY_THRESHOLD 200
#define LOG_FILE_NAME "color_proximity_log.csv"
#define I2C_BUS 1

static int keep_running = 1;
static FILE *log_file = NULL;
static uint8_t sensor_id = 0;
static uint16_t raw_rgb = 0;
static uint8_t proximity = 0;

void signal_handler(int signum) {
    keep_running = 0;
}

int main() {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Failed to initialize pigpio\n");
        return EXIT_FAILURE;
    }

    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    int i2c_handle = i2cOpen(I2C_BUS, SENSOR_ADDRESS, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Failed to open I2C bus\n");
        gpioTerminate();
        return EXIT_FAILURE;
    }

    log_file = fopen(LOG_FILE_NAME, "w");
    if (log_file == NULL) {
        fprintf(stderr, "Failed to open log file\n");
        i2cClose(i2c_handle);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    fprintf(log_file, "Timestamp,Raw RGB,Proximity\n");

    while (keep_running) {
        // Read sensor ID
        if (i2cReadByteData(i2c_handle, 0x92) != SENSOR_ID) {
            fprintf(stderr, "Sensor ID mismatch\n");
            i2cClose(i2c_handle);
            i2c_handle = i2cOpen(I2C_BUS, SENSOR_ADDRESS, 0);
            if (i2c_handle < 0) {
                fprintf(stderr, "Failed to re-open I2C bus\n");
                gpioTerminate();
                fclose(log_file);
                return EXIT_FAILURE;
            }
            continue;
        }

        // Configure sensor
        i2cWriteByteData(i2c_handle, 0x80, 0x03);
        i2cWriteByteData(i2c_handle, 0x81, 0xDB);
        i2cWriteByteData(i2c_handle, 0x83, 0xF6);
        i2cWriteByteData(i2c_handle, 0x8E, 0x87);
        i2cWriteByteData(i2c_handle, 0xF1, 0x03);
        i2cWriteByteData(i2c_handle, 0x90, 0x01);

        // Read raw RGB and proximity
        raw_rgb = i2cReadWordData(i2c_handle, 0x96);
        proximity = i2cReadByteData(i2c_handle, 0x9C);

        // Log data if proximity exceeds threshold
        if (proximity > PROXIMITY_THRESHOLD) {
            time_t timestamp = time(NULL);
            fprintf(log_file, "%ld,%d,%d\n", timestamp, raw_rgb, proximity);
            fflush(log_file);
        }

        // Sleep for a bit
        gpioDelay(100000);
    }

    fclose(log_file);
    i2cClose(i2c_handle);
    gpioTerminate();
    return EXIT_SUCCESS;
}

