    if (i2c_fd < 0) {
        perror("Failed to open i2c device");
        return 1;
    }

    ret = ioctl(i2c_fd, I2C_SLAVE, 0x5A);
    if (ret < 0) {
        perror("Failed to set i2c slave address");
        close(i2c_fd);
        return 1;
    }

    uint8_t part_id = i2c_smbus_read_byte_data(i2c_fd, 0x00);
    if (part_id != SI1182_PART_ID) {
        fprintf(stderr, "Si1182 part ID mismatch: expected 0x%02X, got 0x%02X\n", SI1182_PART_ID, part_id);
        close(i2c_fd);
        return 1;
    }

    i2c_smbus_write_byte_data(i2c_fd, SI1182_MEAS_RATE0, 0x01); // Set measurement rate to 1 Hz
    i2c_smbus_write_byte_data(i2c_fd, SI1182_COMMAND, 0x40); // Reset and start measurement

    csv_file = fopen("heartrate.csv", "w");
    if (!csv_file) {
        perror("Failed to open CSV file");
        close(i2c_fd);
        return 1;
    }

    signal(SIGINT, sig_handler);
    signal(SIGTERM, sig_handler);

    while (running) {
        ret = i2c_smbus_read_word_data(i2c_fd, SI1182_PS_DATA0);
        if (ret < 0) {
            perror("Failed to read proximity data");
            continue;
        }

        proximity_data = (uint16_t)ret;

        ret = i2c_smbus_read_word_data(i2c_fd, SI1182_PS_DATA1);
        if (ret < 0) {
            perror("Failed to read proximity data");
            continue;
        }

        proximity_data |= (uint16_t)ret << 16;

        clock_gettime(CLOCK_REALTIME, &ts);
        fprintf(csv_file, "%ld.%09ld,%d\n", ts.tv_sec, ts.tv_nsec, proximity_data >> 16);

        fflush(csv_file);
    }

    fclose(csv_file);
    close(i2c_fd);

    return 0;
}

