#define VL53L0X_ADDRESS 0x29
#define SYSRANGE_START 0x00
#define RESULT_INTERRUPT_STATUS 0x13
#define RESULT_RANGE_STATUS 0x14
#define SYSTEM_INTERRUPT_CLEAR 0x0B

volatile sig_atomic_t stop = 0;

void signal_handler(int signum) {
    stop = 1;
}

int main() {
    FILE *log_file;
    int i2c_handle, gpio_handle, distance;
    struct timespec start_time, end_time;
    uint32_t elapsed_time;

    gpio_handle = piHiPri(99);
    if (gpio_handle < 0) {
        printf("Failed to set high priority for GPIO\n");
        return -1;
    }

    i2c_handle = i2cOpen(1, VL53L0X_ADDRESS, 0);
    if (i2c_handle < 0) {
        printf("Failed to open I2C bus\n");
        return -1;
    }

    log_file = fopen("distance_log.txt", "w");
    if (log_file == NULL) {
        printf("Failed to open log file\n");
        return -1;
    }

    signal(SIGINT, signal_handler);

    gpioSetMode(17, PI_INPUT);
    gpioSetPullUpDown(17, PI_PUD_UP);

    while (!stop) {
        if (gpioWaitForEdge(17, RISING_EDGE) < 0) {
            printf("Failed to wait for rising edge\n");
            break;
        }

        clock_gettime(CLOCK_MONOTONIC, &start_time);

        if (i2cWriteByteData(i2c_handle, SYSRANGE_START, 0x01) < 0) {
            printf("Failed to write to I2C device\n");
            break;
        }

        while (1) {
            if (i2cReadByteData(i2c_handle, RESULT_INTERRUPT_STATUS) & 0x01) {
                break;
            }

            if (clock_gettime(CLOCK_MONOTONIC, &end_time) < 0) {
                printf("Failed to get time\n");
                break;
            }

            elapsed_time = (end_time.tv_sec - start_time.tv_sec) * 1000 + (end_time.tv_nsec - start_time.tv_nsec) / 1000000;

            if (elapsed_time > 100) {
                printf("Timeout while waiting for interrupt\n");
                break;
            }
        }

        if (i2cReadI2CBlockData(i2c_handle, RESULT_RANGE_STATUS, 14) < 0) {
            printf("Failed to read from I2C device\n");
            break;
        }

        distance = i2cReadByteData(i2c_handle, RESULT_RANGE_STATUS + 10) << 8 | i2cReadByteData(i2c_handle, RESULT_RANGE_STATUS + 11);

        if (i2cWriteByteData(i2c_handle, SYSTEM_INTERRUPT_CLEAR, 0x01) < 0) {
            printf("Failed to write to I2C device\n");
            break;
        }

        clock_gettime(CLOCK_MONOTONIC, &end_time);
        elapsed_time = (end_time.tv_sec - start_time.tv_sec) * 1000 + (end_time.tv_nsec - start_time.tv_nsec) / 1000000;

        fprintf(log_file, "%ld,%d\n", elapsed_time, distance);
    }

    fclose(log_file);
    i2cClose(i2c_handle);
    gpioTerminate();

    return 0;
}

