#define GPIO_LED 17
#define DISTANCE_THRESHOLD 20

volatile sig_atomic_t stop = 0;

void signal_handler(int signum) {
    stop = 1;
}

int main() {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Failed to initialize pigpio library\n");
        return EXIT_FAILURE;
    }

    if (signal(SIGINT, signal_handler) == SIG_ERR || signal(SIGTERM, signal_handler) == SIG_ERR) {
        fprintf(stderr, "Failed to set signal handler\n");
        gpioTerminate();
        return EXIT_FAILURE;
    }

    int i2c_handle = i2cOpen(I2C_BUS, I2C_ADDRESS, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Failed to open I2C bus\n");
        gpioTerminate();
        return EXIT_FAILURE;
    }

    int gpio_led = gpioOpen(GPIO_LED, PI_OUTPUT, 0);
    if (gpio_led < 0) {
        fprintf(stderr, "Failed to open GPIO LED\n");
        i2cClose(i2c_handle);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    FILE *log_file = fopen("distance_log.txt", "w");
    if (log_file == NULL) {
        fprintf(stderr, "Failed to open log file\n");
        gpioClose(gpio_led);
        i2cClose(i2c_handle);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    while (!stop) {
        uint8_t buffer[2];
        if (i2cReadFile(i2c_handle, buffer, 2) != 2) {
            fprintf(stderr, "Failed to read from I2C sensor\n");
            break;
        }

        int distance = (buffer[0] << 8) | buffer[1];
        if (distance < 0) {
            fprintf(stderr, "Invalid distance measurement\n");
            break;
        }

        time_t now = time(NULL);
        struct tm *time_info = localtime(&now);
        char time_str[20];
        strftime(time_str, sizeof(time_str), "%Y-%m-%dT%H:%M:%S", time_info);

        fprintf(log_file, "%s: %d cm\n", time_str, distance);
        fflush(log_file);

        if (distance < DISTANCE_THRESHOLD) {
            gpioWrite(gpio_led, PI_HIGH);
        } else {
            gpioWrite(gpio_led, PI_LOW);
        }

        sleep(100);
    }

    fclose(log_file);
    gpioClose(gpio_led);
    i2cClose(i2c_handle);
    gpioTerminate();

    return EXIT_SUCCESS;
}

