        if (distance < threshold) {
            gpioWrite(led, 1);
        } else {
            gpioWrite(led, 0);
        }

        nanosleep((const struct timespec[]){{0, 50000000L}}, NULL);
    }

    fclose(log_file);
    cleanup(EXIT_SUCCESS);
}

