            return 1;
        }

        int distance = (response_frame[11] << 8) | response_frame[12];
        distance_sum += distance;
        distance_count++;

        clock_gettime(CLOCK_MONOTONIC, &current_time);
        if (current_time.tv_sec - start_time.tv_sec >= 1) {
            int average_distance = distance_sum / distance_count;
            if (average_distance < 1000) {
                fprintf(log_file, "Intrusion detected at %ld.%09ld with average distance %d mm\n",
                        current_time.tv_sec, current_time.tv_nsec, average_distance);
                fflush(log_file);
            }
            distance_sum = 0;
            distance_count = 0;
            clock_gettime(CLOCK_MONOTONIC, &start_time);
        }

        usleep(CYCLE_DELAY_MS * 1000); // Wait for the next cycle
    }

    return 0;
}

#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <errno.h>
#include <signal.h>
#include <pigpio.h>

#define VL53L0X_REG_IDENTIFICATION_MODEL_ID 0xC0
#define VL53L0X_REG_RESULT_INTERRUPT_STATUS 0x13
#define VL53L0X_REG_RESULT_RANGE_STATUS 0x14
#define VL53L0X_REG_SYSTEM_INTERRUPT_CLEAR 0x0B
#define VL53L0X_REG_SYSRANGE_START 0x00

volatile sig_atomic_t stop = 0;

void signal_handler(int signum) {
    stop = 1;
}

int main() {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Failed to initialize pigpio: %s\n", strerror(errno));
        return EXIT_FAILURE;
    }

    struct timespec ts = {0, 500000000}; // 500 ms

    int i2c = i2cOpen(1, 0x29, 0);
    if (i2c < 0) {
        fprintf(stderr, "Failed to open I2C device: %s\n", strerror(errno));
        gpioTerminate();
        return EXIT_FAILURE;
    }

    uint8_t model_id;
    if (i2cReadByteData(i2c, VL53L0X_REG_IDENTIFICATION_MODEL_ID, &model_id) < 0) {
        fprintf(stderr, "Failed to read model ID: %s\n", strerror(errno));
        gpioTerminate();
        i2cClose(i2c);
        return EXIT_FAILURE;
    }

    if (model_id != 0xEE) {
        fprintf(stderr, "Invalid model ID: 0x%X\n", model_id);
        gpioTerminate();
        i2cClose(i2c);
        return EXIT_FAILURE;
    }

    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    while (!stop) {
        if (i2cWriteByteData(i2c, VL53L0X_REG_SYSRANGE_START, 0x01) < 0) {
            fprintf(stderr, "Failed to start measurement: %s\n", strerror(errno));
            continue;
        }

        uint8_t status;
        while (1) {
            if (i2cReadByteData(i2c, VL53L0X_REG_RESULT_INTERRUPT_STATUS, &status) < 0) {
                fprintf(stderr, "Failed to read interrupt status: %s\n", strerror(errno));
                break;
            }

            if (status & 0x01) {
                uint16_t distance;
                if (i2cReadWordData(i2c, VL53L0X_REG_RESULT_RANGE_STATUS, &distance) < 0) {
                    fprintf(stderr, "Failed to read distance: %s\n", strerror(errno));
                    break;
                }

                if (i2cWriteByteData(i2c, VL53L0X_REG_SYSTEM_INTERRUPT_CLEAR, 0x01) < 0) {
                    fprintf(stderr, "Failed to clear interrupt: %s\n", strerror(errno));
                    break;
                }

                time_t now = time(NULL);
                struct tm *t = localtime(&now);
                char buffer[26];
                strftime(buffer, sizeof(buffer), "%Y-%m-%d %H:%M:%S", t);
                printf("%s Distance: %u mm\n", buffer, distance);
                break;
            }

            nanosleep(&ts, NULL);
        }
    }

    gpioTerminate();
    i2cClose(i2c);
    return EXIT_SUCCESS;
}

#include <stdio.h>
