#define SI1182_ADDRESS 0x39
#define SI1182_CONFIG 0x18
#define SI1182_IRQ_STATUS 0x25
#define SI1182_PROXIMITY_RESULT_LSB 0x2A
#define SI1182_PROXIMITY_RESULT_MSB 0x2B

volatile sig_atomic_t stop = 0;

void sigint_handler(int signum) {
    stop = 1;
}

int main() {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialization failed\n");
        return 1;
    }

    signal(SIGINT, sigint_handler);

    int i2c_handle = i2cOpen(1, SI1182_ADDRESS, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Failed to open I2C bus\n");
        gpioTerminate();
        return 1;
    }

    uint8_t config_data = 0x01;
    if (i2cWriteByteData(i2c_handle, SI1182_CONFIG, config_data) < 0) {
        fprintf(stderr, "Failed to write to CONFIG register\n");
        i2cClose(i2c_handle);
        gpioTerminate();
        return 1;
    }

    while (!stop) {
        uint8_t irq_status = i2cReadByteData(i2c_handle, SI1182_IRQ_STATUS);
        if (irq_status < 0) {
            fprintf(stderr, "Failed to read IRQ status register\n");
            break;
        }

        if (irq_status & 0x01) {
            uint16_t proximity_result = i2cReadWordData(i2c_handle, SI1182_PROXIMITY_RESULT_LSB);
            if (proximity_result < 0) {
                fprintf(stderr, "Failed to read proximity result\n");
                break;
            }

