}

#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <fcntl.h>
#include <unistd.h>
#include <sys/ioctl.h>
#include <linux/i2c-dev.h>
#include <signal.h>
#include <time.h>

#define MLX75030_ADDRESS 0x4C
#define MLX75030_DISTANCE_REG 0x00
#define MLX75030_COUNTS_PER_MM 0.125

int i2c_fd = -1;

void close_i2c_on_exit(int status) {
    if (i2c_fd != -1) {
        close(i2c_fd);
    }
    exit(status);
}

void handle_sigint(int signum) {
    printf("\nReceived SIGINT, exiting...\n");
    close_i2c_on_exit(0);
}

int main() {
    struct sigaction action;
    memset(&action, 0, sizeof(action));
    action.sa_handler = handle_sigint;
    sigaction(SIGINT, &action, NULL);
    sigaction(SIGTERM, &action, NULL);

    if ((i2c_fd = open("/dev/i2c-1", O_RDWR)) < 0) {
        perror("Failed to open i2c device");
        close_i2c_on_exit(1);
    }

    if (ioctl(i2c_fd, I2C_SLAVE, MLX75030_ADDRESS) < 0) {
        perror("Failed to set i2c slave address");
        close_i2c_on_exit(1);
    }

    uint8_t buffer[2];
    struct timespec req, rem;
    req.tv_sec = 0;
    req.tv_nsec = 500000000; // 500 ms

    while (1) {
        if (read(i2c_fd, buffer, 2) != 2) {
            perror("Failed to read from i2c device");
            continue;
        }

        uint16_t distance_counts = (buffer[1] << 8) | buffer[0];
        float distance_mm = distance_counts * MLX75030_COUNTS_PER_MM;

        printf("Distance: %.2f mm\n", distance_mm);

        if (nanosleep(&req, &rem) == -1) {
            perror("Failed to sleep");
            continue;
        }
    }

    return 0;
}

