#include <stdio.h>
#include <signal.h>
#include <pigpio.h>

#define TRIG 17
#define ECHO 18
#define MAX_RANGE_US 38000 // 38 ms in microseconds
#define MAX_RANGE_CM 1000 // Maximum range of HC-SR04 in cm

volatile sig_atomic_t stop = 0;

void sig_handler(int signum) {
    stop = 1;
}

int main() {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialization failed\n");
        return 1;
    }

    signal(SIGINT, sig_handler);
    signal(SIGTERM, sig_handler);

    if (gpioSetMode(TRIG, PI_OUTPUT) < 0) {
        fprintf(stderr, "Failed to set TRIG GPIO mode\n");
        gpioTerminate();
        return 1;
    }

    if (gpioSetMode(ECHO, PI_INPUT) < 0) {
        fprintf(stderr, "Failed to set ECHO GPIO mode\n");
        gpioTerminate();
        return 1;
    }

    uint32_t start_tick, end_tick, pulse_width, distance_cm;
    while (!stop) {
        gpioWrite(TRIG, PI_HIGH);
        usleep(10); // 10 microseconds
        gpioWrite(TRIG, PI_LOW);

        start_tick = gpioTick();
        while (gpioRead(ECHO) == PI_LOW && (gpioTick() - start_tick) < 200000); // Wait for echo to go high

        if (gpioRead(ECHO) == PI_HIGH) {
            end_tick = gpioTick();
            while (gpioRead(ECHO) == PI_HIGH && (gpioTick() - end_tick) < 200000); // Wait for echo to go low

            pulse_width = end_tick - start_tick;
            if (pulse_width > 0 && pulse_width <= MAX_RANGE_US) {
                distance_cm = (pulse_width * 0.0343) / 2;
                printf("Distance: %d cm\n", distance_cm);
            } else {
                printf("Invalid pulse width\n");
            }
        } else {
            printf("Echo timeout\n");
        }

        sleep(1); // Wait for 1 second
    }

    gpioTerminate();
    return 0;
}

