#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <libgpiod.h>

#define SENSOR_PIN 17
#define BUZZER_PIN 18
#define LOG_FILE "obstacle_log.txt"
#define POLL_INTERVAL_MS 100

static struct gpiod_chip *chip;
static struct gpiod_line *sensor_line;
static struct gpiod_line *buzzer_line;
static int running = 1;

void handle_signal(int signum) {
    running = 0;
}

int main() {
    struct sigaction action;
    memset(&action, 0, sizeof(struct sigaction));
    action.sa_handler = handle_signal;
    sigaction(SIGINT, &action, NULL);
    sigaction(SIGTERM, &action, NULL);

    chip = gpiod_chip_open("/dev/gpiochip0");
    if (!chip) {
        fprintf(stderr, "Failed to open GPIO chip\n");
        return EXIT_FAILURE;
    }

    sensor_line = gpiod_chip_get_line(chip, SENSOR_PIN);
    if (!sensor_line) {
        fprintf(stderr, "Failed to get sensor line\n");
        goto cleanup_chip;
    }

    buzzer_line = gpiod_chip_get_line(chip, BUZZER_PIN);
    if (!buzzer_line) {
        fprintf(stderr, "Failed to get buzzer line\n");
        goto cleanup_chip;
    }

    if (gpiod_line_request_input(sensor_line, "sensor") < 0) {
        fprintf(stderr, "Failed to request sensor line as input\n");
        goto cleanup_chip;
    }

    if (gpiod_line_request_output(buzzer_line, "buzzer", 0) < 0) {
        fprintf(stderr, "Failed to request buzzer line as output\n");
        goto cleanup_chip;
    }

    FILE *log_file = fopen(LOG_FILE, "w");
    if (!log_file) {
        fprintf(stderr, "Failed to open log file\n");
        goto cleanup_chip;
    }

    while (running) {
        struct timespec ts = {0, POLL_INTERVAL_MS * 1000 * 1000};
        nanosleep(&ts, NULL);

        int sensor_value;
        if (gpiod_line_read(sensor_line, &sensor_value) < 0) {
            fprintf(stderr, "Failed to read sensor line\n");
            continue;
        }

        int buzzer_value = sensor_value ? 1 : 0;
        if (gpiod_line_set_value(buzzer_line, buzzer_value) < 0) {
            fprintf(stderr, "Failed to set buzzer line\n");
            continue;
        }

        time_t now = time(NULL);
        struct tm *timeinfo = localtime(&now);
        char timestamp[20];
        strftime(timestamp, sizeof(timestamp), "%Y-%m-%dT%H:%M:%S", timeinfo);

        fprintf(log_file, "%s: Sensor value: %d, Buzzer value: %d\n", timestamp, sensor_value, buzzer_value);
        fflush(log_file);
    }

    fclose(log_file);

cleanup_chip:
    gpiod_line_release(sensor_line);
    gpiod_line_release(buzzer_line);
    gpiod_chip_close(chip);

    return EXIT_SUCCESS;
}

#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <pigpio.h>
#include <errno.h>

#define SENSOR_ADDRESS 0x69
#define SENSOR_REG_HIGH 0x31
#define SENSOR_REG_LOW 0x32
#define GPIO_TRIGGER 17
#define SAMPLE_INTERVAL 100 // ms
#define MIN_DISTANCE 10.0 // cm

static int keep_running = 1;
static FILE *log_file = NULL;

void signal_handler(int signum) {
    if (signum == SIGINT || signum == SIGTERM) {
        keep_running = 0;
    }
}

int read_distance(pigpio_handle_t i2c) {
    uint8_t high_byte, low_byte;
    int16_t distance;

    if (i2cReadByteData(i2c, SENSOR_REG_HIGH, &high_byte) < 0) {
        return -1;
    }
    if (i2cReadByteData(i2c, SENSOR_REG_LOW, &low_byte) < 0) {
        return -1;
    }
    distance = (high_byte << 8) | low_byte;
    return distance;
}

int main() {
    struct timespec sleep_time = {0, SAMPLE_INTERVAL * 1000000};
    pigpio_handle_t i2c, gpio;
    int distance;

    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    if ((i2c = i2cOpen(1, SENSOR_ADDRESS, 0)) < 0) {
        fprintf(stderr, "Failed to open I2C bus 1: %s\n", strerror(errno));
        return EXIT_FAILURE;
    }

    if ((gpio = gpioInitialise()) < 0) {
        fprintf(stderr, "Failed to initialize GPIO: %s\n", strerror(errno));
        return EXIT_FAILURE;
    }

    if ((log_file = fopen("distance_log.txt", "w")) == NULL) {
        fprintf(stderr, "Failed to open log file: %s\n", strerror(errno));
        return EXIT_FAILURE;
    }

    gpioSetMode(gpio, GPIO_TRIGGER, PI_OUTPUT);

    while (keep_running) {
        if ((distance = read_distance(i2c)) < 0) {
            fprintf(stderr, "Failed to read distance: %s\n", strerror(errno));
            keep_running = 0;
            continue;
        }

        if (distance < MIN_DISTANCE) {
            gpioWrite(gpio, GPIO_TRIGGER, PI_HIGH);
            usleep(1000); // 1 ms
            gpioWrite(gpio, GPIO_TRIGGER, PI_LOW);
        }

        time_t now = time(NULL);
        struct tm *timeinfo = localtime(&now);
        char timestamp[20];
        strftime(timestamp, sizeof(timestamp), "%Y-%m-%dT%H:%M:%S", timeinfo);

        fprintf(log_file, "%s, %d cm\n", timestamp, distance);

        nanosleep(&sleep_time, NULL);
    }

    fclose(log_file);
    gpioTerminate();
    i2cClose(i2c);

    return EXIT_SUCCESS;
}

#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <signal.h>
#include <time.h>
#include <pigpio.h>
#include <errno.h>

#define VL53L1X_ADDRESS 0x29
#define VL53L1X_REG_IDENTIFICATION_MODEL_ID 0x010F
#define VL53L1X_REG_SYSTEM_MODE_START 0x007
#define VL53L1X_REG_SYSRANGE_START 0x000
#define VL53L1X_REG_RESULT_INTERRUPT_STATUS 0x013
#define VL53L1X_REG_RESULT_RANGE_STATUS 0x078
#define VL53L1X_REG_SYSTEM_INTERRUPT_CLEAR 0x014

volatile sig_atomic_t running = 1;

void signal_handler(int signum) {
    running = 0;
}

int main() {
    FILE *log_file;
    int i2c_handle, distance_mm;
    uint16_t model_id;
    uint8_t data_ready, interrupt_status;
    struct timespec ts;

    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    if ((i2c_handle = pi_i2c_open(1, VL53L1X_ADDRESS)) < 0) {
        fprintf(stderr, "Failed to open I2C bus: %s\n", strerror(-i2c_handle));
        return EXIT_FAILURE;
    }

    if (pi_i2c_read_byte_data(i2c_handle, VL53L1X_REG_IDENTIFICATION_MODEL_ID, &model_id) < 0) {
        fprintf(stderr, "Failed to read model ID: %s\n", strerror(errno));
        goto cleanup;
    }

    if (model_id != 0xEA) {
        fprintf(stderr, "Invalid model ID: 0x%X\n", model_id);
        goto cleanup;
    }

    if (pi_i2c_write_byte_data(i2c_handle, 0x0000, 0x00) < 0) {
        fprintf(stderr, "Failed to perform software reset: %s\n", strerror(errno));
        goto cleanup;
    }

    usleep(2000);

    if (pi_i2c_write_byte_data(i2c_handle, VL53L1X_REG_SYSTEM_MODE_START, 0x01) < 0) {
        fprintf(stderr, "Failed to start ranging: %s\n", strerror(errno));
        goto cleanup;
    }

    log_file = fopen("distance_log.csv", "a");
    if (!log_file) {
        fprintf(stderr, "Failed to open log file: %s\n", strerror(errno));
        goto cleanup;
    }

    if (fseek(log_file, 0, SEEK_END) < 0) {
        fprintf(stderr, "Failed to seek log file: %s\n", strerror(errno));
        goto cleanup;
    }

    if (ftell(log_file) == 0) {
        if (fprintf(log_file, "timestamp,distance_mm\n") < 0) {
            fprintf(stderr, "Failed to write header to log file: %s\n", strerror(errno));
            goto cleanup;
        }
    }

    while (running) {
        if (pi_i2c_read_byte_data(i2c_handle, VL53L1X_REG_SYSRANGE_START, &data_ready) < 0) {
            fprintf(stderr, "Failed to read start register: %s\n", strerror(errno));
            goto cleanup;
        }

        if (!(data_ready & 0x01)) {
            continue;
        }

        if (pi_i2c_read_byte_data(i2c_handle, VL53L1X_REG_RESULT_INTERRUPT_STATUS, &interrupt_status) < 0) {
            fprintf(stderr, "Failed to read interrupt status: %s\n", strerror(errno));
            goto cleanup;
        }

        if (!(interrupt_status & 0x01)) {
            continue;
        }

        if (pi_i2c_read_word_data(i2c_handle, VL53L1X_REG_RESULT_RANGE_STATUS + 10, &distance_mm) < 0) {
            fprintf(stderr, "Failed to read distance: %s\n", strerror(errno));
            goto cleanup;
        }

        if (pi_i2c_write_byte_data(i2c_handle, VL53L1X_REG_SYSTEM_INTERRUPT_CLEAR, 0x01) < 0) {
            fprintf(stderr, "Failed to clear interrupt: %s\n", strerror(errno));
            goto cleanup;
        }

        clock_gettime(CLOCK_REALTIME, &ts);

        if (fprintf(log_file, "%ld,%d\n", ts.tv_sec, distance_mm) < 0) {
            fprintf(stderr, "Failed to write distance to log file: %s\n", strerror(errno));
            goto cleanup;
        }

        fflush(log_file);

        if (distance_mm < 300) {
            printf("STOP\n");
        } else if (distance_mm < 600) {
            printf("APPROACH\n");
        } else if (distance_mm < 1200) {
            printf("SLOW\n");
        } else {
            printf("CLEAR\n");
        }
    }

    fclose(log_file);
    return EXIT_SUCCESS;

cleanup:
    fclose(log_file);
    pi_i2c_close(i2c_handle);
    return EXIT_FAILURE;
}

