    int i2c_handle = i2cOpen(I2C_BUS, I2C_ADDRESS, 0);
    if (i2c_handle < 0) {
        printf("Failed to open I2C bus\n");
        gpioTerminate();
        return EXIT_FAILURE;
    }

    gpioSetMode(LED, PI_OUTPUT);

    while (!stop) {
        uint8_t buffer[2];
        int ret = i2cReadFile(i2c_handle, buffer, 2);
        if (ret != 2) {
            printf("Failed to read from I2C sensor, retrying...\n");
            continue;
        }

        uint16_t distance = (buffer[0] << 8) | buffer[1];

        float frequency;
        if (distance < 50) {
            frequency = 10.0;
        } else if (distance > 500) {
            frequency = 1.0;
        } else {
            frequency = 50.0 / distance;
        }

        gpioPWM(LED, (int)(frequency * 1000));

        printf("Distance: %d mm, Blink Frequency: %.2f Hz\n", distance, frequency);

        gpioDelay(10000000); // 10 ms delay
    }

    gpioPWM(LED, 0);
    gpioTerminate();
    i2cClose(i2c_handle);

    return EXIT_SUCCESS;
}

#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <unistd.h>
#include <signal.h>
#include <time.h>
#include <pigpio.h>

#define MLX75030_ADDRESS 0x70
#define MLX75030_COMMAND 0x04
#define MLX75030_DELAY 100 // microseconds
#define MLX75030_READ_LENGTH 2
#define I2C_BUS 1
#define LOG_FILE "distance_log.csv"
#define RETRY_LIMIT 5
#define RETRY_DELAY 100 // milliseconds

volatile sig_atomic_t stop_requested = 0;

void signal_handler(int signum) {
    stop_requested = 1;
}

int main() {
    FILE *log_file;
    int retry_count = 0;
    int distance;
    struct timespec ts;
    uint8_t buffer[MLX75030_READ_LENGTH];
    int i2c_handle;

    if (signal(SIGINT, signal_handler) == SIG_ERR || signal(SIGTERM, signal_handler) == SIG_ERR) {
        fprintf(stderr, "Could not set up signal handlers.\n");
        return EXIT_FAILURE;
    }

    if ((i2c_handle = pi_i2c_open(I2C_BUS, MLX75030_ADDRESS)) < 0) {
        fprintf(stderr, "Failed to open I2C bus.\n");
        return EXIT_FAILURE;
    }

    if ((log_file = fopen(LOG_FILE, "a")) == NULL) {
        fprintf(stderr, "Failed to open log file.\n");
        pi_i2c_close(i2c_handle);
        return EXIT_FAILURE;
    }

    fprintf(log_file, "timestamp,distance_cm\n");

    while (!stop_requested) {
        if (pi_i2c_write_byte_data(i2c_handle, MLX75030_COMMAND, 0) < 0) {
            fprintf(stderr, "Failed to write command to sensor.\n");
            retry_count++;
            if (retry_count >= RETRY_LIMIT) {
                pi_i2c_close(i2c_handle);
                fclose(log_file);
                return EXIT_FAILURE;
            }
            usleep(RETRY_DELAY * 1000);
            continue;
        }

        usleep(MLX75030_DELAY);

        if (pi_i2c_read_device(i2c_handle, buffer, MLX75030_READ_LENGTH) < 0) {
            fprintf(stderr, "Failed to read from sensor.\n");
            retry_count++;
            if (retry_count >= RETRY_LIMIT) {
                pi_i2c_close(i2c_handle);
                fclose(log_file);
                return EXIT_FAILURE;
            }
            usleep(RETRY_DELAY * 1000);
            continue;
        }

        distance = (buffer[0] << 8) | buffer[1];

        clock_gettime(CLOCK_REALTIME, &ts);
        fprintf(log_file, "%ld.%09ld,%d\n", ts.tv_sec, ts.tv_nsec, distance);

        retry_count = 0;
        usleep(100000); // 100 ms
    }

    pi_i2c_close(i2c_handle);
    fclose(log_file);

    return EXIT_SUCCESS;
}

#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <pigpio.h>

#define SENSOR_1 17
#define SENSOR_2 27
#define DEBOUNCE_TIME 50 // ms
#define POLLING_INTERVAL 10 // ms
#define LOG_FILE "proximity_log.txt"

FILE *log_file;
int sensor_1_state, sensor_2_state;
time_t last_sensor_1_check, last_sensor_2_check;

void log_event(int sensor_id, const char *event_type) {
    time_t now = time(NULL);
    struct tm *gmtm = gmtime(&now);
    char timestamp[20];
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%dT%H:%M:%SZ", gmtm);
    fprintf(log_file, "%s, Sensor %d, %s\n", timestamp, sensor_id, event_type);
    fflush(log_file);
}

void check_sensor(int sensor_id, int *state, time_t *last_check) {
    int current_state = gpioRead(sensor_id);
    if (current_state != *state) {
        if (current_state == 0) {
            log_event(sensor_id, "DETECTED");
        } else {
            log_event(sensor_id, "CLEARED");
        }
        *state = current_state;
        *last_check = time(NULL);
    }
}

void cleanup() {
    fclose(log_file);
    gpioTerminate();
}

int main() {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Failed to initialize pigpio\n");
        return EXIT_FAILURE;
    }

    signal(SIGINT, cleanup);
    signal(SIGTERM, cleanup);

    log_file = fopen(LOG_FILE, "w");
    if (!log_file) {
        fprintf(stderr, "Failed to open log file\n");
        gpioTerminate();
        return EXIT_FAILURE;
    }

    if (gpioSetMode(SENSOR_1, PI_INPUT) < 0 || gpioSetMode(SENSOR_2, PI_INPUT) < 0) {
        fprintf(stderr, "Failed to set sensor modes\n");
        cleanup();
        return EXIT_FAILURE;
    }

    sensor_1_state = gpioRead(SENSOR_1);
    sensor_2_state = gpioRead(SENSOR_2);

    while (1) {
        time_t now = time(NULL);
        if (now - last_sensor_1_check >= DEBOUNCE_TIME) {
            check_sensor(SENSOR_1, &sensor_1_state, &last_sensor_1_check);
        }
        if (now - last_sensor_2_check >= DEBOUNCE_TIME) {
            check_sensor(SENSOR_2, &sensor_2_state, &last_sensor_2_check);
        }
        usleep(POLLING_INTERVAL * 1000);
    }

    cleanup();
    return EXIT_SUCCESS;
}

#include <stdio.h>
