#include <linux/i2c-dev.h>
#include <time.h>
#include <signal.h>

#define I2C_BUS "/dev/i2c-1"
#define TDK_CH101_ADDRESS 0x49
#define MEAS_TRIGGER 0x04
#define MEAS_STATUS 0x06
#define DIST_HIGH 0x08
#define DIST_LOW 0x09
#define TIMEOUT 50000 // 50 ms
#define LOG_FILE "distance_log.csv"

int i2c_fd;
FILE *log_fd;

void signal_handler(int signum) {
    if (i2c_fd >= 0) close(i2c_fd);
    if (log_fd) fclose(log_fd);
    exit(signum);
}

int i2c_read_register(int reg, uint8_t *data, size_t len) {
    if (write(i2c_fd, &reg, 1) != 1) {
        perror("Failed to write register address");
        return -1;
    }
    if (read(i2c_fd, data, len) != len) {
        perror("Failed to read data");
        return -1;
    }
    return 0;
}

int main() {
    struct sigaction action;
    memset(&action, 0, sizeof(action));
    action.sa_handler = signal_handler;
    sigaction(SIGINT, &action, NULL);
    sigaction(SIGTERM, &action, NULL);

    if ((i2c_fd = open(I2C_BUS, O_RDWR)) < 0) {
        perror("Failed to open I2C bus");
        return 1;
    }

    if (ioctl(i2c_fd, I2C_SLAVE, TDK_CH101_ADDRESS) < 0) {
        perror("Failed to set I2C address");
        close(i2c_fd);
        return 1;
    }

    if (!(log_fd = fopen(LOG_FILE, "w"))) {
        perror("Failed to open log file");
        close(i2c_fd);
        return 1;
    }

    fprintf(log_fd, "timestamp,distance_mm\n");

    while (1) {
        if (write(i2c_fd, &MEAS_TRIGGER, 1) != 1) {
            perror("Failed to trigger measurement");
            continue;
        }

        uint8_t status;
        int timeout = TIMEOUT;
        while (timeout > 0) {
            if (i2c_read_register(MEAS_STATUS, &status, 1) < 0) {
                continue;
            }
            if (status & 0x01) break;
            usleep(1000);
            timeout -= 1000;
        }

        if (!(status & 0x01)) {
            fprintf(stderr, "Measurement timeout\n");
            continue;
        }

        uint8_t high, low;
        if (i2c_read_register(DIST_HIGH, &high, 1) < 0 ||
            i2c_read_register(DIST_LOW, &low, 1) < 0) {
            continue;
        }

        uint16_t distance = (high << 8) | low;

        time_t now = time(NULL);
        struct tm *timeinfo = localtime(&now);
        char timestamp[20];
        strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", timeinfo);

        fprintf(log_fd, "%s,%u\n", timestamp, distance);

        usleep(500000); // 500 ms
    }

    fclose(log_fd);
    close(i2c_fd);
    return 0;
}

