#include <stdio.h>
#include <stdlib.h>
#include <signal.h>
#include <pigpio.h>

#define MLX75030_ADDRESS 0x4C
#define I2C_BUS 1
#define RETRIES 3
#define RETRY_DELAY 10

volatile sig_atomic_t stop = 0;

void signal_handler(int signum) {
    stop = 1;
}

int main() {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Failed to initialize pigpio\n");
        return EXIT_FAILURE;
    }

    if (gpioSetSignalFunc(SIGINT, signal_handler) < 0) {
        fprintf(stderr, "Failed to set signal handler\n");
        gpioTerminate();
        return EXIT_FAILURE;
    }

    int i2c_handle = -1;
    for (int i = 0; i < RETRIES; ++i) {
        i2c_handle = gpioI2COpen(I2C_BUS, MLX75030_ADDRESS, 0);
        if (i2c_handle >= 0) {
            break;
        }
        gpioDelay(RETRY_DELAY * 1000);
    }

    if (i2c_handle < 0) {
        fprintf(stderr, "Failed to open I2C bus\n");
        gpioTerminate();
        return EXIT_FAILURE;
    }

    uint8_t buffer[2];
    while (!stop) {
        for (int i = 0; i < RETRIES; ++i) {
            int bytes_read = gpioI2CReadDevice(i2c_handle, buffer, sizeof(buffer));
            if (bytes_read == sizeof(buffer)) {
                break;
            }
            gpioDelay(RETRY_DELAY * 1000);
        }

        if (bytes_read != sizeof(buffer)) {
            fprintf(stderr, "Failed to read from sensor\n");
            break;
        }

        uint16_t distance = (buffer[0] << 8) | buffer[1];
        printf("%llu: %u\n", gpioGetMicrosecondCounter(), distance);

        gpioDelay(100 * 1000);
    }

    gpioI2CClose(i2c_handle);
    gpioTerminate();

    return EXIT_SUCCESS;
}

#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
