#include <pigpio.h>

#define VL53L4CX_ADDRESS 0x29
#define VL53L4CX_REG_SOFT_RESET 0x7FFF
#define VL53L4CX_REG_START_RANGING 0x0009
#define VL53L4CX_REG_INTERRUPT_STATUS 0x0046
#define VL53L4CX_REG_DISTANCE_HIGH 0x0096
#define VL53L4CX_REG_DISTANCE_LOW 0x0097

volatile sig_atomic_t stop_requested = 0;

void signal_handler(int signum) {
    stop_requested = 1;
}

int main() {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Failed to initialize pigpio\n");
        return EXIT_FAILURE;
    }

    if (gpioSetSignalFunc(SIGINT, signal_handler) < 0) {
        fprintf(stderr, "Failed to set signal handler for SIGINT\n");
        gpioTerminate();
        return EXIT_FAILURE;
    }

    if (gpioSetSignalFunc(SIGTERM, signal_handler) < 0) {
        fprintf(stderr, "Failed to set signal handler for SIGTERM\n");
        gpioTerminate();
        return EXIT_FAILURE;
    }

    int i2c_handle = gpioI2COpen(1, VL53L4CX_ADDRESS);
    if (i2c_handle < 0) {
        fprintf(stderr, "Failed to open I2C bus 1\n");
        gpioTerminate();
        return EXIT_FAILURE;
    }

    if (gpioI2CWriteByte(i2c_handle, VL53L4CX_REG_SOFT_RESET, 0x00) < 0) {
        fprintf(stderr, "Failed to write to register 0x7FFF\n");
        gpioI2CWriteByte(i2c_handle, VL53L4CX_REG_SOFT_RESET, 0x00);
        gpioI2CWriteByte(i2c_handle, VL53L4CX_REG_START_RANGING, 0x00);
        gpioI2CClose(i2c_handle);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    usleep(10000);

    if (gpioI2CWriteByte(i2c_handle, VL53L4CX_REG_START_RANGING, 0x00) < 0) {
        fprintf(stderr, "Failed to write to register 0x0009\n");
        gpioI2CWriteByte(i2c_handle, VL53L4CX_REG_SOFT_RESET, 0x00);
        gpioI2CWriteByte(i2c_handle, VL53L4CX_REG_START_RANGING, 0x00);
        gpioI2CClose(i2c_handle);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    while (!stop_requested) {
        uint8_t interrupt_status;
        if (gpioI2CReadByte(i2c_handle, VL53L4CX_REG_INTERRUPT_STATUS, &interrupt_status) < 0) {
            fprintf(stderr, "Failed to read interrupt status\n");
            continue;
