                gpioI2CReadByte(i2c_handle, VL53L4CX_REG_DISTANCE_LOW, (uint8_t *)&distance_low) < 0) {
                fprintf(stderr, "Failed to read distance\n");
                continue;
            }

            distance_high <<= 8;
            distance_high |= distance_low;

            struct timespec ts;
            clock_gettime(CLOCK_REALTIME, &ts);

