#include <pigpio.h>

#define VL53L1X_ADDRESS 0x29
#define VL53L1X_SOFT_RESET 0x0001
#define VL53L1X_I2C_SLAVE_DEVICE_ADDRESS 0x0001
#define VL53L1X_SYSTEM_MODE_START 0x0007
#define VL53L1X_RESULT_FINAL_CROSSTALK_CORRECTED_DISTANCE_MM 0x0096
#define VL53L1X_GPIO 1
#define BUZZER_GPIO 22
#define BUZZER_ON 1
#define BUZZER_OFF 0
#define DISTANCE_THRESHOLD 100

volatile sig_atomic_t stop = 0;

void signal_handler(int signum) {
    stop = 1;
}

int main() {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Failed to initialize pigpio library\n");
        return EXIT_FAILURE;
    }

    signal(SIGINT, signal_handler);

    int file = -1;
    int buzzer_state = BUZZER_OFF;

    while (!stop) {
        if (file < 0) {
            file = i2cOpen(VL53L1X_GPIO, VL53L1X_ADDRESS, VL53L1X_I2C_SLAVE_DEVICE_ADDRESS);
            if (file < 0) {
                fprintf(stderr, "Failed to open I2C device\n");
