            i2cWriteByte(file, VL53L1X_SOFT_RESET, 0x00);
            i2cWriteByte(file, VL53L1X_I2C_SLAVE_DEVICE_ADDRESS, VL53L1X_ADDRESS);
            i2cWriteByte(file, VL53L1X_SYSTEM_MODE_START, VL53L1X_SYSTEM_MODE_START);
        }

