#define TRIG 23
#define ECHO 24
#define SERVO 17
#define SPEED_OF_SOUND 0.0343 // m/us
#define MIN_DISTANCE 2 // cm
#define MAX_DISTANCE 400 // cm
#define MIN_SERVO_PULSE 1 // ms
#define MAX_SERVO_PULSE 2 // ms
#define TIMEOUT 50000 // us
#define LOG_FILE "sensor_data.log"

volatile sig_atomic_t stop = 0;

void signal_handler(int signum) {
    stop = 1;
}

int main() {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return EXIT_FAILURE;
    }

    if (gpioSetMode(TRIG, PI_OUTPUT) < 0) {
        fprintf(stderr, "Failed to set TRIG as output\n");
        goto cleanup;
    }

    if (gpioSetMode(ECHO, PI_INPUT) < 0) {
        fprintf(stderr, "Failed to set ECHO as input\n");
        goto cleanup;
    }

    if (gpioSetMode(SERVO, PI_OUTPUT) < 0) {
        fprintf(stderr, "Failed to set SERVO as output\n");
        goto cleanup;
    }

    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    FILE *log_file = fopen(LOG_FILE, "a");
    if (!log_file) {
        fprintf(stderr, "Failed to open log file\n");
        goto cleanup;
    }

    while (!stop) {
        gpioWrite(TRIG, PI_HIGH);
        usleep(10);
        gpioWrite(TRIG, PI_LOW);

        uint32_t start_time = timeGetTime();
        uint32_t end_time = start_time;
        while (gpioRead(ECHO) == PI_LOW && (end_time - start_time) < TIMEOUT) {
            end_time = timeGetTime();
        }

        if ((end_time - start_time) >= TIMEOUT) {
            fprintf(stderr, "Sensor timeout\n");
            continue;
        }

        uint32_t pulse_width = end_time - start_time;
        float distance = pulse_width * SPEED_OF_SOUND / 2.0;

        if (distance < MIN_DISTANCE || distance > MAX_DISTANCE) {
            fprintf(stderr, "Invalid distance: %f cm\n", distance);
            continue;
        }

        float servo_pulse = MIN_SERVO_PULSE + (MAX_SERVO_PULSE - MIN_SERVO_PULSE) * (distance - MIN_DISTANCE) / (MAX_DISTANCE - MIN_DISTANCE);
        gpioServo(SERVO, (int)(servo_pulse * 1000));

        time_t now = time(NULL);
        struct tm *timeinfo = localtime(&now);
        char timestamp[20];
        strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", timeinfo);

        fprintf(log_file, "%s, %.2f cm\n", timestamp, distance);
        fflush(log_file);
    }

    fclose(log_file);

cleanup:
    gpioServo(SERVO, 0);
    gpioTerminate();
    return EXIT_SUCCESS;
}

