#include <stdio.h>
#include <signal.h>
#include <pigpio.h>

#define TRIG 17
#define ECHO 27
#define BUZZER 22
#define SOUND_SPEED 0.0343 // cm/us
#define MAX_DISTANCE 400 // cm
#define MIN_DISTANCE 2 // cm
#define BUZZER_THRESHOLD 30 // cm

volatile int distance = 0;
volatile int buzz = 0;

void buzz_on() {
    gpioWrite(BUZZER, 1);
    buzz = 1;
}

void buzz_off() {
    gpioWrite(BUZZER, 0);
    buzz = 0;
}

void echo_callback(int gpio, int level, uint32_t tick) {
    static uint32_t start_tick = 0;
    static int rising_edge = 0;

    if (level == 1) {
        start_tick = tick;
        rising_edge = 1;
    } else if (level == 0 && rising_edge) {
        uint32_t end_tick = tick;
        uint32_t pulse_width = (end_tick > start_tick) ? (end_tick - start_tick) : (4294967295 - start_tick + end_tick);
        distance = (int)((pulse_width / 1000000.0) / SOUND_SPEED);
        if (distance < MIN_DISTANCE || distance > MAX_DISTANCE) {
            printf("Invalid reading: %d cm\n", distance);
            distance = 0;
        }
        rising_edge = 0;
    }
}

void signal_handler(int signum) {
    if (signum == SIGINT) {
        printf("Shutting down...\n");
        buzz_off();
        gpioTerminate();
        exit(0);
    }
}

int main() {
    if (gpioInitialise() < 0) {
        printf("pigpio initialization failed\n");
        return 1;
    }

    signal(SIGINT, signal_handler);

    if (gpioSetMode(TRIG, PI_OUTPUT) < 0) {
        printf("Failed to set TRIG GPIO mode\n");
        gpioTerminate();
        return 1;
    }

    if (gpioSetMode(ECHO, PI_INPUT) < 0) {
        printf("Failed to set ECHO GPIO mode\n");
        gpioTerminate();
        return 1;
    }

    if (gpioSetMode(BUZZER, PI_OUTPUT) < 0) {
        printf("Failed to set BUZZER GPIO mode\n");
        gpioTerminate();
        return 1;
    }

    if (gpioSetAlertFuncEx(ECHO, echo_callback, NULL) < 0) {
        printf("Failed to set ECHO GPIO alert function\n");
        gpioTerminate();
        return 1;
    }

    while (1) {
        gpioWrite(TRIG, 0);
        usleep(2);
        gpioWrite(TRIG, 1);
        usleep(10);
        gpioWrite(TRIG, 0);

        if (distance > 0) {
            printf("Distance: %d cm\n", distance);
            if (distance < BUZZER_THRESHOLD && !buzz) {
                buzz_on();
            } else if (distance >= BUZZER_THRESHOLD && buzz) {
                buzz_off();
            }
        }

        usleep(100000);
    }

    gpioTerminate();
    return 0;
}

#include <stdio.h>
#include <stdlib.h>
#include <string.h>
