#include <mosquitto.h>

#define VL53L1X_I2C_ADDR 0x29
#define VL53L1X_I2C_BUS 1
#define GATE_PIN 18
#define DISTANCE_THRESHOLD 20

int gate_open = 0;
FILE *log_file;

void close_gate() {
    if (gate_open) {
        gpioPWM(GATE_PIN, 0);
        gate_open = 0;
        time_t now = time(NULL);
        fprintf(log_file, "Gate closed at %s\n", ctime(&now));
        fflush(log_file);
    }
}

void open_gate() {
    if (!gate_open) {
        gpioPWM(GATE_PIN, 1024);
        gate_open = 1;
        time_t now = time(NULL);
        fprintf(log_file, "Gate opened at %s\n", ctime(&now));
        fflush(log_file);
    }
}

void on_message(struct mosquitto *mosq, void *obj, const struct mosquitto_message *msg) {
    if (strcmp(msg->topic, "gate/command") == 0) {
        if (strcmp((char *)msg->payload, "force_open") == 0) {
            open_gate();
        } else if (strcmp((char *)msg->payload, "force_close") == 0) {
            close_gate();
        } else if (strcmp((char *)msg->payload, "status_request") == 0) {
            if (gate_open) {
                mosquitto_publish(mosq, NULL, "gate/status", strlen("open"), "open", 0, false);
            } else {
                mosquitto_publish(mosq, NULL, "gate/status", strlen("closed"), "closed", 0, false);
            }
        }
    }
}

int main() {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Failed to initialize GPIO\n");
        return EXIT_FAILURE;
    }

    log_file = fopen("gate_log.txt", "w");
    if (!log_file) {
        fprintf(stderr, "Failed to open log file\n");
        gpioTerminate();
        return EXIT_FAILURE;
    }

    struct mosquitto *mosq = mosquitto_new(NULL, true, NULL);
    if (!mosq) {
        fprintf(stderr, "Failed to create mosquitto client\n");
        fclose(log_file);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    mosquitto_connect_callback_set(mosq, on_message);

    if (mosquitto_connect(mosq, "localhost", 1883, 60) != MOSQ_ERR_SUCCESS) {
        fprintf(stderr, "Failed to connect to MQTT broker\n");
        mosquitto_destroy(mosq);
        fclose(log_file);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    if (mosquitto_subscribe(mosq, NULL, "gate/command", 0) != MOSQ_ERR_SUCCESS) {
        fprintf(stderr, "Failed to subscribe to gate/command topic\n");
        mosquitto_destroy(mosq);
        fclose(log_file);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    gpioSetMode(GATE_PIN, PI_OUTPUT);
    gpioSetPWMfrequency(GATE_PIN, 50);
    gpioSetPWMrange(GATE_PIN, 1024);

    while (1) {
        int distance = gpioGetI2CDevice(VL53L1X_I2C_BUS, VL53L1X_I2C_ADDR);
        if (distance < 0) {
            fprintf(stderr, "Failed to read distance from sensor\n");
            continue;
        }

        if (distance < DISTANCE_THRESHOLD) {
            open_gate();
        } else {
            close_gate();
        }

        mosquitto_loop(mosq, -1, 1);
    }

    mosquitto_destroy(mosq);
    fclose(log_file);
    gpioTerminate();
    return EXIT_SUCCESS;
}

