#include <time.h>
#include <pigpio.h>

#define TRIG 23
#define ECHO 24
#define SOUND_SPEED 0.0343 // cm/us
#define MIN_PULSE_WIDTH 100 // microseconds
#define MAX_PULSE_WIDTH 30000 // microseconds
#define MEASURE_INTERVAL 200 // milliseconds
#define TIMEOUT_INTERVAL 60 // milliseconds

static int measure_distance(gpioContext ctx, int trig, int echo) {
    uint32_t rising_tick, falling_tick;
    uint32_t pulse_width;
    float distance;

    gpioSetMode(trig, PI_OUTPUT);
    gpioWrite(trig, PI_LOW);
    gpioDelay(10); // 10 microseconds

    gpioSetMode(trig, PI_INPUT);
    gpioSetPullUpDown(echo, PI_PUD_DOWN);

    gpioSetAlertFunc(echo, NULL);

    gpioWrite(trig, PI_HIGH);
    gpioDelay(10); // 10 microseconds
    gpioWrite(trig, PI_LOW);

    while (gpioWaitForAlert(echo, &rising_tick) != 0) {
        gpioDelay(TIMEOUT_INTERVAL);
        printf("Timeout warning: No valid echo received within %d ms\n", TIMEOUT_INTERVAL);
        continue;
    }

    while (gpioWaitForAlert(echo, &falling_tick) != 0) {
        gpioDelay(TIMEOUT_INTERVAL);
        printf("Timeout warning: No valid echo received within %d ms\n", TIMEOUT_INTERVAL);
        continue;
    }

    pulse_width = falling_tick - rising_tick;
    if (pulse_width < MIN_PULSE_WIDTH || pulse_width > MAX_PULSE_WIDTH) {
        printf("Rejected reading: pulse width %u us\n", pulse_width);
        return -1;
    }

    distance = (float)pulse_width / 2.0 * SOUND_SPEED;
    printf("Distance: %.2f cm\n", distance);

    return 0;
}

static void log_distance(FILE *log_file, const char *timestamp, float distance) {
    fprintf(log_file, "%s,%.2f\n", timestamp, distance);
    fflush(log_file);
}

static void signal_handler(int signum) {
    printf("Signal %d received, exiting...\n", signum);
    exit(signum);
}

