#define MOTOR_BACKWARD 18
#define DISTANCE_THRESHOLD_LOW 100
#define DISTANCE_THRESHOLD_HIGH 300

volatile sig_atomic_t stop_requested = false;

void handle_signal(int signum) {
    stop_requested = true;
}

int main() {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Failed to initialize pigpio\n");
        return EXIT_FAILURE;
    }

    signal(SIGINT, handle_signal);
    signal(SIGTERM, handle_signal);

    int i2c_handle = i2cOpen(1, VL53L1X_ADDRESS, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Failed to open I2C bus 1\n");
        gpioTerminate();
        return EXIT_FAILURE;
    }

    gpioSetMode(MOTOR_FORWARD, PI_OUTPUT);
    gpioSetMode(MOTOR_BACKWARD, PI_OUTPUT);

    gpioSetISRFunc(24, PI_RISING_EDGE, 0, NULL);

    while (!stop_requested) {
        // VL53L1X soft reset
        if (i2cWriteByteData(i2c_handle, VL53L1X_REG_SOFT_RESET, 0x00) < 0) {
            fprintf(stderr, "Failed to write to VL53L1X\n");
            break;
        }
        usleep(1000);

        // VL53L1X start measurement
        if (i2cWriteByteData(i2c_handle, VL53L1X_REG_START_MEASUREMENT, 0x01) < 0) {
            fprintf(stderr, "Failed to write to VL53L1X\n");
            break;
        }

        // Wait for data ready
        uint8_t data_ready = 0;
        while (data_ready == 0) {
            if (i2cReadByteData(i2c_handle, VL53L1X_REG_DATA_READY, &data_ready) < 0) {
                fprintf(stderr, "Failed to read from VL53L1X\n");
                break;
            }
            usleep(1000);
        }

        // Read distance
        uint16_t distance = 0;
        if (i2cReadWordData(i2c_handle, VL53L1X_REG_DISTANCE, &distance) < 0) {
            fprintf(stderr, "Failed to read from VL53L1X\n");
            break;
        }

        // Control motor
        if (distance < DISTANCE_THRESHOLD_LOW) {
            gpioWrite(MOTOR_FORWARD, PI_HIGH);
            gpioWrite(MOTOR_BACKWARD, PI_LOW);
            printf("Distance: %d mm, Motor: Forward\n", distance);
