            gpioWrite(MOTOR_FORWARD, PI_LOW);
            gpioWrite(MOTOR_BACKWARD, PI_HIGH);
            printf("Distance: %d mm, Motor: Backward\n", distance);
        } else {
            gpioWrite(MOTOR_FORWARD, PI_LOW);
            gpioWrite(MOTOR_BACKWARD, PI_LOW);
            printf("Distance: %d mm, Motor: Stop\n", distance);
        }
    }

    gpioTerminate();
    i2cClose(i2c_handle);
    return EXIT_SUCCESS;
}

#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <stdbool.h>
#include <unistd.h>
#include <fcntl.h>
#include <sys/ioctl.h>
#include <linux/i2c-dev.h>
#include <libgpiod.h>

#define I2C_BUS "/dev/i2c-1"
#define I2C_ADDRESS 0x5A
#define GPIO_17 17
#define GPIO_18 18
#define GPIO_27 27
#define GPIO_22 22

int main() {
    int i2c_fd, gpio_fd;
    uint8_t buffer[2];
    struct gpiod_chip *chip;
    struct gpiod_line_request request;
    struct gpiod_line *line[4];

    // Open I2C bus
    if ((i2c_fd = open(I2C_BUS, O_RDWR)) < 0) {
        perror("Failed to open I2C bus");
        return EXIT_FAILURE;
    }

    // Set I2C address
    if (ioctl(i2c_fd, I2C_SLAVE, I2C_ADDRESS) < 0) {
        perror("Failed to set I2C address");
        return EXIT_FAILURE;
    }

    // Initialize GPIO lines
    chip = gpiod_chip_open_by_name("gpiochip0");
    if (!chip) {
        perror("Failed to open GPIO chip");
        return EXIT_FAILURE;
    }

    line[0] = gpiod_chip_get_line(chip, GPIO_17);
    line[1] = gpiod_chip_get_line(chip, GPIO_18);
    line[2] = gpiod_chip_get_line(chip, GPIO_27);
    line[3] = gpiod_chip_get_line(chip, GPIO_22);

    for (int i = 0; i < 4; i++) {
        gpiod_line_request_input(line[i], "proximity_led");
    }

    // Perform soft reset
    buffer[0] = 0x80;
    buffer[1] = 0x63;
    write(i2c_fd, buffer, 2);

    // Verify sensor is present
    buffer[0] = 0x00;
    read(i2c_fd, buffer, 1);
    if (buffer[0] != 0x5A) {
        printf("Sensor not present\n");
        return EXIT_FAILURE;
    }

    // Initialize sensor
    buffer[0] = 0x00;
    write(i2c_fd, buffer, 1);

    // Set up polling loop
    while (true) {
        // Read touch status registers
        buffer[0] = 0x00;
        read(i2c_fd, buffer, 2);

        // Check for proximity events
        for (int i = 0; i < 12; i++) {
            if (buffer[i / 8] & (1 << (i % 8))) {
                printf("Proximity detected on electrode %d\n", i);
                // Set LED pattern based on electrode number
                for (int j = 0; j < 4; j++) {
                    gpiod_line_set_value(line[j], (i >> j) & 1);
                }
            }
        }

        // Sleep for a bit
        usleep(50000);
    }

    // Clean up
    for (int i = 0; i < 4; i++) {
        gpiod_line_release(line[i]);
    }
    gpiod_chip_close(chip);
    close(i2c_fd);

    return EXIT_SUCCESS;
}

