        nanosleep((struct timespec[]){{0, 5000}}, NULL); // 5 microseconds
        gpiod_line_set_value(trigger_line, 1);
        nanosleep((struct timespec[]){{0, 10000}}, NULL); // 10 microseconds
        gpiod_line_set_value(trigger_line, 0);

        if (gpiod_line_event_wait(echo_line, &start_time, 30000000) < 0) {
            fprintf(stderr, "Echo did not rise\n");
            continue;
        }

        if (gpiod_line_event_wait(echo_line, &end_time, 30000000) < 0) {
            fprintf(stderr, "Echo did not fall\n");
            continue;
        }

        pulse_width = (end_time.tv_sec - start_time.tv_sec) * 1000000000 + (end_time.tv_nsec - start_time.tv_nsec);
        distance = pulse_width * SOUND_SPEED / 2.0;

        if (distance < MIN_DISTANCE || distance > MAX_DISTANCE) {
            fprintf(stderr, "Distance out of range\n");
            continue;
        }

        fprintf(log_file, "%s: %.2f cm\n", ctime(&end_time.tv_sec), distance);
        fflush(log_file);
    }

    fclose(log_file);

cleanup:
    gpiod_line_release(echo_line);
    gpiod_line_release(trigger_line);
    gpiod_chip_close(chip);

    return EXIT_SUCCESS;
}

