#define MAX_PULSE_US 25000
#define LOG_FILE "distance_log.txt"

volatile sig_atomic_t running = 1;

void stop(int signum) {
    running = 0;
}

void echo_callback(int gpio, unsigned int level, uint32_t tick) {
    static uint32_t last_tick = 0;
    static int rising_edge = 0;
    uint32_t pulse_width;

    if (level == 1) {
        rising_edge = 1;
        last_tick = tick;
    } else {
        if (rising_edge) {
            pulse_width = gpioTickDiff(tick, last_tick);
            if (pulse_width > 0 && pulse_width < MAX_PULSE_US) {
                float distance = pulse_width * 0.000343;
                FILE *log_file = fopen(LOG_FILE, "a");
                if (log_file) {
                    fprintf(log_file, "%u, %.2f\n", gpioTick(), distance);
                    fclose(log_file);
                }
            }
            rising_edge = 0;
        }
    }
}

