    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialization failed\n");
        return EXIT_FAILURE;
    }

    signal(SIGINT, stop);
    signal(SIGTERM, stop);

    if (gpioSetMode(TRIG, PI_OUTPUT) < 0) {
        fprintf(stderr, "Failed to set TRIG GPIO mode\n");
        gpioTerminate();
        return EXIT_FAILURE;
    }

    if (gpioSetMode(ECHO, PI_INPUT) < 0) {
        fprintf(stderr, "Failed to set ECHO GPIO mode\n");
        gpioTerminate();
        return EXIT_FAILURE;
