#define VL53L1X_REG_CTRL 0x0018
#define VL53L1X_REG_TIMOUT 0x0019
#define VL53L1X_REG_START 0x0020
#define VL53L1X_REG_DISTANCE 0x0014
#define VL53L1X_REG_STATUS 0x0016
#define VL53L1X_DISTANCE_TIMEOUT 0x00
#define VL53L1X_DISTANCE_MODE 0x00
#define VL53L1X_DISTANCE_INTERVAL 100000 // 100ms

static int i2c_handle = -1;
static int gpio_handle = -1;

void terminate(int signum) {
    if (i2c_handle != -1) {
        close(i2c_handle);
    }
    if (gpio_handle != -1) {
        gpioTerminate();
    }
    exit(signum);
}

int main() {
    struct sigaction action;
    memset(&action, 0, sizeof(struct sigaction));
    action.sa_handler = terminate;
    sigaction(SIGINT, &action, NULL);
    sigaction(SIGTERM, &action, NULL);

    gpio_handle = gpioInitialise();
    if (gpio_handle < 0) {
        syslog(LOG_ERR, "Failed to initialise pigpio: %s", strerror(-gpio_handle));
        return EXIT_FAILURE;
    }

