    gpioWrite(27, PI_HIGH);

    i2c_handle = i2cOpen(1, VL53L1X_ADDRESS, 0);
    if (i2c_handle < 0) {
        syslog(LOG_ERR, "Failed to open I2C device: %s", strerror(-i2c_handle));
        gpioTerminate();
        return EXIT_FAILURE;
    }

    if (i2cWriteByteData(i2c_handle, VL53L1X_REG_CTRL, VL53L1X_DISTANCE_MODE) < 0 ||
        i2cWriteByteData(i2c_handle, VL53L1X_REG_TIMOUT, VL53L1X_DISTANCE_TIMEOUT) < 0 ||
        i2cWriteByteData(i2c_handle, VL53L1X_REG_START, 0x01) < 0) {
        syslog(LOG_ERR, "Failed to initialise VL53L1X");
        close(i2c_handle);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    while (1) {
        uint16_t distance;
        uint8_t status;
        int ret;

        ret = i2cReadWordData(i2c_handle, VL53L1X_REG_DISTANCE);
        if (ret < 0) {
            syslog(LOG_ERR, "Failed to read distance: %s", strerror(-ret));
            continue;
        }
        distance = (uint16_t)ret;

        ret = i2cReadByteData(i2c_handle, VL53L1X_REG_STATUS);
        if (ret < 0) {
            syslog(LOG_ERR, "Failed to read status: %s", strerror(-ret));
            continue;
        }
        status = (uint8_t)ret;

        syslog(LOG_INFO, "Distance: %u mm, Status: %u", distance, status);
        usleep(VL53L1X_DISTANCE_INTERVAL);
    }

    return EXIT_SUCCESS;
}

#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <pigpio.h>

#define VL53L1X_ADDRESS 0x29
#define VL53L1X_REG_IDENTIFICATION_MODEL_ID 0x010F
#define VL53L1X_REG_SYSTEM_MODE 0x0021
#define VL53L1X_REG_REGISTERS 0x0015
#define VL53L1X_REG_RESULT_RANGE_STATUS 0x0089
#define GATE_PIN 24

FILE *log_file;
time_t current_time;
struct tm *time_info;
char time_string[50];

void log_message(const char *message) {
    current_time = time(NULL);
    time_info = localtime(&current_time);
    strftime(time_string, sizeof(time_string), "%Y-%m-%d %H:%M:%S", time_info);
    fprintf(log_file, "%s: %s\n", time_string, message);
    fflush(log_file);
}

void error_handler(const char *message) {
    log_message(message);
    exit(EXIT_FAILURE);
}

void signal_handler(int signum) {
    log_message("Received SIGINT/SIGTERM, shutting down...");
    fclose(log_file);
    gpioTerminate();
    exit(EXIT_SUCCESS);
}

int main() {
    if (gpioInitialise() < 0) {
        error_handler("Failed to initialize pigpio");
    }

    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    log_file = fopen("gate_log.txt", "w");
    if (log_file == NULL) {
        error_handler("Failed to open log file");
    }

    log_message("Starting program...");

    int i2c_handle = gpioI2COpen(1, VL53L1X_ADDRESS);
    if (i2c_handle < 0) {
        error_handler("Failed to open I2C handle");
    }

    uint8_t model_id;
    if (gpioI2CReadByteData(i2c_handle, VL53L1X_REG_IDENTIFICATION_MODEL_ID, &model_id) < 0) {
        error_handler("Failed to read model ID");
    }

    if (model_id != 0xEA) {
        error_handler("Invalid model ID");
    }

    if (gpioI2CWriteByteData(i2c_handle, VL53L1X_REG_SYSTEM_MODE, 0x00) < 0) {
        error_handler("Failed to set ranging mode");
    }

    if (gpioI2CWriteByteData(i2c_handle, VL53L1X_REG_REGISTERS, 0x01) < 0) {
        error_handler("Failed to start ranging");
    }

    gpioSetMode(GATE_PIN, PI_OUTPUT);
    gpioWrite(GATE_PIN, PI_LOW);

    while (1) {
        uint16_t distance_mm;
        if (gpioI2CReadWordData(i2c_handle, VL53L1X_REG_RESULT_RANGE_STATUS, &distance_mm) < 0) {
            error_handler("Failed to read distance");
        }

        int distance_cm = distance_mm / 10;

        if (distance_cm < 20) {
            if (gpioRead(GATE_PIN) == PI_LOW) {
                gpioWrite(GATE_PIN, PI_HIGH);
                log_message("Gate opened");
            }
        } else {
            if (gpioRead(GATE_PIN) == PI_HIGH) {
                gpioWrite(GATE_PIN, PI_LOW);
                log_message("Gate closed");
            }
        }

        log_message("Distance: %d cm", distance_cm);

        gpioDelay(100000); // 100 ms
    }

    fclose(log_file);
    gpioTerminate();
    return 0;
}

#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <signal.h>
#include <pigpio.h>
#include <math.h>

#define TRIG 23
#define ECHO 24
#define SERVO 18
#define LOG_FILE "distance_log.csv"
#define TRIG_INTERVAL 100
#define SPEED_OF_SOUND 0.0343
#define MIN_DISTANCE 2
#define MAX_DISTANCE 400
#define MIN_SERVO_ANGLE 0
#define MAX_SERVO_ANGLE 180
#define MIN_SERVO_PULSE 500
#define MAX_SERVO_PULSE 2500

volatile sig_atomic_t stop = 0;

void handle_sigint(int signum) {
    stop = 1;
}

void alert_func(uint32_t tick, void *userdata) {
    static uint32_t last_tick = 0;
    static uint32_t last_distance = 0;
    static uint32_t distance_sum = 0;
    static int sample_count = 0;
    static FILE *log_file = NULL;
    static int log_file_open = 0;
    static int first_run = 1;
    uint32_t pulse_width = 0;
    uint32_t distance = 0;
    float angle = 0;

    if (first_run) {
        log_file = fopen(LOG_FILE, "w");
        if (!log_file) {
            printf("Failed to open log file\n");
            return;
        }
        fprintf(log_file, "Timestamp,Distance (cm),Servo Angle (degrees)\n");
        log_file_open = 1;
        first_run = 0;
    }

    if (tick < last_tick) {
        pulse_width = (uint32_t)(4294967295 - last_tick + tick);
    } else {
        pulse_width = tick - last_tick;
    }

    distance = (uint32_t)((float)pulse_width / 2.0 * SPEED_OF_SOUND * 100.0);
    if (distance < MIN_DISTANCE || distance > MAX_DISTANCE) {
        distance = last_distance;
    } else {
        distance_sum += distance;
        sample_count++;
        if (sample_count >= 5) {
            distance = distance_sum / 5;
            distance_sum = 0;
            sample_count = 0;
        }
    }

    angle = log(distance) * (MAX_SERVO_ANGLE - MIN_SERVO_ANGLE) / log(MAX_DISTANCE) + MIN_SERVO_ANGLE;
    uint32_t servo_pulse = (uint32_t)(MIN_SERVO_PULSE + (MAX_SERVO_PULSE - MIN_SERVO_PULSE) * angle / MAX_SERVO_ANGLE);

    gpioServo(SERVO, servo_pulse);

    if (log_file_open) {
        fprintf(log_file, "%u,%u,%f\n", tick, distance, angle);
        fflush(log_file);
    }

    last_tick = tick;
    last_distance = distance;
}

int main() {
    if (gpioInitialise() < 0) {
        printf("Failed to initialize pigpio\n");
        return EXIT_FAILURE;
    }

    if (gpioSetAlertFunc(ECHO, alert_func, NULL) < 0) {
        printf("Failed to set alert function for ECHO\n");
        gpioTerminate();
        return EXIT_FAILURE;
    }

    if (gpioSetMode(TRIG, PI_OUTPUT) < 0) {
        printf("Failed to set mode for TRIG\n");
        gpioTerminate();
        return EXIT_FAILURE;
    }

    if (gpioSetMode(SERVO, PI_OUTPUT) < 0) {
        printf("Failed to set mode for SERVO\n");
        gpioTerminate();
        return EXIT_FAILURE;
    }

    signal(SIGINT, handle_sigint);

    while (!stop) {
        gpioWrite(TRIG, PI_HIGH);
        usleep(10);
        gpioWrite(TRIG, PI_LOW);
        usleep(TRIG_INTERVAL * 1000);
    }

    gpioServo(SERVO, 90);
    if (log_file_open) {
        fclose(log_file);
    }
    gpioTerminate();

    return EXIT_SUCCESS;
}

