        fprintf(stderr, "Failed to open I2C device: %s\n", strerror(errno));
        return 1;
    }

    if (gpioInitialise() < 0) {
        fprintf(stderr, "Failed to initialise pigpio: %s\n", strerror(errno));
        return 1;
    }

    signal(SIGINT, signal_handler);

    if (gpioSetMode(27, PI_INPUT) < 0) {
        fprintf(stderr, "Failed to set GPIO mode: %s\n", strerror(errno));
        return 1;
    }

    if (gpioSetAlertFunc(27, interrupt_handler) < 0) {
        fprintf(stderr, "Failed to set GPIO alert function: %s\n", strerror(errno));
        return 1;
    }

    while (running) {
        gpioSleep(0, 0, 1000000);
    }

    gpioSetAlertFunc(27, NULL);
    gpioTerminate();
    close(proximity_fd);
    close(log_fd);

    return 0;
}

