#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <pigpio.h>
#include <math.h>

#define TRIGGER_PIN 23
#define ECHO_PIN 24
#define SPEAKER_PIN 18
#define MAX_DISTANCE 200
#define MIN_DISTANCE 2
#define DISTANCE_RANGE (MAX_DISTANCE - MIN_DISTANCE)

void signal_handler(int signum) {
    gpioTerminate();
    exit(signum);
}

int main() {
    struct sigaction action;
    memset(&action, 0, sizeof(struct sigaction));
    action.sa_handler = signal_handler;
    sigaction(SIGINT, &action, NULL);
    sigaction(SIGTERM, &action, NULL);

    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return EXIT_FAILURE;
    }

    if (gpioSetMode(TRIGGER_PIN, PI_OUTPUT) < 0) {
        fprintf(stderr, "failed to set trigger pin mode\n");
        return EXIT_FAILURE;
    }

    if (gpioSetMode(ECHO_PIN, PI_INPUT) < 0) {
        fprintf(stderr, "failed to set echo pin mode\n");
        return EXIT_FAILURE;
    }

    if (gpioSetMode(SPEAKER_PIN, PI_OUTPUT) < 0) {
        fprintf(stderr, "failed to set speaker pin mode\n");
        return EXIT_FAILURE;
    }

    uint32_t last_distance = MAX_DISTANCE;
    uint32_t last_frequency = 2000;
    uint32_t distance;
    uint32_t frequency;
    int timeout = 20000000; // 20ms

    while (1) {
        gpioTrigger(TRIGGER_PIN, 10, 0); // 10us pulse

        while (gpioWaveTxBusy()) {
            gpioDelay(1000);
        }

        distance = gpioRead(ECHO_PIN);

        if (distance == 0) {
            distance = last_distance;
        } else {
            last_distance = distance;
        }

        if (distance < MIN_DISTANCE || distance > MAX_DISTANCE) {
            frequency = last_frequency;
        } else {
            frequency = (uint32_t)(200 * exp((double)(distance - MIN_DISTANCE) / DISTANCE_RANGE));
            last_frequency = frequency;
        }

        if (gpioHardwarePWM(SPEAKER_PIN, frequency, 50) < 0) {
            fprintf(stderr, "failed to set PWM frequency\n");
            return EXIT_FAILURE;
        }

        gpioDelay(timeout);
    }

    gpioTerminate();
    return EXIT_SUCCESS;
}

