#include <stdio.h>
#include <signal.h>
#include <pigpio.h>

#define TRIG 23
#define ECHO 24
#define BUZZER 18
#define MIN_FREQ 200
#define MAX_FREQ 2000
#define MAX_DIST 50
#define MIN_DIST 5

volatile sig_atomic_t stop = 0;

void handler(int signum) {
    stop = 1;
}

int main() {
    if (gpioInitialise() < 0) {
        printf("pigpio initialisation failed\n");
        return 1;
    }

    signal(SIGINT, handler);

    gpioSetMode(TRIG, PI_OUTPUT);
    gpioSetMode(ECHO, PI_INPUT);
    gpioSetMode(BUZZER, PI_OUTPUT);

    gpioWrite(TRIG, PI_LOW);

    while (!stop) {
        gpioWrite(TRIG, PI_LOW);
        gpioDelay(2);
        gpioWrite(TRIG, PI_HIGH);
        gpioDelay(10);
        gpioWrite(TRIG, PI_LOW);

        uint32_t start = gpioTick();
        uint32_t timeout = start + 10000000; // 10 ms timeout
        uint32_t width = 0;

        while (gpioRead(ECHO) == PI_LOW && !stop) {
            if (gpioTick() > timeout) {
                printf("Echo timeout\n");
                break;
            }
        }

        if (!stop) {
            start = gpioTick();

            while (gpioRead(ECHO) == PI_HIGH && !stop) {
                if (gpioTick() > timeout) {
                    printf("Echo timeout\n");
                    break;
                }
                width = gpioTick() - start;
            }
        }

        uint32_t distance = width / 58; // convert width to distance in cm

        if (distance > MAX_DIST) {
            distance = MAX_DIST;
        }

        uint32_t frequency = MIN_FREQ + (MAX_FREQ - MIN_FREQ) * (MAX_DIST - distance) / (MAX_DIST - MIN_DIST);

        if (frequency < MIN_FREQ) {
            frequency = MIN_FREQ;
        }

        if (frequency > MAX_FREQ) {
            frequency = MAX_FREQ;
        }

        gpioHardwarePWM(BUZZER, frequency, 50);

        printf("Distance: %u cm, Frequency: %u Hz\n", distance, frequency);

        gpioDelay(10000000); // 10 ms delay
    }

    gpioHardwarePWM(BUZZER, 0, 0);
    gpioTerminate();

    return 0;
}

