#define SPI_CHANNEL 0
#define SPI_SPEED 1000000
#define SPI_CS 8
#define REG_MODE 0x01
#define REG_RANGE 0x02
#define REG_TRIGGER 0x00
#define REG_LOW_BYTE 0x0C
#define REG_HIGH_BYTE 0x0D
#define DISTANCE_LOG "distance_log.csv"

static void close_spi(int spi_fd) {
    if (spi_fd >= 0) {
        gpioTerminate();
    }
}

static void log_error(const char *message) {
    fprintf(stderr, "%s\n", message);
}

static void log_distance(int spi_fd, uint16_t distance) {
    FILE *log_file = fopen(DISTANCE_LOG, "a");
    if (log_file) {
        time_t now = time(NULL);
        struct tm *t = localtime(&now);
        fprintf(log_file, "%d-%02d-%02d %02d:%02d:%02d, %d\n",
                t->tm_year + 1900, t->tm_mon + 1, t->tm_mday,
                t->tm_hour, t->tm_min, t->tm_sec, distance);
        fclose(log_file);
    }
}

static void handle_sigint(int signum) {
    close_spi(spi_fd);
    exit(EXIT_SUCCESS);
}

static void handle_sigterm(int signum) {
    close_spi(spi_fd);
    exit(EXIT_SUCCESS);
}

int main() {
    int spi_fd = -1;
    uint8_t txbuf[3] = {REG_MODE, 0x01, REG_RANGE, 0x00, REG_TRIGGER, 0x01};
    uint8_t rxbuf[3] = {0};
    uint16_t distance = 0;
    struct timespec delay = {0, 100000000};

    if (gpioInitialise() < 0) {
        log_error("Failed to initialize pigpio");
        return EXIT_FAILURE;
    }

    atexit(close_spi);

    signal(SIGINT, handle_sigint);
    signal(SIGTERM, handle_sigterm);

    spi_fd = spiOpen(SPI_CHANNEL, SPI_SPEED, SPI_CS);
    if (spi_fd < 0) {
        log_error("Failed to open SPI device");
        return EXIT_FAILURE;
    }

    while (1) {
        if (spiXfer(spi_fd, txbuf, rxbuf, sizeof(txbuf)) != sizeof(txbuf)) {
            log_error("Failed to write/read SPI data");
            continue;
        }

        distance = (rxbuf[1] << 8) | rxbuf[2];
        log_distance(spi_fd, distance);

        nanosleep(&delay, NULL);
    }

    return EXIT_SUCCESS;
}

