    uint16_t als_visible;
    struct timespec sleep_time = {5, 0};
    FILE *log_file;

    // Open I2C bus
    if ((i2c_fd = open("/dev/i2c-1", O_RDWR)) < 0) {
        perror("Failed to open I2C bus");
        return EXIT_FAILURE;
    }

    // Set I2C address
    if (ioctl(i2c_fd, I2C_SLAVE, SI1175_ADDRESS) < 0) {
        perror("Failed to set I2C address");
        close(i2c_fd);
        return EXIT_FAILURE;
    }

    // Open log file
    if ((log_file = fopen("proximity_log.csv", "w")) == NULL) {
        perror("Failed to open log file");
        close(i2c_fd);
        return EXIT_FAILURE;
    }

    // Write header to log file
    fprintf(log_file, "timestamp,als_visible\n");

    while (1) {
        // Read ALS visible value
        if (write(i2c_fd, &ALS_VISIBLE_LOW, 1) != 1) {
            perror("Failed to write register address");
            break;
        }
        if (read(i2c_fd, buffer, 2) != 2) {
            perror("Failed to read ALS visible value");
            break;
        }
        als_visible = (buffer[1] << 8) | buffer[0];

        // Get current time
        time_t now = time(NULL);
        struct tm *time_info = localtime(&now);
        char timestamp[20];
        strftime(timestamp, sizeof(timestamp), "%Y-%m-%dT%H:%M:%S", time_info);

        // Write to log file
        fprintf(log_file, "%s,%d\n", timestamp, als_visible);

        // Sleep for 5 seconds
        nanosleep(&sleep_time, NULL);
    }

    // Close log file
    fclose(log_file);

    // Close I2C bus
    close(i2c_fd);

    return EXIT_SUCCESS;
}

#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <pigpio.h>

#define SI1120_ADDRESS 0x60
#define SI1120_PART_ID 0x41
#define ALS_REG_LOW 0x22
#define ALS_REG_HIGH 0x23
#define PS1_REG_LOW 0x18
#define PS1_REG_HIGH 0x19
#define I2C_BUS 1
#define SAMPLE_INTERVAL_MS 500
#define I2C_RETRY_COUNT 3
#define I2C_RETRY_DELAY_US 10000

int i2c_handle;
FILE *log_file;

void cleanup() {
    if (i2c_handle >= 0) {
        i2cClose(i2c_handle);
    }
    if (log_file) {
        fclose(log_file);
    }
    gpioTerminate();
}

void sigint_handler(int signum) {
    printf("SIGINT received, exiting...\n");
    cleanup();
    exit(0);
}

int read_register(uint8_t reg, uint16_t *value) {
    int retry_count = 0;
    while (retry_count < I2C_RETRY_COUNT) {
        if (i2cReadDevice(i2c_handle, reg, value, 2) == 0) {
            return 0;
        }
        usleep(I2C_RETRY_DELAY_US);
        retry_count++;
    }
    return -1;
}

int main() {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Failed to initialize pigpio\n");
        return EXIT_FAILURE;
    }

    signal(SIGINT, sigint_handler);

    i2c_handle = i2cOpen(I2C_BUS, SI1120_ADDRESS, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Failed to open I2C bus %d\n", I2C_BUS);
        cleanup();
        return EXIT_FAILURE;
    }

    log_file = fopen("si1120_log.txt", "a");
    if (!log_file) {
        fprintf(stderr, "Failed to open log file\n");
        cleanup();
        return EXIT_FAILURE;
    }

    uint8_t part_id;
    if (read_register(0x00, &part_id) != 0 || part_id != SI1120_PART_ID) {
        fprintf(stderr, "Failed to verify part ID\n");
        cleanup();
        return EXIT_FAILURE;
    }

    while (1) {
        uint16_t als_low, als_high, ps1_low, ps1_high;
        if (read_register(ALS_REG_LOW, &als_low) != 0 || read_register(ALS_REG_HIGH, &als_high) != 0 ||
            read_register(PS1_REG_LOW, &ps1_low) != 0 || read_register(PS1_REG_HIGH, &ps1_high) != 0) {
            fprintf(stderr, "Failed to read sensor data\n");
            cleanup();
            return EXIT_FAILURE;
        }

        uint16_t als_value = (als_high << 8) | als_low;
        uint16_t ps1_value = (ps1_high << 8) | ps1_low;

        time_t now = time(NULL);
        struct tm *t = localtime(&now);
        char timestamp[20];
        strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", t);

        fprintf(log_file, "%s ALS: %u PS1: %u\n", timestamp, als_value, ps1_value);

        sleep(SAMPLE_INTERVAL_MS / 1000);
    }

    cleanup();
    return EXIT_SUCCESS;
}

