#define SI1182_ADDRESS 0x39
#define PART_ID 0x00
#define MEASUREMENT_RATE 0x08
#define AMBIENT_LIGHT_LOWER 0x22
#define AMBIENT_LIGHT_UPPER 0x23
#define PROXIMITY_LOWER 0x24
#define PROXIMITY_UPPER 0x25

volatile sig_atomic_t stop = 0;

void signal_handler(int signum) {
    stop = 1;
}

int main() {
    int file;
    char filename[20];
    struct i2c_rdwr_ioctl_data packets;
    struct i2c_msg messages[2];
    unsigned char part_id[1];
    unsigned char measurement_rate[1];
    unsigned char ambient_light_lower[2];
    unsigned char ambient_light_upper[2];
    unsigned char proximity_lower[2];
    unsigned char proximity_upper[2];
    int lux;
    FILE *log_file;
    time_t current_time;
    struct tm *time_info;
    char time_string[20];

