        perror("Failed to open the i2c bus");
        return 1;
    }

    if (ioctl(file, I2C_SLAVE, SI1182_ADDRESS) < 0) {
        perror("Failed to acquire bus access and/or talk to slave");
        return 1;
    }

    messages[0].addr = SI1182_ADDRESS;
    messages[0].flags = 0;
    messages[0].len = 1;
    messages[0].buf = part_id;
    messages[1].addr = SI1182_ADDRESS;
    messages[1].flags = I2C_M_RD;
    messages[1].len = 1;
    messages[1].buf = part_id;

    packets.msgs = messages;
    packets.nmsgs = 2;

    if (ioctl(file, I2C_RDWR, &packets) < 0) {
        perror("Failed to read from the i2c slave");
        return 1;
    }

    if (part_id[0] != 0x11) {
        printf("Sensor not found\n");
        return 1;
    }

    memset(measurement_rate, 0x07, 1);
    messages[0].addr = SI1182_ADDRESS;
    messages[0].flags = 0;
    messages[0].len = 2;
    messages[0].buf = measurement_rate;
    messages[1].addr = SI1182_ADDRESS;
    messages[1].flags = I2C_M_RD;
    messages[1].len = 2;
    messages[1].buf = measurement_rate;

    if (ioctl(file, I2C_RDWR, &packets) < 0) {
        perror("Failed to write to the i2c slave");
        return 1;
    }

    log_file = fopen("biometric_log.txt", "w");
    if (log_file == NULL) {
        perror("Failed to open log file");
        return 1;
    }

    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    while (!stop) {
        current_time = time(NULL);
        time_info = localtime(&current_time);
        strftime(time_string, sizeof(time_string), "%Y-%m-%d %H:%M:%S", time_info);

        memset(ambient_light_lower, 0, 2);
        memset(ambient_light_upper, 0, 2);
        memset(proximity_lower, 0, 2);
        memset(proximity_upper, 0, 2);

        messages[0].addr = SI1182_ADDRESS;
        messages[0].flags = 0;
        messages[0].len = 2;
        messages[0].buf = ambient_light_lower;
        messages[1].addr = SI1182_ADDRESS;
        messages[1].flags = I2C_M_RD;
        messages[1].len = 2;
        messages[1].buf = ambient_light_upper;

        if (ioctl(file, I2C_RDWR, &packets) < 0) {
            perror("Failed to read from the i2c slave");
            return 1;
        }

        messages[0].addr = SI1182_ADDRESS;
        messages[0].flags = 0;
        messages[0].len = 2;
        messages[0].buf = proximity_lower;
        messages[1].addr = SI1182_ADDRESS;
        messages[1].flags = I2C_M_RD;
        messages[1].len = 2;
        messages[1].buf = proximity_upper;

        if (ioctl(file, I2C_RDWR, &packets) < 0) {
            perror("Failed to read from the i2c slave");
            return 1;
        }

        lux = (ambient_light_upper[0] << 8) | ambient_light_lower[0];
        lux = lux * 0.1;

        fprintf(log_file, "%s,%d,%d\n", time_string, lux, (proximity_upper[0] << 8) | proximity_lower[0]);
        printf("%s,%d,%d\n", time_string, lux, (proximity_upper[0] << 8) | proximity_lower[0]);

        usleep(100000);
    }

    fclose(log_file);
    close(file);

    return 0;
}

