static FILE *log_file = NULL;
static volatile sig_atomic_t running = 1;

void sig_handler(int signum) {
    running = 0;
}

int main() {
    struct timespec sleep_time = {0, 2000000}; // 2 ms
    struct tm *timeinfo;
    time_t rawtime;
    char buffer[80];
    uint16_t proximity_data;
    int retry_count;

    signal(SIGINT, sig_handler);
    signal(SIGTERM, sig_handler);

    if ((i2c_handle = i2cOpen(1, SI1145_ADDRESS, 0)) < 0) {
        printf("Failed to open I2C handle\n");
        return EXIT_FAILURE;
    }

    if ((log_file = fopen(LOG_FILE, "a")) == NULL) {
        printf("Failed to open log file\n");
        i2cClose(i2c_handle);
        return EXIT_FAILURE;
    }

    // Sensor initialisation sequence
    uint8_t init_sequence[14] = {0x03, 0x07, 0x02, 0x06, 0x00, 0x1A, 0x0B, 0x21, 0x00, 0x24, 0x49, 0x22, 0x0F, 0x0C};
    for (int i = 0; i < sizeof(init_sequence); i += 2) {
        if (i2cWriteByteData(i2c_handle, init_sequence[i], init_sequence[i + 1]) < 0) {
            printf("Failed to write to sensor\n");
            fclose(log_file);
            i2cClose(i2c_handle);
            return EXIT_FAILURE;
        }
    }

    while (running) {
        retry_count = 0;
        while (retry_count < 3) {
            if (i2cReadByteData(i2c_handle, 0x16, &proximity_data) < 0) {
                printf("Failed to read proximity data, retrying...\n");
                retry_count++;
                continue;
            }
            break;
        }
        if (retry_count == 3) {
            printf("Failed to read proximity data after 3 retries\n");
            fclose(log_file);
            i2cClose(i2c_handle);
            return EXIT_FAILURE;
        }

        time(&rawtime);
        timeinfo = localtime(&rawtime);
        strftime(buffer, sizeof(buffer), "%Y-%m-%d %H:%M:%S", timeinfo);
        fprintf(log_file, "%s Proximity: %d\n", buffer, proximity_data);

        nanosleep(&sleep_time, NULL);
    }

    fclose(log_file);
    i2cClose(i2c_handle);
    gpioTerminate();

    return EXIT_SUCCESS;
}

#include <stdio.h>
#include <stdlib.h>
#include <signal.h>
#include <pigpio.h>

#define TRIG 17
#define ECHO 18
#define BUZZ 27
#define SPEED_OF_SOUND 0.0343 // cm/us

volatile int running = 1;
volatile int distance = 0;

void stop(int signum) {
    running = 0;
    gpioTerminate();
    exit(0);
}

void echo_callback(int gpio, int level, uint32_t tick) {
    static uint32_t start_tick = 0;
    static int rising_edge = 0;

    if (level == 1) {
        start_tick = tick;
        rising_edge = 1;
    } else if (rising_edge) {
        uint32_t end_tick = tick;
        distance = (end_tick - start_tick) * SPEED_OF_SOUND / 2;
        rising_edge = 0;
    }
}

int main() {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return EXIT_FAILURE;
    }

    signal(SIGINT, stop);

    if (gpioSetMode(TRIG, PI_OUTPUT) < 0) {
        fprintf(stderr, "Failed to set TRIG pin mode\n");
        gpioTerminate();
        return EXIT_FAILURE;
    }

    if (gpioSetMode(ECHO, PI_INPUT) < 0) {
        fprintf(stderr, "Failed to set ECHO pin mode\n");
        gpioTerminate();
        return EXIT_FAILURE;
    }

    if (gpioSetMode(BUZZ, PI_OUTPUT) < 0) {
        fprintf(stderr, "Failed to set BUZZ pin mode\n");
        gpioTerminate();
        return EXIT_FAILURE;
    }

    if (gpioSetAlertFuncEx(ECHO, echo_callback, NULL) < 0) {
        fprintf(stderr, "Failed to set ECHO pin alert function\n");
        gpioTerminate();
        return EXIT_FAILURE;
    }

    while (running) {
        gpioWrite(TRIG, 0);
        gpioDelay(2);
        gpioWrite(TRIG, 1);
        gpioDelay(10);
        gpioWrite(TRIG, 0);

        printf("Distance: %d cm\n", distance);

        if (distance < 20) {
            gpioWrite(BUZZ, 1);
        } else {
            gpioWrite(BUZZ, 0);
        }

        sleep(1);
    }

    gpioTerminate();
    return EXIT_SUCCESS;
}

#include <stdio.h>
#include <signal.h>
#include <pigpio.h>
#include <time.h>

#define TRIG 4
#define ECHO 17
#define SERVO 18
#define MIN_DISTANCE 20
#define MAX_DISTANCE 110
#define MIN_ANGLE 0
#define MAX_ANGLE 180

volatile sig_atomic_t stop = 0;

void cleanup(int signum) {
    gpioServo(SERVO, 0);
    gpioTerminate();
    printf("Cleanup complete\n");
    stop = 1;
}

int main() {
    if (gpioInitialise() < 0) {
        printf("pigpio initialisation failed\n");
        return 1;
    }

    signal(SIGINT, cleanup);

    gpioSetMode(TRIG, PI_OUTPUT);
    gpioSetMode(ECHO, PI_INPUT);
    gpioSetMode(SERVO, PI_OUTPUT);

    gpioServo(SERVO, 500);

    while (!stop) {
        gpioWrite(TRIG, 0);
        gpioDelay(2);
        gpioWrite(TRIG, 1);
        gpioDelay(10);
        gpioWrite(TRIG, 0);

        uint32_t start = gpioGetTime();
        uint32_t end = 0;

        while (gpioRead(ECHO) == 0) {
            start = gpioGetTime();
        }

        while (gpioRead(ECHO) == 1) {
            end = gpioGetTime();
        }

        if (end == 0) {
            printf("Echo timeout\n");
            continue;
        }

        uint32_t pulseWidth = end - start;

        float distance = (float)pulseWidth / 58.0;

        if (distance < MIN_DISTANCE || distance > MAX_DISTANCE) {
            printf("Sensor error\n");
            continue;
        }

        int angle = MIN_ANGLE + (int)((MAX_ANGLE - MIN_ANGLE) / (MAX_DISTANCE - MIN_DISTANCE) * (distance - MIN_DISTANCE));

        gpioServo(SERVO, angle * 10);

        printf("Distance: %.2f cm, Servo angle: %d degrees\n", distance, angle);
    }

    return 0;
}

#include <stdio.h>
#include <signal.h>
#include <pigpio.h>

#define TRIG 23
#define ECHO 24
#define SERVO 18
#define TRIG_PULSE 10
#define MAX_DISTANCE 400
#define MIN_DISTANCE 2
#define MIN_ANGLE 0
#define MAX_ANGLE 180
#define MIN_PULSE_WIDTH 500
#define MAX_PULSE_WIDTH 2500
#define MEASUREMENT_INTERVAL 100

static int keep_running = 1;

void intHandler(int dummy) {
    keep_running = 0;
}

int main() {
    if (gpioInitialise() < 0) {
        printf("Failed to initialize pigpio\n");
        return 1;
    }

    signal(SIGINT, intHandler);

    if (gpioSetMode(TRIG, PI_OUTPUT) < 0) {
        printf("Failed to set TRIG pin mode\n");
        gpioTerminate();
        return 1;
    }

    if (gpioSetMode(ECHO, PI_INPUT) < 0) {
        printf("Failed to set ECHO pin mode\n");
        gpioTerminate();
        return 1;
    }

    if (gpioSetMode(SERVO, PI_OUTPUT) < 0) {
        printf("Failed to set SERVO pin mode\n");
        gpioTerminate();
        return 1;
    }

    while (keep_running) {
        gpioWrite(TRIG, PI_HIGH);
        gpioDelay(TRIG_PULSE);
        gpioWrite(TRIG, PI_LOW);

        uint32_t start_tick = gpioTick();
        uint32_t end_tick = 0;
        uint32_t pulse_duration = 0;

        while (gpioRead(ECHO) == PI_LOW && (gpioTick() - start_tick) < 50000) {}
        start_tick = gpioTick();

        while (gpioRead(ECHO) == PI_HIGH && (gpioTick() - start_tick) < 50000) {
            end_tick = gpioTick();
        }

        if (end_tick > start_tick) {
            pulse_duration = end_tick - start_tick;
        }

        float distance = (pulse_duration * 0.0343) / 2;

        if (distance < MIN_DISTANCE || distance > MAX_DISTANCE) {
            distance = -1.0;
        }

        int angle = 0;

        if (distance >= 0) {
            angle = (int)((distance - MIN_DISTANCE) / (MAX_DISTANCE - MIN_DISTANCE) * (MAX_ANGLE - MIN_ANGLE) + MIN_ANGLE);
        }

        int pulse_width = (int)((angle / (float)(MAX_ANGLE - MIN_ANGLE) * (MAX_PULSE_WIDTH - MIN_PULSE_WIDTH) + MIN_PULSE_WIDTH));

        gpioServo(SERVO, pulse_width);

        printf("Distance: %.2f cm, Angle: %d degrees\n", distance, angle);

        gpioDelay(MEASUREMENT_INTERVAL * 1000);
    }

    gpioServo(SERVO, 0);
    gpioTerminate();

    return 0;
}

#include <stdio.h>
#include <stdlib.h>
#include <signal.h>
#include <pigpio.h>

#define SI7005_ADDRESS 0x40
#define SI7005_CONFIG 0x03
#define SI7005_TEMP 0x01
#define SI7005_HUMIDITY 0x02
#define SI7005_HEATER_DISABLE 0x00
#define SI7005_TEMP_CONVERSION_FACTOR 175.72
#define SI7005_TEMP_CONVERSION_OFFSET 46.85
#define SI7005_HUMIDITY_CONVERSION_FACTOR 125.0
#define SI7005_HUMIDITY_CONVERSION_OFFSET 6.0
#define I2C_BUS 1
#define READ_INTERVAL 2000000

volatile sig_atomic_t stop = 0;

void signal_handler(int signum) {
    stop = 1;
}

int main() {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return EXIT_FAILURE;
    }

    if (signal(SIGINT, signal_handler) == SIG_ERR) {
        fprintf(stderr, "could not set signal handler\n");
        gpioTerminate();
        return EXIT_FAILURE;
    }

    int i2c_handle = -1;
    while (!stop) {
        if (i2c_handle < 0) {
            i2c_handle = gpioI2COpen(I2C_BUS, SI7005_ADDRESS, 0);
            if (i2c_handle < 0) {
                fprintf(stderr, "I2C bus open failed\n");
                gpioTerminate();
                return EXIT_FAILURE;
            }
        }

        uint8_t config_data = SI7005_HEATER_DISABLE;
        if (gpioI2CWriteByteData(i2c_handle, SI7005_CONFIG, config_data) < 0) {
            fprintf(stderr, "I2C write failed\n");
            gpioI2CWriteByteData(i2c_handle, SI7005_CONFIG, config_data);
            continue;
        }

        gpioDelay(10000);

        uint8_t temp_data = gpioI2CReadByteData(i2c_handle, SI7005_TEMP);
        if (temp_data < 0) {
            fprintf(stderr, "I2C read failed\n");
            continue;
        }

        gpioDelay(10000);

        uint8_t humidity_data = gpioI2CReadByteData(i2c_handle, SI7005_HUMIDITY);
        if (humidity_data < 0) {
            fprintf(stderr, "I2C read failed\n");
            continue;
        }

        float temperature = (SI7005_TEMP_CONVERSION_FACTOR * temp_data) / 65536.0 - SI7005_TEMP_CONVERSION_OFFSET;
        float humidity = (SI7005_HUMIDITY_CONVERSION_FACTOR * humidity_data) / 65536.0 - SI7005_HUMIDITY_CONVERSION_OFFSET;

        printf("Temperature: %.2f°C, Humidity: %.2f%%\n", temperature, humidity);

        gpioDelay(READ_INTERVAL);
    }

    gpioI2CClose(i2c_handle);
    gpioTerminate();
    return EXIT_SUCCESS;
}

#include <stdio.h>
#include <signal.h>
#include <pigpio.h>

#define MPU6050_ADDRESS 0x68
#define WHO_AM_I 0x75
#define PWR_MGMT_1 0x6B
#define SMPLRT_DIV 0x19
#define ACCEL_CONFIG 0x1C
#define GYRO_CONFIG 0x1B
#define ACCEL_XOUT_H 0x3B

volatile sig_atomic_t stop = 0;

void signal_handler(int signum) {
    stop = 1;
}

int main() {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    printf("Starting MPU6050 data acquisition\n");

    int i2c_handle = i2cOpen(1, MPU6050_ADDRESS, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Failed to open I2C bus\n");
        gpioTerminate();
        return 1;
    }

    uint8_t who_am_i;
    if (i2cReadByteData(i2c_handle, WHO_AM_I, &who_am_i) < 0) {
        fprintf(stderr, "Failed to read WHO_AM_I register\n");
        i2cClose(i2c_handle);
        gpioTerminate();
        return 1;
    }

    if (who_am_i != 0x68) {
        fprintf(stderr, "MPU6050 not found\n");
        i2cClose(i2c_handle);
        gpioTerminate();
        return 1;
    }

    if (i2cWriteByteData(i2c_handle, PWR_MGMT_1, 0x00) < 0) {
        fprintf(stderr, "Failed to reset MPU6050\n");
        i2cClose(i2c_handle);
        gpioTerminate();
        return 1;
    }

    sleep(1);

    if (i2cWriteByteData(i2c_handle, SMPLRT_DIV, 0x07) < 0) {
        fprintf(stderr, "Failed to set sample rate divider\n");
        i2cClose(i2c_handle);
        gpioTerminate();
        return 1;
    }

    if (i2cWriteByteData(i2c_handle, ACCEL_CONFIG, 0x00) < 0) {
        fprintf(stderr, "Failed to set accelerometer configuration\n");
        i2cClose(i2c_handle);
        gpioTerminate();
        return 1;
    }

    if (i2cWriteByteData(i2c_handle, GYRO_CONFIG, 0x00) < 0) {
        fprintf(stderr, "Failed to set gyroscope configuration\n");
        i2cClose(i2c_handle);
        gpioTerminate();
        return 1;
    }

    while (!stop) {
        uint8_t data[14];
        if (i2cReadI2CBlockData(i2c_handle, ACCEL_XOUT_H, 14, data) < 0) {
            fprintf(stderr, "Failed to read data from MPU6050\n");
            break;
        }

        int16_t accel_x = (data[0] << 8) | data[1];
        int16_t accel_y = (data[2] << 8) | data[3];
        int16_t accel_z = (data[4] << 8) | data[5];
        int16_t temp = (data[6] << 8) | data[7];
        int16_t gyro_x = (data[8] << 8) | data[9];
        int16_t gyro_y = (data[10] << 8) | data[11];
        int16_t gyro_z = (data[12] << 8) | data[13];

        printf("Accel: %d, %d, %d\n", accel_x, accel_y, accel_z);
        printf("Temp: %d\n", temp);
        printf("Gyro: %d, %d, %d\n", gyro_x, gyro_y, gyro_z);

        sleep(0.1);
    }

    i2cClose(i2c_handle);
    gpioTerminate();

    printf("Shutting down MPU6050 data acquisition\n");

    return 0;
}

#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <signal.h>
#include <pigpio.h>

#define SHT40_ADDRESS 0x44
#define SHT40_CMD_MEASURE_HIGH_REP 0xFD
#define SHT40_CRC_POLYNOMIAL 0x31
#define SHT40_CRC_INIT 0xFF

volatile sig_atomic_t running = 1;

void signal_handler(int signum) {
    running = 0;
}

uint8_t crc8(const uint8_t *data, size_t len) {
    uint8_t crc = SHT40_CRC_INIT;
    for (size_t i = 0; i < len; i++) {
        crc ^= data[i];
        for (int j = 0; j < 8; j++) {
            if (crc & 0x80) {
                crc = (crc << 1) ^ SHT40_CRC_POLYNOMIAL;
            } else {
                crc <<= 1;
            }
        }
    }
    return crc;
}

int main() {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Failed to initialize pigpio\n");
        return EXIT_FAILURE;
    }

    if (gpioSetSignalFunc(SIGINT, signal_handler) < 0) {
        fprintf(stderr, "Failed to set signal handler for SIGINT\n");
        gpioTerminate();
        return EXIT_FAILURE;
    }

    if (gpioSetSignalFunc(SIGTERM, signal_handler) < 0) {
        fprintf(stderr, "Failed to set signal handler for SIGTERM\n");
        gpioTerminate();
        return EXIT_FAILURE;
    }

    int i2c_handle = gpioI2COpen(1, SHT40_ADDRESS);
    if (i2c_handle < 0) {
        fprintf(stderr, "Failed to open I2C bus 1\n");
        gpioTerminate();
        return EXIT_FAILURE;
    }

    while (running) {
        uint8_t cmd = SHT40_CMD_MEASURE_HIGH_REP;
        if (gpioI2CWriteByteData(i2c_handle, 0x00, cmd) < 0) {
            fprintf(stderr, "Failed to write command to SHT40\n");
            gpioI2CClose(i2c_handle);
            i2c_handle = gpioI2COpen(1, SHT40_ADDRESS);
            continue;
        }

        usleep(10000);

        uint8_t buffer[6];
        if (gpioI2CReadByteData(i2c_handle, 0x00, buffer, sizeof(buffer)) < 0) {
            fprintf(stderr, "Failed to read data from SHT40\n");
            gpioI2CClose(i2c_handle);
            i2c_handle = gpioI2COpen(1, SHT40_ADDRESS);
            continue;
        }

        if (crc8(buffer, 2) != buffer[2] || crc8(buffer + 3, 2) != buffer[5]) {
            fprintf(stderr, "CRC check failed for SHT40 data\n");
            gpioI2CClose(i2c_handle);
            i2c_handle = gpioI2COpen(1, SHT40_ADDRESS);
            continue;
        }

        int16_t raw_temperature = (buffer[0] << 8) | buffer[1];
        int16_t raw_humidity = (buffer[3] << 8) | buffer[4];

        float temperature = -45 + 175 * raw_temperature / 65535.0;
        float humidity = -6 + 125 * raw_humidity / 65535.0;

        printf("Temperature: %.2f°C, Humidity: %.2f%%\n", temperature, humidity);

        sleep(5);
    }

    gpioI2CClose(i2c_handle);
    gpioTerminate();
    return EXIT_SUCCESS;
}

#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <stdbool.h>
#include <string.h>
#include <unistd.h>
#include <fcntl.h>
#include <signal.h>
#include <sys/ioctl.h>
#include <linux/i2c-dev.h>
#include <libgpiod.h>

#define I2C_BUS "/dev/i2c-1"
#define SENSOR_ADDRESS 0x5A
#define AMBIENT_REGISTER 0x06
#define OBJECT_REGISTER 0x07
#define LOG_FILE "temperature_log.csv"

static bool running = true;

void signal_handler(int signum) {
    running = false;
}

int main() {
    struct gpiod_chip *chip;
    struct gpiod_line_request request;
    int i2c_fd, ret;
    uint8_t buffer[2];
    FILE *log_file;

    // Register signal handler for clean exit
    signal(SIGINT, signal_handler);

    // Open I2C bus
    if ((i2c_fd = open(I2C_BUS, O_RDWR)) < 0) {
        perror("Failed to open I2C bus");
        return EXIT_FAILURE;
    }

    // Request I2C access
    if (ioctl(i2c_fd, I2C_SLAVE, SENSOR_ADDRESS) < 0) {
        perror("Failed to acquire I2C bus access and/or talk to slave");
        close(i2c_fd);
        return EXIT_FAILURE;
    }

    // Open log file
    if ((log_file = fopen(LOG_FILE, "w")) == NULL) {
        perror("Failed to open log file");
        close(i2c_fd);
        return EXIT_FAILURE;
    }

    // Write header to log file
    fprintf(log_file, "Timestamp,Ambient Temperature,Object Temperature\n");

    while (running) {
        // Read ambient temperature
        buffer[0] = AMBIENT_REGISTER;
        if (write(i2c_fd, buffer, 1) != 1) {
            perror("Failed to write register address");
            break;
        }
        if (read(i2c_fd, buffer, 2) != 2) {
            perror("Failed to read ambient temperature");
            break;
        }
        float ambient_temp = buffer[0] + buffer[1] * 0.02;

        // Read object temperature
        buffer[0] = OBJECT_REGISTER;
        if (write(i2c_fd, buffer, 1) != 1) {
            perror("Failed to write register address");
            break;
        }
        if (read(i2c_fd, buffer, 2) != 2) {
            perror("Failed to read object temperature");
            break;
        }
        float object_temp = buffer[0] + buffer[1] * 0.02;

        // Log temperature readings
        time_t now = time(NULL);
        struct tm *t = localtime(&now);
        fprintf(log_file, "%d-%02d-%02d %02d:%02d:%02d,%f,%f\n",
                t->tm_year + 1900, t->tm_mon + 1, t->tm_mday,
                t->tm_hour, t->tm_min, t->tm_sec,
                ambient_temp, object_temp);

        // Wait for 5 seconds
        sleep(5);
    }

    // Clean up
    fclose(log_file);
    close(i2c_fd);

    return EXIT_SUCCESS;
}

#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <pigpio.h>

#define SENSIRION_I2C_ADDRESS 0x4A
#define SENSIRION_I2C_BUS 1
#define LOG_FILE "enclosure_temp_log.txt"
#define ERROR_LOG_FILE "error_log.txt"
#define SAMPLE_INTERVAL 5

void log_error(const char *message) {
    FILE *error_log = fopen(ERROR_LOG_FILE, "a");
    if (error_log == NULL) {
        printf("Failed to open error log file\n");
        return;
    }
    time_t now = time(NULL);
    struct tm *t = localtime(&now);
    char time_str[26];
    strftime(time_str, sizeof(time_str), "%Y-%m-%d %H:%M:%S", t);
    fprintf(error_log, "%s: %s\n", time_str, message);
    fclose(error_log);
}

void signal_handler(int signum) {
    printf("Caught signal %d, exiting...\n", signum);
    exit(0);
}

int main() {
    if (gpioInitialise() < 0) {
        log_error("Failed to initialize pigpio");
        return EXIT_FAILURE;
    }

    signal(SIGINT, signal_handler);

    FILE *log_file = fopen(LOG_FILE, "a");
    if (log_file == NULL) {
        log_error("Failed to open log file");
        gpioTerminate();
        return EXIT_FAILURE;
    }

    while (1) {
        uint16_t raw_temp;
        int ret = gpioI2CReadDeviceReg16(SENSIRION_I2C_BUS, SENSIRION_I2C_ADDRESS, 0x0D, &raw_temp);
        if (ret < 0) {
            char error_message[256];
            sprintf(error_message, "Failed to read temperature: %s", strerror(-ret));
            log_error(error_message);
        } else {
            time_t now = time(NULL);
            struct tm *t = localtime(&now);
            char time_str[26];
            strftime(time_str, sizeof(time_str), "%Y-%m-%d %H:%M:%S", t);
            fprintf(log_file, "%s: %d\n", time_str, raw_temp);
            fflush(log_file);
        }

        sleep(SAMPLE_INTERVAL);
    }

    fclose(log_file);
    gpioTerminate();
    return EXIT_SUCCESS;
}

