    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    FILE *file = fopen(PRESSURE_FILE, "a");
    if (!file) {
        fprintf(stderr, "Failed to open file %s\n", PRESSURE_FILE);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    uint8_t cmd[2] = PRESSURE_CMD;
    uint8_t data[PRESSURE_DATA_LEN];
    uint16_t pressure, temperature;
    uint8_t crc;

    while (running) {
        if (gpioI2CWriteDevice(I2C_BUS, I2C_ADDRESS, cmd, sizeof(cmd)) != sizeof(cmd)) {
            fprintf(stderr, "Failed to write command to sensor\n");
            break;
        }

        usleep(1000);

        if (gpioI2CReadDevice(I2C_BUS, I2C_ADDRESS, data, PRESSURE_DATA_LEN) != PRESSURE_DATA_LEN) {
            fprintf(stderr, "Failed to read data from sensor\n");
            break;
        }

        crc = PRESSURE_CRC_INIT;
        for (int i = 0; i < PRESSURE_DATA_LEN - 1; i++) {
            crc ^= data[i];
            for (int j = 0; j < 8; j++) {
                if (crc & 0x80) {
                    crc = (crc << 1) ^ PRESSURE_CRC_POLY;
                } else {
                    crc <<= 1;
                }
            }
        }

        if (crc != data[PRESSURE_DATA_LEN - 1]) {
            fprintf(stderr, "Invalid CRC\n");
            break;
        }

        pressure = (data[0] << 8) | data[1];
        temperature = (data[3] << 8) | data[4];
        pressure = (pressure & 0x0FFF) * PRESSURE_SCALE_FACTOR;
        temperature = (temperature & 0x0FFF) * TEMPERATURE_SCALE_FACTOR;

        time_t now = time(NULL);
        struct tm *timeinfo = gmtime(&now);
        char timestamp[20];
        strftime(timestamp, sizeof(timestamp), "%Y-%m-%dT%H:%M:%SZ", timeinfo);

        fprintf(file, "%s,%f,%f\n", timestamp, pressure, temperature);

        fflush(file);
    }

    fclose(file);
    gpioTerminate();
    return EXIT_SUCCESS;
}

#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <string.h>
