#include <unistd.h>
#include <signal.h>
#include <sys/ioctl.h>
#include <linux/i2c-dev.h>
#include <time.h>

#define SHT40_ADDRESS 0x44
#define SHT40_MEASUREMENT_CMD 0xFD
#define SHT40_DATA_LEN 6
#define SHT40_LOG_FILE "sht40_log.txt"
#define SHT40_RETRY_INTERVAL 5

static int i2c_fd = -1;
static FILE *log_file = NULL;

void cleanup() {
    if (i2c_fd != -1) {
        close(i2c_fd);
    }
    if (log_file != NULL) {
        fclose(log_file);
    }
}

void log_error(const char *msg) {
    fprintf(stderr, "%s\n", msg);
    if (log_file != NULL) {
        fprintf(log_file, "%s\n", msg);
    }
}

uint8_t calculate_crc8(const uint8_t *data, size_t len) {
    uint8_t crc = 0xFF;
    for (size_t i = 0; i < len; i++) {
        crc ^= data[i];
        for (int j = 0; j < 8; j++) {
            if ((crc & 0x80) != 0) {
                crc = (crc << 1) ^ 0x31;
            } else {
                crc <<= 1;
            }
        }
    }
    return crc;
}

int main() {
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = cleanup;
    sigaction(SIGINT, &sa, NULL);
    sigaction(SIGTERM, &sa, NULL);

    if ((i2c_fd = open("/dev/i2c-1", O_RDWR)) < 0) {
        log_error("Failed to open I2C device");
        return EXIT_FAILURE;
    }

    if (ioctl(i2c_fd, I2C_SLAVE, SHT40_ADDRESS) < 0) {
        log_error("Failed to set I2C slave address");
        return EXIT_FAILURE;
    }

    if ((log_file = fopen(SHT40_LOG_FILE, "a")) == NULL) {
        log_error("Failed to open log file");
        return EXIT_FAILURE;
    }

    while (1) {
        uint8_t buffer[SHT40_DATA_LEN];
        if (write(i2c_fd, &SHT40_MEASUREMENT_CMD, 1) != 1) {
            log_error("Failed to write measurement command");
            continue;
        }

        struct timespec ts;
        ts.tv_sec = 0;
        ts.tv_nsec = 10000000; // 10 ms
        nanosleep(&ts, NULL);

        if (read(i2c_fd, buffer, SHT40_DATA_LEN) != SHT40_DATA_LEN) {
            log_error("Failed to read data from sensor");
            continue;
        }

        if (buffer[2] != calculate_crc8(buffer, 2) || buffer[5] != calculate_crc8(buffer + 3, 2)) {
            log_error("CRC check failed");
            continue;
        }

        float temperature = -45 + 175 * (buffer[0] << 8 | buffer[1]) / 65535.0;
        float humidity = 100 * (buffer[3] << 8 | buffer[4]) / 65535.0;

        time_t now = time(NULL);
        struct tm *timeinfo = localtime(&now);
        char timestamp[20];
        strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", timeinfo);

        fprintf(log_file, "%s Temperature: %.2f°C Humidity: %.2f%%\n", timestamp, temperature, humidity);

        ts.tv_sec = SHT40_RETRY_INTERVAL;
        ts.tv_nsec = 0;
        nanosleep(&ts, NULL);
    }

    return EXIT_SUCCESS;
}

#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <signal.h>
#include <time.h>
#include <pigpio.h>

volatile sig_atomic_t stop_requested = 0;

void signal_handler(int signum) {
    stop_requested = 1;
}

int main() {
    FILE *log_file;
    uint8_t buffer[6];
    uint16_t raw_pressure, raw_temperature;
    float pressure_pa, temperature_c;
    time_t timestamp;
    struct tm *timeinfo;
    char time_string[20];
    int i2c_handle;
    int retry_count;

    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    if ((i2c_handle = i2cOpen(1, 0x28, 0)) < 0) {
        printf("Failed to open I2C bus 1.\n");
        return EXIT_FAILURE;
    }

    if ((log_file = fopen("airflow.log", "w")) == NULL) {
        printf("Failed to open log file.\n");
        i2cClose(i2c_handle);
        return EXIT_FAILURE;
    }

    gpioInitialise();

    while (!stop_requested) {
        retry_count = 3;
        while (retry_count-- > 0) {
            if (i2cWriteByteData(i2c_handle, 0x21, 0x96) < 0) {
                printf("Failed to write to I2C device, retrying...\n");
                continue;
            }
            usleep(1000); // Wait at least 1 ms
            if (i2cReadDevice(i2c_handle, buffer, 6) < 0) {
                printf("Failed to read from I2C device, retrying...\n");
                continue;
            }
            break;
        }
        if (retry_count < 0) {
            printf("Failed to read from I2C device after 3 attempts.\n");
            break;
        }

        raw_pressure = (buffer[0] << 8) | buffer[1];
        raw_temperature = (buffer[3] << 8) | buffer[4];

        pressure_pa = raw_pressure / 60.0;
        temperature_c = raw_temperature / 200.0;

        time(&timestamp);
        timeinfo = localtime(&timestamp);
        strftime(time_string, sizeof(time_string), "%Y-%m-%d %H:%M:%S", timeinfo);

        fprintf(log_file, "%s,%f,%f\n", time_string, pressure_pa, temperature_c);
        fflush(log_file);

        usleep(100000); // Wait for 100 ms
    }

    gpioTerminate();
    fclose(log_file);
    i2cClose(i2c_handle);

    return EXIT_SUCCESS;
}

#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <unistd.h>
#include <signal.h>
#include <time.h>
#include <errno.h>
#include <pigpio.h>

#define SI7015_ADDRESS 0x40
#define SI7015_CMD_TEMP 0xF3
#define SI7015_CMD_HUMID 0xF5
#define I2C_BUS 1
#define SAMPLE_INTERVAL 5

static int i2c_handle = -1;
static FILE *file_handle = NULL;

void terminate(int signum) {
    if (i2c_handle >= 0) {
        i2cClose(i2c_handle);
    }
    if (file_handle) {
        fclose(file_handle);
    }
    exit(signum);
}

int read_sensor(int cmd, float *value) {
    uint8_t buffer[2];
    int retries = 5;
    int ret;

    while (retries--) {
        ret = i2cWriteByteData(i2c_handle, cmd);
        if (ret < 0) {
            return -1;
        }
        usleep(20000); // Wait for measurement
        ret = i2cReadByteData(i2c_handle, buffer, 2);
        if (ret < 0) {
            return -1;
        }
        if ((buffer[0] & 0x07) == 0x07) {
            // Measurement ready
            break;
        }
        usleep(1000); // Wait a bit before retrying
    }

    if (retries < 0) {
        return -1;
    }

    *value = (cmd == SI7015_CMD_TEMP) ?
        (175.72 * ((buffer[0] << 8) | buffer[1]) / 65536.0) - 46.85 :
        (125.0 * ((buffer[0] << 8) | buffer[1]) / 65536.0) - 6.0;

    return 0;
}

int main() {
    float temperature, humidity;
    struct timespec ts;
    char timestamp[64];
    int ret;

    signal(SIGINT, terminate);

    ret = gpioInitialise();
    if (ret < 0) {
        fprintf(stderr, "Failed to initialise pigpio: %s\n", pigpio_error(ret));
        return EXIT_FAILURE;
    }

    i2c_handle = i2cOpen(I2C_BUS, SI7015_ADDRESS, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Failed to open I2C bus: %s\n", strerror(-i2c_handle));
        gpioTerminate();
        return EXIT_FAILURE;
    }

    file_handle = fopen("sensor_data.txt", "a");
    if (!file_handle) {
        fprintf(stderr, "Failed to open sensor_data.txt: %s\n", strerror(errno));
        gpioTerminate();
        return EXIT_FAILURE;
    }

    while (1) {
        if (read_sensor(SI7015_CMD_TEMP, &temperature) < 0) {
            fprintf(stderr, "Failed to read temperature\n");
            terminate(EXIT_FAILURE);
        }
        if (read_sensor(SI7015_CMD_HUMID, &humidity) < 0) {
            fprintf(stderr, "Failed to read humidity\n");
            terminate(EXIT_FAILURE);
        }

        clock_gettime(CLOCK_REALTIME, &ts);
        strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", localtime(&ts.tv_sec));
        fprintf(file_handle, "%s Temperature: %.2f°C Humidity: %.2f%%\n", timestamp, temperature, humidity);
        printf("%s Temperature: %.2f°C Humidity: %.2f%%\n", timestamp, temperature, humidity);

        sleep(SAMPLE_INTERVAL);
    }

    terminate(EXIT_SUCCESS);
}

#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <string.h>
#include <fcntl.h>
#include <unistd.h>
#include <sys/ioctl.h>
#include <linux/i2c-dev.h>
#include <signal.h>
#include <time.h>

#define I2C_BUS "/dev/i2c-1"
#define SENSOR_ADDRESS 0x25
#define LOG_FILE "airflow_data.txt"
#define PRESSURE_SCALE_FACTOR 1000
#define CRC_POLYNOMIAL 0x31
#define CRC_INIT 0xFF
#define CRC_XOROUT 0xFF
#define MEASUREMENT_INTERVAL 100 // ms
#define PRESSURE_CONVERSION_FACTOR 0.001 // Pa per bit

volatile sig_atomic_t stop = 0;

void signal_handler(int signum) {
    stop = 1;
}

uint8_t crc8(const uint8_t *data, size_t len) {
    uint8_t crc = CRC_INIT;
    for (size_t i = 0; i < len; i++) {
        crc ^= data[i];
        for (int j = 0; j < 8; j++) {
            if (crc & 0x80) {
                crc = (crc << 1) ^ CRC_POLYNOMIAL;
            } else {
                crc <<= 1;
            }
        }
    }
    return crc ^ CRC_XOROUT;
}

int main() {
    int i2c_fd, log_fd;
    struct timespec sleep_time = {0, MEASUREMENT_INTERVAL * 1000000};
    uint8_t buffer[9];
    uint32_t pressure, temperature, scale_factor;
    FILE *log_file;

    if ((i2c_fd = open(I2C_BUS, O_RDWR)) < 0) {
        perror("Failed to open I2C bus");
        return EXIT_FAILURE;
    }

    if (ioctl(i2c_fd, I2C_SLAVE, SENSOR_ADDRESS) < 0) {
        perror("Failed to set I2C address");
        close(i2c_fd);
        return EXIT_FAILURE;
    }

    if ((log_fd = open(LOG_FILE, O_WRONLY | O_CREAT | O_APPEND, 0666)) < 0) {
        perror("Failed to open log file");
        close(i2c_fd);
        return EXIT_FAILURE;
    }

    log_file = fdopen(log_fd, "a");
    if (!log_file) {
        perror("Failed to open log file stream");
        close(i2c_fd);
        close(log_fd);
        return EXIT_FAILURE;
    }

    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    fprintf(log_file, "Timestamp,Pressure (Pa),Temperature (°C)\n");

    while (!stop) {
        if (write(i2c_fd, "\x36\x2F", 2) != 2) {
            perror("Failed to write command");
            break;
        }
        nanosleep(&sleep_time, NULL);

        if (read(i2c_fd, buffer, 9) != 9) {
            perror("Failed to read data");
            break;
        }

        if (crc8(buffer, 3) != buffer[3] || crc8(buffer + 3, 3) != buffer[6] || crc8(buffer + 6, 3) != buffer[9]) {
            fprintf(stderr, "CRC error\n");
            break;
        }

        pressure = (buffer[0] << 16) | (buffer[1] << 8) | buffer[2];
        temperature = (buffer[4] << 16) | (buffer[5] << 8) | buffer[6];
        scale_factor = (buffer[7] << 16) | (buffer[8] << 8) | buffer[9];

        fprintf(log_file, "%ld,%f,%f\n", time(NULL), (double)pressure / PRESSURE_SCALE_FACTOR * PRESSURE_CONVERSION_FACTOR, (double)temperature / 200 - 45);
    }

    fclose(log_file);
    close(i2c_fd);
    close(log_fd);

    return EXIT_SUCCESS;
}

#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <pigpio.h>

#define SENSIRION_I2C_ADDRESS 0x4A
#define SENSIRION_CMD_HIGH_REP 0x2C06
#define SENSIRION_CRC_POLYNOMIAL 0x31
#define SENSIRION_CRC_INIT 0xFF
#define SENSIRION_DATA_BYTES 2
#define SENSIRION_CRC_BYTE 1
#define SENSIRION_CONVERSION_TIME 15 // ms

#define LOG_FILE "enclosure_temp_log.txt"
#define ERROR_LOG_FILE "error_log.txt"

volatile sig_atomic_t running = 1;

void signal_handler(int signum) {
    running = 0;
}

int calculate_crc8(const uint8_t *data, size_t length) {
    uint8_t crc = SENSIRION_CRC_INIT;
    for (size_t i = 0; i < length; i++) {
        crc ^= data[i];
        for (int j = 0; j < 8; j++) {
            if (crc & 0x80) {
                crc = (crc << 1) ^ SENSIRION_CRC_POLYNOMIAL;
            } else {
                crc <<= 1;
            }
        }
    }
    return crc;
}

int main() {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Failed to initialize pigpio library\n");
        return EXIT_FAILURE;
    }

    if (signal(SIGINT, signal_handler) == SIG_ERR) {
        fprintf(stderr, "Failed to set signal handler\n");
        gpioTerminate();
        return EXIT_FAILURE;
    }

    int i2c_handle = gpioI2COpen(1, SENSIRION_I2C_ADDRESS);
    if (i2c_handle < 0) {
        fprintf(stderr, "Failed to open I2C bus\n");
        gpioTerminate();
        return EXIT_FAILURE;
    }

    FILE *log_file = fopen(LOG_FILE, "a");
    if (!log_file) {
        fprintf(stderr, "Failed to open log file\n");
        gpioTerminate();
        return EXIT_FAILURE;
    }

    FILE *error_log_file = fopen(ERROR_LOG_FILE, "a");
    if (!error_log_file) {
        fprintf(stderr, "Failed to open error log file\n");
        fclose(log_file);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    while (running) {
        uint8_t command[2] = {SENSIRION_CMD_HIGH_REP >> 8, SENSIRION_CMD_HIGH_REP & 0xFF};
        if (gpioI2CWrite(i2c_handle, command, sizeof(command)) != sizeof(command)) {
            fprintf(error_log_file, "%ld: Failed to write command to sensor\n", time(NULL));
            continue;
        }

        usleep(SENSIRION_CONVERSION_TIME * 1000);

        uint8_t response[SENSIRION_DATA_BYTES + SENSIRION_CRC_BYTE];
        if (gpioI2CRead(i2c_handle, response, sizeof(response)) != sizeof(response)) {
            fprintf(error_log_file, "%ld: Failed to read response from sensor\n", time(NULL));
            continue;
        }

        if (calculate_crc8(response, SENSIRION_DATA_BYTES) != response[SENSIRION_DATA_BYTES]) {
            fprintf(error_log_file, "%ld: CRC mismatch\n", time(NULL));
            continue;
        }

        int16_t raw_value = (response[0] << 8) | response[1];
        double temperature = -45 + 175 * (raw_value / 65535.0);

        fprintf(log_file, "%ld: %.2f\n", time(NULL), temperature);
    }

    fclose(log_file);
    fclose(error_log_file);
    gpioI2CClose(i2c_handle);
    gpioTerminate();

    return EXIT_SUCCESS;
}

