        if (crc8(data, SHT40_DATA_LEN - 1) != data[SHT40_DATA_LEN - 1]) {
            printf("CRC failure\n");
            continue;
        }

        int16_t raw_temp = (data[0] << 8) | data[1];
        float temp = -45 + 175 * raw_temp / 65535.0;

        int16_t raw_humidity = (data[3] << 8) | data[4];
