#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <string.h>
#include <fcntl.h>
#include <unistd.h>
#include <sys/ioctl.h>
#include <linux/i2c-dev.h>
#include <signal.h>
#include <time.h>

#define I2C_BUS "/dev/i2c-1"
#define SENSIRION_SDP800_ADDRESS 0x25
#define SENSIRION_SDP800_CMD 0x362F
#define SENSIRION_SDP800_CRC_POLYNOMIAL 0x31
#define SENSIRION_SDP800_CRC_INIT 0xFF
#define SENSIRION_SDP800_PRESSURE_SCALE_FACTOR 240
#define SENSIRION_SDP800_TEMPERATURE_SCALE 200
#define SENSIRION_SDP800_TEMPERATURE_OFFSET -45
#define LOG_FILE "airflow_data.txt"

int i2c_fd;
FILE *log_fd;

void cleanup(int signum) {
    close(i2c_fd);
    fclose(log_fd);
    exit(signum);
}

uint8_t calculate_crc8(uint8_t *data, size_t length) {
    uint8_t crc = SENSIRION_SDP800_CRC_INIT;
    for (size_t i = 0; i < length; i++) {
        crc ^= data[i];
        for (int j = 0; j < 8; j++) {
            if (crc & 0x80) {
                crc = (crc << 1) ^ SENSIRION_SDP800_CRC_POLYNOMIAL;
            } else {
                crc <<= 1;
            }
        }
    }
    return crc;
}

int main() {
    struct sigaction sigact;
    memset(&sigact, 0, sizeof(sigact));
    sigact.sa_handler = cleanup;
    sigaction(SIGINT, &sigact, NULL);

    i2c_fd = open(I2C_BUS, O_RDWR);
    if (i2c_fd < 0) {
        perror("Failed to open i2c bus");
        return 1;
    }

    if (ioctl(i2c_fd, I2C_SLAVE, SENSIRION_SDP800_ADDRESS) < 0) {
        perror("Failed to acquire bus access and/or talk to slave");
        return 1;
    }

    uint8_t cmd[2] = {0x36, 0x2F};
    if (write(i2c_fd, cmd, sizeof(cmd)) != sizeof(cmd)) {
        perror("Failed to write command");
        return 1;
    }

    usleep(1000); // Wait at least 1 ms

    uint8_t response[6];
    if (read(i2c_fd, response, sizeof(response)) != sizeof(response)) {
        perror("Failed to read response");
        return 1;
    }

    uint8_t crc = calculate_crc8(response, sizeof(response) - 2);
    if (crc != response[sizeof(response) - 2]) {
        fprintf(stderr, "CRC mismatch\n");
        return 1;
    }

    int16_t raw_pressure = (response[0] << 8) | response[1];
    int16_t raw_temperature = (response[3] << 8) | response[4];

    float pressure = raw_pressure / (float)SENSIRION_SDP800_PRESSURE_SCALE_FACTOR;
