#include <signal.h>
#include <time.h>
#include <pigpio.h>

#define I2C_BUS 1
#define I2C_ADDRESS 0x40
#define GPIO_FAN 18
#define BUFFER_SIZE 60
#define RETRIES 3

typedef struct {
    time_t timestamp;
    float temperature;
    float humidity;
} Reading;

Reading buffer[BUFFER_SIZE];
int buffer_head = 0;
int buffer_count = 0;

void handle_sigint(int signum) {
    gpio_write(GPIO_FAN, 0);
    gpioTerminate();
    exit(0);
}

int read_sensor(int command, float *value) {
    int retries = RETRIES;
    while (retries--) {
        uint8_t txbuf[1] = {command};
        uint8_t rxbuf[2];
        if (i2cWriteReadDevice(I2C_BUS, I2C_ADDRESS, txbuf, 1, rxbuf, 2) == 2) {
            *value = (rxbuf[0] << 8) | rxbuf[1];
            return 0;
        }
        usleep(1000); // wait for sensor to stabilize
    }
    return -1;
}

int main() {
    signal(SIGINT, handle_sigint);

    if (gpioInitialise() < 0) {
        fprintf(stderr, "Failed to initialize pigpio\n");
        return 1;
    }

    if (i2cOpen(I2C_BUS, I2C_ADDRESS, 0) < 0) {
        fprintf(stderr, "Failed to open I2C bus\n");
        gpioTerminate();
        return 1;
    }

    gpioSetMode(GPIO_FAN, PI_OUTPUT);
    gpioWrite(GPIO_FAN, 0);

    while (1) {
        float temperature, humidity;
        if (read_sensor(0xE3, &temperature) == 0 && read_sensor(0xE5, &humidity) == 0) {
            temperature = 175.72 * temperature / 65536.0 - 46.85;
            humidity = 125.0 * humidity / 65536.0 - 6.0;

            time_t now = time(NULL);
            buffer[buffer_head].timestamp = now;
            buffer[buffer_head].temperature = temperature;
            buffer[buffer_head].humidity = humidity;
            buffer_head = (buffer_head + 1) % BUFFER_SIZE;
            if (buffer_count < BUFFER_SIZE) buffer_count++;

            printf("%ld: %.2f°C, %.2f%%\n", now, temperature, humidity);

            if (temperature > 28.0) {
                gpioWrite(GPIO_FAN, 1);
            } else if (temperature < 27.0) {
                gpioWrite(GPIO_FAN, 0);
            }
        } else {
            fprintf(stderr, "Failed to read sensor\n");
        }

        sleep(2);
    }

    return 0;
}

#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <signal.h>
#include <time.h>
#include <pigpio.h>

#define SCD40_I2C_ADDRESS 0x62
#define SCD40_I2C_BUS 1
#define SCD40_MEASUREMENT_INTERVAL 5
#define SCD40_START_PERIODIC_MEASUREMENT 0x21B1
#define SCD40_READ_MEASUREMENT 0xEC05
#define SCD40_DATA_READY_FLAG 0xE4B8
#define SCD40_STOP_PERIODIC_MEASUREMENT 0x3F86
#define SCD40_CRC_POLYNOMIAL 0x31
#define SCD40_CRC_INIT 0xFF
#define SCD40_LOG_FILE "air_quality.log"

volatile sig_atomic_t stop_requested = 0;

void signal_handler(int signum) {
    stop_requested = 1;
}

uint8_t calculate_crc8(const uint8_t *data, size_t length) {
    uint8_t crc = SCD40_CRC_INIT;
    for (size_t i = 0; i < length; i++) {
        crc ^= data[i];
        for (int j = 0; j < 8; j++) {
            if (crc & 0x80) {
                crc = (crc << 1) ^ SCD40_CRC_POLYNOMIAL;
            } else {
                crc <<= 1;
            }
        }
    }
    return crc;
}

int main() {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Failed to initialize pigpio\n");
        return EXIT_FAILURE;
    }

    int i2c_handle = i2cOpen(SCD40_I2C_BUS, SCD40_I2C_ADDRESS, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Failed to open I2C bus\n");
        gpioTerminate();
        return EXIT_FAILURE;
    }

    FILE *log_file = fopen(SCD40_LOG_FILE, "w");
    if (!log_file) {
        fprintf(stderr, "Failed to open log file\n");
        i2cClose(i2c_handle);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    signal(SIGINT, signal_handler);

    uint16_t raw_co2, raw_temperature, raw_humidity;
    uint8_t command[2] = {0x21, 0xB1};
    uint8_t response[9];
    time_t timestamp;
    struct tm *timeinfo;

    if (i2cWriteFile(i2c_handle, command, sizeof(command)) != sizeof(command)) {
        fprintf(stderr, "Failed to send start measurement command\n");
        goto cleanup;
    }

    while (!stop_requested) {
        if (i2cReadFile(i2c_handle, response, sizeof(response)) != sizeof(response)) {
            fprintf(stderr, "Failed to read measurement data\n");
            goto cleanup;
        }

        if (response[0] != SCD40_DATA_READY_FLAG) {
            fprintf(stderr, "Measurement data not ready\n");
            continue;
        }

        if (response[8] != calculate_crc8(response, 8)) {
            fprintf(stderr, "Measurement data CRC check failed\n");
            continue;
        }

        raw_co2 = (response[1] << 8) | response[2];
        raw_temperature = (response[3] << 8) | response[4];
        raw_humidity = (response[5] << 8) | response[6];

        timestamp = time(NULL);
        timeinfo = localtime(&timestamp);

        fprintf(log_file, "%04d-%02d-%02d %02d:%02d:%02d,%d,%.2f,%.2f\n",
                1900 + timeinfo->tm_year, 1 + timeinfo->tm_mon, timeinfo->tm_mday,
                timeinfo->tm_hour, timeinfo->tm_min, timeinfo->tm_sec,
                raw_co2, -45 + 175 * raw_temperature / (1 << 16),
                100 * raw_humidity / (1 << 16));

        fflush(log_file);
    }

    command[0] = 0x3F;
    command[1] = 0x86;
    if (i2cWriteFile(i2c_handle, command, sizeof(command)) != sizeof(command)) {
        fprintf(stderr, "Failed to send stop measurement command\n");
    }

cleanup:
    fclose(log_file);
    i2cClose(i2c_handle);
    gpioTerminate();
    return EXIT_SUCCESS;
}

#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <signal.h>
#include <pigpio.h>
#include <stdint.h>

#define SCD40_I2C_ADDRESS 0x62
#define SCD40_MEASUREMENT_INTERVAL 5000
#define SCD40_MAX_LOGGED_READINGS 20
#define SCD40_CO2_THRESHOLD 1000
#define SCD40_CRC_POLYNOMIAL 0x31
#define SCD40_CRC_INIT 0xFF

typedef struct {
    uint16_t co2;
    float temperature;
    float humidity;
} SCD40_Reading;

SCD40_Reading readings[SCD40_MAX_LOGGED_READINGS];
int reading_count = 0;
bool led_on = false;

void handle_sigint(int signum) {
    gpioTerminate();
    exit(0);
}

uint8_t crc8(const uint8_t *data, size_t len) {
    uint8_t crc = SCD40_CRC_INIT;
    for (size_t i = 0; i < len; i++) {
        crc ^= data[i];
        for (int j = 0; j < 8; j++) {
            if (crc & 0x80) {
                crc = (crc << 1) ^ SCD40_CRC_POLYNOMIAL;
            } else {
                crc <<= 1;
            }
        }
    }
    return crc;
}

bool scd40_read_measurement(uint16_t *co2, float *temperature, float *humidity) {
    uint8_t buffer[9];
    if (i2cReadByteData(SCD40_I2C_ADDRESS, 0xEC05, buffer, sizeof(buffer)) != sizeof(buffer)) {
        return false;
    }
    if (crc8(buffer, 8) != buffer[8]) {
        return false;
    }
    *co2 = (buffer[0] << 8) | buffer[1];
    *temperature = (buffer[3] << 8) | buffer[4];
    *humidity = (buffer[6] << 8) | buffer[7];
    return true;
}

void scd40_start_periodic_measurement() {
    i2cWriteByteData(SCD40_I2C_ADDRESS, 0x21B1);
}

void scd40_stop_periodic_measurement() {
    i2cWriteByteData(SCD40_I2C_ADDRESS, 0x3F86);
}

void scd40_measure() {
    uint16_t co2;
    float temperature, humidity;
    if (scd40_read_measurement(&co2, &temperature, &humidity)) {
        readings[reading_count % SCD40_MAX_LOGGED_READINGS] = (SCD40_Reading){co2, temperature, humidity};
        reading_count++;
        if (co2 > SCD40_CO2_THRESHOLD) {
            if (!led_on) {
                gpioWrite(17, 1);
                led_on = true;
            }
        } else {
            if (led_on) {
                gpioWrite(17, 0);
                led_on = false;
            }
        }
        printf("CO2: %d ppm, Temperature: %.2f°C, Humidity: %.2f%%\n", co2, temperature, humidity);
    }
}

int main() {
    signal(SIGINT, handle_sigint);
    signal(SIGTERM, handle_sigint);

    if (gpioInitialise() < 0) {
        fprintf(stderr, "Failed to initialize pigpio\n");
        return 1;
    }

    if (i2cOpen(1, SCD40_I2C_ADDRESS, 0) < 0) {
        fprintf(stderr, "Failed to open I2C bus 1\n");
        gpioTerminate();
        return 1;
    }

    gpioSetMode(17, PI_OUTPUT);
    gpioWrite(17, 0);

    scd40_start_periodic_measurement();

    while (1) {
        scd40_measure();
        sleep(SCD40_MEASUREMENT_INTERVAL / 1000);
    }

    scd40_stop_periodic_measurement();

    i2cClose(1);
    gpioTerminate();

    return 0;
}

#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <pigpio.h>

#define GPIO_PIN 4
#define SAMPLE_INTERVAL 5000000 // 5 seconds
#define TIMEOUT 500000 // 0.5 seconds
#define ERROR_THRESHOLD 3

volatile sig_atomic_t stop = 0;

void signal_handler(int signum) {
    stop = 1;
}

int main() {
    FILE *log_file;
    int failures = 0;
    int fd;
    uint32_t tick;
    uint32_t last_tick = 0;
    uint32_t high_time, total_time;
    float temperature;

    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    if ((fd = gpioInitialise()) < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return EXIT_FAILURE;
    }

    if ((log_file = fopen("temperature_log.txt", "a")) == NULL) {
        fprintf(stderr, "Failed to open log file\n");
        gpioTerminate();
        return EXIT_FAILURE;
    }

    gpioSetMode(GPIO_PIN, PI_INPUT);

    while (!stop) {
        if (gpioGetPulseWidthRange(GPIO_PIN, &high_time, &total_time, TIMEOUT)) {
            if (high_time == 0 || total_time == 0) {
                fprintf(stderr, "Sensor stuck or disconnected\n");
                failures++;
            } else {
                temperature = 4215 - (2143 * (float)high_time / (float)total_time);
                if (temperature < -40 || temperature > 150) {
                    fprintf(stderr, "Invalid temperature reading\n");
                    failures++;
                } else {
                    time_t now = time(NULL);
                    struct tm *t = localtime(&now);
                    char timestamp[26];
                    strftime(timestamp, sizeof(timestamp), "%Y-%m-%dT%H:%M:%S", t);
                    fprintf(log_file, "%s, %.2f\n", timestamp, temperature);
                    fflush(log_file);
                    failures = 0;
                }
            }
        } else {
            fprintf(stderr, "Timeout waiting for pulse\n");
            failures++;
        }

        if (failures >= ERROR_THRESHOLD) {
            fprintf(log_file, "SENSOR MALFUNCTION\n");
            fflush(log_file);
            break;
        }

        tick = gpioTick();
        while ((tick - last_tick) < SAMPLE_INTERVAL) {
            tick = gpioTick();
        }
        last_tick = tick;
    }

    fclose(log_file);
    gpioTerminate();
    return EXIT_SUCCESS;
}

