        uint8_t command[2] = {SHT35_CMD_HIGHREP_NO_STRETCH, SHT35_CMD_HIGHREP_NO_STRETCH_ACK};
        if (i2cWriteFile(i2c_handle, command, sizeof(command)) != sizeof(command)) {
            printf("I2C write failed\n");
            continue;
        }

        usleep(SHT35_MEASUREMENT_TIME * 1000);

        uint8_t response[6];
