        float temperature = response[0] * 175.0 / 65535.0 - 45.0;
        float humidity = response[1] * 100.0 / 65535.0;
        temperature += sin(time(NULL)) * 2;
        humidity += sin(time(NULL)) * 5;

        // Log data
        char buffer[100];
        strftime(buffer, sizeof(buffer), "%Y-%m-%dT%H:%M:%SZ", gmtime(&response[3]));
        fprintf(file, "%s, %.2f, %.2f\n", buffer, temperature, humidity);

        fflush(file);
    }

    i2cClose(i2c_handle);
    fclose(file);
    gpioTerminate();

    return EXIT_SUCCESS;
}

