#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <fcntl.h>
#include <unistd.h>
#include <signal.h>
#include <sys/ioctl.h>
#include <linux/i2c-dev.h>
#include <time.h>

#define I2C_BUS 1
#define I2C_ADDRESS 0x25
#define PRESSURE_SENSOR_ADDRESS 0x36
#define CONVERSION_TIME 45 // ms
#define CSV_FILE_NAME "airflow.csv"
#define CRC_POLYNOMIAL 0x31
#define CRC_INITIAL 0xFF
#define PRESSURE_LSB 0.000064 // Pa
#define TEMPERATURE_LSB 0.0025 // °C

volatile sig_atomic_t stop = 0;

void signal_handler(int signum) {
    stop = 1;
}

int main() {
    int i2c_fd, file_fd;
    struct timespec sleep_time = {0, 100000000}; // 1 second
    unsigned char buffer[9];
    unsigned char crc;
    int pressure, temperature;
    time_t rawtime;
    struct tm * timeinfo;
    char time_string[20];

    if ((i2c_fd = open("/dev/i2c-1", O_RDWR)) < 0) {
        perror("Failed to open the i2c bus");
        return 1;
    }

    if (ioctl(i2c_fd, I2C_SLAVE, I2C_ADDRESS) < 0) {
        perror("Failed to acquire bus access and/or talk to slave");
        return 1;
    }

    if ((file_fd = open(CSV_FILE_NAME, O_WRONLY | O_CREAT | O_TRUNC, 0644)) < 0) {
        perror("Failed to open CSV file");
        return 1;
    }

    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    while (!stop) {
        if (write(i2c_fd, &PRESSURE_SENSOR_ADDRESS, 1) != 1) {
            perror("Failed to write to i2c device");
            return 1;
        }

        nanosleep(&sleep_time, NULL);

        if (read(i2c_fd, buffer, 9) != 9) {
            perror("Failed to read from i2c device");
            return 1;
        }

        crc = CRC_INITIAL;
        for (int i = 0; i < 8; i++) {
            crc ^= buffer[i];
            for (int j = 0; j < 8; j++) {
                if (crc & 0x80) {
                    crc = (crc << 1) ^ CRC_POLYNOMIAL;
                } else {
                    crc <<= 1;
                }
            }
        }

        if (crc != buffer[8]) {
            printf("CRC error\n");
            continue;
        }

        pressure = (buffer[0] << 8) | buffer[1];
        temperature = (buffer[2] << 8) | buffer[3];

        pressure = (pressure >> 2) * PRESSURE_LSB;
        temperature = (temperature >> 2) * TEMPERATURE_LSB;

        time(&rawtime);
        timeinfo = localtime(&rawtime);
        strftime(time_string, sizeof(time_string), "%Y-%m-%d %H:%M:%S", timeinfo);

        dprintf(file_fd, "%s,%d,%d\n", time_string, pressure, temperature);
    }

    close(i2c_fd);
    close(file_fd);

    return 0;
}

#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <pigpio.h>
#include <crc8.h>

#define SHT35_ADDRESS 0x44
#define SHT35_CMD_HIGHREP_STRETCHING_DISABLED 0x2400
#define SHT35_DATA_BYTES 6
#define SHT35_CRC_POLYNOMIAL 0x31
#define SHT35_CRC_INIT_VALUE 0xFF
#define CSV_FILENAME "environment.csv"

volatile sig_atomic_t running = 1;

void signal_handler(int signum) {
    running = 0;
}

int main() {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Failed to initialize pigpio\n");
        return EXIT_FAILURE;
    }

    if (signal(SIGINT, signal_handler) == SIG_ERR || signal(SIGTERM, signal_handler) == SIG_ERR) {
        fprintf(stderr, "Failed to set signal handler\n");
        gpioTerminate();
        return EXIT_FAILURE;
    }

    int i2c_handle = i2cOpen(1, SHT35_ADDRESS, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Failed to open I2C bus\n");
        gpioTerminate();
        return EXIT_FAILURE;
    }

    FILE *csv_file = fopen(CSV_FILENAME, "a");
    if (!csv_file) {
        fprintf(stderr, "Failed to open CSV file\n");
        gpioTerminate();
        i2cClose(i2c_handle);
        return EXIT_FAILURE;
    }

    char header[] = "timestamp,temperature_c,humidity_pct\n";
    if (ftell(csv_file) == 0) {
        fwrite(header, sizeof(char), strlen(header), csv_file);
    }

    while (running) {
        uint16_t raw_data[SHT35_DATA_BYTES];
        uint8_t crc;

        if (i2cWriteByteData(i2c_handle, SHT35_CMD_HIGHREP_STRETCHING_DISABLED) < 0) {
            fprintf(stderr, "Failed to write command to SHT35\n");
            break;
        }

        usleep(15000);

        if (i2cReadDevice(i2c_handle, raw_data, SHT35_DATA_BYTES) < 0) {
            fprintf(stderr, "Failed to read data from SHT35\n");
            break;
        }

        crc = crc8(SHT35_CRC_POLYNOMIAL, SHT35_CRC_INIT_VALUE, raw_data, 2);
        if (crc != raw_data[2]) {
            fprintf(stderr, "Failed to validate temperature CRC\n");
            break;
        }

        crc = crc8(SHT35_CRC_POLYNOMIAL, crc, raw_data + 3, 2);
        if (crc != raw_data[5]) {
            fprintf(stderr, "Failed to validate humidity CRC\n");
            break;
        }

        float temperature_c = -45 + 175 * raw_data[0] / 65535.0;
        float humidity_pct = 100 * raw_data[3] / 65535.0;

        time_t now = time(NULL);
        struct tm *timestamp = localtime(&now);
        char buffer[20];
        strftime(buffer, sizeof(buffer), "%Y-%m-%dT%H:%M:%S", timestamp);

        fprintf(csv_file, "%s,%.2f,%.2f\n", buffer, temperature_c, humidity_pct);

        fflush(csv_file);
    }

    fclose(csv_file);
    i2cClose(i2c_handle);
    gpioTerminate();

    return EXIT_SUCCESS;
}

