#include <stdlib.h>
#include <string.h>
#include <unistd.h>
#include <fcntl.h>
#include <sys/ioctl.h>
#include <linux/i2c-dev.h>
#include <time.h>
#include <signal.h>

#define SI7021_ADDRESS 0x40
#define SI7021_MEASURE_HUMIDITY_NO_HOLD 0xF5
#define SI7021_MEASURE_TEMP_NO_HOLD 0xF3
#define SI7021_READ_TEMP_FROM_PREV_MEAS 0xE0
#define SI7021_RESET 0xFE
#define SI7021_CRC_POLYNOMIAL 0x31
#define SI7021_CRC_INIT_VALUE 0x00
#define SI7021_TIMEOUT 100 // ms

volatile sig_atomic_t running = 1;

void sig_handler(int signum) {
    running = 0;
}

int main() {
    int file;
    char filename[20];
    struct sigaction sigIntHandler;

    sigIntHandler.sa_handler = sig_handler;
    sigemptyset(&sigIntHandler.sa_mask);
    sigIntHandler.sa_flags = 0;

    sigaction(SIGINT, &sigIntHandler, NULL);
    sigaction(SIGTERM, &sigIntHandler, NULL);

    sprintf(filename, "/dev/i2c-1");
    file = open(filename, O_RDWR);
    if (file < 0) {
        fprintf(stderr, "Failed to open the i2c bus\n");
        return 1;
    }

    if (ioctl(file, I2C_SLAVE, SI7021_ADDRESS) < 0) {
        fprintf(stderr, "Failed to acquire bus access and/or talk to slave.\n");
        return 1;
    }

    FILE *logfile = fopen("environment.log", "w");
    if (!logfile) {
        fprintf(stderr, "Failed to open log file\n");
        return 1;
    }

    fprintf(logfile, "timestamp,temperature_C,humidity_percent\n");

    while (running) {
        uint8_t command = SI7021_MEASURE_HUMIDITY_NO_HOLD;
        if (write(file, &command, 1) != 1) {
            fprintf(stderr, "Failed to write humidity command\n");
            fprintf(logfile, "ERROR\n");
            continue;
        }

        uint8_t response[3];
        int attempts = 0;
        while (read(file, response, 3) != 3 && attempts++ < 10) {
            usleep(10000);
        }

        if (attempts >= 10) {
            fprintf(stderr, "Failed to read humidity response\n");
            fprintf(logfile, "ERROR\n");
            continue;
        }

        uint16_t rawHumidity = (response[0] << 8) | response[1];
        uint8_t crc = response[2];
