#include <stdlib.h>
#include <signal.h>
#include <pigpio.h>
#include <stdint.h>

#define SDP810_ADDRESS 0x25
#define SDP810_CONVERSION_TIME 100 // ms
#define SDP810_COMMAND 0x362F
#define SDP810_CRC_POLYNOMIAL 0x31
#define SDP810_CRC_INIT 0xFF
#define SDP810_CRC_XOR 0xFF

volatile sig_atomic_t running = 1;

void signal_handler(int signum) {
    running = 0;
}

int calculate_crc8(uint8_t *data, size_t length) {
    uint8_t crc = SDP810_CRC_INIT;
    for (size_t i = 0; i < length; i++) {
        crc ^= data[i];
        for (int j = 0; j < 8; j++) {
            if (crc & 0x80) {
                crc = (crc << 1) ^ SDP810_CRC_POLYNOMIAL;
            } else {
                crc <<= 1;
            }
        }
    }
    return crc ^ SDP810_CRC_XOR;
}

int main() {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Failed to initialize pigpio\n");
        return EXIT_FAILURE;
    }

    int i2c_handle = gpioI2COpen(1, SDP810_ADDRESS);
    if (i2c_handle < 0) {
        fprintf(stderr, "Failed to open I2C bus\n");
        gpioTerminate();
        return EXIT_FAILURE;
    }

    FILE *file = fopen("airflow.dat", "wb");
    if (!file) {
        fprintf(stderr, "Failed to open file\n");
        gpioI2CWrite(i2c_handle, SDP810_COMMAND, NULL, 0);
        gpioI2CRead(i2c_handle, NULL, 0);
        gpioI2COpen(1, SDP810_ADDRESS);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    while (running) {
        uint8_t command[2] = {SDP810_COMMAND >> 8, SDP810_COMMAND & 0xFF};
        if (gpioI2CWrite(i2c_handle, command, sizeof(command)) != sizeof(command)) {
            fprintf(stderr, "Failed to write command\n");
            break;
        }

        usleep(SDP810_CONVERSION_TIME * 1000);

        uint8_t buffer[9];
        if (gpioI2CRead(i2c_handle, buffer, sizeof(buffer)) != sizeof(buffer)) {
            fprintf(stderr, "Failed to read data\n");
            break;
        }

        if (calculate_crc8(buffer, 8) != buffer[8]) {
            fprintf(stderr, "CRC mismatch\n");
            break;
        }

        int16_t raw_pressure = (buffer[0] << 8) | buffer[1];
        int16_t raw_temperature = (buffer[3] << 8) | buffer[4];
        float scale_factor = (buffer[6] << 8) | buffer[7];
        float pressure = (float)raw_pressure / scale_factor - 1000.0;
        float temperature = (float)raw_temperature / 200.0 - 45.0;

        if (fwrite(&pressure, sizeof(pressure), 1, file) != 1 || fwrite(&temperature, sizeof(temperature), 1, file) != 1) {
            fprintf(stderr, "Failed to write to file\n");
            break;
        }
    }

    fclose(file);
    gpioI2CWrite(i2c_handle, SDP810_COMMAND, NULL, 0);
    gpioI2CRead(i2c_handle, NULL, 0);
    gpioI2CClose(i2c_handle);
    gpioTerminate();

    return EXIT_SUCCESS;
}

#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <pigpio.h>

#define I2C_BUS 1
#define I2C_ADDRESS 0x25
#define MEASUREMENT_COMMAND 0x3603
#define CONVERSION_TIME 45
#define SCALE_FACTOR 60.0
#define LOG_FILE "pressure_log.txt"

volatile sig_atomic_t stop = 0;

void signal_handler(int signum) {
    stop = 1;
}

uint8_t crc8(const uint8_t *data, size_t len, uint8_t crc) {
    while (len--) {
        crc ^= *data++;
        for (int i = 0; i < 8; i++) {
            if (crc & 0x80) {
                crc = (crc << 1) ^ 0x31;
            } else {
                crc <<= 1;
            }
        }
    }
    return crc;
}

int main() {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Failed to initialize pigpio\n");
        return EXIT_FAILURE;
    }

    int i2c_handle = gpioI2COpen(I2C_BUS, I2C_ADDRESS, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Failed to open I2C bus\n");
        gpioTerminate();
        return EXIT_FAILURE;
    }

    FILE *log_file = fopen(LOG_FILE, "w");
    if (!log_file) {
        fprintf(stderr, "Failed to open log file\n");
        gpioI2CWriteByteData(i2c_handle, MEASUREMENT_COMMAND);
        gpioI2CReadByteData(i2c_handle, 0);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    while (!stop) {
        if (gpioI2CWriteByteData(i2c_handle, MEASUREMENT_COMMAND) < 0) {
            fprintf(stderr, "Failed to write to I2C device\n");
            break;
        }

        usleep(CONVERSION_TIME * 1000);

        uint8_t buffer[9];
        if (gpioI2CReadByteData(i2c_handle, buffer, sizeof(buffer)) < 0) {
            fprintf(stderr, "Failed to read from I2C device\n");
            break;
        }

        if (crc8(buffer, sizeof(buffer) - 3, 0xFF) != buffer[sizeof(buffer) - 3]) {
            fprintf(stderr, "CRC check failed\n");
            break;
        }

        uint32_t raw_pressure = (buffer[0] << 16) | (buffer[1] << 8) | buffer[2];
        double pressure = raw_pressure * SCALE_FACTOR;

        time_t now = time(NULL);
        struct tm *t = localtime(&now);
        char timestamp[20];
        strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", t);

        fprintf(log_file, "%s: %.2f Pa\n", timestamp, pressure);

        sleep(5);
    }

    fclose(log_file);
    gpioI2CWriteByteData(i2c_handle, 0);
    gpioI2CReadByteData(i2c_handle, 0);
    gpioTerminate();

    return EXIT_SUCCESS;
}

#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <signal.h>
#include <time.h>
#include <pigpio.h>

#define FAN_PIN 18
#define SENSOR_ADDRESS 0x28
#define SAMPLE_INTERVAL 100 // ms
#define MIN_FLOW 0 // SLPM
#define MAX_FLOW 10 // SLPM
#define MIN_PWM 0 // %
#define MAX_PWM 100 // %

volatile sig_atomic_t running = 1;

void signal_handler(int signum) {
    running = 0;
}

int main() {
    FILE *log_file;
    int i2c_handle;
    uint16_t raw_flow;
    float flow_rate;
    uint32_t pwm_duty_cycle;
    struct timespec sleep_time = {0, SAMPLE_INTERVAL * 1000000};

    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    if ((i2c_handle = pi_i2c_open(1, SENSOR_ADDRESS)) < 0) {
        fprintf(stderr, "Failed to open I2C handle: %s\n", strerror(-i2c_handle));
        return EXIT_FAILURE;
    }

    if ((log_file = fopen("flow_log.txt", "w")) == NULL) {
        fprintf(stderr, "Failed to open log file\n");
        pi_i2c_close(i2c_handle);
        return EXIT_FAILURE;
    }

    if (gpioSetPWMfrequency(FAN_PIN, 25000) < 0) {
        fprintf(stderr, "Failed to set PWM frequency\n");
        fclose(log_file);
        pi_i2c_close(i2c_handle);
        return EXIT_FAILURE;
    }

    while (running) {
        if (pi_i2c_read_i2c_block_data(i2c_handle, 0x00, 2, (char *)&raw_flow) < 0) {
            fprintf(stderr, "Failed to read from I2C sensor\n");
            continue;
        }

        raw_flow = (raw_flow >> 2) & 0x3FFF;

        flow_rate = (float)raw_flow / 1638 * (MAX_FLOW - MIN_FLOW) + MIN_FLOW;

        pwm_duty_cycle = (uint32_t)(flow_rate / MAX_FLOW * MAX_PWM);

        gpioSetPWMdutycycle(FAN_PIN, pwm_duty_cycle);

        clock_nanosleep(CLOCK_MONOTONIC, 0, &sleep_time, NULL);

        fprintf(log_file, "%ld,%f\n", time(NULL), flow_rate);
    }

    gpioSetPWMdutycycle(FAN_PIN, 0);

    fclose(log_file);
    pi_i2c_close(i2c_handle);

    return EXIT_SUCCESS;
}

#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <pigpio.h>

#define WHO_AM_I 0x0F
#define CTRL_REG1 0x10
#define PRESS_OUT_XL 0x28
#define PRESS_OUT_L 0x29
#define PRESS_OUT_H 0x2A
#define TEMP_OUT_L 0x2B
#define TEMP_OUT_H 0x2C

volatile sig_atomic_t stop = 0;

void signal_handler(int signum) {
    stop = 1;
}

int main() {
    FILE *log_file;
    if ((log_file = fopen("environmental_data.txt", "w")) == NULL) {
        fprintf(stderr, "Error opening log file\n");
        return EXIT_FAILURE;
    }

    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        fclose(log_file);
        return EXIT_FAILURE;
    }

    gpioSetSignalFunc(SIGINT, signal_handler);

    int i2c_handle = gpioI2COpen(1, 0x5D);
    if (i2c_handle < 0) {
        fprintf(stderr, "Error opening I2C bus\n");
        gpioTerminate();
        fclose(log_file);
        return EXIT_FAILURE;
    }

    uint8_t who_am_i_reg = WHO_AM_I;
    uint8_t who_am_i_data;
    if (gpioI2CReadByteData(i2c_handle, who_am_i_reg, &who_am_i_data) < 0) {
        fprintf(stderr, "Error reading WHO_AM_I register\n");
        gpioTerminate();
        fclose(log_file);
        return EXIT_FAILURE;
    }

    if (who_am_i_data != 0xB1) {
        fprintf(stderr, "WHO_AM_I register does not match expected value\n");
        gpioTerminate();
        fclose(log_file);
        return EXIT_FAILURE;
    }

    uint8_t ctrl_reg1_data = 0xB0;
    if (gpioI2CWriteByteData(i2c_handle, CTRL_REG1, ctrl_reg1_data) < 0) {
        fprintf(stderr, "Error writing CTRL_REG1 register\n");
        gpioTerminate();
        fclose(log_file);
        return EXIT_FAILURE;
    }

    while (!stop) {
        int32_t pressure = 0;
        if (gpioI2CReadByteData(i2c_handle, PRESS_OUT_XL, (uint8_t *)&pressure) < 0 ||
            gpioI2CReadByteData(i2c_handle, PRESS_OUT_L, (uint8_t *)&pressure + 1) < 0 ||
            gpioI2CReadByteData(i2c_handle, PRESS_OUT_H, (uint8_t *)&pressure + 2) < 0) {
            fprintf(stderr, "Error reading pressure data\n");
            continue;
        }
        pressure >>= 4;

        int16_t temperature = 0;
        if (gpioI2CReadByteData(i2c_handle, TEMP_OUT_L, (uint8_t *)&temperature) < 0 ||
            gpioI2CReadByteData(i2c_handle, TEMP_OUT_H, (uint8_t *)&temperature + 1) < 0) {
            fprintf(stderr, "Error reading temperature data\n");
            continue;
        }
        temperature >>= 8;

        time_t now;
        struct tm *time_info;
        char time_str[20];
        time(&now);
        time_info = localtime_r(&now, time_str);
        strftime(time_str, sizeof(time_str), "%Y-%m-%d %H:%M:%S", time_info);

        fprintf(log_file, "%s, Pressure: %.2f hPa, Temperature: %.2f °C\n", time_str, pressure / 4096.0, 42.5 + temperature / 480.0);
        fflush(log_file);
        gpioDelay(1000000);
    }

    gpioTerminate();
    fclose(log_file);
    return EXIT_SUCCESS;
}

#include <stdio.h>
#include <stdlib.h>
#include <signal.h>
#include <pigpio.h>

#define I2C_BUS 1
#define I2C_ADDRESS 0x48
#define TEMPERATURE_REGISTER 0x00
#define LED_PIN 17
#define BUFFER_SIZE 10
#define ALARM_TEMP 28.0

volatile sig_atomic_t stop = 0;

void signal_handler(int signum) {
    stop = 1;
}

int main() {
    int i2c_handle;
    float buffer[BUFFER_SIZE];
    float sum = 0.0;
    int buffer_index = 0;
    float average;
    float temperature;

    if (gpioInitialise() < 0) {
        fprintf(stderr, "Failed to initialize pigpio\n");
        return EXIT_FAILURE;
    }

    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    i2c_handle = gpioI2COpen(I2C_BUS, I2C_ADDRESS, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Failed to open I2C bus\n");
        gpioTerminate();
        return EXIT_FAILURE;
    }

    gpioSetMode(LED_PIN, PI_OUTPUT);

    while (!stop) {
        uint16_t raw_temp;
        int read_status = gpioI2CReadWordData(i2c_handle, TEMPERATURE_REGISTER);
        if (read_status < 0) {
            continue;
        }

        raw_temp = (uint16_t)read_status;
        temperature = ((float)((raw_temp >> 7) & 0xFF)) / 2.0;

        buffer[buffer_index] = temperature;
        sum -= buffer[buffer_index];
        sum += temperature;
        buffer_index = (buffer_index + 1) % BUFFER_SIZE;
        average = sum / BUFFER_SIZE;

        if (average > ALARM_TEMP) {
            gpioWrite(LED_PIN, PI_HIGH);
        } else {
            gpioWrite(LED_PIN, PI_LOW);
        }

        printf("Temperature: %.2f°C, Average: %.2f°C\n", temperature, average);
        sleep(1);
    }

    gpioI2CClose(i2c_handle);
    gpioTerminate();
    return EXIT_SUCCESS;
}

#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <pigpio.h>

#define SCD30_ADDRESS 0x61
#define SCD30_INTERVAL 2000
#define SCD30_CRC_POLYNOMIAL 0x31
#define SCD30_CRC_INIT_VALUE 0xFF
#define SCD30_DATA_READY 0x0202
#define SCD30_MEASUREMENT 0x0300
#define SCD30_LOG_FILE "air_quality.log"

volatile sig_atomic_t stop = 0;

void signal_handler(int signum) {
    stop = 1;
}

int scd30_crc8(const uint8_t *data, size_t len) {
    uint8_t crc = SCD30_CRC_INIT_VALUE;
    for (size_t i = 0; i < len; i++) {
        crc ^= data[i];
        for (int j = 0; j < 8; j++) {
            if (crc & 0x80) {
                crc = (crc << 1) ^ SCD30_CRC_POLYNOMIAL;
            } else {
                crc <<= 1;
            }
        }
    }
    return crc;
}

int main() {
    int i2c_handle;
    FILE *log_file;
    struct sigaction action;
    struct timespec sleep_time = {0, SCD30_INTERVAL * 1000 * 1000};

    action.sa_handler = signal_handler;
    sigemptyset(&action.sa_mask);
    action.sa_flags = 0;
    sigaction(SIGINT, &action, NULL);
    sigaction(SIGTERM, &action, NULL);

    if (gpioInitialise() < 0) {
        printf("Failed to initialize pigpio\n");
        return 0;
    }

    i2c_handle = i2cOpen(1, SCD30_ADDRESS, 0);
    if (i2c_handle < 0) {
        printf("Failed to open I2C bus\n");
        gpioTerminate();
        return 0;
    }

    log_file = fopen(SCD30_LOG_FILE, "w");
    if (log_file == NULL) {
        printf("Failed to open log file\n");
        i2cClose(i2c_handle);
        gpioTerminate();
        return 0;
    }

    while (!stop) {
        uint8_t command[2] = {SCD30_DATA_READY, 0x00};
        uint8_t response[3] = {0};
        int ready = 0;

        i2cWriteDevice(i2c_handle, command, 2);
        while (!ready) {
            i2cReadDevice(i2c_handle, response, 3);
            if (response[0] == 0x01 && response[1] == 0x00 && response[2] == 0x00) {
                ready = 1;
            }
        }

        command[0] = SCD30_MEASUREMENT;
        command[1] = 0x00;
        i2cWriteDevice(i2c_handle, command, 2);
        i2cReadDevice(i2c_handle, response, 18);

        if (scd30_crc8(response, 18) != response[17]) {
            printf("CRC mismatch\n");
            continue;
        }

        uint16_t co2 = (response[0] << 8) | response[1];
        int16_t temp = (response[3] << 8) | response[4];
        int16_t humidity = (response[6] << 8) | response[7];

        time_t now = time(NULL);
        struct tm *time_info = gmtime(&now);
        char time_str[20];
        strftime(time_str, sizeof(time_str), "%Y-%m-%dT%H:%M:%SZ", time_info);

        fprintf(log_file, "%s, %d, %.2f, %.2f\n", time_str, co2, temp / 1000.0, humidity / 1000.0);

        if (co2 < 800) {
            printf("Ventilation system: OFF\n");
        } else if (co2 < 1200) {
            printf("Ventilation system: LOW\n");
        } else {
            printf("Ventilation system: HIGH\n");
        }

        fflush(log_file);
        nanosleep(&sleep_time, NULL);
    }

    fclose(log_file);
    i2cClose(i2c_handle);
    gpioTerminate();

    return 0;
}

