#include <pigpio.h>

#define I2C_ADDRESS 0x63
#define I2C_BUS 1
#define CALIBRATION_COMMAND 0x50
#define MEASUREMENT_COMMAND 0x40
#define MEASUREMENT_DELAY 7
#define TEMPERATURE_OFFSET 3
#define PRESSURE_OFFSET 0
#define TEMPERATURE_SCALE_FACTOR 0.5
#define PRESSURE_SCALE_FACTOR 0.25
#define TEMPERATURE_LSB 0.0025
#define PRESSURE_LSB 0.25
#define TEMPERATURE_MIN -40
#define TEMPERATURE_MAX 85
#define PRESSURE_MIN 30000
#define PRESSURE_MAX 110000

volatile sig_atomic_t running = 1;

void signal_handler(int signum) {
    running = 0;
}

int main() {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Failed to initialize pigpio library\n");
        return EXIT_FAILURE;
    }

    struct sigaction action;
    memset(&action, 0, sizeof(struct sigaction));
    action.sa_handler = signal_handler;
    sigaction(SIGINT, &action, NULL);
    sigaction(SIGTERM, &action, NULL);

    uint8_t calibration_data[8];
    if (gpioI2CReadDevice(I2C_BUS, I2C_ADDRESS, CALIBRATION_COMMAND, calibration_data, 8) < 0) {
        fprintf(stderr, "Failed to read calibration data from sensor\n");
        gpioTerminate();
        return EXIT_FAILURE;
    }

    int16_t scale_factor_lut = (calibration_data[0] << 8) | calibration_data[1];
    int16_t scale_factor_h = (calibration_data[2] << 8) | calibration_data[3];
    int16_t scale_factor_p = (calibration_data[4] << 8) | calibration_data[5];

    while (running) {
        uint8_t measurement_data[6];
        if (gpioI2CReadDevice(I2C_BUS, I2C_ADDRESS, MEASUREMENT_COMMAND, measurement_data, 6) < 0) {
            fprintf(stderr, "Failed to read measurement data from sensor\n");
            break;
        }

        int16_t raw_temperature = (measurement_data[TEMPERATURE_OFFSET] << 8) | measurement_data[TEMPERATURE_OFFSET + 1];
        int32_t raw_pressure = (measurement_data[PRESSURE_OFFSET] << 16) | (measurement_data[PRESSURE_OFFSET + 1] << 8) | measurement_data[PRESSURE_OFFSET + 2];

        float temperature = raw_temperature * TEMPERATURE_SCALE_FACTOR + TEMPERATURE_LSB * scale_factor_lut;
        float pressure = raw_pressure * PRESSURE_SCALE_FACTOR + PRESSURE_LSB * scale_factor_p;

        if (temperature < TEMPERATURE_MIN || temperature > TEMPERATURE_MAX || pressure < PRESSURE_MIN || pressure > PRESSURE_MAX) {
            fprintf(stderr, "Sensor data out of range\n");
            break;
        }

        time_t now = time(NULL);
        struct tm *timeinfo = localtime(&now);
        char buffer[26];
        strftime(buffer, sizeof(buffer), "%Y-%m-%dT%H:%M:%S", timeinfo);

        printf("%s - Temperature: %.2f C, Pressure: %.2f Pa\n", buffer, temperature, pressure);

        gpioDelay(MEASUREMENT_DELAY * 1000);
    }

    gpioTerminate();
    return EXIT_SUCCESS;
}

