#define I2C_BUS "/dev/i2c-1"
#define SENSOR_ADDRESS 0x60
#define PRESSURE_MSB_REG 0xAA
#define PRESSURE_LSB_REG 0xAB
#define PRESSURE_SCALE_FACTOR 0.1

int i2c_fd = -1;
volatile sig_atomic_t stop = 0;

void sig_handler(int signum) {
    stop = 1;
}

int main() {
    struct sigaction sigIntHandler;

    sigIntHandler.sa_handler = sig_handler;
    sigemptyset(&sigIntHandler.sa_mask);
    sigIntHandler.sa_flags = 0;

    sigaction(SIGINT, &sigIntHandler, NULL);
    sigaction(SIGTERM, &sigIntHandler, NULL);

    if ((i2c_fd = open(I2C_BUS, O_RDWR)) < 0) {
        perror("Failed to open the i2c bus");
        return EXIT_FAILURE;
    }

    if (ioctl(i2c_fd, I2C_SLAVE, SENSOR_ADDRESS) < 0) {
        perror("Failed to acquire bus access and/or talk to slave");
        close(i2c_fd);
        return EXIT_FAILURE;
    }

    while (!stop) {
        uint8_t msb, lsb;
        int16_t raw_pressure;
        float kpa;

        // Trigger a measurement
        if (write(i2c_fd, &PRESSURE_MSB_REG, 1) != 1) {
            perror("Failed to write to sensor");
            continue;
        }

        // Read the MSB and LSB
        if (read(i2c_fd, &msb, 1) != 1 || read(i2c_fd, &lsb, 1) != 1) {
            perror("Failed to read from sensor");
            continue;
        }

        // Combine MSB and LSB into a 16-bit integer
        raw_pressure = (msb << 8) | lsb;

        // Convert to kPa
        kpa = raw_pressure * PRESSURE_SCALE_FACTOR;

        // Log the reading with a timestamp
        time_t now = time(NULL);
        char *time_str = ctime(&now);
        time_str[strcspn(time_str, "\n")] = 0; // Remove newline
        printf("%s: %.2f kPa\n", time_str, kpa);
    }

    close(i2c_fd);
    return EXIT_SUCCESS;
}

