#define PRESSURE_LOG_FILE "pressure_log.txt"
#define PRESSURE_CONVERSION_FACTOR 60.0
#define TEMPERATURE_CONVERSION_FACTOR 200.0
#define CRC_POLYNOMIAL 0x31
#define CRC_INITIAL_VALUE 0xFF
#define MEASUREMENT_COMMAND 0x362F
#define MEASUREMENT_INTERVAL 45
#define WORD_SIZE 3
#define BYTE_SIZE 9

volatile sig_atomic_t stop = 0;

void signal_handler(int signum) {
    stop = 1;
}

int main() {
    int i2c_fd, ret;
    uint8_t buffer[BYTE_SIZE];
    uint16_t raw_values[WORD_SIZE];
    uint8_t crc_values[WORD_SIZE];
    double pressure, temperature;
    struct timespec sleep_time = {0, 45000000}; // 45 ms

    if ((i2c_fd = open(I2C_BUS, O_RDWR)) < 0) {
        perror("Failed to open the i2c bus");
        return EXIT_FAILURE;
    }

    if (ioctl(i2c_fd, I2C_SLAVE, I2C_ADDRESS) < 0) {
        perror("Failed to acquire bus access and/or talk to slave");
        close(i2c_fd);
        return EXIT_FAILURE;
    }

    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    while (!stop) {
        // Send measurement command
        buffer[0] = MEASUREMENT_COMMAND >> 8;
        buffer[1] = MEASUREMENT_COMMAND & 0xFF;
        if (write(i2c_fd, buffer, 2) != 2) {
            perror("Failed to write to i2c slave");
            break;
        }

        // Wait for measurement to complete
        nanosleep(&sleep_time, NULL);

        // Read 9 bytes
        if (read(i2c_fd, buffer, BYTE_SIZE) != BYTE_SIZE) {
            perror("Failed to read from i2c slave");
            break;
        }

        // Validate and convert raw values
        for (int i = 0; i < WORD_SIZE; i++) {
            raw_values[i] = (buffer[i * 2] << 8) | buffer[i * 2 + 1];
            crc_values[i] = buffer[i * 2 + 2];

            // Validate CRC
            uint8_t crc = crc_values[i];
            uint8_t data = raw_values[i] >> 8;
            for (int j = 0; j < 8; j++) {
                if ((crc ^ data) & 0x80) {
                    crc = (crc << 1) ^ CRC_POLYNOMIAL;
                } else {
                    crc <<= 1;
                }
                data <<= 1;
            }
            if (crc != 0xFF) {
                fprintf(stderr, "CRC validation failed for word %d\n", i);
                break;
            }

            // Convert raw values to pressure and temperature
            if (i == 0) {
                pressure = raw_values[i] / PRESSURE_CONVERSION_FACTOR;
            } else if (i == 1) {
                temperature = raw_values[i] / TEMPERATURE_CONVERSION_FACTOR;
            }
        }

        // Log the timestamp, pressure, and temperature
        FILE *log_file = fopen(PRESSURE_LOG_FILE, "a");
        if (log_file == NULL) {
            perror("Failed to open log file");
            break;
        }
        fprintf(log_file, "%ld,%lf,%lf\n", (long)time(NULL), pressure, temperature);
        fclose(log_file);
    }

    close(i2c_fd);
    return EXIT_SUCCESS;
}

