#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <unistd.h>
#include <signal.h>
#include <time.h>
#include <pigpio.h>

#define I2C_BUS 1
#define I2C_ADDRESS 0x25
#define PRESSURE_CMD1 0x36
#define PRESSURE_CMD2 0x2F
#define PRESSURE_CRC_POLYNOMIAL 0x31
#define PRESSURE_CRC_INITIAL_VALUE 0xFF
#define PRESSURE_CONVERSION_FACTOR 60.0
#define LOG_FILE_NAME "airflow_log.csv"
#define LOG_FILE_HEADER "Timestamp,Pressure (Pa)\n"

volatile sig_atomic_t running = 1;

void signal_handler(int signum) {
    running = 0;
}

int main() {
    FILE *log_file;
    struct timespec sleep_time = {0, 100000000}; // 0.1 seconds
    uint8_t data_bytes[3];
    uint16_t raw_pressure;
    uint8_t crc;
    uint8_t calculated_crc;
    uint8_t checksum;
    int i;

    if (access(LOG_FILE_NAME, F_OK) != 0) {
        log_file = fopen(LOG_FILE_NAME, "w");
        if (log_file == NULL) {
            fprintf(stderr, "Failed to create log file\n");
            return EXIT_FAILURE;
        }
        fprintf(log_file, LOG_FILE_HEADER);
    } else {
        log_file = fopen(LOG_FILE_NAME, "a");
        if (log_file == NULL) {
            fprintf(stderr, "Failed to open log file\n");
            return EXIT_FAILURE;
        }
    }

    if (signal(SIGINT, signal_handler) == SIG_ERR || signal(SIGTERM, signal_handler) == SIG_ERR) {
        fprintf(stderr, "Failed to set signal handlers\n");
        fclose(log_file);
        return EXIT_FAILURE;
    }

    if (gpioInitialise() < 0) {
        fprintf(stderr, "Failed to initialize pigpio\n");
        fclose(log_file);
        return EXIT_FAILURE;
    }

    while (running) {
        if (gpioI2CWriteDevice(I2C_BUS, I2C_ADDRESS) < 0) {
            fprintf(stderr, "Failed to write to I2C device\n");
            break;
        }

        if (gpioI2CWriteByte(I2C_BUS, PRESSURE_CMD1) < 0) {
            fprintf(stderr, "Failed to write command byte 1\n");
            break;
        }

        if (gpioI2CWriteByte(I2C_BUS, PRESSURE_CMD2) < 0) {
            fprintf(stderr, "Failed to write command byte 2\n");
            break;
        }

        nanosleep(&sleep_time, NULL);

        if (gpioI2CReadDevice(I2C_BUS, I2C_ADDRESS) < 0) {
            fprintf(stderr, "Failed to read from I2C device\n");
            break;
        }

        for (i = 0; i < 3; i++) {
            if ((data_bytes[i] = gpioI2CReadByte(I2C_BUS)) < 0) {
                fprintf(stderr, "Failed to read byte %d\n", i + 1);
                break;
            }
        }

        if (i < 3) {
            break;
        }

        raw_pressure = (data_bytes[0] << 8) | data_bytes[1];
        crc = data_bytes[2];

        calculated_crc = PRESSURE_CRC_INITIAL_VALUE;
        for (i = 0; i < 2; i++) {
            checksum = raw_pressure >> (8 * (1 - i));
            while (checksum) {
                if (calculated_crc & 0x80) {
                    calculated_crc = (calculated_crc << 1) ^ PRESSURE_CRC_POLYNOMIAL;
                } else {
                    calculated_crc <<= 1;
                }
                calculated_crc ^= checksum;
                checksum >>= 1;
            }
        }

        if (calculated_crc != crc) {
            fprintf(stderr, "Checksum mismatch\n");
            break;
        }

        raw_pressure /= PRESSURE_CONVERSION_FACTOR;

        time_t now = time(NULL);
        struct tm *time_info = localtime(&now);
        char timestamp[20];
        strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", time_info);

        fprintf(log_file, "%s,%d\n", timestamp, raw_pressure);

        fflush(log_file);
    }

    gpioTerminate();
    fclose(log_file);
    return EXIT_SUCCESS;
}

