#include <pigpio.h>

#define SCALE_FACTOR 0.01
#define MIN_SAFE_PRESSURE 200
#define MAX_SAFE_PRESSURE 250
#define I2C_ADDRESS 0x40
#define I2C_BUS 1
#define PRESSURE_REGISTER 0x00
#define LOG_FILE_NAME "pressure_log.csv"

static int i2c_handle = -1;
static FILE *log_file = NULL;

void close_safely() {
    if (i2c_handle >= 0) {
        i2cClose(i2c_handle);
    }
    if (log_file) {
        fclose(log_file);
    }
    gpioTerminate();
}

void handle_sigint(int signum) {
    close_safely();
    exit(EXIT_SUCCESS);
}

void handle_sigterm(int signum) {
    close_safely();
    exit(EXIT_SUCCESS);
}

int main() {
    struct timespec sleep_time = {1, 0}; // 1 second
    uint16_t pressure;
    char buffer[256];
    time_t rawtime;
    struct tm *timeinfo;
    int bytes_read;

    if (gpioInitialise() < 0) {
        fprintf(stderr, "Failed to initialize pigpio\n");
        return EXIT_FAILURE;
    }

    signal(SIGINT, handle_sigint);
    signal(SIGTERM, handle_sigterm);

    i2c_handle = i2cOpen(I2C_BUS, I2C_ADDRESS, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Failed to open I2C bus\n");
        goto cleanup;
    }

    log_file = fopen(LOG_FILE_NAME, "a");
    if (!log_file) {
        fprintf(stderr, "Failed to open log file\n");
        goto cleanup;
    }

    if (fseek(log_file, 0, SEEK_END) == 0 && ftell(log_file) == 0) {
        fprintf(log_file, "timestamp,pressure_kPa\n");
    }

    while (1) {
        bytes_read = i2cReadI2CBlockData(i2c_handle, PRESSURE_REGISTER, (char *)&pressure, 2);
        if (bytes_read != 2) {
            i2cClose(i2c_handle);
            i2c_handle = i2cOpen(I2C_BUS, I2C_ADDRESS, 0);
            if (i2c_handle < 0) {
                fprintf(stderr, "Failed to read pressure, retrying...\n");
                continue;
            }
            continue;
        }

        pressure = (pressure >> 8) | (pressure << 8); // Convert to big-endian
        pressure *= SCALE_FACTOR;

        time(&rawtime);
        timeinfo = gmtime(&rawtime);
        strftime(buffer, sizeof(buffer), "%Y-%m-%d %H:%M:%S", timeinfo);
        fprintf(log_file, "%s,%f\n", buffer, pressure);

        if (pressure < MIN_SAFE_PRESSURE || pressure > MAX_SAFE_PRESSURE) {
            fprintf(stderr, "Warning: Pressure is outside safe range: %f kPa\n", pressure);
        }

        nanosleep(&sleep_time, NULL);
    }

cleanup:
    close_safely();
    return EXIT_FAILURE;
}

#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <pigpio.h>

#define HIH6130_ADDRESS 0x27
#define HIH6130_MEASURE 0x00
#define HIH6130_STATUS 0x02
#define HIH6130_TEMPERATURE 0x03
#define HIH6130_HUMIDITY 0x05
#define FILE_MAX_SIZE 1048576 // 1 MB

void write_log(const char *message) {
    FILE *file = fopen("environmental_data.log", "a");
    if (file == NULL) {
        printf("Failed to open log file\n");
        return;
    }
    time_t now = time(NULL);
    struct tm *t = localtime(&now);
    char timestamp[20];
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%dT%H:%M:%S", t);
    fprintf(file, "%s %s\n", timestamp, message);
    fclose(file);
}

void truncate_log() {
    FILE *file = fopen("environmental_data.log", "r+");
    if (file == NULL) {
        printf("Failed to open log file\n");
        return;
    }
    fseek(file, 0, SEEK_END);
    long file_size = ftell(file);
    fseek(file, 0, SEEK_SET);
    if (file_size > FILE_MAX_SIZE) {
        ftruncate(file, FILE_MAX_SIZE);
    }
    fclose(file);
}

int main() {
    if (gpioInitialise() < 0) {
        printf("pigpio initialisation failed\n");
        return 1;
    }
    int i2c = i2cOpen(1, HIH6130_ADDRESS, 0);
    if (i2c < 0) {
        printf("Failed to open I2C bus\n");
        gpioTerminate();
        return 1;
    }
    while (1) {
        uint8_t buffer[4];
        if (i2cWriteByteData(i2c, HIH6130_MEASURE, HIH6130_ADDRESS) < 0) {
            printf("Failed to write to HIH6130\n");
            break;
        }
        usleep(40000); // Wait for measurement
        if (i2cReadByteData(i2c, HIH6130_STATUS, buffer, 4) < 0) {
            printf("Failed to read from HIH6130\n");
            break;
        }
        if ((buffer[0] & 0x03) != 0) {
            printf("Invalid measurement status\n");
            break;
        }
        int16_t raw_T = (buffer[1] << 8) | buffer[2];
        int16_t raw_H = (buffer[3] << 8) | buffer[0];
        float temperature = raw_T * 165.0/16383.0 - 40.0;
        float humidity = raw_H * 100.0/16383.0;
        char message[100];
        snprintf(message, sizeof(message), "Temperature: %.2f°C, Humidity: %.2f%%", temperature, humidity);
        write_log(message);
        truncate_log();
        sleep(5); // Wait for 5 seconds
    }
    i2cClose(i2c);
    gpioTerminate();
    return 0;
}

#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <pigpio.h>

#define GPIO_PIN 4
#define SENT_TICK_TIME 3e-6
#define SYNC_PULSE_TICKS 56
#define NIBBLE_MIN_TICKS 12
#define NIBBLE_MAX_TICKS 271
#define NIBBLE_WIDTH_TICKS 36
#define NIBBLE_WIDTH_US 813
#define NIBBLE_CHECKSUM 16
#define SCALE 0.001
#define OFFSET 0.0

volatile sig_atomic_t stop = 0;

void signal_handler(int signum) {
    stop = 1;
}

int main() {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Failed to initialize pigpio\n");
        return EXIT_FAILURE;
    }

    if (gpioSetMode(GPIO_PIN, PI_INPUT) < 0) {
        fprintf(stderr, "Failed to set GPIO mode\n");
        gpioTerminate();
        return EXIT_FAILURE;
    }

    if (gpioSetPullUpDown(GPIO_PIN, PI_PUD_UP) < 0) {
        fprintf(stderr, "Failed to set GPIO pull-up/down\n");
        gpioTerminate();
        return EXIT_FAILURE;
    }

    FILE *log_file = fopen("pressure_log.txt", "w");
    if (log_file == NULL) {
        fprintf(stderr, "Failed to open log file\n");
        gpioTerminate();
        return EXIT_FAILURE;
    }

    struct timespec start_time, current_time;
    clock_gettime(CLOCK_REALTIME, &start_time);

    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    while (!stop) {
        int pulse_start = gpioGetTickCount();
        while (gpioRead(GPIO_PIN) == PI_LOW) {
            if (gpioGetTickCount() - pulse_start > SYNC_PULSE_TICKS) {
                fprintf(stderr, "Sensor absent\n");
                break;
            }
        }

        if (stop) break;

        int pulse_end = gpioGetTickCount();
        int pulse_width = pulse_end - pulse_start;
        if (pulse_width < NIBBLE_MIN_TICKS || pulse_width > NIBBLE_MAX_TICKS) {
            fprintf(stderr, "Bus error: pulse width out of range\n");
            break;
        }

        int nibble = (pulse_width - NIBBLE_MIN_TICKS) / NIBBLE_WIDTH_TICKS;
        int checksum = 0;
        for (int i = 0; i < 4; i++) {
            if (i > 0) {
                pulse_start = gpioGetTickCount();
                while (gpioRead(GPIO_PIN) == PI_LOW) {}
                pulse_end = gpioGetTickCount();
                pulse_width = pulse_end - pulse_start;
                if (pulse_width < NIBBLE_MIN_TICKS || pulse_width > NIBBLE_MAX_TICKS) {
                    fprintf(stderr, "Bus error: pulse width out of range\n");
                    break;
                }
                nibble = (pulse_width - NIBBLE_MIN_TICKS) / NIBBLE_WIDTH_TICKS;
                checksum += nibble;
            }
            if (i == 3) {
                if (nibble != (checksum % NIBBLE_CHECKSUM)) {
                    fprintf(stderr, "Bus error: checksum mismatch\n");
                    break;
                }
            }
        }

        if (stop) break;

        int raw = (nibble << 8) | (nibble << 4) | nibble;
        float pressure = raw * SCALE + OFFSET;

        clock_gettime(CLOCK_REALTIME, &current_time);
        int elapsed_seconds = (current_time.tv_sec - start_time.tv_sec) % 60;
        int elapsed_minutes = (current_time.tv_sec - start_time.tv_sec) / 60;
        int elapsed_hours = (current_time.tv_sec - start_time.tv_sec) / 3600;
        fprintf(log_file, "%02d:%02d:%02d, Pressure: %.2f Pa\n", elapsed_hours, elapsed_minutes, elapsed_seconds, pressure);
        fflush(log_file);
    }

    fclose(log_file);
    gpioTerminate();
    return EXIT_SUCCESS;
}

#include <stdio.h>
#include <stdlib.h>
#include <signal.h>
#include <pigpio.h>
#include <stdint.h>

#define I2C_BUS 1
#define I2C_ADDRESS 0x48
#define TEMPERATURE_REGISTER 0x00
#define FILE_NAME "greenhouse_temps.dat"

static int i2c_handle = -1;
static FILE *file_stream = NULL;

void cleanup(int signum) {
    if (i2c_handle >= 0) {
        i2cClose(i2c_handle);
    }
    if (file_stream) {
        fclose(file_stream);
    }
    exit(signum);
}

int main() {
    struct sigaction action;
    action.sa_handler = cleanup;
    sigemptyset(&action.sa_mask);
    action.sa_flags = 0;
    sigaction(SIGINT, &action, NULL);
    sigaction(SIGTERM, &action, NULL);

    i2c_handle = i2cOpen(I2C_BUS, I2C_ADDRESS, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Failed to open I2C bus %d\n", I2C_BUS);
        return EXIT_FAILURE;
    }

    uint8_t device_id_register = 0x00;
    uint8_t device_id[2];
    if (i2cReadDevice(i2c_handle, device_id_register, device_id, 2) != 2) {
        fprintf(stderr, "Failed to read device ID\n");
        return EXIT_FAILURE;
    }

    if (device_id[0] != 0x01 || device_id[1] != 0x17) {
        fprintf(stderr, "Invalid device ID\n");
        return EXIT_FAILURE;
    }

    file_stream = fopen(FILE_NAME, "ab");
    if (!file_stream) {
        fprintf(stderr, "Failed to open file %s\n", FILE_NAME);
        return EXIT_FAILURE;
    }

    while (1) {
        int16_t temperature_raw;
        if (i2cReadDevice(i2c_handle, TEMPERATURE_REGISTER, (uint8_t *)&temperature_raw, 2) != 2) {
            fprintf(stderr, "Failed to read temperature\n");
            continue;
        }

        float temperature = (float)temperature_raw * 0.0078125;
        fwrite(&temperature, sizeof(float), 1, file_stream);

        sleep(60);
    }

    return EXIT_SUCCESS;
}

#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <signal.h>
#include <time.h>
#include <pigpio.h>

#define SHT40_ADDRESS 0x44
#define SHT40_MEASURE_HIGH_PRECISION 0xFD
#define SHT40_DATA_LENGTH 6
#define SHT40_CRC_POLYNOMIAL 0x31
#define SHT40_CRC_INITIAL_VALUE 0xFF
#define LOG_FILE_NAME "environmental_data.txt"

static int i2c_handle = -1;
static FILE *log_file = NULL;

void cleanup(int signum) {
    if (i2c_handle >= 0) {
        i2cClose(i2c_handle);
    }
    if (log_file) {
        fclose(log_file);
    }
    exit(signum);
}

uint8_t calculateCRC8(const uint8_t *data, size_t length) {
    uint8_t crc = SHT40_CRC_INITIAL_VALUE;
    for (size_t i = 0; i < length; i++) {
        crc ^= data[i];
        for (int j = 0; j < 8; j++) {
            if (crc & 0x80) {
                crc = (crc << 1) ^ SHT40_CRC_POLYNOMIAL;
            } else {
                crc <<= 1;
            }
        }
    }
    return crc;
}

int main() {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Failed to initialize pigpio\n");
        return EXIT_FAILURE;
    }

    signal(SIGINT, cleanup);

    i2c_handle = i2cOpen(1, SHT40_ADDRESS, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Failed to open I2C bus\n");
        cleanup(EXIT_FAILURE);
    }

    log_file = fopen(LOG_FILE_NAME, "a");
    if (!log_file) {
        fprintf(stderr, "Failed to open log file\n");
        cleanup(EXIT_FAILURE);
    }

    while (1) {
        uint8_t command = SHT40_MEASURE_HIGH_PRECISION;
        if (i2cWriteByteData(i2c_handle, SHT40_MEASURE_HIGH_PRECISION) < 0) {
            fprintf(stderr, "Failed to write command to SHT40\n");
            cleanup(EXIT_FAILURE);
        }

        usleep(8500); // Wait for the conversion to complete

        uint8_t buffer[SHT40_DATA_LENGTH];
        if (i2cReadByteData(i2c_handle, buffer, SHT40_DATA_LENGTH) < 0) {
            fprintf(stderr, "Failed to read data from SHT40\n");
            cleanup(EXIT_FAILURE);
        }

        uint8_t crc1 = buffer[2];
        uint8_t crc2 = buffer[5];
        buffer[2] = 0;
        buffer[5] = 0;

        if (crc1 != calculateCRC8(buffer, 2) || crc2 != calculateCRC8(buffer + 3, 2)) {
            fprintf(stderr, "CRC validation failed\n");
            cleanup(EXIT_FAILURE);
        }

        float temperature = -45 + 175 * (buffer[0] * 256 + buffer[1]) / 65535.0;
        float humidity = -6 + 125 * (buffer[3] * 256 + buffer[4]) / 65535.0;

        time_t now = time(NULL);
        struct tm *timeinfo = localtime(&now);
        char timestamp[20];
        strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", timeinfo);

        fprintf(log_file, "%s Temperature: %.2f°C Humidity: %.2f%%\n", timestamp, temperature, humidity);
        fflush(log_file);

        sleep(5); // Wait for 5 seconds before the next measurement
    }

    cleanup(EXIT_SUCCESS);
}

#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <signal.h>
#include <pigpio.h>
#include <stdbool.h>

#define TMP117_ADDRESS 0x48
#define TMP117_REG_TEMP 0x00
#define TMP117_RESOLUTION 0.0078125
#define SAMPLE_INTERVAL 5000 // 5 seconds
#define BUFFER_SIZE 100

typedef struct {
    uint16_t buffer[BUFFER_SIZE];
    int head;
    int count;
} CircularBuffer;

volatile sig_atomic_t stop = false;

void handle_sigint(int signum) {
    stop = true;
}

void write_buffer_to_file(CircularBuffer *buffer, const char *filename) {
    FILE *file = fopen(filename, "wb");
    if (file == NULL) {
        fprintf(stderr, "Failed to open file for writing\n");
        return;
    }
    fwrite(buffer->buffer, sizeof(uint16_t), buffer->count, file);
    fclose(file);
}

int main() {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Failed to initialize pigpio\n");
        return EXIT_FAILURE;
    }

    int i2c_handle = i2cOpen(1, TMP117_ADDRESS, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Failed to open I2C handle\n");
        gpioTerminate();
        return EXIT_FAILURE;
    }

    CircularBuffer buffer = {0};
    buffer.head = 0;
    buffer.count = 0;

    signal(SIGINT, handle_sigint);
    signal(SIGTERM, handle_sigint);

    while (!stop) {
        uint8_t data[2];
        if (i2cReadDevice(i2c_handle, TMP117_REG_TEMP, data, 2) != 2) {
            fprintf(stderr, "Failed to read temperature\n");
            continue;
        }

        uint16_t temp = (data[0] << 8) | data[1];
        buffer.buffer[buffer.head] = temp;
        buffer.head = (buffer.head + 1) % BUFFER_SIZE;
        if (buffer.count < BUFFER_SIZE) {
            buffer.count++;
        }

        write_buffer_to_file(&buffer, "temperature_log.dat");

        gpioDelay(SAMPLE_INTERVAL * 1000);
    }

    write_buffer_to_file(&buffer, "temperature_log.dat");

    i2cClose(i2c_handle);
    gpioTerminate();

    return EXIT_SUCCESS;
}

#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <pigpio.h>

#define SHTC3_ADDRESS 0x70
#define SHTC3_MEASUREMENT_CMD 0x7866
#define SHTC3_CRC_POLYNOMIAL 0x31
#define SHTC3_CRC_INIT_VALUE 0xFF
#define SHTC3_TEMPERATURE_MIN -40
#define SHTC3_TEMPERATURE_MAX 125
#define SHTC3_HUMIDITY_MIN 0
#define SHTC3_HUMIDITY_MAX 100
#define SHTC3_LOG_FILE "shtc3_environment.log"

volatile sig_atomic_t stop = 0;

void signal_handler(int signum) {
    stop = 1;
}

uint8_t crc8(const uint8_t *data, size_t len) {
    uint8_t crc = SHTC3_CRC_INIT_VALUE;
    for (size_t i = 0; i < len; i++) {
        crc ^= data[i];
        for (int j = 0; j < 8; j++) {
            if (crc & 0x80) {
                crc = (crc << 1) ^ SHTC3_CRC_POLYNOMIAL;
            } else {
                crc <<= 1;
            }
        }
    }
    return crc;
}

int main() {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Failed to initialize pigpio\n");
        return EXIT_FAILURE;
    }

    int i2c_handle = gpioI2COpen(1, SHTC3_ADDRESS);
    if (i2c_handle < 0) {
        fprintf(stderr, "Failed to open I2C bus 1\n");
        gpioTerminate();
        return EXIT_FAILURE;
    }

    FILE *log_file = fopen(SHTC3_LOG_FILE, "a");
    if (!log_file) {
        fprintf(stderr, "Failed to open log file\n");
        gpioI2CWriteByteData(i2c_handle, SHTC3_MEASUREMENT_CMD);
        gpioI2CClose(i2c_handle);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    signal(SIGINT, signal_handler);

    while (!stop) {
        uint8_t buffer[6];
        if (gpioI2CWriteByteData(i2c_handle, SHTC3_MEASUREMENT_CMD) < 0) {
            fprintf(stderr, "Failed to write measurement command\n");
            break;
        }

        usleep(12000); // Wait for conversion

        if (gpioI2CReadByteData(i2c_handle, buffer, sizeof(buffer)) < 0) {
            fprintf(stderr, "Failed to read data\n");
            break;
        }

        if (crc8(buffer, sizeof(buffer) - 1) != buffer[sizeof(buffer) - 1]) {
            fprintf(stderr, "CRC failure\n");
            break;
        }

        int16_t raw_temperature = (buffer[0] << 8) | buffer[1];
        int16_t raw_humidity = (buffer[3] << 8) | buffer[4];

        float temperature = 175.0 * raw_temperature / 65535.0 - 45.0;
        float humidity = 100.0 * raw_humidity / 65535.0;

        if (temperature < SHTC3_TEMPERATURE_MIN || temperature > SHTC3_TEMPERATURE_MAX ||
            humidity < SHTC3_HUMIDITY_MIN || humidity > SHTC3_HUMIDITY_MAX) {
            fprintf(stderr, "Out of range values\n");
            break;
        }

        time_t now = time(NULL);
        struct tm *time_info = localtime(&now);
        char time_str[20];
        strftime(time_str, sizeof(time_str), "%Y-%m-%d %H:%M:%S", time_info);

        fprintf(stdout, "%s,%.2f,%.2f\n", time_str, temperature, humidity);
        fprintf(log_file, "%s,%.2f,%.2f\n", time_str, temperature, humidity);
    }

    fclose(log_file);
    gpioI2CWriteByteData(i2c_handle, SHTC3_MEASUREMENT_CMD);
    gpioI2CClose(i2c_handle);
    gpioTerminate();
    return EXIT_SUCCESS;
}

#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <unistd.h>
#include <signal.h>
#include <pigpio.h>

#define SENSOR_ADDRESS 0x40
#define LOG_FILE "mag_temp_log.csv"
#define HEADER "Timestamp,Magnetic Field (Gauss),Temperature (Celsius)\n"

volatile sig_atomic_t stop_requested = 0;

void signal_handler(int signum) {
    stop_requested = 1;
}

int main() {
    FILE *log_file;
    uint8_t buffer[2];
    float field_gauss, temp_celsius;
    time_t timestamp;
    struct tm *timeinfo;
    char time_str[20];

    if (gpioInitialise() < 0) {
        fprintf(stderr, "Failed to initialize pigpio\n");
        return EXIT_FAILURE;
    }

    signal(SIGINT, signal_handler);

    log_file = fopen(LOG_FILE, "a");
    if (!log_file) {
        fprintf(stderr, "Failed to open log file\n");
        gpioTerminate();
        return EXIT_FAILURE;
    }

    if (fseek(log_file, 0, SEEK_END) == 0 && ftell(log_file) == 0) {
        fwrite(HEADER, 1, strlen(HEADER), log_file);
    }

    while (!stop_requested) {
        if (i2cReadDevice(1, SENSOR_ADDRESS, buffer, 2) != 2) {
            fprintf(stderr, "Failed to read from sensor\n");
            field_gauss = NAN;
            temp_celsius = NAN;
        } else {
            field_gauss = (buffer[0] << 8 | buffer[1]) * 0.1;
            temp_celsius = (buffer[0] << 8 | buffer[1]) * 0.01 - 25.0;
        }

        time(&timestamp);
        timeinfo = localtime(&timestamp);
        strftime(time_str, sizeof(time_str), "%Y-%m-%d %H:%M:%S", timeinfo);

        fprintf(log_file, "%s,%.2f,%.2f\n", time_str, field_gauss, temp_celsius);

        sleep(1);
    }

    fclose(log_file);
    gpioTerminate();

    return EXIT_SUCCESS;
}

#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <pigpio.h>

#define TMP117_ADDRESS 0x48
#define TMP117_REG_TEMP 0x00
#define TMP117_RESOLUTION 0.0078125

volatile sig_atomic_t stop = 0;

void signal_handler(int signum) {
    stop = 1;
}

int main() {
    int i2c_handle;
    int retries = 3;
    int16_t temp_raw;
    float temp_c;
    time_t now;
    struct tm *timeinfo;
    char buffer[80];

    signal(SIGINT, signal_handler);

    while (retries--) {
        if ((i2c_handle = i2cOpen(1, TMP117_ADDRESS, 0)) < 0) {
            printf("Failed to open I2C bus 1. Retrying...\n");
            continue;
        }

        while (!stop) {
            if (i2cReadDevice(i2c_handle, &temp_raw, 2) != 2) {
                printf("Failed to read temperature from TMP117. Retrying...\n");
                break;
            }

            temp_c = (float)temp_raw * TMP117_RESOLUTION;

            if (temp_c >= 32768) {
                temp_c -= 65536;
            }

            time(&now);
            timeinfo = localtime(&now);

            strftime(buffer, sizeof(buffer), "%Y-%m-%d %H:%M:%S", timeinfo);
            printf("%s, Temperature: %.2f C\n", buffer, temp_c);

            FILE *file = fopen("temperature_log.txt", "a");
            if (file == NULL) {
                printf("Failed to open temperature_log.txt for writing.\n");
                break;
            }

            fprintf(file, "%s, Temperature: %.2f C\n", buffer, temp_c);
            fclose(file);

            sleep(1);
        }

        i2cClose(i2c_handle);
        break;
    }

    return 0;
}

#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <signal.h>
#include <time.h>
#include <pigpio.h>

#define FLOW_SENSOR_ADDRESS 0x49
#define FLOW_SENSOR_REG 0x00
#define I2C_BUS 1

FILE *log_file;
bool run = true;

void close_program(int signum) {
    run = false;
    gpioTerminate();
    fclose(log_file);
    exit(signum);
}

int main() {
    signal(SIGINT, close_program);
    signal(SIGTERM, close_program);

    if (gpioInitialise() < 0) {
        printf("Failed to initialize pigpio\n");
        return 1;
    }

    log_file = fopen("flow_log.txt", "w");
    if (!log_file) {
        printf("Failed to open log file\n");
        return 1;
    }

    int i2c_handle = i2cOpen(I2C_BUS, FLOW_SENSOR_ADDRESS, 0);
    if (i2c_handle < 0) {
        printf("Failed to open I2C handle\n");
        return 1;
    }

    while (run) {
        uint8_t raw_data[4];
        int ret = i2cReadDevice(i2c_handle, FLOW_SENSOR_REG, raw_data, 4);
        if (ret != 4) {
            printf("Failed to read from I2C device\n");
            i2cClose(i2c_handle);
            i2c_handle = i2cOpen(I2C_BUS, FLOW_SENSOR_ADDRESS, 0);
            if (i2c_handle < 0) {
                printf("Failed to re-initialize I2C handle\n");
                return 1;
            }
            continue;
        }

        uint16_t raw_flow = (raw_data[0] << 8) | raw_data[1];
        uint16_t raw_temp = (raw_data[2] << 8) | raw_data[3];

        float flow = ((float)raw_flow / 16384.0 - 0.1) / 0.8 * 25.0;
        float temp = ((float)raw_temp / 4096.0 - 0.1) / 0.8 * 80.0 - 40.0;

        time_t now = time(NULL);
        struct tm *t = localtime(&now);
        char timestamp[20];
        strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", t);

        fprintf(log_file, "%s, Flow: %.2f SLPM, Temperature: %.2f°C\n", timestamp, flow, temp);

        sleep(1);
    }

    i2cClose(i2c_handle);
    fclose(log_file);
    gpioTerminate();

    return 0;
}

