#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <pigpio.h>

#define SHT31D_ADDRESS 0x44
#define SHT31D_MEASURE_CMD 0x2C06
#define SHT31D_CRC_POLYNOMIAL 0x31
#define SHT31D_CRC_INIT_VALUE 0xFF
#define SHT31D_READ_DELAY 15
#define SHT31D_LOG_FILE "sht31d_data.log"
#define SHT31D_LOG_FORMAT "%s,%d,%d\n"
#define SHT31D_MAX_RETRIES 3

volatile sig_atomic_t running = 1;

void signal_handler(int signum) {
    running = 0;
}

int calculate_crc8(const uint8_t *data, size_t length) {
    uint8_t crc = SHT31D_CRC_INIT_VALUE;
    for (size_t i = 0; i < length; i++) {
        crc ^= data[i];
        for (int j = 0; j < 8; j++) {
            if (crc & 0x80) {
                crc = (crc << 1) ^ SHT31D_CRC_POLYNOMIAL;
            } else {
                crc <<= 1;
            }
        }
    }
    return crc;
}

int main() {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Failed to initialize pigpio\n");
        return EXIT_FAILURE;
    }

    int i2c_handle = gpioI2COpen(1, SHT31D_ADDRESS);
    if (i2c_handle < 0) {
        fprintf(stderr, "Failed to open I2C bus\n");
        gpioTerminate();
        return EXIT_FAILURE;
    }

    FILE *log_file = fopen(SHT31D_LOG_FILE, "a");
    if (!log_file) {
        fprintf(stderr, "Failed to open log file\n");
        gpioI2CWrite(i2c_handle, SHT31D_MEASURE_CMD);
        gpioI2CClose(i2c_handle);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    while (running) {
        for (int retry = 0; retry <= SHT31D_MAX_RETRIES; retry++) {
            if (gpioI2CWrite(i2c_handle, SHT31D_MEASURE_CMD) < 0) {
                fprintf(stderr, "Failed to write to I2C device\n");
                continue;
            }

            if (gpioDelay(SHT31D_READ_DELAY * 1000) < 0) {
                fprintf(stderr, "Failed to delay\n");
                continue;
            }

            uint8_t buffer[6];
            ssize_t bytes_read = gpioI2CRead(i2c_handle, buffer, sizeof(buffer));
            if (bytes_read != sizeof(buffer)) {
                fprintf(stderr, "Failed to read from I2C device\n");
                continue;
            }

            if (calculate_crc8(buffer, 2) != buffer[2] || calculate_crc8(buffer + 3, 2) != buffer[5]) {
                fprintf(stderr, "CRC validation failed\n");
                continue;
            }

            int16_t raw_temperature = (buffer[0] << 8) | buffer[1];
            int16_t raw_humidity = (buffer[3] << 8) | buffer[4];

            double temperature = -45 + 175 * raw_temperature / 65535.0;
            double humidity = 100 * raw_humidity / 65535.0;

            time_t now = time(NULL);
            struct tm *time_info = localtime(&now);
            char timestamp[20];
            strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", time_info);

            fprintf(log_file, SHT31D_LOG_FORMAT, timestamp, (int)temperature, (int)humidity);

            break;
        }

        if (running) {
            gpioDelay(5000000); // Wait for 5 seconds
        }
    }

    fclose(log_file);
    gpioI2CClose(i2c_handle);
    gpioTerminate();

    return EXIT_SUCCESS;
}

#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <signal.h>
#include <time.h>
#include <pigpio.h>

#define ADPD105_ADDRESS 0x64
#define ADPD105_CHANNELS 3
#define ADPD105_REG_ID 0x00
#define ADPD105_REG_RED 0x64
#define ADPD105_REG_GREEN 0x66
#define ADPD105_REG_BLUE 0x68
#define ADPD105_CCT_FORMULA 0.0014327

FILE *log_file;
int i2c_handles[2];

void cleanup(int signum) {
    for (int i = 0; i < 2; i++) {
        if (i2c_handles[i] != 0) {
            i2cClose(i2c_handles[i]);
        }
    }
    if (log_file != NULL) {
