int main() {
    signal(SIGINT, cleanup);
    signal(SIGTERM, cleanup);

    if (gpioInitialise() < 0) {
        fprintf(stderr, "Failed to initialize pigpio\n");
        return EXIT_FAILURE;
    }

    for (int i = 0; i < 2; i++) {
        i2c_handles[i] = i2cOpen(1, ADPD105_ADDRESS + i, 0);
        if (i2c_handles[i] < 0) {
            fprintf(stderr, "Failed to open I2C bus 1 at address 0x%02X\n", ADPD105_ADDRESS + i);
            cleanup(EXIT_FAILURE);
        }
    }

    log_file = fopen("cct_log.csv", "a");
    if (log_file == NULL) {
        fprintf(stderr, "Failed to open log file\n");
        cleanup(EXIT_FAILURE);
    }

    uint8_t id_reg[1] = {ADPD105_REG_ID};
    uint8_t data_reg[ADPD105_CHANNELS] = {ADPD105_REG_RED, ADPD105_REG_GREEN, ADPD105_REG_BLUE};
    uint16_t data[ADPD105_CHANNELS];
    float cct[2];
    struct timespec ts;

