    if (gpioInitialise() < 0) {
        fprintf(stderr, "Failed to initialize pigpio\n");
        return EXIT_FAILURE;
    }

    if (signal(SIGINT, signal_handler) == SIG_ERR || signal(SIGTERM, signal_handler) == SIG_ERR) {
        fprintf(stderr, "Failed to set signal handler\n");
        gpioTerminate();
        return EXIT_FAILURE;
    }

    int i2c_handle = i2cOpen(I2C_BUS, I2C_ADDRESS, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Failed to open I2C bus\n");
        gpioTerminate();
        return EXIT_FAILURE;
    }

    float buffer[BUFFER_SIZE] = {0};
    float running_average = 0;
    bool fan_on = false;

    while (!stop) {
        uint8_t data[2];
        if (i2cReadDevice(i2c_handle, TEMPERATURE_REGISTER, data, 2) != 2) {
            fprintf(stderr, "Failed to read temperature\n");
            continue;
        }

        int16_t raw_temperature = (data[0] << 8) | data[1];
        float temperature = raw_temperature * 0.5;

        buffer[i2cWriteFile(i2c_handle, &temperature, sizeof(temperature)) % BUFFER_SIZE] = temperature;
        running_average = 0;
        for (int i = 0; i < BUFFER_SIZE; i++) {
            running_average += buffer[i];
        }
        running_average /= BUFFER_SIZE;

        if (running_average > TEMPERATURE_THRESHOLD_ON && !fan_on) {
            gpioSetMode(FAN_GPIO, PI_OUTPUT);
            gpioWrite(FAN_GPIO, PI_HIGH);
            fan_on = true;
        } else if (running_average < TEMPERATURE_THRESHOLD_OFF && fan_on) {
            gpioWrite(FAN_GPIO, PI_LOW);
            gpioSetMode(FAN_GPIO, PI_INPUT);
            fan_on = false;
        }

        sleep(1);
    }

    gpioTerminate();
    i2cClose(i2c_handle);
    return EXIT_SUCCESS;
}

