#define SDP810_ADDRESS 0x25
#define SDP810_MEASUREMENT_CMD 0x362F
#define SDP810_CRC_POLYNOMIAL 0x31
#define SDP810_CRC_INIT_VALUE 0xFF
#define SDP810_PRESSURE_SCALE_FACTOR 60
#define SDP810_TEMPERATURE_SCALE_FACTOR 200
#define LOG_FILE_NAME "airflow.log"
#define MAX_LOG_LINE_LENGTH 256

volatile sig_atomic_t running = 1;

void signal_handler(int signum) {
    running = 0;
}

int main() {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Failed to initialize pigpio library\n");
        return EXIT_FAILURE;
    }

    int i2c_handle = i2cOpen(1, SDP810_ADDRESS, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Failed to open I2C bus 1\n");
        gpioTerminate();
        return EXIT_FAILURE;
    }

    FILE *log_file = fopen(LOG_FILE_NAME, "w");
    if (!log_file) {
        fprintf(stderr, "Failed to open log file\n");
        i2cClose(i2c_handle);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    uint8_t buffer[9];
    int16_t pressure, temperature;
    uint8_t crc;

    while (running) {
        if (i2cWriteByteData(i2c_handle, SDP810_MEASUREMENT_CMD) < 0) {
            fprintf(stderr, "Failed to write measurement command\n");
            break;
        }

        usleep(45000); // Wait for measurement

        if (i2cReadByteData(i2c_handle, buffer, sizeof(buffer)) < 0) {
            fprintf(stderr, "Failed to read measurement data\n");
            break;
        }

        // Validate CRC
        crc = buffer[8];
        buffer[8] = 0; // Clear CRC byte for CRC calculation
        uint8_t calculated_crc = 0xFF;
        for (int i = 0; i < 8; ++i) {
            for (int j = 0; j < 8; ++j) {
                if ((calculated_crc ^ buffer[i]) & 0x80) {
                    calculated_crc = (calculated_crc << 1) ^ SDP810_CRC_POLYNOMIAL;
                } else {
                    calculated_crc <<= 1;
                }
            }
        }
        buffer[8] = crc; // Restore CRC byte
        if (calculated_crc != crc) {
            fprintf(stderr, "CRC mismatch\n");
            break;
        }

        // Convert raw data to pressure and temperature
        pressure = (buffer[0] << 8) | buffer[1];
        temperature = (buffer[2] << 8) | buffer[3];
        pressure = (pressure * SDP810_PRESSURE_SCALE_FACTOR) / 1000;
        temperature = (temperature * SDP810_TEMPERATURE_SCALE_FACTOR) / 1000;

        // Log data
        time_t now = time(NULL);
        struct tm *time_info = localtime(&now);
        char log_line[MAX_LOG_LINE_LENGTH];
        strftime(log_line, sizeof(log_line), "%Y-%m-%d %H:%M:%S,%d,%d\n", time_info, pressure, temperature);
        fwrite(log_line, 1, strlen(log_line), log_file);

        // Check for high pressure
        if (pressure > 500) {
            fprintf(stderr, "High pressure detected: %d Pa\n", pressure);
        }

        // Sleep for a second
        sleep(1);
    }

    fclose(log_file);
    i2cClose(i2c_handle);
    gpioTerminate();
    return EXIT_SUCCESS;
}

#include <stdio.h>
