#define I2C_SLAVE_ADDRESS 0x4A
#define I2C_FILE "/dev/i2c-1"
#define GPIO_PIN 17
#define TEMP_THRESHOLD_HIGH 28
#define TEMP_THRESHOLD_LOW 27
#define TEMP_CONVERSION_FACTOR 0.0625

static int i2c_fd = -1;
static struct gpiod_chip *chip = NULL;
static struct gpiod_line *line = NULL;

static void cleanup_and_exit(int exit_code) {
    if (line) {
        gpiod_line_release(line);
    }
    if (chip) {
        gpiod_chip_close(chip);
    }
    if (i2c_fd != -1) {
        close(i2c_fd);
    }
    exit(exit_code);
}

static void signal_handler(int signum) {
    cleanup_and_exit(EXIT_SUCCESS);
}

static int read_temperature() {
    uint8_t reg = 0x00;
    uint8_t data[2];
    int ret;

    ret = write(i2c_fd, &reg, 1);
    if (ret != 1) {
        perror("Failed to write register address");
        return -1;
    }

    ret = read(i2c_fd, data, 2);
    if (ret != 2) {
        perror("Failed to read temperature data");
        return -1;
    }

    int16_t temp = (data[0] << 8) | data[1];
    return (temp >> 4) * TEMP_CONVERSION_FACTOR;
}

static void update_led(int temperature) {
    int state = (temperature > TEMP_THRESHOLD_HIGH) ? 1 : ((temperature < TEMP_THRESHOLD_LOW) ? 0 : line->state);
    gpiod_line_set_value(line, state);
}

int main() {
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigaction(SIGINT, &sa, NULL);
    sigaction(SIGTERM, &sa, NULL);

    i2c_fd = open(I2C_FILE, O_RDWR);
    if (i2c_fd < 0) {
        perror("Failed to open I2C device");
        return EXIT_FAILURE;
    }

    if (ioctl(i2c_fd, I2C_SLAVE, I2C_SLAVE_ADDRESS) < 0) {
        perror("Failed to set I2C slave address");
        return EXIT_FAILURE;
    }

    chip = gpiod_chip_open_by_name("gpiochip0");
    if (!chip) {
        perror("Failed to open GPIO chip");
        return EXIT_FAILURE;
    }

    line = gpiod_chip_get_line(chip, GPIO_PIN);
    if (!line) {
        perror("Failed to get GPIO line");
        return EXIT_FAILURE;
    }

    gpiod_line_request_output(line, "temp_led", 0);

    while (1) {
        int temperature = read_temperature();
        if (temperature < 0) {
            cleanup_and_exit(EXIT_FAILURE);
        }

        printf("Temperature: %.2f°C\n", temperature);
        update_led(temperature);

        sleep(1);
    }

    cleanup_and_exit(EXIT_SUCCESS);
}

#include <stdio.h>
