#define I2C_BUS 1
#define I2C_ADDRESS 0x25
#define PRESSURE_DATA_LENGTH 9
#define CRC_POLYNOMIAL 0x31
#define CRC_INITIAL_VALUE 0xFF
#define SCALE_FACTOR_MASK 0xFFFF0000
#define PRESSURE_DATA_OFFSET 0
#define TEMPERATURE_DATA_OFFSET 2
#define SCALE_FACTOR_DATA_OFFSET 4
#define PRESSURE_CONVERSION_FACTOR 0.0001
#define TEMPERATURE_CONVERSION_FACTOR 0.02
#define FILE_NAME "flow_data.txt"

volatile sig_atomic_t stop = 0;

void signal_handler(int signum) {
    stop = 1;
}

int calculate_crc8(const uint8_t *data, size_t length) {
    uint8_t crc = CRC_INITIAL_VALUE;
    for (size_t i = 0; i < length; i++) {
        crc ^= data[i];
        for (int j = 0; j < 8; j++) {
            if (crc & 0x80) {
                crc = (crc << 1) ^ CRC_POLYNOMIAL;
            } else {
                crc <<= 1;
            }
        }
    }
    return crc;
}

int main() {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Failed to initialize pigpio library\n");
        return EXIT_FAILURE;
    }

    if (signal(SIGINT, signal_handler) == SIG_ERR) {
        fprintf(stderr, "Failed to set signal handler\n");
        gpioTerminate();
        return EXIT_FAILURE;
    }

    int file_descriptor = open(FILE_NAME, O_WRONLY | O_CREAT | O_APPEND, 0644);
    if (file_descriptor < 0) {
        fprintf(stderr, "Failed to open file %s\n", FILE_NAME);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    while (!stop) {
        uint8_t buffer[PRESSURE_DATA_LENGTH];
        if (gpioI2CReadDevice(I2C_BUS, I2C_ADDRESS, buffer, PRESSURE_DATA_LENGTH) != PRESSURE_DATA_LENGTH) {
            fprintf(stderr, "Failed to read data from sensor\n");
            break;
        }

        int crc8 = calculate_crc8(buffer, PRESSURE_DATA_LENGTH - 1);
        if (crc8 != buffer[PRESSURE_DATA_LENGTH - 1]) {
            fprintf(stderr, "CRC8 check failed\n");
            break;
        }

        int16_t scale_factor = (buffer[SCALE_FACTOR_DATA_OFFSET + 1] << 8) | buffer[SCALE_FACTOR_DATA_OFFSET];
        int32_t pressure = (buffer[PRESSURE_DATA_OFFSET + 1] << 8) | buffer[PRESSURE_DATA_OFFSET];
        pressure = (pressure * PRESSURE_CONVERSION_FACTOR) / scale_factor;

        int16_t temperature = (buffer[TEMPERATURE_DATA_OFFSET + 1] << 8) | buffer[TEMPERATURE_DATA_OFFSET];
        temperature = (temperature * TEMPERATURE_CONVERSION_FACTOR) / 100;

        struct timespec ts;
        clock_gettime(CLOCK_REALTIME, &ts);
        char timestamp[64];
        strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", localtime(&ts.tv_sec));
        char log_entry[256];
        snprintf(log_entry, sizeof(log_entry), "%s.%09ld, Pressure: %d Pa, Temperature: %d C\n", timestamp, ts.tv_nsec, pressure, temperature);

        if (write(file_descriptor, log_entry, strlen(log_entry)) < 0) {
            fprintf(stderr, "Failed to write data to file\n");
            break;
        }
    }

    close(file_descriptor);
    gpioTerminate();
    return EXIT_SUCCESS;
}

