        retry_count = 0;
        while (retry_count++ < I2C_RETRIES) {
            cmd[0] = SI7021_CMD_RH_NOHOLD;
            if (i2cWriteDevice(i2c_handle, cmd, 1) == 1) {
                break;
            }
            usleep(100000); // Wait 100 ms before retrying
        }
        if (retry_count == I2C_RETRIES) {
            fprintf(stderr, "Failed to send RH command\n");
            continue;
        }

        usleep(200000); // Wait at least 20 ms after no-hold command

        retry_count = 0;
        while (retry_count++ < I2C_RETRIES) {
            if (i2cReadDevice(i2c_handle, data, 2) == 2) {
                humidity = (SI7021_RH_MULT * (data[0] << 8 | data[1]) + SI7021_RH_OFFSET) / SI7021_RH_DIV;
                break;
            }
            usleep(100000); // Wait 100 ms before retrying
        }
        if (retry_count == I2C_RETRIES) {
            fprintf(stderr, "Failed to read RH data\n");
            continue;
        }

        retry_count = 0;
        while (retry_count++ < I2C_RETRIES) {
            cmd[0] = SI7021_CMD_TEMP_FROM_RH;
            if (i2cWriteDevice(i2c_handle, cmd, 1) == 1) {
                break;
            }
            usleep(100000); // Wait 100 ms before retrying
        }
        if (retry_count == I2C_RETRIES) {
            fprintf(stderr, "Failed to send temperature command\n");
            continue;
        }

        retry_count = 0;
        while (retry_count++ < I2C_RETRIES) {
            if (i2cReadDevice(i2c_handle, data, 2) == 2) {
                temperature = (SI7021_TEMP_MULT * (data[0] << 8 | data[1]) + SI7021_TEMP_OFFSET) / SI7021_TEMP_DIV;
                break;
            }
            usleep(100000); // Wait 100 ms before retrying
        }
        if (retry_count == I2C_RETRIES) {
            fprintf(stderr, "Failed to read temperature data\n");
            continue;
        }

        now = time(NULL);
        time_info = localtime(&now);
        strftime(time_str, sizeof(time_str), "%Y-%m-%dT%H:%M:%S", time_info);

        snprintf(log_buf, sizeof(log_buf), LOG_FORMAT, time_str, temperature, humidity);
        fputs(log_buf, log_file);
        fputs(log_buf, stdout);

        fflush(log_file);
        fflush(stdout);
    }

    fclose(log_file);
    i2cClose(i2c_handle);
    gpioTerminate();

    return EXIT_SUCCESS;
}

#include <stdio.h>
