#define HDC1080_ADDRESS 0x40
#define HDC1080_CONFIGURATION_REGISTER 0x02
#define HDC1080_TEMPERATURE_REGISTER 0x00
#define HDC1080_CONVERSION_DELAY_MS 20

int i2c_handle;
int terminate = 0;

void cleanup(int signum) {
    printf("Interrupt received, cleaning up...\n");
    terminate = 1;
    gpioTerminate();
}

int main() {
    if (gpioInitialise() < 0) {
        printf("Failed to initialize pigpio\n");
        return EXIT_FAILURE;
    }

    signal(SIGINT, cleanup);
    signal(SIGTERM, cleanup);

    i2c_handle = gpioI2COpen(1, HDC1080_ADDRESS);
    if (i2c_handle < 0) {
        printf("Failed to open I2C bus\n");
        gpioTerminate();
        return EXIT_FAILURE;
    }

    uint8_t config_data[] = {HDC1080_CONFIGURATION_REGISTER, 0x10};
    if (gpioI2CWrite(i2c_handle, config_data, sizeof(config_data)) != sizeof(config_data)) {
        printf("Failed to write configuration register\n");
        gpioI2CWrite(i2c_handle, config_data, sizeof(config_data));
        gpioI2CRead(i2c_handle, NULL, 0);
        gpioI2COpen(1, HDC1080_ADDRESS);
        return EXIT_FAILURE;
    }

    FILE *log_file = fopen("enviro_log.txt", "a");
    if (!log_file) {
        printf("Failed to open log file\n");
        gpioTerminate();
        return EXIT_FAILURE;
    }

    while (!terminate) {
        uint8_t read_data[4] = {HDC1080_TEMPERATURE_REGISTER};
        if (gpioI2CWriteRead(i2c_handle, read_data, sizeof(read_data), read_data, sizeof(read_data)) != sizeof(read_data)) {
            printf("Failed to read temperature and humidity\n");
            continue;
        }

        int16_t raw_temp = (read_data[0] << 8) | read_data[1];
        int16_t raw_humidity = (read_data[2] << 8) | read_data[3];

        float temperature = (raw_temp / 65536.0) * 165.0 - 40.0;
        float humidity = (raw_humidity / 65536.0) * 100.0;

        time_t now = time(NULL);
        struct tm *t = localtime(&now);
        char timestamp[20];
        strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", t);

        fprintf(log_file, "%s,%f,%f\n", timestamp, temperature, humidity);
        fflush(log_file);

        sleep(5);
    }

    fclose(log_file);
    gpioI2CWrite(i2c_handle, NULL, 0);
    gpioI2CRead(i2c_handle, NULL, 0);
    gpioI2COpen(1, HDC1080_ADDRESS);
    gpioTerminate();

    return EXIT_SUCCESS;
}

#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <unistd.h>
#include <fcntl.h>
#include <sys/ioctl.h>
#include <linux/i2c-dev.h>
#include <time.h>
#include <signal.h>

#define SENSIRION_POLYNOMIAL 0x31
#define SENSIRION_TICKS_PER_CELSIUS 175
#define SENSIRION_TICKS_OFFSET -45
#define SENSIRION_BYTES_PER_TICK 65535.0

int fd;
FILE *log_file;

void cleanup(int signum) {
    close(fd);
    fclose(log_file);
    exit(signum);
}

int main() {
    struct sigaction sigIntHandler;

    sigIntHandler.sa_handler = cleanup;
    sigemptyset(&sigIntHandler.sa_mask);
    sigIntHandler.sa_flags = 0;

    sigaction(SIGINT, &sigIntHandler, NULL);
    sigaction(SIGTERM, &sigIntHandler, NULL);

    if ((fd = open("/dev/i2c-1", O_RDWR)) < 0) {
        perror("Failed to open the i2c bus");
        return 1;
    }

    if (ioctl(fd, I2C_SLAVE, 0x44) < 0) {
        perror("Failed to acquire bus access and/or talk to slave");
        return 1;
    }

    if ((log_file = fopen("temperature_log.txt", "a")) == NULL) {
        perror("Failed to open log file");
        return 1;
    }

    while (1) {
        if (write(fd, "\x2C\xE0", 2) != 2) {
            perror("Failed to write to i2c slave");
            continue;
        }

        usleep(10000);

        unsigned char buffer[3];
        if (read(fd, buffer, 3) != 3) {
            perror("Failed to read from i2c slave");
            continue;
        }

        unsigned char crc = buffer[0] ^ buffer[1];
        for (int i = 0; i < 8; i++) {
            crc = (crc >> 1) ^ (crc & 1 ? SENSIRION_POLYNOMIAL : 0);
        }

        if (crc != buffer[2]) {
            fprintf(stderr, "CRC mismatch\n");
            continue;
        }

        float temperature = SENSIRION_TICKS_OFFSET + SENSIRION_TICKS_PER_CELSIUS * buffer[1] / SENSIRION_BYTES_PER_TICK;

        time_t rawtime;
        struct tm *timeinfo;
        char time_buffer[20];

        time(&rawtime);
        timeinfo = localtime(&rawtime);
        strftime(time_buffer, sizeof(time_buffer), "%Y-%m-%d %H:%M:%S", timeinfo);

        fprintf(log_file, "%s: %.2f°C\n", time_buffer, temperature);

        fflush(log_file);
        sleep(5);
    }

    return 0;
}

#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <pigpio.h>

#define I2C_BUS 1
#define I2C_ADDRESS 0x25
#define LOG_FILE "hvac_pressure_log.txt"

static FILE *log_file;
static uint8_t i2c_handle;

void log_error(const char *message) {
    time_t now = time(NULL);
    struct tm *t = localtime(&now);
    char timestamp[20];
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", t);
    fprintf(log_file, "%s, %s\n", timestamp, message);
    fflush(log_file);
}

void terminate(int signum) {
    i2cClose(i2c_handle);
    fclose(log_file);
    gpioTerminate();
    exit(signum);
}

int main() {
    if (gpioInitialise() < 0) {
        log_error("Failed to initialize GPIO");
        return EXIT_FAILURE;
    }

    i2c_handle = i2cOpen(I2C_BUS, I2C_ADDRESS, 0);
    if (i2c_handle < 0) {
        log_error("Failed to open I2C bus");
        gpioTerminate();
        return EXIT_FAILURE;
    }

    log_file = fopen(LOG_FILE, "w");
    if (!log_file) {
        log_error("Failed to open log file");
        i2cClose(i2c_handle);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    signal(SIGINT, terminate);

    uint8_t command[] = {0x36, 0x15};
    uint8_t buffer[9];
    uint16_t raw_pressure, raw_temperature;
    float pressure_Pa, temperature_C;
    uint8_t crc;

    while (1) {
        if (i2cWriteByteData(i2c_handle, 0x36, 0x15) < 0) {
            log_error("Failed to write command to I2C device");
            continue;
        }

        usleep(50000);

        if (i2cReadByteData(i2c_handle, 0x00, buffer, sizeof(buffer)) < 0) {
            log_error("Failed to read data from I2C device");
            continue;
        }

        crc = 0xFF;
        for (int i = 0; i < sizeof(buffer) - 1; i++) {
            crc ^= buffer[i];
        }

        if (crc != buffer[sizeof(buffer) - 1]) {
            log_error("CRC error");
            continue;
        }

        raw_pressure = (buffer[0] << 8) | buffer[1];
        raw_temperature = (buffer[3] << 8) | buffer[4];

        pressure_Pa = (float)raw_pressure / buffer[6];
        temperature_C = (float)raw_temperature / 200.0;

        time_t now = time(NULL);
        struct tm *t = localtime(&now);
        char timestamp[20];
        strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", t);
        fprintf(log_file, "%s, %.2f, %.2f\n", timestamp, pressure_Pa, temperature_C);
        fflush(log_file);
    }

    return EXIT_SUCCESS;
}

#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <unistd.h>
#include <signal.h>
#include <time.h>
#include <pthread.h>
#include <errno.h>
#include <pigpio.h>

#define SCD40_I2C_ADDRESS 0x62
#define SCD40_START_PERIODIC_MEASUREMENT 0x21B1
#define SCD40_READ_MEASUREMENT 0xE000
#define SCD40_STOP_PERIODIC_MEASUREMENT 0x3F86
#define SCD40_CO2_SCALE 2000
#define SCD40_TEMP_SCALE 175.0
#define SCD40_TEMP_OFFSET -45
#define SCD40_HUMIDITY_SCALE 100.0
#define SCD40_CRC_POLYNOMIAL 0x31
#define SCD40_CRC_INITIAL_VALUE 0xFF
#define SCD40_ERROR_LOG "/var/log/scd40_error.log"
#define SCD40_DATA_LOG "/var/log/scd40_data/"
#define SCD40_DATA_LOG_CAPACITY 100

volatile sig_atomic_t running = 1;
pthread_t logging_thread;
struct timespec buffer[SCD40_DATA_LOG_CAPACITY];
int buffer_head = 0;
int buffer_tail = 0;

void write_log(const char *message) {
    FILE *file = fopen(SCD40_ERROR_LOG, "a");
    if (file) {
        time_t now = time(NULL);
        struct tm *t = localtime(&now);
        fprintf(file, "%02d:%02d:%02d %s\n", t->tm_hour, t->tm_min, t->tm_sec, message);
        fclose(file);
    }
}

void *logging_function(void *arg) {
    while (running) {
        FILE *file = fopen(SCD40_DATA_LOG, "a");
        if (file) {
            for (int i = buffer_tail; i != buffer_head; i = (i + 1) % SCD40_DATA_LOG_CAPACITY) {
                struct timespec ts = buffer[i];
                fprintf(file, "%ld.%09ld,%d,%f,%f\n", ts.tv_sec, ts.tv_nsec, ts.co2, ts.temperature, ts.humidity);
            }
            fclose(file);
        }
        sleep(60);
    }
    return NULL;
}

int main() {
    if (gpioInitialise() < 0) {
        write_log("Failed to initialize pigpio");
        return 1;
    }

    int i2c = gpioI2COpen(1, SCD40_I2C_ADDRESS);
    if (i2c < 0) {
        write_log("Failed to open I2C bus");
        gpioTerminate();
        return 1;
    }

    if (gpioI2CWriteByteData(i2c, SCD40_START_PERIODIC_MEASUREMENT) < 0) {
        write_log("Failed to send start measurement command");
        gpioI2CWriteByte(i2c);
        gpioTerminate();
        return 1;
    }

    pthread_create(&logging_thread, NULL, logging_function, NULL);

    while (running) {
        uint8_t data[9];
        if (gpioI2CReadByteData(i2c, SCD40_READ_MEASUREMENT, data, sizeof(data)) < 0) {
            write_log("Failed to read measurement");
            continue;
        }

        uint16_t co2 = (data[0] << 8) | data[1];
        uint16_t temp_raw = (data[3] << 8) | data[4];
        uint16_t humidity_raw = (data[6] << 8) | data[7];

        if (data[2] != ((co2 >> 8) ^ (co2 & 0xFF) ^ SCD40_CRC_INITIAL_VALUE) ||
            data[5] != ((temp_raw >> 8) ^ (temp_raw & 0xFF) ^ SCD40_CRC_INITIAL_VALUE) ||
            data[8] != ((humidity_raw >> 8) ^ (humidity_raw & 0xFF) ^ SCD40_CRC_INITIAL_VALUE)) {
            write_log("CRC check failed");
            continue;
        }

        struct timespec ts;
        clock_gettime(CLOCK_REALTIME, &ts);
        struct timespec measurement = {
            .tv_sec = ts.tv_sec,
            .tv_nsec = ts.tv_nsec,
            .co2 = co2 * SCD40_CO2_SCALE / 1000,
            .temperature = SCD40_TEMP_OFFSET + SCD40_TEMP_SCALE * temp_raw / 65535,
            .humidity = SCD40_HUMIDITY_SCALE * humidity_raw / 65535
        };

        buffer[buffer_head] = measurement;
        buffer_head = (buffer_head + 1) % SCD40_DATA_LOG_CAPACITY;
        if (buffer_head == buffer_tail) {
            buffer_tail = (buffer_tail + 1) % SCD40_DATA_LOG_CAPACITY;
        }
    }

    gpioI2CWriteByteData(i2c, SCD40_STOP_PERIODIC_MEASUREMENT);
    gpioI2CWriteByte(i2c);
    pthread_join(logging_thread, NULL);
    gpioTerminate();
    return 0;
}

#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <signal.h>
#include <time.h>
#include <pigpio.h>

#define I2C_BUS 1
#define I2C_ADDRESS 0x25
#define SDP810_CMD 0x362F
#define SDP810_CRC_POLYNOMIAL 0x31
#define SDP810_CRC_INIT 0xFF
#define LOG_FILE "sdp810_log.txt"

volatile sig_atomic_t stop = 0;

void signal_handler(int signum) {
    stop = 1;
}

int calculate_crc8(const uint8_t *data, size_t length) {
    uint8_t crc = SDP810_CRC_INIT;
    for (size_t i = 0; i < length; i++) {
        crc ^= data[i];
        for (int j = 0; j < 8; j++) {
            if (crc & 0x80) {
                crc = (crc << 1) ^ SDP810_CRC_POLYNOMIAL;
            } else {
                crc <<= 1;
            }
        }
    }
    return crc;
}

int main() {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Failed to initialize pigpio\n");
        return EXIT_FAILURE;
    }

    int i2c_handle = gpioI2COpen(I2C_BUS, I2C_ADDRESS, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Failed to open I2C device\n");
        gpioTerminate();
        return EXIT_FAILURE;
    }

    FILE *log_file = fopen(LOG_FILE, "w");
    if (!log_file) {
        fprintf(stderr, "Failed to open log file\n");
        gpioI2CWriteByteData(i2c_handle, 0xFF, 0x00); // Stop command
        gpioI2CClose(i2c_handle);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    struct timespec ts;
    clock_gettime(CLOCK_REALTIME, &ts);
    uint32_t last_sec = ts.tv_sec;

    while (!stop) {
        if (gpioI2CWriteByteData(i2c_handle, SDP810_CMD, 0x00) < 0) {
            fprintf(stderr, "Failed to write command to I2C device\n");
            break;
        }
        usleep(45000); // Wait at least 45 ms

        uint8_t buffer[9];
        if (gpioI2CReadByteData(i2c_handle, 0x00, buffer, sizeof(buffer)) < 0) {
            fprintf(stderr, "Failed to read data from I2C device\n");
            break;
        }

        for (int i = 0; i < sizeof(buffer); i++) {
            if (calculate_crc8(buffer, i) != buffer[i]) {
                fprintf(stderr, "CRC failure\n");
                break;
            }
        }

        uint16_t raw_pressure = (buffer[0] << 8) | buffer[1];
        uint16_t raw_temp = (buffer[3] << 8) | buffer[4];
        uint16_t scale_factor = (buffer[6] << 8) | buffer[7];

        float pressure_Pa = raw_pressure * scale_factor / 1000.0;
        float temperature_C = -45 + 175 * raw_temp / 65535.0;

        clock_gettime(CLOCK_REALTIME, &ts);
        if (ts.tv_sec != last_sec) {
            fprintf(log_file, "%ld,%f,%f\n", ts.tv_sec, pressure_Pa, temperature_C);
            fflush(log_file);
            last_sec = ts.tv_sec;
        }
    }

    fclose(log_file);
    gpioI2CWriteByteData(i2c_handle, 0xFF, 0x00); // Stop command
    gpioI2CClose(i2c_handle);
    gpioTerminate();

    return EXIT_SUCCESS;
}

