    if (i2cReadI2CBlockData(i2c_handle, 0x05, CALIBRATION_COEFFICIENTS, calibration_coefficients) < 0) {
        fprintf(stderr, "Failed to read calibration coefficients\n");
        goto cleanup;
    }

    FILE *file = fopen("environmental_data.txt", "a");
    if (file == NULL) {
        fprintf(stderr, "Failed to open file\n");
        goto cleanup;
    }

    signal(SIGINT, signal_handler);

    while (!exit_flag) {
        if (i2cWriteByteData(i2c_handle, MEASUREMENT_TRIGGER, 0x00) < 0) {
            fprintf(stderr, "Failed to trigger measurement\n");
            continue;
        }

        usleep(10000);

        uint8_t pressure_and_temperature_data[PRESSURE_AND_TEMPERATURE_DATA];
        if (i2cReadI2CBlockData(i2c_handle, 0x00, PRESSURE_AND_TEMPERATURE_DATA, pressure_and_temperature_data) < 0) {
            fprintf(stderr, "Failed to read pressure and temperature data\n");
            continue;
        }

        // TODO: Convert pressure and temperature data to hPa and Celsius using the ICP-10110 datasheet formulas

        time_t now = time(NULL);
        struct tm *time_info = localtime(&now);
        char timestamp[20];
        strftime(timestamp, sizeof(timestamp), "%Y-%m-%dT%H:%M:%S", time_info);

        fprintf(file, "%s Pressure: %.2f hPa, Temperature: %.2f C\n", timestamp, pressure, temperature);
        fflush(file);
        printf("%s Pressure: %.2f hPa, Temperature: %.2f C\n", timestamp, pressure, temperature);

        sleep(SAMPLE_INTERVAL);
    }

cleanup:
    fclose(file);
    i2cClose(i2c_handle);
    gpioTerminate();
