#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <pigpio.h>

#define MLX90614_ADDRESS 0x5A
#define MLX90614_REG_AMBIENT 0x06
#define MLX90614_REG_OBJECT 0x07
#define FAN_PIN 18
#define FAN_ON_TEMP 30
#define FAN_OFF_TEMP 28
#define I2C_RETRIES 3
#define I2C_RETRY_DELAY 10

volatile sig_atomic_t stop = 0;

void signal_handler(int signum) {
    stop = 1;
}

int main() {
    FILE *log_file;
    int i2c_handle, fan_state = 0;
    uint16_t raw_ambient, raw_object;
    float ambient_temp, object_temp;
    struct timespec sleep_time = {2, 0};

    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    if (gpioInitialise() < 0) {
        fprintf(stderr, "Failed to initialize pigpio\n");
        return EXIT_FAILURE;
    }

    i2c_handle = gpioI2COpen(1, MLX90614_ADDRESS);
    if (i2c_handle < 0) {
        fprintf(stderr, "Failed to open I2C bus\n");
        gpioTerminate();
        return EXIT_FAILURE;
    }

    log_file = fopen("temperature_log.txt", "w");
    if (!log_file) {
        fprintf(stderr, "Failed to open log file\n");
        gpioI2CWriteByteData(i2c_handle, MLX90614_REG_AMBIENT, 0);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    gpioSetMode(FAN_PIN, PI_OUTPUT);
    gpioWrite(FAN_PIN, PI_LOW);

    while (!stop) {
        for (int i = 0; i < I2C_RETRIES; ++i) {
            raw_ambient = gpioI2CReadWordData(i2c_handle, MLX90614_REG_AMBIENT);
            raw_object = gpioI2CReadWordData(i2c_handle, MLX90614_REG_OBJECT);
            if (raw_ambient != 0 && raw_object != 0) break;
            usleep(I2C_RETRY_DELAY * 1000);
        }

        if (raw_ambient == 0 || raw_object == 0) {
            fprintf(stderr, "Failed to read temperature data\n");
            continue;
        }

        ambient_temp = raw_ambient * 0.02 - 273.15;
        object_temp = raw_object * 0.02 - 273.15;

        if (object_temp < -50 || object_temp > 100) {
            fprintf(stderr, "Invalid object temperature reading\n");
            continue;
        }

        time_t now = time(NULL);
        char *time_str = ctime(&now);
        time_str[strcspn(time_str, "\n")] = 0;

        fprintf(log_file, "%s Ambient: %.2f°C Object: %.2f°C\n", time_str, ambient_temp, object_temp);

        if (object_temp > FAN_ON_TEMP && !fan_state) {
            gpioWrite(FAN_PIN, PI_HIGH);
            fan_state = 1;
        } else if (object_temp < FAN_OFF_TEMP && fan_state) {
            gpioWrite(FAN_PIN, PI_LOW);
            fan_state = 0;
        }
    }

    fclose(log_file);
    gpioI2CWriteByteData(i2c_handle, MLX90614_REG_AMBIENT, 0);
    gpioTerminate();
    return EXIT_SUCCESS;
}

#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <signal.h>
#include <pigpio.h>
#include <http.h>

#define I2C_BUS 1
#define I2C_ADDRESS 0x44
#define MEASUREMENT_COMMAND 0xFD
#define MEASUREMENT_TIME 10000 // 10 ms
#define MAX_RETRIES 3

volatile sig_atomic_t stop = 0;

void signal_handler(int signum) {
    stop = 1;
}

int read_sensor(int i2c, uint8_t address, uint8_t command, uint8_t *data, int len) {
    int retries = 0;
    int ret;

    while (retries < MAX_RETRIES) {
        ret = i2cWriteReadDevice(i2c, address, &command, 1, data, len);
        if (ret >= 0) {
            return ret;
        }
        retries++;
    }

    return ret;
}

int main() {
    int i2c;
    uint8_t data[6];
    float temperature, humidity;
    struct httpServerInfo *server;

    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    if ((i2c = i2cOpen(I2C_BUS, I2C_ADDRESS, 0)) < 0) {
        printf("Failed to open I2C bus\n");
        return EXIT_FAILURE;
    }

    if (httpCreateServer(&server, 8080) < 0) {
        printf("Failed to create HTTP server\n");
        return EXIT_FAILURE;
    }

    while (!stop) {
        if (read_sensor(i2c, I2C_ADDRESS, MEASUREMENT_COMMAND, data, 6) < 0) {
            printf("Failed to read from sensor\n");
            continue;
        }

        // Convert raw data to temperature and humidity
        uint16_t raw_T = (data[3] << 8) | data[4];
        uint16_t raw_RH = (data[0] << 8) | data[1];

        temperature = -45 + 175 * (raw_T / 65535.0);
        humidity = -6 + 125 * (raw_RH / 65535.0);
        if (humidity > 100) {
            humidity = 100;
        }

        // Send HTTP response
        char response[256];
        sprintf(response, "<html><body>Temperature: %.2f°C<br>Humidity: %.2f%%</body></html>", temperature, humidity);
        httpSendResponse(server, response, strlen(response), "text/html");
    }

    httpDeleteServer(server);
    i2cClose(i2c);

    return EXIT_SUCCESS;
}

