#include <stdio.h>
#include <stdlib.h>
#include <signal.h>
#include <stdbool.h>
#include <pigpio.h>

volatile sig_atomic_t stop;

void signal_handler(int signum) {
    stop = 1;
}

int main() {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return EXIT_FAILURE;
    }

    int i2c_handle = i2cOpen(1, 0x40, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Failed to open I2C bus\n");
        gpioTerminate();
        return EXIT_FAILURE;
    }

    signal(SIGINT, signal_handler);

    uint8_t txbuf[2] = {0x0E, 0x01};
    uint8_t rxbuf[4];
    int retry_count = 0;
    const int max_retries = 5;

    while (!stop) {
        if (i2cWrite(i2c_handle, txbuf, 2) != 2) {
            fprintf(stderr, "Failed to write to I2C sensor\n");
            if (++retry_count >= max_retries) {
                break;
            }
            continue;
        }

        retry_count = 0;

        uint8_t config_reg = 0x0F;
        uint8_t config_val = 0x00;
        if (i2cReadByteData(i2c_handle, config_reg, &config_val) < 0) {
            fprintf(stderr, "Failed to read config register\n");
            break;
        }

        uint8_t measurement_config_reg = 0x0E;
        uint8_t measurement_config_val = 0x01;
        if (i2cWriteByteData(i2c_handle, measurement_config_reg, measurement_config_val) < 0) {
            fprintf(stderr, "Failed to write measurement config register\n");
            break;
        }

        int timeout = 500000; // 500 ms
        while (timeout > 0) {
            if (i2cReadByteData(i2c_handle, measurement_config_reg, &measurement_config_val) < 0) {
                fprintf(stderr, "Failed to read measurement config register\n");
                break;
            }

            if ((measurement_config_val & 0x01) == 0) {
                break;
            }

            usleep(1000); // 1 ms
            timeout -= 1000;
        }

        if (timeout <= 0) {
            fprintf(stderr, "Measurement config register timeout\n");
            break;
        }

        if (i2cRead(i2c_handle, rxbuf, 4) != 4) {
            fprintf(stderr, "Failed to read from I2C sensor\n");
            break;
        }

        int16_t raw_temperature = (rxbuf[0] << 8) | rxbuf[1];
        int16_t raw_humidity = (rxbuf[2] << 8) | rxbuf[3];

        float temperature = raw_temperature / 65536.0f * 165.0f - 40.0f;
        float humidity = raw_humidity / 65536.0f * 100.0f;

        printf("Temperature: %.2f°C, Humidity: %.2f%%\n", temperature, humidity);

        sleep(5);
    }

    i2cClose(i2c_handle);
    gpioTerminate();

    return EXIT_SUCCESS;
}

#include <stdio.h>
#include <stdlib.h>
#include <signal.h>
#include <pigpio.h>
#include <stdint.h>

#define I2C_BUS 1
#define I2C_ADDRESS 0x25
#define CONTINUOUS_MEASUREMENT_CMD 0x362F
#define CRC_POLYNOMIAL 0x31
#define CRC_INITIAL_VALUE 0xFF
#define PRESSURE_DATA_LENGTH 2
#define TEMPERATURE_DATA_LENGTH 2
#define CRC_DATA_LENGTH 1
#define TOTAL_DATA_LENGTH (PRESSURE_DATA_LENGTH + TEMPERATURE_DATA_LENGTH + CRC_DATA_LENGTH)

volatile sig_atomic_t stop = 0;

void signal_handler(int signum) {
    stop = 1;
}

uint8_t crc8(const uint8_t *data, size_t length, uint8_t crc) {
    for (size_t i = 0; i < length; ++i) {
        crc ^= data[i];
        for (int j = 0; j < 8; ++j) {
            if (crc & 0x80) {
                crc = (crc << 1) ^ CRC_POLYNOMIAL;
            } else {
                crc <<= 1;
            }
        }
    }
    return crc;
}

int main() {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Failed to initialize pigpio\n");
        return EXIT_FAILURE;
    }

    if (signal(SIGINT, signal_handler) == SIG_ERR) {
        fprintf(stderr, "Failed to set signal handler\n");
        gpioTerminate();
        return EXIT_FAILURE;
    }

    int i2c_handle = i2cOpen(I2C_BUS, I2C_ADDRESS, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Failed to open I2C bus\n");
        gpioTerminate();
        return EXIT_FAILURE;
    }

    uint8_t buffer[TOTAL_DATA_LENGTH];
    while (!stop) {
        if (i2cWriteByteData(i2c_handle, CONTINUOUS_MEASUREMENT_CMD) < 0) {
            fprintf(stderr, "Failed to write command to sensor\n");
            break;
        }

        usleep(45000); // Wait for measurement to complete

        if (i2cReadByteData(i2c_handle, 0, buffer, TOTAL_DATA_LENGTH) < 0) {
            fprintf(stderr, "Failed to read data from sensor\n");
            break;
        }

        uint8_t crc = crc8(buffer, TOTAL_DATA_LENGTH - CRC_DATA_LENGTH, CRC_INITIAL_VALUE);
        if (crc != buffer[TOTAL_DATA_LENGTH - 1]) {
            fprintf(stderr, "CRC check failed\n");
            break;
        }

        uint16_t pressure = (buffer[0] << 8) | buffer[1];
        uint16_t temperature = (buffer[2] << 8) | buffer[3];

        printf("Pressure: %u, Temperature: %u\n", pressure, temperature);

        usleep(500000); // Wait for 500 ms
    }

    i2cClose(i2c_handle);
    gpioTerminate();
    return EXIT_SUCCESS;
}

#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <stdbool.h>
#include <unistd.h>
#include <fcntl.h>
#include <sys/ioctl.h>
#include <linux/spi/spidev.h>
#include <gpiod.h>

#define MAX6675_CS 0
#define MAX6675_CLK 1
#define RELAY_GPIO 17
#define TEMP_LOG_FILE "reflow_log.csv"

int spi_fd, gpio_fd;
uint16_t read_temp() {
    uint16_t temp = 0;
    uint8_t tx[2] = {0, 0};
    uint8_t rx[2] = {0, 0};
    struct spi_ioc_transfer tr = {
        .tx_buf = (unsigned long)tx,
        .rx_buf = (unsigned long)rx,
        .len = 2,
        .speed_hz = 1000000,
        .delay_usecs = 0,
        .bits_per_word = 8,
    };
    ioctl(spi_fd, SPI_IOC_MESSAGE(1), &tr);
    temp = (rx[0] << 8) | rx[1];
    return temp;
}

void write_relay(float duty_cycle) {
    struct gpiod_line_bulk lines;
    struct gpiod_line_request rq = {
        .consumer = "reflow_oven",
        .request_type = GPIO_REQUEST_OUTPUT,
        .default_value = (duty_cycle > 0.5) ? 1 : 0,
    };
    gpiod_line_request_bulk(gpio_fd, &rq, 1, &lines);
    gpiod_line_set_value_bulk(gpio_fd, &lines);
}

int main() {
    FILE *profile = fopen("profile.txt", "r");
    if (!profile) {
        perror("Failed to open profile.txt");
        return EXIT_FAILURE;
    }
    spi_fd = open("/dev/spidev0.0", O_RDWR);
    if (spi_fd < 0) {
        perror("Failed to open SPI device");
        return EXIT_FAILURE;
    }
    gpio_fd = gpiod_chip_open("/dev/gpiochip0");
    if (!gpio_fd) {
        perror("Failed to open GPIO chip");
        return EXIT_FAILURE;
    }
    struct gpiod_line *line = gpiod_chip_get_line(gpio_fd, RELAY_GPIO);
    if (!line) {
        perror("Failed to get GPIO line");
        return EXIT_FAILURE;
    }
    if (gpiod_line_request_output(line, "reflow_oven", 0)) {
        perror("Failed to request GPIO line as output");
        return EXIT_FAILURE;
    }
    float Kp = 1.0, Ki = 0.1, Kd = 0.01;
    float integral = 0, prev_error = 0;
    float target_temp, time_seconds, duty_cycle;
    while (fscanf(profile, "%f,%f", &time_seconds, &target_temp) == 2) {
        sleep(time_seconds);
        uint16_t temp = read_temp();
        float error = target_temp - (temp >> 3);
        integral += error;
        float derivative = error - prev_error;
        prev_error = error;
        duty_cycle = Kp * error + Ki * integral + Kd * derivative;
        if (duty_cycle < 0) duty_cycle = 0;
        if (duty_cycle > 1) duty_cycle = 1;
        write_relay(duty_cycle);
        printf("Time: %f, Target Temp: %f, Current Temp: %f, Duty Cycle: %f\n", time_seconds, target_temp, temp >> 3, duty_cycle);
    }
    fclose(profile);
    close(spi_fd);
    gpiod_line_release(line);
    gpiod_chip_close(gpio_fd);
    return EXIT_SUCCESS;
}

