#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <unistd.h>
#include <signal.h>
#include <time.h>
#include <errno.h>
#include <libgpiod.h>

#define AHT20_ADDRESS 0x38
#define AHT20_INIT_CMD {0xBE, 0x08, 0x00}
#define AHT20_MEASURE_CMD {0xAC, 0x33, 0x00}
#define AHT20_DATA_LEN 6
#define AHT20_BUS "/dev/i2c-1"
#define AHT20_RETRY_COUNT 3
#define AHT20_RETRY_DELAY 10
#define AHT20_POLL_INTERVAL 5
#define DEHUMIDIFIER_GPIO 17

static gpiod_line *dehumidifier_line = NULL;
static int i2c_fd = -1;

static void cleanup(int exit_code) {
    if (dehumidifier_line) {
        gpiod_line_set_value(dehumidifier_line, 0);
        gpiod_line_release(dehumidifier_line);
    }
    if (i2c_fd != -1) {
        close(i2c_fd);
    }
    exit(exit_code);
}

static int i2c_write(const uint8_t *data, size_t len) {
    int retries = AHT20_RETRY_COUNT;
    while (retries--) {
        if (write(i2c_fd, data, len) == len) {
            return 0;
        }
        usleep(AHT20_RETRY_DELAY * 1000);
    }
    return -1;
}

static int i2c_read(uint8_t *data, size_t len) {
    int retries = AHT20_RETRY_COUNT;
    while (retries--) {
        if (read(i2c_fd, data, len) == len) {
            return 0;
        }
        usleep(AHT20_RETRY_DELAY * 1000);
    }
    return -1;
}

static float read_humidity() {
    uint8_t init_cmd[] = AHT20_INIT_CMD;
    uint8_t measure_cmd[] = AHT20_MEASURE_CMD;
    uint8_t data[AHT20_DATA_LEN];
    float humidity;

    if (i2c_write(init_cmd, sizeof(init_cmd)) < 0) {
        return -1;
    }
    usleep(80000); // Wait for measurement
    if (i2c_write(measure_cmd, sizeof(measure_cmd)) < 0) {
        return -1;
    }
    if (i2c_read(data, AHT20_DATA_LEN) < 0) {
        return -1;
    }
    if (data[0] & 0x08) { // Check if the status byte indicates the sensor is calibrated and not busy
        return -1;
    }
    humidity = ((data[1] << 12) | (data[2] << 4) | (data[3] >> 4)) * 100.0 / 0x0FFFFF;
    return humidity;
}

static void signal_handler(int signum) {
    cleanup(0);
}

int main() {
    struct sigaction sa;
    float humidity;

    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigaction(SIGINT, &sa, NULL);
    sigaction(SIGTERM, &sa, NULL);

    dehumidifier_line = gpiod_line_request_output(DEHUMIDIFIER_GPIO, "dehumidifier", 0);
    if (!dehumidifier_line) {
        fprintf(stderr, "Failed to request GPIO line: %s\n", strerror(errno));
        cleanup(1);
    }

    i2c_fd = open(AHT20_BUS, O_RDWR);
    if (i2c_fd < 0) {
        fprintf(stderr, "Failed to open I2C bus: %s\n", strerror(errno));
        cleanup(1);
    }

    if (ioctl(i2c_fd, I2C_SLAVE, AHT20_ADDRESS) < 0) {
        fprintf(stderr, "Failed to set I2C address: %s\n", strerror(errno));
        cleanup(1);
    }

    while (1) {
        humidity = read_humidity();
        if (humidity < 0) {
            fprintf(stderr, "Failed to read humidity: %s\n", strerror(errno));
        } else {
            printf("Humidity: %.2f%%\n", humidity);
            if (humidity > 60) {
                gpiod_line_set_value(dehumidifier_line, 1);
            } else if (humidity < 55) {
                gpiod_line_set_value(dehumidifier_line, 0);
            }
        }
        sleep(AHT20_POLL_INTERVAL);
    }

    cleanup(0);
    return 0;
}

