#define BMP280_CTRL_MEAS_REG 0xF4
#define BMP280_PRESSURE_MSB_REG 0xF7
#define BMP280_PRESSURE_OSR_1X 0x25
#define BMP280_PRESSURE_THRESHOLD_HIGH 1020
#define BMP280_PRESSURE_THRESHOLD_LOW 980
#define BMP280_PRESSURE_CALIB_1 0x88
#define BMP280_PRESSURE_CALIB_2 0x8E
#define BMP280_PRESSURE_CALIB_3 0x90
#define BMP280_PRESSURE_CALIB_4 0x92
#define BMP280_PRESSURE_CALIB_5 0x94
#define BMP280_PRESSURE_CALIB_6 0x96
#define BMP280_PRESSURE_CALIB_7 0x98
#define BMP280_PRESSURE_CALIB_8 0x9A
#define BMP280_PRESSURE_CALIB_9 0x9C
#define BMP280_PRESSURE_CALIB_10 0x9E
#define BMP280_PRESSURE_CALIB_LEN 24

volatile sig_atomic_t stop = 0;

void signal_handler(int signum) {
    stop = 1;
}

int main() {
    int i2c_handle;
    uint8_t chip_id;
    uint8_t data[BMP280_PRESSURE_CALIB_LEN];
    int32_t dig_T1, dig_T2, dig_T3, dig_P1, dig_P2, dig_P3, dig_P4, dig_P5, dig_P6, dig_P7, dig_P8, dig_P9;
    int64_t t_fine;
    int32_t adc_T, adc_P;
    double t, p;
    FILE *log_file;

    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    if ((i2c_handle = pi_i2c_open(1, BMP280_ADDRESS)) < 0) {
        printf("Failed to open I2C bus\n");
        return EXIT_FAILURE;
    }

    if (pi_i2c_read_device(i2c_handle, &chip_id, 1) != 1 || chip_id != BMP280_CHIP_ID) {
        printf("Failed to verify chip ID\n");
        pi_i2c_close(i2c_handle);
        return EXIT_FAILURE;
    }

    if (pi_i2c_read_device(i2c_handle, data, BMP280_PRESSURE_CALIB_LEN) != BMP280_PRESSURE_CALIB_LEN) {
        printf("Failed to read calibration data\n");
        pi_i2c_close(i2c_handle);
        return EXIT_FAILURE;
    }

    dig_T1 = (data[1] << 8) | data[0];
    dig_T2 = (data[3] << 8) | data[2];
    dig_T3 = (data[5] << 8) | data[4];
    dig_P1 = (data[7] << 8) | data[6];
    dig_P2 = (data[9] << 8) | data[8];
    dig_P3 = (data[11] << 8) | data[10];
    dig_P4 = (data[13] << 8) | data[12];
    dig_P5 = (data[15] << 8) | data[14];
    dig_P6 = (data[17] << 8) | data[16];
    dig_P7 = (data[19] << 8) | data[18];
    dig_P8 = (data[21] << 8) | data[20];
    dig_P9 = (data[23] << 8) | data[22];

    if (pi_i2c_write_byte_data(i2c_handle, BMP280_CTRL_MEAS_REG, BMP280_PRESSURE_OSR_1X) < 0) {
        printf("Failed to configure measurement\n");
        pi_i2c_close(i2c_handle);
        return EXIT_FAILURE;
    }

    log_file = fopen("pressure_log.txt", "w");
    if (log_file == NULL) {
        printf("Failed to open log file\n");
        pi_i2c_close(i2c_handle);
        return EXIT_FAILURE;
    }

    while (!stop) {
        if (pi_i2c_write_byte_data(i2c_handle, BMP280_CTRL_MEAS_REG, BMP280_PRESSURE_OSR_1X | 0x01) < 0) {
            printf("Failed to trigger measurement\n");
            break;
        }

        usleep(10000);

        if (pi_i2c_read_device(i2c_handle, data, 6) != 6) {
            printf("Failed to read raw data\n");
            break;
        }

        adc_P = (data[0] << 12) | (data[1] << 4) | (data[2] >> 4);
        adc_T = (data[3] << 12) | (data[4] << 4) | (data[5] >> 4);

        // Apply Bosch compensation formulas
        // ...

        if (p > BMP280_PRESSURE_THRESHOLD_HIGH || p < BMP280_PRESSURE_THRESHOLD_LOW) {
            time_t now = time(NULL);
            struct tm *t = localtime(&now);
            fprintf(log_file, "%s: Pressure = %.2f hPa\n", asctime(t), p);
        }
    }

    fclose(log_file);
    pi_i2c_close(i2c_handle);
    gpioTerminate();
    return EXIT_SUCCESS;
}

