#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <unistd.h>
#include <fcntl.h>
#include <sys/ioctl.h>
#include <linux/i2c-dev.h>
#include <gpiod.h>

#define TMP117_ADDRESS 0x48
#define TMP117_TEMP_REG 0x00
#define AHT20_ADDRESS 0x38
#define AHT20_INIT_CMD 0xBE, 0x08, 0x00
#define AHT20_MEASURE_CMD 0xAC, 0x33, 0x00
#define PIR_GPIO_CHIP 4
#define PIR_GPIO_LINE 17
#define I2C_BUS "/dev/i2c-1"
#define LOG_FILE_PATH "/var/log/sensor_data.csv"
#define MAX_RETRIES 3
#define BACKOFF_TIME 10

int main() {
    // Initialize GPIO
    struct gpiod_chip *chip = gpiod_chip_open(PIR_GPIO_CHIP);
    struct gpiod_line *line = gpiod_chip_get_line(chip, PIR_GPIO_LINE);
    gpiod_line_request_input(line, "PIR Sensor");

    // Initialize I2C
    int i2c_fd = open(I2C_BUS, O_RDWR);
    if (i2c_fd < 0) {
        perror("Failed to open I2C bus");
        return EXIT_FAILURE;
    }
    if (ioctl(i2c_fd, I2C_SLAVE, TMP117_ADDRESS) < 0) {
        perror("Failed to set I2C slave address");
        return EXIT_FAILURE;
    }

    // Check for TMP117
    unsigned char tmp117_id_reg = 0x0F;
    if (i2c_smbus_read_byte_data(i2c_fd, tmp117_id_reg) != 0x48) {
        printf("TMP117 not found\n");
    }

    // Check for AHT20
    unsigned char aht20_id_reg = 0x36;
    if (i2c_smbus_read_byte_data(i2c_fd, aht20_id_reg) != 0x18) {
        printf("AHT20 not found\n");
    }

    // Create log file
    FILE *log_file = fopen(LOG_FILE_PATH, "a");
    if (!log_file) {
        perror("Failed to open log file");
        return EXIT_FAILURE;
    }

    // Log header
    fprintf(log_file, "Timestamp,Temperature(C),Humidity(%),MotionDetected\n");

    // Main loop
    while (1) {
        // Get current time
        time_t now = time(NULL);
        struct tm *time_info = localtime(&now);

        // Log motion
        int motion = gpiod_line_get_value(line);
        fprintf(log_file, "%04d-%02d-%02d %02d:%02d:%02d,%f,%f,%d\n",
                time_info->tm_year + 1900, time_info->tm_mon + 1, time_info->tm_mday,
                time_info->tm_hour, time_info->tm_min, time_info->tm_sec,
                0.0, 0.0, motion);

        // Sleep for 1 second
        sleep(1);
    }

    // Clean up
    fclose(log_file);
    gpiod_line_release(line);
    gpiod_chip_close(chip);
    close(i2c_fd);

    return EXIT_SUCCESS;
}

#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <unistd.h>
#include <libgpiod.h>

#define RAIN_SENSOR 17
#define MOTOR_ENABLE 22
#define MOTOR_FORWARD_1 23
#define MOTOR_FORWARD_2 24

gpiod_chip *chip;
gpiod_line *rain_sensor;
gpiod_line *motor_enable;
gpiod_line *motor_forward_1;
gpiod_line *motor_forward_2;

void cleanup() {
    gpiod_line_set_value(motor_enable, 0);
    gpiod_line_set_value(motor_forward_1, 0);
    gpiod_line_set_value(motor_forward_2, 0);
    gpiod_line_release(motor_enable);
    gpiod_line_release(motor_forward_1);
    gpiod_line_release(motor_forward_2);
    gpiod_line_release(rain_sensor);
    gpiod_chip_close(chip);
}

int main() {
    atexit(cleanup);

    chip = gpiod_chip_open("/dev/gpiochip0");
    if (!chip) {
        fprintf(stderr, "Failed to open GPIO chip\n");
        return EXIT_FAILURE;
    }

    rain_sensor = gpiod_chip_get_line(chip, RAIN_SENSOR);
    if (!rain_sensor) {
        fprintf(stderr, "Failed to get line for rain sensor\n");
        return EXIT_FAILURE;
    }

    motor_enable = gpiod_chip_get_line(chip, MOTOR_ENABLE);
    if (!motor_enable) {
        fprintf(stderr, "Failed to get line for motor enable\n");
        return EXIT_FAILURE;
    }

    motor_forward_1 = gpiod_chip_get_line(chip, MOTOR_FORWARD_1);
    if (!motor_forward_1) {
        fprintf(stderr, "Failed to get line for motor forward 1\n");
        return EXIT_FAILURE;
    }

    motor_forward_2 = gpiod_chip_get_line(chip, MOTOR_FORWARD_2);
    if (!motor_forward_2) {
        fprintf(stderr, "Failed to get line for motor forward 2\n");
        return EXIT_FAILURE;
    }

    if (gpiod_line_request_input(rain_sensor, "rain_sensor") < 0) {
        fprintf(stderr, "Failed to request input for rain sensor\n");
        return EXIT_FAILURE;
    }

    if (gpiod_line_request_output(motor_enable, "motor_enable") < 0) {
        fprintf(stderr, "Failed to request output for motor enable\n");
        return EXIT_FAILURE;
    }

    if (gpiod_line_request_output(motor_forward_1, "motor_forward_1") < 0) {
        fprintf(stderr, "Failed to request output for motor forward 1\n");
        return EXIT_FAILURE;
    }

    if (gpiod_line_request_output(motor_forward_2, "motor_forward_2") < 0) {
        fprintf(stderr, "Failed to request output for motor forward 2\n");
        return EXIT_FAILURE;
    }

    while (1) {
        int value = gpiod_line_get_value(rain_sensor);
        if (value < 0) {
            fprintf(stderr, "Failed to get value for rain sensor\n");
            return EXIT_FAILURE;
        }

        if (value == 0) {
            printf("%ld: Rain detected, closing window\n", time(NULL));
            gpiod_line_set_value(motor_enable, 1);
            gpiod_line_set_value(motor_forward_1, 1);
            gpiod_line_set_value(motor_forward_2, 0);
            sleep(5);
            gpiod_line_set_value(motor_enable, 0);
            gpiod_line_set_value(motor_forward_1, 0);
            gpiod_line_set_value(motor_forward_2, 0);
        }

        sleep(2);
    }

    return EXIT_SUCCESS;
}

#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <unistd.h>
#include <signal.h>
#include <pigpio.h>

#define RED_PIN 17
#define GREEN_PIN 22
#define BLUE_PIN 27

volatile sig_atomic_t stop = 0;

void signal_handler(int signum) {
    stop = 1;
}

void set_led_color(uint8_t red, uint8_t green, uint8_t blue) {
    gpioPWM(RED_PIN, red);
    gpioPWM(GREEN_PIN, green);
    gpioPWM(BLUE_PIN, blue);
}

void terminate_program() {
    set_led_color(0, 0, 0);
    gpioTerminate();
    exit(0);
}

int main() {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Failed to initialize pigpio\n");
        return 1;
    }

    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    gpioSetPWMfrequency(RED_PIN, 1000);
    gpioSetPWMfrequency(GREEN_PIN, 1000);
    gpioSetPWMfrequency(BLUE_PIN, 1000);

    FILE *file;
    char line[128];
    unsigned long long prev_total, total, prev_idle, idle;
    unsigned long long prev_load, load;
    float cpu_load;

    file = fopen("/proc/stat", "r");
    if (file == NULL) {
        fprintf(stderr, "Failed to open /proc/stat\n");
        terminate_program();
    }

    fscanf(file, "%*s %llu %llu %llu %llu", &prev_total, &prev_idle, &prev_load, &load);
    fclose(file);

    while (!stop) {
        sleep(1);

        file = fopen("/proc/stat", "r");
        if (file == NULL) {
            fprintf(stderr, "Failed to open /proc/stat\n");
            terminate_program();
        }

        fscanf(file, "%*s %llu %llu %llu %llu", &total, &idle, &load, &load);
        fclose(file);

        cpu_load = (float)(total - prev_total) / (total - prev_total - (idle - prev_idle));

        if (cpu_load < 0.5) {
            set_led_color(0, 255, 0); // Green
        } else if (cpu_load < 1.0) {
            set_led_color(255, 255, 0); // Yellow
        } else {
            set_led_color(255, 0, 0); // Red
        }

        prev_total = total;
        prev_idle = idle;
        prev_load = load;
    }

    terminate_program();
}

