#define MAX31855_FAULT_REG 0x01
#define MAX31855_FAULT_OC 0x01
#define MAX31855_FAULT_SCG 0x02
#define MAX31855_FAULT_SCV 0x04
#define MAX31855_FAULT_MASK (MAX31855_FAULT_OC | MAX31855_FAULT_SCG | MAX31855_FAULT_SCV)
#define PWM_FREQ 1000
#define PWM_DUTY_MIN 0
#define PWM_DUTY_MAX 255
#define TEMP_MIN 25
#define TEMP_MAX 60
#define BUF_SIZE 20

typedef struct {
    time_t timestamp;
    int16_t temperature;
    uint8_t duty_cycle;
} LogEntry;

LogEntry log_buffer[BUF_SIZE];
int log_head = 0;
int log_tail = 0;
int log_count = 0;

void log_temperature(int16_t temperature, uint8_t duty_cycle) {
    time(&log_buffer[log_head].timestamp);
    log_buffer[log_head].temperature = temperature;
    log_buffer[log_head].duty_cycle = duty_cycle;
    log_head = (log_head + 1) % BUF_SIZE;
    if (log_count < BUF_SIZE) {
        log_count++;
    } else {
        log_tail = (log_tail + 1) % BUF_SIZE;
    }
}

void print_log() {
    for (int i = 0; i < log_count; i++) {
        int index = (log_tail + i) % BUF_SIZE;
        printf("%ld: %d°C, PWM: %d%%\n", log_buffer[index].timestamp, log_buffer[index].temperature, log_buffer[index].duty_cycle);
    }
}

void handle_sigint(int signum) {
    gpioTerminate();
    exit(0);
}

int main() {
    signal(SIGINT, handle_sigint);

    if (gpioInitialise() < 0) {
        fprintf(stderr, "Failed to initialize pigpio\n");
        return 1;
    }

    int spi = spiOpen(SPI_CHANNEL, SPI_SPEED, SPI_MODE);
    if (spi < 0) {
        fprintf(stderr, "Failed to open SPI channel\n");
        gpioTerminate();
        return 1;
    }

    gpioSetPWMfrequency(FAN_PIN, PWM_FREQ);
    gpioSetPWMrange(FAN_PIN, PWM_DUTY_MAX);

    while (1) {
        uint8_t txbuf[3] = {MAX31855_REG, 0, 0};
        uint8_t rxbuf[3] = {0, 0, 0};
        int ret = spiXfer(spi, txbuf, rxbuf, 3);
        if (ret < 0) {
            fprintf(stderr, "SPI transfer error\n");
            continue;
        }

        int16_t raw_temp = (rxbuf[1] << 8) | rxbuf[2];
        int16_t temperature = (raw_temp >> 2) * 0.25;
        uint8_t duty_cycle = 0;

        if (temperature < TEMP_MIN) {
            duty_cycle = PWM_DUTY_MIN;
        } else if (temperature < TEMP_MAX) {
            duty_cycle = (uint8_t)((temperature - TEMP_MIN) * (PWM_DUTY_MAX - PWM_DUTY_MIN) / (TEMP_MAX - TEMP_MIN) + PWM_DUTY_MIN);
        } else {
            duty_cycle = PWM_DUTY_MAX;
        }

        log_temperature(temperature, duty_cycle);
        gpioPWM(FAN_PIN, duty_cycle);

        sleep(1);
    }

    gpioTerminate();
    spiClose(spi);
    return 0;
}

