#define MAX31865_RTD_MUX 0x07
#define MAX31865_DIAG 0x02
#define MAX31865_FAULT 0x01
#define RTD_A 0x3FFFF
#define RTD_B 0x145E
#define RTD_C 0x16C0
#define RTD_D 0x068B

static int spi_fd;
static FILE *log_file;
static int running = 1;

void signal_handler(int signum) {
    running = 0;
}

void close_spi() {
    if (spi_fd >= 0) {
        close(spi_fd);
    }
}

void close_log() {
    if (log_file) {
        fclose(log_file);
    }
