int main() {
    struct gpiod_chip *chip;
    struct gpiod_line_request request;
    struct spi_ioc_transfer tr;
    uint8_t tx[3] = {0x00, 0x00, 0x00};
    uint8_t rx[3] = {0x00, 0x00, 0x00};
    uint32_t rtd;
    float temp;
    struct timespec ts;

    // Initialize GPIO
    chip = gpiod_chip_open_by_name("gpiochip0");
    if (!chip) {
        fprintf(stderr, "Failed to open GPIO chip\n");
        return EXIT_FAILURE;
    }
    gpiod_line_request_input(&request, "max31865_cs");
    gpiod_chip_request_line(chip, CS_PIN, &request);
    gpiod_line_set_value(chip, CS_PIN, 1);

    // Initialize SPI
    spi_fd = open(SPI_DEVICE, O_RDWR);
    if (spi_fd < 0) {
        fprintf(stderr, "Failed to open SPI device\n");
        gpiod_chip_close(chip);
        return EXIT_FAILURE;
    }
    memset(&tr, 0, sizeof(tr));
    tr.tx_buf = (unsigned long)tx;
    tr.rx_buf = (unsigned long)rx;
    tr.len = 3;
    tr.delay_usecs = 0;
    tr.speed_hz = 1000000;
    tr.bits_per_word = 8;
    if (ioctl(spi_fd, SPI_IOC_MESSAGE(1), &tr) < 0) {
        fprintf(stderr, "Failed to configure SPI\n");
        close_spi();
        gpiod_chip_close(chip);
        return EXIT_FAILURE;
    }

    // Initialize log file
    log_file = fopen(LOG_FILE, "w");
    if (!log_file) {
        fprintf(stderr, "Failed to open log file\n");
        close_spi();
        gpiod_chip_close(chip);
        return EXIT_FAILURE;
    }
    fprintf(log_file, "Timestamp, Temperature\n");

    // Set up signal handler
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Main loop
    while (running) {
        // Request a conversion
        tx[0] = MAX31865_CONFIG | MAX31865_RTD_MUX;
        if (ioctl(spi_fd, SPI_IOC_MESSAGE(1), &tr) < 0) {
            fprintf(stderr, "Failed to send SPI message\n");
            break;
        }

        // Read the result
        tx[0] = 0x01;
        if (ioctl(spi_fd, SPI_IOC_MESSAGE(1), &tr) < 0) {
            fprintf(stderr, "Failed to read SPI message\n");
            break;
        }
        rtd = (rx[1] << 16) | (rx[2] << 8) | rx[0];

        // Check for faults
        tx[0] = MAX31865_DIAG;
        if (ioctl(spi_fd, SPI_IOC_MESSAGE(1), &tr) < 0) {
            fprintf(stderr, "Failed to read fault status\n");
            break;
        }
        if (rx[0] & MAX31865_FAULT) {
            fprintf(stderr, "Sensor fault detected\n");
            break;
        }

        // Calculate temperature
        temp = (float)RTD_A / (float)rtd;
        temp = (1.0 / temp) - 1.0;
        temp = 1.0 / temp;
        temp = (temp - RTD_A) / (RTD_B * temp - RTD_C * temp + RTD_D);

        // Log the reading
        clock_gettime(CLOCK_REALTIME, &ts);
        fprintf(log_file, "%ld.%09ld, %.2f\n", ts.tv_sec, ts.tv_nsec, temp);

        // Wait for the next reading
        sleep(5);
    }

    // Clean up
    close_log();
    close_spi();
    gpiod_chip_close(chip);
    return EXIT_SUCCESS;
}

