#define CSV_FILE "bme280_log.csv"

int bme280_read(int file, uint8_t reg, uint8_t *data, int len) {
    if (ioctl(file, I2C_SLAVE, BME280_I2C_ADDRESS) < 0) {
        return -1;
    }
    if (write(file, &reg, 1) != 1) {
        return -1;
    }
    if (read(file, data, len) != len) {
        return -1;
    }
    return 0;
}

int bme280_write(int file, uint8_t reg, uint8_t *data, int len) {
    if (ioctl(file, I2C_SLAVE, BME280_I2C_ADDRESS) < 0) {
        return -1;
    }
    uint8_t buf[len + 1];
    buf[0] = reg;
    memcpy(buf + 1, data, len);
    if (write(file, buf, len + 1) != len + 1) {
        return -1;
    }
    return 0;
}

