    uint8_t chip_id;
    if (bme280_read(file, BME280_REG_ID, &chip_id, 1) < 0 || chip_id != BME280_CHIP_ID) {
        perror("Failed to read or verify chip ID");
        close(file);
        return EXIT_FAILURE;
    }

    FILE *csv_file = fopen(CSV_FILE, "w");
    if (!csv_file) {
        perror("Failed to open CSV file");
        close(file);
