            break;
        }

        int16_t temp_raw = (data[0] << 8) | data[1];
        float temperature_C = (float)temp_raw / 100.0;

        if (bme280_read(file, BME280_REG_HUM, data, BME280_DATA_LEN) < 0) {
            perror("Failed to read humidity data");
            break;
        }

        int16_t hum_raw = (data[0] << 8) | data[1];
        float humidity_percent = (float)hum_raw / 1024.0 * 100.0;

        if (bme280_read(file, BME280_REG_PRESS, data, BME280_DATA_LEN) < 0) {
