#include <stdio.h>
#include <stdlib.h>
#include <signal.h>
#include <pigpio.h>
#include <time.h>

#define I2C_BUS 1
#define I2C_ADDRESS 0x77
#define PRESSURE_REG 0xF4
#define CALIBRATION_REG 0xAA
#define PRESSURE_SAMPLE_TIME 5 // ms
#define SAMPLE_INTERVAL 50 // ms
#define ALERT_THRESHOLD 5 // hPa
#define BUFFER_SIZE 60 // seconds

typedef struct {
    uint32_t timestamp;
    float pressure;
} Reading;

Reading buffer[BUFFER_SIZE];
int buffer_head = 0;
float rolling_average = 0;
int alert_triggered = 0;

void handle_sigint(int signum) {
    gpioTerminate();
    exit(0);
}

void timer_callback(uint32_t timer, int32_t tick, void *userdata) {
    int file = *(int *)userdata;
    uint8_t data[2];
    int16_t raw_pressure;
    float pressure;

    // Read pressure
    data[0] = PRESSURE_REG;
    data[1] = 0x34 + (0 << 6);
    i2cWriteByteData(file, PRESSURE_REG, data[1]);
    usleep(PRESSURE_SAMPLE_TIME * 1000);
    raw_pressure = (i2cReadByteData(file, 0xF6) << 8) | i2cReadByteData(file, 0xF7);
    pressure = (raw_pressure / 2.0) + 0.36;

    // Update rolling average
    rolling_average = (rolling_average * (BUFFER_SIZE - 1) + pressure) / BUFFER_SIZE;

    // Check for alert
    if (fabs(pressure - rolling_average) > ALERT_THRESHOLD) {
        gpioWrite(24, 1);
        alert_triggered = 1;
    }

    // Log reading
    buffer[buffer_head].timestamp = time(NULL);
    buffer[buffer_head].pressure = pressure;
    buffer_head = (buffer_head + 1) % BUFFER_SIZE;

    // Reset alert if necessary
    if (alert_triggered && fabs(pressure - rolling_average) <= ALERT_THRESHOLD) {
        gpioWrite(24, 0);
        alert_triggered = 0;
    }
}

int main() {
    int file;
    struct sigaction sigact;
    uint32_t timer;

    // Initialize GPIO
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Failed to initialize GPIO\n");
        return 1;
    }

    // Register SIGINT handler
    sigact.sa_handler = handle_sigint;
    sigemptyset(&sigact.sa_mask);
    sigact.sa_flags = 0;
    sigaction(SIGINT, &sigact, NULL);

    // Open I2C device
    file = i2cOpen(I2C_BUS, I2C_ADDRESS, 0);
    if (file < 0) {
        fprintf(stderr, "Failed to open I2C device\n");
        gpioTerminate();
        return 1;
    }

    // Set up timer
    timer = gpioSetTimerFuncEx(timer_callback, &file, SAMPLE_INTERVAL);

    // Main loop
    while (1) {
        sleep(1);
    }

    // Clean up
    gpioSetTimerFuncEx(timer, NULL, 0);
    i2cClose(file);
    gpioTerminate();
    return 0;
}

