    rolling_average = (rolling_average * (BUFFER_SIZE - 1) + pressure) / BUFFER_SIZE;

    // Check for alert
    if (fabs(pressure - rolling_average) > ALERT_THRESHOLD) {
        gpioWrite(24, 1);
        alert_triggered = 1;
    }

    // Log reading
