    if ((i2c_fd = open(BMP280_I2C_BUS, O_RDWR)) < 0) {
        perror("Failed to open the i2c bus");
        return 1;
    }

    if (ioctl(i2c_fd, I2C_SLAVE, BMP280_ADDRESS) < 0) {
        perror("Failed to acquire bus access and/or talk to slave");
        return 1;
    }

    messages[0].addr = BMP280_ADDRESS;
    messages[0].flags = 0;
    messages[0].len = 1;
    messages[0].buf = &BMP280_REG_CHIPID;

    messages[1].addr = BMP280_ADDRESS;
    messages[1].flags = I2C_M_RD;
    messages[1].len = 1;
    messages[1].buf = &chip_id;

    packets.msgs = messages;
    packets.nmsgs = 2;

    if (ioctl(i2c_fd, I2C_RDWR, &packets) < 0) {
        perror("Failed to send command");
        return 1;
    }

    if (chip_id != BMP280_ID) {
        printf("Invalid chip ID: %x\n", chip_id);
        return 1;
    }

    // Set up signal handler
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    while (!stop) {
