        do {
            usleep(1000);
            messages[0].len = 1;
            messages[0].buf = &BMP280_REG_STATUS;
            if (ioctl(i2c_fd, I2C_RDWR, &packets) < 0) {
                perror("Failed to read status");
                return 1;
            }
