        // Read the raw temperature and pressure data
        messages[0].len = 2;
        messages[0].buf = &BMP280_REG_TEMP_MSB;
        messages[1].len = BMP280_DATA_LEN;
        messages[1].buf = data;

        if (ioctl(i2c_fd, I2C_RDWR, &packets) < 0) {
            perror("Failed to read raw data");
            return 1;
        }

        raw_temp = (data[0] << 12) | (data[1] << 4) | (data[2] >> 4);
        raw_press = (data[3] << 12) | (data[4] << 4) | (data[5] >> 4);

        // Convert the raw data to temperature and pressure
        // This is a simplified version and does not include the calibration block
        temp = raw_temp / 16.0;
        press = raw_press / 4096.0;

        // Get the current time
