#define I2C_BUS 1
#define I2C_ADDRESS 0x48
#define GPIO_PIN 18
#define BUFFER_SIZE 60

struct circular_buffer {
    int head;
    int tail;
    int count;
    float buffer[BUFFER_SIZE];
};

struct circular_buffer cb;
pthread_mutex_t cb_mutex = PTHREAD_MUTEX_INITIALIZER;
pthread_t thread_id;
bool running = true;

void* read_temperature(void* arg) {
    int i2c_fd = open("/dev/i2c-1", O_RDWR);
    if (i2c_fd < 0) {
        perror("Failed to open I2C bus");
        exit(EXIT_FAILURE);
    }

    if (ioctl(i2c_fd, I2C_SLAVE, I2C_ADDRESS) < 0) {
        perror("Failed to set I2C address");
        close(i2c_fd);
        exit(EXIT_FAILURE);
    }

    struct gpiod_chip *chip = gpiod_chip_open_by_name("gpiochip0");
    if (!chip) {
        perror("Failed to open GPIO chip");
        close(i2c_fd);
        exit(EXIT_FAILURE);
    }

    struct gpiod_line *line = gpiod_chip_get_line(chip, GPIO_PIN);
    if (!line) {
        perror("Failed to get GPIO line");
        gpiod_chip_close(chip);
        close(i2c_fd);
        exit(EXIT_FAILURE);
    }

    while (running) {
        uint8_t reg = 0x00;
        int16_t temp;
        if (write(i2c_fd, &reg, 1) != 1) {
            perror("Failed to write to I2C device");
            continue;
        }

        if (read(i2c_fd, &temp, 2) != 2) {
            perror("Failed to read from I2C device");
            continue;
        }

        temp = (temp >> 5) * 0.25;

        pthread_mutex_lock(&cb_mutex);
        cb.buffer[cb.head] = temp;
        cb.head = (cb.head + 1) % BUFFER_SIZE;
        if (cb.count < BUFFER_SIZE) {
            cb.count++;
        } else {
            cb.tail = (cb.tail + 1) % BUFFER_SIZE;
        }
        pthread_mutex_unlock(&cb_mutex);
    }

    gpiod_line_release(line);
    gpiod_chip_close(chip);
    close(i2c_fd);
    return NULL;
}

int main() {
    pthread_create(&thread_id, NULL, read_temperature, NULL);

    struct gpiod_chip *chip = gpiod_chip_open_by_name("gpiochip0");
    if (!chip) {
        perror("Failed to open GPIO chip");
        return EXIT_FAILURE;
    }

    struct gpiod_line *line = gpiod_chip_get_line(chip, GPIO_PIN);
    if (!line) {
        perror("Failed to get GPIO line");
        gpiod_chip_close(chip);
        return EXIT_FAILURE;
    }

    while (running) {
        pthread_mutex_lock(&cb_mutex);
        float sum = 0;
        for (int i = 0; i < cb.count; i++) {
            sum += cb.buffer[(cb.tail + i) % BUFFER_SIZE];
        }
        float avg = sum / cb.count;
        pthread_mutex_unlock(&cb_mutex);

        if (avg > 28.0) {
            gpiod_line_set_value(line, 1);
        } else {
            gpiod_line_set_value(line, 0);
        }

        sleep(1);
    }

    gpiod_line_release(line);
    gpiod_chip_close(chip);
    pthread_cancel(thread_id);
    pthread_join(thread_id, NULL);
    return EXIT_SUCCESS;
}

#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <stdbool.h>
#include <stdint.h>
#include <unistd.h>
#include <signal.h>
#include <pigpio.h>
#include <libconfig.h>

#define SPI_CHANNEL 0
#define SPI_SPEED 500000
#define SPI_MODE 1
#define SPI_MAX31865_CONFIG 0xC1
#define SPI_MAX31865_RTDMSB 0x01
#define SPI_MAX31865_RTDLSB 0x02
#define SPI_MAX31865_FAULT 0x07
#define GPIO_MOSFET 18
#define GPIO_MOSFET_FREQ 1000
#define GPIO_MOSFET_RANGE 1000
#define PID_UPDATE_INTERVAL 100
#define TEMP_MAX 80.0
#define R_REF 430.0
#define R0 100.0
#define A 3.9083e-3
#define B -5.775e-7

volatile sig_atomic_t stop = 0;

void signal_handler(int signum) {
    stop = 1;
}

int main(int argc, char *argv[]) {
    // Load config
    config_t cfg;
    config_init(&cfg);
    if (!config_read_file(&cfg, "config.json")) {
        fprintf(stderr, "%s:%d - %s\n", config_error_file(&cfg),
                config_error_line(&cfg), config_error_text(&cfg));
        config_destroy(&cfg);
        return EXIT_FAILURE;
    }
    double target_temp = 25.0;
    double Kp = 1.0;
    double Ki = 0.1;
    double Kd = 0.01;
    config_lookup_float(&cfg, "target", &target_temp);
    config_lookup_float(&cfg, "Kp", &Kp);
    config_lookup_float(&cfg, "Ki", &Ki);
    config_lookup_float(&cfg, "Kd", &Kd);
    config_destroy(&cfg);

    // Initialize GPIO and SPI
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Failed to initialize GPIO\n");
        return EXIT_FAILURE;
    }
    if (spiOpen(SPI_CHANNEL, SPI_SPEED, SPI_MODE) < 0) {
        fprintf(stderr, "Failed to open SPI\n");
        gpioTerminate();
        return EXIT_FAILURE;
    }

    // Set up GPIO and SPI
    if (gpioSetMode(GPIO_MOSFET, PI_OUTPUT) < 0) {
        fprintf(stderr, "Failed to set GPIO mode\n");
        spiClose(SPI_CHANNEL);
        gpioTerminate();
        return EXIT_FAILURE;
    }
    if (spiMax31865(SPI_CHANNEL, SPI_MAX31865_CONFIG) < 0) {
        fprintf(stderr, "Failed to configure MAX31865\n");
        spiClose(SPI_CHANNEL);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    // Set up signal handler
    struct sigaction action;
    memset(&action, 0, sizeof(struct sigaction));
    action.sa_handler = signal_handler;
    sigaction(SIGINT, &action, NULL);
    sigaction(SIGTERM, &action, NULL);

    // PID control loop
    double integral = 0.0;
    double last_error = 0.0;
    uint32_t last_time = millis();
    while (!stop) {
        // Read temperature
        uint16_t rtd_code = spiMax31865(SPI_CHANNEL, SPI_MAX31865_RTDMSB);
        if (rtd_code < 0) {
            fprintf(stderr, "Failed to read RTD code\n");
            stop = 1;
            break;
        }
        double resistance = (double)rtd_code / 32768.0 * R_REF;
        double temperature = R0 * (1 + A * temperature + B * temperature * temperature);

        // Check for faults
        uint8_t fault = spiMax31865(SPI_CHANNEL, SPI_MAX31865_FAULT);
        if (fault < 0) {
            fprintf(stderr, "Failed to read fault status\n");
            stop = 1;
            break;
        }
        if (fault & 0x01) {
            fprintf(stderr, "MAX31865 open circuit fault\n");
            stop = 1;
            break;
        }
        if (fault & 0x02) {
            fprintf(stderr, "MAX31865 over-voltage fault\n");
            stop = 1;
            break;
        }
        if (fault & 0x04) {
            fprintf(stderr, "MAX31865 under-voltage fault\n");
            stop = 1;
            break;
        }

        // Check for max temperature
        if (temperature > TEMP_MAX) {
            fprintf(stderr, "Temperature exceeded max limit\n");
            stop = 1;
            break;
        }

        // PID control
        double error = target_temp - temperature;
        integral += error * (double)(millis() - last_time) / 1000.0;
        double derivative = (error - last_error) / (double)(millis() - last_time) / 1000.0;
        double output = Kp * error + Ki * integral + Kd * derivative;
        last_error = error;
        last_time = millis();

        // Set PWM
        uint32_t duty = (uint32_t)(output * (double)GPIO_MOSFET_RANGE + 0.5);
        if (gpioHardwarePWM(GPIO_MOSFET, GPIO_MOSFET_FREQ, duty) < 0) {
            fprintf(stderr, "Failed to set PWM\n");
            stop = 1;
            break;
        }

        // Sleep for a bit
        usleep(PID_UPDATE_INTERVAL * 1000);
    }

    // Clean up
    gpioHardwarePWM(GPIO_MOSFET, 0, 0);
    spiClose(SPI_CHANNEL);
    gpioTerminate();
    return EXIT_SUCCESS;
}

