#define BMP180_LOG_FILE "breach_log.txt"

int i2c_fd;
FILE *log_fd;

void cleanup(int signum) {
    close(i2c_fd);
    fclose(log_fd);
    exit(signum);
}

int read_i2c_reg(int fd, uint8_t reg) {
    int ret;
    uint8_t buf[2];

    buf[0] = reg;
    ret = write(fd, buf, 1);
    if (ret != 1) {
        return -1;
    }

    ret = read(fd, buf, 2);
    if (ret != 2) {
        return -1;
    }

    return (buf[0] << 8) | buf[1];
}

int main() {
    struct sigaction action;
    action.sa_handler = cleanup;
    sigemptyset(&action.sa_mask);
    action.sa_flags = 0;
    sigaction(SIGINT, &action, NULL);
    sigaction(SIGTERM, &action, NULL);

    i2c_fd = open(BMP180_FILE, O_RDWR);
    if (i2c_fd < 0) {
        perror("Failed to open i2c device");
        return 1;
    }

    if (ioctl(i2c_fd, I2C_SLAVE, BMP180_I2C_ADDRESS) < 0) {
        perror("Failed to set i2c address");
        return 1;
    }

    log_fd = fopen(BMP180_LOG_FILE, "w");
    if (!log_fd) {
        perror("Failed to open log file");
        return 1;
    }

    while (1) {
        int temp = read_i2c_reg(i2c_fd, 0x2b);
        int pressure = read_i2c_reg(i2c_fd, 0x29);

        if (temp < 0 || pressure < 0) {
            fprintf(log_fd, "Failed to read sensor data\n");
            continue;
        }

        if (temp > BMP180_TEMP_THRESHOLD) {
            time_t now = time(NULL);
            struct tm *t = localtime(&now);
            char timestamp[20];
            strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", t);
            fprintf(log_fd, "%s: Temperature breach: %d\n", timestamp, temp);
        }

        if (pressure < BMP180_PRESSURE_THRESHOLD) {
            time_t now = time(NULL);
            struct tm *t = localtime(&now);
            char timestamp[20];
            strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", t);
            fprintf(log_fd, "%s: Pressure breach: %d\n", timestamp, pressure);
        }

        sleep(1);
    }

    return 0;
}

