#define DEBOUNCE_TIME 200
#define LOG_INTERVAL 2

int i2c_handle;
int logging_enabled = 0;
FILE *log_file;

void cleanup(int signum) {
    if (i2c_handle >= 0) {
        i2cClose(i2c_handle);
    }
    if (log_file) {
        fclose(log_file);
    }
    exit(signum);
}

void toggle_logging() {
    logging_enabled = !logging_enabled;
    printf("Logging %s\n", logging_enabled ? "enabled" : "disabled");
}

void read_and_log() {
    uint8_t raw_data[3];
    int32_t adc, b5;
    int16_t calib[11];
    float pressure;

    i2cReadByteData(i2c_handle, BMP180_REG_RESULT + 2);
    i2cReadBlockData(i2c_handle, BMP180_REG_RESULT, raw_data, 3);

    adc = (raw_data[0] << 16) | (raw_data[1] << 8) | raw_data[2];

    for (int i = 0; i < 11; i++) {
        calib[i] = i2cReadByteData(i2c_handle, BMP180_REG_CALIB + i * 2);
    }

    b5 = calib[5] * 32768 + calib[6] * adc;
    pressure = (b5 / 32768.0) * (1.0 + calib[2] / 131072.0 + calib[3] / 65536.0) +
                calib[4] / 16384.0;

    fprintf(log_file, "%ld, %f\n", time(NULL), pressure);
    fflush(log_file);
}

int main() {
