#include <pigpio.h>
#include <max31855.h>

#define TARGET_TEMP 25.0
#define PWM_FREQ 2e6
#define PWM_MAX_DUTY 80
#define SPI_CHANNEL 0
#define MAX31855_CS 8
#define MAX31855_MISO 9
#define MAX31855_MOSI 10
#define MAX31855_SCLK 11
#define RELAY_GPIO 17

FILE *log_file;
bool running = true;

void cleanup(int signum) {
    running = false;
    gpioSetPWMdutycycle(RELAY_GPIO, 0);
    fclose(log_file);
    spiClose(SPI_CHANNEL);
    gpioTerminate();
    exit(signum);
}

void log_data(float temp, float duty) {
    time_t now = time(NULL);
    struct tm *t = localtime(&now);
    char timestamp[20];
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%dT%H:%M:%S", t);
    fprintf(log_file, "%s,%.2f,%.2f\n", timestamp, temp, duty);
    fflush(log_file);
}

int main() {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Failed to initialize pigpio\n");
        return EXIT_FAILURE;
    }

    signal(SIGINT, cleanup);
    signal(SIGTERM, cleanup);

    if ((log_file = fopen("heater_log.csv", "w")) == NULL) {
        fprintf(stderr, "Failed to open log file\n");
        gpioTerminate();
        return EXIT_FAILURE;
    }

    if (spiOpen(SPI_CHANNEL, MAX31855_CS, MAX31855_SCLK, MAX31855_MOSI, MAX31855_MISO) < 0) {
        fprintf(stderr, "Failed to open SPI channel\n");
        cleanup(EXIT_FAILURE);
    }

    if (gpioSetPWMfrequency(SPI_CHANNEL, PWM_FREQ) < 0) {
        fprintf(stderr, "Failed to set PWM frequency\n");
        cleanup(EXIT_FAILURE);
    }

    gpioSetMode(RELAY_GPIO, PI_OUTPUT);

    float temp, prev_error = 0, integral = 0;
    int duty = 0;

    while (running) {
        temp = max31855Read(SPI_CHANNEL);
        if (temp < 0) {
            fprintf(stderr, "Failed to read temperature\n");
            duty = 0;
        } else {
            float error = TARGET_TEMP - temp;
            integral += error;
            if (integral > PWM_MAX_DUTY) integral = PWM_MAX_DUTY;
            if (integral < 0) integral = 0;
            duty = error * 0.1 + integral * 0.1;
            if (duty > PWM_MAX_DUTY) duty = PWM_MAX_DUTY;
            if (duty < 0) duty = 0;
        }

        gpioSetPWMdutycycle(RELAY_GPIO, duty);
        log_data(temp, duty / (float) PWM_MAX_DUTY * 100);
    }

    cleanup(EXIT_SUCCESS);
}

