#define DHT22_PIN 4
#define DHT22_DATA_TIMEOUT 1000
#define DHT22_MAX_RETRIES 3
#define DHT22_POST_URL "http://yourserver.com/api/humidity"

static bool running = true;
static CURL *curl_handle = NULL;
static gpioPulse_t pulse;

void cleanup(int signum) {
    running = false;
    if (curl_handle) {
        curl_easy_cleanup(curl_handle);
    }
    gpioTerminate();
    exit(signum);
}

size_t write_callback(void *contents, size_t size, size_t nmemb, void *userp) {
    return size * nmemb;
}

bool send_data(float humidity, float temperature) {
    CURLcode res;
    char post_data[128];
    snprintf(post_data, sizeof(post_data), "{\"humidity\":%.2f,\"temperature\":%.2f}", humidity, temperature);

    curl_easy_setopt(curl_handle, CURLOPT_POSTFIELDS, post_data);
    res = curl_easy_perform(curl_handle);

    if (res != CURLE_OK) {
        fprintf(stderr, "curl_easy_perform() failed: %s\n", curl_easy_strerror(res));
        return false;
    }

    return true;
}

bool read_dht22(float *humidity, float *temperature) {
    int retries = 0;
    uint8_t data[5] = {0};

    while (retries < DHT22_MAX_RETRIES) {
        // Send start signal
        gpioSetMode(DHT22_PIN, PI_OUTPUT);
        gpioWrite(DHT22_PIN, PI_LOW);
        usleep(1000);
        gpioWrite(DHT22_PIN, PI_HIGH);
        gpioSetMode(DHT22_PIN, PI_INPUT);

        // Wait for response
        struct timespec ts = {0, DHT22_DATA_TIMEOUT * 1000};
        if (gpioWaitForEdge(DHT22_PIN, RISING_EDGE, &ts) != 0) {
            retries++;
            continue;
        }

        // Read 40 bits of data
        for (int i = 0; i < 40; i++) {
            struct timespec ts = {0, DHT22_DATA_TIMEOUT * 1000};
            if (gpioWaitForEdge(DHT22_PIN, FALLING_EDGE, &ts) != 0) {
                retries++;
                break;
            }
            usleep(35);
            data[i / 8] <<= 1;
            if (gpioRead(DHT22_PIN) == PI_HIGH) {
                data[i / 8] |= 1;
            }
        }

        // Validate checksum
        uint8_t checksum = data[0] + data[1] + data[2] + data[3];
        if (checksum == data[4]) {
            *humidity = data[0] * 256 + data[1];
            *temperature = data[2] * 256 + data[3];
            return true;
        }

        retries++;
    }

    return false;
}

int main() {
    struct sigaction action;
    memset(&action, 0, sizeof(struct sigaction));
    action.sa_handler = cleanup;
    sigaction(SIGINT, &action, NULL);
    sigaction(SIGTERM, &action, NULL);

    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialization failed\n");
        return EXIT_FAILURE;
    }

    curl_global_init(CURL_GLOBAL_DEFAULT);
    curl_handle = curl_easy_init();

    if (!curl_handle) {
        fprintf(stderr, "curl_easy_init() failed\n");
        return EXIT_FAILURE;
    }

    curl_easy_setopt(curl_handle, CURLOPT_URL, DHT22_POST_URL);
    curl_easy_setopt(curl_handle, CURLOPT_WRITEFUNCTION, write_callback);

    float humidity, temperature;
    while (running) {
        if (read_dht22(&humidity, &temperature)) {
            if (!send_data(humidity, temperature)) {
                fprintf(stderr, "Failed to send data\n");
            }
        } else {
            fprintf(stderr, "Failed to read DHT22 sensor\n");
        }
        sleep(2);
    }

    cleanup(0);
    return EXIT_SUCCESS;
}

#include <stdio.h>
