#define BMP180_ADDRESS 0x77
#define BMP180_REG_CONTROL 0xF4
#define BMP180_REG_RESULT 0xF6
#define BMP180_REG_CALIB 0xAA
#define BMP180_OSS 3
#define BMP180_CONVERSION_DELAY 26 //ms

volatile sig_atomic_t stop;

void gpioCallback(int gpio, int level, uint32_t tick) {
    static uint32_t lastTick = 0;
    if (tick - lastTick > 200000) { // debounce
        stop = !stop;
        printf("Logging %s\n", stop ? "enabled" : "disabled");
    }
    lastTick = tick;
}

int main() {
    FILE *file;
    int fd, i;
    uint8_t data[22];
    int16_t calib[11];
    int32_t ut, up, p;
    int32_t x1, x2, b5;

    if ((fd = i2cOpen(1, BMP180_ADDRESS, 0)) < 0) {
        fprintf(stderr, "Failed to open I2C device\n");
        return EXIT_FAILURE;
    }

    if (i2cReadFile(fd, data, 22) != 22) {
        fprintf(stderr, "Failed to read calibration data\n");
        i2cClose(fd);
        return EXIT_FAILURE;
    }

    for (i = 0; i < 11; i++) {
        calib[i] = (data[i * 2 + 1] << 8) | data[i * 2];
    }

    signal(SIGINT, gpioTerminate);

    if (gpioInitialise() < 0) {
        fprintf(stderr, "Failed to initialize pigpio\n");
        return EXIT_FAILURE;
    }

    gpioSetMode(4, PI_INPUT);
    gpioSetPullUpDown(4, PI_PUD_UP);
    gpioSetAlertFunc(4, gpioCallback);

    file = fopen("pressure_log.txt", "w");
    if (!file) {
        fprintf(stderr, "Failed to open log file\n");
        gpioTerminate();
        return EXIT_FAILURE;
    }

    while (!stop) {
        gpioDelay(2000000); // wait for 2 seconds

        if (i2cWriteByteData(fd, BMP180_REG_CONTROL, 0x34 + (BMP180_OSS << 6)) < 0) {
            fprintf(stderr, "Failed to write control data\n");
            break;
        }

        gpioDelay(BMP180_CONVERSION_DELAY * 1000);

        if (i2cReadFile(fd, data, 3) != 3) {
            fprintf(stderr, "Failed to read uncompensated temperature\n");
            break;
        }

        ut = (data[0] << 8) | data[1];
        up = (data[2] << 8) | data[3];

        x1 = ((ut - calib[5]) * calib[2]) >> 15;
        x2 = ((calib[4] * (ut - calib[5])) >> 15) + calib[3];
        b5 = x1 + x2;

        p = ((up * calib[1]) >> 8) - (calib[0] * 2) + ((b5 * calib[6]) >> 16);

        if (stop) {
            fprintf(file, "%ld, %d\n", time(NULL), p);
        } else {
            printf("Logging disabled\n");
        }
    }

    fclose(file);
    gpioTerminate();
    i2cClose(fd);

    return EXIT_SUCCESS;
}

