        int bytes_read = read(temp_fd, buffer, sizeof(buffer) - 1);
        if (bytes_read < 0) {
            perror("Failed to read temperature");
            continue;
        }
        buffer[bytes_read] = '\0';

        int temp = atoi(buffer);
        if (temp < 0) {
            perror("Invalid temperature");
            continue;
        }

        if (temp > TEMP_THRESHOLD_HIGH) {
            fan_state = FAN_HIGH;
        } else if (temp > TEMP_THRESHOLD_MEDIUM) {
            fan_state = FAN_MEDIUM;
        } else if (temp > TEMP_THRESHOLD_LOW) {
            fan_state = FAN_LOW;
        } else {
            fan_state = FAN_OFF;
        }

        if (fan_state > max_state) {
            fan_state = max_state;
        }

        if (temp != prev_temp) {
            char log_message[100];
            time_t now = time(NULL);
            strftime(log_message, sizeof(log_message), "%Y-%m-%d %H:%M:%S", localtime(&now));
            sprintf(log_message + strlen(log_message), " Fan speed: %d\n", fan_state);
            write(log_fd, log_message, strlen(log_message));
        }

        prev_temp = temp;

        write(fan_fd, &fan_state, sizeof(fan_state));
    }

    close(temp_fd);
    close(fan_fd);
    close(log_fd);

    return EXIT_SUCCESS;
}

