#define TARGET_TEMP 50
#define KP 1.0
#define KI 0.1
#define KD 0.01
#define SPI_SPEED 500000
#define MAX31855_FAULT_OPEN_CIRCUIT 0x01
#define MAX31855_FAULT_SHORT_TO_GND 0x02
#define MAX31855_FAULT_SHORT_TO_VCC 0x04

volatile sig_atomic_t stop = 0;

void signal_handler(int signum) {
    stop = 1;
}

int main() {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return EXIT_FAILURE;
    }

    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    int spi_fd = spiOpen(0, SPI_SPEED, 0);
    if (spi_fd < 0) {
        fprintf(stderr, "SPI open failed\n");
        gpioTerminate();
        return EXIT_FAILURE;
    }

    int heater_pin = 18;
    gpioSetMode(heater_pin, PI_OUTPUT);
    gpioPWM(heater_pin, 0);

    FILE *log_file = fopen("heater_log.txt", "w");
    if (log_file == NULL) {
        fprintf(stderr, "Log file open failed\n");
        spiClose(spi_fd);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    double integral = 0.0;
    double last_error = 0.0;

    while (!stop) {
        uint8_t tx[4] = {0x00, 0x00, 0x00, 0x00};
        uint8_t rx[4];

        if (spiXfer(spi_fd, tx, rx, 4) != 4) {
            fprintf(log_file, "SPI transfer failed\n");
            break;
        }

        int16_t temp = (rx[1] << 8) | rx[2];
        double error = TARGET_TEMP - temp;

        if (error > 100 || error < 0) {
            fprintf(log_file, "Temperature out of range: %d\n", temp);
            break;
        }

        integral += error;
        double derivative = error - last_error;
        last_error = error;

        double output = KP * error + KI * integral + KD * derivative;

        if (output > 100) {
            output = 100;
        } else if (output < 0) {
            output = 0;
        }

        gpioPWM(heater_pin, (int)(output * 1023 / 100));

        fprintf(log_file, "Temperature: %d, PWM: %d, PID: %f\n", temp, (int)(output * 1023 / 100), output);

        sleep(1);
    }

    fclose(log_file);
    spiClose(spi_fd);
    gpioTerminate();

    return EXIT_SUCCESS;
}

