#define FAN_PIN 18
#define TEMP_FILE "/sys/class/thermal/thermal_zone0/temp"
#define LOG_FILE "cooling_log.csv"
#define MIN_TEMP 40000
#define MAX_TEMP 70000
#define MIN_DUTY 0
#define MAX_DUTY 100

volatile sig_atomic_t stop = 0;

void signal_handler(int signum) {
    stop = 1;
}

int main() {
    FILE *temp_file, *log_file;
    char buffer[256];
    int temp, duty;
    struct timespec ts = {5, 0};

    if (gpioInitialise() < 0) {
        fprintf(stderr, "Failed to initialize pigpio\n");
        return EXIT_FAILURE;
    }

    if ((log_file = fopen(LOG_FILE, "w")) == NULL) {
        fprintf(stderr, "Failed to open log file\n");
        gpioTerminate();
        return EXIT_FAILURE;
    }

    fprintf(log_file, "Timestamp, Temperature (°C), PWM Duty Cycle (%)\n");

    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    if (gpioSetPWMfrequency(FAN_PIN, 25000) < 0) {
        fprintf(stderr, "Failed to set PWM frequency\n");
        fclose(log_file);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    if (gpioSetPWMrange(FAN_PIN, 100) < 0) {
        fprintf(stderr, "Failed to set PWM range\n");
        fclose(log_file);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    while (!stop) {
        if ((temp_file = fopen(TEMP_FILE, "r")) == NULL) {
            fprintf(stderr, "Failed to open temperature file\n");
            fclose(log_file);
            gpioTerminate();
            return EXIT_FAILURE;
        }

        if (fgets(buffer, sizeof(buffer), temp_file) == NULL) {
            fprintf(stderr, "Failed to read temperature\n");
            fclose(temp_file);
            fclose(log_file);
            gpioTerminate();
            return EXIT_FAILURE;
        }

        fclose(temp_file);

        temp = atoi(buffer);

        if (temp < MIN_TEMP) {
            duty = MIN_DUTY;
        } else if (temp > MAX_TEMP) {
            duty = MAX_DUTY;
        } else {
            duty = (temp - MIN_TEMP) / (MAX_TEMP - MIN_TEMP) * (MAX_DUTY - MIN_DUTY) + MIN_DUTY;
        }

        if (gpioSetPWMdutycycle(FAN_PIN, duty) < 0) {
            fprintf(stderr, "Failed to set PWM duty cycle\n");
            fclose(log_file);
            gpioTerminate();
            return EXIT_FAILURE;
        }

        clock_nanosleep(CLOCK_REALTIME, 0, &ts, NULL);

        time_t now = time(NULL);
        struct tm *t = localtime(&now);

        fprintf(log_file, "%04d-%02d-%02d %02d:%02d:%02d, %d, %d\n",
                t->tm_year + 1900, t->tm_mon + 1, t->tm_mday,
                t->tm_hour, t->tm_min, t->tm_sec, temp / 1000, duty);
    }

    gpioSetPWMdutycycle(FAN_PIN, 0);
    fclose(log_file);
    gpioTerminate();

    return EXIT_SUCCESS;
}

#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <pigpio.h>

#define SLF3S_1300F_CMD 0x3608
#define SLF3S_1300F_BYTES 3
#define SLF3S_1300F_CRC_POLYNOMIAL 0x31
#define SLF3S_1300F_CRC_INIT 0xFF
#define SLF3S_1300F_CRC_XOROUT 0xFF

volatile sig_atomic_t stop = 0;

void signal_handler(int signum) {
    stop = 1;
}

uint8_t crc8(const uint8_t *data, size_t len) {
    uint8_t crc = SLF3S_1300F_CRC_INIT;
    for (size_t i = 0; i < len; ++i) {
        crc ^= data[i];
        for (int j = 0; j < 8; ++j) {
            if (crc & 0x80) {
                crc = (crc << 1) ^ SLF3S_1300F_CRC_POLYNOMIAL;
            } else {
                crc <<= 1;
            }
        }
    }
    return crc ^ SLF3S_1300F_CRC_XOROUT;
}

int main() {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Failed to initialize pigpio\n");
        return EXIT_FAILURE;
    }

    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    int fd1 = gpioI2COpen(1, 0x08, 0);
    int fd2 = gpioI2COpen(1, 0x09, 0);

    FILE *log_file = fopen("flow_log.txt", "a");
    if (!log_file) {
        fprintf(stderr, "Failed to open log file\n");
        gpioTerminate();
        return EXIT_FAILURE;
    }

    while (!stop) {
        uint8_t buf1[SLF3S_1300F_BYTES];
        uint8_t buf2[SLF3S_1300F_BYTES];

        for (int i = 0; i < 3; ++i) {
            if (gpioI2CReadByteData(fd1, SLF3S_1300F_CMD, buf1) == SLF3S_1300F_BYTES &&
                gpioI2CReadByteData(fd2, SLF3S_1300F_CMD, buf2) == SLF3S_1300F_BYTES &&
                crc8(buf1, SLF3S_1300F_BYTES - 1) == buf1[2] &&
                crc8(buf2, SLF3S_1300F_BYTES - 1) == buf2[2]) {
                break;
            }
            gpioDelay(1000000); // Wait 1 second before retrying
        }

        if (stop) break;

        time_t now = time(NULL);
        struct tm *t = localtime(&now);
        char timestamp[20];
        strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", t);

        float flow1 = (buf1[0] << 8 | buf1[1]) * 0.01;
        float flow2 = (buf2[0] << 8 | buf2[1]) * 0.01;

        fprintf(log_file, "%s,%f,%f\n", timestamp, flow1, flow2);

        fflush(log_file);
        gpioDelay(1000000); // Wait 1 second before next measurement
    }

    fclose(log_file);
    gpioI2CClose(fd1);
    gpioI2CClose(fd2);
    gpioTerminate();

    return EXIT_SUCCESS;
}

