        fprintf(stderr, "Failed to open log file\n");
        gpioTerminate();
        return EXIT_FAILURE;
    }

    gpioSetMode(SENSOR_A, PI_INPUT);
    gpioSetMode(SENSOR_B, PI_INPUT);

    gpioSetPullUpDown(SENSOR_A, PI_PUD_UP);
    gpioSetPullUpDown(SENSOR_B, PI_PUD_UP);

    int last_a = 0;
    int last_b = 0;
    int state = 0;
    int position = 0;

    while (!stop) {
        int a = gpioRead(SENSOR_A);
        int b = gpioRead(SENSOR_B);

        if (a != last_a || b != last_b) {
            if (a == 1 && b == 0) {
                state = (state + 1) % 4;
            } else if (a == 0 && b == 1) {
                state = (state + 3) % 4;
            }

            switch (state) {
                case 0:
                    position = (position + 90) % 360;
                    break;
                case 1:
                    position = (position + 45) % 360;
                    break;
                case 2:
                    position = (position + 0) % 360;
                    break;
                case 3:
                    position = (position + 315) % 360;
                    break;
            }

            fprintf(log_file, "%d: %d\n", gpioTick(), position);
            fflush(log_file);

            last_a = a;
            last_b = b;
