    gpioTerminate();

    return EXIT_SUCCESS;
}

#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <unistd.h>
#include <signal.h>
#include <fcntl.h>
#include <sys/ioctl.h>
#include <linux/i2c-dev.h>
#include <libgpiod.h>

#define ADPD144RI_ADDRESS 0x39
#define ADPD144RI_FIFO_DATA 0x60
#define GPIO_TRIGGER 17
#define SAMPLE_INTERVAL 100 // ms
#define IR_THRESHOLD 2000

static int i2c_fd = -1;
static int gpio_fd = -1;
static FILE *log_file = NULL;

void cleanup() {
    if (i2c_fd != -1) close(i2c_fd);
    if (gpio_fd != -1) gpiod_line_release(gpio_fd);
    if (log_file != NULL) fclose(log_file);
}

void sig_handler(int signum) {
    cleanup();
    exit(signum);
}

int main() {
    struct sigaction sigact;
    sigact.sa_handler = sig_handler;
    sigemptyset(&sigact.sa_mask);
    sigact.sa_flags = 0;
    sigaction(SIGINT, &sigact, NULL);
    sigaction(SIGTERM, &sigact, NULL);

    if ((i2c_fd = open("/dev/i2c-1", O_RDWR)) < 0) {
        perror("Failed to open I2C bus");
        return 1;
    }

    if (ioctl(i2c_fd, I2C_SLAVE, ADPD144RI_ADDRESS) < 0) {
        perror("Failed to acquire ADPD144RI I2C slave access");
        return 1;
    }

    if ((gpio_fd = gpiod_line_request_output("gpiochip0", GPIO_TRIGGER, "trigger", 0)) < 0) {
        perror("Failed to request GPIO line");
        return 1;
    }

    if ((log_file = fopen("adpd144ri_log.txt", "w")) == NULL) {
        perror("Failed to open log file");
        return 1;
    }

    atexit(cleanup);

    while (1) {
        uint16_t red, ir;
        if (read(i2c_fd, &red, 2) != 2 || read(i2c_fd, &ir, 2) != 2) {
            perror("Failed to read from ADPD144RI");
            return 1;
        }

        if (ir > IR_THRESHOLD) {
            gpiod_line_set_value(gpio_fd, 1);
        } else {
            gpiod_line_set_value(gpio_fd, 0);
        }

        fprintf(log_file, "%ld,%u,%u\n", time(NULL), red, ir);

        usleep(SAMPLE_INTERVAL * 1000);
    }

    return 0;
}

