#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <pthread.h>
#include <signal.h>
#include <time.h>
#include <pigpio.h>

#define GPIO_PIN 18
#define LOG_FILE "rpm_log.txt"
#define SAMPLE_INTERVAL 1.0 // seconds

volatile sig_atomic_t running = 1;
volatile sig_atomic_t pulse_count = 0;
pthread_mutex_t pulse_mutex = PTHREAD_MUTEX_INITIALIZER;
struct timespec last_time = {0, 0};

void signal_handler(int signum) {
    running = 0;
}

void edge_detected(int gpio, int level, uint32_t tick) {
    pthread_mutex_lock(&pulse_mutex);
    if (level == 1) {
        pulse_count++;
    }
    pthread_mutex_unlock(&pulse_mutex);
}

void log_rpm(double rpm) {
    FILE *file = fopen(LOG_FILE, "a");
    if (file == NULL) {
        fprintf(stderr, "Failed to open log file\n");
        return;
    }
    struct timespec now;
    clock_gettime(CLOCK_REALTIME, &now);
    fprintf(file, "%ld.%09ld %0.2f\n", now.tv_sec, now.tv_nsec, rpm);
    fflush(file);
    fclose(file);
}

int main() {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Failed to initialize pigpio\n");
        return EXIT_FAILURE;
    }

    struct sigaction action;
    memset(&action, 0, sizeof(struct sigaction));
    action.sa_handler = signal_handler;
    sigaction(SIGINT, &action, NULL);
    sigaction(SIGTERM, &action, NULL);

    if (gpioSetISRFunc(GPIO_PIN, 0, edge_detected) < 0) {
        fprintf(stderr, "Failed to set ISR function\n");
        gpioTerminate();
        return EXIT_FAILURE;
    }

    FILE *file = fopen(LOG_FILE, "w");
    if (file == NULL) {
        fprintf(stderr, "Failed to open log file\n");
        gpioTerminate();
        return EXIT_FAILURE;
    }
    fclose(file);

    struct timespec start_time, current_time;
    clock_gettime(CLOCK_REALTIME, &start_time);
    double rpm = 0.0;

    while (running) {
        clock_gettime(CLOCK_REALTIME, &current_time);
        double elapsed = (current_time.tv_sec - start_time.tv_sec) +
                         (current_time.tv_nsec - start_time.tv_nsec) / 1e9;
        if (elapsed >= SAMPLE_INTERVAL) {
            pthread_mutex_lock(&pulse_mutex);
            int count = pulse_count;
            pulse_count = 0;
            pthread_mutex_unlock(&pulse_mutex);
            rpm = count / SAMPLE_INTERVAL;
            log_rpm(rpm);
            start_time = current_time;
        }
        usleep(1000);
    }

    gpioSetISRFunc(GPIO_PIN, 0, NULL);
    gpioTerminate();
    pthread_mutex_destroy(&pulse_mutex);
    return EXIT_SUCCESS;
}

#include <stdio.h>
