    unsigned char buffer[2];
    struct gpiod_chip *chip;
    struct gpiod_line *line;
    FILE *log_file;

    // Open the I2C bus
    if ((file = open(I2C_BUS, O_RDWR)) < 0) {
        perror("Failed to open the I2C bus");
        return 1;
    }

    // Set the I2C address
    if (ioctl(file, I2C_SLAVE, I2C_ADDRESS) < 0) {
        perror("Failed to set the I2C address");
        return 1;
    }

    // Read the PART_ID register to verify the sensor is present
    if (write(file, &PART_ID, 1) != 1) {
        perror("Failed to write to the I2C bus");
        return 1;
    }

    if (read(file, buffer, 1) != 1) {
        perror("Failed to read from the I2C bus");
        return 1;
    }

    if (buffer[0] != I2C_ADDRESS) {
        printf("Sensor not found\n");
        return 1;
    }

    // Initialize the GPIO chip
    if ((chip = gpiod_chip_open_by_name("gpiochip0")) == NULL) {
        perror("Failed to open the GPIO chip");
        return 1;
    }

    // Request the GPIO line
    if ((line = gpiod_chip_get_line(chip, GPIO_PIN)) == NULL) {
        perror("Failed to get the GPIO line");
        return 1;
    }

    // Set the GPIO line as an output
    if (gpiod_line_request_output(line, "adpd144ri", 0) < 0) {
        perror("Failed to set the GPIO line as an output");
        return 1;
    }

    // Open the log file
    if ((log_file = fopen("adpd144ri_log.txt", "w")) == NULL) {
        perror("Failed to open the log file");
        return 1;
    }

    // Main loop
    while (1) {
        // Read the FIFO data registers
        if (write(file, &FIFO_DATA, 1) != 1) {
            perror("Failed to write to the I2C bus");
            break;
        }

        if (read(file, buffer, 2) != 2) {
            perror("Failed to read from the I2C bus");
            break;
        }

        // Check the IR reading
        if (buffer[1] > IR_THRESHOLD) {
            // Trigger the LED
            gpiod_line_set_value(line, 1);
        } else {
            gpiod_line_set_value(line, 0);
        }

        // Log the readings
        fprintf(log_file, "%ld,%d,%d\n", time(NULL), buffer[0], buffer[1]);

