#include <libgpiod.h>

#define INPUT_PIN 17
#define GAIN_PIN 18
#define LOG_FILE "audio_log.txt"
#define SAMPLE_INTERVAL 10000 // 10 ms

static struct gpiod_chip *chip;
static struct gpiod_line *input_line;
static struct gpiod_line *gain_line;
static int running = 1;

void cleanup() {
    gpiod_line_release(input_line);
    gpiod_chip_close(chip);
    printf("Cleanup complete.\n");
}

void sig_handler(int signum) {
    running = 0;
}

int main() {
    struct sigaction action;
    action.sa_handler = sig_handler;
    sigemptyset(&action.sa_mask);
    action.sa_flags = 0;
    sigaction(SIGINT, &action, NULL);
    sigaction(SIGTERM, &action, NULL);

    atexit(cleanup);

    chip = gpiod_chip_open("/dev/gpiochip0");
    if (!chip) {
        fprintf(stderr, "Failed to open GPIO chip\n");
        return EXIT_FAILURE;
    }

    input_line = gpiod_chip_get_line(chip, INPUT_PIN);
    if (!input_line) {
        fprintf(stderr, "Failed to get input line\n");
        return EXIT_FAILURE;
    }

    gain_line = gpiod_chip_get_line(chip, GAIN_PIN);
    if (!gain_line) {
        fprintf(stderr, "Failed to get gain line\n");
        return EXIT_FAILURE;
    }

    if (gpiod_line_request_input(input_line, "audio_input") < 0) {
        fprintf(stderr, "Failed to request input line\n");
        return EXIT_FAILURE;
    }

    if (gpiod_line_request_output(gain_line, "audio_gain", 0) < 0) {
        fprintf(stderr, "Failed to request output line\n");
        return EXIT_FAILURE;
    }

    printf("Startup complete. Press Ctrl+C to exit.\n");

    FILE *log_file = fopen(LOG_FILE, "w");
    if (!log_file) {
        fprintf(stderr, "Failed to open log file\n");
        return EXIT_FAILURE;
    }

    while (running) {
        struct timespec sleep_time = {0, SAMPLE_INTERVAL};
        nanosleep(&sleep_time, NULL);

        int value = gpiod_line_get_value(input_line);
        if (value < 0) {
            fprintf(stderr, "Failed to read input line\n");
            return EXIT_FAILURE;
        }

        if (value) {
            struct timespec now;
            clock_gettime(CLOCK_REALTIME, &now);
            char timestamp[20];
            strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", localtime(&now.tv_sec));
            fprintf(log_file, "%s 1\n", timestamp);
            fflush(log_file);
        }
    }

    fclose(log_file);
    return EXIT_SUCCESS;
}

#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <pigpio.h>

#define SLF3S_ADDRESS 0x36
#define SLF3S_CMD 0x3608
#define SLF3S_CRC_POLY 0x31
#define SLF3S_CRC_INIT 0xFF
#define FLOW_LOG_FILE "flow_log.csv"

static int i2c_handle = -1;
static FILE *log_file = NULL;

void log_error(const char *msg) {
    fprintf(stderr, "%s\n", msg);
}

void log_flow_rate(double flow_rate) {
    time_t now = time(NULL);
    struct tm *t = localtime(&now);
    char timestamp[20];
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", t);
    fprintf(log_file, "%s,%.2f\n", timestamp, flow_rate);
    fflush(log_file);
}

uint8_t crc8(uint8_t *data, size_t len) {
    uint8_t crc = SLF3S_CRC_INIT;
    for (size_t i = 0; i < len; i++) {
        crc ^= data[i];
        for (int j = 0; j < 8; j++) {
            if (crc & 0x80) {
                crc = (crc << 1) ^ SLF3S_CRC_POLY;
            } else {
                crc <<= 1;
            }
        }
    }
    return crc;
}

void handle_sigint(int signum) {
    if (i2c_handle != -1) {
        gpio_i2c_close(i2c_handle);
    }
    if (log_file != NULL) {
        fclose(log_file);
    }
    exit(0);
}

int main() {
    if (gpioInitialise() < 0) {
        log_error("Failed to initialize pigpio");
        return 1;
    }

    signal(SIGINT, handle_sigint);

    i2c_handle = gpio_i2c_open(1, SLF3S_ADDRESS);
    if (i2c_handle < 0) {
        log_error("Failed to open I2C handle");
        goto cleanup;
    }

    log_file = fopen(FLOW_LOG_FILE, "a");
    if (log_file == NULL) {
        log_error("Failed to open log file");
        goto cleanup;
    }

    uint8_t cmd[] = {SLF3S_CMD >> 8, SLF3S_CMD & 0xFF};
    if (gpio_i2c_write(i2c_handle, cmd, sizeof(cmd)) != sizeof(cmd)) {
        log_error("Failed to write command to sensor");
        goto cleanup;
    }

    while (1) {
        uint8_t buffer[3];
        if (gpio_i2c_read(i2c_handle, buffer, sizeof(buffer)) != sizeof(buffer)) {
            log_error("Failed to read from sensor");
            continue;
        }

        uint16_t raw_flow = (buffer[0] << 8) | buffer[1];
        uint8_t crc = buffer[2];
        if (crc8(buffer, sizeof(buffer) - 1) != crc) {
            log_error("CRC check failed");
            continue;
        }

        double flow_rate = (double)raw_flow / 1000.0;
        log_flow_rate(flow_rate);
    }

cleanup:
    if (i2c_handle != -1) {
        gpio_i2c_close(i2c_handle);
    }
    if (log_file != NULL) {
        fclose(log_file);
    }
    gpioTerminate();
    return 0;
}

#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <pigpio.h>

#define IAQ_MIN 0
#define IAQ_MAX 100
#define TVOC_DIVISOR 10.0
#define ECO2_DIVISOR 50.0
#define ECO2_BASE 400

void log_data(FILE *log_file, uint16_t tvoc, uint16_t eco2, float iaq) {
    time_t now = time(NULL);
    struct tm *t = localtime(&now);
    fprintf(log_file, "%d-%02d-%02d %02d:%02d:%02d, IAQ: %.2f, TVOC: %d, eCO2: %d\n",
            t->tm_year + 1900, t->tm_mon + 1, t->tm_mday, t->tm_hour, t->tm_min, t->tm_sec, iaq, tvoc, eco2);
}

void handle_sigint(int signum) {
    printf("SIGINT received, exiting...\n");
    gpioTerminate();
    exit(0);
}

int main() {
    FILE *log_file = fopen("air_quality_log.csv", "w");
    if (!log_file) {
        fprintf(stderr, "Failed to open log file\n");
        return 1;
    }

    if (gpioInitialise() < 0) {
        fprintf(stderr, "Failed to initialize pigpio\n");
        fclose(log_file);
        return 1;
    }

    signal(SIGINT, handle_sigint);

    int i2c_handle = gpioI2COpen(1, 0x70);
    if (i2c_handle < 0) {
        fprintf(stderr, "Failed to open I2C bus\n");
        gpioTerminate();
        fclose(log_file);
        return 1;
    }

    uint8_t buffer[7];
    while (1) {
        int result = gpioI2CReadDevice(i2c_handle, buffer, sizeof(buffer));
        if (result < 0) {
            fprintf(stderr, "Failed to read from sensor\n");
            break;
        }

        uint16_t tvoc = (buffer[1] << 8) | buffer[2];
        uint16_t eco2 = (buffer[5] << 8) | buffer[6];

        float iaq = 100 - (tvoc / TVOC_DIVISOR) - ((eco2 - ECO2_BASE) / ECO2_DIVISOR);
        iaq = iaq < IAQ_MIN ? IAQ_MIN : (iaq > IAQ_MAX ? IAQ_MAX : iaq);

        log_data(log_file, tvoc, eco2, iaq);

        sleep(5);
    }

    gpioI2CClose(i2c_handle);
    gpioTerminate();
    fclose(log_file);

    return 0;
}

