#define GPIO_CHIP_NAME "gpiochip0"
#define GPIO_LINE_NAME "17"
#define GPIO_LINE_CONSUMER "ttp223_tamper"
#define POLL_INTERVAL_MS 100
#define TOUCH_THRESHOLD_S 5

static bool running = true;
static struct gpiod_chip *chip;
static struct gpiod_line *line;
static struct timespec last_touch_time;

static void handle_signal(int signum) {
    running = false;
}

static void cleanup() {
    if (line) {
        gpiod_line_release(line);
    }
    if (chip) {
        gpiod_chip_close(chip);
    }
}

static void check_error(int error, const char *message) {
    if (error < 0) {
        fprintf(stderr, "%s: %s\n", message, strerror(-error));
        cleanup();
        exit(EXIT_FAILURE);
    }
}

static void check_sensor() {
    int error;
    enum gpiod_line_level level;

    error = gpiod_line_get_level(line, &level);
    check_error(error, "Failed to read sensor");

    if (level == GPIO_LEVEL_HIGH) {
        struct timespec now;
        clock_gettime(CLOCK_MONOTONIC, &now);

        if (last_touch_time.tv_sec == 0 || now.tv_sec - last_touch_time.tv_sec > TOUCH_THRESHOLD_S) {
            printf("Intrusion alert!\n");
            last_touch_time = now;
        }
    } else {
        last_touch_time.tv_sec = 0;
    }
}

int main() {
    int error;

    error = gpiod_chip_open_by_name(GPIO_CHIP_NAME, &chip);
    check_error(error, "Failed to open GPIO chip");

    error = gpiod_chip_get_line(chip, GPIO_LINE_NAME, &line);
    check_error(error, "Failed to get GPIO line");

    error = gpiod_line_request_input(line, GPIO_LINE_CONSUMER);
    check_error(error, "Failed to request GPIO line as input");

    signal(SIGINT, handle_signal);
    signal(SIGTERM, handle_signal);

    while (running) {
        check_sensor();

        struct timespec sleep_time = {0, POLL_INTERVAL_MS * 1000000};
        nanosleep(&sleep_time, NULL);
    }

    cleanup();
    return EXIT_SUCCESS;
}

#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <fcntl.h>
#include <unistd.h>
#include <signal.h>
#include <libgpiod.h>

#define I2S_DEVICE "/dev/snd/pcmC0D0c"
#define SAMPLES_PER_FRAME 4
#define LEFT_CHANNEL 17

static int running = 1;

void signal_handler(int signum) {
    running = 0;
}

int main() {
    struct gpiod_chip *chip;
    struct gpiod_line *line;
    int i2s_fd, pcm_fd;
    unsigned int sample;
    unsigned char buffer[4];

    // Set up signal handler
    signal(SIGINT, signal_handler);

    // Open I2S device
    i2s_fd = open(I2S_DEVICE, O_RDONLY);
    if (i2s_fd < 0) {
        perror("Failed to open I2S device");
        return EXIT_FAILURE;
    }

    // Open PCM file
    pcm_fd = open("audio_capture.pcm", O_WRONLY | O_CREAT | O_TRUNC, 0644);
    if (pcm_fd < 0) {
        perror("Failed to open PCM file");
        close(i2s_fd);
        return EXIT_FAILURE;
    }

    // Set up GPIO
    chip = gpiod_chip_open_by_name("gpiochip0");
    if (!chip) {
        perror("Failed to open GPIO chip");
        close(i2s_fd);
        close(pcm_fd);
        return EXIT_FAILURE;
    }

    line = gpiod_chip_get_line(chip, LEFT_CHANNEL);
    if (!line) {
        perror("Failed to get GPIO line");
        gpiod_chip_close(chip);
        close(i2s_fd);
        close(pcm_fd);
        return EXIT_FAILURE;
    }

    // Set GPIO line to output
    if (gpiod_line_request_output(line, "audio_capture", 0) < 0) {
        perror("Failed to set GPIO line to output");
        gpiod_chip_close(chip);
        gpiod_line_release(line);
        close(i2s_fd);
        close(pcm_fd);
        return EXIT_FAILURE;
    }

    // Main loop
    while (running) {
        // Read 4 bytes from I2S device
        if (read(i2s_fd, buffer, sizeof(buffer)) != sizeof(buffer)) {
            perror("Failed to read from I2S device");
            break;
        }

        // Extract 24-bit sample from 32-bit frame
        sample = (buffer[0] << 16) | (buffer[1] << 8) | buffer[2];
        sample >>= 8;

        // Write 16-bit sample to PCM file
        if (write(pcm_fd, &sample, sizeof(sample)) != sizeof(sample)) {
            perror("Failed to write to PCM file");
            break;
        }
    }

    // Clean up
    gpiod_line_release(line);
    gpiod_chip_close(chip);
    close(i2s_fd);
    close(pcm_fd);

    return EXIT_SUCCESS;
}

#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <pigpio.h>

#define FAN_PIN 18
#define FLAME_PIN 4
#define FLAME_DETECTED 0
#define FLAME_DURATION_MAX 10000 // 10 seconds
#define FLAME_DURATION_MIN 1000 // 1 second
#define FLAME_DURATION_SCALE 0.5 // 0.5x exponential curve

volatile sig_atomic_t running = 1;
FILE *log_file;

void cleanup() {
    if (log_file) fclose(log_file);
    gpioTerminate();
}

void sig_handler(int signum) {
    running = 0;
}

int main() {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialization failed\n");
        return EXIT_FAILURE;
    }

    signal(SIGINT, sig_handler);
    signal(SIGTERM, sig_handler);

    log_file = fopen("flame_log.txt", "w");
    if (!log_file) {
        fprintf(stderr, "Failed to open log file\n");
        gpioTerminate();
        return EXIT_FAILURE;
    }

    time_t start_time, flame_time;
    int flame_duration = 0;
    int fan_duty_cycle = 0;

    while (running) {
        if (gpioRead(FLAME_PIN) == FLAME_DETECTED) {
            if (flame_duration == 0) {
                start_time = time(NULL);
                flame_time = start_time;
                fprintf(log_file, "%ld: Flame detected\n", start_time);
                fflush(log_file);
            }
            flame_duration = time(NULL) - flame_time;
            fan_duty_cycle = (int)((1 - exp(-FLAME_DURATION_SCALE * flame_duration)) * 80);
            if (fan_duty_cycle > 80) fan_duty_cycle = 80;
            gpioHardwarePWM(FAN_PIN, 100, fan_duty_cycle * 1000);
            flame_time = time(NULL);
        } else {
            if (flame_duration > 0) {
                fprintf(log_file, "%ld: Flame ended after %d ms\n", time(NULL), flame_duration);
                fflush(log_file);
                flame_duration = 0;
                gpioHardwarePWM(FAN_PIN, 0, 0);
            }
        }

        if (flame_duration > FLAME_DURATION_MAX) {
            fprintf(log_file, "%ld: Flame duration exceeded maximum limit\n", time(NULL));
            fflush(log_file);
            flame_duration = 0;
            gpioHardwarePWM(FAN_PIN, 0, 0);
        }

        if (flame_duration > 0 && time(NULL) - start_time > FLAME_DURATION_MIN) {
            fprintf(log_file, "%ld: Shutdown due to inactivity\n", time(NULL));
            fflush(log_file);
            running = 0;
            gpioHardwarePWM(FAN_PIN, 0, 0);
        }

        usleep(50000); // 50 ms
    }

    cleanup();
    return EXIT_SUCCESS;
}

