    }

    if (gpioSetMode(GPIO_DATA_READY, PI_INPUT) < 0) {
        fprintf(stderr, "Failed to set GPIO mode\n");
        goto cleanup;
    }

    if (gpioSetAlertFuncEx(GPIO_DATA_READY, NULL, NULL) < 0) {
        fprintf(stderr, "Failed to set GPIO alert function\n");
        goto cleanup;
    }

    while (running) {
        gpioTrigger(0, 0, GPIO_TRIGGER, 0);

        while (gpioWaitForAlert(0) < 0) {
            if (!running) {
                break;
            }
        }

        uint8_t buffer[FRAME_SIZE];
        if (spiXfer(0, NULL, buffer, FRAME_SIZE) < 0) {
            fprintf(stderr, "Failed to read frame\n");
            break;
        }

        uint64_t timestamp = time(NULL);
        fwrite(&timestamp, sizeof(uint64_t), 1, log_file);
        fwrite(buffer, FRAME_SIZE, 1, log_file);
    }

cleanup:
    fclose(log_file);
    gpioTerminate();
    return EXIT_SUCCESS;
}

