#include <pigpio.h>

#define OPT3001_ADDRESS 0x44
#define OPT3001_CONFIGURATION 0x01
#define OPT3001_RESULT 0x00
#define OPT3001_CONVERSION_TIME 100 // ms

volatile sig_atomic_t stop = 0;

void signal_handler(int signum) {
    stop = 1;
}

int main() {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Failed to initialize pigpio library\n");
        return EXIT_FAILURE;
    }

    int i2c_handle = i2cOpen(1, OPT3001_ADDRESS, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Failed to open I2C bus 1\n");
        gpioTerminate();
        return EXIT_FAILURE;
    }

    FILE *file = fopen("light_data.txt", "w");
    if (!file) {
        fprintf(stderr, "Failed to open light_data.txt\n");
        i2cClose(i2c_handle);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    struct sigaction action;
    memset(&action, 0, sizeof(struct sigaction));
    action.sa_handler = signal_handler;
    sigaction(SIGINT, &action, NULL);
    sigaction(SIGTERM, &action, NULL);

    uint16_t config = 0x10C0; // 100 ms conversion time, automatic full-scale range
    if (i2cWriteByteData(i2c_handle, OPT3001_CONFIGURATION, config) < 0) {
        fprintf(stderr, "Failed to write configuration to OPT3001\n");
        fclose(file);
        i2cClose(i2c_handle);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    while (!stop) {
        uint16_t result;
        if (i2cReadByteData(i2c_handle, OPT3001_RESULT, &result) < 0) {
            fprintf(stderr, "Failed to read result from OPT3001\n");
            break;
        }

        int exponent = (result >> 12) & 0x000F;
        int mantissa = result & 0x0FFF;
        float lux = 0.01 * pow(2, exponent) * mantissa;

        time_t now = time(NULL);
        struct tm *timeinfo = localtime(&now);
        char timestamp[20];
        strftime(timestamp, sizeof(timestamp), "%Y-%m-%dT%H:%M:%S", timeinfo);

        fprintf(file, "%s, %.2f\n", timestamp, lux);

        usleep(1000000 * OPT3001_CONVERSION_TIME);
    }

    fclose(file);
    i2cClose(i2c_handle);
    gpioTerminate();
    return EXIT_SUCCESS;
}

#include <stdio.h>
