#include <gpiod.h>

volatile sig_atomic_t stop = 0;

void signal_handler(int signum) {
    stop = 1;
}

int main() {
    struct gpiod_chip *chip;
    struct gpiod_line_request *line_request;
    struct gpiod_line_settings *line_settings;
    struct gpiod_line *line;
    int ret;

    // Open the GPIO chip
    chip = gpiod_chip_open("/dev/gpiochip0");
    if (!chip) {
        fprintf(stderr, "Failed to open GPIO chip\n");
        return EXIT_FAILURE;
    }

    // Request lines
    line_request = gpiod_chip_request_lines(chip, "flame_detect", "flame_detect", 1);
    if (!line_request) {
        fprintf(stderr, "Failed to request lines\n");
        gpiod_chip_close(chip);
        return EXIT_FAILURE;
    }

    // Configure lines
    line_settings = gpiod_line_settings_new();
    gpiod_line_settings_set_direction(line_settings, GPIOD_LINE_DIRECTION_INPUT);
    gpiod_line_settings_set_bias(line_settings, GPIOD_LINE_BIAS_PULL_UP);
    ret = gpiod_chip_set_line_settings(chip, line_request, line_settings);
    if (ret < 0) {
        fprintf(stderr, "Failed to set line settings\n");
        gpiod_line_settings_free(line_settings);
        gpiod_chip_release_lines(chip, line_request);
        gpiod_chip_close(chip);
        return EXIT_FAILURE;
    }

    // Get the line
    line = gpiod_line_request_get_line(line_request, 0);
    if (!line) {
        fprintf(stderr, "Failed to get line\n");
        gpiod_line_settings_free(line_settings);
        gpiod_chip_release_lines(chip, line_request);
        gpiod_chip_close(chip);
        return EXIT_FAILURE;
    }

    // Set up signal handler
    signal(SIGINT, signal_handler);

    // Main loop
    while (!stop) {
        struct timespec ts;
        time_t now;
        struct tm *timeinfo;
        char buffer[80];

        // Get current time
        now = time(NULL);
        timeinfo = localtime(&now);
        strftime(buffer, sizeof(buffer), "%Y-%m-%d %H:%M:%S", timeinfo);

        // Read the line
        int value = gpiod_line_get_value(line);
        if (value < 0) {
            fprintf(stderr, "Failed to read line\n");
            break;
        }

        // Log the flame detection status
        printf("%s Flame Detected: %s\n", buffer, value ? "NO" : "YES");

        // Sleep for 1 second
        ts.tv_sec = 1;
        ts.tv_nsec = 0;
        nanosleep(&ts, NULL);
    }

    // Clean up
    gpiod_line_settings_free(line_settings);
    gpiod_chip_release_lines(chip, line_request);
    gpiod_chip_close(chip);

    return EXIT_SUCCESS;
}

