        ret = gpioSetMode(channel + 2, PI_INPUT);
        if (ret < 0) {
            fprintf(stderr, "gpioSetMode failed for channel %d: %d\n", channel + 1, ret);
            gpioTerminate();
            return 1;
        }

        ret = gpioSetPullUpDown(channel + 2, PI_PUD_DOWN);
