            fprintf(stderr, "gpioSetPullUpDown failed for channel %d: %d\n", channel + 1, ret);
            gpioTerminate();
            return 1;
        }
    }

    printf("Sampling started...\n");

    while (1) {
        for (channel = 0; channel < NUM_CHANNELS; channel++) {
            state[channel] = gpioRead(channel + 2);
        }

        printf("[%+ld ms] ", gpioTick() / 1000);

        for (channel = 0; channel < NUM_CHANNELS; channel++) {
            printf("CH%d=%d ", channel + 1, state[channel]);
        }

        printf("\n");

        gpioDelay(POLL_INTERVAL);
    }

    gpioTerminate();
    return 0;
