static struct gpiod_line *gpio_line;
static FILE *log_file;
static bool running = true;

static uint8_t crc8(uint8_t *data, size_t len) {
    uint8_t crc = 0xFF;
    for (size_t i = 0; i < len; i++) {
        crc ^= data[i];
        for (int j = 0; j < 8; j++) {
            if (crc & 0x80) {
                crc = (crc << 1) ^ 0x31;
            } else {
                crc <<= 1;
            }
        }
    }
    return crc;
}

static void read_sensor(int i2c_fd, uint8_t address) {
    uint8_t buffer[9];
    if (write(i2c_fd, &address, 1) != 1 || read(i2c_fd, buffer, 9) != 9) {
        fprintf(stderr, "I2C read error\n");
        return;
    }
    if (buffer[8] != crc8(buffer, 8)) {
        fprintf(stderr, "CRC error\n");
        return;
    }
    int16_t flow = (buffer[2] << 8) | buffer[1];
    if (flow < 0) {
        flow += 65536;
    }
    float flow_rate = flow * FLOW_SCALE_FACTOR;
    fprintf(log_file, "%f\n", flow_rate);
    gpiod_line_set_value(gpio_line, flow_rate < 0.5);
}

static void signal_handler(int signum) {
    running = false;
}

int main() {
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigaction(SIGINT, &sa, NULL);
    sigaction(SIGTERM, &sa, NULL);

    i2c_fd_1 = open(I2C_BUS, O_RDWR);
    if (i2c_fd_1 < 0) {
        perror("Failed to open I2C bus 1");
        return EXIT_FAILURE;
    }
    if (ioctl(i2c_fd_1, I2C_SLAVE, FLOW_SENSOR_ADDRESS_1) < 0) {
        perror("Failed to set I2C address 1");
        return EXIT_FAILURE;
    }
    if (write(i2c_fd_1, "\x08\x3608", 2) != 2) {
        perror("Failed to write to I2C address 1");
        return EXIT_FAILURE;
    }
    usleep(100000);

    i2c_fd_2 = open(I2C_BUS, O_RDWR);
    if (i2c_fd_2 < 0) {
        perror("Failed to open I2C bus 2");
        return EXIT_FAILURE;
    }
    if (ioctl(i2c_fd_2, I2C_SLAVE, FLOW_SENSOR_ADDRESS_2) < 0) {
        perror("Failed to set I2C address 2");
        return EXIT_FAILURE;
    }
    if (write(i2c_fd_2, "\x08\x3608", 2) != 2) {
        perror("Failed to write to I2C address 2");
        return EXIT_FAILURE;
    }
    usleep(100000);

    gpio_chip = gpiod_chip_open_by_name("gpiochip0");
    if (!gpio_chip) {
        perror("Failed to open GPIO chip");
        return EXIT_FAILURE;
    }
    gpio_line = gpiod_chip_get_line(gpio_chip, GPIO_ALARM);
    if (!gpio_line) {
        perror("Failed to get GPIO line");
        return EXIT_FAILURE;
    }
    if (gpiod_line_request_output(gpio_line, "flow_alarm", 0) < 0) {
        perror("Failed to request GPIO line as output");
        return EXIT_FAILURE;
    }

    log_file = fopen(LOG_FILE, "w");
    if (!log_file) {
        perror("Failed to open log file");
        return EXIT_FAILURE;
    }

    while (running) {
        read_sensor(i2c_fd_1, FLOW_SENSOR_ADDRESS_1);
        read_sensor(i2c_fd_2, FLOW_SENSOR_ADDRESS_2);
        fflush(log_file);
        sleep(1);
    }

    fclose(log_file);
    gpiod_line_release(gpio_line);
    gpiod_chip_close(gpio_chip);
    close(i2c_fd_1);
    close(i2c_fd_2);

    return EXIT_SUCCESS;
}

