typedef struct {
    time_t timestamp;
    int reading;
} BufferEntry;

BufferEntry buffer[BUFFER_SIZE];
int buffer_head = 0;
int buffer_count = 0;

void on_sigint(int signum) {
    printf("\nBuffer contents:\n");
    for (int i = 0; i < buffer_count; i++) {
        printf("%ld: %d\n", buffer[(buffer_head + i) % BUFFER_SIZE].timestamp, buffer[(buffer_head + i) % BUFFER_SIZE].reading);
    }
    gpioTerminate();
    exit(0);
}

int main() {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialization failed\n");
        return 1;
    }

    if (gpioSetMode(GPIO, PI_INPUT) < 0) {
        fprintf(stderr, "failed to set GPIO mode\n");
        gpioTerminate();
        return 1;
    }

    if (gpioSetPullUpDown(GPIO, PI_PUD_UP) < 0) {
        fprintf(stderr, "failed to set pull-up resistor\n");
        gpioTerminate();
        return 1;
    }

    signal(SIGINT, on_sigint);

    while (1) {
        int reading = gpioRead(GPIO);
        if (reading == 0) {
            time_t timestamp = time(NULL);
            buffer[buffer_head] = (BufferEntry){timestamp, reading};
            buffer_head = (buffer_head + 1) % BUFFER_SIZE;
            if (buffer_count < BUFFER_SIZE) {
                buffer_count++;
            }
            printf("Obstacle detected!\n");
        }
        usleep(50000); // 50 ms
    }

    gpioTerminate();
