#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <unistd.h>
#include <fcntl.h>
#include <sys/ioctl.h>
#include <linux/i2c-dev.h>
#include <signal.h>
#include <time.h>
#include <sys/time.h>
#include <sys/stat.h>
#include <sys/types.h>
#include <sys/wait.h>
#include <errno.h>

#define I2C_BUS "/dev/i2c-1"
#define I2C_ADDRESS 0x55
#define MODE_CONTROL 0x1D
#define OPERATING_STATUS 0x1B
#define ACCEL_X_MSB 0x2A
#define ACCEL_Y_MSB 0x2C
#define ACCEL_Z_MSB 0x2E
#define SCALE_FACTOR 0.0009765625
#define SAMPLE_INTERVAL 500000 // 500 ms
#define ACTIVE_TIMEOUT 1000000 // 1 second

int i2c_fd;
FILE *csv_fd;

void cleanup(int signum) {
    close(i2c_fd);
    fclose(csv_fd);
    exit(signum);
}

int main() {
    struct sigaction sigact;
    memset(&sigact, 0, sizeof(sigact));
    sigact.sa_handler = cleanup;
    sigaction(SIGINT, &sigact, NULL);
    sigaction(SIGTERM, &sigact, NULL);

    if ((i2c_fd = open(I2C_BUS, O_RDWR)) < 0) {
        perror("Failed to open the i2c bus");
        return 1;
    }

    if (ioctl(i2c_fd, I2C_SLAVE, I2C_ADDRESS) < 0) {
        perror("Failed to acquire bus access and/or talk to slave");
        return 1;
    }

    if (write(i2c_fd, &MODE_CONTROL, 1) != 1 || write(i2c_fd, &0x10, 1) != 1) {
        perror("Failed to write to MODE_CONTROL");
        return 1;
    }

    struct timespec start_time, current_time;
    clock_gettime(CLOCK_REALTIME, &start_time);

    int active = 0;
    while (!active) {
        if (write(i2c_fd, &OPERATING_STATUS, 1) != 1 || read(i2c_fd, &active, 1) != 1) {
            perror("Failed to read from OPERATING_STATUS");
            continue;
        }

        clock_gettime(CLOCK_REALTIME, &current_time);
        if ((current_time.tv_sec - start_time.tv_sec) * 1000 + (current_time.tv_nsec - start_time.tv_nsec) / 1000000 > ACTIVE_TIMEOUT) {
            fprintf(stderr, "Sensor did not become active within the timeout period\n");
            return 1;
        }
    }

    if ((csv_fd = fopen("fan_health.csv", "a")) == NULL) {
        perror("Failed to open CSV file");
        return 1;
    }

    char header[] = "timestamp,x_g,y_g,z_g\n";
    if (fseek(csv_fd, 0, SEEK_END) == 0 && ftell(csv_fd) == 0) {
        fwrite(header, sizeof(char), strlen(header), csv_fd);
    }

    int16_t x, y, z;
    while (1) {
        if (write(i2c_fd, &ACCEL_X_MSB, 1) != 1 || read(i2c_fd, &x, 2) != 2 ||
            write(i2c_fd, &ACCEL_Y_MSB, 1) != 1 || read(i2c_fd, &y, 2) != 2 ||
            write(i2c_fd, &ACCEL_Z_MSB, 1) != 1 || read(i2c_fd, &z, 2) != 2) {
            perror("Failed to read acceleration data");
            continue;
        }

        struct timeval tv;
        gettimeofday(&tv, NULL);
        char timestamp[26];
        strftime(timestamp, sizeof(timestamp), "%Y-%m-%dT%H:%M:%S", localtime(&tv.tv_sec));
        fprintf(csv_fd, "%s.%06ld,%f,%f,%f\n", timestamp, tv.tv_usec, x * SCALE_FACTOR, y * SCALE_FACTOR, z * SCALE_FACTOR);

        struct timespec req, rem;
        req.tv_sec = 0;
        req.tv_nsec = SAMPLE_INTERVAL;
        nanosleep(&req, &rem);
    }

    return 0;
}

