#include <stdio.h>
#include <stdlib.h>
#include <signal.h>
#include <time.h>
#include <pigpio.h>

#define SENSOR_1 17
#define SENSOR_2 18
#define STALL_DURATION 2 // in seconds

int sensor_1_state = 1;
int sensor_2_state = 1;
int stall_detected = 0;
time_t stall_start_time;

void log_stall() {
    FILE *file = fopen("stall_log.txt", "a");
    if (file == NULL) {
        printf("Error opening file!\n");
        return;
    }
    time_t now = time(NULL);
    struct tm *timeinfo = localtime(&now);
    char buffer[80];
    strftime(buffer, sizeof(buffer), "%Y-%m-%d %H:%M:%S", timeinfo);
    fprintf(file, "%s: Stall detected\n", buffer);
    fclose(file);
}

void check_stall() {
    if (sensor_1_state == 0 && sensor_2_state == 0) {
        if (!stall_detected) {
            stall_detected = 1;
            stall_start_time = time(NULL);
        } else {
            time_t current_time = time(NULL);
            if (difftime(current_time, stall_start_time) >= STALL_DURATION) {
                log_stall();
                stall_detected = 0;
            }
        }
    } else {
        stall_detected = 0;
    }
}

void gpio_callback(int gpio, int level, uint32_t tick) {
    if (gpio == SENSOR_1) {
        sensor_1_state = level;
    } else if (gpio == SENSOR_2) {
        sensor_2_state = level;
    }
    check_stall();
}

void cleanup() {
    gpioTerminate();
    printf("Program terminated.\n");
}

int main() {
    if (gpioInitialise() < 0) {
        printf("pigpio initialization failed.\n");
        return 1;
    }

    signal(SIGINT, cleanup);
    signal(SIGTERM, cleanup);

    if (gpioSetMode(SENSOR_1, PI_INPUT) < 0) {
        printf("Failed to set mode for GPIO %d\n", SENSOR_1);
        cleanup();
        return 1;
    }

    if (gpioSetMode(SENSOR_2, PI_INPUT) < 0) {
        printf("Failed to set mode for GPIO %d\n", SENSOR_2);
        cleanup();
        return 1;
    }

    if (gpioSetAlertFunc(SENSOR_1, gpio_callback) < 0) {
        printf("Failed to set alert function for GPIO %d\n", SENSOR_1);
        cleanup();
        return 1;
    }

    if (gpioSetAlertFunc(SENSOR_2, gpio_callback) < 0) {
        printf("Failed to set alert function for GPIO %d\n", SENSOR_2);
        cleanup();
        return 1;
    }

    printf("Monitoring for stalls...\n");
    while (1) {
        gpioSleep(0, 0, 100000); // sleep for 0.1 seconds
    }

    return 0;
}

#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <pigpio.h>

#define SENSOR_ADDRESS 0x0E
#define FILE_NAME "magnetic_log.csv"
#define SAMPLE_INTERVAL 100 // ms

int fd;
FILE *file;

void signal_handler(int signum) {
    printf("Interrupt signal received, closing files and terminating...\n");
    fclose(file);
    gpioTerminate();
    exit(0);
}

int main() {
    struct timespec ts;
    uint8_t buffer[6];
    int16_t raw_values[3];
    float magnetic_field[3];
    uint8_t device_id;
    int ret;

    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    if ((fd = gpio_i2c_open(1, SENSOR_ADDRESS)) < 0) {
        fprintf(stderr, "Failed to open I2C device\n");
        return EXIT_FAILURE;
    }

    if ((file = fopen(FILE_NAME, "a")) == NULL) {
        fprintf(stderr, "Failed to open file\n");
        gpioTerminate();
        return EXIT_FAILURE;
    }

    // Check device ID
    ret = gpio_i2c_read_byte_data(fd, 0x00, &device_id);
    if (ret < 0) {
        fprintf(stderr, "Failed to read device ID\n");
        gpioTerminate();
        return EXIT_FAILURE;
    }
    if (device_id != 0x8D) {
        fprintf(stderr, "Invalid device ID\n");
        gpioTerminate();
        return EXIT_FAILURE;
    }

    // Write CSV header
    fprintf(file, "Timestamp,X,Y,Z\n");

    while (1) {
        // Read raw values
        ret = gpio_i2c_read_i2c_block_data(fd, 0x03, 6, buffer);
        if (ret < 0) {
            fprintf(stderr, "Failed to read raw values\n");
            continue;
        }

        // Convert to 16-bit two's-complement values
        for (int i = 0; i < 3; i++) {
            raw_values[i] = (buffer[2 * i] << 8) | buffer[2 * i + 1];
            if (raw_values[i] & 0x8000) {
                raw_values[i] -= 0x10000;
            }
        }

        // Convert to mT
        magnetic_field[0] = raw_values[0] * 0.15f;
        magnetic_field[1] = raw_values[1] * 0.15f;
        magnetic_field[2] = raw_values[2] * 0.15f;

        // Get current time
        clock_gettime(CLOCK_REALTIME, &ts);

        // Write to CSV
        fprintf(file, "%ld.%09ld,%f,%f,%f\n", ts.tv_sec, ts.tv_nsec, magnetic_field[0], magnetic_field[1], magnetic_field[2]);

        // Wait for next sample
        gpioDelay(SAMPLE_INTERVAL * 1000);
    }

    fclose(file);
    gpioTerminate();
    return EXIT_SUCCESS;
}

#include <stdio.h>
