#include <pigpio.h>

#define GPIO_PIN 23
#define LOG_FILE "flood_log.txt"
#define ALERT_MSG "ALERT: Water detected"

void log_message(const char *message) {
    time_t now = time(NULL);
    struct tm *t = localtime(&now);
    char buffer[100];
    strftime(buffer, sizeof(buffer), "%Y-%m-%d %H:%M:%S ", t);
    FILE *file = fopen(LOG_FILE, "a");
    if (file) {
        fprintf(file, "%s%s\n", buffer, message);
        fclose(file);
    }
}

void signal_handler(int signum) {
    if (signum == SIGINT || signum == SIGTERM) {
        printf("Exiting...\n");
        exit(0);
    }
}

int main() {
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    if (gpioInitialise() < 0) {
        printf("Failed to initialize pigpio\n");
        return 1;
    }

    int fd = gpioOpen(GPIO_PIN, PI_INPUT, PI_PUD_DOWN);
    if (fd < 0) {
        printf("Failed to open GPIO %d\n", GPIO_PIN);
        gpioTerminate();
        return 1;
    }

    while (1) {
        int level = gpioRead(fd);
        if (level < 0) {
            printf("Failed to read GPIO %d\n", GPIO_PIN);
            gpioTerminate();
            return 1;
        }

        if (level == PI_HIGH) {
