#define PULSE_PIN 4
#define LOG_FILE "rpm_log.txt"
#define SAMPLE_INTERVAL 1

volatile int pulses = 0;
pthread_mutex_t pulses_mutex = PTHREAD_MUTEX_INITIALIZER;

void pulse_count(int gpio, unsigned int level, uint32_t tick) {
    pthread_mutex_lock(&pulses_mutex);
    pulses++;
    pthread_mutex_unlock(&pulses_mutex);
}

void* sample_rpm(void* arg) {
    int rpm;
    time_t now;
    struct tm *timeinfo;
    char buffer[80];
    FILE *log_file = fopen(LOG_FILE, "w");

    if (log_file == NULL) {
        fprintf(stderr, "Failed to open log file\n");
        exit(EXIT_FAILURE);
    }

    while (1) {
        sleep(SAMPLE_INTERVAL);
        pthread_mutex_lock(&pulses_mutex);
        rpm = pulses * 60;
        pulses = 0;
        pthread_mutex_unlock(&pulses_mutex);

        time(&now);
        timeinfo = localtime(&now);
        strftime(buffer, sizeof(buffer), "%Y-%m-%d %H:%M:%S", timeinfo);
        fprintf(log_file, "%s %d\n", buffer, rpm);
        fflush(log_file);
        printf("%s %d\n", buffer, rpm);
    }

    fclose(log_file);
    return NULL;
}

void signal_handler(int signum) {
    gpioTerminate();
    exit(signum);
}

int main() {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Failed to initialize pigpio\n");
        return EXIT_FAILURE;
    }

    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    if (gpioSetMode(PULSE_PIN, PI_INPUT) < 0) {
        fprintf(stderr, "Failed to set pin mode\n");
        gpioTerminate();
        return EXIT_FAILURE;
    }

    if (gpioSetPullUpDown(PULSE_PIN, PI_PUD_UP) < 0) {
        fprintf(stderr, "Failed to set pull-up resistor\n");
        gpioTerminate();
        return EXIT_FAILURE;
    }

    if (gpioSetAlertFunc(PULSE_PIN, pulse_count) < 0) {
        fprintf(stderr, "Failed to set alert function\n");
        gpioTerminate();
        return EXIT_FAILURE;
    }

    pthread_t sample_thread;
    if (pthread_create(&sample_thread, NULL, sample_rpm, NULL) < 0) {
        fprintf(stderr, "Failed to create sampling thread\n");
        gpioTerminate();
        return EXIT_FAILURE;
    }

    pthread_join(sample_thread, NULL);
    gpioTerminate();
    return EXIT_SUCCESS;
}

