FILE *log_file;
int sensor_a, sensor_b;
pthread_mutex_t mutex = PTHREAD_MUTEX_INITIALIZER;
int prev_state = 0;

void signal_handler(int signum) {
    pthread_mutex_lock(&mutex);
    fclose(log_file);
    gpioTerminate();
    pthread_mutex_unlock(&mutex);
    exit(signum);
}

void alert_func(uint8_t gpio, uint8_t level, uint32_t tick) {
    int state;
    pthread_mutex_lock(&mutex);
    state = gpioRead(SENSOR_A) + 2 * gpioRead(SENSOR_B);
    if (state != prev_state) {
        time_t now = time(NULL);
        struct tm *t = localtime(&now);
        char buffer[26];
        strftime(buffer, sizeof(buffer), "%Y-%m-%d %H:%M:%S", t);
        if (state == 3) {
            fprintf(log_file, "%s.%03d: CCW\n", buffer, tick % 1000);
        } else if (state == 1) {
            fprintf(log_file, "%s.%03d: CW\n", buffer, tick % 1000);
        }
        fflush(log_file);
    }
    prev_state = state;
    pthread_mutex_unlock(&mutex);
}

int main() {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Failed to initialize pigpio\n");
        return EXIT_FAILURE;
    }

    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    log_file = fopen(ROTATION_LOG, "w");
    if (!log_file) {
        fprintf(stderr, "Failed to open log file\n");
        gpioTerminate();
        return EXIT_FAILURE;
    }

    if (gpioSetAlertFunc(SENSOR_A, alert_func) < 0) {
        fprintf(stderr, "Failed to set alert function for sensor A\n");
        fclose(log_file);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    if (gpioSetAlertFunc(SENSOR_B, alert_func) < 0) {
        fprintf(stderr, "Failed to set alert function for sensor B\n");
        fclose(log_file);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    if (gpioSetPullUpDown(SENSOR_A, PI_PUD_UP) < 0) {
        fprintf(stderr, "Failed to set pull-up for sensor A\n");
        fclose(log_file);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    if (gpioSetPullUpDown(SENSOR_B, PI_PUD_UP) < 0) {
        fprintf(stderr, "Failed to set pull-up for sensor B\n");
        fclose(log_file);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    while (1) {
        sleep(1);
    }

    return EXIT_SUCCESS;
}

