}

static void handle_sig(int signum) {
    fprintf(stderr, "Caught signal %d, exiting...\n", signum);
    exit(EXIT_FAILURE);
}

int main() {
    struct sigaction sa;
    gpiod_chip *chip;
    gpiod_line *led_line, *touch_line;
    int ret;

    // Register signal handlers
    sa.sa_handler = handle_sig;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) == -1) {
        perror("sigaction");
        return EXIT_FAILURE;
    }
    if (sigaction(SIGTERM, &sa, NULL) == -1) {
        perror("sigaction");
        return EXIT_FAILURE;
    }

    // Open GPIO chip
    chip = gpiod_chip_open("/dev/gpiochip0");
    if (!chip) {
        perror("gpiod_chip_open");
        return EXIT_FAILURE;
    }

    // Request LED line
    led_line = gpiod_chip_get_line(chip, LED_PIN);
    if (!led_line) {
        perror("gpiod_chip_get_line");
        cleanup(chip, NULL, NULL);
        return EXIT_FAILURE;
    }
    ret = gpiod_line_request_output(led_line, "led", 0);
    if (ret) {
        perror("gpiod_line_request_output");
        cleanup(chip, led_line, NULL);
        return EXIT_FAILURE;
    }

    // Request touch line
    touch_line = gpiod_chip_get_line(chip, TOUCH_PIN);
    if (!touch_line) {
        perror("gpiod_chip_get_line");
        cleanup(chip, led_line, NULL);
        return EXIT_FAILURE;
    }
    ret = gpiod_line_request_input(touch_line, "touch");
    if (ret) {
        perror("gpiod_line_request_input");
        cleanup(chip, led_line, touch_line);
        return EXIT_FAILURE;
    }

    // Main loop
    int last_value = 0;
    while (1) {
        struct gpiod_line_event event;
        ret = gpiod_line_event_wait(touch_line, NULL);
        if (ret) {
            perror("gpiod_line_event_wait");
            cleanup(chip, led_line, touch_line);
            return EXIT_FAILURE;
        }
        ret = gpiod_line_event_read(touch_line, &event);
        if (ret) {
            perror("gpiod_line_event_read");
            cleanup(chip, led_line, touch_line);
            return EXIT_FAILURE;
        }
        if (event.event_type == GPIOD_LINE_EVENT_RISING_EDGE && event.level == 1 && last_value == 0) {
            last_value = 1;
            int led_value = gpiod_line_get_value(led_line);
            ret = gpiod_line_set_value(led_line, !led_value);
            if (ret) {
