                cleanup(chip, led_line, touch_line);
                return EXIT_FAILURE;
            }
        } else if (event.event_type == GPIOD_LINE_EVENT_FALLING_EDGE && event.level == 0) {
            last_value = 0;
        }
    }

    // Cleanup
    cleanup(chip, led_line, touch_line);
    return EXIT_SUCCESS;
}

