int overflowCount = 0;

void logEvent(int sensor, time_t timestamp, int state) {
    if ((logHead + 1) % BUFFER_SIZE == logTail) {
        overflowCount++;
    } else {
        logBuffer[logHead].sensor = sensor;
        logBuffer[logHead].timestamp = timestamp;
        logBuffer[logHead].state = state;
        logHead = (logHead + 1) % BUFFER_SIZE;
    }
}

void printLog() {
    printf("Log buffer contents:\n");
    for (int i = logTail; i != logHead; i = (i + 1) % BUFFER_SIZE) {
        printf("Sensor: %d, Timestamp: %ld, State: %d\n", logBuffer[i].sensor, logBuffer[i].timestamp, logBuffer[i].state);
    }
    printf("Overflow count: %d\n", overflowCount);
}

