#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <errno.h>
#include <signal.h>
#include <pigpio.h>

#define GPIO_SENSOR1 17
#define GPIO_SENSOR2 18
#define DEBOUNCE_TIME 5000 // 5 ms
#define PULSES_PER_REV 2

FILE *log_file;
volatile sig_atomic_t stop_requested = 0;

void handle_sigint(int signum) {
    stop_requested = 1;
}

int main() {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Failed to initialize pigpio: %s\n", strerror(errno));
        return EXIT_FAILURE;
    }

    if ((log_file = fopen("shaft_log.txt", "w")) == NULL) {
        fprintf(stderr, "Failed to open log file: %s\n", strerror(errno));
        gpioTerminate();
        return EXIT_FAILURE;
    }

    signal(SIGINT, handle_sigint);

    int count = 0;
    int last_sensor1_state = -1;
    int last_sensor2_state = -1;
    struct timespec debounce_timer = {0, 0};

    while (!stop_requested) {
        int sensor1_state = gpioRead(GPIO_SENSOR1);
        int sensor2_state = gpioRead(GPIO_SENSOR2);

        struct timespec current_time;
        clock_gettime(CLOCK_REALTIME, &current_time);

        if (sensor1_state != last_sensor1_state || sensor2_state != last_sensor2_state) {
            if (debounce_timer.tv_sec == 0 && debounce_timer.tv_nsec == 0) {
                // First change after debounce
                count++;
                if (count == PULSES_PER_REV) {
                    // One revolution completed
                    count = 0;
                    fprintf(log_file, "%ld.%09ld,%d,%d\n", current_time.tv_sec, current_time.tv_nsec, sensor1_state, sensor2_state);
                    fflush(log_file);
                }
                // Reset debounce timer
                clock_gettime(CLOCK_REALTIME, &debounce_timer);
            } else {
                // Debounce in progress
                struct timespec elapsed_time;
                elapsed_time.tv_sec = current_time.tv_sec - debounce_timer.tv_sec;
                elapsed_time.tv_nsec = current_time.tv_nsec - debounce_timer.tv_nsec;
                if (elapsed_time.tv_nsec < 0) {
                    elapsed_time.tv_sec--;
                    elapsed_time.tv_nsec += 1000000000;
                }
                if (elapsed_time.tv_sec < 0) {
                    // Timer expired
                    debounce_timer.tv_sec = 0;
                    debounce_timer.tv_nsec = 0;
                } else {
                    // Timer not expired yet
                    struct timespec remaining_time = {DEBOUNCE_TIME / 1000000000, (DEBOUNCE_TIME % 1000000000) * 1000};
                    if ((remaining_time.tv_sec > elapsed_time.tv_sec) ||
                        (remaining_time.tv_sec == elapsed_time.tv_sec && remaining_time.tv_nsec > elapsed_time.tv_nsec)) {
                        // Still within debounce time
                        struct timespec sleep_time = {remaining_time.tv_sec - elapsed_time.tv_sec,
                                                      remaining_time.tv_nsec - elapsed_time.tv_nsec};
                        nanosleep(&sleep_time, NULL);
                    } else {
                        // Debounce time expired
                        debounce_timer.tv_sec = 0;
                        debounce_timer.tv_nsec = 0;
                    }
                }
            }
        }

        last_sensor1_state = sensor1_state;
        last_sensor2_state = sensor2_state;
    }

    fclose(log_file);
    gpioTerminate();
    return EXIT_SUCCESS;
}

#include <stdio.h>
