#define PART_ID 0x00
#define CONFIG 0x30
#define HR 0x02
#define SPO2 0x04

volatile sig_atomic_t stop = 0;

void signal_handler(int signum) {
    stop = 1;
}

int main() {
    int i2c_handle, file;
    uint8_t part_id, config;
    uint16_t hr, spo2;
    time_t rawtime;
    struct tm *timeinfo;
    char buffer[80];

    if ((i2c_handle = pi_i2c_open(1, 0x28)) < 0) {
        fprintf(stderr, "Failed to open I2C bus 1 at address 0x28\n");
        return EXIT_FAILURE;
    }

    if ((file = open("biometric_log.txt", O_WRONLY | O_APPEND | O_CREAT, 0666)) < 0) {
        fprintf(stderr, "Failed to open log file\n");
        pi_i2c_close(i2c_handle);
        return EXIT_FAILURE;
    }

    if (signal(SIGINT, signal_handler) == SIG_ERR) {
        fprintf(stderr, "Failed to set signal handler\n");
        pi_i2c_close(i2c_handle);
        close(file);
        return EXIT_FAILURE;
    }

    if (pi_i2c_read_byte_data(i2c_handle, PART_ID, &part_id) < 0) {
        fprintf(stderr, "Failed to read PART_ID register\n");
        pi_i2c_close(i2c_handle);
        close(file);
        return EXIT_FAILURE;
    }

    if (part_id != 0x11) {
        fprintf(stderr, "Invalid PART_ID: 0x%02X\n", part_id);
        pi_i2c_close(i2c_handle);
        close(file);
        return EXIT_FAILURE;
    }

    config = 0x01; // Continuous measurement mode
    if (pi_i2c_write_byte_data(i2c_handle, CONFIG, config) < 0) {
        fprintf(stderr, "Failed to write CONFIG register\n");
        pi_i2c_close(i2c_handle);
        close(file);
        return EXIT_FAILURE;
    }

    while (!stop) {
        if (pi_i2c_read_word_data(i2c_handle, HR, &hr) < 0) {
            fprintf(stderr, "Failed to read HR data\n");
            continue;
        }

        if (pi_i2c_read_word_data(i2c_handle, SPO2, &spo2) < 0) {
            fprintf(stderr, "Failed to read SPO2 data\n");
            continue;
        }

        time(&rawtime);
        timeinfo = localtime(&rawtime);
        strftime(buffer, sizeof(buffer), "%Y-%m-%d %H:%M:%S", timeinfo);
        dprintf(file, "%s, Heart Rate: %d BPM, SpO2: %d%%\n", buffer, hr, spo2);
        fflush(file);
    }

    pi_i2c_close(i2c_handle);
    close(file);
    pi_stop();

    return EXIT_SUCCESS;
}

