    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialization failed\n");
        return EXIT_FAILURE;
    }

    signal(SIGINT, handle_signal);
    signal(SIGTERM, handle_signal);

    log_file = fopen("bridge_integrity.log", "w");
    if (!log_file) {
        fprintf(stderr, "Failed to open log file\n");
        gpioTerminate();
        return EXIT_FAILURE;
    }

    log_event("Program started");

    gpioSetMode(GPIO_SENSOR_1, PI_INPUT);
    gpioSetPullUpDown(GPIO_SENSOR_1, PI_PUD_DOWN);
    gpioSetMode(GPIO_SENSOR_2, PI_INPUT);
    gpioSetPullUpDown(GPIO_SENSOR_2, PI_PUD_DOWN);
    gpioSetMode(GPIO_ALARM, PI_OUTPUT);
    gpioWrite(GPIO_ALARM, 0);

    int sensor_1_state = 0;
    int sensor_2_state = 0;
    int sensor_1_tilt_start = 0;
    int sensor_2_tilt_start = 0;

    while (1) {
        int sensor_1_new_state = gpioRead(GPIO_SENSOR_1);
        int sensor_2_new_state = gpioRead(GPIO_SENSOR_2);

        if (sensor_1_new_state == 1 && sensor_1_state == 0) {
            sensor_1_tilt_start = time(NULL);
            log_event("Sensor 1 tilt-start");
        } else if (sensor_1_new_state == 1 && time(NULL) - sensor_1_tilt_start >= TILT_THRESHOLD) {
            activate_alarm();
        }

        if (sensor_2_new_state == 1 && sensor_2_state == 0) {
            sensor_2_tilt_start = time(NULL);
            log_event("Sensor 2 tilt-start");
        } else if (sensor_2_new_state == 1 && time(NULL) - sensor_2_tilt_start >= TILT_THRESHOLD) {
            activate_alarm();
        }

        if (sensor_1_new_state == 0 && sensor_1_state == 1) {
            log_event("Sensor 1 tilt-end");
        }

        if (sensor_2_new_state == 0 && sensor_2_state == 1) {
            log_event("Sensor 2 tilt-end");
        }

        sensor_1_state = sensor_1_new_state;
        sensor_2_state = sensor_2_new_state;

        gpioDelay(100000); // 100 ms
    }

    return EXIT_SUCCESS;
}

#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <pigpio.h>
#include <errno.h>

#define SENSOR_ADDRESS 0x1D
#define LED_PIN 17
#define THRESHOLD 500
#define LOG_FILE "seismic_events.log"

int main() {
    int i2c_handle, ret, retries;
    uint8_t data[6];
    float vibration_magnitude;
    time_t rawtime;
    struct tm *timeinfo;
    char buffer[80];

    // Initialize pigpio library
    if ((i2c_handle = pi_i2c_open(1, SENSOR_ADDRESS)) < 0) {
        printf("Failed to open I2C bus: %s\n", strerror(errno));
        return EXIT_FAILURE;
    }

    // Initialize LED pin
    if (gpioSetMode(LED_PIN, PI_OUTPUT) < 0) {
        printf("Failed to set LED pin mode: %s\n", strerror(errno));
        return EXIT_FAILURE;
    }

    // Initialize log file
    FILE *log_file = fopen(LOG_FILE, "w");
    if (log_file == NULL) {
        printf("Failed to open log file: %s\n", strerror(errno));
        return EXIT_FAILURE;
    }

    while (1) {
        // Clear power-down bit in CTRL1 register
        ret = pi_i2c_write_byte_data(i2c_handle, 0x1F, 0x00);
        if (ret < 0) {
            printf("Failed to clear power-down bit: %s\n", strerror(errno));
            continue;
        }

        // Read 3-axis acceleration data
        retries = 3;
        while (retries--) {
            ret = pi_i2c_read_i2c_block_data(i2c_handle, 0x28, 6, data);
            if (ret == 6) break;
            usleep(100000); // Wait before retrying
        }

        if (ret != 6) {
            printf("Failed to read acceleration data: %s\n", strerror(errno));
            continue;
        }

        // Compute Euclidean vibration magnitude
        vibration_magnitude = sqrt((data[0] << 8 | data[1]) * (data[0] << 8 | data[1]) +
                                    (data[2] << 8 | data[3]) * (data[2] << 8 | data[3]) +
                                    (data[4] << 8 | data[5]) * (data[4] << 8 | data[5]));

        // Check if vibration magnitude exceeds threshold
        if (vibration_magnitude > THRESHOLD) {
            // Get current time
            time(&rawtime);
            timeinfo = localtime(&rawtime);
            strftime(buffer, sizeof(buffer), "%Y-%m-%dT%H:%M:%S", timeinfo);

            // Log event
            fprintf(log_file, "%s: %.2f\n", buffer, vibration_magnitude);

            // Turn on LED
            gpioWrite(LED_PIN, PI_HIGH);
            usleep(1000000); // Wait for 1 second
            gpioWrite(LED_PIN, PI_LOW);
        }
    }

    // Clean up
    fclose(log_file);
    pi_i2c_close(i2c_handle);
    gpioTerminate();
    return EXIT_SUCCESS;
}

#include <stdio.h>
#include <stdlib.h>
#include <signal.h>
#include <libgpiod.h>

#define LED_PIN 18
#define SENSOR_PINS 4
#define SENSOR_PINS_ARRAY {4, 17, 27, 22}
#define POLLING_INTERVAL_MS 50

static struct gpiod_chip *chip;
static struct gpiod_line_bulk lines;
static struct gpiod_line_event events[SENSOR_PINS];
static int led_state = 0;

void cleanup_and_exit(int status) {
    gpiod_line_set_value(led_state ? chip, LED_PIN, 0);
    gpiod_line_release_bulk(chip, &lines);
    gpiod_chip_close(chip);
    exit(status);
}

void handle_signal(int signum) {
    cleanup_and_exit(EXIT_SUCCESS);
}

int main() {
    struct sigaction action;
    action.sa_handler = handle_signal;
    sigemptyset(&action.sa_mask);
    action.sa_flags = 0;
    sigaction(SIGINT, &action, NULL);
    sigaction(SIGTERM, &action, NULL);

    chip = gpiod_chip_open("/dev/gpiochip0");
    if (!chip) {
        fprintf(stderr, "Failed to open GPIO chip\n");
        return EXIT_FAILURE;
    }

    lines.offsets = SENSOR_PINS_ARRAY;
    lines.count = SENSOR_PINS;
    if (gpiod_line_request_bulk(chip, &lines, "input") < 0) {
        fprintf(stderr, "Failed to request lines\n");
        cleanup_and_exit(EXIT_FAILURE);
    }

    if (gpiod_line_set_direction(chip, LED_PIN, GPIOD_LINE_DIRECTION_OUT) < 0) {
        fprintf(stderr, "Failed to set LED pin direction\n");
        cleanup_and_exit(EXIT_FAILURE);
    }

    while (1) {
        if (gpiod_line_event_wait_bulk(chip, &lines, events, POLLING_INTERVAL_MS) < 0) {
            fprintf(stderr, "Failed to wait for events\n");
            cleanup_and_exit(EXIT_FAILURE);
        }

        for (int i = 0; i < SENSOR_PINS; i++) {
            if (events[i].event_type == GPIOD_LINE_EVENT_RISING_EDGE) {
                led_state = 1;
                gpiod_line_set_value(chip, LED_PIN, led_state);
            }
        }

        led_state = 0;
        gpiod_line_set_value(chip, LED_PIN, led_state);
    }

    cleanup_and_exit(EXIT_SUCCESS);
}

#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <syslog.h>
#include <gpiod.h>
#include <unistd.h>
#include <fcntl.h>
#include <signal.h>

#define NUM_SENSORS 5
#define DEBOUNCE_TIME 50 // ms
#define LOG_FILE "/var/log/flame_events.log"

volatile sig_atomic_t stop = 0;

void sig_handler(int signum) {
    stop = 1;
}

int main() {
    struct gpiod_chip *chip;
    struct gpiod_line *lines[NUM_SENSORS];
    struct sigaction action;
    int i, ret, fd;
    char log_message[256];
    struct timespec ts = {0, 100000000}; // 1 second

    openlog("flame_monitor", LOG_PID, LOG_USER);

    action.sa_handler = sig_handler;
    sigemptyset(&action.sa_mask);
    action.sa_flags = 0;

    sigaction(SIGINT, &action, NULL);
    sigaction(SIGTERM, &action, NULL);

    chip = gpiod_chip_open("/dev/gpiochip0");
    if (!chip) {
        syslog(LOG_ERR, "Failed to open GPIO chip");
        closelog();
        return EXIT_FAILURE;
    }

    for (i = 0; i < NUM_SENSORS; i++) {
        lines[i] = gpiod_chip_get_line(chip, i + 2);
        if (!lines[i]) {
            syslog(LOG_ERR, "Failed to get line %d", i + 2);
            goto cleanup;
        }

        ret = gpiod_line_request(lines[i], "flame_monitor", GPIO_LINE_REQUEST_DIRECTION_IN);
        if (ret) {
            syslog(LOG_ERR, "Failed to request line %d", i + 2);
            goto cleanup;
        }
    }

    fd = open(LOG_FILE, O_WRONLY | O_CREAT | O_APPEND, 0644);
    if (fd < 0) {
        syslog(LOG_ERR, "Failed to open log file");
        goto cleanup;
    }

    flock(fd, LOCK_EX);

    syslog(LOG_USER, "flame_monitor started");

    while (!stop) {
        for (i = 0; i < NUM_SENSORS; i++) {
            struct gpiod_line_event event;
            int value, debounce_value;

            ret = gpiod_line_event_read(lines[i], &event);
            if (ret) {
                syslog(LOG_ERR, "Failed to read event for line %d", i + 2);
                continue;
            }

            value = gpiod_line_get_value(lines[i]);
            usleep(DEBOUNCE_TIME * 1000); // 50 ms debounce
            debounce_value = gpiod_line_get_value(lines[i]);

            if (value == 0 && debounce_value == 1) {
                time_t now = time(NULL);
                struct tm *tm = gmtime(&now);

                strftime(log_message, sizeof(log_message), "%Y-%m-%dT%H:%M:%SZ - Sensor ID: %d (GPIO %d) - Flame Detected\n", tm, i + 1, i + 2);
                write(fd, log_message, strlen(log_message));
                fflush(NULL);
            }
        }

        nanosleep(&ts, NULL);
    }

    syslog(LOG_USER, "flame_monitor stopped");

cleanup:
    for (i = 0; i < NUM_SENSORS; i++) {
        if (lines[i]) {
            gpiod_line_release(lines[i]);
        }
    }

    if (chip) {
        gpiod_chip_close(chip);
    }

    close(fd);
    closelog();

    return EXIT_SUCCESS;
}

#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <gpiod.h>

#define GPIO_CHIP "/dev/gpiochip0"
#define GPIO_LINE_COUNT 8
#define GPIO_LINE_NUMBERS {5, 6, 13, 19, 26, 12, 16, 20}
#define POLL_INTERVAL_MS 50

static struct gpiod_chip *chip;
static struct gpiod_line_bulk lines;
static int line_values[GPIO_LINE_COUNT];
static int running = 1;

static void sigint_handler(int signum) {
    running = 0;
}

static void print_timestamp() {
    time_t now = time(NULL);
    struct tm *t = localtime(&now);
    printf("%04d-%02d-%02dT%02d:%02d:%02d ",
           t->tm_year + 1900, t->tm_mon + 1, t->tm_mday,
           t->tm_hour, t->tm_min, t->tm_sec);
}

static void handle_error(const char *msg) {
    perror(msg);
    exit(EXIT_FAILURE);
}

static void release_resources() {
    if (lines.lines) {
        gpiod_line_release_bulk(lines.lines, lines.count);
    }
    if (chip) {
        gpiod_chip_close(chip);
    }
}

int main() {
    struct sigaction action;
    memset(&action, 0, sizeof(struct sigaction));
    action.sa_handler = sigint_handler;
    sigaction(SIGINT, &action, NULL);

    atexit(release_resources);

    chip = gpiod_chip_open_by_name(GPIO_CHIP);
    if (!chip) {
        handle_error("Failed to open GPIO chip");
    }

    lines.count = GPIO_LINE_COUNT;
    lines.lines = malloc(sizeof(struct gpiod_line *) * lines.count);
    if (!lines.lines) {
        handle_error("Failed to allocate memory for GPIO lines");
    }

    int line_numbers[GPIO_LINE_COUNT] = GPIO_LINE_NUMBERS;
    for (int i = 0; i < lines.count; i++) {
        lines.lines[i] = gpiod_chip_get_line(chip, line_numbers[i]);
        if (!lines.lines[i]) {
            handle_error("Failed to get GPIO line");
        }
    }

    if (gpiod_line_request_bulk(lines.lines, lines.count, "touch_sensor") < 0) {
        handle_error("Failed to request GPIO lines");
    }

    while (running) {
        struct gpiod_line_event event;
        for (int i = 0; i < lines.count; i++) {
            if (gpiod_line_event_read(lines.lines[i], &event) < 0) {
                handle_error("Failed to read GPIO line event");
            }
            if (event.event_type == GPIOD_LINE_EVENT_RISING_EDGE) {
                print_timestamp();
                printf("Touch %d detected on GPIO %d\n", i, line_numbers[i]);
            } else if (event.event_type == GPIOD_LINE_EVENT_FALLING_EDGE) {
                print_timestamp();
                printf("Touch %d released on GPIO %d\n", i, line_numbers[i]);
            }
        }
        usleep(POLL_INTERVAL_MS * 1000);
    }

    free(lines.lines);
    return 0;
}

#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <pigpio.h>
#include <errno.h>

#define ALS_GAIN 0x00
#define ALS_TIME 0x00
#define ALS_REG 0x04
#define PWM_FREQ 1000
#define PWM_RANGE 100
#define LOG_FILE "grow_log.txt"

int terminate = 0;

void signal_handler(int signum) {
    terminate = 1;
}

int main() {
    FILE *log_file;
    int i2c_handle, gpio_handle;
    uint16_t raw;
    float lux;
    int brightness;

    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    if ((i2c_handle = i2cOpen(1, 0x10, 0)) < 0) {
        printf("Failed to open I2C bus 1: %s\n", strerror(errno));
        return EXIT_FAILURE;
    }

    if ((gpio_handle = gpioInitialise()) < 0) {
        printf("Failed to initialize pigpio: %s\n", strerror(errno));
        return EXIT_FAILURE;
    }

    if (i2cWriteByteData(i2c_handle, 0x00, ALS_GAIN | ALS_TIME) < 0) {
        printf("Failed to write to VEML7700: %s\n", strerror(errno));
        return EXIT_FAILURE;
    }

    log_file = fopen(LOG_FILE, "w");
    if (log_file == NULL) {
        printf("Failed to open log file: %s\n", strerror(errno));
        return EXIT_FAILURE;
    }

    gpioSetPWMfrequency(gpio_handle, 18, PWM_FREQ);
    gpioSetPWMrange(gpio_handle, 18, PWM_RANGE);

    while (!terminate) {
        if (i2cReadWordData(i2c_handle, ALS_REG) < 0) {
            printf("Failed to read from VEML7700: %s\n", strerror(errno));
            terminate = 1;
            continue;
        }

        raw = i2cReadByteData(i2c_handle, ALS_REG + 1) << 8 | i2cReadByteData(i2c_handle, ALS_REG);
        lux = raw * 0.0576;

        if (lux < 100) {
            brightness = PWM_RANGE;
        } else if (lux < 500) {
            brightness = PWM_RANGE * 3 / 4;
        } else if (lux < 1000) {
            brightness = PWM_RANGE / 2;
        } else {
            brightness = PWM_RANGE / 4;
        }

        gpioPWM(gpio_handle, 18, brightness);

        time_t now = time(NULL);
        struct tm *t = localtime(&now);
        char timestamp[20];
        strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", t);

        fprintf(log_file, "%s, %.2f, %d, %d\n", timestamp, lux, brightness, errno);
        fflush(log_file);
    }

    gpioPWM(gpio_handle, 18, 0);
    fclose(log_file);
    i2cClose(i2c_handle);
    gpioTerminate();

    return EXIT_SUCCESS;
}

#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <pigpio.h>

#define GPIO_COUNT 8
#define DEBOUNCE_TIME 100 // ms

volatile sig_atomic_t running = 1;
int gpios[GPIO_COUNT];
int led_gpio;
FILE *log_file;

void signal_handler(int signum) {
    running = 0;
    gpioWrite(led_gpio, 0);
    gpioTerminate();
    fclose(log_file);
    exit(signum);
}

void touch_detected(int gpio, int level, uint32_t tick) {
    if (level == 0) {
        for (int i = 0; i < GPIO_COUNT; i++) {
            if (gpio == gpios[i]) {
                time_t now = time(NULL);
                struct tm *t = localtime(&now);
                char buffer[100];
                strftime(buffer, sizeof(buffer), "%Y-%m-%d %H:%M:%S", t);
                fprintf(log_file, "%s - Channel %d Touched\n", buffer, i + 1);
                fflush(log_file);
                gpioWrite(led_gpio, 1);
                break;
            }
        }
    }
}

int main() {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return EXIT_FAILURE;
    }

    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    led_gpio = 17;
    gpioSetMode(led_gpio, PI_OUTPUT);
    gpioWrite(led_gpio, 0);

    log_file = fopen("touch_log.txt", "a");
    if (log_file == NULL) {
        fprintf(stderr, "Failed to open log file\n");
        gpioTerminate();
        return EXIT_FAILURE;
    }

    for (int i = 0; i < GPIO_COUNT; i++) {
        gpios[i] = i + 2;
        gpioSetMode(gpios[i], PI_INPUT);
        gpioSetPullUpDown(gpios[i], PI_PUD_DOWN);
        gpioGlitchFilter(gpios[i], 100); // 100 ms glitch filter
        gpioSetAlertFunc(gpios[i], touch_detected);
    }

    while (running) {
        gpioDelay(50000); // 50 ms delay
    }

    gpioTerminate();
    fclose(log_file);
    return EXIT_SUCCESS;
}

#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <pigpio.h>

#define OPT3001_ADDRESS 0x44
#define CONFIGURATION_REGISTER 0x01
#define RESULT_REGISTER 0x00
#define CONFIGURATION_WORD 0xC810
#define CONVERSION_TIME 100 // ms

int main() {
    int h = i2cOpen(1, OPT3001_ADDRESS, 0);
    if (h < 0) {
        fprintf(stderr, "Failed to open I2C bus: %s\n", strerror(-h));
        return EXIT_FAILURE;
    }

    if (i2cWriteWordData(h, CONFIGURATION_REGISTER, CONFIGURATION_WORD) < 0) {
        fprintf(stderr, "Failed to write configuration to OPT3001: %s\n", strerror(-h));
        i2cClose(h);
        return EXIT_FAILURE;
    }

    FILE *log_file = fopen("light_data.txt", "w");
    if (!log_file) {
        fprintf(stderr, "Failed to open log file: %s\n", strerror(errno));
        i2cClose(h);
        return EXIT_FAILURE;
    }

    struct sigaction sigIntHandler;
    sigIntHandler.sa_handler = gpioTerminate;
    sigemptyset(&sigIntHandler.sa_mask);
    sigIntHandler.sa_flags = 0;
    sigaction(SIGINT, &sigIntHandler, NULL);

    while (1) {
        uint16_t result;
        if (i2cReadWordData(h, RESULT_REGISTER, &result) < 0) {
            fprintf(stderr, "Failed to read result from OPT3001: %s\n", strerror(-h));
            break;
        }

        uint16_t exponent = (result >> 12) & 0x0F;
        uint16_t mantissa = result & 0x0FFF;
        double lux = mantissa * 0.01 * (1 << exponent);

        time_t now = time(NULL);
        struct tm *t = localtime(&now);
        char time_str[20];
        strftime(time_str, sizeof(time_str), "%Y-%m-%d %H:%M:%S", t);

        fprintf(log_file, "%s, %.2f\n", time_str, lux);
        printf("%s, %.2f\n", time_str, lux);

        fflush(log_file);
        sleep(1);
    }

    fclose(log_file);
    i2cClose(h);
    return EXIT_SUCCESS;
}

#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <pigpio.h>

#define SENSOR_GPIO 4
#define ALERT_GPIO 17
#define LOG_FILE "fire_events.log"
#define POLL_INTERVAL 500
#define ALERT_DURATION 1000

static int keep_running = 1;

void signal_handler(int signum) {
    keep_running = 0;
}

int main() {
    FILE *log_file;
    int sensor_fd, alert_fd;
    struct timespec ts = {0, POLL_INTERVAL * 1000 * 1000};

    if (gpioInitialise() < 0) {
        fprintf(stderr, "Failed to initialize pigpio\n");
        return EXIT_FAILURE;
    }

    signal(SIGINT, signal_handler);

    log_file = fopen(LOG_FILE, "a");
    if (!log_file) {
        fprintf(stderr, "Failed to open log file\n");
        gpioTerminate();
        return EXIT_FAILURE;
    }

    sensor_fd = gpioOpen(SENSOR_GPIO, PI_INPUT, 0);
    if (sensor_fd < 0) {
        fprintf(stderr, "Failed to open sensor GPIO\n");
        fclose(log_file);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    alert_fd = gpioOpen(ALERT_GPIO, PI_OUTPUT, 0);
    if (alert_fd < 0) {
        fprintf(stderr, "Failed to open alert GPIO\n");
        gpioClose(sensor_fd);
        fclose(log_file);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    while (keep_running) {
        int sensor_value;
        struct timespec start_time, end_time;

        clock_gettime(CLOCK_MONOTONIC, &start_time);

        sensor_value = gpioRead(sensor_fd);
        if (sensor_value < 0) {
            fprintf(stderr, "Failed to read sensor GPIO\n");
            continue;
        }

        fprintf(log_file, "%ld.%09ld: Sensor value: %d\n",
                start_time.tv_sec, start_time.tv_nsec, sensor_value);

        if (sensor_value == 0) {
            gpioWrite(alert_fd, PI_HIGH);
            nanosleep(&ts, NULL);
            gpioWrite(alert_fd, PI_LOW);
        }

        clock_gettime(CLOCK_MONOTONIC, &end_time);
        ts.tv_sec = POLL_INTERVAL - (end_time.tv_sec - start_time.tv_sec);
        ts.tv_nsec = 0;
        nanosleep(&ts, NULL);
    }

    gpioClose(sensor_fd);
    gpioClose(alert_fd);
    fclose(log_file);
    gpioTerminate();

    return EXIT_SUCCESS;
}

#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <libgpiod.h>

#define GPIO_PIN 4
#define DEBOUNCE_INTERVAL 50 // ms

FILE *log_file;
struct gpiod_chip *chip;
struct gpiod_line *line;

void log_touch_event(const char *event) {
