        return EXIT_FAILURE;
    }

    if (gpiod_line_request_input(line, "touch_sensor", 0) < 0) {
        fprintf(stderr, "Failed to request GPIO line as input\n");
        gpiod_line_release(line);
        gpiod_chip_close(chip);
        return EXIT_FAILURE;
    }

    log_file = fopen("touch_log.txt", "a");
    if (!log_file) {
        fprintf(stderr, "Failed to open log file\n");
        gpiod_line_release(line);
        gpiod_chip_close(chip);
        return EXIT_FAILURE;
    }

    int previous_level = gpiod_line_get_value(line);
    struct timespec sleep_time = {0, DEBOUNCE_INTERVAL * 1000000L};

    while (1) {
        nanosleep(&sleep_time, NULL);
        int current_level = gpiod_line_get_value(line);
        if (current_level != previous_level) {
            if (current_level) {
                log_touch_event("Touch Detected");
            } else {
                log_touch_event("Touch Released");
            }
            previous_level = current_level;
        }
    }

    return EXIT_SUCCESS;
}

#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <signal.h>
#include <time.h>
#include <errno.h>
#include <unistd.h>
#include <pigpio.h>

#define SLF3S_ADDRESS 0x08
#define SLF3S_CMD 0x36
#define SLF3S_CMD_LEN 2
#define SLF3S_READ_LEN 3
#define SLF3S_CRC_POLY 0x31
#define SLF3S_CRC_INIT 0xFF
#define FLOW_MIN 0.0
#define FLOW_MAX 100.0
#define LOG_FILE "cooling_log.csv"

static int i2c_handle = -1;
static FILE *log_file = NULL;
static volatile sig_atomic_t running = 1;

static uint8_t crc8(uint8_t *data, size_t len, uint8_t crc) {
    for (size_t i = 0; i < len; i++) {
        crc ^= data[i];
        for (int j = 0; j < 8; j++) {
            if (crc & 0x80) {
                crc = (crc << 1) ^ SLF3S_CRC_POLY;
            } else {
                crc <<= 1;
            }
        }
    }
    return crc;
}

static int read_sensor(uint16_t *raw, uint8_t *crc) {
    uint8_t buffer[SLF3S_READ_LEN];
    if (i2c_read_device(i2c_handle, buffer, SLF3S_READ_LEN) != SLF3S_READ_LEN) {
        return -1;
    }
    *raw = (buffer[0] << 8) | buffer[1];
    *crc = buffer[2];
    return 0;
}

static int write_sensor(uint8_t *cmd, size_t len) {
    if (i2c_write_device(i2c_handle, cmd, len) != len) {
        return -1;
    }
    return 0;
}

static void log_data(const char *status, double flow_rate) {
    time_t now = time(NULL);
    struct tm *timeinfo = localtime(&now);
    char timestamp[20];
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", timeinfo);
    fprintf(log_file, "%s,%.2f,%s\n", timestamp, flow_rate, status);
    fflush(log_file);
}

static void signal_handler(int signum) {
    running = 0;
}

int main() {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Failed to initialize pigpio\n");
        return EXIT_FAILURE;
    }

    if ((i2c_handle = i2c_open(1, SLF3S_ADDRESS)) < 0) {
        fprintf(stderr, "Failed to open I2C device\n");
        gpioTerminate();
        return EXIT_FAILURE;
    }

    if (write_sensor((uint8_t *)&SLF3S_CMD, SLF3S_CMD_LEN) != 0) {
        fprintf(stderr, "Failed to write to sensor\n");
        i2c_close(i2c_handle);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    if ((log_file = fopen(LOG_FILE, "a")) == NULL) {
        fprintf(stderr, "Failed to open log file\n");
        i2c_close(i2c_handle);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    if (fseek(log_file, 0, SEEK_END) != 0 || ftell(log_file) == 0) {
        fprintf(log_file, "Timestamp,Flow Rate (ml/min),Status\n");
    }

    signal(SIGINT, signal_handler);

    while (running) {
        uint16_t raw;
        uint8_t crc;
        if (read_sensor(&raw, &crc) != 0 || crc8((uint8_t *)&raw, sizeof(raw), SLF3S_CRC_INIT) != crc) {
            log_data("ERROR", 0.0);
            continue;
        }
        double flow_rate = raw / 90.0;
        if (flow_rate < FLOW_MIN || flow_rate > FLOW_MAX) {
            log_data("INVALID", flow_rate);
            continue;
        }
        log_data("OK", flow_rate);
        sleep(1);
    }

    fclose(log_file);
    i2c_close(i2c_handle);
    gpioTerminate();
    return EXIT_SUCCESS;
}

#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <gpiod.h>
#include <signal.h>
#include <errno.h>

#define GPIO_CHIP "/dev/gpiochip0"
#define LEFT_LINE 17
#define MIDDLE_LINE 27
#define RIGHT_LINE 22
#define LOG_FILE "path_log.csv"
#define POLL_INTERVAL 50 // ms

static bool running = true;
static struct gpiod_chip *chip;
static struct gpiod_line *lines[3];
static FILE *log_file;

void cleanup() {
    for (int i = 0; i < 3; i++) {
        gpiod_line_release(lines[i]);
    }
    gpiod_chip_close(chip);
    fclose(log_file);
}

void sigint_handler(int signum) {
    running = false;
}

int main() {
    struct sigaction action;
    memset(&action, 0, sizeof(struct sigaction));
    action.sa_handler = sigint_handler;
    sigaction(SIGINT, &action, NULL);

    atexit(cleanup);

    chip = gpiod_chip_open(GPIO_CHIP);
    if (!chip) {
        fprintf(stderr, "Failed to open GPIO chip: %s\n", strerror(errno));
        return EXIT_FAILURE;
    }

    lines[0] = gpiod_chip_get_line(chip, LEFT_LINE);
    lines[1] = gpiod_chip_get_line(chip, MIDDLE_LINE);
    lines[2] = gpiod_chip_get_line(chip, RIGHT_LINE);

    for (int i = 0; i < 3; i++) {
        if (!gpiod_line_request_input(lines[i], "path_sensor")) {
            fprintf(stderr, "Failed to request line %d as input: %s\n", i, strerror(errno));
            return EXIT_FAILURE;
        }
    }

    log_file = fopen(LOG_FILE, "a");
    if (!log_file) {
        fprintf(stderr, "Failed to open log file: %s\n", strerror(errno));
        return EXIT_FAILURE;
    }

    fprintf(log_file, "timestamp,left,middle,right\n");

    while (running) {
        struct timespec req = {0, POLL_INTERVAL * 1000 * 1000};
        nanosleep(&req, NULL);

        for (int i = 0; i < 3; i++) {
            int value = gpiod_line_get_value(lines[i]);
            struct timespec ts;
            clock_gettime(CLOCK_REALTIME, &ts);
            char timestamp[26];
            strftime(timestamp, sizeof(timestamp), "%Y-%m-%dT%H:%M:%S", gmtime(&ts.tv_sec));
            fprintf(log_file, "%s.%09ld,%d,%d,%d\n", timestamp, ts.tv_nsec, value, value, value);
        }
    }

    return EXIT_SUCCESS;
}

#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <libgpiod.h>

#define GPIO_CHIP "/dev/gpiochip0"
#define GPIO_LINE 4
#define FLAME_LOG_FILE "flame_events.txt"

static struct gpiod_chip *chip;
static struct gpiod_line *line;
static int running = 1;

void handle_signal(int signum) {
    running = 0;
}

void log_event(const char *message) {
    FILE *file = fopen(FLAME_LOG_FILE, "a");
    if (file) {
        time_t now = time(NULL);
        char *time_str = ctime(&now);
        time_str[strcspn(time_str, "\n")] = 0; // Remove newline
        fprintf(file, "[%s] %s\n", time_str, message);
        fclose(file);
    }
}

int main() {
    struct sigaction action;
    memset(&action, 0, sizeof(struct sigaction));
    action.sa_handler = handle_signal;
    sigaction(SIGINT, &action, NULL);
    sigaction(SIGTERM, &action, NULL);

    chip = gpiod_chip_open(GPIO_CHIP);
    if (!chip) {
        fprintf(stderr, "Failed to open GPIO chip\n");
        return EXIT_FAILURE;
    }

    line = gpiod_chip_get_line(chip, GPIO_LINE);
    if (!line) {
        fprintf(stderr, "Failed to get GPIO line\n");
        gpiod_chip_close(chip);
        return EXIT_FAILURE;
    }

    if (gpiod_line_request_input(line, "flame_sensor") < 0) {
        fprintf(stderr, "Failed to request GPIO line as input\n");
        gpiod_chip_close(chip);
        gpiod_line_release(line);
        return EXIT_FAILURE;
    }

    struct gpiod_line_event event;
    while (running) {
        if (gpiod_line_event_wait(line, 0) < 0) {
            fprintf(stderr, "Failed to wait for GPIO line event\n");
            break;
        }

        if (gpiod_line_event_read(line, &event) < 0) {
            fprintf(stderr, "Failed to read GPIO line event\n");
            break;
        }

        if (event.event_type == GPIOD_LINE_EVENT_FALLING_EDGE) {
            printf("Flame detected!\n");
            log_event("Flame detected");
        }
    }

    gpiod_line_release(line);
    gpiod_chip_close(chip);
    return EXIT_SUCCESS;
}

#include <stdio.h>
