#define GPIO_CHIP "/dev/gpiochip4"
#define LED_PIN 24
#define TOUCH_PIN 23
#define LOG_FILE "touch_log.txt"

static gpiod_chip *chip;
static gpiod_line *led_line, *touch_line;
static FILE *log_file;
static int running = 1;

static void cleanup() {
    if (led_line) gpiod_line_release(led_line);
    if (touch_line) gpiod_line_release(touch_line);
    if (chip) gpiod_chip_close(chip);
    if (log_file) fclose(log_file);
}

static void sig_handler(int signum) {
    running = 0;
}

int main() {
    struct sigaction action;
    action.sa_handler = sig_handler;
    sigemptyset(&action.sa_mask);
    action.sa_flags = 0;
    sigaction(SIGINT, &action, NULL);
    sigaction(SIGTERM, &action, NULL);

    atexit(cleanup);

    chip = gpiod_chip_open_by_name(GPIO_CHIP);
    if (!chip) {
        fprintf(stderr, "Failed to open GPIO chip %s\n", GPIO_CHIP);
        return EXIT_FAILURE;
    }

    led_line = gpiod_chip_get_line(chip, LED_PIN);
    if (!led_line) {
        fprintf(stderr, "Failed to get LED line\n");
        return EXIT_FAILURE;
    }

    touch_line = gpiod_chip_get_line(chip, TOUCH_PIN);
    if (!touch_line) {
        fprintf(stderr, "Failed to get touch line\n");
        return EXIT_FAILURE;
    }

    if (gpiod_line_request_input(touch_line, "touch_input") < 0) {
        fprintf(stderr, "Failed to request touch line as input\n");
        return EXIT_FAILURE;
    }

    if (gpiod_line_request_output(led_line, "led_output", 0) < 0) {
        fprintf(stderr, "Failed to request LED line as output\n");
        return EXIT_FAILURE;
    }

    log_file = fopen(LOG_FILE, "w");
    if (!log_file) {
        fprintf(stderr, "Failed to open log file %s\n", LOG_FILE);
        return EXIT_FAILURE;
    }

    while (running) {
        struct gpiod_line_event event;
        int ret = gpiod_line_event_wait(touch_line, 1, &event);
        if (ret < 0) {
            fprintf(stderr, "Failed to wait for touch event\n");
            return EXIT_FAILURE;
        }

        if (event.event_type == GPIOD_LINE_EVENT_RISING_EDGE) {
            time_t rawtime;
            struct tm *timeinfo;
            char buffer[20];

            time(&rawtime);
            timeinfo = localtime(&rawtime);
            strftime(buffer, sizeof(buffer), "%Y-%m-%dT%H:%M:%S", timeinfo);

            int led_state = gpiod_line_get_value(led_line);
            fprintf(log_file, "%s: Touch detected, LED state is now %d\n", buffer, led_state);

            gpiod_line_set_value(led_line, !led_state);
        }
    }

    return EXIT_SUCCESS;
}

