#include <gpiod.h>

#define BUZZER_PIN 18
#define FLAME_SENSOR_PIN 17
#define POLL_INTERVAL_MS 500
#define BUZZER_DURATION_MS 2000
#define SLICE_DURATION_MS 100

static gpiod_chip *chip;
static gpiod_line *buzzer_line;
static gpiod_line *flame_sensor_line;
static FILE *log_file;

void cleanup() {
    if (buzzer_line) {
        gpiod_line_set_value(buzzer_line, 0);
        gpiod_line_release(buzzer_line);
    }
    if (flame_sensor_line) {
        gpiod_line_release(flame_sensor_line);
    }
    if (chip) {
        gpiod_chip_close(chip);
    }
    if (log_file) {
        fclose(log_file);
    }
}

void handle_signal(int signum) {
    cleanup();
    exit(0);
}

int main() {
    struct sigaction action;
    action.sa_handler = handle_signal;
    sigemptyset(&action.sa_mask);
    action.sa_flags = 0;
    sigaction(SIGINT, &action, NULL);
    sigaction(SIGTERM, &action, NULL);

    chip = gpiod_chip_open_by_name("gpiochip0");
    if (!chip) {
        fprintf(stderr, "Failed to open GPIO chip: %s\n", strerror(errno));
        return 1;
    }

    buzzer_line = gpiod_chip_get_line(chip, BUZZER_PIN);
    if (!buzzer_line) {
        fprintf(stderr, "Failed to get buzzer line: %s\n", strerror(errno));
        cleanup();
        return 1;
    }

    flame_sensor_line = gpiod_chip_get_line(chip, FLAME_SENSOR_PIN);
    if (!flame_sensor_line) {
        fprintf(stderr, "Failed to get flame sensor line: %s\n", strerror(errno));
        cleanup();
        return 1;
    }

    if (gpiod_line_request_output(buzzer_line, "buzzer", 0) < 0) {
        fprintf(stderr, "Failed to request buzzer line as output: %s\n", strerror(errno));
        cleanup();
        return 1;
    }

    if (gpiod_line_request_input(flame_sensor_line, "flame_sensor") < 0) {
        fprintf(stderr, "Failed to request flame sensor line as input: %s\n", strerror(errno));
        cleanup();
        return 1;
    }

    log_file = fopen("alert_log.txt", "a");
    if (!log_file) {
        fprintf(stderr, "Failed to open log file: %s\n", strerror(errno));
        cleanup();
        return 1;
    }

    fprintf(log_file, "System started\n");
    fflush(log_file);

    int last_value = 1;
    while (1) {
        int current_value = gpiod_line_get_value(flame_sensor_line);
        if (current_value == 0 && last_value == 1) {
            time_t now = time(NULL);
            struct tm *timeinfo = localtime(&now);
            char buffer[80];
            strftime(buffer, sizeof(buffer), "%Y-%m-%d %H:%M:%S", timeinfo);
            fprintf(log_file, "%s: Flame detected\n", buffer);
            fflush(log_file);

            for (int i = 0; i < BUZZER_DURATION_MS / SLICE_DURATION_MS; i++) {
                gpiod_line_set_value(buzzer_line, 1);
                usleep(SLICE_DURATION_MS * 1000);
                gpiod_line_set_value(buzzer_line, 0);
                usleep(SLICE_DURATION_MS * 1000);
            }
        }
        last_value = current_value;
        usleep(POLL_INTERVAL_MS * 1000);
    }

    cleanup();
    return 0;
}

#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
