#include <pigpio.h>

#define GPIO_TOUCH 4
#define GPIO_LED 17
#define DEBOUNCE_TIME 200
#define LOG_FILE "touch_log.txt"

static int running = 1;
static int last_touch_time = 0;

void signal_handler(int signum) {
    running = 0;
}

int main() {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return EXIT_FAILURE;
    }

    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    if (gpioSetMode(GPIO_TOUCH, PI_INPUT) < 0) {
        fprintf(stderr, "Failed to set GPIO%d mode to input\n", GPIO_TOUCH);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    if (gpioSetMode(GPIO_LED, PI_OUTPUT) < 0) {
        fprintf(stderr, "Failed to set GPIO%d mode to output\n", GPIO_LED);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    FILE *log_file = fopen(LOG_FILE, "a");
    if (!log_file) {
        fprintf(stderr, "Failed to open log file '%s'\n", LOG_FILE);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    while (running) {
        int current_time = time(NULL);
        if (gpioRead(GPIO_TOUCH) == PI_LOW && current_time - last_touch_time > DEBOUNCE_TIME / 1000) {
            last_touch_time = current_time;
            gpioToggle(GPIO_LED);
            struct tm *timeinfo = gmtime(&last_touch_time);
            char timestamp[26];
            strftime(timestamp, sizeof(timestamp), "%Y-%m-%dT%H:%M:%SZ", timeinfo);
            fprintf(log_file, "%s: Touch detected\n", timestamp);
            fflush(log_file);
        }
        gpioDelay(10000); // 10 ms
    }

    fclose(log_file);
    gpioTerminate();
    return EXIT_SUCCESS;
}

#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <pigpio.h>

#define SENSOR_COUNT 3
#define GPIO_PINS {4, 17, 27}
#define LOG_FILE "magnet_log.txt"

int main() {
    int gpios[SENSOR_COUNT] = GPIO_PINS;
    int initial_states[SENSOR_COUNT] = {0};
    int current_states[SENSOR_COUNT] = {0};
    int i, j;
    time_t now;
    struct tm *timeinfo;
    char buffer[80];

    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return EXIT_FAILURE;
    }

    FILE *log_file = fopen(LOG_FILE, "w");
    if (!log_file) {
        fprintf(stderr, "Failed to open log file\n");
        gpioTerminate();
        return EXIT_FAILURE;
    }

    for (i = 0; i < SENSOR_COUNT; i++) {
        if (gpioSetMode(gpios[i], PI_INPUT) < 0) {
            fprintf(stderr, "Failed to set GPIO %d mode\n", gpios[i]);
            goto cleanup;
        }
        if (gpioSetPullUpDown(gpios[i], PI_PUD_UP) < 0) {
            fprintf(stderr, "Failed to set GPIO %d pull-up\n", gpios[i]);
            goto cleanup;
        }
        initial_states[i] = gpioRead(gpios[i]);
        current_states[i] = initial_states[i];
    }

    while (1) {
        for (i = 0; i < SENSOR_COUNT; i++) {
            int new_state = gpioRead(gpios[i]);
            if (new_state != current_states[i]) {
                time(&now);
                timeinfo = localtime(&now);
                strftime(buffer, sizeof(buffer), "%Y-%m-%dT%H:%M:%S", timeinfo);
                fprintf(log_file, "%s Sensor %d: %s\n", buffer, i + 1, new_state ? "Removed" : "Present");
                fflush(log_file);
                current_states[i] = new_state;
            }
        }
        gpioDelay(100000000); // 100 ms
    }

cleanup:
    fclose(log_file);
    gpioTerminate();
    return EXIT_FAILURE;
}

#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <pigpio.h>

#define PART_ID 0x02
#define HW_REV 0x01
#define LED_CURRENT 0x3F
#define AVERAGING 0x04
#define ENABLE 0x01
#define HR_MSB 0x2A
#define HR_LSB 0x2B
#define MOVING_AVERAGE_SIZE 5

volatile sig_atomic_t stop = 0;

void handler(int signum) {
    stop = 1;
}

int main() {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return EXIT_FAILURE;
    }

    int i2c_handle = i2cOpen(1, 0x4A, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Failed to open I2C bus\n");
        gpioTerminate();
        return EXIT_FAILURE;
    }

    uint8_t part_id = i2cReadByteData(i2c_handle, 0x00);
    uint8_t hw_rev = i2cReadByteData(i2c_handle, 0x01);
    if (part_id != PART_ID || hw_rev != HW_REV) {
        fprintf(stderr, "Sensor is absent or wrong\n");
        i2cClose(i2c_handle);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    i2cWriteByteData(i2c_handle, LED_CURRENT, 0x3F);
    i2cWriteByteData(i2c_handle, AVERAGING, 0x04);
    i2cWriteByteData(i2c_handle, ENABLE, 0x01);

    FILE *log_file = fopen("heart_rate.csv", "w");
    if (log_file == NULL) {
        fprintf(stderr, "Failed to open log file\n");
        i2cClose(i2c_handle);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    signal(SIGINT, handler);

    int moving_average[MOVING_AVERAGE_SIZE] = {0};
    int moving_average_index = 0;
    int bpm = 0;

    while (!stop) {
        int hr_raw = i2cReadWordData(i2c_handle, HR_MSB);
        if (hr_raw < 0) {
            continue;
        }

        bpm = (int)(hr_raw * 0.5);

        moving_average[moving_average_index] = bpm;
        moving_average_index = (moving_average_index + 1) % MOVING_AVERAGE_SIZE;

        int sum = 0;
        for (int i = 0; i < MOVING_AVERAGE_SIZE; i++) {
            sum += moving_average[i];
        }

        int average_bpm = sum / MOVING_AVERAGE_SIZE;

        if (average_bpm >= 30 && average_bpm <= 220) {
            time_t now = time(NULL);
            struct tm *t = localtime(&now);
            char buffer[20];
            strftime(buffer, sizeof(buffer), "%Y-%m-%d %H:%M:%S", t);
            fprintf(log_file, "%s,%d\n", buffer, average_bpm);
            fflush(log_file);
        }
    }

    fclose(log_file);
    i2cClose(i2c_handle);
    gpioTerminate();
    return EXIT_SUCCESS;
}

#include <stdio.h>
#include <stdlib.h>
#include <signal.h>
#include <time.h>
#include <libgpiod.h>

#define GPIO_PIN 17
#define FLAME_DETECTED "FLAME DETECTED\n"
#define LOG_FILE "flame_log.txt"

static gpiod_chip *chip;
static gpiod_line *line;
static FILE *log_file;
static int running = 1;

void sig_handler(int signum) {
    if (signum == SIGINT || signum == SIGTERM) {
        running = 0;
    }
}

int main() {
    struct timespec ts = {0, 100000000}; // 100 ms

    // Register signal handler
    signal(SIGINT, sig_handler);
    signal(SIGTERM, sig_handler);

    // Open GPIO chip
    chip = gpiod_chip_open("/dev/gpiochip0");
    if (!chip) {
        fprintf(stderr, "Failed to open GPIO chip\n");
