#define GPIO_COUNT 8
#define LOG_FILE "touch_log.txt"
#define POLL_INTERVAL 10
#define STABILIZE_DELAY 200

static volatile sig_atomic_t running = 1;
static gpiod_chip *chip;
static gpiod_line_bulk lines;
static uint8_t counter = 0;
static uint8_t channel_states[GPIO_COUNT] = {0};

static void handle_signal(int signum) {
    running = 0;
}

static void log_touch(int channel) {
    time_t now = time(NULL);
    struct tm *t = localtime(&now);
    char buffer[26];
    strftime(buffer, sizeof(buffer), "%Y-%m-%dT%H:%M:%SZ", t);
    printf("Touch on channel %d | Counter: %d\n", channel, counter);
    fprintf(stderr, "%s, Channel: %d, Counter: %d\n", buffer, channel, counter);
}

static void update_outputs() {
    for (int i = 0; i < GPIO_COUNT; i++) {
        gpiod_line_set_value(lines.lines[i], (counter >> i) & 1);
    }
}

static void process_touch(int channel) {
    if (channel_states[channel] == 0) {
        counter = (counter + 1) & 0xFF;
        update_outputs();
        log_touch(channel);
    }
    channel_states[channel] = 1;
}

static void reset_outputs() {
    for (int i = 0; i < GPIO_COUNT; i++) {
        gpiod_line_set_value(lines.lines[i], 0);
    }
}

static void cleanup() {
    reset_outputs();
    gpiod_chip_close(chip);
}

int main() {
    struct sigaction sa = {
        .sa_handler = handle_signal,
        .sa_flags = SA_RESTART
    };
    sigaction(SIGINT, &sa, NULL);
    sigaction(SIGTERM, &sa, NULL);

    chip = gpiod_chip_open("/dev/gpiochip0");
    if (!chip) {
        fprintf(stderr, "Failed to open GPIO chip: %s\n", strerror(errno));
        return EXIT_FAILURE;
    }

    gpiod_line_bulk_init(&lines);
    for (int i = 0; i < GPIO_COUNT; i++) {
        gpiod_line *line = gpiod_chip_get_line(chip, 5 + i);
        if (!line) {
            fprintf(stderr, "Failed to get line %d: %s\n", 5 + i, strerror(errno));
            cleanup();
            return EXIT_FAILURE;
        }
        gpiod_line_request req = {
            .consumer = "touch_counter",
            .flags = GPIO_LINE_REQUEST_FLAG_BIAS_PULL_UP,
            .events = GPIO_LINE_EVENT_BOTH_EDGES,
        };
        if (gpiod_line_request_enable(line, &req) < 0) {
            fprintf(stderr, "Failed to request line %d: %s\n", 5 + i, strerror(errno));
            cleanup();
            return EXIT_FAILURE;
        }
        gpiod_line_bulk_add(&lines, line);
    }

    if (gpiod_chip_request_lines(chip, &lines) < 0) {
        fprintf(stderr, "Failed to request lines: %s\n", strerror(errno));
        cleanup();
        return EXIT_FAILURE;
    }

    usleep(STABILIZE_DELAY * 1000);

    FILE *log_file = fopen(LOG_FILE, "a");
    if (!log_file) {
        fprintf(stderr, "Failed to open log file: %s\n", strerror(errno));
    }

    while (running) {
        for (int i = 0; i < GPIO_COUNT; i++) {
            gpiod_line_event event;
            if (gpiod_line_event_read(lines.lines[i], &event) < 0) {
                fprintf(stderr, "Failed to read line event: %s\n", strerror(errno));
                continue;
            }
            if (event.event_type == GPIO_LINE_EVENT_RISING_EDGE) {
                process_touch(i);
            }
        }
        usleep(POLL_INTERVAL * 1000);
    }

    fclose(log_file);
    cleanup();
    return EXIT_SUCCESS;
}

