void log_event(int sensor) {
    time_t now = time(NULL);
    struct tm *t = localtime(&now);
    char buffer[80];
    strftime(buffer, sizeof(buffer), "%Y-%m-%d %H:%M:%S", t);
    fprintf(log_file, "%s, Sensor %d tilted\n", buffer, sensor);
    fflush(log_file);
}

void handle_signal(int signum) {
    gpiod_line_release(line17);
    gpiod_line_release(line18);
    gpiod_chip_close(chip);
    fclose(log_file);
    exit(signum);
}

int main() {
    struct sigaction action;
    memset(&action, 0, sizeof(struct sigaction));
    action.sa_handler = handle_signal;
    sigaction(SIGINT, &action, NULL);
    sigaction(SIGTERM, &action, NULL);

    log_file = fopen(LOG_FILE, "a");
    if (!log_file) {
        fprintf(stderr, "Failed to open log file\n");
        return 1;
    }

    chip = gpiod_chip_open_by_name("gpiochip0");
    if (!chip) {
        fprintf(stderr, "Failed to open GPIO chip\n");
        return 1;
    }

    line17 = gpiod_chip_get_line(chip, GPIO17);
    if (!line17) {
        fprintf(stderr, "Failed to get line 17\n");
        return 1;
    }

    line18 = gpiod_chip_get_line(chip, GPIO18);
    if (!line18) {
        fprintf(stderr, "Failed to get line 18\n");
        return 1;
    }

    gpiod_line_request_input(line17, "Sensor 1", GPIOD_LINE_REQUEST_FLAG_BIAS_PULL_UP);
    gpiod_line_request_input(line18, "Sensor 2", GPIOD_LINE_REQUEST_FLAG_BIAS_PULL_UP);

    int last_value17 = 1, last_value18 = 1;
    struct timespec last_event17 = {0, 0}, last_event18 = {0, 0};

    while (1) {
        int value17 = gpiod_line_get_value(line17);
        int value18 = gpiod_line_get_value(line18);

        if (value17 == 0 && value17 != last_value17) {
            struct timespec now = {0, 0};
            clock_gettime(CLOCK_REALTIME, &now);
            if (now.tv_sec - last_event17.tv_sec > DEBOUNCE_TIME / 1000) {
                log_event(1);
                last_event17 = now;
            }
        }

        if (value18 == 0 && value18 != last_value18) {
            struct timespec now = {0, 0};
            clock_gettime(CLOCK_REALTIME, &now);
            if (now.tv_sec - last_event18.tv_sec > DEBOUNCE_TIME / 1000) {
                log_event(2);
                last_event18 = now;
            }
        }

        last_value17 = value17;
        last_value18 = value18;

        nanosleep((struct timespec[]){{0, POLL_TIME * 1000 * 1000L}}, NULL);
    }

    return 0;
}

