volatile sig_atomic_t stop_flag = 0;

void signal_handler(int signum) {
    stop_flag = 1;
}

int main() {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialization failed\n");
        return EXIT_FAILURE;
    }

    if (signal(SIGINT, signal_handler) == SIG_ERR) {
        fprintf(stderr, "signal handler setup failed\n");
        gpioTerminate();
        return EXIT_FAILURE;
    }

    int mic_gpio = 4;
    int led_gpio = 17;

    if (gpioSetMode(mic_gpio, PI_INPUT) != 0) {
        fprintf(stderr, "failed to set GPIO%d mode to input\n", mic_gpio);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    if (gpioSetMode(led_gpio, PI_OUTPUT) != 0) {
        fprintf(stderr, "failed to set GPIO%d mode to output\n", led_gpio);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    uint32_t last_high_time = 0;
    while (!stop_flag) {
        if (gpioRead(mic_gpio) == PI_HIGH) {
            uint32_t current_time = gpioTick();
            if (last_high_time == 0 || (current_time - last_high_time) > 125000) {
                printf("%u\n", current_time / 1000);
                gpioWrite(led_gpio, PI_HIGH);
                gpioDelay(100000);
                gpioWrite(led_gpio, PI_LOW);
                last_high_time = current_time;
            }
        }
        gpioDelay(1250);
    }

    gpioTerminate();
    return EXIT_SUCCESS;
}

