#define ALS_MSB_REG 0x25

int main() {
    int file;
    char *filename = "/dev/i2c-1";
    uint8_t buffer[2];
    int16_t raw_value;
    int ret;

    if ((file = open(filename, O_RDWR)) < 0) {
        perror("Failed to open the i2c bus");
        exit(1);
    }

    if (ioctl(file, I2C_SLAVE, SENSOR_ADDRESS) < 0) {
        perror("Failed to acquire bus access and/or talk to slave");
        close(file);
        exit(1);
    }

    while (1) {
        // Read LSB
        ret = read(file, buffer, 1);
        if (ret != 1) {
            perror("Failed to read LSB");
            break;
        }

        // Read MSB
        ret = read(file, buffer + 1, 1);
        if (ret != 1) {
            perror("Failed to read MSB");
            break;
        }

        // Combine LSB and MSB into a 16-bit value
        raw_value = (buffer[1] << 8) | buffer[0];

        // Log the raw sensor values
        printf("Raw sensor value: %d\n", raw_value);

        // Wait for 100 ms
        usleep(100000);
    }

    close(file);
    return 0;
}

