#define GPIO_CHIP "/dev/gpiochip0"
#define GPIO_LINES "5,6,13,19,26,12,16,20"

static struct gpiod_chip *chip;
static struct gpiod_line_bulk lines;
static int running = 1;

static void cleanup(void) {
    if (lines.lines) {
        gpiod_line_release_bulk(&lines);
    }
    if (chip) {
        gpiod_chip_close(chip);
    }
}

static void sig_handler(int signum) {
    running = 0;
}

int main() {
    struct timespec ts;
    int ret, i, value;
    char buffer[256];

    // Register signal handlers
    signal(SIGINT, sig_handler);
    signal(SIGTERM, sig_handler);

    // Open GPIO chip
    chip = gpiod_chip_open(GPIO_CHIP);
    if (!chip) {
        fprintf(stderr, "Failed to open GPIO chip %s\n", GPIO_CHIP);
        return EXIT_FAILURE;
    }

    // Request lines
    ret = gpiod_chip_get_lines(chip, GPIO_LINES, &lines);
    if (ret < 0) {
        fprintf(stderr, "Failed to request lines %s from chip %s\n", GPIO_LINES, GPIO_CHIP);
        cleanup();
        return EXIT_FAILURE;
    }

    // Set lines as inputs
    ret = gpiod_line_request_bulk(&lines, GPIO_LINE_REQUEST_DIRECTION_INPUT);
    if (ret < 0) {
        fprintf(stderr, "Failed to set lines %s as inputs\n", GPIO_LINES);
        cleanup();
        return EXIT_FAILURE;
    }

    // Main loop
    while (running) {
        clock_gettime(CLOCK_MONOTONIC, &ts);
        printf("[%ld.%09lds] ", ts.tv_sec, ts.tv_nsec);

        for (i = 0; i < lines.count; i++) {
            ret = gpiod_line_get_value(lines.lines[i]);
            if (ret < 0) {
                fprintf(stderr, "Failed to read line %d\n", lines.lines[i]->offset);
                cleanup();
                return EXIT_FAILURE;
            }
            value = ret ? 1 : 0;
            printf("CH%d=%d ", i + 1, value);
        }
        printf("\n");

        // Sleep for a bit
        nanosleep((const struct timespec[]){{0, 200000000L}}, NULL);
    }

    // Cleanup
    cleanup();
    return EXIT_SUCCESS;
}

