void hsv_to_rgb(float h, float s, float v, uint8_t *r, uint8_t *g, uint8_t *b) {
    int i;
    float f, p, q, t;

    if (s == 0) {
        *r = *g = *b = (uint8_t)(v * PWM_RANGE);
        return;
    }

    h /= 60;
    i = (int)h;
    f = h - i;
    p = v * (1 - s);
    q = v * (1 - s * f);
    t = v * (1 - s * (1 - f));

    switch (i) {
        case 0:
            *r = (uint8_t)(v * PWM_RANGE);
            *g = (uint8_t)(t * PWM_RANGE);
            *b = (uint8_t)(p * PWM_RANGE);
            break;
        case 1:
            *r = (uint8_t)(q * PWM_RANGE);
            *g = (uint8_t)(v * PWM_RANGE);
            *b = (uint8_t)(p * PWM_RANGE);
            break;
        case 2:
            *r = (uint8_t)(p * PWM_RANGE);
            *g = (uint8_t)(v * PWM_RANGE);
            *b = (uint8_t)(t * PWM_RANGE);
            break;
        case 3:
            *r = (uint8_t)(p * PWM_RANGE);
            *g = (uint8_t)(q * PWM_RANGE);
            *b = (uint8_t)(v * PWM_RANGE);
            break;
        case 4:
            *r = (uint8_t)(t * PWM_RANGE);
            *g = (uint8_t)(p * PWM_RANGE);
            *b = (uint8_t)(v * PWM_RANGE);
            break;
        default:
            *r = (uint8_t)(v * PWM_RANGE);
            *g = (uint8_t)(p * PWM_RANGE);
            *b = (uint8_t)(q * PWM_RANGE);
            break;
    }
