#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <stdbool.h>
#include <string.h>
#include <unistd.h>
#include <fcntl.h>
#include <signal.h>
#include <sys/ioctl.h>
#include <linux/i2c-dev.h>
#include <libgpiod.h>

#define TCS34725_ADDRESS 0x29
#define TCS34725_ID 0x44
#define TCS34725_COMMAND_BIT 0x80
#define TCS34725_ENABLE_PON (1 << 0)
#define TCS34725_ENABLE_AEN (1 << 1)
#define TCS34725_INTEGRATION_TIME_154MS 0x00
#define TCS34725_GAIN_1X 0x00
#define TCS34725_CHANNEL_CLEAR 0x14
#define TCS34725_CHANNEL_RED 0x16
#define TCS34725_CHANNEL_GREEN 0x18
#define TCS34725_CHANNEL_BLUE 0x1A
#define TCS34725_THRESHOLD 200
#define GPIO17 17

static int i2c_fd = -1;
static struct gpiod_line *led_line = NULL;

static void cleanup(void) {
    if (led_line) {
        gpiod_line_set_value(led_line, 0);
        gpiod_line_release(led_line);
    }
    if (i2c_fd >= 0) {
        close(i2c_fd);
    }
}

static void sig_handler(int signum) {
    cleanup();
    exit(signum);
}

static int i2c_write_byte(uint8_t reg, uint8_t data) {
    struct i2c_rdwr_ioctl_data packets;
    struct i2c_msg messages[1];
    uint8_t buffer[2];

    buffer[0] = reg;
    buffer[1] = data;
    messages[0].addr = TCS34725_ADDRESS;
    messages[0].flags = 0;
    messages[0].len = 2;
    messages[0].buf = buffer;

    packets.msgs = messages;
    packets.nmsgs = 1;

    return ioctl(i2c_fd, I2C_RDWR, &packets);
}

static int i2c_read_word(uint8_t reg, uint16_t *data) {
    struct i2c_rdwr_ioctl_data packets;
    struct i2c_msg messages[2];
    uint8_t buffer[2];

    messages[0].addr = TCS34725_ADDRESS;
    messages[0].flags = 0;
    messages[0].len = 1;
    messages[0].buf = &reg;
    messages[1].addr = TCS34725_ADDRESS;
    messages[1].flags = I2C_M_RD;
    messages[1].len = 2;
    messages[1].buf = buffer;

    packets.msgs = messages;
    packets.nmsgs = 2;

    if (ioctl(i2c_fd, I2C_RDWR, &packets) < 0) {
        return -1;
    }

    *data = (buffer[1] << 8) | buffer[0];
    return 0;
}

static void read_sensor(void) {
    uint16_t clear, red, green, blue;
    int ret;

    ret = i2c_read_word(TCS34725_CHANNEL_CLEAR, &clear);
    if (ret < 0) {
        printf("Failed to read clear channel\n");
        return;
    }

    ret = i2c_read_word(TCS34725_CHANNEL_RED, &red);
    if (ret < 0) {
        printf("Failed to read red channel\n");
        return;
    }

    ret = i2c_read_word(TCS34725_CHANNEL_GREEN, &green);
    if (ret < 0) {
        printf("Failed to read green channel\n");
        return;
    }

    ret = i2c_read_word(TCS34725_CHANNEL_BLUE, &blue);
    if (ret < 0) {
        printf("Failed to read blue channel\n");
        return;
    }

    printf("Clear: %d, Red: %d, Green: %d, Blue: %d\n", clear, red, green, blue);

    if (red > TCS34725_THRESHOLD) {
        gpiod_line_set_value(led_line, 1);
    } else {
        gpiod_line_set_value(led_line, 0);
    }
}

int main(void) {
    struct gpiod_chip *chip;
    struct sigaction action;
    int ret;

    action.sa_handler = sig_handler;
    sigemptyset(&action.sa_mask);
    action.sa_flags = 0;
    sigaction(SIGINT, &action, NULL);
    sigaction(SIGTERM, &action, NULL);

    chip = gpiod_chip_open("/dev/gpiochip0");
    if (!chip) {
        printf("Failed to open GPIO chip\n");
        return EXIT_FAILURE;
    }

    led_line = gpiod_chip_get_line(chip, GPIO17);
    if (!led_line) {
        printf("Failed to get LED line\n");
        gpiod_chip_close(chip);
        return EXIT_FAILURE;
    }

    ret = gpiod_line_request_output(led_line, "led", 0);
    if (ret < 0) {
        printf("Failed to request LED line as output\n");
        gpiod_chip_close(chip);
        return EXIT_FAILURE;
    }

    i2c_fd = open("/dev/i2c-1", O_RDWR);
    if (i2c_fd < 0) {
        printf("Failed to open I2C device\n");
        gpiod_chip_close(chip);
        return EXIT_FAILURE;
    }

    ret = i2c_write_byte(TCS34725_COMMAND_BIT | 0x00, TCS34725_ENABLE_PON);
    if (ret < 0) {
        printf("Failed to write enable register\n");
        cleanup();
        return EXIT_FAILURE;
    }

    usleep(1000);

    ret = i2c_write_byte(TCS34725_COMMAND_BIT | 0x01, TCS34725_ENABLE_PON | TCS34725_ENABLE_AEN);
    if (ret < 0) {
        printf("Failed to write enable register\n");
        cleanup();
        return EXIT_FAILURE;
    }

    ret = i2c_write_byte(TCS34725_COMMAND_BIT | 0x0F, TCS34725_INTEGRATION_TIME_154MS);
    if (ret < 0) {
        printf("Failed to write integration time register\n");
        cleanup();
        return EXIT_FAILURE;
    }

    ret = i2c_write_byte(TCS34725_COMMAND_BIT | 0x0E, TCS34725_GAIN_1X);
    if (ret < 0) {
        printf("Failed to write gain register\n");
        cleanup();
        return EXIT_FAILURE;
    }

    uint8_t id;
    ret = i2c_read_word(TCS34725_COMMAND_BIT | 0x12, (uint16_t *)&id);
    if (ret < 0 || id != TCS34725_ID) {
        printf("Failed to read sensor ID or incorrect ID\n");
        cleanup();
        return EXIT_FAILURE;
    }

    while (true) {
        read_sensor();
        usleep(200000);
    }

    cleanup();
    return EXIT_SUCCESS;
}

#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <signal.h>
#include <pigpio.h>
#include <i2c.h>

#define LED_COUNT 10
#define I2C_ADDRESS 0x23
#define I2C_BUS 1
#define GPIO_PIN 18
#define PWM_FREQ 800000
#define PWM_DUTY_MIN 0
#define PWM_DUTY_MAX 255

volatile sig_atomic_t stop = 0;

void signal_handler(int signum) {
    stop = 1;
}

int main() {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return EXIT_FAILURE;
    }

    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    int i2c_handle = i2cOpen(I2C_BUS, I2C_ADDRESS, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "I2C open failed\n");
        gpioTerminate();
        return EXIT_FAILURE;
    }

    uint8_t buffer[2];
    uint16_t lux;
    int brightness;

    gpioSetMode(GPIO_PIN, PI_OUTPUT);
    gpioPWMSetMode(PI_PWMMODE_BAL);
    gpioPWMSetRange(GPIO_PIN, PWM_DUTY_MAX);
    gpioPWMSetData(GPIO_PIN, PWM_DUTY_MIN);

    while (!stop) {
        if (i2cReadFile(i2c_handle, buffer, 2) != 2) {
            fprintf(stderr, "I2C read failed\n");
            continue;
        }

        lux = (buffer[0] << 8) | buffer[1];
        lux /= 1.2;

        brightness = (int)((log10((double)lux / 1000.0) + 1.0) * PWM_DUTY_MAX / 2.0);

        if (brightness < PWM_DUTY_MIN) brightness = PWM_DUTY_MIN;
        if (brightness > PWM_DUTY_MAX) brightness = PWM_DUTY_MAX;

        gpioPWMSetData(GPIO_PIN, brightness);

        usleep(180000);
    }

    i2cClose(i2c_handle);
    gpioTerminate();

    return EXIT_SUCCESS;
}

#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <stdbool.h>
#include <string.h>
#include <unistd.h>
#include <fcntl.h>
#include <signal.h>
#include <sys/ioctl.h>
#include <linux/i2c-dev.h>
#include <linux/spi/spidev.h>

#define BH1750_ADDRESS 0x23
#define APA102_CLOCK 1000000
#define APA102_LEDS 30

static int i2c_fd, spi_fd;
static uint16_t lux;
static uint8_t brightness;

static void cleanup(int signum) {
    uint32_t end_frame = 0xFF000000;
    write(spi_fd, &end_frame, sizeof(end_frame));
    close(i2c_fd);
    close(spi_fd);
    exit(signum);
}

static void init() {
    struct sigaction action;
    action.sa_handler = cleanup;
    sigemptyset(&action.sa_mask);
    action.sa_flags = 0;
    sigaction(SIGINT, &action, NULL);

    i2c_fd = open("/dev/i2c-1", O_RDWR);
    if (i2c_fd < 0) {
        perror("Failed to open i2c device");
        exit(1);
    }
    if (ioctl(i2c_fd, I2C_SLAVE, BH1750_ADDRESS) < 0) {
        perror("Failed to acquire bus access and/or talk to slave");
        exit(1);
    }

    spi_fd = open("/dev/spidev0.0", O_RDWR);
    if (spi_fd < 0) {
        perror("Failed to open spi device");
        exit(1);
    }
    uint8_t mode = SPI_MODE_0;
    uint8_t bits = 8;
    uint32_t speed = APA102_CLOCK;
    if (ioctl(spi_fd, SPI_IOC_WR_MODE, &mode) < 0 ||
        ioctl(spi_fd, SPI_IOC_WR_BITS_PER_WORD, &bits) < 0 ||
        ioctl(spi_fd, SPI_IOC_WR_MAX_SPEED_HZ, &speed) < 0) {
        perror("Failed to configure spi device");
        exit(1);
    }
}

static void read_lux() {
    uint8_t command = 0x20;
    if (write(i2c_fd, &command, sizeof(command)) < 0) {
        perror("Failed to write command to BH1750");
        exit(1);
    }
    usleep(120000);
    uint16_t raw;
    if (read(i2c_fd, &raw, sizeof(raw)) < 0) {
        perror("Failed to read from BH1750");
        exit(1);
    }
    lux = raw / 1.2;
}

static void set_brightness() {
    if (lux < 10) brightness = 0;
    else if (lux > 300) brightness = 31;
    else brightness = (lux - 10) / 10;
}

static void write_leds() {
    uint32_t start_frame = 0x00000000;
    uint32_t end_frame = 0xFF000000;
    write(spi_fd, &start_frame, sizeof(start_frame));
    for (int i = 0; i < APA102_LEDS; i++) {
        uint32_t led_frame = (0xE0 | brightness) << 24;
        write(spi_fd, &led_frame, sizeof(led_frame));
    }
    write(spi_fd, &end_frame, sizeof(end_frame));
}

int main() {
    init();
    while (true) {
        read_lux();
        set_brightness();
        write_leds();
    }
    return 0;
}

