#include <linux/i2c-dev.h>
#include <libgpiod.h>

#define I2C_BUS "/dev/i2c-1"
#define VEML7700_ADDRESS 0x10
#define WS2812B_PIN 18
#define INTEGRATION_TIME 100 // ms
#define GAIN 1.0/8.0
#define GAMMA 1.0/2.2
#define MAX_LUX 120000
#define I2C_RETRIES 3
#define I2C_RETRY_DELAY 100 // ms

static int i2c_fd = -1;
static struct gpiod_line *ws2812b_line = NULL;
static bool running = true;

static void cleanup() {
    if (ws2812b_line) {
        gpiod_line_set_value(ws2812b_line, 0);
        gpiod_line_release(ws2812b_line);
    }
    if (i2c_fd >= 0) {
        close(i2c_fd);
    }
}

static void sig_handler(int signum) {
    running = false;
}

static uint16_t read_i2c_reg(uint8_t reg) {
    uint8_t buf[2] = {reg};
    if (write(i2c_fd, buf, 1) != 1) {
        return 0;
    }
    if (read(i2c_fd, buf, 2) != 2) {
        return 0;
    }
    return (buf[0] << 8) | buf[1];
}

static void write_i2c_reg(uint8_t reg, uint16_t value) {
    uint8_t buf[3] = {reg, value >> 8, value & 0xFF};
    write(i2c_fd, buf, 3);
}

static void set_ws2812b_brightness(uint8_t brightness) {
    // Bit-banging WS2812B at 800 kHz
    // ...
}

int main() {
    signal(SIGINT, sig_handler);
    signal(SIGTERM, sig_handler);

    atexit(cleanup);

    i2c_fd = open(I2C_BUS, O_RDWR);
    if (i2c_fd < 0) {
        perror("Failed to open I2C bus");
        return EXIT_FAILURE;
    }

    if (ioctl(i2c_fd, I2C_SLAVE, VEML7700_ADDRESS) < 0) {
        perror("Failed to set I2C address");
        return EXIT_FAILURE;
    }

    write_i2c_reg(0x00, 0x0000); // Configure VEML7700

    ws2812b_line = gpiod_line_request_output(WS2812B_PIN, "ws2812b", 0);
    if (!ws2812b_line) {
        perror("Failed to request WS2812B GPIO line");
        return EXIT_FAILURE;
    }

    while (running) {
        uint16_t raw = read_i2c_reg(0x04);
        if (raw == 0) {
            continue;
        }

        uint32_t lux = raw * 0.0036 * GAIN * (100.0 / INTEGRATION_TIME);
        uint8_t brightness = (uint8_t)(255.0 * pow(lux / MAX_LUX, GAMMA));

        set_ws2812b_brightness(brightness);

        printf("Lux: %u, Brightness: %u\n", lux, brightness);

        usleep(200000); // 200 ms
    }

    return EXIT_SUCCESS;
}

#include <stdio.h>
#include <stdlib.h>
#include <signal.h>
#include <time.h>
#include <gpiod.h>

#define BUZZER_PIN 17
#define LED_PIN 18
#define FLAME_SENSOR_PIN 4
#define SELF_TEST_COUNT 5
#define SELF_TEST_ERROR_BLINKS 5
#define SELF_TEST_ERROR_SOUNDS 3
#define SELF_TEST_ERROR_SOUND_DURATION 200
#define MAIN_LOOP_POLLING_INTERVAL 50
#define MAIN_LOOP_DEBOUNCE_INTERVAL 100
#define ERROR_LOG(...) fprintf(stderr, __VA_ARGS__)

static struct gpiod_chip *chip;
static struct gpiod_line *buzzer_line;
static struct gpiod_line *led_line;
static struct gpiod_line *flame_sensor_line;
static int self_test_passed = 0;

static void cleanup() {
    gpiod_line_release(buzzer_line);
    gpiod_line_release(led_line);
    gpiod_line_release(flame_sensor_line);
    gpiod_chip_close(chip);
}

static void signal_handler(int signum) {
    cleanup();
    exit(1);
}

static void self_test() {
    int i, count = 0;
    for (i = 0; i < SELF_TEST_COUNT; i++) {
        gpiod_line_set_value(led_line, 1);
        gpiod_line_set_value(buzzer_line, 0);
        usleep(500000);
        gpiod_line_set_value(led_line, 0);
        gpiod_line_set_value(buzzer_line, 0);
        usleep(500000);
        if (!gpiod_line_get_value(flame_sensor_line)) {
            count++;
        }
    }
    if (count == SELF_TEST_COUNT) {
        self_test_passed = 0;
        ERROR_LOG("Self-test failed: Sensor fault\n");
        return;
    }
    self_test_passed = 1;
    ERROR_LOG("Self-test passed\n");
}

static void error_blink() {
    int i;
    for (i = 0; i < SELF_TEST_ERROR_BLINKS; i++) {
        gpiod_line_set_value(led_line, 1);
        gpiod_line_set_value(buzzer_line, 0);
        usleep(100000);
        gpiod_line_set_value(led_line, 0);
        gpiod_line_set_value(buzzer_line, 0);
        usleep(100000);
    }
}

static void error_sound() {
    int i;
    for (i = 0; i < SELF_TEST_ERROR_SOUNDS; i++) {
        gpiod_line_set_value(buzzer_line, 1);
        usleep(SELF_TEST_ERROR_SOUND_DURATION * 1000);
        gpiod_line_set_value(buzzer_line, 0);
        usleep(SELF_TEST_ERROR_SOUND_DURATION * 1000);
        gpiod_line_set_value(buzzer_line, 1);
        usleep(SELF_TEST_ERROR_SOUND_DURATION * 1000);
        gpiod_line_set_value(buzzer_line, 0);
        usleep(SELF_TEST_ERROR_SOUND_DURATION * 1000);
    }
}

int main() {
    struct sigaction action;
    action.sa_handler = signal_handler;
    sigemptyset(&action.sa_mask);
    action.sa_flags = 0;
    sigaction(SIGINT, &action, NULL);

    chip = gpiod_chip_open("/dev/gpiochip0");
    if (!chip) {
        ERROR_LOG("Failed to open GPIO chip\n");
        return 1;
    }

    buzzer_line = gpiod_chip_get_line(chip, BUZZER_PIN);
    if (!buzzer_line) {
        ERROR_LOG("Failed to get buzzer line\n");
        cleanup();
        return 1;
    }

    led_line = gpiod_chip_get_line(chip, LED_PIN);
    if (!led_line) {
        ERROR_LOG("Failed to get LED line\n");
        cleanup();
        return 1;
    }

    flame_sensor_line = gpiod_chip_get_line(chip, FLAME_SENSOR_PIN);
    if (!flame_sensor_line) {
        ERROR_LOG("Failed to get flame sensor line\n");
        cleanup();
        return 1;
    }

    self_test();
    if (!self_test_passed) {
        error_blink();
        error_sound();
        cleanup();
        return 1;
    }

    gpiod_line_set_value(led_line, 0);
    gpiod_line_set_value(buzzer_line, 0);

    while (1) {
        if (!gpiod_line_get_value(flame_sensor_line)) {
            gpiod_line_set_value(buzzer_line, 1);
            gpiod_line_set_value(led_line, 1);
            usleep(MAIN_LOOP_DEBOUNCE_INTERVAL * 1000);
            while (!gpiod_line_get_value(flame_sensor_line)) {
                usleep(MAIN_LOOP_POLLING_INTERVAL * 1000);
            }
            gpiod_line_set_value(buzzer_line, 0);
            gpiod_line_set_value(led_line, 0);
        }
        usleep(MAIN_LOOP_POLLING_INTERVAL * 1000);
    }

    cleanup();
    return 0;
}

