#include <stdio.h>
#include <stdlib.h>
#include <stdbool.h>
#include <libgpiod.h>

#define DATA_PIN 17
#define CLOCK_PIN 18
#define LATCH_PIN 27

void shift_out(uint8_t data) {
    for (int i = 0; i < 8; i++) {
        gpiod_set_value(chip, clock_pin, (data >> i) & 1);
        gpiod_set_value(chip, data_pin, 1);
        gpiod_set_value(chip, clock_pin, 0);
    }
    gpiod_set_value(chip, latch_pin, 1);
    gpiod_set_value(chip, latch_pin, 0);
}

int main() {
    struct gpiod_chip *chip;
    struct gpiod_line *data_pin_line, *clock_pin_line, *latch_pin_line;
    uint8_t digit_5 = 0b00110000; // 5 in common-cathode seven-segment display format

    chip = gpiod_chip_open("/dev/gpiochip0");
    if (!chip) {
        fprintf(stderr, "Failed to open GPIO chip\n");
        return EXIT_FAILURE;
    }

    data_pin_line = gpiod_chip_get_line(chip, DATA_PIN);
    clock_pin_line = gpiod_chip_get_line(chip, CLOCK_PIN);
    latch_pin_line = gpiod_chip_get_line(chip, LATCH_PIN);

    if (!data_pin_line || !clock_pin_line || !latch_pin_line) {
        fprintf(stderr, "Failed to get GPIO lines\n");
        goto cleanup;
    }

    if (gpiod_line_request_output(data_pin_line, "data_pin", 0) ||
        gpiod_line_request_output(clock_pin_line, "clock_pin", 0) ||
        gpiod_line_request_output(latch_pin_line, "latch_pin", 0)) {
        fprintf(stderr, "Failed to request GPIO lines as output\n");
        goto cleanup;
    }

    while (true) {
        shift_out(digit_5);
        sleep(1);
        shift_out(0xFF); // Turn off all segments
        sleep(1);
    }

cleanup:
    gpiod_line_release(data_pin_line);
    gpiod_line_release(clock_pin_line);
    gpiod_line_release(latch_pin_line);
    gpiod_chip_close(chip);
    return EXIT_FAILURE;
}

#include <stdio.h>
#include <stdlib.h>
#include <signal.h>
#include <stdbool.h>
#include <gpiod.h>

#define LED_PIN 17
#define BUTTON_PIN 18

static bool running = true;

static void sigint_handler(int signum) {
    running = false;
}

int main() {
    struct gpiod_chip *chip;
    struct gpiod_line *led_line, *button_line;
    struct gpiod_line_event event;
    int ret;

    // Register SIGINT handler
    signal(SIGINT, sigint_handler);

    // Open GPIO chip 0
    chip = gpiod_chip_open(0);
    if (!chip) {
        fprintf(stderr, "Failed to open GPIO chip 0\n");
        return EXIT_FAILURE;
    }

    // Request LED line as output initially low
    led_line = gpiod_chip_get_line(chip, LED_PIN);
    if (!led_line) {
        fprintf(stderr, "Failed to get LED line\n");
        goto cleanup_chip;
    }
    ret = gpiod_line_request_output(led_line, "blink_button", 0);
    if (ret) {
        fprintf(stderr, "Failed to request LED line as output\n");
        goto cleanup_chip;
    }

    // Request button line as input with internal pull-up and falling-edge event detection
    button_line = gpiod_chip_get_line(chip, BUTTON_PIN);
    if (!button_line) {
        fprintf(stderr, "Failed to get button line\n");
        goto cleanup_chip;
    }
    ret = gpiod_line_request_input(button_line, "blink_button");
    if (ret) {
        fprintf(stderr, "Failed to request button line as input\n");
        goto cleanup_chip;
    }
    ret = gpiod_line_event_request(button_line, GPIOD_EVENT_BOTH_EDGES);
    if (ret) {
        fprintf(stderr, "Failed to request button line events\n");
        goto cleanup_chip;
    }

    // Blink LED
    while (running) {
        ret = gpiod_line_set_value(led_line, 1);
        if (ret) {
            fprintf(stderr, "Failed to set LED line value\n");
            goto cleanup_chip;
        }
        sleep(1);
        ret = gpiod_line_set_value(led_line, 0);
        if (ret) {
            fprintf(stderr, "Failed to set LED line value\n");
            goto cleanup_chip;
        }
        sleep(1);

        // Check for button events
        ret = gpiod_line_event_wait(button_line, &event, 1);
        if (ret == 0) {
            running = false;
            ret = gpiod_line_set_value(led_line, 0);
            if (ret) {
                fprintf(stderr, "Failed to set LED line value\n");
                goto cleanup_chip;
            }
            printf("Button pressed, stopping blinking\n");
        }
    }

    // Cleanup
cleanup_chip:
    gpiod_chip_close(chip);

    return EXIT_SUCCESS;
}

#include <stdio.h>
#include <stdlib.h>
#include <signal.h>
#include <pigpio.h>

volatile sig_atomic_t stop;

void handler(int signum) {
    stop = 1;
}

int main() {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialization failed\n");
        return 1;
    }

    signal(SIGINT, handler);

    int gpio = 5;
    gpioSetMode(gpio, PI_OUTPUT);

    while (!stop) {
        gpioWrite(gpio, PI_HIGH);
        printf("LED ON\n");
        fflush(stdout);
        gpioDelay(750 * 1000);
        gpioWrite(gpio, PI_LOW);
        printf("LED OFF\n");
        fflush(stdout);
        gpioDelay(750 * 1000);
    }

    gpioTerminate();
    return 0;
}

#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <unistd.h>
#include <signal.h>
#include <gpiod.h>

#define LED_PIN 24
#define BUTTON_PIN 22

static struct gpiod_chip *chip;
static struct gpiod_line *led_line;
static struct gpiod_line *button_line;
static int led_state = 0;

static void cleanup() {
    if (led_line) gpiod_line_release(led_line);
    if (button_line) gpiod_line_release(button_line);
    if (chip) gpiod_chip_close(chip);
}

static void handle_sigint(int signum) {
    cleanup();
    exit(0);
}

static void handle_error(const char *msg) {
    fprintf(stderr, "%s: %s\n", msg, strerror(errno));
    cleanup();
    exit(1);
}

static void set_led(int state) {
    int ret = gpiod_line_set_value(led_line, state);
    if (ret < 0) handle_error("Failed to set LED state");
    led_state = state;
}

static int get_button() {
    int value, ret;
    ret = gpiod_line_get_value(button_line, &value);
    if (ret < 0) handle_error("Failed to get button state");
    return value;
}

int main() {
    struct sigaction sigact;
    sigact.sa_handler = handle_sigint;
    sigemptyset(&sigact.sa_mask);
    sigact.sa_flags = 0;
    sigaction(SIGINT, &sigact, NULL);
    sigaction(SIGTERM, &sigact, NULL);

    chip = gpiod_chip_open("/dev/gpiochip0");
    if (!chip) handle_error("Failed to open GPIO chip");

    led_line = gpiod_chip_get_line(chip, LED_PIN);
    if (!led_line) handle_error("Failed to get LED line");

    button_line = gpiod_chip_get_line(chip, BUTTON_PIN);
    if (!button_line) handle_error("Failed to get button line");

    int ret = gpiod_line_request_output(led_line, "led", 0);
    if (ret < 0) handle_error("Failed to request LED line as output");

    ret = gpiod_line_request_input(button_line, "button");
    if (ret < 0) handle_error("Failed to request button line as input");

    atexit(cleanup);

    while (1) {
        int button_state = get_button();
        if (button_state) {
            while (get_button()) {
                set_led(1);
                usleep(500000);
                set_led(0);
                usleep(500000);
            }
        } else {
            set_led(0);
        }
    }

    return 0;
}

#include <stdio.h>
#include <stdlib.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <sys/timerfd.h>
#include <bcm2835.h>

#define RED_PIN 24
#define GREEN_PIN 23
#define BLUE_PIN 18
#define PWM_FREQ 100 // 100 Hz

static int running = 1;

void signal_handler(int signum) {
    running = 0;
}

int main() {
    if (!bcm2835_init()) {
        fprintf(stderr, "bcm2835_init failed. Are you running as root?\n");
        return 1;
    }

    struct sigaction action;
    action.sa_handler = signal_handler;
    sigemptyset(&action.sa_mask);
    action.sa_flags = 0;
    sigaction(SIGINT, &action, NULL);

    int red_fd = bcm2835_pwm_open(RED_PIN, PWM_FREQ, 0);
    int green_fd = bcm2835_pwm_open(GREEN_PIN, PWM_FREQ, 0);
    int blue_fd = bcm2835_pwm_open(BLUE_PIN, PWM_FREQ, 0);

    if (red_fd < 0 || green_fd < 0 || blue_fd < 0) {
        fprintf(stderr, "Failed to open PWM for RGB LED\n");
        return 1;
    }

    srand(time(NULL));

    while (running) {
        int red = rand() % 101;
        int green = rand() % 101;
        int blue = rand() % 101;

        bcm2835_pwm_set_duty(red_fd, red);
        bcm2835_pwm_set_duty(green_fd, green);
        bcm2835_pwm_set_duty(blue_fd, blue);

        bcm2835_pwm_start(red_fd);
        bcm2835_pwm_start(green_fd);
        bcm2835_pwm_start(blue_fd);

        usleep(100000); // 100 ms

        bcm2835_pwm_stop(red_fd);
        bcm2835_pwm_stop(green_fd);
        bcm2835_pwm_stop(blue_fd);
    }

    bcm2835_pwm_close(red_fd);
    bcm2835_pwm_close(green_fd);
    bcm2835_pwm_close(blue_fd);

    bcm2835_close();

    return 0;
}

#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <signal.h>
#include <time.h>
#include <pigpio.h>

#define I2C_BUS 1
#define I2C_ADDRESS 0x19
#define ACCEL_SENSITIVITY 16384.0
#define DEFAULT_THRESHOLD 2.0
#define GPIO_PIN 17
#define LOG_FILE "impact_log.txt"
#define ACCEL_REG_OUT_X_L_A 0x28
#define ACCEL_REG_CTRL_REG1_A 0x20
#define ACCEL_REG_CTRL_REG4_A 0x23

volatile sig_atomic_t stop = 0;

void signal_handler(int signum) {
    stop = 1;
}

int main(int argc, char *argv[]) {
    double threshold = DEFAULT_THRESHOLD;
    if (argc > 1) {
        threshold = atof(argv[1]);
    }

    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return EXIT_FAILURE;
    }

    if (signal(SIGINT, signal_handler) == SIG_ERR || signal(SIGTERM, signal_handler) == SIG_ERR) {
        fprintf(stderr, "signal handler registration failed\n");
        gpioTerminate();
        return EXIT_FAILURE;
    }

    int i2c_handle = i2cOpen(I2C_BUS, I2C_ADDRESS, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "I2C open failed\n");
        gpioTerminate();
        return EXIT_FAILURE;
    }

    int gpio_handle = gpioOpen(GPIO_PIN, 0, 0);
    if (gpio_handle < 0) {
        fprintf(stderr, "GPIO open failed\n");
        i2cClose(i2c_handle);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    FILE *log_file = fopen(LOG_FILE, "w");
    if (log_file == NULL) {
        fprintf(stderr, "log file open failed\n");
        gpioClose(gpio_handle);
        i2cClose(i2c_handle);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    uint8_t buffer[6];
    struct timespec ts;
    double g_force;

    while (!stop) {
        if (i2cReadDevice(i2c_handle, ACCEL_REG_OUT_X_L_A, buffer, 6) != 6) {
            fprintf(stderr, "I2C read failed\n");
            break;
        }

        int16_t x = (buffer[0] | (buffer[1] << 8)) >> 4;
        int16_t y = (buffer[2] | (buffer[3] << 8)) >> 4;
        int16_t z = (buffer[4] | (buffer[5] << 8)) >> 4;

        g_force = sqrt(x * x + y * y + z * z) / ACCEL_SENSITIVITY;

        if (g_force > threshold) {
            gpioWrite(gpio_handle, 1);
            nanosleep((const struct timespec[]){{0, 50000000L}}, NULL);
            gpioWrite(gpio_handle, 0);

            clock_gettime(CLOCK_REALTIME, &ts);
            fprintf(log_file, "%ld.%09ld: %.2f\n", ts.tv_sec, ts.tv_nsec, g_force);
            fflush(log_file);
        }

        nanosleep((const struct timespec[]){{0, 100000000L}}, NULL);
    }

    fclose(log_file);
    gpioClose(gpio_handle);
    i2cClose(i2c_handle);
    gpioTerminate();

    return EXIT_SUCCESS;
}

#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

#define ALS_REG_LSB 0x64
#define ALS_REG_MSB 0x65
#define RED_REG 0x66
#define GREEN_REG 0x68
#define BLUE_REG 0x6A
#define MODE_REG 0x0D
#define MODE_VALUE 0x01
#define LED_PIN 18
#define SAMPLE_INTERVAL 500
#define RETRY_INTERVAL 100

FILE *csv_file;
bool running = true;

void signal_handler(int signum) {
    running = false;
}

void write_i2c_byte(uint8_t reg, uint8_t value) {
    if (i2cWriteByte(1, 0x39, reg) < 0) {
        fprintf(stderr, "Failed to write to register 0x%02X\n", reg);
        sleep(RETRY_INTERVAL / 1000);
        write_i2c_byte(reg, value);
    }
}

uint16_t read_i2c_word(uint8_t reg) {
    uint16_t value;
    if (i2cReadWordData(1, 0x39, reg, &value) < 0) {
        fprintf(stderr, "Failed to read from register 0x%02X\n", reg);
        sleep(RETRY_INTERVAL / 1000);
        return read_i2c_word(reg);
    }
    return value;
}

void log_data(uint16_t als, uint16_t red, uint16_t green, uint16_t blue) {
    fprintf(csv_file, "%u,%u,%u,%u\n", als, red, green, blue);
    fflush(csv_file);
}

int main() {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Failed to initialize pigpio\n");
        return EXIT_FAILURE;
    }

    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    csv_file = fopen("color_log.csv", "w");
    if (!csv_file) {
        fprintf(stderr, "Failed to open CSV file\n");
        gpioTerminate();
        return EXIT_FAILURE;
    }

    fprintf(csv_file, "ALS,Red,Green,Blue\n");

    write_i2c_byte(MODE_REG, MODE_VALUE);

    gpioSetMode(LED_PIN, PI_OUTPUT);

    while (running) {
        uint16_t als = read_i2c_word(ALS_REG_LSB);
        uint16_t red = read_i2c_word(RED_REG);
        uint16_t green = read_i2c_word(GREEN_REG);
        uint16_t blue = read_i2c_word(BLUE_REG);

        log_data(als, red, green, blue);

        uint8_t brightness = (als >> 8) & 0xFF;
        gpioPWM(LED_PIN, brightness);

        usleep(SAMPLE_INTERVAL * 1000);
    }

    fclose(csv_file);
    gpioTerminate();
    return EXIT_SUCCESS;
}

#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <pigpio.h>

#define FXOS8700CQ_ADDRESS 0x1F
#define FXOS8700CQ_WHOAMI 0x0D
#define FXOS8700CQ_CTRL_REG1 0x2A
#define FXOS8700CQ_OUT_X_MSB 0x01
#define FXOS8700CQ_XYZ_DATA_CFG 0x0E
#define FXOS8700CQ_SENSITIVITY 4096.0
#define G_TO_MS2 9.81
#define THRESHOLD 19.62

int main() {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return EXIT_FAILURE;
    }

    int i2c_handle = piI2COpen(1, FXOS8700CQ_ADDRESS);
    if (i2c_handle < 0) {
        fprintf(stderr, "Failed to open I2C bus 1\n");
        gpioTerminate();
        return EXIT_FAILURE;
    }

    uint8_t who_am_i = piI2CReadByteData(i2c_handle, FXOS8700CQ_WHOAMI);
    if (who_am_i != 0xC7) {
        fprintf(stderr, "Failed to verify sensor (WHO_AM_I = 0x%02X)\n", who_am_i);
        piI2CWriteByteData(i2c_handle, FXOS8700CQ_CTRL_REG1, 0x00);
        gpioI2CWriteByteData(i2c_handle, FXOS8700CQ_XYZ_DATA_CFG, 0x00);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    piI2CWriteByteData(i2c_handle, FXOS8700CQ_CTRL_REG1, 0x00);
    piI2CWriteByteData(i2c_handle, FXOS8700CQ_XYZ_DATA_CFG, 0x00);
    piI2CWriteByteData(i2c_handle, FXOS8700CQ_CTRL_REG1, 0x01);

    FILE *log_file = fopen("impact_log.txt", "a");
    if (!log_file) {
        fprintf(stderr, "Failed to open log file\n");
        gpioTerminate();
        return EXIT_FAILURE;
    }

    struct timespec sleep_time = {0, 50000000};
    while (1) {
        uint8_t data[6];
        if (piI2CReadByteData(i2c_handle, FXOS8700CQ_OUT_X_MSB, data, 6) != 6) {
            fprintf(stderr, "Failed to read sensor data\n");
            continue;
        }

        int16_t accel[3] = {
            (data[0] << 8) | data[1],
            (data[2] << 8) | data[3],
            (data[4] << 8) | data[5]
        };

        double magnitude = sqrt(accel[0] * accel[0] + accel[1] * accel[1] + accel[2] * accel[2]);
        magnitude *= FXOS8700CQ_SENSITIVITY / G_TO_MS2;

        if (magnitude > THRESHOLD) {
            time_t now = time(NULL);
            struct tm *time_info = localtime(&now);
            char time_str[20];
            strftime(time_str, sizeof(time_str), "%Y-%m-%d %H:%M:%S", time_info);

            fprintf(log_file, "%s,%f,%f,%f,%f\n", time_str, accel[0], accel[1], accel[2], magnitude);
            fflush(log_file);
        }

        nanosleep(&sleep_time, NULL);
    }

    fclose(log_file);
    piI2CWriteByteData(i2c_handle, FXOS8700CQ_CTRL_REG1, 0x00);
    gpioTerminate();
    return EXIT_SUCCESS;
}

#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <unistd.h>
#include <fcntl.h>
#include <sys/ioctl.h>
#include <linux/i2c-dev.h>
#include <time.h>
#include <signal.h>
#include <libgpiod.h>

#define GYRO_I2C_ADDRESS 0x69
#define GYRO_REG_WHO_AM_I 0x0F
#define GYRO_REG_CTRL_REG1 0x20
#define GYRO_REG_CTRL_REG4 0x23
#define GYRO_REG_OUT_X_L 0x28
#define GYRO_SENSITIVITY 0.00875
#define GYRO_ZERO_THRESHOLD 50.0
#define GYRO_LOG_PERIOD 50 // ms
#define GYRO_CALIBRATION_SAMPLES 100

static int i2c_fd = -1;
static FILE *log_file = NULL;
static struct timespec log_time = {0, 0};
static int16_t zero_offsets[3] = {0, 0, 0};

static void cleanup(int signum) {
    if (i2c_fd >= 0) close(i2c_fd);
    if (log_file) fclose(log_file);
    exit(signum);
}

static int i2c_write(int fd, uint8_t reg, uint8_t data) {
    uint8_t buf[2] = {reg, data};
    return write(fd, buf, 2) != 2;
}

static int i2c_read(int fd, uint8_t reg, uint8_t *data, size_t len) {
    if (write(fd, &reg, 1) != 1) return -1;
    return read(fd, data, len) != len;
}

static void calibrate_gyro() {
    int16_t samples[3][GYRO_CALIBRATION_SAMPLES];
    for (int axis = 0; axis < 3; axis++) {
        for (int i = 0; i < GYRO_CALIBRATION_SAMPLES; i++) {
            if (i2c_read(i2c_fd, GYRO_REG_OUT_X_L + axis * 2, (uint8_t *)&samples[axis][i], 2)) {
                fprintf(stderr, "Failed to read gyro data\n");
                exit(EXIT_FAILURE);
            }
        }
    }
    for (int axis = 0; axis < 3; axis++) {
        int32_t sum = 0;
        for (int i = 0; i < GYRO_CALIBRATION_SAMPLES; i++) {
            sum += samples[axis][i];
        }
        zero_offsets[axis] = sum / GYRO_CALIBRATION_SAMPLES;
    }
}

static void log_gyro_data(int16_t *data) {
    struct timespec now;
    clock_gettime(CLOCK_REALTIME, &now);
    if (log_time.tv_sec == 0) log_time = now;
    while ((now.tv_sec - log_time.tv_sec) * 1000 + (now.tv_nsec - log_time.tv_nsec) / 1e6 < GYRO_LOG_PERIOD) {
        nanosleep((struct timespec[]){{0, 1000000}}, NULL);
        clock_gettime(CLOCK_REALTIME, &now);
    }
    log_time = now;
    for (int axis = 0; axis < 3; axis++) {
        int16_t value = data[axis] - zero_offsets[axis];
        if (fabs(value * GYRO_SENSITIVITY) > GYRO_ZERO_THRESHOLD) {
            fprintf(stderr, "Gyro axis %d exceeded threshold: %d\n", axis, value);
            fprintf(log_file, "ALERT: Gyro axis %d exceeded threshold: %d\n", axis, value);
        }
        fprintf(log_file, "%ld.%09ld %d %d\n", now.tv_sec, now.tv_nsec, axis, value);
    }
    fflush(log_file);
}

int main() {
    signal(SIGINT, cleanup);
    signal(SIGTERM, cleanup);

    i2c_fd = open("/dev/i2c-1", O_RDWR);
    if (i2c_fd < 0) {
        fprintf(stderr, "Failed to open I2C device\n");
        return EXIT_FAILURE;
    }

    if (ioctl(i2c_fd, I2C_SLAVE, GYRO_I2C_ADDRESS) < 0) {
        fprintf(stderr, "Failed to set I2C address\n");
        return EXIT_FAILURE;
    }

    uint8_t who_am_i;
    if (i2c_read(i2c_fd, GYRO_REG_WHO_AM_I, &who_am_i, 1) || who_am_i != 0xD3) {
        fprintf(stderr, "Failed to verify gyro identity\n");
        return EXIT_FAILURE;
    }

    if (i2c_write(i2c_fd, GYRO_REG_CTRL_REG1, 0x0F) || i2c_write(i2c_fd, GYRO_REG_CTRL_REG4, 0x00)) {
        fprintf(stderr, "Failed to configure gyro\n");
        return EXIT_FAILURE;
    }

    log_file = fopen("gyro_log.txt", "w");
    if (!log_file) {
        fprintf(stderr, "Failed to open log file\n");
        return EXIT_FAILURE;
    }

    calibrate_gyro();

    while (1) {
        int16_t data[3];
        if (i2c_read(i2c_fd, GYRO_REG_OUT_X_L, (uint8_t *)data, 6)) {
            fprintf(stderr, "Failed to read gyro data\n");
            return EXIT_FAILURE;
        }
        log_gyro_data(data);
    }

    return EXIT_SUCCESS;
}

#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <signal.h>
#include <pigpio.h>
#include <time.h>

#define ADXL345_ADDRESS 0x53
#define ADXL345_DEVID 0x00
#define ADXL345_DATAX0 0x32
#define ADXL345_RANGE 2.0f // ±2g

int fd, led;

void cleanup(int signum) {
    gpioWrite(led, 0);
    gpioTerminate();
    close(fd);
    exit(signum);
}

int main() {
    signal(SIGINT, cleanup);
    signal(SIGTERM, cleanup);

    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialization failed\n");
        return EXIT_FAILURE;
    }

    led = 17;
    gpioSetMode(led, PI_OUTPUT);
    gpioWrite(led, 0);

    fd = open("/dev/i2c-1", O_RDWR);
    if (fd < 0) {
        fprintf(stderr, "Failed to open I2C bus\n");
        return EXIT_FAILURE;
    }

    if (ioctl(fd, I2C_SLAVE, ADXL345_ADDRESS) < 0) {
        fprintf(stderr, "Failed to acquire ADXL345\n");
        return EXIT_FAILURE;
    }

    uint8_t devid;
    if (read(fd, &devid, 1) != 1 || devid != ADXL345_DEVID) {
        fprintf(stderr, "ADXL345 not found\n");
        return EXIT_FAILURE;
    }

    uint8_t data[6];
    FILE *log = fopen("accel_log.txt", "w");
    if (!log) {
        fprintf(stderr, "Failed to open log file\n");
        return EXIT_FAILURE;
    }

    struct timespec ts;
    clock_gettime(CLOCK_REALTIME, &ts);
    long start = ts.tv_sec;

    while (1) {
        if (read(fd, data, 6) != 6) {
            fprintf(stderr, "Failed to read from ADXL345\n");
            continue;
        }

        clock_gettime(CLOCK_REALTIME, &ts);
        float x = (int16_t)((data[1] << 8) | data[0]) * ADXL345_RANGE / 32768.0f;
        float y = (int16_t)((data[3] << 8) | data[2]) * ADXL345_RANGE / 32768.0f;
        float z = (int16_t)((data[5] << 8) | data[4]) * ADXL345_RANGE / 32768.0f;

        fprintf(log, "%ld,%0.3f,%0.3f,%0.3f\n", ts.tv_sec - start, x, y, z);

        if (fabs(x) > 2.0f || fabs(y) > 2.0f || fabs(z) > 2.0f) {
            gpioWrite(led, 1);
        } else {
            gpioWrite(led, 0);
        }

        usleep(100000);
    }

    fclose(log);
    cleanup(0);
    return EXIT_SUCCESS;
}

#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <signal.h>
#include <pigpio.h>
#include <time.h>

#define ACCEL_ADDRESS 0x19
#define MAG_ADDRESS 0x1E
#define ACCEL_CTRL_REG1_A 0x20
#define ACCEL_OUT_X_L_A 0x28
#define MAG_MR_REG_M 0x02
#define MAG_OUT_X_H_M 0x03

volatile sig_atomic_t stop = 0;

void signal_handler(int signum) {
    stop = 1;
}

int main() {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return EXIT_FAILURE;
    }

    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    int i2c = i2cOpen(1, ACCEL_ADDRESS, 0);
    if (i2c < 0) {
        fprintf(stderr, "Failed to open I2C bus 1\n");
        gpioTerminate();
        return EXIT_FAILURE;
    }

    int mag_i2c = i2cOpen(1, MAG_ADDRESS, 0);
    if (mag_i2c < 0) {
        fprintf(stderr, "Failed to open I2C bus 1\n");
        gpioTerminate();
        return EXIT_FAILURE;
    }

    FILE *log_file = fopen("compass_log.txt", "a");
    if (!log_file) {
        fprintf(stderr, "Failed to open log file\n");
        gpioTerminate();
        return EXIT_FAILURE;
    }

    char header[] = "timestamp,heading_x,heading_y,heading_z,accel_x,accel_y,accel_z,mag_x,mag_y,mag_z\n";
    if (ftell(log_file) == 0) {
        fwrite(header, 1, sizeof(header) - 1, log_file);
    }

    uint8_t accel_config[] = {ACCEL_CTRL_REG1_A, 0x27};
    i2cWriteByteData(i2c, ACCEL_CTRL_REG1_A, accel_config[1]);

    uint8_t mag_config[] = {MAG_MR_REG_M, 0x00};
    i2cWriteByteData(mag_i2c, MAG_MR_REG_M, mag_config[1]);

    while (!stop) {
        struct timespec start_time, end_time;
        clock_gettime(CLOCK_MONOTONIC, &start_time);

        int16_t accel_data[3];
        accel_data[0] = i2cReadByteData(i2c, ACCEL_OUT_X_L_A) | (i2cReadByteData(i2c, ACCEL_OUT_X_L_A + 1) << 8);
        accel_data[1] = i2cReadByteData(i2c, ACCEL_OUT_X_L_A + 2) | (i2cReadByteData(i2c, ACCEL_OUT_X_L_A + 3) << 8);
        accel_data[2] = i2cReadByteData(i2c, ACCEL_OUT_X_L_A + 4) | (i2cReadByteData(i2c, ACCEL_OUT_X_L_A + 5) << 8);

        int16_t mag_data[3];
        mag_data[0] = i2cReadByteData(mag_i2c, MAG_OUT_X_H_M) | (i2cReadByteData(mag_i2c, MAG_OUT_X_H_M + 1) << 8);
        mag_data[1] = i2cReadByteData(mag_i2c, MAG_OUT_X_H_M + 2) | (i2cReadByteData(mag_i2c, MAG_OUT_X_H_M + 3) << 8);
        mag_data[2] = i2cReadByteData(mag_i2c, MAG_OUT_X_H_M + 4) | (i2cReadByteData(mag_i2c, MAG_OUT_X_H_M + 5) << 8);

        clock_gettime(CLOCK_MONOTONIC, &end_time);
        double elapsed_time = (end_time.tv_sec - start_time.tv_sec) + (end_time.tv_nsec - start_time.tv_nsec) / 1e9;

        fprintf(log_file, "%ld,%d,%d,%d,%d,%d,%d,%d,%d\n",
                (long)time(NULL), accel_data[0], accel_data[1], accel_data[2], mag_data[0], mag_data[1], mag_data[2]);

        fflush(log_file);

        usleep(100000 - (elapsed_time * 1e6));
    }

    fclose(log_file);
    i2cClose(i2c);
    i2cClose(mag_i2c);
    gpioTerminate();

    return EXIT_SUCCESS;
}

