#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <unistd.h>
#include <signal.h>
#include <time.h>
#include <pigpio.h>

#define SENSOR1_ADDRESS 0x68
#define SENSOR2_ADDRESS 0x69
#define SAMPLING_INTERVAL 10000 // 10 ms
#define LOG_FILE_NAME "audio_log.dat"

int sensor1_fd, sensor2_fd;
FILE *log_file;

void cleanup(int signum) {
    if (sensor1_fd >= 0) gpio_i2c_close(sensor1_fd);
    if (sensor2_fd >= 0) gpio_i2c_close(sensor2_fd);
    if (log_file) fclose(log_file);
    gpioTerminate();
    exit(signum);
}

int main() {
    struct timespec ts;
    int16_t sensor1_data, sensor2_data, tdoa;
    int ret;

    signal(SIGINT, cleanup);

    if ((ret = gpioInitialise()) < 0) {
        printf("pigpio initialization failed: %d\n", ret);
        return EXIT_FAILURE;
    }

    if ((sensor1_fd = gpioI2COpen(1, SENSOR1_ADDRESS)) < 0) {
        printf("Failed to open sensor1\n");
        cleanup(EXIT_FAILURE);
    }

    if ((sensor2_fd = gpioI2COpen(1, SENSOR2_ADDRESS)) < 0) {
        printf("Failed to open sensor2\n");
        cleanup(EXIT_FAILURE);
    }

    if ((log_file = fopen(LOG_FILE_NAME, "w")) == NULL) {
        printf("Failed to open log file\n");
        cleanup(EXIT_FAILURE);
    }

    while (1) {
        if ((ret = gpioI2CReadDevice(sensor1_fd, 0x01, &sensor1_data, 2)) < 0) {
            printf("Failed to read sensor1 data: %d\n", ret);
            continue;
        }

        if ((ret = gpioI2CReadDevice(sensor2_fd, 0x01, &sensor2_data, 2)) < 0) {
            printf("Failed to read sensor2 data: %d\n", ret);
            continue;
        }

        if ((ret = clock_gettime(CLOCK_REALTIME, &ts)) < 0) {
            printf("Failed to get time: %d\n", ret);
            continue;
        }

        tdoa = sensor1_data - sensor2_data;

        fprintf(log_file, "%ld,%ld,%d,%d,%d\n", ts.tv_sec, ts.tv_nsec, sensor1_data, sensor2_data, tdoa);

        usleep(SAMPLING_INTERVAL);
    }

    cleanup(EXIT_SUCCESS);
}

