    fclose(f);
}

void signal_handler(int signum) {
    cleanup();
    exit(signum);
}

int main() {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Failed to initialize pigpio\n");
        return EXIT_FAILURE;
    }

    atexit(cleanup);
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    int spi_handle = spiOpen(SPI_CHANNEL, SPI_SPEED, SPI_MODE);
    if (spi_handle < 0) {
        fprintf(stderr, "Failed to open SPI channel\n");
        return EXIT_FAILURE;
    }

    FILE *f = fopen("imu_data.csv", "w");
    if (!f) {
        fprintf(stderr, "Failed to open CSV file\n");
        return EXIT_FAILURE;
    }

    uint16_t tx[2] = {0, 0};
    uint16_t rx[2] = {0, 0};
    struct timespec sleep_time = {0, 1000000};
    struct timespec start_time, current_time;
    clock_gettime(CLOCK_MONOTONIC, &start_time);

    while (running) {
        clock_nanosleep(CLOCK_MONOTONIC, 0, &sleep_time, NULL);

        clock_gettime(CLOCK_MONOTONIC, &current_time);
        double timestamp = (current_time.tv_sec - start_time.tv_sec) + (current_time.tv_nsec - start_time.tv_nsec) / 1e9;

        // Gyroscope X
        tx[0] = 0x04 << 8;
        if (spiXfer(spi_handle, tx, rx, 2) < 0) {
            fprintf(stderr, "Failed to read gyroscope X\n");
            continue;
        }
        double gyro_x = (rx[1] >> 7) * GYRO_SENSITIVITY;

        // Gyroscope Y
        tx[0] = 0x06 << 8;
        if (spiXfer(spi_handle, tx, rx, 2) < 0) {
            fprintf(stderr, "Failed to read gyroscope Y\n");
            continue;
        }
        double gyro_y = (rx[1] >> 7) * GYRO_SENSITIVITY;

        // Gyroscope Z
        tx[0] = 0x08 << 8;
        if (spiXfer(spi_handle, tx, rx, 2) < 0) {
            fprintf(stderr, "Failed to read gyroscope Z\n");
            continue;
        }
        double gyro_z = (rx[1] >> 7) * GYRO_SENSITIVITY;

        // Accelerometer X
        tx[0] = 0x0A << 8;
        if (spiXfer(spi_handle, tx, rx, 2) < 0) {
            fprintf(stderr, "Failed to read accelerometer X\n");
            continue;
        }
        double accel_x = (rx[1] >> 7) * ACCEL_SENSITIVITY;

        // Accelerometer Y
        tx[0] = 0x0C << 8;
        if (spiXfer(spi_handle, tx, rx, 2) < 0) {
            fprintf(stderr, "Failed to read accelerometer Y\n");
            continue;
        }
        double accel_y = (rx[1] >> 7) * ACCEL_SENSITIVITY;

        // Accelerometer Z
        tx[0] = 0x0E << 8;
        if (spiXfer(spi_handle, tx, rx, 2) < 0) {
            fprintf(stderr, "Failed to read accelerometer Z\n");
            continue;
        }
        double accel_z = (rx[1] >> 7) * ACCEL_SENSITIVITY;

        fprintf(f, "%f,%f,%f,%f,%f,%f\n", timestamp, gyro_x, gyro_y, gyro_z, accel_x, accel_y, accel_z);
    }

    return EXIT_SUCCESS;
}

