    // Set SPI mode and speed
    ret = ioctl(spi_fd, SPI_IOC_WR_MODE32, &SPI_MODE);
    if (ret < 0) {
        perror("Failed to set SPI mode");
        return -1;
    }
    ret = ioctl(spi_fd, SPI_IOC_WR_MAX_SPEED_HZ, &SPI_SPEED);
    if (ret < 0) {
        perror("Failed to set SPI speed");
        return -1;
    }

    // Open GPIO chip
    chip = gpiod_chip_open_by_name("gpiochip0");
    if (!chip) {
        perror("Failed to open GPIO chip");
        return -1;
    }
    gpiod_fd = gpiod_chip_get_fd(chip);

    // Request GPIO line
    memset(&req, 0, sizeof(req));
    req.consumer = "adis16448";
    req.request_type = GPIO_REQUEST_OUTPUT;
    line = gpiod_chip_get_line(chip, 8);
    ret = gpiod_line_request(line, &req);
    if (ret < 0) {
        perror("Failed to request GPIO line");
        return -1;
    }

    // Main loop
    while (1) {
        // Set chip-select low
        gpiod_line_set_value(line, 0);

        // Send register address
        spi[0].tx_buf = (unsigned long)tx;
        spi[0].rx_buf = 0;
        spi[0].len = 1;
        spi[0].cs_change = 0;
        spi[0].delay_usecs = 0;

        // Read data
        spi[1].tx_buf = 0;
        spi[1].rx_buf = (unsigned long)rx;
        spi[1].len = 2;
        spi[1].cs_change = 1;
        spi[1].delay_usecs = 0;

        ret = ioctl(spi_fd, SPI_IOC_MESSAGE(2), spi);
        if (ret < 0) {
            perror("Failed to read data");
            return -1;
        }

        // Set chip-select high
        gpiod_line_set_value(line, 1);

        // Log data
        printf("Gyro X: %d, Y: %d, Z: %d\n", (rx[1] << 8) | rx[0], (rx[1] << 8) | rx[0], (rx[1] << 8) | rx[0]);
        printf("Accel X: %d, Y: %d, Z: %d\n", (rx[1] << 8) | rx[0], (rx[1] << 8) | rx[0], (rx[1] << 8) | rx[0]);

        // Sleep for 100 ms
        usleep(100000);
    }

    return 0;
}

#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <pigpio.h>

#define ADIS16448_SPI_CHANNEL 0
#define ADIS16448_SPI_SPEED 1000000
#define ADIS16448_SPI_MODE 0
#define ADIS16448_READ_CMD_BIT 15
#define ADIS16448_STALL_TIME 40
#define ADIS16448_GYRO_SCALE 0.05
#define ADIS16448_ACCEL_SCALE 0.00025

#define ADIS16448_REG_X_GYRO_OUT 0x04
#define ADIS16448_REG_Y_GYRO_OUT 0x06
#define ADIS16448_REG_Z_GYRO_OUT 0x08
#define ADIS16448_REG_X_ACCL_OUT 0x0A
#define ADIS16448_REG_Y_ACCL_OUT 0x0C
#define ADIS16448_REG_Z_ACCL_OUT 0x0E

void read_imu_data() {
    uint16_t tx_data[2] = {0};
    uint16_t rx_data[2] = {0};

    // Read X_GYRO_OUT
    tx_data[0] = (ADIS16448_REG_X_GYRO_OUT << 1) | ADIS16448_READ_CMD_BIT;
    gpioSPIDataRW(ADIS16448_SPI_CHANNEL, tx_data, rx_data, 2);
    printf("X_GYRO_OUT: %d\n", (int16_t)(rx_data[1] >> 4) * ADIS16448_GYRO_SCALE);

    // Read Y_GYRO_OUT
    tx_data[0] = (ADIS16448_REG_Y_GYRO_OUT << 1) | ADIS16448_READ_CMD_BIT;
    gpioDelay(ADIS16448_STALL_TIME);
    gpioSPIDataRW(ADIS16448_SPI_CHANNEL, tx_data, rx_data, 2);
    printf("Y_GYRO_OUT: %d\n", (int16_t)(rx_data[1] >> 4) * ADIS16448_GYRO_SCALE);

    // Read Z_GYRO_OUT
    tx_data[0] = (ADIS16448_REG_Z_GYRO_OUT << 1) | ADIS16448_READ_CMD_BIT;
    gpioDelay(ADIS16448_STALL_TIME);
    gpioSPIDataRW(ADIS16448_SPI_CHANNEL, tx_data, rx_data, 2);
    printf("Z_GYRO_OUT: %d\n", (int16_t)(rx_data[1] >> 4) * ADIS16448_GYRO_SCALE);

    // Read X_ACCL_OUT
    tx_data[0] = (ADIS16448_REG_X_ACCL_OUT << 1) | ADIS16448_READ_CMD_BIT;
    gpioSPIDataRW(ADIS16448_SPI_CHANNEL, tx_data, rx_data, 2);
    printf("X_ACCL_OUT: %d\n", (int16_t)(rx_data[1] >> 4) * ADIS16448_ACCEL_SCALE);

    // Read Y_ACCL_OUT
    tx_data[0] = (ADIS16448_REG_Y_ACCL_OUT << 1) | ADIS16448_READ_CMD_BIT;
    gpioDelay(ADIS16448_STALL_TIME);
    gpioSPIDataRW(ADIS16448_SPI_CHANNEL, tx_data, rx_data, 2);
    printf("Y_ACCL_OUT: %d\n", (int16_t)(rx_data[1] >> 4) * ADIS16448_ACCEL_SCALE);

    // Read Z_ACCL_OUT
    tx_data[0] = (ADIS16448_REG_Z_ACCL_OUT << 1) | ADIS16448_READ_CMD_BIT;
    gpioDelay(ADIS16448_STALL_TIME);
    gpioSPIDataRW(ADIS16448_SPI_CHANNEL, tx_data, rx_data, 2);
    printf("Z_ACCL_OUT: %d\n", (int16_t)(rx_data[1] >> 4) * ADIS16448_ACCEL_SCALE);
}

int main() {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialization failed\n");
        return EXIT_FAILURE;
    }

    if (gpioSetMode(8, PI_OUTPUT) < 0) {
        fprintf(stderr, "Failed to set GPIO8 mode\n");
        gpioTerminate();
        return EXIT_FAILURE;
    }

    if (gpioSPISetup(ADIS16448_SPI_CHANNEL, ADIS16448_SPI_SPEED, ADIS16448_SPI_MODE) < 0) {
        fprintf(stderr, "Failed to setup SPI channel\n");
        gpioTerminate();
        return EXIT_FAILURE;
    }

    while (1) {
        read_imu_data();
        gpioDelay(100000); // 100 ms delay
    }

    gpioTerminate();
    return EXIT_SUCCESS;
}

#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
