#include <unistd.h>
#include <sys/ioctl.h>
#include <linux/i2c-dev.h>

#define MPU6886_ADDRESS 0x68
#define WHO_AM_I 0x75
#define PWR_MGMT_1 0x6B
#define ACCEL_CONFIG 0x1C
#define GYRO_CONFIG 0x1B
#define ACCEL_XOUT_H 0x3B
#define GYRO_XOUT_H 0x43

int i2c_fd;

int i2c_write_byte(uint8_t reg, uint8_t data) {
    uint8_t buf[2] = {reg, data};
    return write(i2c_fd, buf, 2);
}

int i2c_read_bytes(uint8_t reg, uint8_t *data, int len) {
    if (write(i2c_fd, &reg, 1) != 1) {
        return -1;
    }
    return read(i2c_fd, data, len);
}

int main() {
    if ((i2c_fd = open("/dev/i2c-1", O_RDWR)) < 0) {
        perror("Failed to open i2c device");
        return EXIT_FAILURE;
    }

    if (ioctl(i2c_fd, I2C_SLAVE, MPU6886_ADDRESS) < 0) {
        perror("Failed to set i2c slave address");
        close(i2c_fd);
        return EXIT_FAILURE;
    }

    uint8_t who_am_i;
    if (i2c_read_bytes(WHO_AM_I, &who_am_i, 1) != 1 || who_am_i != 0x86) {
        fprintf(stderr, "Failed to verify sensor\n");
        close(i2c_fd);
        return EXIT_FAILURE;
    }

    if (i2c_write_byte(PWR_MGMT_1, 0x00) != 2 || i2c_write_byte(ACCEL_CONFIG, 0x00) != 2 || i2c_write_byte(GYRO_CONFIG, 0x00) != 2) {
        fprintf(stderr, "Failed to initialize sensor\n");
        close(i2c_fd);
        return EXIT_FAILURE;
    }

    while (1) {
        uint8_t accel_data[6], gyro_data[6];
        if (i2c_read_bytes(ACCEL_XOUT_H, accel_data, 6) != 6 || i2c_read_bytes(GYRO_XOUT_H, gyro_data, 6) != 6) {
            fprintf(stderr, "Failed to read sensor data\n");
            break;
        }

        int16_t accel_x = (accel_data[0] << 8) | accel_data[1];
        int16_t accel_y = (accel_data[2] << 8) | accel_data[3];
        int16_t accel_z = (accel_data[4] << 8) | accel_data[5];
        int16_t gyro_x = (gyro_data[0] << 8) | gyro_data[1];
        int16_t gyro_y = (gyro_data[2] << 8) | gyro_data[3];
        int16_t gyro_z = (gyro_data[4] << 8) | gyro_data[5];

        printf("Accel: %d, %d, %d\n", accel_x, accel_y, accel_z);
        printf("Gyro: %d, %d, %d\n", gyro_x, gyro_y, gyro_z);

        usleep(50000);
    }

    close(i2c_fd);
    return EXIT_SUCCESS;
}

#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <signal.h>
#include <time.h>
#include <pigpio.h>

#define LED_PIN 17
#define IMPACT_THRESHOLD 2.5
#define IMPACT_LOG_FILE "impact_log.txt"
#define I2C_BUS 1
#define I2C_ADDRESS 0x53
#define ACCEL_SCALE_FACTOR 256.0

int i2c_handle;
FILE *log_file;

void cleanup() {
    if (log_file) fclose(log_file);
    if (i2c_handle >= 0) pi_i2c_close(i2c_handle);
    gpioTerminate();
}

void handle_sigint(int signum) {
    cleanup();
    exit(0);
}

int read_register(uint8_t reg, uint8_t *data, int len) {
    return pi_i2c_read_device(i2c_handle, reg, data, len);
}

int write_register(uint8_t reg, uint8_t *data, int len) {
    return pi_i2c_write_device(i2c_handle, reg, data, len);
}

void log_impact(float magnitude, float x, float y, float z) {
    time_t now = time(NULL);
    struct tm *t = localtime(&now);
    char timestamp[20];
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", t);
    fprintf(log_file, "%s: Magnitude: %.2fg, X: %.2fg, Y: %.2fg, Z: %.2fg\n", timestamp, magnitude, x, y, z);
    fflush(log_file);
}

int main() {
    signal(SIGINT, handle_sigint);
    signal(SIGTERM, handle_sigint);

    if (gpioInitialise() < 0) {
        fprintf(stderr, "Failed to initialize pigpio\n");
        return 1;
    }

    i2c_handle = pi_i2c_open(I2C_BUS, I2C_ADDRESS);
    if (i2c_handle < 0) {
        fprintf(stderr, "Failed to open I2C bus\n");
        cleanup();
        return 1;
    }

    uint8_t device_id;
    if (read_register(0x00, &device_id, 1) != 1 || device_id != 0xE5) {
        fprintf(stderr, "Failed to verify ADXL345 device ID\n");
        cleanup();
        return 1;
    }

    log_file = fopen(IMPACT_LOG_FILE, "a");
    if (!log_file) {
        fprintf(stderr, "Failed to open log file\n");
        cleanup();
        return 1;
    }

    if (gpioSetMode(LED_PIN, PI_OUTPUT) < 0) {
        fprintf(stderr, "Failed to set LED pin mode\n");
        cleanup();
        return 1;
    }

    uint8_t data[6];
    float x, y, z, magnitude;
    while (1) {
        if (read_register(0x32, data, 6) != 6) {
            fprintf(stderr, "Failed to read accelerometer data\n");
            cleanup();
            return 1;
        }

        x = (int16_t)((data[1] << 8) | data[0]) / ACCEL_SCALE_FACTOR;
        y = (int16_t)((data[3] << 8) | data[2]) / ACCEL_SCALE_FACTOR;
        z = (int16_t)((data[5] << 8) | data[4]) / ACCEL_SCALE_FACTOR;
        magnitude = sqrt(x * x + y * y + z * z);

        if (magnitude > IMPACT_THRESHOLD) {
            gpioWrite(LED_PIN, 1);
            sleep(0.5);
            gpioWrite(LED_PIN, 0);
            log_impact(magnitude, x, y, z);
        }

        usleep(10000);
    }

    cleanup();
    return 0;
}

#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <signal.h>
#include <pigpio.h>

#define ACCEL_CONFIG 0x1C
#define GYRO_CONFIG 0x1B
#define PWR_MGMT_1 0x6B
#define WHO_AM_I 0x75
#define ACCEL_OUT 0x3B
#define GYRO_OUT 0x43

volatile sig_atomic_t stop;

void signal_handler(int signum) {
    stop = 1;
}

int main() {
    int i2c_handle, file;
    uint8_t buffer[14];
    struct timespec ts;

    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialization failed\n");
        return EXIT_FAILURE;
    }

    i2c_handle = gpioI2COpen(1, 0x68);
    if (i2c_handle < 0) {
        fprintf(stderr, "I2C open failed\n");
        gpioTerminate();
        return EXIT_FAILURE;
    }

    if (gpioI2CWriteByteData(i2c_handle, PWR_MGMT_1, 0x00) < 0) {
        fprintf(stderr, "Failed to wake up the IMU\n");
        goto cleanup;
    }

    if (gpioI2CWriteByteData(i2c_handle, ACCEL_CONFIG, 0x00) < 0) {
        fprintf(stderr, "Failed to set accelerometer range\n");
        goto cleanup;
    }

    if (gpioI2CWriteByteData(i2c_handle, GYRO_CONFIG, 0x00) < 0) {
        fprintf(stderr, "Failed to set gyroscope range\n");
        goto cleanup;
    }

    uint8_t who_am_i;
    if (gpioI2CReadByteData(i2c_handle, WHO_AM_I, &who_am_i) < 0) {
        fprintf(stderr, "Failed to read WHO_AM_I register\n");
        goto cleanup;
    }

    if (who_am_i != 0x12) {
        fprintf(stderr, "WHO_AM_I register does not match expected value\n");
        goto cleanup;
    }

    file = open("imu_log.csv", O_WRONLY | O_CREAT | O_TRUNC, 0644);
    if (file < 0) {
        fprintf(stderr, "Failed to open log file\n");
        goto cleanup;
    }

    signal(SIGINT, signal_handler);

    while (!stop) {
        if (gpioI2CReadI2CBlockData(i2c_handle, ACCEL_OUT, 6, buffer) < 0) {
            fprintf(stderr, "Failed to read accelerometer data\n");
            goto cleanup;
        }

        if (clock_gettime(CLOCK_REALTIME, &ts) < 0) {
            fprintf(stderr, "Failed to get time\n");
            goto cleanup;
        }

        dprintf(file, "%ld.%09ld,%d,%d,%d,%d,%d,%d,%d,%d\n",
                ts.tv_sec, ts.tv_nsec,
                buffer[0] << 8 | buffer[1],
                buffer[2] << 8 | buffer[3],
                buffer[4] << 8 | buffer[5],
                buffer[6] << 8 | buffer[7],
                buffer[8] << 8 | buffer[9],
                buffer[10] << 8 | buffer[11],
                buffer[12] << 8 | buffer[13]);

        usleep(100000);
    }

cleanup:
    close(file);
    gpioI2CClose(i2c_handle);
    gpioTerminate();
    return EXIT_SUCCESS;
}

#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <unistd.h>
#include <fcntl.h>
#include <signal.h>
#include <sys/ioctl.h>
#include <linux/i2c-dev.h>
#include <gpiod.h>

#define WHO_AM_I 0x0D
#define XYZ_DATA 0x01
#define GYRO_RANGE 0x0F
#define ACCEL_RANGE 0x0E
#define ACCEL_MG_LSB_2G 0.061

int fd, accel_fd;
struct gpiod_chip *chip;
struct gpiod_line *line;
struct sigaction sa;
FILE *log_file;

void cleanup(int signum) {
    gpiod_line_set_value(line, 0);
    gpiod_chip_close(chip);
    close(fd);
    close(accel_fd);
    fclose(log_file);
    exit(signum);
}

int main() {
    char filename[20];
    int who_am_i, x, y, z, threshold = 2048; // 2g threshold
    struct timespec ts;

    // Setup signal handlers
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = cleanup;
    sigaction(SIGINT, &sa, NULL);
    sigaction(SIGTERM, &sa, NULL);

    // Open I2C bus
    strcpy(filename, "/dev/i2c-1");
    if ((fd = open(filename, O_RDWR)) < 0) {
        perror("Failed to open the i2c bus");
        return 1;
    }

    // Open accelerometer
    if (ioctl(fd, I2C_SLAVE, 0x1D) < 0) {
        perror("Failed to acquire bus access and/or talk to slave");
        return 1;
    }

    // Check WHO_AM_I register
    if (write(fd, &WHO_AM_I, 1) != 1 || read(fd, &who_am_i, 1) != 1 || who_am_i != 0x1A) {
        printf("Failed to verify accelerometer identity\n");
        return 1;
    }

    // Set accelerometer range to +-2g
    if (write(fd, &ACCEL_RANGE, 1) != 1 || write(fd, &GYRO_RANGE, 1) != 1) {
        printf("Failed to set accelerometer range\n");
        return 1;
    }

    // Open GPIO chip
    chip = gpiod_chip_open_by_name("gpiochip0");
    if (!chip) {
        perror("Failed to open GPIO chip");
        return 1;
    }

    // Request GPIO line
    line = gpiod_chip_get_line(chip, 17);
    if (!line) {
        perror("Failed to get GPIO line");
        return 1;
    }

    // Set GPIO line direction to output
    if (gpiod_line_request_output(line, "accelerometer_led", 0) < 0) {
        perror("Failed to set GPIO line direction");
        return 1;
    }

    // Open log file
    log_file = fopen("impact_log.txt", "a");
    if (!log_file) {
        perror("Failed to open log file");
        return 1;
    }

    while (1) {
        // Read accelerometer data
        if (write(fd, &XYZ_DATA, 1) != 1 || read(fd, &x, 2) != 2 || read(fd, &y, 2) != 2 || read(fd, &z, 2) != 2) {
            printf("Failed to read accelerometer data\n");
            continue;
        }

        // Check if acceleration exceeds threshold
        if (abs(x) > threshold || abs(y) > threshold || abs(z) > threshold) {
            gpiod_line_set_value(line, 1);
            nanosleep((const struct timespec[]){{0, 500000000L}}, NULL);
            gpiod_line_set_value(line, 0);

            // Log impact
            clock_gettime(CLOCK_REALTIME, &ts);
            fprintf(log_file, "%ld.%09ld: Impact detected\n", ts.tv_sec, ts.tv_nsec);
            fflush(log_file);
        }

        // Sleep for 100 ms
        nanosleep((const struct timespec[]){{0, 100000000L}}, NULL);
    }

    return 0;
}

