#define OUTZ_H_G 0x27

volatile sig_atomic_t stop = 0;

void signal_handler(int signum) {
    stop = 1;
}

int main() {
    FILE *log_file;
    int i2c_handle;
    int accel_handle;
    int gyro_handle;
    int16_t accel_data[3];
    int16_t gyro_data[3];
    int state = 0; // 0: IDLE, 1: FREEFALL, 2: IMPACT
    time_t start_time, current_time;
    double accel_magnitude;

    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    i2c_handle = pi_i2c_open(1, ACCEL_ADDRESS);
    if (i2c_handle < 0) {
        printf("Failed to open I2C bus\n");
        return -1;
    }

    accel_handle = pi_i2c_write_byte_data(i2c_handle, 0x10, ACCEL_RANGE);
    if (accel_handle < 0) {
        printf("Failed to set accelerometer range\n");
        return -1;
    }

    gyro_handle = pi_i2c_write_byte_data(i2c_handle, 0x11, GYRO_RANGE);
    if (gyro_handle < 0) {
        printf("Failed to set gyroscope range\n");
        return -1;
    }

    pi_i2c_write_byte_data(i2c_handle, 0x12, ODR);

    log_file = fopen("motion_log.txt", "w");
    if (log_file == NULL) {
        printf("Failed to open log file\n");
        return -1;
    }

    while (!stop) {
        accel_data[0] = pi_i2c_read_byte_data(i2c_handle, OUTX_L_G);
        accel_data[1] = pi_i2c_read_byte_data(i2c_handle, OUTY_L_G);
        accel_data[2] = pi_i2c_read_byte_data(i2c_handle, OUTZ_L_G);

        gyro_data[0] = pi_i2c_read_byte_data(i2c_handle, OUTX_L_G + 1);
        gyro_data[1] = pi_i2c_read_byte_data(i2c_handle, OUTY_L_G + 1);
        gyro_data[2] = pi_i2c_read_byte_data(i2c_handle, OUTZ_L_G + 1);

        accel_magnitude = sqrt(accel_data[0] * accel_data[0] + accel_data[1] * accel_data[1] + accel_data[2] * accel_data[2]);

        current_time = time(NULL);
        fprintf(log_file, "%ld,%d,%d,%d,%d,%d,%d,%d\n", current_time, accel_data[0], accel_data[1], accel_data[2], gyro_data[0], gyro_data[1], gyro_data[2], accel_magnitude);

        switch (state) {
            case 0: // IDLE
                if (accel_magnitude < 0.2) {
                    state = 1;
                    start_time = current_time;
                }
                break;
            case 1: // FREEFALL
                if (accel_magnitude > 2.5) {
                    state = 2;
                } else if (difftime(current_time, start_time) > 1.0) {
                    state = 0;
                }
                break;
            case 2: // IMPACT
                if (difftime(current_time, start_time) > 1.0) {
                    state = 0;
                }
                break;
        }

        usleep(100000); // sleep for 0.1 seconds
    }

    fclose(log_file);
    pi_i2c_close(i2c_handle);

    return 0;
}

