#define GYRO_SENSITIVITY 8.75

volatile sig_atomic_t stop = 0;

void signal_handler(int signum) {
    stop = 1;
}

int main() {
    FILE *file;
    int i2c_handle;
    uint8_t who_am_i, ctrl_reg1, ctrl_reg4;
    int16_t x, y, z;
    struct timespec ts;

    signal(SIGINT, signal_handler);

    if ((i2c_handle = pi_i2c_open(1, GYRO_ADDRESS)) < 0) {
        printf("Failed to open I2C bus 1.\n");
        return EXIT_FAILURE;
    }

    if (pi_i2c_write_byte_data(i2c_handle, GYRO_WHO_AM_I, 0x00) < 0) {
        printf("Failed to read WHO_AM_I register.\n");
        pi_i2c_close(i2c_handle);
        return EXIT_FAILURE;
    }

    who_am_i = pi_i2c_read_byte_data(i2c_handle, GYRO_WHO_AM_I);
    if (who_am_i != 0xD3) {
        printf("WHO_AM_I register does not match expected value.\n");
        pi_i2c_close(i2c_handle);
        return EXIT_FAILURE;
    }

    ctrl_reg1 = 0x0F;
    ctrl_reg4 = 0x00;

    for (int retry = 0; retry < 3; retry++) {
        if (pi_i2c_write_byte_data(i2c_handle, GYRO_CTRL_REG1, ctrl_reg1) < 0) {
            printf("Failed to write CTRL_REG1 register.\n");
            continue;
        }

