            printf("Failed to write CTRL_REG4 register.\n");
            continue;
        }

        break;
    }

    file = fopen("gyro_log.csv", "w");
    if (file == NULL) {
        printf("Failed to open file for writing.\n");
        pi_i2c_close(i2c_handle);
        return EXIT_FAILURE;
    }

    fprintf(file, "Timestamp,X,Y,Z\n");

    while (!stop) {
        if (pi_i2c_read_i2c_block_data(i2c_handle, GYRO_OUT_X_L, 6, (char *)&x) < 0) {
