        fprintf(file, "%ld,%f,%f,%f\n", ts.tv_nsec, (float)x / GYRO_SENSITIVITY, (float)y / GYRO_SENSITIVITY, (float)z / GYRO_SENSITIVITY);

        usleep(10000);
    }

    fclose(file);
    pi_i2c_close(i2c_handle);
    gpioTerminate();

    return EXIT_SUCCESS;
}

