#define I2C_BUS "/dev/i2c-1"
#define SENSOR_ADDRESS 0x53
#define SAMPLE_INTERVAL 100 // ms
#define LOG_FILE "vibration_log.csv"

int i2c_fd;
FILE *log_fd;

void signal_handler(int signum) {
    if (i2c_fd != -1) close(i2c_fd);
    if (log_fd != NULL) fclose(log_fd);
    exit(signum);
}

int main() {
    struct sigaction sigIntHandler;

    sigIntHandler.sa_handler = signal_handler;
    sigemptyset(&sigIntHandler.sa_mask);
    sigIntHandler.sa_flags = 0;

    sigaction(SIGINT, &sigIntHandler, NULL);

    i2c_fd = open(I2C_BUS, O_RDWR);
    if (i2c_fd < 0) {
        perror("Failed to open the i2c bus");
        return 1;
    }

    if (ioctl(i2c_fd, I2C_SLAVE, SENSOR_ADDRESS) < 0) {
        perror("Failed to acquire bus access and/or talk to slave");
        close(i2c_fd);
        return 1;
    }

    log_fd = fopen(LOG_FILE, "w");
    if (log_fd == NULL) {
        perror("Failed to open log file");
        close(i2c_fd);
        return 1;
    }

    fprintf(log_fd, "Timestamp,X,Y,Z\n");

    while (1) {
        uint8_t reg = 0x28;
        int16_t x, y, z;
        struct timespec req, rem;

        req.tv_sec = 0;
        req.tv_nsec = SAMPLE_INTERVAL * 1000000L;

        nanosleep(&req, &rem);

        if (ioctl(i2c_fd, I2C_SLAVE, SENSOR_ADDRESS) < 0) {
            perror("Failed to re-acquire bus access and/or talk to slave");
            continue;
        }

        if (write(i2c_fd, &reg, 1) != 1) {
            perror("Failed to write register address");
            continue;
        }

        if (read(i2c_fd, &x, 2) != 2 || read(i2c_fd, &y, 2) != 2 || read(i2c_fd, &z, 2) != 2) {
            perror("Failed to read data");
            continue;
        }

        time_t now = time(NULL);
        struct tm *timeinfo = gmtime(&now);
        char timestamp[20];
        strftime(timestamp, sizeof(timestamp), "%Y-%m-%dT%H:%M:%SZ", timeinfo);

        fprintf(log_fd, "%s,%d,%d,%d\n", timestamp, x, y, z);
    }

    fclose(log_fd);
    close(i2c_fd);

    return 0;
}

