static int running = 1;

void log_sensor_states() {
    struct timespec ts;
    clock_gettime(CLOCK_REALTIME, &ts);
    char timestamp[32];
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S.", gmtime(&ts.tv_sec));
    sprintf(timestamp + strlen(timestamp), "%03ld", ts.tv_nsec / 1e6);

    gpiod_line_bulk_request_values(&lines, timestamp, LOG_FILE, "a", NULL);
}

void handle_signal(int signum) {
    running = 0;
}

int main() {
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = handle_signal;
    sigaction(SIGINT, &sa, NULL);
    sigaction(SIGTERM, &sa, NULL);

    chip = gpiod_chip_open("/dev/gpiochip0");
    if (!chip) {
        fprintf(stderr, "Failed to open GPIO chip\n");
        return EXIT_FAILURE;
    }

    if (gpiod_chip_get_lines(chip, SENSOR_PIN_COUNT, SENSOR_PINS, &lines)) {
        fprintf(stderr, "Failed to get lines\n");
        gpiod_chip_close(chip);
        return EXIT_FAILURE;
    }

    for (int i = 0; i < SENSOR_PIN_COUNT; i++) {
        if (gpiod_line_request_input(&lines.lines[i], "sensor", 0)) {
            fprintf(stderr, "Failed to request line %d\n", SENSOR_PINS[i]);
            gpiod_chip_close(chip);
            return EXIT_FAILURE;
        }
