        gpiod_chip_close(chip);
        return EXIT_FAILURE;
    }

    while (running) {
        log_sensor_states();
        usleep(LOG_INTERVAL_MS * 1000);

        if (gpiod_line_bulk_read(&lines, GPIOD_LINE_VALUES_RAW)) {
            fprintf(stderr, "Failed to read lines\n");
            running = 0;
        }

        if (lines.values[0] && lines.values[1]) {
            printf("Both sensors triggered, stopping conveyor\n");
            // Here you would normally stop the conveyor
        }
    }

    fclose(log_file);
    gpiod_chip_close(chip);
    return EXIT_SUCCESS;
}

#include <stdio.h>
