#include <string.h>
#include <fcntl.h>
#include <unistd.h>
#include <sys/ioctl.h>
#include <linux/i2c-dev.h>
#include <math.h>
#include <signal.h>

#define I2C_BUS "/dev/i2c-1"
#define I2C_ADDRESS 0x1D
#define WHO_AM_I 0x0D
#define CTRL_REG1 0x2A
#define X_OUT 0x01
#define Y_OUT 0x03
#define Z_OUT 0x05
#define FALL_DEGREE_THRESHOLD 45.0

static int i2c_fd = -1;
static FILE *log_file = NULL;

void cleanup(int signum) {
    if (i2c_fd != -1) close(i2c_fd);
    if (log_file != NULL) fclose(log_file);
    exit(signum);
}

int main() {
    struct sigaction action;
    memset(&action, 0, sizeof(action));
    action.sa_handler = cleanup;
    sigaction(SIGINT, &action, NULL);
    sigaction(SIGTERM, &action, NULL);

    if ((i2c_fd = open(I2C_BUS, O_RDWR)) < 0) {
        perror("Failed to open the i2c bus");
        return 1;
    }

    if (ioctl(i2c_fd, I2C_SLAVE, I2C_ADDRESS) < 0) {
        perror("Failed to acquire bus access and/or talk to slave");
        return 1;
    }

    char who_am_i;
    if (read(i2c_fd, &who_am_i, 1) != 1 || who_am_i != 0x2A) {
        fprintf(stderr, "Failed to verify sensor identity\n");
        return 1;
    }

    char ctrl_reg1 = 0x01; // Place in standby mode
    if (write(i2c_fd, &ctrl_reg1, 1) != 1) {
        perror("Failed to initialize sensor");
        return 1;
    }

    ctrl_reg1 = 0x0A; // Set data rate to 100 Hz
    if (write(i2c_fd, &ctrl_reg1, 1) != 1) {
        perror("Failed to set sensor data rate");
        return 1;
    }

    ctrl_reg1 = 0x03; // Switch to active mode
    if (write(i2c_fd, &ctrl_reg1, 1) != 1) {
        perror("Failed to activate sensor");
        return 1;
    }

    log_file = fopen("fall_log.txt", "a");
    if (log_file == NULL) {
        perror("Failed to open log file");
        return 1;
    }

    while (1) {
        char data[6];
        if (read(i2c_fd, data, 6) != 6) {
            perror("Failed to read sensor data");
            continue;
        }

        int16_t x = (data[1] << 8) | data[0];
        int16_t y = (data[3] << 8) | data[2];
        int16_t z = (data[5] << 8) | data[4];

        double tilt_angle = atan2(x, sqrt(y*y + z*z)) * (180.0 / M_PI);

        if (fabs(tilt_angle) > FALL_DEGREE_THRESHOLD) {
            fprintf(log_file, "%ld: X=%d, Y=%d, Z=%d\n", time(NULL), x, y, z);
            fflush(log_file);
        }

        usleep(10000); // 10 ms
    }

    return 0;
}

