#define LIS3MDL_CTRL_REG4 0x23
#define LIS3MDL_CTRL_REG3 0x22
#define LIS3MDL_OUT_X_L 0x28
#define LIS3MDL_OUT_Y_L 0x2A
#define LIS3MDL_OUT_Z_L 0x2C
#define LIS3MDL_ODR_80Hz 0x70
#define LIS3MDL_FS_4G 0x0C
#define LIS3MDL_SENSITIVITY 0.146

volatile sig_atomic_t stop = 0;

void signal_handler(int signum) {
    stop = 1;
}

int main() {
    int i2c_fd, log_fd;
    uint8_t who_am_i, ctrl_reg1, ctrl_reg4, ctrl_reg3;
    int16_t x, y, z;
    float xf, yf, zf;
    char buffer[256];

    if ((i2c_fd = open("/dev/i2c-1", O_RDWR)) < 0) {
        perror("Failed to open i2c device");
        return EXIT_FAILURE;
    }

    if (ioctl(i2c_fd, I2C_SLAVE, LIS3MDL_ADDRESS) < 0) {
        perror("Failed to set i2c slave address");
        close(i2c_fd);
        return EXIT_FAILURE;
    }

    if (write(i2c_fd, &LIS3MDL_WHO_AM_I, 1) != 1) {
        perror("Failed to write to i2c device");
        close(i2c_fd);
        return EXIT_FAILURE;
    }

    if (read(i2c_fd, &who_am_i, 1) != 1) {
        perror("Failed to read from i2c device");
        close(i2c_fd);
        return EXIT_FAILURE;
    }

    if (who_am_i != 0x3D) {
        fprintf(stderr, "Incorrect WHO_AM_I value: 0x%02X\n", who_am_i);
        close(i2c_fd);
        return EXIT_FAILURE;
    }

    ctrl_reg1 = LIS3MDL_ODR_80Hz;
    if (write(i2c_fd, &ctrl_reg1, 1) != 1) {
        perror("Failed to write to i2c device");
        close(i2c_fd);
        return EXIT_FAILURE;
    }

    ctrl_reg4 = LIS3MDL_FS_4G;
    if (write(i2c_fd, &ctrl_reg4, 1) != 1) {
        perror("Failed to write to i2c device");
        close(i2c_fd);
        return EXIT_FAILURE;
    }

    ctrl_reg3 = 0x00;
    if (write(i2c_fd, &ctrl_reg3, 1) != 1) {
        perror("Failed to write to i2c device");
        close(i2c_fd);
        return EXIT_FAILURE;
    }

    if ((log_fd = open("magnetic_log.txt", O_WRONLY | O_CREAT | O_TRUNC, 0644)) < 0) {
        perror("Failed to open log file");
        close(i2c_fd);
        return EXIT_FAILURE;
    }

    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    while (!stop) {
        if (write(i2c_fd, &LIS3MDL_OUT_X_L, 1) != 1) {
            perror("Failed to write to i2c device");
            break;
        }

        if (read(i2c_fd, &x, 2) != 2) {
            perror("Failed to read from i2c device");
            break;
        }

        if (write(i2c_fd, &LIS3MDL_OUT_Y_L, 1) != 1) {
            perror("Failed to write to i2c device");
            break;
        }

        if (read(i2c_fd, &y, 2) != 2) {
            perror("Failed to read from i2c device");
            break;
        }

        if (write(i2c_fd, &LIS3MDL_OUT_Z_L, 1) != 1) {
            perror("Failed to write to i2c device");
            break;
        }

        if (read(i2c_fd, &z, 2) != 2) {
            perror("Failed to read from i2c device");
            break;
        }

        xf = (float)x * LIS3MDL_SENSITIVITY;
        yf = (float)y * LIS3MDL_SENSITIVITY;
        zf = (float)z * LIS3MDL_SENSITIVITY;

        snprintf(buffer, sizeof(buffer), "%.2f,%.2f,%.2f\n", xf, yf, zf);
        if (write(log_fd, buffer, strlen(buffer)) != strlen(buffer)) {
            perror("Failed to write to log file");
            break;
        }

        if (xf * xf + yf * yf + zf * zf > 800 * 800) {
            fprintf(stderr, "Metal detected!\n");
        }

        usleep(100000); // 10 Hz
    }

    close(log_fd);
    close(i2c_fd);

    return EXIT_SUCCESS;
}
```
This code should be compiled and run on a Raspberry Pi 3 Model B+ with the Adafruit LIS3MDL Triple-Axis Magnetometer connected to the I2C bus. It will continuously read the magnetic field data from the sensor and append it to 'magnetic_log.txt' at 10 Hz. If the total magnetic field magnitude exceeds 800 mG, it will print a metal-detected alert to stderr.
