#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <signal.h>
#include <time.h>
#include <pigpio.h>

#define SPI_CHANNEL 0
#define SPI_SPEED 1000000
#define SPI_MODE 0
#define SPI_READ_BIT 0x40
#define SPI_MULTI_BYTE_BIT 0x20
#define ACCEL_RANGE 2.0f // g
#define ACCEL_SENSITIVITY 0.0000039f // g/LSB
#define ACCEL_DATA_BYTES 3
#define ACCEL_RESET_REG 0x1F
#define ACCEL_RESET_VALUE 0x52
#define ACCEL_POWER_CTL_REG 0x2D
#define ACCEL_RUN_BIT 0x00
#define ACCEL_STATUS_REG 0x04
#define ACCEL_STABLE_BIT 0x01
#define ACCEL_PARTID_REG 0x01
#define ACCEL_PARTID_VALUE 0x1D
#define ACCEL_XDATA_REG 0x08
#define ACCEL_YDATA_REG 0x0B
#define ACCEL_ZDATA_REG 0x0E
#define ACCEL_LOG_INTERVAL 100 // ms
#define ACCEL_LOG_FILE "vibration_log.txt"

volatile sig_atomic_t running = 1;

void signal_handler(int signum) {
    running = 0;
}

int main() {
    FILE *log_file;
    int spi_handle;
    uint8_t partid;
    uint8_t reset_command[1] = {ACCEL_RESET_VALUE};
    uint8_t power_ctl_command[1] = {ACCEL_RUN_BIT};
    uint8_t status_command[1] = {ACCEL_STATUS_REG};
    uint8_t partid_command[1] = {ACCEL_PARTID_REG};
    uint8_t xdata_command[1] = {ACCEL_XDATA_REG};
    uint8_t ydata_command[1] = {ACCEL_YDATA_REG};
    uint8_t zdata_command[1] = {ACCEL_ZDATA_REG};
    uint8_t data[ACCEL_DATA_BYTES];
    float x, y, z;
    struct timespec start_time, current_time, elapsed_time;

    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    if ((spi_handle = spiOpen(SPI_CHANNEL, SPI_SPEED, SPI_MODE)) < 0) {
        fprintf(stderr, "Failed to open SPI channel\n");
        return EXIT_FAILURE;
    }

    if ((log_file = fopen(ACCEL_LOG_FILE, "w")) == NULL) {
        fprintf(stderr, "Failed to open log file\n");
        spiClose(spi_handle);
        return EXIT_FAILURE;
    }

    if (spiXfer(spi_handle, partid_command, 1, &partid, 1) != 1) {
        fprintf(stderr, "Failed to read PARTID\n");
        fclose(log_file);
        spiClose(spi_handle);
        return EXIT_FAILURE;
    }

    if (partid != ACCEL_PARTID_VALUE) {
        fprintf(stderr, "Invalid PARTID\n");
        fclose(log_file);
        spiClose(spi_handle);
        return EXIT_FAILURE;
    }

    if (spiXfer(spi_handle, reset_command, 1, NULL, 0) != 0) {
        fprintf(stderr, "Failed to write RESET value\n");
        fclose(log_file);
        spiClose(spi_handle);
        return EXIT_FAILURE;
    }

    usleep(1000);

    if (spiXfer(spi_handle, power_ctl_command, 1, NULL, 0) != 0) {
        fprintf(stderr, "Failed to set measurement mode\n");
        fclose(log_file);
        spiClose(spi_handle);
        return EXIT_FAILURE;
    }

    clock_gettime(CLOCK_MONOTONIC, &start_time);

    while (running) {
        if (spiXfer(spi_handle, status_command, 1, data, 1) != 1) {
            fprintf(stderr, "Failed to read STATUS\n");
            break;
        }

        if (!(data[0] & ACCEL_STABLE_BIT)) {
            continue;
        }

        if (spiXfer(spi_handle, xdata_command, 1, data, ACCEL_DATA_BYTES) != ACCEL_DATA_BYTES) {
            fprintf(stderr, "Failed to read XDATA\n");
            break;
        }

        x = (data[0] << 16 | data[1] << 8 | data[2]) * ACCEL_SENSITIVITY * ACCEL_RANGE;

        if (spiXfer(spi_handle, ydata_command, 1, data, ACCEL_DATA_BYTES) != ACCEL_DATA_BYTES) {
            fprintf(stderr, "Failed to read YDATA\n");
            break;
        }

        y = (data[0] << 16 | data[1] << 8 | data[2]) * ACCEL_SENSITIVITY * ACCEL_RANGE;

        if (spiXfer(spi_handle, zdata_command, 1, data, ACCEL_DATA_BYTES) != ACCEL_DATA_BYTES) {
            fprintf(stderr, "Failed to read ZDATA\n");
            break;
        }

        z = (data[0] << 16 | data[1] << 8 | data[2]) * ACCEL_SENSITIVITY * ACCEL_RANGE;

        clock_gettime(CLOCK_MONOTONIC, &current_time);
        elapsed_time.tv_sec = current_time.tv_sec - start_time.tv_sec;
        elapsed_time.tv_nsec = current_time.tv_nsec - start_time.tv_nsec;

        if (elapsed_time.tv_nsec < 0) {
            elapsed_time.tv_sec--;
            elapsed_time.tv_nsec += 1000000000;
        }

        fprintf(log_file, "%ld.%09ld %f %f %f\n", elapsed_time.tv_sec, elapsed_time.tv_nsec, x, y, z);

        usleep(ACCEL_LOG_INTERVAL * 1000);
    }

    fclose(log_file);
    spiClose(spi_handle);

    return EXIT_SUCCESS;
}

#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <unistd.h>
#include <signal.h>
#include <time.h>
#include <pigpio.h>

#define SPI_CHANNEL 0
#define SPI_SPEED 1000000
#define SPI_MODE 3
#define SPI_READ_BIT 0x80
#define GYRO_SCALE 0.05
#define ACCEL_SCALE 0.0025
#define SAMPLE_DELAY 10 // ms

FILE *log_file;
uint8_t spi_buffer[3];

void signal_handler(int signum) {
    if (signum == SIGINT) {
        fclose(log_file);
        gpioTerminate();
        exit(0);
    }
}

int spi_read(uint8_t address, uint16_t *data) {
    spi_buffer[0] = address | SPI_READ_BIT;
    spi_buffer[1] = 0x00;
    spi_buffer[2] = 0x00;
    if (spiXfer(SPI_CHANNEL, spi_buffer, spi_buffer, 3) < 0) {
        return -1;
    }
    *data = (spi_buffer[1] << 8) | spi_buffer[2];
    return 0;
}

int main() {
    signal(SIGINT, signal_handler);

    if (gpioInitialise() < 0) {
        fprintf(stderr, "Failed to initialize pigpio\n");
        return 1;
    }

    int spi_handle = spiOpen(SPI_CHANNEL, SPI_SPEED, SPI_MODE);
    if (spi_handle < 0) {
        fprintf(stderr, "Failed to open SPI channel\n");
        gpioTerminate();
        return 1;
    }

    log_file = fopen("imu_log.csv", "w");
    if (log_file == NULL) {
        fprintf(stderr, "Failed to open log file\n");
        spiClose(spi_handle);
        gpioTerminate();
        return 1;
    }

    fprintf(log_file, "Timestamp,X_Gyro,Y_Gyro,Z_Gyro,X_Accel,Y_Accel,Z_Accel\n");

    while (1) {
        uint16_t gyro_data[3], accel_data[3];
        struct timespec ts;

        clock_gettime(CLOCK_REALTIME, &ts);
        fprintf(log_file, "%ld.%09ld,", ts.tv_sec, ts.tv_nsec);

        for (int i = 0; i < 3; i++) {
            if (spi_read(0x04 + i * 2, &gyro_data[i]) < 0) {
                fprintf(stderr, "Failed to read gyro data\n");
                continue;
            }
            fprintf(log_file, "%.2f,", gyro_data[i] * GYRO_SCALE);

            if (spi_read(0x0A + i * 2, &accel_data[i]) < 0) {
                fprintf(stderr, "Failed to read accel data\n");
                continue;
            }
            fprintf(log_file, "%.2f,", accel_data[i] * ACCEL_SCALE);
        }

        fprintf(log_file, "\n");
        fflush(log_file);
        usleep(SAMPLE_DELAY * 1000);
    }

    fclose(log_file);
    spiClose(spi_handle);
    gpioTerminate();
    return 0;
}

