        fprintf(stderr, "Failed to request input direction for GPIO line %d\n", GPIO_LINE_NUMBER);
        return EXIT_FAILURE;
    }

    while (keep_running) {
        struct timespec ts = {POLL_INTERVAL, 0};
        nanosleep(&ts, NULL);

        int value = gpiod_line_get_value(line);
        if (value < 0) {
            fprintf(stderr, "Failed to read GPIO line %d\n", GPIO_LINE_NUMBER);
            return EXIT_FAILURE;
