        }
    }

    return EXIT_SUCCESS;
}

#include <stdio.h>
#include <stdlib.h>
#include <signal.h>
#include <time.h>
#include <libgpiod.h>

#define GPIO_CHIP "/dev/gpiochip0"
#define GPIO_LINE1 17
#define GPIO_LINE2 27
#define POLL_INTERVAL_MS 100

static struct gpiod_chip *chip;
static struct gpiod_line_bulk lines;
static int running = 1;

static void cleanup(void) {
    if (lines.lines) {
        gpiod_line_release_bulk(&lines);
    }
    if (chip) {
        gpiod_chip_close(chip);
    }
}

static void sigint_handler(int signum) {
    running = 0;
}

int main(int argc, char *argv[]) {
    struct timespec ts = {0, POLL_INTERVAL_MS * 1000000};
    unsigned int values[2];

    signal(SIGINT, sigint_handler);

    chip = gpiod_chip_open(GPIO_CHIP);
    if (!chip) {
        fprintf(stderr, "Failed to open GPIO chip %s\n", GPIO_CHIP);
        return EXIT_FAILURE;
    }

    lines.chip = chip;
    lines.num_lines = 2;
    lines.lines = (struct gpiod_line **)malloc(sizeof(struct gpiod_line *) * lines.num_lines);
    if (!lines.lines) {
        fprintf(stderr, "Failed to allocate memory for lines\n");
        cleanup();
        return EXIT_FAILURE;
    }

    lines.lines[0] = gpiod_chip_get_line(chip, GPIO_LINE1);
    lines.lines[1] = gpiod_chip_get_line(chip, GPIO_LINE2);
    if (!lines.lines[0] || !lines.lines[1]) {
        fprintf(stderr, "Failed to get lines %d and %d\n", GPIO_LINE1, GPIO_LINE2);
        cleanup();
        return EXIT_FAILURE;
    }

    if (gpiod_line_request_bulk(lines.lines, lines.num_lines, "collision_avoidance", 0) < 0) {
        fprintf(stderr, "Failed to request lines\n");
        cleanup();
        return EXIT_FAILURE;
    }

    while (running) {
        if (gpiod_line_request_get_values(chip, &lines, values) < 0) {
            fprintf(stderr, "Failed to read lines\n");
            cleanup();
            return EXIT_FAILURE;
        }

        printf("%ld.%09ld: Sensor 1: %s, Sensor 2: %s\n",
               (long)time(NULL), ts.tv_nsec,
               values[0] ? "clear" : "obstacle",
               values[1] ? "clear" : "obstacle");

        nanosleep(&ts, NULL);
    }

    cleanup();
    free(lines.lines);
    return EXIT_SUCCESS;
}

#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <stdbool.h>
#include <unistd.h>
#include <fcntl.h>
#include <sys/ioctl.h>
#include <linux/spi/spidev.h>
#include <gpiod.h>

#define SPI_MODE 3
#define SPI_SPEED 1000000
#define SPI_DEV "/dev/spidev0.0"
#define CS_PIN 8
#define MSC_CTRL 0x24
#define XGAIN 0x04
#define YGAIN 0x06
#define ZGAIN 0x08
#define SCALE_FACTOR 0.02

int spi_fd, gpiod_fd;
struct spi_ioc_transfer spi_xfer[2];
struct gpiod_line_request request;

void cleanup() {
    if (spi_fd >= 0) close(spi_fd);
    if (gpiod_fd >= 0) gpiod_line_release(gpiod_fd);
}

int main() {
    atexit(cleanup);

    // Open SPI device
    spi_fd = open(SPI_DEV, O_RDWR);
    if (spi_fd < 0) {
        perror("Failed to open SPI device");
        return EXIT_FAILURE;
    }

    // Configure SPI
    uint8_t mode = SPI_MODE;
    uint32_t speed = SPI_SPEED;
    if (ioctl(spi_fd, SPI_IOC_WR_MODE, &mode) < 0 ||
        ioctl(spi_fd, SPI_IOC_WR_MAX_SPEED_HZ, &speed) < 0) {
        perror("Failed to configure SPI");
        return EXIT_FAILURE;
    }

    // Open GPIO line for CS
    gpiod_fd = gpiod_open_line_request("gpiochip0", CS_PIN, &request);
    if (gpiod_fd < 0) {
        perror("Failed to open GPIO line");
        return EXIT_FAILURE;
    }

    // Request CS line
    if (gpiod_line_request_output(gpiod_fd, "spi_cs", 1) < 0) {
        perror("Failed to request CS line");
        return EXIT_FAILURE;
    }

    // Configure SPI transfers
    memset(spi_xfer, 0, sizeof(spi_xfer));
    spi_xfer[0].tx_buf = (unsigned long)&request;
    spi_xfer[0].len = sizeof(request);
    spi_xfer[1].rx_buf = (unsigned long)buffer;
    spi_xfer[1].len = 2;

    // Write to MSC_CTRL register
    request.tx_buf = MSC_CTRL;
    request.rx_buf = NULL;
    request.len = 1;
    if (ioctl(spi_fd, SPI_IOC_MESSAGE(1), &spi_xfer[0]) < 0) {
        perror("Failed to write to MSC_CTRL register");
        return EXIT_FAILURE;
    }

    // Main loop
    while (true) {
        // Send address with MSB set
        request.tx_buf = XGAIN | 0x80;
        request.rx_buf = NULL;
        request.len = 1;
        if (ioctl(spi_fd, SPI_IOC_MESSAGE(1), &spi_xfer[0]) < 0) {
            perror("Failed to send address");
            return EXIT_FAILURE;
        }

        // Read 2 bytes
        request.tx_buf = NULL;
        request.rx_buf = (unsigned long)buffer;
        request.len = 2;
        if (ioctl(spi_fd, SPI_IOC_MESSAGE(1), &spi_xfer[1]) < 0) {
            perror("Failed to read data");
            return EXIT_FAILURE;
        }

        // Convert to angular rate and log
        int16_t value = (buffer[0] << 8) | buffer[1];
        float angular_rate = value * SCALE_FACTOR;
        printf("X: %f deg/sec\n", angular_rate);

        // Sleep for 100 ms
        usleep(100000);
    }

    return EXIT_SUCCESS;
}

