#include <stdio.h>
#include <signal.h>
#include <pigpio.h>

#define FXOS8700_ADDRESS 0x1D
#define WHO_AM_I 0x0D
#define CTRL_REG1 0x2A
#define CTRL_REG2 0x2B
#define M_CTRL_REG1 0x5B
#define M_CTRL_REG2 0x5C
#define OUT_X_MSB 0x01

volatile sig_atomic_t stop = 0;

void signal_handler(int signum) {
    stop = 1;
}

int main() {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialization failed\n");
        return 1;
    }

    int i2c_handle = gpioI2COpen(1, FXOS8700_ADDRESS);
    if (i2c_handle < 0) {
        fprintf(stderr, "Failed to open I2C bus\n");
        gpioTerminate();
        return 1;
    }

    uint8_t who_am_i;
    if (gpioI2CReadByteData(i2c_handle, WHO_AM_I, &who_am_i) < 0) {
        fprintf(stderr, "Failed to read WHO_AM_I register\n");
        gpioI2CWriteByteData(i2c_handle, CTRL_REG1, 0x00);
        gpioI2CWriteByteData(i2c_handle, CTRL_REG2, 0x00);
        gpioI2CWriteByteData(i2c_handle, M_CTRL_REG1, 0x00);
        gpioI2CWriteByteData(i2c_handle, M_CTRL_REG2, 0x00);
        gpioI2CClose(i2c_handle);
        gpioTerminate();
        return 1;
    }

    if (who_am_i != 0xC7) {
        fprintf(stderr, "WHO_AM_I register does not match expected value\n");
        gpioI2CWriteByteData(i2c_handle, CTRL_REG1, 0x00);
        gpioI2CWriteByteData(i2c_handle, CTRL_REG2, 0x00);
        gpioI2CWriteByteData(i2c_handle, M_CTRL_REG1, 0x00);
        gpioI2CWriteByteData(i2c_handle, M_CTRL_REG2, 0x00);
        gpioI2CClose(i2c_handle);
        gpioTerminate();
        return 1;
    }

    gpioI2CWriteByteData(i2c_handle, CTRL_REG1, 0x01);
    gpioI2CWriteByteData(i2c_handle, CTRL_REG2, 0x00);
    gpioI2CWriteByteData(i2c_handle, M_CTRL_REG1, 0x01);
    gpioI2CWriteByteData(i2c_handle, M_CTRL_REG2, 0x00);

    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    while (!stop) {
        uint8_t data[12];
        if (gpioI2CReadData(i2c_handle, OUT_X_MSB, data, 12) < 0) {
            fprintf(stderr, "Failed to read sensor data\n");
            continue;
        }

        int16_t accel_x = (data[0] << 8) | data[1];
        int16_t accel_y = (data[2] << 8) | data[3];
        int16_t accel_z = (data[4] << 8) | data[5];
        int16_t mag_x = (data[6] << 8) | data[7];
        int16_t mag_y = (data[8] << 8) | data[9];
        int16_t mag_z = (data[10] << 8) | data[11];

        printf("Accel: X: %d, Y: %d, Z: %d\n", accel_x, accel_y, accel_z);
        printf("Magnet: X: %d, Y: %d, Z: %d\n", mag_x, mag_y, mag_z);

        gpioDelay(100000);
    }

    gpioI2CWriteByteData(i2c_handle, CTRL_REG1, 0x00);
    gpioI2CWriteByteData(i2c_handle, CTRL_REG2, 0x00);
    gpioI2CWriteByteData(i2c_handle, M_CTRL_REG1, 0x00);
    gpioI2CWriteByteData(i2c_handle, M_CTRL_REG2, 0x00);

    gpioI2CClose(i2c_handle);
    gpioTerminate();

    return 0;
}

