#include <stdio.h>
#include <stdlib.h>
#include <signal.h>
#include <time.h>
#include <pigpio.h>

#define GPIO_PIN 17
#define WINDOW_SIZE 5000 // 5 seconds
#define SAMPLE_INTERVAL 1000 // 1 ms

volatile sig_atomic_t stop = 0;

void handle_signal(int signum) {
    stop = 1;
}

int main(int argc, char *argv[]) {
    if (argc != 2) {
        fprintf(stderr, "Usage: %s <threshold>\n", argv[0]);
        return EXIT_FAILURE;
    }

    int threshold;
    if (sscanf(argv[1], "%d", &threshold) != 1 || threshold <= 0) {
        fprintf(stderr, "Error: Threshold must be a positive integer.\n");
        return EXIT_FAILURE;
    }

    if (gpioInitialise() < 0) {
        fprintf(stderr, "Error: Failed to initialize pigpio.\n");
        return EXIT_FAILURE;
    }

    if (gpioSetMode(GPIO_PIN, PI_INPUT) < 0) {
        fprintf(stderr, "Error: Failed to set GPIO mode.\n");
        gpioTerminate();
        return EXIT_FAILURE;
    }

    signal(SIGINT, handle_signal);
    signal(SIGTERM, handle_signal);

    int high_count = 0;
    struct timespec start_time, current_time;
    clock_gettime(CLOCK_MONOTONIC, &start_time);

    while (!stop) {
        if (gpioRead(GPIO_PIN) == PI_HIGH) {
            high_count++;
        }

        clock_gettime(CLOCK_MONOTONIC, &current_time);
        if ((current_time.tv_sec - start_time.tv_sec) * 1000 + (current_time.tv_nsec - start_time.tv_nsec) / 1000000 >= WINDOW_SIZE) {
            if (high_count >= threshold) {
                printf("%ld.%09ld ALERT: High reading count %d exceeds threshold %d\n", current_time.tv_sec, current_time.tv_nsec, high_count, threshold);
            } else {
                printf("%ld.%09ld Status: High reading count %d\n", current_time.tv_sec, current_time.tv_nsec, high_count);
            }

            high_count = 0;
            start_time = current_time;
        }

        usleep(SAMPLE_INTERVAL);
    }

    gpioTerminate();
    return EXIT_SUCCESS;
}

#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <unistd.h>
#include <libgpiod.h>

#define DOOR_A_PIN 17
#define DOOR_B_PIN 27
#define CODE_MIN 100000
#define CODE_MAX 999999
#define LOG_FILE "access_log.txt"

volatile sig_atomic_t exit_flag = 0;

void sig_handler(int signum) {
    exit_flag = 1;
}

int main() {
    struct gpiod_chip *chip;
    struct gpiod_line *line_a, *line_b;
    FILE *log_file;
    int code, user_code;
    time_t t;

    // Register signal handler
    signal(SIGINT, sig_handler);
    signal(SIGTERM, sig_handler);

    // Open GPIO chip
    chip = gpiod_chip_open("/dev/gpiochip0");
    if (!chip) {
        fprintf(stderr, "Failed to open GPIO chip\n");
        return EXIT_FAILURE;
    }

    // Get GPIO lines
    line_a = gpiod_chip_get_line(chip, DOOR_A_PIN);
    line_b = gpiod_chip_get_line(chip, DOOR_B_PIN);
    if (!line_a || !line_b) {
        fprintf(stderr, "Failed to get GPIO lines\n");
        gpiod_chip_close(chip);
        return EXIT_FAILURE;
    }

    // Request GPIO lines
    if (gpiod_line_request_output(line_a, "door_a", 0) < 0 ||
        gpiod_line_request_output(line_b, "door_b", 0) < 0) {
        fprintf(stderr, "Failed to request GPIO lines\n");
        gpiod_chip_close(chip);
        return EXIT_FAILURE;
    }

    // Open log file
    log_file = fopen(LOG_FILE, "a");
    if (!log_file) {
        fprintf(stderr, "Failed to open log file\n");
        gpiod_chip_close(chip);
        return EXIT_FAILURE;
    }

    // Generate random code
    srand((unsigned) time(&t));
    code = rand() % (CODE_MAX - CODE_MIN + 1) + CODE_MIN;
    printf("Enter the code: %06d\n", code);

    // Main loop
    while (!exit_flag) {
        printf("Enter the code: ");
        scanf("%d", &user_code);
        while (getchar() != '\n'); // Clear input buffer

        if (user_code == code) {
            gpiod_line_set_value(line_a, 1);
            gpiod_line_set_value(line_b, 1);
            sleep(5);
            gpiod_line_set_value(line_a, 0);
            gpiod_line_set_value(line_b, 0);

            // Log successful entry
            time(&t);
            fprintf(log_file, "%s,%06d\n", ctime(&t), code);
            fflush(log_file);

            // Generate new random code
            code = rand() % (CODE_MAX - CODE_MIN + 1) + CODE_MIN;
            printf("Enter the code: %06d\n", code);
        } else {
            printf("Access denied\n");
        }
    }

    // Release resources
    gpiod_line_release(line_a);
    gpiod_line_release(line_b);
    gpiod_chip_close(chip);
    fclose(log_file);

    return EXIT_SUCCESS;
}

#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <string.h>
#include <fcntl.h>
#include <unistd.h>
#include <sys/ioctl.h>
#include <linux/i2c-dev.h>
#include <time.h>
#include <signal.h>

#define I2C_BUS "/dev/i2c-1"
#define BH1750_ADDRESS 0x23
#define BH1750_CMD_ONE_TIME_HIGH_RES_MODE_2 0x21
#define BH1750_DATA_LENGTH 2
#define CONVERSION_TIME_MS 180
#define LOG_FILE "light_log.txt"

int i2c_fd = -1;
FILE *log_fd = NULL;

void cleanup(int signum) {
    if (i2c_fd != -1) {
        close(i2c_fd);
    }
    if (log_fd != NULL) {
        fclose(log_fd);
    }
    exit(signum);
}

int main() {
    struct sigaction action;
    memset(&action, 0, sizeof(action));
    action.sa_handler = cleanup;
    sigaction(SIGINT, &action, NULL);

    if ((i2c_fd = open(I2C_BUS, O_RDWR)) < 0) {
        perror("Failed to open the i2c bus");
        return 1;
    }

    if (ioctl(i2c_fd, I2C_SLAVE, BH1750_ADDRESS) < 0) {
        perror("Failed to acquire bus access and/or talk to slave");
        return 1;
    }

    if (write(i2c_fd, &BH1750_CMD_ONE_TIME_HIGH_RES_MODE_2, 1) != 1) {
        perror("Failed to write command to BH1750");
        return 1;
    }

    usleep(CONVERSION_TIME_MS * 1000);

    uint8_t data[BH1750_DATA_LENGTH];
    if (read(i2c_fd, data, BH1750_DATA_LENGTH) != BH1750_DATA_LENGTH) {
        perror("Failed to read data from BH1750");
        return 1;
    }

    if ((log_fd = fopen(LOG_FILE, "a")) == NULL) {
        perror("Failed to open log file");
        return 1;
    }

    uint16_t raw_value = (data[0] << 8) | data[1];
    float lux = (raw_value * 5) / 6.0;

    time_t now = time(NULL);
    struct tm *t = localtime(&now);
    char timestamp[20];
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", t);

    fprintf(log_fd, "Timestamp: %s, Lux: %.2f\n", timestamp, lux);

    fclose(log_fd);
    close(i2c_fd);

    return 0;
}

#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <unistd.h>
#include <signal.h>
#include <sys/socket.h>
#include <netinet/in.h>
#include <arpa/inet.h>
#include <pigpio.h>

#define I2C_BUS 1
#define I2C_ADDRESS 0x5A
#define MOTION_DETECTED "MOTION_DETECTED:"
#define SHARED_SECRET "MySecretKey"
#define PWM_PIN 18
#define PWM_FREQ 440
#define PWM_DUTY 50
#define MAX_ELECTRODE_VALUE 255
#define MIN_FREQUENCY 220
#define MAX_FREQUENCY 880
#define SAMPLE_INTERVAL 20
#define PLAYBACK_DURATION 5000
#define LOG_FILE "frequency_log.txt"

int i2c_handle;
int pwm_handle;
int server_socket;
int client_socket;
struct sockaddr_in server_addr;
struct sockaddr_in client_addr;
char buffer[256];

void cleanup() {
    gpioTerminate();
    close(i2c_handle);
    close(server_socket);
    close(client_socket);
}

void handle_sigint(int signum) {
    cleanup();
    exit(0);
}

void handle_sigterm(int signum) {
    cleanup();
    exit(0);
}

void play_tones() {
    FILE *log_file = fopen(LOG_FILE, "w");
    if (!log_file) {
        perror("Failed to open log file");
        return;
    }

    int electrode_values[MAX_ELECTRODE_VALUE + 1] = {0};
    for (int i = 0; i <= MAX_ELECTRODE_VALUE; i++) {
        float frequency = MIN_FREQUENCY + (MAX_FREQUENCY - MIN_FREQUENCY) * log2((float)i / MAX_ELECTRODE_VALUE);
        gpioSetPWMfrequency(PWM_PIN, frequency);
        gpioSetPWMdutycycle(PWM_PIN, PWM_DUTY);
        usleep(SAMPLE_INTERVAL * 1000);
        gpioSetPWMfrequency(PWM_PIN, 0);
        electrode_values[i] = frequency;
        fprintf(log_file, "%d: %f\n", i, frequency);
    }

    fclose(log_file);
}

int main() {
    signal(SIGINT, handle_sigint);
    signal(SIGTERM, handle_sigterm);

    if (gpioInitialise() < 0) {
        perror("Failed to initialize pigpio");
        return 1;
    }

    i2c_handle = open("/dev/i2c-1", O_RDWR);
    if (i2c_handle < 0) {
        perror("Failed to open I2C bus");
        return 1;
    }

    if (ioctl(i2c_handle, I2C_SLAVE, I2C_ADDRESS) < 0) {
        perror("Failed to set I2C address");
        return 1;
    }

    server_socket = socket(AF_INET, SOCK_STREAM, 0);
    if (server_socket < 0) {
        perror("Failed to create server socket");
        return 1;
    }

    memset(&server_addr, 0, sizeof(server_addr));
    server_addr.sin_family = AF_INET;
    server_addr.sin_addr.s_addr = INADDR_ANY;
    server_addr.sin_port = htons(12345);

    if (bind(server_socket, (struct sockaddr *)&server_addr, sizeof(server_addr)) < 0) {
        perror("Failed to bind server socket");
        return 1;
    }

    if (listen(server_socket, 5) < 0) {
        perror("Failed to listen on server socket");
        return 1;
    }

    while (1) {
        socklen_t client_addr_len = sizeof(client_addr);
        client_socket = accept(server_socket, (struct sockaddr *)&client_addr, &client_addr_len);
        if (client_socket < 0) {
            perror("Failed to accept client connection");
            continue;
        }

        memset(buffer, 0, sizeof(buffer));
        if (recv(client_socket, buffer, sizeof(buffer), 0) < 0) {
            perror("Failed to receive message from client");
            continue;
        }

        if (strncmp(buffer, MOTION_DETECTED, strlen(MOTION_DETECTED)) == 0 && strstr(buffer, SHARED_SECRET) != NULL) {
            play_tones();
        }

        close(client_socket);
    }

    cleanup();
    return 0;
}

