#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <unistd.h>
#include <fcntl.h>
#include <signal.h>
#include <sys/ioctl.h>
#include <linux/i2c-dev.h>
#include <gpiod.h>

#define I2C_BUS "/dev/i2c-1"
#define I2C_ADDRESS 0x1E
#define LED_PIN 17
#define PWM_CHAN 0
#define PWM_FREQ 1000
#define PWM_DUTY_MAX 255

static int i2c_fd = -1;
static int pwm_fd = -1;

void cleanup(int signum) {
    if (pwm_fd != -1) {
        gpiod_pwm_release(pwm_fd);
    }
    if (i2c_fd != -1) {
        close(i2c_fd);
    }
    exit(signum);
}

int main() {
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = cleanup;
    sigaction(SIGINT, &sa, NULL);
    sigaction(SIGTERM, &sa, NULL);

    i2c_fd = open(I2C_BUS, O_RDWR);
    if (i2c_fd < 0) {
        perror("Failed to open I2C bus");
        return 1;
    }

    if (ioctl(i2c_fd, I2C_SLAVE, I2C_ADDRESS) < 0) {
        perror("Failed to set I2C address");
        return 1;
    }

    uint8_t ctrl_reg1_m = 0x18;
    if (write(i2c_fd, &ctrl_reg1_m, 1) != 1) {
        perror("Failed to write to CTRL_REG1_M");
        return 1;
    }

    pwm_fd = gpiod_pwm_open(LED_PIN, PWM_CHAN, PWM_FREQ, PWM_DUTY_MAX);
    if (pwm_fd < 0) {
        perror("Failed to open PWM");
        return 1;
    }

    while (1) {
        uint8_t data[6];
        if (read(i2c_fd, data, 6) != 6) {
            perror("Failed to read from magnetometer");
            continue;
        }

        int16_t x = (data[0] << 8) | data[1];
        int16_t y = (data[2] << 8) | data[3];
        int16_t z = (data[4] << 8) | data[5];

        uint8_t duty_cycle = (uint8_t)((abs(z) * PWM_DUTY_MAX) / 4096);
        gpiod_pwm_set_duty_cycle(pwm_fd, duty_cycle);

        usleep(100000);
    }

    return 0;
}

#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <signal.h>
#include <pigpio.h>

#define HMC5883L_ADDRESS 0x1E
#define HMC5883L_CONFIG_A 0x00
#define HMC5883L_CONFIG_B 0x01
#define HMC5883L_MODE 0x02
#define HMC5883L_DATA_X 0x03
#define HMC5883L_DATA_Y 0x07
#define HMC5883L_DATA_Z 0x05
#define HMC5883L_SAMPLERATE 0x10
#define HMC5883L_GAIN 0x20

volatile sig_atomic_t running = 1;

void signal_handler(int signum) {
    running = 0;
}

int main() {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Failed to initialize pigpio library\n");
        return EXIT_FAILURE;
    }

    int i2c_handle = gpioI2COpen(1, HMC5883L_ADDRESS);
    if (i2c_handle < 0) {
        fprintf(stderr, "Failed to open I2C bus\n");
        gpioTerminate();
        return EXIT_FAILURE;
    }

    struct sigaction action;
    memset(&action, 0, sizeof(struct sigaction));
    action.sa_handler = signal_handler;
    sigaction(SIGINT, &action, NULL);
    sigaction(SIGTERM, &action, NULL);

    int samples = 0;
    int16_t offsets[3] = {0, 0, 0};

    while (running) {
        int16_t raw[3];
        if (gpioI2CReadReg16(i2c_handle, HMC5883L_DATA_X, &raw[0]) < 0) {
            fprintf(stderr, "Failed to read X value\n");
            continue;
        }
        if (gpioI2CReadReg16(i2c_handle, HMC5883L_DATA_Y, &raw[1]) < 0) {
            fprintf(stderr, "Failed to read Y value\n");
            continue;
        }
        if (gpioI2CReadReg16(i2c_handle, HMC5883L_DATA_Z, &raw[2]) < 0) {
            fprintf(stderr, "Failed to read Z value\n");
            continue;
        }

        if (samples < 100) {
            for (int i = 0; i < 3; i++) {
                offsets[i] += raw[i];
            }
            samples++;
        } else {
            for (int i = 0; i < 3; i++) {
                offsets[i] /= 100;
            }

            printf("X: %d, Y: %d, Z: %d\n", raw[0] - offsets[0], raw[1] - offsets[1], raw[2] - offsets[2]);
            samples = 0;
            memset(offsets, 0, sizeof(offsets));
        }

        gpioDelay(500000); // 500 ms
    }

    gpioI2CWriteReg(i2c_handle, HMC5883L_MODE, 0x00); // Switch to standby mode
    gpioI2CWriteReg(i2c_handle, HMC5883L_CONFIG_A, 0x70); // Set configuration register A
    gpioI2CWriteReg(i2c_handle, HMC5883L_CONFIG_B, 0x20); // Set configuration register B
    gpioI2CWriteReg(i2c_handle, HMC5883L_MODE, 0x00); // Switch to continuous mode

    gpioI2CClose(i2c_handle);
    gpioTerminate();

    return EXIT_SUCCESS;
}

#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <stdbool.h>
#include <string.h>
#include <unistd.h>
#include <fcntl.h>
#include <sys/ioctl.h>
#include <linux/i2c-dev.h>
#include <gpiod.h>

#define LSM303D_ADDRESS 0x1D
#define LSM303D_INT1_PIN 23
#define LSM303D_WHO_AM_I 0x0F
#define LSM303D_CTRL_REG1 0x20
#define LSM303D_CTRL_REG4 0x23
#define LSM303D_INT1_CFG 0x30
#define LSM303D_OUT_X_L_A 0x28
#define LSM303D_OUT_X_H_A 0x29
#define LSM303D_OUT_Y_L_A 0x2A
#define LSM303D_OUT_Y_H_A 0x2B
#define LSM303D_OUT_Z_L_A 0x2C
#define LSM303D_OUT_Z_H_A 0x2D
#define LSM303D_THRESHOLD 2000
#define LSM303D_DURATION 0
#define LSM303D_ODR 50
#define LSM303D_FS 2
#define LSM303D_SAMPLES 64
#define LSM303D_INTERVAL 10

static int i2c_fd;
static int gpio_fd;
static uint8_t buffer[LSM303D_SAMPLES * 3];
static size_t buffer_head = 0;
static bool running = true;

static void handle_interrupt() {
    printf("Interrupt received\n");
    for (size_t i = 0; i < 10; ++i) {
        size_t index = (buffer_head - i - 1) % LSM303D_SAMPLES;
        printf("Sample %zu: %02X %02X %02X\n", i, buffer[index * 3], buffer[index * 3 + 1], buffer[index * 3 + 2]);
    }
    gpiod_event_wait(gpio_fd, NULL);
}

static void handle_sigint(int signum) {
    printf("SIGINT received\n");
    running = false;
}

int main() {
    struct sigaction sigint_action;
    memset(&sigint_action, 0, sizeof(sigint_action));
    sigint_action.sa_handler = handle_sigint;
    sigaction(SIGINT, &sigint_action, NULL);

    i2c_fd = open("/dev/i2c-1", O_RDWR);
    if (i2c_fd < 0) {
        perror("Failed to open I2C device");
        return EXIT_FAILURE;
    }

    if (ioctl(i2c_fd, I2C_SLAVE, LSM303D_ADDRESS) < 0) {
        perror("Failed to set I2C slave address");
        close(i2c_fd);
        return EXIT_FAILURE;
    }

    gpio_fd = gpiod_open_by_number(LSM303D_INT1_PIN, GPIOD_OPEN_BY_NUMBER);
    if (gpio_fd < 0) {
        perror("Failed to open GPIO device");
        close(i2c_fd);
        return EXIT_FAILURE;
    }

    struct gpiod_event_request_config event_config;
    memset(&event_config, 0, sizeof(event_config));
    event_config.event_type = GPIOD_EVENT_RISING_EDGE;
    event_config.debounce_period = 0;
    if (gpiod_event_request_enable(gpio_fd, &event_config) < 0) {
        perror("Failed to enable GPIO event request");
        close(gpio_fd);
        close(i2c_fd);
        return EXIT_FAILURE;
    }

    if (gpiod_event_wait(gpio_fd, NULL) < 0) {
        perror("Failed to wait for GPIO event");
        close(gpio_fd);
        close(i2c_fd);
        return EXIT_FAILURE;
    }

    if (write(i2c_fd, &LSM303D_WHO_AM_I, 1) < 0) {
        perror("Failed to write to I2C device");
        close(gpio_fd);
        close(i2c_fd);
        return EXIT_FAILURE;
    }

    uint8_t who_am_i;
    if (read(i2c_fd, &who_am_i, 1) < 0) {
        perror("Failed to read from I2C device");
        close(gpio_fd);
        close(i2c_fd);
        return EXIT_FAILURE;
    }

    if (who_am_i != 0x49) {
        fprintf(stderr, "Invalid WHO_AM_I value: 0x%02X\n", who_am_i);
        close(gpio_fd);
        close(i2c_fd);
        return EXIT_FAILURE;
    }

    if (write(i2c_fd, &LSM303D_CTRL_REG1, 1) < 0) {
        perror("Failed to write to I2C device");
        close(gpio_fd);
        close(i2c_fd);
        return EXIT_FAILURE;
    }

    uint8_t ctrl_reg1 = LSM303D_ODR << 4;
    if (write(i2c_fd, &ctrl_reg1, 1) < 0) {
        perror("Failed to write to I2C device");
        close(gpio_fd);
        close(i2c_fd);
        return EXIT_FAILURE;
    }

    if (write(i2c_fd, &LSM303D_CTRL_REG4, 1) < 0) {
        perror("Failed to write to I2C device");
        close(gpio_fd);
        close(i2c_fd);
        return EXIT_FAILURE;
    }

    uint8_t ctrl_reg4 = LSM303D_FS << 4;
    if (write(i2c_fd, &ctrl_reg4, 1) < 0) {
        perror("Failed to write to I2C device");
        close(gpio_fd);
        close(i2c_fd);
        return EXIT_FAILURE;
    }

    if (write(i2c_fd, &LSM303D_INT1_CFG, 1) < 0) {
        perror("Failed to write to I2C device");
        close(gpio_fd);
        close(i2c_fd);
        return EXIT_FAILURE;
    }

    uint8_t int1_cfg = LSM303D_THRESHOLD >> 3;
    if (write(i2c_fd, &int1_cfg, 1) < 0) {
        perror("Failed to write to I2C device");
        close(gpio_fd);
        close(i2c_fd);
        return EXIT_FAILURE;
    }

    while (running) {
        if (write(i2c_fd, &LSM303D_OUT_X_L_A, 1) < 0) {
            perror("Failed to write to I2C device");
            continue;
        }

        uint8_t data[6];
        if (read(i2c_fd, data, 6) < 0) {
            perror("Failed to read from I2C device");
            continue;
        }

        buffer[buffer_head * 3] = data[0];
        buffer[buffer_head * 3 + 1] = data[1];
        buffer[buffer_head * 3 + 2] = data[2];
        buffer_head = (buffer_head + 1) % LSM303D_SAMPLES;
    }

    if (write(i2c_fd, &LSM303D_CTRL_REG1, 1) < 0) {
        perror("Failed to write to I2C device");
    }

    close(gpio_fd);
    close(i2c_fd);
    return EXIT_SUCCESS;
}

#include <stdio.h>
#include <stdlib.h>
#include <signal.h>
#include <unistd.h>
#include <libgpiod.h>

static void cleanup(gpiod_line_bulk lines) {
    gpiod_line_set_value_bulk(lines, GPIO_LOW);
    gpiod_line_release_bulk(lines);
}

static void sig_handler(int signum) {
    gpiod_line_bulk lines;
    lines.num_lines = 2;
    lines.lines = (gpiod_line *)malloc(sizeof(gpiod_line) * lines.num_lines);
    lines.lines[0] = gpiod_chip_get_line(gpiod_chip_open_by_offset(0, 17), 17);
    lines.lines[1] = gpiod_chip_get_line(gpiod_chip_open_by_offset(0, 27), 27);
    cleanup(lines);
    free(lines.lines);
    exit(signum);
}

int main() {
    struct sigaction sigIntHandler;
    sigIntHandler.sa_handler = sig_handler;
    sigemptyset(&sigIntHandler.sa_mask);
    sigIntHandler.sa_flags = 0;
    sigaction(SIGINT, &sigIntHandler, NULL);
    sigaction(SIGTERM, &sigIntHandler, NULL);

    gpiod_chip *chip1 = gpiod_chip_open_by_offset(0, 17);
    gpiod_chip *chip2 = gpiod_chip_open_by_offset(0, 27);
    gpiod_line *line1 = gpiod_chip_get_line(chip1, 17);
    gpiod_line *line2 = gpiod_chip_get_line(chip2, 27);
    gpiod_line_bulk lines;
    lines.num_lines = 2;
    lines.lines = (gpiod_line *)malloc(sizeof(gpiod_line) * lines.num_lines);
    lines.lines[0] = line1;
    lines.lines[1] = line2;

    if (gpiod_line_request_output(line1, "solenoid1", GPIO_LOW) < 0) {
        fprintf(stderr, "Failed to request line 17 as output\n");
        cleanup(lines);
        free(lines.lines);
        return EXIT_FAILURE;
    }
    if (gpiod_line_request_output(line2, "solenoid2", GPIO_LOW) < 0) {
        fprintf(stderr, "Failed to request line 27 as output\n");
        cleanup(lines);
        free(lines.lines);
        return EXIT_FAILURE;
    }

    while (1) {
        gpiod_line_set_value_bulk(lines, GPIO_HIGH);
        nanosleep((const struct timespec[]){{0, 500000000L}}, NULL);
        gpiod_line_set_value_bulk(lines, GPIO_LOW);
        nanosleep((const struct timespec[]){{0, 500000000L}}, NULL);
    }

    cleanup(lines);
    free(lines.lines);
    return EXIT_SUCCESS;
}

#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <signal.h>
#include <pigpio.h>
#include <errno.h>

#define CODE_LEN 6
#define CODE "123456"
#define TIMEOUT 5
#define OPEN_TIME 2000

static volatile sig_atomic_t running = 1;

void terminate(int signum) {
    running = 0;
}

int main() {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Failed to initialize pigpio: %s\n", strerror(errno));
        return EXIT_FAILURE;
    }

    signal(SIGINT, terminate);
    signal(SIGTERM, terminate);

    int gpio17 = 17;
    int gpio27 = 27;
    int serial0 = 14;
    int serial1 = 15;

    if (gpioSetMode(gpio17, PI_OUTPUT) < 0) {
        fprintf(stderr, "Failed to set GPIO17 mode: %s\n", strerror(errno));
        goto cleanup;
    }

    if (gpioSetMode(gpio27, PI_OUTPUT) < 0) {
        fprintf(stderr, "Failed to set GPIO27 mode: %s\n", strerror(errno));
        goto cleanup;
    }

    if (gpioWrite(gpio17, PI_LOW) < 0) {
        fprintf(stderr, "Failed to write GPIO17: %s\n", strerror(errno));
        goto cleanup;
    }

    if (gpioWrite(gpio27, PI_LOW) < 0) {
        fprintf(stderr, "Failed to write GPIO27: %s\n", strerror(errno));
        goto cleanup;
    }

    int fd0 = serialOpen("/dev/serial0", 9600);
    if (fd0 < 0) {
        fprintf(stderr, "Failed to open serial0: %s\n", strerror(errno));
        goto cleanup;
    }

    int fd1 = serialOpen("/dev/serial1", 9600);
    if (fd1 < 0) {
        fprintf(stderr, "Failed to open serial1: %s\n", strerror(errno));
        goto cleanup;
    }

    char code0[CODE_LEN + 1] = {0};
    char code1[CODE_LEN + 1] = {0};

    while (running) {
        int c0 = serialReadByte(fd0);
        int c1 = serialReadByte(fd1);

        if (c0 >= 0 && c0 <= '9' && c0 >= '0') {
            code0[strlen(code0)] = c0;
        } else {
            code0[0] = '\0';
        }

        if (c1 >= 0 && c1 <= '9' && c1 >= '0') {
            code1[strlen(code1)] = c1;
        } else {
            code1[0] = '\0';
        }

        if (strlen(code0) == CODE_LEN && strlen(code1) == CODE_LEN) {
            if (memcmp(code0, CODE, CODE_LEN) == 0 && memcmp(code1, CODE, CODE_LEN) == 0) {
                if (gpioWrite(gpio17, PI_HIGH) < 0) {
                    fprintf(stderr, "Failed to write GPIO17: %s\n", strerror(errno));
                    goto cleanup;
                }

                if (gpioWrite(gpio27, PI_HIGH) < 0) {
                    fprintf(stderr, "Failed to write GPIO27: %s\n", strerror(errno));
                    goto cleanup;
                }

                usleep(OPEN_TIME * 1000);

                if (gpioWrite(gpio17, PI_LOW) < 0) {
                    fprintf(stderr, "Failed to write GPIO17: %s\n", strerror(errno));
                    goto cleanup;
                }

                if (gpioWrite(gpio27, PI_LOW) < 0) {
                    fprintf(stderr, "Failed to write GPIO27: %s\n", strerror(errno));
                    goto cleanup;
                }
            }

            code0[0] = '\0';
            code1[0] = '\0';
        }
    }

cleanup:
    serialClose(fd0);
    serialClose(fd1);
    gpioTerminate();
    return EXIT_FAILURE;
}

#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <unistd.h>
#include <signal.h>
#include <syslog.h>
#include <gpiod.h>

#define GPIOCHIP_NAME "gpiochip0"
#define PIR_PIN 4
#define RELAY_PIN 17
#define POLL_INTERVAL_MS 50
#define FAILSAFE_THRESHOLD_S 10

static struct gpiod_chip *chip;
static struct gpiod_line *pir_line;
static struct gpiod_line *relay_line;
static int motion_detected = 0;
static int relay_state = 0;
static int failsafe_counter = 0;

static void log_error(const char *msg) {
    syslog(LOG_ERR, "%s", msg);
}

static void log_warning(const char *msg) {
    syslog(LOG_WARNING, "%s", msg);
}

static void log_info(const char *msg) {
    syslog(LOG_INFO, "%s", msg);
}

static void handle_sigint(int signum) {
    log_info("Received SIGINT, shutting down...");
    gpiod_line_set_value(relay_line, 0);
    gpiod_line_release(relay_line);
    gpiod_chip_close(chip);
    closelog();
    exit(EXIT_SUCCESS);
}

static void setup_signals() {
    struct sigaction action;
    memset(&action, 0, sizeof(struct sigaction));
    action.sa_handler = handle_sigint;
    sigaction(SIGINT, &action, NULL);
    sigaction(SIGTERM, &action, NULL);
}

static int setup_gpio() {
    chip = gpiod_chip_open_by_name(GPIOCHIP_NAME);
    if (!chip) {
        log_error("Failed to open GPIO chip");
        return -1;
    }

    pir_line = gpiod_chip_get_line(chip, PIR_PIN);
    if (!pir_line) {
        log_error("Failed to get PIR line");
        return -1;
    }

    relay_line = gpiod_chip_get_line(chip, RELAY_PIN);
    if (!relay_line) {
        log_error("Failed to get RELAY line");
        return -1;
    }

    if (gpiod_line_request_input(pir_line, "pir_input") < 0) {
        log_error("Failed to request PIR line as input");
        return -1;
    }

    if (gpiod_line_request_output(relay_line, "relay_output", 0) < 0) {
        log_error("Failed to request RELAY line as output");
        return -1;
    }

    return 0;
}

static void cleanup_gpio() {
    gpiod_line_release(relay_line);
    gpiod_chip_close(chip);
}

int main() {
    openlog("door_strike", LOG_PID, LOG_USER);
    setup_signals();

    if (setup_gpio() < 0) {
        log_error("Failed to setup GPIO");
        return EXIT_FAILURE;
    }

    log_info("Door strike system started");

    while (1) {
        int value = gpiod_line_get_value(pir_line);
        if (value < 0) {
            log_error("Failed to get PIR line value");
            break;
        }

        if (value == 1) {
            if (!motion_detected) {
                log_info("Motion detected");
                motion_detected = 1;
                failsafe_counter = 0;
            }

            if (relay_state == 0) {
                gpiod_line_set_value(relay_line, 1);
                relay_state = 1;
                log_info("Relay ON");
            }

            failsafe_counter = 0;
        } else {
            if (motion_detected) {
                log_info("Motion ended");
                motion_detected = 0;
            }

            if (relay_state == 1) {
                gpiod_line_set_value(relay_line, 0);
                relay_state = 0;
                log_info("Relay OFF");
            }

            failsafe_counter++;
            if (failsafe_counter >= FAILSAFE_THRESHOLD_S / POLL_INTERVAL_MS) {
                log_warning("PIR sensor remains HIGH for more than 10 seconds continuously");
                failsafe_counter = 0;
            }
        }

        usleep(POLL_INTERVAL_MS * 1000);
    }

    cleanup_gpio();
    closelog();
    return EXIT_FAILURE;
}

#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <signal.h>
#include <time.h>
#include <syslog.h>
#include <pigpio.h>

#define RELAY_COUNT 4
#define ACTIVATION_TIME 300 // 5 minutes
#define PAUSE_TIME 60 // 1 minute

volatile sig_atomic_t running = 1;

void signal_handler(int signum) {
    running = 0;
}

void log_syslog(int priority, const char *message) {
    openlog("irrigation_system", LOG_PID, LOG_USER);
    syslog(priority, "%s", message);
    closelog();
}

int main() {
    if (gpioInitialise() < 0) {
        log_syslog(LOG_ERR, "Failed to initialize pigpio");
        return EXIT_FAILURE;
    }

    int relay_pins[RELAY_COUNT] = {4, 17, 27, 22};
    for (int i = 0; i < RELAY_COUNT; i++) {
        if (gpioSetMode(relay_pins[i], PI_OUTPUT) < 0) {
            log_syslog(LOG_ERR, "Failed to set GPIO mode");
            gpioTerminate();
            return EXIT_FAILURE;
        }
        gpioWrite(relay_pins[i], PI_HIGH); // Set all relays to OFF
    }

    struct sigaction action;
    memset(&action, 0, sizeof(struct sigaction));
    action.sa_handler = signal_handler;
    sigaction(SIGINT, &action, NULL);
    sigaction(SIGTERM, &action, NULL);

    struct timespec ts = {0, 600000000}; // 60 seconds
    int current_relay = 0;
    int state = 0; // 0: pause, 1: activation, 2: deactivation
    int elapsed_time = 0;

    while (running) {
        switch (state) {
            case 0: // Pause
                if (elapsed_time >= PAUSE_TIME) {
                    state = 1;
                    elapsed_time = 0;
                    gpioWrite(relay_pins[current_relay], PI_LOW); // Activate relay
                    log_syslog(LOG_INFO, "Activated relay");
                }
                break;
            case 1: // Activation
                if (elapsed_time >= ACTIVATION_TIME) {
                    state = 2;
                    elapsed_time = 0;
                }
                break;
            case 2: // Deactivation
                gpioWrite(relay_pins[current_relay], PI_HIGH); // Deactivate relay
                log_syslog(LOG_INFO, "Deactivated relay");
                current_relay = (current_relay + 1) % RELAY_COUNT;
                state = 0;
                break;
        }
        nanosleep(&ts, NULL);
        elapsed_time += 60;
    }

    for (int i = 0; i < RELAY_COUNT; i++) {
        gpioWrite(relay_pins[i], PI_HIGH); // Deactivate all relays
    }

    gpioTerminate();
    return EXIT_SUCCESS;
}

