#include <stdio.h>
#include <stdlib.h>
#include <signal.h>
#include <stdbool.h>
#include <time.h>
#include <libgpiod.h>

#define NUM_RELAYS 4
#define RELAY_PINS {18, 23, 24, 25}
#define PRIME_INTERVALS {2, 3, 5, 7}

static struct gpiod_chip *chip;
static struct gpiod_line_bulk lines;
static bool running = true;

void cleanup() {
    gpiod_line_set_value_bulk(lines, NUM_RELAYS, 0);
    gpiod_chip_close(chip);
}

void handle_sigint(int signum) {
    running = false;
}

int main() {
    struct timespec start_time, current_time;
    clock_gettime(CLOCK_MONOTONIC, &start_time);
    int intervals[NUM_RELAYS] = PRIME_INTERVALS;
    int relay_pins[NUM_RELAYS] = RELAY_PINS;

    chip = gpiod_chip_open("/dev/gpiochip0");
    if (!chip) {
        fprintf(stderr, "Failed to open GPIO chip\n");
        return EXIT_FAILURE;
    }

    gpiod_line_request_config config = {
        .consumer = "smart_lighting",
        .request_type = GPIO_LINE_REQUEST_DIRECTION_OUTPUT,
        .default_value = 0
    };

    for (int i = 0; i < NUM_RELAYS; i++) {
        struct gpiod_line *line = gpiod_chip_get_line(chip, relay_pins[i]);
        if (!line) {
            fprintf(stderr, "Failed to get line %d\n", relay_pins[i]);
            cleanup();
            return EXIT_FAILURE;
        }

        if (gpiod_line_request(line, &config, 0)) {
            fprintf(stderr, "Failed to request line %d\n", relay_pins[i]);
            cleanup();
            return EXIT_FAILURE;
        }

        lines.lines[i] = line;
    }

    signal(SIGINT, handle_sigint);
    signal(SIGTERM, handle_sigint);

    while (running) {
        clock_gettime(CLOCK_MONOTONIC, &current_time);
        for (int i = 0; i < NUM_RELAYS; i++) {
            if ((current_time.tv_sec - start_time.tv_sec) % intervals[i] == 0) {
                gpiod_line_set_value_bulk(lines, 1 << i, 1);
            } else {
                gpiod_line_set_value_bulk(lines, 1 << i, 0);
            }
        }
    }

    cleanup();
    return EXIT_SUCCESS;
}

#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <signal.h>
#include <time.h>
#include <pigpio.h>

#define SOUND_SENSOR_PIN 17
#define RELAY_PIN 27
#define DEBOUNCE_TIME 300 // ms
#define LOG_FILE "alarm_log.txt"

volatile sig_atomic_t stop = 0;

void signal_handler(int signum) {
    stop = 1;
}

int main() {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialization failed\n");
        return EXIT_FAILURE;
    }

    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    if (gpioSetMode(SOUND_SENSOR_PIN, PI_INPUT) < 0) {
        fprintf(stderr, "Failed to set mode for sound sensor pin\n");
        goto cleanup;
    }

    if (gpioSetMode(RELAY_PIN, PI_OUTPUT) < 0) {
        fprintf(stderr, "Failed to set mode for relay pin\n");
        goto cleanup;
    }

    gpioWrite(RELAY_PIN, PI_OFF);

    time_t last_trigger_time = 0;
    int last_sound_state = 0;

    while (!stop) {
        int sound_state = gpioRead(SOUND_SENSOR_PIN);

        if (sound_state == PI_HIGH && sound_state != last_sound_state && time(NULL) - last_trigger_time > DEBOUNCE_TIME / 1000) {
            gpioWrite(RELAY_PIN, PI_ON);
            sleep(3);
            gpioWrite(RELAY_PIN, PI_OFF);

            FILE *log_file = fopen(LOG_FILE, "a");
            if (log_file == NULL) {
                fprintf(stderr, "Failed to open log file\n");
                goto cleanup;
            }

            time_t now = time(NULL);
            struct tm *time_info = localtime(&now);
            char timestamp[20];
            strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", time_info);
            fprintf(log_file, "%s\n", timestamp);

            fclose(log_file);

            last_trigger_time = time(NULL);
        }

        last_sound_state = sound_state;
        sleep(0.1);
    }

    cleanup:
    gpioTerminate();
    return EXIT_SUCCESS;
}

#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <string.h>
#include <fcntl.h>
#include <unistd.h>
#include <linux/i2c-dev.h>
#include <sys/ioctl.h>

#define MPU6050_ADDRESS 0x68
#define PWR_MGMT_1 0x6B
#define WHO_AM_I 0x75
#define GYRO_XOUT_H 0x43
#define GYRO_SENSITIVITY 131.0

typedef struct {
    int16_t x;
    int16_t y;
    int16_t z;
} gyro_data_t;

gyro_data_t buffer[100];
int buffer_index = 0;

void on_threshold_exceeded(gyro_data_t data) {
    printf("Threshold exceeded: %d, %d, %d\n", data.x, data.y, data.z);
}

int main() {
    int file;
    char filename[20];
    uint8_t buffer[14];
    gyro_data_t data;

    sprintf(filename, "/dev/i2c-1");
    file = open(filename, O_RDWR);
    if (file < 0) {
        perror("Failed to open the i2c bus");
        exit(1);
    }

    if (ioctl(file, I2C_SLAVE, MPU6050_ADDRESS) < 0) {
        perror("Failed to acquire bus access and/or talk to slave");
        exit(1);
    }

    // Wake up the MPU6050
    buffer[0] = PWR_MGMT_1;
    buffer[1] = 0;
    write(file, buffer, 2);

    // Verify the device
    buffer[0] = WHO_AM_I;
    read(file, buffer, 1);
    if (buffer[0] != 0x68) {
        printf("Error: Device not found\n");
        exit(1);
    }

    while (1) {
        // Read the gyroscope data
        buffer[0] = GYRO_XOUT_H;
        read(file, buffer, 14);

        data.x = (buffer[0] << 8) | buffer[1];
        data.y = (buffer[2] << 8) | buffer[3];
        data.z = (buffer[4] << 8) | buffer[5];

        // Log the data
        buffer[buffer_index] = data;
        buffer_index = (buffer_index + 1) % 100;

        // Check if the threshold has been exceeded
        if (sqrt(data.x * data.x + data.y * data.y + data.z * data.z) > 50.0) {
            on_threshold_exceeded(data);
        }

        // Sleep for a short amount of time to prevent overloading the I2C bus
        usleep(10000);
    }

    close(file);
    return 0;
}

#include <stdio.h>
#include <stdlib.h>
