#include <signal.h>
#include <pigpio.h>
#include <errno.h>

#define SERIAL_PORT "/dev/serial0"
#define BAUD_RATE 9600
#define READ_COMMAND {0xFF,0x01,0x86,0x00,0x00,0x00,0x00,0x00,0x79}
#define READ_SIZE 9
#define TIMEOUT 1000000
#define INTERVAL 5000
#define LOG_FILE "co2_log.json"
#define ERROR_LOG "co2_error.log"

volatile sig_atomic_t running = 1;

void signal_handler(int signum) {
    running = 0;
}

int main() {
    FILE *log_file, *error_log;
    struct timespec start_time, current_time;
    uint8_t read_command[READ_SIZE] = READ_COMMAND;
    uint8_t response[READ_SIZE];
    int serial_fd, i, checksum, ppm;
    char json[256];

    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    if (clock_gettime(CLOCK_REALTIME, &start_time) == -1) {
        perror("clock_gettime");
        return EXIT_FAILURE;
    }

    if ((serial_fd = serOpen(SERIAL_PORT, BAUD_RATE, 0)) < 0) {
        fprintf(stderr, "Failed to open serial port: %s\n", strerror(errno));
        return EXIT_FAILURE;
    }

    if ((log_file = fopen(LOG_FILE, "w")) == NULL) {
        fprintf(stderr, "Failed to open log file: %s\n", strerror(errno));
        return EXIT_FAILURE;
    }

    if ((error_log = fopen(ERROR_LOG, "w")) == NULL) {
        fprintf(stderr, "Failed to open error log file: %s\n", strerror(errno));
        return EXIT_FAILURE;
    }

    while (running) {
        if (serWrite(serial_fd, read_command, READ_SIZE) != READ_SIZE) {
            fprintf(error_log, "[%ld.%09ld] Failed to write to serial port: %s\n", current_time.tv_sec, current_time.tv_nsec, strerror(errno));
            continue;
        }

        memset(response, 0, READ_SIZE);
        for (i = 0; i < READ_SIZE; i++) {
            if (serDataAvailable(serial_fd) > 0) {
                response[i] = serReadByte(serial_fd);
            } else {
                fprintf(error_log, "[%ld.%09ld] Timeout reading from serial port\n", current_time.tv_sec, current_time.tv_nsec);
                break;
            }
        }

        if (i != READ_SIZE) {
            continue;
        }

        checksum = response[1];
        for (i = 2; i < 8; i++) {
            checksum += response[i];
        }

        if ((checksum & 0xFF) != response[8]) {
            fprintf(error_log, "[%ld.%09ld] Checksum mismatch: expected 0x%02X, got 0x%02X\n", current_time.tv_sec, current_time.tv_nsec, checksum & 0xFF, response[8]);
            continue;
        }

        ppm = (response[2] << 8) | response[3];

        if (clock_gettime(CLOCK_REALTIME, &current_time) == -1) {
            fprintf(error_log, "[%ld.%09ld] Failed to get current time: %s\n", current_time.tv_sec, current_time.tv_nsec, strerror(errno));
            continue;
        }

        sprintf(json, "{\"timestamp\":\"%ld.%09ld\",\"ppm\":%d,\"error\":false}\n", current_time.tv_sec, current_time.tv_nsec, ppm);
        fwrite(json, 1, strlen(json), log_file);
        fflush(log_file);
        printf("%s", json);

        if (clock_nanosleep(CLOCK_REALTIME, 0, (struct timespec[]){{0, INTERVAL * 1000000}}, NULL) == -1) {
            fprintf(error_log, "[%ld.%09ld] Failed to sleep: %s\n", current_time.tv_sec, current_time.tv_nsec, strerror(errno));
        }
    }

    fclose(log_file);
    fclose(error_log);
    serClose(serial_fd);
    gpioTerminate();

    return EXIT_SUCCESS;
}

#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <signal.h>
#include <pigpio.h>
#include <errno.h>

#define I2C_BUS 1
#define I2C_ADDRESS 0x1E
#define REG_CONFIG_A 0x00
#define REG_CONFIG_B 0x01
#define REG_MODE 0x02
#define REG_DATA 0x03
#define SAMPLE_INTERVAL 100
#define MAX_LOG_SIZE 100
#define TARGET_HEADING 90.0
#define DEVIATION_THRESHOLD 10.0

typedef struct {
    float x;
    float y;
    float z;
} HeadingData;

HeadingData log_buffer[MAX_LOG_SIZE];
int log_head = 0;
int log_tail = 0;
int log_size = 0;

void log_heading(HeadingData heading) {
    log_buffer[log_head] = heading;
    log_head = (log_head + 1) % MAX_LOG_SIZE;
    if (log_size < MAX_LOG_SIZE) {
        log_size++;
    } else {
        log_tail = (log_tail + 1) % MAX_LOG_SIZE;
    }
}

HeadingData read_heading() {
    uint8_t data[6];
    if (i2cReadDevice(I2C_BUS, I2C_ADDRESS, REG_DATA, data, 6) != 6) {
        printf("Failed to read heading data\n");
        exit(EXIT_FAILURE);
    }
    HeadingData heading;
    heading.x = (data[0] << 8) | data[1];
    heading.z = (data[2] << 8) | data[3];
    heading.y = (data[4] << 8) | data[5];
    return heading;
}

void configure_sensor() {
    uint8_t config_a = 0x70;
    uint8_t config_b = 0x20;
    uint8_t mode = 0x00;
    if (i2cWriteDevice(I2C_BUS, I2C_ADDRESS, REG_CONFIG_A, &config_a, 1) != 1 ||
        i2cWriteDevice(I2C_BUS, I2C_ADDRESS, REG_CONFIG_B, &config_b, 1) != 1 ||
        i2cWriteDevice(I2C_BUS, I2C_ADDRESS, REG_MODE, &mode, 1) != 1) {
        printf("Failed to configure sensor\n");
        exit(EXIT_FAILURE);
    }
}

void cleanup() {
    gpioTerminate();
    i2cClose(I2C_BUS);
}

void signal_handler(int signum) {
    cleanup();
    exit(signum + 128);
}

int main() {
    if (gpioInitialise() < 0) {
        printf("Failed to initialize pigpio\n");
        return EXIT_FAILURE;
    }
    if (i2cOpen(I2C_BUS, I2C_ADDRESS, 0) < 0) {
        printf("Failed to open I2C bus\n");
        return EXIT_FAILURE;
    }
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);
    configure_sensor();
    while (1) {
        HeadingData heading = read_heading();
        heading.x -= 100;
        heading.y += 50;
        log_heading(heading);
        if (fabs(heading.x - TARGET_HEADING) > DEVIATION_THRESHOLD) {
            gpioWrite(17, 1);
        } else {
            gpioWrite(17, 0);
        }
        sleep(SAMPLE_INTERVAL);
    }
    cleanup();
    return EXIT_SUCCESS;
}

#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <stdbool.h>
#include <string.h>
#include <unistd.h>
#include <fcntl.h>
#include <sys/ioctl.h>
#include <linux/i2c-dev.h>
#include <gpiod.h>

#define BH1750_ADDRESS 0x23
#define BH1750_MODE_CONTINUOUS_HIGH_RES 0x10
#define RED_RELAY 17
#define GREEN_RELAY 27
#define BLUE_RELAY 22

int main() {
    struct gpiod_chip *chip;
    struct gpiod_line_bulk lines;
    int file;
    uint16_t lux;
    uint8_t buffer[2];

    chip = gpiod_chip_open("/dev/gpiochip0");
    if (!chip) {
        fprintf(stderr, "Failed to open GPIO chip\n");
        return EXIT_FAILURE;
    }

    gpiod_chip_get_lines(chip, RED_RELAY, GREEN_RELAY, BLUE_RELAY, NULL, &lines);
    if (gpiod_line_request_output_bulk(lines, "smart_lighting", 0)) {
        fprintf(stderr, "Failed to request GPIO lines\n");
        gpiod_chip_close(chip);
        return EXIT_FAILURE;
    }

    file = open("/dev/i2c-1", O_RDWR);
    if (file < 0) {
        fprintf(stderr, "Failed to open I2C bus\n");
        gpiod_line_release_bulk(lines);
        gpiod_chip_close(chip);
        return EXIT_FAILURE;
    }

    if (ioctl(file, I2C_SLAVE, BH1750_ADDRESS) < 0) {
        fprintf(stderr, "Failed to set I2C address\n");
        close(file);
        gpiod_line_release_bulk(lines);
        gpiod_chip_close(chip);
        return EXIT_FAILURE;
    }

    buffer[0] = BH1750_MODE_CONTINUOUS_HIGH_RES;
    if (write(file, buffer, 1) != 1) {
        fprintf(stderr, "Failed to write to BH1750\n");
        close(file);
        gpiod_line_release_bulk(lines);
        gpiod_chip_close(chip);
        return EXIT_FAILURE;
    }

    sleep(1);

    if (read(file, buffer, 2) != 2) {
        fprintf(stderr, "Failed to read from BH1750\n");
        close(file);
        gpiod_line_release_bulk(lines);
        gpiod_chip_close(chip);
        return EXIT_FAILURE;
    }

    lux = (buffer[0] << 8) | buffer[1];
    lux /= 1.2;

    if (lux < 50) {
        gpiod_line_set_value_bulk(lines, 1, 0, 0, 0);
    } else if (lux < 150) {
        gpiod_line_set_value_bulk(lines, 0, 1, 0, 0);
    } else if (lux < 300) {
        gpiod_line_set_value_bulk(lines, 0, 0, 1, 0);
    } else {
        gpiod_line_set_value_bulk(lines, 0, 0, 0, 1);
    }

    close(file);
    gpiod_line_release_bulk(lines);
    gpiod_chip_close(chip);

    return EXIT_SUCCESS;
}

#include <stdio.h>
#include <stdlib.h>
#include <pigpio.h>

#define MOTOR_A_IN1 17
#define MOTOR_A_IN2 18
#define MOTOR_B_IN3 22
#define MOTOR_B_IN4 23
#define PWM_FREQ 1000
#define PWM_RANGE 255

void controlMotors(int distanceA, int distanceB) {
    int dutyCycleA = (255 - ((distanceA - 10) * PWM_RANGE / 90));
    int dutyCycleB = (255 - ((distanceB - 10) * PWM_RANGE / 90));

    // Clamp the duty cycle to [0, 255]
    if (dutyCycleA < 0) dutyCycleA = 0;
    if (dutyCycleA > 255) dutyCycleA = 255;
    if (dutyCycleB < 0) dutyCycleB = 0;
    if (dutyCycleB > 255) dutyCycleB = 255;

    // Set the direction of the motors
    if (distanceA < 50) {
        gpioPWM(MOTOR_A_IN1, 0);
        gpioPWM(MOTOR_A_IN2, dutyCycleA);
    } else {
        gpioPWM(MOTOR_A_IN1, dutyCycleA);
        gpioPWM(MOTOR_A_IN2, 0);
    }

    if (distanceB < 50) {
        gpioPWM(MOTOR_B_IN3, 0);
        gpioPWM(MOTOR_B_IN4, dutyCycleB);
    } else {
        gpioPWM(MOTOR_B_IN3, dutyCycleB);
        gpioPWM(MOTOR_B_IN4, 0);
    }
}

int main(int argc, char *argv[]) {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return EXIT_FAILURE;
    }

    atexit(gpioTerminate);

    signal(SIGINT, gpioTerminate);
    signal(SIGTERM, gpioTerminate);

    int distanceA = atoi(argv[1]);
    int distanceB = atoi(argv[2]);

    while (1) {
        controlMotors(distanceA, distanceB);
        gpioDelay(100000); // Wait for 100 ms
    }

    return EXIT_SUCCESS;
}

#include <stdio.h>
#include <stdlib.h>
#include <signal.h>
#include <pigpio.h>

#define IN1 17
#define IN2 18
#define IN3 27
#define IN4 22
#define BUTTON_LOCK 24
#define BUTTON_UNLOCK 23
#define STEPS 512
#define DELAY 2000

volatile sig_atomic_t stop = 0;

void stop_handler(int signum) {
    stop = 1;
}

void step(int step) {
    gpioPWM(IN1, step & 0x01 ? 512 : 0);
    gpioPWM(IN2, step & 0x02 ? 512 : 0);
    gpioPWM(IN3, step & 0x04 ? 512 : 0);
    gpioPWM(IN4, step & 0x08 ? 512 : 0);
    usleep(DELAY);
}

int main() {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return EXIT_FAILURE;
    }

    signal(SIGINT, stop_handler);
    signal(SIGTERM, stop_handler);

    gpioSetMode(IN1, PI_OUTPUT);
    gpioSetMode(IN2, PI_OUTPUT);
    gpioSetMode(IN3, PI_OUTPUT);
    gpioSetMode(IN4, PI_OUTPUT);
    gpioSetMode(BUTTON_LOCK, PI_INPUT);
    gpioSetMode(BUTTON_UNLOCK, PI_INPUT);

    gpioSetPullUpDown(BUTTON_LOCK, PI_PUD_UP);
    gpioSetPullUpDown(BUTTON_UNLOCK, PI_PUD_UP);

    gpioSetAlertFunc(BUTTON_LOCK, NULL);
    gpioSetAlertFunc(BUTTON_UNLOCK, NULL);

    int lock_button_state = 1;
    int unlock_button_state = 1;

    while (!stop) {
        int new_lock_button_state = gpioRead(BUTTON_LOCK);
        int new_unlock_button_state = gpioRead(BUTTON_UNLOCK);

        if (new_lock_button_state == 0 && lock_button_state == 1) {
            printf("Locking...\n");
            for (int i = 0; i < STEPS; i++) {
                step(0x01);
                step(0x03);
                step(0x02);
                step(0x06);
                step(0x04);
                step(0x0C);
                step(0x08);
                step(0x09);
            }
            printf("Locked.\n");
        }
        lock_button_state = new_lock_button_state;

        if (new_unlock_button_state == 0 && unlock_button_state == 1) {
            printf("Unlocking...\n");
            for (int i = 0; i < STEPS; i++) {
                step(0x09);
                step(0x08);
                step(0x0C);
                step(0x04);
                step(0x06);
                step(0x02);
                step(0x03);
                step(0x01);
            }
            printf("Unlocked.\n");
        }
        unlock_button_state = new_unlock_button_state;
    }

    gpioPWM(IN1, 0);
    gpioPWM(IN2, 0);
    gpioPWM(IN3, 0);
    gpioPWM(IN4, 0);

    gpioTerminate();
    printf("Exiting...\n");
    return EXIT_SUCCESS;
}

#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <fcntl.h>
#include <unistd.h>
#include <sys/ioctl.h>
#include <linux/i2c-dev.h>
#include <sys/mman.h>
#include <sys/stat.h>
#include <sys/types.h>
#include <sys/time.h>
#include <sys/select.h>
#include <sys/signalfd.h>
#include <sys/epoll.h>
#include <sys/wait.h>
#include <signal.h>
#include <string.h>
#include <errno.h>
#include <dirent.h>
#include <time.h>

#define I2C_BUS "/dev/i2c-1"
#define MPU6050_ADDRESS 0x68
#define SERVO_PIN 18
#define LOG_FILE "solar_tracker.log"

int main() {
    int i2c_fd, pwm_fd, log_fd;
    struct i2c_rdwr_ioctl_data packets;
    struct i2c_msg messages[2];
    uint8_t buffer[14];
    struct itimerspec timer;
    struct sigaction sa;
    struct epoll_event event;
    int epoll_fd;
    struct signalfd_siginfo fdsi;
    ssize_t s;

    // Open I2C bus
    if ((i2c_fd = open(I2C_BUS, O_RDWR)) < 0) {
        perror("Failed to open I2C bus");
        return EXIT_FAILURE;
    }

    // Set I2C slave address
    if (ioctl(i2c_fd, I2C_SLAVE, MPU6050_ADDRESS) < 0) {
        perror("Failed to set I2C slave address");
        return EXIT_FAILURE;
    }

    // Read from MPU6050
    messages[0].addr = MPU6050_ADDRESS;
    messages[0].flags = 0;
    messages[0].len = 1;
    messages[0].buf = &buffer[0];
    messages[1].addr = MPU6050_ADDRESS;
    messages[1].flags = I2C_M_RD;
    messages[1].len = 14;
    messages[1].buf = &buffer[1];
    packets.msgs = messages;
    packets.nmsgs = 2;
    if (ioctl(i2c_fd, I2C_RDWR, &packets) < 0) {
        perror("Failed to read from MPU6050");
        return EXIT_FAILURE;
    }

    // Open PWM chip
    if ((pwm_fd = open("/sys/class/pwm/pwmchip2/pwm0", O_WRONLY)) < 0) {
        perror("Failed to open PWM chip");
        return EXIT_FAILURE;
    }

    // Set up signal handler
    sa.sa_handler = &signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = SA_RESTART;
    if (sigaction(SIGINT, &sa, NULL) < 0) {
        perror("Failed to set up signal handler");
        return EXIT_FAILURE;
    }

    // Set up timer
    timer.it_value.tv_sec = 1;
    timer.it_value.tv_nsec = 0;
    timer.it_interval.tv_sec = 1;
    timer.it_interval.tv_nsec = 0;
    if (timerfd_create(CLOCK_REALTIME, 0) < 0) {
        perror("Failed to create timer");
        return EXIT_FAILURE;
    }

    // Set up epoll
    if ((epoll_fd = epoll_create1(0)) < 0) {
        perror("Failed to create epoll");
        return EXIT_FAILURE;
    }

    // Set up log file
    if ((log_fd = open(LOG_FILE, O_WRONLY | O_APPEND | O_CREAT, 0644)) < 0) {
        perror("Failed to open log file");
        return EXIT_FAILURE;
    }

    // Main loop
    while (1) {
        // Wait for signal
        s = read(epoll_fd, &fdsi, sizeof(fdsi));
        if (s < 0) {
            perror("Failed to read from epoll");
            return EXIT_FAILURE;
        }

        // Process signal
        if (fdsi.ssi_signo == SIGINT) {
            break;
        }

        // Read from MPU6050
        if (ioctl(i2c_fd, I2C_RDWR, &packets) < 0) {
            perror("Failed to read from MPU6050");
            return EXIT_FAILURE;
        }

        // Write to PWM chip
        if (write(pwm_fd, &buffer[1], 14) < 0) {
            perror("Failed to write to PWM chip");
            return EXIT_FAILURE;
        }

        // Log data
        char log_data[256];
        sprintf(log_data, "%ld,%ld,%ld\n", buffer[1], buffer[2], buffer[3]);
        if (write(log_fd, log_data, strlen(log_data)) < 0) {
            perror("Failed to write to log file");
            return EXIT_FAILURE;
        }
    }

    // Clean up
    close(i2c_fd);
    close(pwm_fd);
    close(log_fd);
    return EXIT_SUCCESS;
}

