int pwm_values[GPIO_COUNT] = {0, 0, 0, 0};
int pwm_targets[GPIO_COUNT] = {0, 0, 0, 0};
int pwm_deltas[GPIO_COUNT] = {0, 0, 0, 0};
int pwm_transitions[GPIO_COUNT] = {0, 0, 0, 0};

void handle_sigint(int signum) {
    for (int i = 0; i < GPIO_COUNT; i++) {
        gpioSetPWMdutycycle(gpios[i], 0);
        gpioTerminate();
    }
    exit(0);
}

void read_schedule() {
    FILE *file = fopen("lighting_schedule.txt", "r");
    if (file == NULL) {
        printf("Error opening schedule file.\n");
        return;
    }

    char line[256];
    while (fgets(line, sizeof(line), file)) {
        char *token = strtok(line, ",");
        struct tm time;
        strptime(token, "%H:%M:%S", &time);
        token = strtok(NULL, ",");
        int gpio = atoi(token);
        token = strtok(NULL, ",");
        int target = atoi(token);
        for (int i = 0; i < GPIO_COUNT; i++) {
            if (gpios[i] == gpio) {
                pwm_targets[i] = target;
                pwm_deltas[i] = (target - pwm_values[i]) / 1800;
                pwm_transitions[i] = 1;
            }
        }
    }

    fclose(file);
}

void update_pwm() {
    for (int i = 0; i < GPIO_COUNT; i++) {
        if (pwm_transitions[i]) {
            pwm_values[i] += pwm_deltas[i];
            gpioSetPWMdutycycle(gpios[i], pwm_values[i]);
            if (pwm_values[i] == pwm_targets[i]) {
                pwm_transitions[i] = 0;
            }
        }
    }
}

