        struct tm time;
        strptime(token, "%H:%M:%S", &time);
        token = strtok(NULL, ",");
        int gpio = atoi(token);
        token = strtok(NULL, ",");
        int target = atoi(token);
        for (int i = 0; i < GPIO_COUNT; i++) {
            if (gpios[i] == gpio) {
                pwm_targets[i] = target;
                pwm_deltas[i] = (target - pwm_values[i]) / 1800;
                pwm_transitions[i] = 1;
            }
        }
    }

    fclose(file);
}

void update_pwm() {
    for (int i = 0; i < GPIO_COUNT; i++) {
        if (pwm_transitions[i]) {
            pwm_values[i] += pwm_deltas[i];
            gpioSetPWMdutycycle(gpios[i], pwm_values[i]);
            if (pwm_values[i] == pwm_targets[i]) {
                pwm_transitions[i] = 0;
            }
        }
    }
}

int main() {
    signal(SIGINT, handle_sigint);
    signal(SIGTERM, handle_sigint);

    if (gpioInitialise() < 0) {
        printf("Failed to initialize GPIO.\n");
        return 1;
    }

    for (int i = 0; i < GPIO_COUNT; i++) {
        gpioSetMode(gpios[i], PI_OUTPUT);
        gpioSetPWMfrequency(gpios[i], 100);
        gpioSetPWMrange(gpios[i], 100);
    }

    while (1) {
        read_schedule();
        update_pwm();
        sleep(1);
    }

    return 0;
}
