#include <unistd.h>
#include <signal.h>
#include <gpiod.h>

#define WINDOW_SIZE 5
#define EARTHQUAKE_THRESHOLD 3
#define DEFAULT_POLL_TIMEOUT 1000

volatile sig_atomic_t stop = 0;

void sig_handler(int signum) {
    stop = 1;
}

int main(int argc, char *argv[]) {
    struct gpiod_chip *chip;
    struct gpiod_line *line;
    struct timespec ts;
    struct timespec window[WINDOW_SIZE];
    int window_head = 0;
    int window_count = 0;
    int poll_timeout = DEFAULT_POLL_TIMEOUT;
    FILE *log_file = NULL;
    int log_fd = -1;
    int ret;

    if (argc > 1) {
        poll_timeout = atoi(argv[1]);
    }

    signal(SIGINT, sig_handler);
    signal(SIGTERM, sig_handler);

    chip = gpiod_chip_open("/dev/gpiochip0");
    if (!chip) {
        fprintf(stderr, "Failed to open GPIO chip\n");
        return EXIT_FAILURE;
    }

    line = gpiod_chip_get_line(chip, 17);
    if (!line) {
        fprintf(stderr, "Failed to get GPIO line\n");
        gpiod_chip_close(chip);
        return EXIT_FAILURE;
    }

    ret = gpiod_line_request_input(line, "vibration_sensor");
    if (ret) {
        fprintf(stderr, "Failed to request GPIO line as input\n");
        gpiod_chip_close(chip);
        gpiod_line_release(line);
        return EXIT_FAILURE;
    }

    log_file = fopen("vibration_events.log", "a");
    if (!log_file) {
        fprintf(stderr, "Failed to open log file\n");
        gpiod_chip_close(chip);
        gpiod_line_release(line);
        return EXIT_FAILURE;
    }

    log_fd = fileno(log_file);

    while (!stop) {
        struct gpiod_line_event event;
        ret = gpiod_line_event_wait(line, poll_timeout);
        if (ret < 0) {
            fprintf(stderr, "Failed to wait for GPIO line event\n");
            break;
        }

        ret = gpiod_line_event_read(line, &event);
        if (ret) {
            fprintf(stderr, "Failed to read GPIO line event\n");
            break;
        }

        clock_gettime(CLOCK_REALTIME, &ts);
        fprintf(log_file, "%ld.%09ld %d\n", ts.tv_sec, ts.tv_nsec, event.level);
        fflush(log_file);
        fsync(log_fd);

        if (event.level == 1) {
            window[window_head] = ts;
            window_head = (window_head + 1) % WINDOW_SIZE;
            if (window_count < WINDOW_SIZE) {
                window_count++;
            }

            if (window_count == WINDOW_SIZE) {
                int i, high_count = 0;
                for (i = 0; i < WINDOW_SIZE; i++) {
                    if (window[(window_head + i) % WINDOW_SIZE].tv_sec == 0) {
                        break;
                    }
                    high_count++;
                }
                if (high_count >= EARTHQUAKE_THRESHOLD) {
                    printf("EARTHQUAKE ALERT at %ld.%09ld\n", ts.tv_sec, ts.tv_nsec);
                }
            }
        }
    }

    fclose(log_file);
    gpiod_line_release(line);
    gpiod_chip_close(chip);

    return EXIT_SUCCESS;
}

