#define LSM303DLHC_ADDRESS 0x1E
#define MR_REG_M 0x02
#define CRA_REG_M 0x00
#define OUT_X_H_M 0x03
#define X_OFFSET 10
#define Y_OFFSET -5
#define Z_OFFSET 20

volatile sig_atomic_t stop = false;

void signal_handler(int signum) {
    stop = true;
}

int main() {
    struct sigaction action;
    memset(&action, 0, sizeof(struct sigaction));
    action.sa_handler = signal_handler;
    sigaction(SIGINT, &action, NULL);
    sigaction(SIGTERM, &action, NULL);

    int i2c_fd = open("/dev/i2c-1", O_RDWR);
    if (i2c_fd < 0) {
        perror("Failed to open I2C device");
        return EXIT_FAILURE;
    }

    if (ioctl(i2c_fd, I2C_SLAVE, LSM303DLHC_ADDRESS) < 0) {
        perror("Failed to set I2C slave address");
        close(i2c_fd);
        return EXIT_FAILURE;
    }

    if (write(i2c_fd, &MR_REG_M, 1) != 1 || write(i2c_fd, &CRA_REG_M, 1) != 1) {
        perror("Failed to write to magnetometer");
        close(i2c_fd);
        return EXIT_FAILURE;
    }

    FILE *csv_file = fopen("mag_log.csv", "a");
    if (!csv_file) {
        perror("Failed to open CSV file");
        close(i2c_fd);
        return EXIT_FAILURE;
    }

    bool first_sample = true;
    while (!stop) {
        uint8_t buffer[6];
        if (read(i2c_fd, buffer, 6) != 6) {
            perror("Failed to read from magnetometer");
            continue;
        }

        int16_t x = (buffer[0] << 8) | buffer[1];
        int16_t z = (buffer[2] << 8) | buffer[3];
        int16_t y = (buffer[4] << 8) | buffer[5];

        float calibrated_x = x + X_OFFSET;
        float calibrated_y = y + Y_OFFSET;
        float calibrated_z = z + Z_OFFSET;

        float heading = atan2f(calibrated_y, calibrated_x) * (180 / M_PI);
        if (heading < 0) {
            heading += 360;
        }

        const char *direction;
        if (heading >= 337.5 || heading < 22.5) {
            direction = "N";
        } else if (heading >= 22.5 && heading < 67.5) {
            direction = "NE";
        } else if (heading >= 67.5 && heading < 112.5) {
            direction = "E";
        } else if (heading >= 112.5 && heading < 157.5) {
            direction = "SE";
        } else if (heading >= 157.5 && heading < 202.5) {
            direction = "S";
        } else if (heading >= 202.5 && heading < 247.5) {
            direction = "SW";
        } else if (heading >= 247.5 && heading < 292.5) {
            direction = "W";
        } else {
            direction = "NW";
        }

        if (first_sample) {
            fprintf(csv_file, "Timestamp,Calibrated X,Calibrated Y,Calibrated Z,Heading\n");
            first_sample = false;
        }

        fprintf(csv_file, "%ld,%f,%f,%f,%s (%.2f)\n", time(NULL), calibrated_x, calibrated_y, calibrated_z, direction, heading);

        printf("%s (%.2f)\n", direction, heading);
        fflush(stdout);
        sleep(1);
    }

    fclose(csv_file);
    close(i2c_fd);
    return EXIT_SUCCESS;
}

#include <stdio.h>
