#define RELAY_PIN 17
#define TOUCH_PIN 4
#define DEBOUNCE_TIME 200 // ms

volatile int touch_flag = 0;
volatile int last_touch_time = 0;

void touch_callback(int gpio, int level, uint32_t tick) {
    if (level == 1 && tick - last_touch_time > DEBOUNCE_TIME) {
        touch_flag = 1;
        last_touch_time = tick;
    }
}

void write_log(int relay_state) {
    FILE *file = fopen("relay_log.json", "a");
    if (file == NULL) {
        printf("Failed to open log file\n");
        return;
    }

    time_t now = time(NULL);
    struct tm *t = localtime(&now);
    char timestamp[20];
    strftime(timestamp, sizeof(timestamp), "%FT%T", t);

    fprintf(file, "{\"timestamp\":\"%s\",\"relay_state\":\"%s\"}\n", timestamp, relay_state ? "ON" : "OFF");
    fclose(file);
}

int main() {
    if (gpioInitialise() < 0) {
        printf("Failed to initialize pigpio\n");
        return 1;
    }

    if (gpioSetMode(RELAY_PIN, PI_OUTPUT) < 0) {
        printf("Failed to set relay pin mode\n");
        gpioTerminate();
        return 1;
    }

    if (gpioSetMode(TOUCH_PIN, PI_INPUT) < 0) {
        printf("Failed to set touch pin mode\n");
        gpioTerminate();
        return 1;
    }

    if (gpioSetPullUpDown(TOUCH_PIN, PI_PUD_DOWN) < 0) {
        printf("Failed to set pull-up/down for touch pin\n");
        gpioTerminate();
        return 1;
    }

    if (gpioSetISRFunc(TOUCH_PIN, EITHER_EDGE, 0, touch_callback) < 0) {
        printf("Failed to set ISR for touch pin\n");
        gpioTerminate();
        return 1;
    }

    signal(SIGINT, (void (*)(int)) gpioTerminate);

    while (1) {
        if (touch_flag) {
            touch_flag = 0;
            int relay_state = gpioRead(RELAY_PIN);
            gpioWrite(RELAY_PIN, !relay_state);
            write_log(!relay_state);
        }
    }

    gpioTerminate();
    return 0;
