                }
                sleep(1);
            }

            // Sweep the nozzle
            for (int angle = 0; angle <= 180; angle += 45) {
                for (int i = 0; i < 3; ++i) {
                    if (gpioServo(18, angle * 10) < 0) {
                        printf("Failed to set nozzle angle to %d\n", angle);
                        break;
                    }
                    sleep(2);
                }
                sleep(5);
            }

            // Close the valve
            for (int i = 0; i < 3; ++i) {
                if (gpioServo(17, 500) < 0) {
                    printf("Failed to close the valve\n");
                    break;
                }
                sleep(1);
            }
        }

        currentMoistureValueIndex = (currentMoistureValueIndex + 1) % moistureValueCount;
        sleep(5);
    }

    gpioServo(17, 0);
    gpioServo(18, 0);
    gpioTerminate();

    return EXIT_SUCCESS;
}

#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <string.h>
#include <fcntl.h>
#include <unistd.h>
#include <sys/ioctl.h>
#include <linux/i2c-dev.h>
#include <time.h>

#define MPU6050_ADDRESS 0x68
#define PWR_MGMT_1 0x6B
#define GYRO_XOUT_H 0x43
#define GYRO_SENSITIVITY 131.0

int main() {
    int file;
    char *filename = "/dev/i2c-1";
    uint8_t buffer[6];
    int16_t raw_values[3];
    double angular_velocities[3];
    struct timespec timestamp;

    if ((file = open(filename, O_RDWR)) < 0) {
        perror("Failed to open the i2c bus");
        exit(1);
    }

    if (ioctl(file, I2C_SLAVE, MPU6050_ADDRESS) < 0) {
        perror("Failed to acquire bus access and/or talk to slave");
        exit(1);
    }

    // Wake the sensor
    if (write(file, &PWR_MGMT_1, 1) != 1) {
        perror("Failed to write to i2c bus");
        exit(1);
    }

    while (1) {
        // Read the gyroscope data
        if (write(file, &GYRO_XOUT_H, 1) != 1) {
            perror("Failed to write to i2c bus");
            exit(1);
        }

        if (read(file, buffer, 6) != 6) {
            perror("Failed to read from i2c bus");
            exit(1);
        }

        // Convert the raw 16-bit big-endian values to degrees/second
        for (int i = 0; i < 3; i++) {
            raw_values[i] = (buffer[i * 2] << 8) | buffer[i * 2 + 1];
            angular_velocities[i] = raw_values[i] / GYRO_SENSITIVITY;
        }

        // Get the current timestamp
        clock_gettime(CLOCK_REALTIME, &timestamp);

        // Log the timestamped reading
        FILE *log_file = fopen("gyro_log.txt", "a");
        if (log_file == NULL) {
            perror("Failed to open log file");
            exit(1);
        }

        fprintf(log_file, "%ld.%09ld, %f, %f, %f\n", timestamp.tv_sec, timestamp.tv_nsec, angular_velocities[0], angular_velocities[1], angular_velocities[2]);
        fclose(log_file);
    }

    close(file);
    return 0;
}

#include <stdio.h>
#include <signal.h>
#include <pigpio.h>

#define LOCK 24
#define UNLOCK 23
#define GPIO4 4
#define GPIO17 17
#define GPIO27 27
#define GPIO22 22
#define FULL_STEP 512

volatile sig_atomic_t stop;

void end_program(int signum) {
    gpioWrite(GPIO4, 0);
    gpioWrite(GPIO17, 0);
    gpioWrite(GPIO27, 0);
    gpioWrite(GPIO22, 0);
    gpioTerminate();
    printf("Program terminated by user\n");
    exit(signum);
}

void rotate(int steps, int delay) {
    for (int i = 0; i < steps; i++) {
        gpioWrite(GPIO4, 1);
        gpioWrite(GPIO17, 0);
        gpioWrite(GPIO27, 0);
        gpioWrite(GPIO22, 0);
        gpioDelay(delay);
        gpioWrite(GPIO4, 0);
        gpioWrite(GPIO17, 1);
        gpioWrite(GPIO27, 0);
        gpioWrite(GPIO22, 0);
        gpioDelay(delay);
        gpioWrite(GPIO4, 0);
        gpioWrite(GPIO17, 0);
        gpioWrite(GPIO27, 1);
        gpioWrite(GPIO22, 0);
        gpioDelay(delay);
        gpioWrite(GPIO4, 0);
        gpioWrite(GPIO17, 0);
        gpioWrite(GPIO27, 0);
        gpioWrite(GPIO22, 1);
        gpioDelay(delay);
    }
}

int main() {
    if (gpioInitialise() < 0) {
        printf("Failed to initialize pigpio\n");
        return 1;
    }

    signal(SIGINT, end_program);

    gpioSetMode(LOCK, PI_INPUT);
    gpioSetMode(UNLOCK, PI_INPUT);
    gpioSetPullUpDown(LOCK, PI_PUD_UP);
    gpioSetPullUpDown(UNLOCK, PI_PUD_UP);

    while (!stop) {
        if (gpioRead(LOCK) == 0) {
            printf("Locking door...\n");
            gpioDelay(500000); // Debounce delay
            rotate(FULL_STEP, 3000);
        } else if (gpioRead(UNLOCK) == 0) {
            printf("Unlocking door...\n");
            gpioDelay(500000); // Debounce delay
            rotate(-FULL_STEP, 3000);
        }
    }

    return 0;
}

#include <stdio.h>
#include <stdlib.h>
#include <signal.h>
#include <unistd.h>
#include <libgpiod.h>

#define TRIG_PIN 17
#define ECHO_PIN 18
#define SPEED_OF_SOUND 0.01715 // cm/us
#define MIN_GUARD_TIME 60000 // us
#define TIMEOUT 50000 // us

FILE *log_file;
uint64_t last_measurement_time = 0;

void cleanup(int signum) {
    gpiod_ctxless_close();
    fclose(log_file);
    exit(signum);
}

int main() {
    struct gpiod_chip *chip;
    struct gpiod_line_request request;
    struct gpiod_line *trig_line, *echo_line;
    uint64_t start_time, end_time, duration_us, distance_cm;
    int ret;

    signal(SIGINT, cleanup);
    signal(SIGTERM, cleanup);

    chip = gpiod_chip_open("/dev/gpiochip0");
    if (!chip) {
        fprintf(stderr, "Failed to open GPIO chip\n");
        return EXIT_FAILURE;
    }

    trig_line = gpiod_chip_get_line(chip, TRIG_PIN);
    if (!trig_line) {
        fprintf(stderr, "Failed to get trigger line\n");
        gpiod_chip_close(chip);
        return EXIT_FAILURE;
    }

    echo_line = gpiod_chip_get_line(chip, ECHO_PIN);
    if (!echo_line) {
        fprintf(stderr, "Failed to get echo line\n");
        gpiod_chip_close(chip);
        return EXIT_FAILURE;
    }

    request.consumer = "HC-SR04";
    request.request_type = GPIOD_LINE_REQUEST_OUTPUT;
    ret = gpiod_line_request_set_direction(&request, GPIOD_LINE_DIRECTION_OUT);
    if (ret) {
        fprintf(stderr, "Failed to set trigger line direction\n");
        gpiod_chip_close(chip);
        return EXIT_FAILURE;
    }

    ret = gpiod_line_request(trig_line, &request);
    if (ret) {
        fprintf(stderr, "Failed to request trigger line\n");
        gpiod_chip_close(chip);
        return EXIT_FAILURE;
    }

    request.request_type = GPIOD_LINE_REQUEST_INPUT;
    ret = gpiod_line_request_set_direction(&request, GPIOD_LINE_DIRECTION_IN);
    if (ret) {
        fprintf(stderr, "Failed to set echo line direction\n");
        gpiod_chip_close(chip);
        return EXIT_FAILURE;
    }

    ret = gpiod_line_request(echo_line, &request);
    if (ret) {
        fprintf(stderr, "Failed to request echo line\n");
        gpiod_chip_close(chip);
        return EXIT_FAILURE;
    }

    log_file = fopen("distance_log.txt", "a");
    if (!log_file) {
        fprintf(stderr, "Failed to open log file\n");
        gpiod_chip_close(chip);
        return EXIT_FAILURE;
    }

    while (1) {
        if (gettimeofday(&start_time, NULL) < 0) {
            fprintf(stderr, "Failed to get start time\n");
            fprintf(log_file, "-1\n");
            continue;
        }

        if (start_time.tv_usec - last_measurement_time.tv_usec < MIN_GUARD_TIME) {
            usleep(MIN_GUARD_TIME - (start_time.tv_usec - last_measurement_time.tv_usec));
        }

        gpiod_line_set_value(trig_line, 1);
        usleep(10);
        gpiod_line_set_value(trig_line, 0);

        while (1) {
            ret = gpiod_line_get_value(echo_line);
            if (ret < 0) {
                fprintf(stderr, "Failed to get echo line value\n");
                fprintf(log_file, "-1\n");
                break;
            }

            if (ret == 1) {
                start_time = start_time.tv_usec;
                break;
            }
        }

        if (ret < 0) {
            continue;
        }

        end_time = 0;
        while (1) {
            ret = gpiod_line_get_value(echo_line);
            if (ret < 0) {
                fprintf(stderr, "Failed to get echo line value\n");
                fprintf(log_file, "-1\n");
                break;
            }

            if (ret == 0) {
                end_time = end_time.tv_usec;
                break;
            }

            if (end_time == 0) {
                end_time = start_time.tv_usec;
            } else {
                end_time = end_time + 1000000;
            }
        }

        if (ret < 0) {
            continue;
        }

        duration_us = end_time - start_time;
        distance_cm = duration_us * SPEED_OF_SOUND;

        if (distance_cm < 0) {
            distance_cm = 0;
        }

        fprintf(log_file, "%llu\n", distance_cm);
        fflush(log_file);

        last_measurement_time = start_time;
    }

    gpiod_chip_close(chip);
    fclose(log_file);
    return EXIT_SUCCESS;
}

#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <signal.h>
#include <pigpio.h>

#define VL53L1X_ADDRESS 0x29
#define VL53L1X_REG_IDENTIFICATION_MODEL_ID 0x000c
#define VL53L1X_REG_SOFT_RESET 0x0000
#define VL53L1X_REG_SYSRANGE_START 0x0080
#define VL53L1X_REG_RESULT_RANGE_STATUS 0x0044
#define VL53L1X_REG_RESULT_RANGE_MSB 0x0096
#define VL53L1X_REG_RESULT_RANGE_LSB 0x0097
#define VL53L1X_INTERRUPT_THRESHOLD 50

static int i2c_handle;
static int gpio_handle;
static int door_open = 0;

void close_sensors() {
    gpioWrite(gpio_handle, 18, 0);
    gpioTerminate();
    i2cClose(i2c_handle);
}

void handle_sigint(int signum) {
    close_sensors();
    exit(0);
}

int main() {
    struct timespec sleep_time = {0, 100000000}; // 100 ms
    uint8_t buffer[2];
    uint16_t distance;
    int ret;

    signal(SIGINT, handle_sigint);

    gpio_handle = gpioInitialise();
    if (gpio_handle < 0) {
        fprintf(stderr, "Failed to initialize pigpio\n");
        return EXIT_FAILURE;
    }

    i2c_handle = i2cOpen(1, VL53L1X_ADDRESS, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Failed to open I2C bus\n");
        gpioTerminate();
        return EXIT_FAILURE;
    }

    // Software reset
    buffer[0] = VL53L1X_REG_SOFT_RESET;
    buffer[1] = 0x00;
    ret = i2cWriteByteData(i2c_handle, buffer[0], buffer[1]);
    if (ret < 0) {
        fprintf(stderr, "Failed to write to I2C bus\n");
        close_sensors();
        return EXIT_FAILURE;
    }

    // Set ranging mode
    buffer[0] = VL53L1X_REG_SYSRANGE_START;
    buffer[1] = 0x01;
    ret = i2cWriteByteData(i2c_handle, buffer[0], buffer[1]);
    if (ret < 0) {
        fprintf(stderr, "Failed to write to I2C bus\n");
        close_sensors();
        return EXIT_FAILURE;
    }

    while (1) {
        // Check for data readiness
        buffer[0] = VL53L1X_REG_RESULT_RANGE_STATUS;
        ret = i2cReadByteData(i2c_handle, buffer[0]);
        if (ret < 0) {
            fprintf(stderr, "Failed to read from I2C bus\n");
            close_sensors();
            return EXIT_FAILURE;
        }

        // Read distance
        buffer[0] = VL53L1X_REG_RESULT_RANGE_MSB;
        ret = i2cReadByteData(i2c_handle, buffer[0]);
        if (ret < 0) {
            fprintf(stderr, "Failed to read from I2C bus\n");
            close_sensors();
            return EXIT_FAILURE;
        }
        buffer[1] = VL53L1X_REG_RESULT_RANGE_LSB;
        ret = i2cReadByteData(i2c_handle, buffer[1]);
        if (ret < 0) {
            fprintf(stderr, "Failed to read from I2C bus\n");
            close_sensors();
            return EXIT_FAILURE;
        }

        distance = (buffer[0] << 8) | buffer[1];

        printf("Distance: %d cm\n", distance);

        if (distance <= VL53L1X_INTERRUPT_THRESHOLD) {
            if (!door_open) {
                gpioWrite(gpio_handle, 18, 1);
                door_open = 1;
            }
        } else {
            if (door_open) {
                gpioWrite(gpio_handle, 18, 0);
                door_open = 0;
            }
        }

        nanosleep(&sleep_time, NULL);
    }

    close_sensors();
    return EXIT_SUCCESS;
}

#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <signal.h>
#include <unistd.h>
#include <stdint.h>
#include <pigpio.h>

#define MPU6050_ADDRESS 0x68
#define PWR_MGMT_1 0x6B
#define GYRO_CONFIG 0x1B
#define GYRO_XOUT_H 0x43
#define SENSITIVITY 131.0

volatile sig_atomic_t stop;

void signal_handler(int signum) {
    stop = 1;
}

int main() {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialization failed\n");
        return EXIT_FAILURE;
    }

    if (gpioSetSignalFunc(SIGINT, signal_handler) < 0) {
        fprintf(stderr, "failed to set signal handler\n");
        gpioTerminate();
        return EXIT_FAILURE;
    }

    int file = open("/dev/i2c-1", O_RDWR);
    if (file < 0) {
        fprintf(stderr, "failed to open /dev/i2c-1\n");
        gpioTerminate();
        return EXIT_FAILURE;
    }

    if (ioctl(file, I2C_SLAVE, MPU6050_ADDRESS) < 0) {
        fprintf(stderr, "failed to set I2C slave address\n");
        close(file);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    uint8_t buffer[6];
    int16_t raw_values[3];
    float dps_values[3];

    // Wake up the MPU-6050
    buffer[0] = PWR_MGMT_1;
    buffer[1] = 0x00;
    if (write(file, buffer, 2) != 2) {
        fprintf(stderr, "failed to write to PWR_MGMT_1\n");
        close(file);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    // Set the gyroscope full-scale range to ±250 dps
    buffer[0] = GYRO_CONFIG;
    buffer[1] = 0x00;
    if (write(file, buffer, 2) != 2) {
        fprintf(stderr, "failed to write to GYRO_CONFIG\n");
        close(file);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    while (!stop) {
        // Read the gyroscope data
        buffer[0] = GYRO_XOUT_H;
        if (write(file, buffer, 1) != 1) {
            fprintf(stderr, "failed to write to GYRO_XOUT_H\n");
            break;
        }

        if (read(file, buffer, 6) != 6) {
            fprintf(stderr, "failed to read gyroscope data\n");
            break;
        }

        // Convert the raw signed 16-bit big-endian values to degrees/second
        for (int i = 0; i < 3; i++) {
            raw_values[i] = (buffer[2 * i] << 8) | buffer[2 * i + 1];
            dps_values[i] = raw_values[i] / SENSITIVITY;
        }

        // Log the x, y, and z axis readings
        printf("x: %f, y: %f, z: %f\n", dps_values[0], dps_values[1], dps_values[2]);
        fflush(stdout);
    }

    close(file);
    gpioTerminate();
    return EXIT_SUCCESS;
}

#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <unistd.h>
#include <signal.h>
#include <libgpiod.h>

#define GPIO_PIN_COUNT 4
#define GPIO_PINS {17, 18, 27, 22}
#define WATERING_INTERVAL 86400
#define POLLING_INTERVAL 60

static struct gpiod_chip *chip;
static struct gpiod_line_bulk lines;
static int watering_sequence[GPIO_PIN_COUNT] = {0, 1, 2, 3};
static int watering_index = 0;
static FILE *log_file;

void cleanup_and_exit(int exit_code) {
    gpiod_line_set_value_bulk(lines, GPIO_PIN_COUNT, (enum gpiod_level[]){1, 1, 1, 1});
    gpiod_chip_close(chip);
    fclose(log_file);
    exit(exit_code);
}

void sig_handler(int signum) {
    cleanup_and_exit(EXIT_SUCCESS);
}

int main() {
    struct timespec sleep_time = {.tv_sec = POLLING_INTERVAL, .tv_nsec = 0};
    struct tm *time_info;
    time_t raw_time;
    char time_string[20];
    int i;

    // Open GPIO chip
    chip = gpiod_chip_open("/dev/gpiochip0");
    if (!chip) {
        fprintf(stderr, "Failed to open GPIO chip\n");
        return EXIT_FAILURE;
    }

    // Request GPIO lines
    lines.offsets = GPIO_PINS;
    lines.count = GPIO_PIN_COUNT;
    if (gpiod_chip_get_lines(chip, &lines) < 0) {
        fprintf(stderr, "Failed to get GPIO lines\n");
        gpiod_chip_close(chip);
        return EXIT_FAILURE;
    }

    // Set lines as outputs
    if (gpiod_line_request_output_bulk(lines, "watering", 1) < 0) {
        fprintf(stderr, "Failed to set GPIO lines as outputs\n");
        gpiod_chip_close(chip);
        return EXIT_FAILURE;
    }

    // Set all lines to HIGH
    gpiod_line_set_value_bulk(lines, GPIO_PIN_COUNT, (enum gpiod_level[]){1, 1, 1, 1});

    // Open log file
    log_file = fopen("watering_log.txt", "a");
    if (!log_file) {
        fprintf(stderr, "Failed to open log file\n");
        gpiod_chip_close(chip);
        return EXIT_FAILURE;
    }

    // Install signal handler
    signal(SIGINT, sig_handler);
    signal(SIGTERM, sig_handler);

    // Main loop
    while (1) {
        // Get current time
        time(&raw_time);
        time_info = localtime(&raw_time);
        strftime(time_string, sizeof(time_string), "%Y-%m-%d %H:%M:%S", time_info);

        // Log start time
        fprintf(log_file, "Watering cycle started at %s\n", time_string);
        fflush(log_file);

        // Activate relays sequentially
        for (i = 0; i < GPIO_PIN_COUNT; i++) {
            gpiod_line_set_value_bulk(lines, GPIO_PIN_COUNT, (enum gpiod_level[]){0, 0, 0, 0});
            gpiod_line_set_value_bulk(lines, watering_sequence[watering_index], (enum gpiod_level[]){1});
            sleep(5);
        }

        // Increment watering index and wrap around
        watering_index = (watering_index + 1) % GPIO_PIN_COUNT;

        // Sleep for the rest of the interval
        nanosleep(&sleep_time, NULL);
    }

    // Cleanup and exit
    cleanup_and_exit(EXIT_SUCCESS);
}

#include <stdio.h>
#include <stdlib.h>
#include <signal.h>
#include <time.h>
#include <pigpio.h>

#define GPIO_PIN_1 0
#define GPIO_PIN_2 1
#define GPIO_PIN_3 2
#define GPIO_PIN_4 3
#define PWM_FREQ 1000
#define PWM_DUTY_MAX 255
#define SUNRISE_DURATION 30 // minutes

static int keep_running = 1;

void intHandler(int dummy) {
    keep_running = 0;
}

int main() {
    FILE *log_file;
    time_t rawtime;
    struct tm *timeinfo;
    char buffer[80];

    log_file = fopen("smart_lighting.log", "a");
    if (log_file == NULL) {
        printf("Error opening log file\n");
        return 1;
    }

    if (gpioInitialise() < 0) {
        fprintf(log_file, "Failed to initialize pigpio\n");
        fclose(log_file);
        return 1;
    }

    signal(SIGINT, intHandler);
    signal(SIGTERM, intHandler);

    time(&rawtime);
    timeinfo = localtime(&rawtime);
    strftime(buffer, sizeof(buffer), "%Y-%m-%d %H:%M:%S", timeinfo);
    fprintf(log_file, "%s: Starting sunrise simulation\n", buffer);

    for (int i = 0; i <= PWM_DUTY_MAX && keep_running; i++) {
        if (gpioSetPWMfrequency(0, PWM_FREQ) < 0) {
            fprintf(log_file, "Failed to set PWM frequency\n");
            keep_running = 0;
        }

        if (gpioSetPWMdutycycle(GPIO_PIN_1, i) < 0) {
            fprintf(log_file, "Failed to set PWM dutycycle for GPIO_PIN_1\n");
            keep_running = 0;
        }

        if (gpioSetPWMdutycycle(GPIO_PIN_2, i) < 0) {
            fprintf(log_file, "Failed to set PWM dutycycle for GPIO_PIN_2\n");
            keep_running = 0;
        }

        if (gpioSetPWMdutycycle(GPIO_PIN_3, i) < 0) {
            fprintf(log_file, "Failed to set PWM dutycycle for GPIO_PIN_3\n");
            keep_running = 0;
        }

        if (gpioSetPWMdutycycle(GPIO_PIN_4, i) < 0) {
            fprintf(log_file, "Failed to set PWM dutycycle for GPIO_PIN_4\n");
            keep_running = 0;
        }

        time(&rawtime);
        timeinfo = localtime(&rawtime);
        strftime(buffer, sizeof(buffer), "%Y-%m-%d %H:%M:%S", timeinfo);
        fprintf(log_file, "%s: Set PWM dutycycle to %d\n", buffer, i);

        sleep(1);
    }

    gpioTerminate();

    time(&rawtime);
    timeinfo = localtime(&rawtime);
    strftime(buffer, sizeof(buffer), "%Y-%m-%d %H:%M:%S", timeinfo);
    fprintf(log_file, "%s: Stopping sunrise simulation\n", buffer);

    fclose(log_file);

    return 0;
}

#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <signal.h>
#include <pigpio.h>

#define I2C_BUS 1
#define I2C_ADDRESS 0x68
#define WHO_AM_I 0x75
#define PWR_MGMT_1 0x6B
#define SMPLRT_DIV 0x19
#define GYRO_CONFIG 0x1B
#define GYRO_XOUT_H 0x43
#define LED_PIN 17
#define BUFFER_SIZE 100
#define THRESHOLD 250

typedef struct {
    uint32_t timestamp;
    float x;
    float y;
    float z;
} Reading;

Reading buffer[BUFFER_SIZE];
volatile int buffer_head = 0;
volatile int buffer_tail = 0;

void signal_handler(int signum) {
    gpioTerminate();
    exit(signum);
}

int main() {
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    if (gpioInitialise() < 0) {
        fprintf(stderr, "Failed to initialise pigpio\n");
        return EXIT_FAILURE;
    }

    if (gpioSetMode(LED_PIN, PI_OUTPUT) < 0) {
        fprintf(stderr, "Failed to set LED pin mode\n");
        gpioTerminate();
        return EXIT_FAILURE;
    }

    if (i2cOpen(I2C_BUS, I2C_ADDRESS, 0) < 0) {
        fprintf(stderr, "Failed to open I2C bus\n");
        gpioTerminate();
        return EXIT_FAILURE;
    }

    uint8_t who_am_i;
    if (i2cReadByteData(I2C_BUS, WHO_AM_I, &who_am_i) < 0) {
        fprintf(stderr, "Failed to read WHO_AM_I register\n");
        i2cClose(I2C_BUS);
        gpioTerminate();
        return EXIT_FAILURE;
