#include <sys/ioctl.h>
#include <linux/spi/spidev.h>

#define SPI_BUS 0
#define SPI_DEVICE 0
#define SPI_SPEED 1000000
#define SPI_MODE 0
#define SPI_BITS 8
#define SPI_LSB 0
#define GYRO_CS 8
#define GYRO_REG 0x43
#define GYRO_SCALE 131.0
#define RETRIES 3
#define LOG_FILE "gyro_log.txt"

static int spi_fd = -1;
static int cs_fd = -1;
static FILE *log_file = NULL;

void cleanup(int signum) {
    if (spi_fd != -1) close(spi_fd);
    if (cs_fd != -1) close(cs_fd);
    if (log_file != NULL) fclose(log_file);
    exit(signum);
}

int main() {
    struct gpiod_chip *chip;
    struct gpiod_line_request request;
    struct spi_ioc_transfer xfer;
    uint8_t tx[1] = {GYRO_REG};
    uint8_t rx[6];
    int ret, retry_count;
    struct timespec ts;
    char timestamp[32];

    signal(SIGINT, cleanup);
    signal(SIGTERM, cleanup);

    spi_fd = open("/dev/spidev0.0", O_RDWR);
    if (spi_fd < 0) {
        perror("Failed to open SPI device");
        return -1;
    }

    chip = gpiod_chip_open("/dev/gpiochip0");
    if (!chip) {
        perror("Failed to open GPIO chip");
        return -1;
    }

    cs_fd = gpiod_chip_get_line(chip, GYRO_CS);
    if (cs_fd < 0) {
        perror("Failed to get GPIO line");
        return -1;
    }

    gpiod_line_request_input(cs_fd, "cs", &request);
    gpiod_line_set_value(cs_fd, 1);

    log_file = fopen(LOG_FILE, "w");
    if (!log_file) {
        perror("Failed to open log file");
        return -1;
    }

    while (1) {
        gpiod_line_set_value(cs_fd, 0);

        memset(&xfer, 0, sizeof(xfer));
        xfer.tx_buf = (unsigned long)tx;
        xfer.rx_buf = (unsigned long)rx;
        xfer.len = sizeof(rx);
        xfer.speed_hz = SPI_SPEED;
        xfer.bits_per_word = SPI_BITS;
        xfer.cs_change = 1;

        retry_count = 0;
        while (ioctl(spi_fd, SPI_IOC_MESSAGE(1), &xfer) < 0) {
            if (++retry_count > RETRIES) {
                perror("Failed to read from SPI device");
                break;
            }
            usleep(1000);
        }

        gpiod_line_set_value(cs_fd, 1);

        if (retry_count > RETRIES) continue;

        clock_gettime(CLOCK_REALTIME, &ts);
        strftime(timestamp, sizeof(timestamp), "%FT%T.", &ts);
        sprintf(timestamp + strlen(timestamp), "%09ld", ts.tv_nsec);

        fprintf(log_file, "%s,%d,%d,%d\n", timestamp,
                (int16_t)((rx[0] << 8) | rx[1]) / GYRO_SCALE,
                (int16_t)((rx[2] << 8) | rx[3]) / GYRO_SCALE,
                (int16_t)((rx[4] << 8) | rx[5]) / GYRO_SCALE);

        fflush(log_file);
    }

    return 0;
}

