#define SPI_CHANNEL 0
#define SPI_SPEED 3900000
#define SPI_MODE 0
#define GYROSCOPE_X_REG 0x43
#define GYROSCOPE_Y_REG 0x45
#define GYROSCOPE_Z_REG 0x47
#define GYROSCOPE_SENSITIVITY 131.0
#define CIRCULAR_BUFFER_SIZE 64
#define LED_PIN 17
#define MAX_ANGULAR_VELOCITY 200

typedef struct {
    uint32_t timestamp;
    int16_t x;
    int16_t y;
    int16_t z;
} Reading;

Reading circular_buffer[CIRCULAR_BUFFER_SIZE];
volatile sig_atomic_t stop = false;
int spi_fd = -1;
int led_fd = -1;

void handle_sigint(int signum) {
    stop = true;
}

void release_resources() {
    if (spi_fd != -1) {
        close(spi_fd);
    }
    if (led_fd != -1) {
        gpiod_line_set_value(led_fd, 0);
        gpiod_line_release(led_fd);
    }
}

int main() {
    struct sigaction action;
    action.sa_handler = handle_sigint;
    sigemptyset(&action.sa_mask);
    action.sa_flags = 0;
    sigaction(SIGINT, &action, NULL);

    atexit(release_resources);

    spi_fd = open("/dev/spidev0.0", O_RDWR);
    if (spi_fd < 0) {
        perror("Failed to open SPI device");
        return EXIT_FAILURE;
    }

    struct spi_ioc_transfer spi_transfer = {
        .tx_buf = 0,
        .rx_buf = 0,
        .len = 2,
        .speed_hz = SPI_SPEED,
        .delay_usecs = 0,
        .bits_per_word = 8,
        .cs_change = 0,
        .pad = 0
    };

    int ret = ioctl(spi_fd, SPI_IOC_WR_MODE, &SPI_MODE);
    if (ret < 0) {
        perror("Failed to set SPI mode");
        return EXIT_FAILURE;
    }

    led_fd = gpiod_open_line_by_offset("gpiochip0", LED_PIN, 0);
    if (led_fd < 0) {
        perror("Failed to open LED GPIO line");
        return EXIT_FAILURE;
    }

    gpiod_line_request_output(led_fd, "LED", 0);

    while (!stop) {
        // Chip select low
        gpiod_line_set_value(led_fd, 0);

        // Read X axis
        spi_transfer.tx_buf = GYROSCOPE_X_REG;
        spi_transfer.rx_buf = (unsigned long)&circular_buffer[0].x;
        ret = ioctl(spi_fd, SPI_IOC_MESSAGE(1), &spi_transfer);
        if (ret < 0) {
            perror("Failed to read X axis");
            return EXIT_FAILURE;
        }

        // Read Y axis
        spi_transfer.tx_buf = GYROSCOPE_Y_REG;
        spi_transfer.rx_buf = (unsigned long)&circular_buffer[0].y;
        ret = ioctl(spi_fd, SPI_IOC_MESSAGE(1), &spi_transfer);
        if (ret < 0) {
            perror("Failed to read Y axis");
            return EXIT_FAILURE;
        }

        // Read Z axis
        spi_transfer.tx_buf = GYROSCOPE_Z_REG;
        spi_transfer.rx_buf = (unsigned long)&circular_buffer[0].z;
        ret = ioctl(spi_fd, SPI_IOC_MESSAGE(1), &spi_transfer);
        if (ret < 0) {
            perror("Failed to read Z axis");
            return EXIT_FAILURE;
        }

        // Chip select high
        gpiod_line_set_value(led_fd, 1);

        // Convert raw values to degrees per second
        circular_buffer[0].x = (circular_buffer[0].x / GYROSCOPE_SENSITIVITY);
        circular_buffer[0].y = (circular_buffer[0].y / GYROSCOPE_SENSITIVITY);
        circular_buffer[0].z = (circular_buffer[0].z / GYROSCOPE_SENSITIVITY);

        // Check for excessive angular velocity
        if (abs(circular_buffer[0].x) > MAX_ANGULAR_VELOCITY ||
            abs(circular_buffer[0].y) > MAX_ANGULAR_VELOCITY ||
            abs(circular_buffer[0].z) > MAX_ANGULAR_VELOCITY) {
            gpiod_line_set_value(led_fd, 1);
            usleep(500000);
            gpiod_line_set_value(led_fd, 0);
            usleep(500000);
        }

        // Print readings
        printf("%u, %d, %d, %d\n", circular_buffer[0].timestamp, circular_buffer[0].x, circular_buffer[0].y, circular_buffer[0].z);
    }

    return EXIT_SUCCESS;
