#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <unistd.h>
#include <signal.h>
#include <pigpio.h>

#define MPU6050_ADDRESS 0x68
#define PWR_MGMT_1 0x6B
#define ACCEL_CONFIG 0x1C
#define ACCEL_XOUT_H 0x3B
#define LED_PIN 21
#define SAMPLE_INTERVAL 100000 // 100ms

int i2c_handle;
FILE *log_file;

void cleanup(int signum) {
    gpioWrite(LED_PIN, 0);
    gpioTerminate();
    fclose(log_file);
    exit(signum);
}

int main() {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Failed to initialize pigpio\n");
        return EXIT_FAILURE;
    }

    signal(SIGINT, cleanup);

    if ((i2c_handle = piI2COpen(1, MPU6050_ADDRESS)) < 0) {
        fprintf(stderr, "Failed to open I2C bus 1\n");
        gpioTerminate();
        return EXIT_FAILURE;
    }

    if (piI2CWriteByteData(i2c_handle, PWR_MGMT_1, 0x00) < 0) {
        fprintf(stderr, "Failed to wake MPU6050\n");
        goto cleanup;
    }

    if (piI2CWriteByteData(i2c_handle, ACCEL_CONFIG, 0x00) < 0) {
        fprintf(stderr, "Failed to set accelerometer range\n");
        goto cleanup;
    }

    log_file = fopen("tilt_log.txt", "w");
    if (!log_file) {
        fprintf(stderr, "Failed to open log file\n");
        goto cleanup;
    }

    gpioSetMode(LED_PIN, PI_OUTPUT);

    while (1) {
        uint8_t raw_data[6];
        int16_t accel_x, accel_y, accel_z;
        float roll, pitch;

        if (piI2CReadByteData(i2c_handle, ACCEL_XOUT_H, raw_data, 6) < 0) {
            fprintf(stderr, "Failed to read accelerometer data\n");
            continue;
        }

        accel_x = (raw_data[0] << 8) | raw_data[1];
        accel_y = (raw_data[2] << 8) | raw_data[3];
        accel_z = (raw_data[4] << 8) | raw_data[5];

        roll = atan2(accel_y, accel_z) * 180 / M_PI;
        pitch = atan2(-accel_x, sqrt(accel_y * accel_y + accel_z * accel_z)) * 180 / M_PI;

        time_t now = time(NULL);
        struct tm *t = localtime(&now);
        char timestamp[20];
        strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", t);

        fprintf(log_file, "%s, %.2f, %.2f\n", timestamp, roll, pitch);
        printf("Roll: %.2f, Pitch: %.2f\n", roll, pitch);

        gpioWrite(LED_PIN, abs(roll) > 45 || abs(pitch) > 45 ? PI_HIGH : PI_LOW);

        usleep(SAMPLE_INTERVAL);
    }

cleanup:
    cleanup(0);
    return EXIT_SUCCESS;
}

#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <string.h>
#include <time.h>
#include <fcntl.h>
#include <unistd.h>
#include <sys/ioctl.h>
#include <linux/i2c-dev.h>
#include <gpiod.h>

#define I2C_ADDRESS 0x5A
#define AMBIENT_LIGHT_REG 0x20
#define PROXIMITY_REG 0x22
#define GPIO17 17
#define RETRIES 3
#define DELAY 10

int i2c_fd, log_fd;
struct gpiod_chip *chip;
struct gpiod_line *line;

void cleanup(int signum) {
    close(i2c_fd);
    close(log_fd);
    gpiod_line_set_value(line, 0);
    gpiod_chip_close(chip);
    exit(signum);
}

int main() {
    struct sigaction sigIntHandler;
    sigIntHandler.sa_handler = cleanup;
    sigemptyset(&sigIntHandler.sa_mask);
    sigIntHandler.sa_flags = 0;
    sigaction(SIGINT, &sigIntHandler, NULL);
    sigaction(SIGTERM, &sigIntHandler, NULL);

    chip = gpiod_chip_open("/dev/gpiochip0");
    if (!chip) {
        fprintf(stderr, "Failed to open GPIO chip\n");
        return EXIT_FAILURE;
    }

    line = gpiod_chip_get_line(chip, GPIO17);
    if (!line) {
        fprintf(stderr, "Failed to get GPIO line\n");
        gpiod_chip_close(chip);
        return EXIT_FAILURE;
    }

    if (gpiod_line_request_output(line, "biometric_led", 0) < 0) {
        fprintf(stderr, "Failed to request GPIO line as output\n");
        gpiod_chip_close(chip);
        return EXIT_FAILURE;
    }

    i2c_fd = open("/dev/i2c-1", O_RDWR);
    if (i2c_fd < 0) {
        fprintf(stderr, "Failed to open I2C device\n");
        gpiod_chip_close(chip);
        return EXIT_FAILURE;
    }

    if (ioctl(i2c_fd, I2C_SLAVE, I2C_ADDRESS) < 0) {
        fprintf(stderr, "Failed to set I2C slave address\n");
        gpiod_chip_close(chip);
        return EXIT_FAILURE;
    }

    log_fd = open("biometric_log.txt", O_WRONLY | O_APPEND | O_CREAT, 0666);
    if (log_fd < 0) {
        fprintf(stderr, "Failed to open log file\n");
        gpiod_chip_close(chip);
        return EXIT_FAILURE;
    }

    while (1) {
        uint8_t buffer[4];
        for (int i = 0; i < RETRIES; i++) {
            if (write(i2c_fd, &AMBIENT_LIGHT_REG, 1) != 1 ||
                read(i2c_fd, buffer, 2) != 2 ||
                write(i2c_fd, &PROXIMITY_REG, 1) != 1 ||
                read(i2c_fd, buffer + 2, 2) != 2) {
                usleep(DELAY * 1000);
                continue;
            }
            break;
        }

        struct timespec ts;
        clock_gettime(CLOCK_REALTIME, &ts);
        char log[64];
        strftime(log, sizeof(log), "%Y-%m-%d %H:%M:%S", gmtime(&ts.tv_sec));
        sprintf(log + strlen(log), ",AmbientLight:%u,Proximity:%u\n", (uint16_t)buffer[0] | (buffer[1] << 8), (uint16_t)buffer[2] | (buffer[3] << 8));
        write(log_fd, log, strlen(log));

        gpiod_line_set_value(line, buffer[2] > 100 ? 1 : 0);

        usleep(100 * 1000);
    }

    return EXIT_SUCCESS;
}

#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <unistd.h>
#include <signal.h>
#include <time.h>
#include <pigpio.h>

#define SPI_CHANNEL 0
#define SPI_SPEED 1000000
#define SPI_MODE 0
#define SPI_BITS 8
#define SPI_LSBFIRST 0
#define SPI_READ_BIT 0x80
#define SPI_XFER_SIZE 3
#define GYRO_DATA_FILE "gyro_data.csv"
#define SAMPLE_DELAY 100000 // 10 ms

volatile sig_atomic_t stop_requested = 0;

void signal_handler(int signum) {
    stop_requested = 1;
}

int spi_read(int spi_fd, uint8_t address, int16_t *data) {
    uint8_t tx[SPI_XFER_SIZE] = {address | SPI_READ_BIT, 0};
    uint8_t rx[SPI_XFER_SIZE] = {0};

    if (spiXfer(spi_fd, tx, rx, SPI_XFER_SIZE) != SPI_XFER_SIZE) {
        return -1;
    }

    *data = (rx[1] << 8) | rx[2];
    return 0;
}

int main() {
    int spi_fd;
    FILE *file;
    struct timespec sleep_time = {0, SAMPLE_DELAY};
    struct tm *time_info;
    time_t raw_time;
    int16_t x_rate, y_rate;
    int reinit_count = 0;

    signal(SIGINT, signal_handler);

    if (gpioInitialise() < 0) {
        fprintf(stderr, "Failed to initialize pigpio\n");
        return EXIT_FAILURE;
    }

    spi_fd = spiOpen(SPI_CHANNEL, SPI_SPEED, SPI_MODE);
    if (spi_fd < 0) {
        fprintf(stderr, "Failed to open SPI channel\n");
        gpioTerminate();
        return EXIT_FAILURE;
    }

    file = fopen(GYRO_DATA_FILE, "w");
    if (!file) {
        fprintf(stderr, "Failed to open file\n");
        spiClose(spi_fd);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    fprintf(file, "timestamp, x_rate, y_rate\n");

    while (!stop_requested && reinit_count < 3) {
        if (spi_read(spi_fd, 0x02, &x_rate) < 0) {
            fprintf(stderr, "Failed to read X rate\n");
            reinit_count++;
            continue;
        }

        if (spi_read(spi_fd, 0x04, &y_rate) < 0) {
            fprintf(stderr, "Failed to read Y rate\n");
            reinit_count++;
            continue;
        }

        time(&raw_time);
        time_info = localtime(&raw_time);

        fprintf(file, "%ld.%06ld, %d, %d\n",
                (long)time_info->tm_sec, (long)time_info->tm_usec,
                x_rate, y_rate);

        nanosleep(&sleep_time, NULL);
        reinit_count = 0;
    }

    fclose(file);
    spiClose(spi_fd);
    gpioTerminate();

    return EXIT_SUCCESS;
}

#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <pigpio.h>

#define ALERT_PIN 17
#define SENSOR1_PIN 23
#define SENSOR2_PIN 24
#define EVENT_DURATION 500 // milliseconds

static int alert_triggered = 0;
static int sensor1_state = 0;
static int sensor2_state = 0;
static int sensor1_count = 0;
static int sensor2_count = 0;
static time_t last_event_time = 0;

void log_event() {
    time_t now = time(NULL);
    struct tm *timeinfo = localtime(&now);
    char buffer[80];
    strftime(buffer, sizeof(buffer), "%Y-%m-%d %H:%M:%S", timeinfo);
    FILE *file = fopen("seismic_events.txt", "a");
    if (file == NULL) {
        printf("Error opening file!\n");
        return;
    }
    fprintf(file, "%s - Seismic event detected!\n", buffer);
    fclose(file);
}

void alert() {
    if (alert_triggered) return;
    alert_triggered = 1;
    gpioWrite(ALERT_PIN, 1);
    sleep(2);
    gpioWrite(ALERT_PIN, 0);
    alert_triggered = 0;
}

void sensor1_callback(int gpio, int level, uint32_t tick) {
    if (level == 1) {
        sensor1_count++;
        if (sensor1_count == 1) {
            sensor1_state = 1;
            last_event_time = time(NULL);
        }
    } else {
        sensor1_count = 0;
        sensor1_state = 0;
    }
    if (sensor1_state && sensor2_state && (time(NULL) - last_event_time) * 1000 >= EVENT_DURATION) {
        alert();
        log_event();
    }
}

void sensor2_callback(int gpio, int level, uint32_t tick) {
    if (level == 1) {
        sensor2_count++;
        if (sensor2_count == 1) {
            sensor2_state = 1;
            last_event_time = time(NULL);
        }
    } else {
        sensor2_count = 0;
        sensor2_state = 0;
    }
    if (sensor1_state && sensor2_state && (time(NULL) - last_event_time) * 1000 >= EVENT_DURATION) {
        alert();
        log_event();
    }
}

void signal_handler(int signum) {
    gpioWrite(ALERT_PIN, 0);
    gpioTerminate();
    exit(signum);
}

int main() {
    if (gpioInitialise() < 0) {
        printf("pigpio initialisation failed\n");
        return 1;
    }

    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    if (gpioSetMode(ALERT_PIN, PI_OUTPUT) < 0) {
        printf("Failed to set mode for alert pin\n");
        return 1;
    }

    if (gpioSetMode(SENSOR1_PIN, PI_INPUT) < 0) {
        printf("Failed to set mode for sensor1 pin\n");
        return 1;
    }

    if (gpioSetMode(SENSOR2_PIN, PI_INPUT) < 0) {
        printf("Failed to set mode for sensor2 pin\n");
        return 1;
    }

