#include <unistd.h>
#include <signal.h>

#define SPI_CHANNEL 0
#define SPI_SPEED 1000000
#define SPI_MODE 0
#define SPI_MSB 1
#define SPI_ADDRESS 0x02
#define LED_PIN 17
#define THRESHOLD 20.0

typedef struct {
    struct timespec timestamp;
    int16_t angular_velocity;
} Reading;

Reading buffer[100];
int buffer_head = 0;
int buffer_tail = 0;
int buffer_count = 0;
int running = 1;

void handle_signal(int signum) {
    running = 0;
}

int main() {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Failed to initialize pigpio\n");
        return EXIT_FAILURE;
    }

    if (gpioSetMode(LED_PIN, PI_OUTPUT) < 0) {
        fprintf(stderr, "Failed to set LED pin mode\n");
        gpioTerminate();
        return EXIT_FAILURE;
    }

    if (gpioSetPullUpDown(LED_PIN, PI_PUD_OFF) < 0) {
        fprintf(stderr, "Failed to set LED pin pull-up/down\n");
        gpioTerminate();
        return EXIT_FAILURE;
    }

    if (gpioSetAlertFunc(LED_PIN, NULL) < 0) {
        fprintf(stderr, "Failed to set LED pin alert function\n");
        gpioTerminate();
        return EXIT_FAILURE;
    }

    if (signal(SIGINT, handle_signal) == SIG_ERR || signal(SIGTERM, handle_signal) == SIG_ERR) {
        fprintf(stderr, "Failed to set signal handler\n");
        gpioTerminate();
        return EXIT_FAILURE;
    }

    if (spiOpen(SPI_CHANNEL, SPI_SPEED, SPI_MODE) < 0) {
        fprintf(stderr, "Failed to open SPI channel\n");
        gpioTerminate();
        return EXIT_FAILURE;
    }

    while (running) {
        uint8_t address = SPI_MSB | SPI_ADDRESS;
        uint8_t data[2];
        if (spiXfer(SPI_CHANNEL, &address, 1, data, 2) != 2) {
            fprintf(stderr, "Failed to read from SPI\n");
            break;
        }

        int16_t angular_velocity = (data[0] << 8) | data[1];
        double angular_velocity_deg_s = angular_velocity * 0.06103515625; // 200 LSB/deg/s

        clock_gettime(CLOCK_MONOTONIC, &buffer[buffer_head].timestamp);
        buffer[buffer_head].angular_velocity = angular_velocity_deg_s;
        buffer_head = (buffer_head + 1) % 100;
        buffer_count = (buffer_count + 1) % 100;

        if (angular_velocity_deg_s > THRESHOLD) {
            gpioWrite(LED_PIN, PI_HIGH);
        } else if (buffer_count > 0) {
            gpioWrite(LED_PIN, PI_LOW);
        }
    }

    spiClose(SPI_CHANNEL);
    gpioTerminate();
    return EXIT_SUCCESS;
}

#include <stdio.h>
#include <stdlib.h>
#include <signal.h>
#include <pigpio.h>

#define LAMP1 17
#define LAMP2 18
#define LAMP3 27
#define PWM_RANGE 255
#define PWM_FREQ 100

volatile sig_atomic_t stop = 0;

void sig_handler(int signum) {
    stop = 1;
}

int main(int argc, char *argv[]) {
    if (argc != 2) {
        fprintf(stderr, "Usage: %s <fade_duration>\n", argv[0]);
        return EXIT_FAILURE;
    }

    int duration = atoi(argv[1]);
    if (duration < 1 || duration > 3600) {
        fprintf(stderr, "Fade duration must be between 1 and 3600 seconds.\n");
        return EXIT_FAILURE;
    }

    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed.\n");
        return EXIT_FAILURE;
    }

    signal(SIGINT, sig_handler);
    signal(SIGTERM, sig_handler);

    printf("Starting smart sunset simulator...\n");

    int lamp_pwm[LAMP3 + 1] = {0};
    for (int i = LAMP1; i <= LAMP3; i++) {
        lamp_pwm[i] = gpioHardwarePWM(i, PWM_FREQ, PWM_RANGE);
        if (lamp_pwm[i] < 0) {
            fprintf(stderr, "Failed to initialise lamp %d.\n", i);
            goto cleanup;
        }
        printf("Lamp %d initialised with PWM channel %d.\n", i, lamp_pwm[i]);
    }

    for (int i = LAMP1; i <= LAMP3; i++) {
        if (stop) break;
        printf("Fading lamp %d...\n", i);
        for (int duty = PWM_RANGE; duty >= 0; duty -= PWM_RANGE / duration) {
            if (stop) break;
            gpioHardwarePWMWrite(lamp_pwm[i], duty);
            sleep(1);
        }
        printf("Lamp %d faded.\n", i);
    }

    printf("Smart sunset simulator completed.\n");

cleanup:
    for (int i = LAMP1; i <= LAMP3; i++) {
        if (lamp_pwm[i] > 0) gpioHardwarePWM(lamp_pwm[i], 0, 0);
    }
    gpioTerminate();
    return stop ? EXIT_FAILURE : EXIT_SUCCESS;
}

