#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <signal.h>
#include <time.h>
#include <pigpio.h>

#define GPIO_PIN 17
#define I2C_BUS 1
#define I2C_ADDRESS 0x5A
#define TOUCH_THRESHOLD 0x0A
#define RELEASE_THRESHOLD 0x08
#define DEBOUNCE_TIME 0x21
#define CHARGE_TIME 0x0D
#define RUN_MODE 0x0D
#define ELECTRODE 0
#define RESET 0x63
#define STOP_MODE 0x00
#define TOUCH_STATUS_LSB 0x00
#define TOGGLE_DELAY 100
#define READ_INTERVAL 10

FILE *log_file;

void close_log() {
    fclose(log_file);
}

void log_error(const char *message) {
    time_t now = time(NULL);
    struct tm *t = localtime(&now);
    fprintf(log_file, "[%d-%02d-%02d %02d:%02d:%02d] %s\n", t->tm_year + 1900, t->tm_mon + 1, t->tm_mday, t->tm_hour, t->tm_min, t->tm_sec, message);
    fflush(log_file);
}

void close_program(int signum) {
    log_error("Program interrupted by signal");
    gpioTerminate();
    close_log();
    exit(signum);
}

int main() {
    signal(SIGINT, close_program);
    signal(SIGTERM, close_program);

    log_file = fopen("touch_relay.log", "w");
    if (!log_file) {
        log_error("Failed to open log file");
        return 1;
    }

    if (gpioInitialise() < 0) {
        log_error("Failed to initialise pigpio");
        return 1;
    }

    if (gpioSetMode(GPIO_PIN, PI_OUTPUT) < 0) {
        log_error("Failed to set GPIO mode");
        return 1;
    }

    if (gpioWrite(GPIO_PIN, PI_LOW) < 0) {
        log_error("Failed to set GPIO to LOW");
        return 1;
    }

    int i2c_handle = i2cOpen(I2C_BUS, I2C_ADDRESS, 0);
    if (i2c_handle < 0) {
        log_error("Failed to open I2C device");
        return 1;
    }

    uint8_t buffer[2] = {RESET, STOP_MODE};
    if (i2cWriteDevice(i2c_handle, buffer, 2) < 0) {
        log_error("Failed to write to I2C device");
        return 1;
    }

    buffer[0] = 0x5E;
    buffer[1] = RUN_MODE;
    if (i2cWriteDevice(i2c_handle, buffer, 2) < 0) {
        log_error("Failed to write to I2C device");
        return 1;
    }

    buffer[0] = 0x5D;
    buffer[1] = 1 << ELECTRODE;
    if (i2cWriteDevice(i2c_handle, buffer, 2) < 0) {
        log_error("Failed to write to I2C device");
        return 1;
    }

    buffer[0] = 0x41;
    buffer[1] = TOUCH_THRESHOLD;
    if (i2cWriteDevice(i2c_handle, buffer, 2) < 0) {
        log_error("Failed to write to I2C device");
        return 1;
    }

    buffer[0] = 0x42;
    buffer[1] = RELEASE_THRESHOLD;
    if (i2cWriteDevice(i2c_handle, buffer, 2) < 0) {
        log_error("Failed to write to I2C device");
        return 1;
    }

    buffer[0] = 0x5B;
    buffer[1] = DEBOUNCE_TIME;
    if (i2cWriteDevice(i2c_handle, buffer, 2) < 0) {
        log_error("Failed to write to I2C device");
        return 1;
    }

    buffer[0] = 0x5C;
    buffer[1] = CHARGE_TIME;
    if (i2cWriteDevice(i2c_handle, buffer, 2) < 0) {
        log_error("Failed to write to I2C device");
        return 1;
    }

    uint8_t touch_status = 0;
    uint8_t last_touch_status = 0;
    uint32_t last_toggle_time = 0;

    while (1) {
        if (i2cReadDevice(i2c_handle, &touch_status, 2) < 0) {
            log_error("Failed to read from I2C device");
            return 1;
        }

        if ((touch_status & (1 << ELECTRODE)) && !(last_touch_status & (1 << ELECTRODE)) && (piTime() - last_toggle_time) > TOGGLE_DELAY) {
            if (gpioWrite(GPIO_PIN, (gpioRead(GPIO_PIN) == PI_LOW) ? PI_HIGH : PI_LOW) < 0) {
                log_error("Failed to toggle GPIO");
                return 1;
            }
            last_toggle_time = piTime();
        }

        last_touch_status = touch_status;
        piSleep(READ_INTERVAL);
    }

    i2cClose(i2c_handle);
    gpioTerminate();
    close_log();
    return 0;
}

#include <stdio.h>
#include <stdlib.h>
#include <signal.h>
#include <time.h>
#include <gpiod.h>

#define SENSOR_PIN 17
#define BUZZER_PIN 18
#define LED_PIN 23
#define DEBOUNCE_COUNT 3
#define DEBOUNCE_INTERVAL 50 // ms

static FILE *log_file;
static struct gpiod_chip *chip;
static struct gpiod_line *sensor_line, *buzzer_line, *led_line;
static int debounce_count = 0;

void cleanup() {
    gpiod_line_release(sensor_line);
    gpiod_line_release(buzzer_line);
    gpiod_line_release(led_line);
    fclose(log_file);
}

void handle_signal(int signum) {
    cleanup();
    exit(signum);
}

int main() {
    struct sigaction action;
    action.sa_handler = handle_signal;
    sigemptyset(&action.sa_mask);
    action.sa_flags = 0;
    sigaction(SIGINT, &action, NULL);
    sigaction(SIGTERM, &action, NULL);

    log_file = fopen("flame_log.txt", "w");
    if (!log_file) {
        fprintf(stderr, "Failed to open log file\n");
        return EXIT_FAILURE;
    }

    chip = gpiod_chip_open("/dev/gpiochip0");
    if (!chip) {
        fprintf(stderr, "Failed to open GPIO chip\n");
        return EXIT_FAILURE;
    }

    sensor_line = gpiod_chip_get_line(chip, SENSOR_PIN);
    if (!sensor_line) {
        fprintf(stderr, "Failed to get sensor line\n");
        return EXIT_FAILURE;
    }

    buzzer_line = gpiod_chip_get_line(chip, BUZZER_PIN);
    if (!buzzer_line) {
        fprintf(stderr, "Failed to get buzzer line\n");
        return EXIT_FAILURE;
    }

    led_line = gpiod_chip_get_line(chip, LED_PIN);
    if (!led_line) {
        fprintf(stderr, "Failed to get LED line\n");
        return EXIT_FAILURE;
    }

    atexit(cleanup);

    while (1) {
        struct gpiod_line_event event;
        int value = gpiod_line_get_value(sensor_line);
        if (value == 0) {
            debounce_count++;
            if (debounce_count == DEBOUNCE_COUNT) {
                gpiod_line_event_wait(sensor_line, &event);
                if (event.event_type == GPIOD_LINE_EVENT_RISING_EDGE) {
                    time_t now = time(NULL);
                    struct tm *timeinfo = localtime(&now);
                    char buffer[80];
                    strftime(buffer, sizeof(buffer), "%Y-%m-%d %H:%M:%S", timeinfo);
                    fprintf(log_file, "%s Flame Detected\n", buffer);
                    fflush(log_file);
                    gpiod_line_set_value(buzzer_line, 1);
                    gpiod_line_set_value(led_line, 1);
                }
                debounce_count = 0;
            }
        } else {
            debounce_count = 0;
            gpiod_line_set_value(buzzer_line, 0);
            gpiod_line_set_value(led_line, 0);
        }
        usleep(DEBOUNCE_INTERVAL * 1000);
    }

    return EXIT_SUCCESS;
}

