#define MOTOR_A_FORWARD  0
#define MOTOR_A_BACKWARD  1
#define MOTOR_B_FORWARD  2
#define MOTOR_B_BACKWARD  3
#define MOTOR_SPEED_MAX  255
#define TILT_ERROR_MIN  -10.0
#define TILT_ERROR_MAX   10.0
#define DISTANCE_MIN     2.0
#define DISTANCE_MAX    400.0
#define PID_KP           1.0
#define PID_KI           0.01
#define PID_KD           0.1
#define CONTROL_INTERVAL  50 // ms

static volatile int run = 1;
static FILE *log_file = NULL;

void stop(int signum) {
    run = 0;
}

int main() {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Failed to initialize pigpio\n");
        return 1;
    }

    signal(SIGINT, stop);

    log_file = fopen("balance_log.txt", "w");
    if (!log_file) {
        fprintf(stderr, "Failed to open log file\n");
        gpioTerminate();
        return 1;
    }

    // Set up motor GPIOs
    int motor_pins[] = {17, 18, 22, 23};
    for (int i = 0; i < sizeof(motor_pins) / sizeof(motor_pins[0]); i++) {
        gpioSetMode(motor_pins[i], PI_OUTPUT);
    }

    // Set up enable GPIOs
    int enable_pins[] = {24, 25};
    for (int i = 0; i < sizeof(enable_pins) / sizeof(enable_pins[0]); i++) {
        gpioSetMode(enable_pins[i], PI_OUTPUT);
        gpioWrite(enable_pins[i], PI_HIGH);
    }

    // Simulate control loop
    while (run) {
        // Simulate tilt error and distance
        float tilt_error = (float)rand() / RAND_MAX * (TILT_ERROR_MAX - TILT_ERROR_MIN) + TILT_ERROR_MIN;
        float distance = (float)rand() / RAND_MAX * (DISTANCE_MAX - DISTANCE_MIN) + DISTANCE_MIN;

        // PID control
        float motor_a_speed = 0;
        float motor_b_speed = 0;

        if (distance < 20) {
            motor_a_speed = -MOTOR_SPEED_MAX / 2;
            motor_b_speed = -MOTOR_SPEED_MAX / 2;
        } else {
            motor_a_speed = PID_KP * tilt_error + PID_KI * distance + PID_KD * distance;
            motor_b_speed = PID_KP * tilt_error - PID_KI * distance - PID_KD * distance;
        }

        // Clamp motor speeds
        if (motor_a_speed > MOTOR_SPEED_MAX) motor_a_speed = MOTOR_SPEED_MAX;
        if (motor_a_speed < -MOTOR_SPEED_MAX) motor_a_speed = -MOTOR_SPEED_MAX;
        if (motor_b_speed > MOTOR_SPEED_MAX) motor_b_speed = MOTOR_SPEED_MAX;
        if (motor_b_speed < -MOTOR_SPEED_MAX) motor_b_speed = -MOTOR_SPEED_MAX;

        // Set motor speeds
        gpioPWM(motor_pins[MOTOR_A_FORWARD], motor_a_speed);
        gpioPWM(motor_pins[MOTOR_A_BACKWARD], -motor_a_speed);
        gpioPWM(motor_pins[MOTOR_B_FORWARD], motor_b_speed);
        gpioPWM(motor_pins[MOTOR_B_BACKWARD], -motor_b_speed);

        // Log control cycle
        time_t now = time(NULL);
        struct tm *t = localtime(&now);
        fprintf(log_file, "%d-%02d-%02d %02d:%02d:%02d, %.2f, %.2f, %.2f, %.2f\n",
                t->tm_year + 1900, t->tm_mon + 1, t->tm_mday,
                t->tm_hour, t->tm_min, t->tm_sec,
                tilt_error, distance, motor_a_speed, motor_b_speed);

        // Wait for next control cycle
        gpioDelay(CONTROL_INTERVAL * 1000);
    }

    // Stop motors
    for (int i = 0; i < sizeof(motor_pins) / sizeof(motor_pins[0]); i++) {
        gpioPWM(motor_pins[i], 0);
    }

    // Close log file
    fclose(log_file);

    // Terminate pigpio
    gpioTerminate();

    return 0;
}

