#include <stdio.h>
#include <stdlib.h>
#include <signal.h>
#include <pigpio.h>

#define RELAY_PIN 17
#define TOUCH_PIN 4
#define DEBOUNCE_TIME 50000 // 50 ms

volatile sig_atomic_t stop = 0;

void signal_handler(int signum) {
    stop = 1;
}

int main() {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
