        fprintf(stderr, "failed to set relay pin mode\n");
        gpioTerminate();
        return EXIT_FAILURE;
    }

    if (gpioSetMode(TOUCH_PIN, PI_INPUT) < 0) {
        fprintf(stderr, "failed to set touch pin mode\n");
        gpioTerminate();
        return EXIT_FAILURE;
    }

    if (gpioSetPullUpDown(TOUCH_PIN, PI_PUD_DOWN) < 0) {
        fprintf(stderr, "failed to set pull down on touch pin\n");
        gpioTerminate();
        return EXIT_FAILURE;
    }

    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    while (!stop) {
        if (gpioRead(TOUCH_PIN) == PI_HIGH) {
            gpioDelay(DEBOUNCE_TIME);
            if (gpioRead(TOUCH_PIN) == PI_HIGH) {
                int relay_state = gpioRead(RELAY_PIN);
                gpioWrite(RELAY_PIN, !relay_state);
            }
        }
    }

    gpioTerminate();
    return EXIT_SUCCESS;
}
```

This program sets up the GPIO pins and then enters an infinite loop where it checks the state of the touch sensor. If the sensor is touched, it waits for the debounce time to ensure it's not a false positive, then toggles the relay. The program will terminate when it receives a SIGINT or SIGTERM signal, which is what happens when you press Ctrl+C.

Please note that you need to have the pigpio library installed on your Raspberry Pi to compile and run this program. You can install it using the following command:

```bash
sudo apt-get install pigpio
```

Also, you need to connect the TTP223 sensor to the Raspberry Pi as follows:

- VCC to 3.3V on Raspberry Pi
- GND to GND on Raspberry Pi
- S to GPIO4 (physical pin 7) on Raspberry Pi

And connect the relay as follows:

- VCC to 5V on Raspberry Pi
- GND to GND on Raspberry Pi
- IN to GPIO17 (physical pin 11) on Raspberry Pi
```
