#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <signal.h>
#include <pigpio.h>
#include <alsa/asoundlib.h>

#define ALSA_AVAILABLE

#ifdef ALSA_AVAILABLE
#define ALSA_DEVICE "default"
#define ALSA_CHANNELS 1
#define ALSA_FORMAT SND_PCM_FORMAT_S16_LE
#define ALSA_RATE 8000
#define ALSA_PERIOD_SIZE 1024
#endif

#define GPIO_RED 17
#define GPIO_GREEN 18
#define GPIO_BLUE 27
#define PWM_RANGE 1024

void exit_handler(int signum) {
    printf("Exiting...\n");
    gpioTerminate();
    exit(signum);
}

int main(int argc, char *argv[]) {
    double sensitivity = 1.0;
    if (argc > 1) {
        sensitivity = atof(argv[1]);
        if (sensitivity <= 0) {
            fprintf(stderr, "Sensitivity must be positive.\n");
            return EXIT_FAILURE;
        }
    }

    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed.\n");
        return EXIT_FAILURE;
    }

    signal(SIGINT, exit_handler);
    signal(SIGTERM, exit_handler);

    #ifdef ALSA_AVAILABLE
    snd_pcm_t *handle;
    snd_pcm_hw_params_t *params;
    int err;

    if ((err = snd_pcm_open(&handle, ALSA_DEVICE, SND_PCM_STREAM_CAPTURE, 0)) < 0) {
        fprintf(stderr, "ALSA: cannot open audio device: %s\n", snd_strerror(err));
        return EXIT_FAILURE;
    }

    if ((err = snd_pcm_hw_params_malloc(&params)) < 0) {
        fprintf(stderr, "ALSA: cannot allocate hardware parameter structure: %s\n", snd_strerror(err));
        return EXIT_FAILURE;
    }

    if ((err = snd_pcm_hw_params_any(handle, params)) < 0) {
        fprintf(stderr, "ALSA: cannot initialize hardware parameter structure: %s\n", snd_strerror(err));
        return EXIT_FAILURE;
    }

    if ((err = snd_pcm_hw_params_set_access(handle, params, SND_PCM_ACCESS_RW_INTERLEAVED)) < 0) {
        fprintf(stderr, "ALSA: cannot set access type: %s\n", snd_strerror(err));
        return EXIT_FAILURE;
    }

    if ((err = snd_pcm_hw_params_set_format(handle, params, ALSA_FORMAT)) < 0) {
        fprintf(stderr, "ALSA: cannot set sample format: %s\n", snd_strerror(err));
        return EXIT_FAILURE;
    }

    if ((err = snd_pcm_hw_params_set_rate_near(handle, params, &ALSA_RATE, 0)) < 0) {
        fprintf(stderr, "ALSA: cannot set sample rate: %s\n", snd_strerror(err));
        return EXIT_FAILURE;
    }

    if ((err = snd_pcm_hw_params_set_channels(handle, params, ALSA_CHANNELS)) < 0) {
        fprintf(stderr, "ALSA: cannot set channel count: %s\n", snd_strerror(err));
        return EXIT_FAILURE;
    }

    if ((err = snd_pcm_hw_params_set_period_size_near(handle, params, &ALSA_PERIOD_SIZE, 0)) < 0) {
        fprintf(stderr, "ALSA: cannot set period size: %s\n", snd_strerror(err));
        return EXIT_FAILURE;
    }

    if ((err = snd_pcm_hw_params(handle, params)) < 0) {
        fprintf(stderr, "ALSA: cannot set parameters: %s\n", snd_strerror(err));
        return EXIT_FAILURE;
    }

    snd_pcm_hw_params_free(params);
    #endif

    gpioSetMode(GPIO_RED, PI_OUTPUT);
    gpioSetMode(GPIO_GREEN, PI_OUTPUT);
    gpioSetMode(GPIO_BLUE, PI_OUTPUT);

    while (1) {
        #ifdef ALSA_AVAILABLE
        short buffer[ALSA_PERIOD_SIZE];
        if ((err = snd_pcm_readi(handle, buffer, ALSA_PERIOD_SIZE)) < 0) {
            if (err == -EPIPE) {
                snd_pcm_prepare(handle);
            } else if (err == -ESTRPIPE) {
                snd_pcm_resume(handle);
            } else {
                fprintf(stderr, "ALSA: read error: %s\n", snd_strerror(err));
                return EXIT_FAILURE;
            }
        }
        #else
        short buffer[ALSA_PERIOD_SIZE];
        for (int i = 0; i < ALSA_PERIOD_SIZE; i++) {
            buffer[i] = sin(i * 2 * M_PI / ALSA_PERIOD_SIZE) * 32767;
        }
        #endif

        long sum = 0;
        for (int i = 0; i < ALSA_PERIOD_SIZE; i++) {
            sum += buffer[i] * buffer[i];
        }
        double rms = sqrt(sum / ALSA_PERIOD_SIZE) / 32767.0 * sensitivity;

        int red = (int)(rms * PWM_RANGE);
        int green = (int)((1 - rms) * PWM_RANGE);
        int blue = (int)((rms * 0.5) * PWM_RANGE);

        gpioPWM(GPIO_RED, red);
        gpioPWM(GPIO_GREEN, green);
        gpioPWM(GPIO_BLUE, blue);

        usleep(10000);
    }

    return EXIT_SUCCESS;
}

