    }

    if (gpioI2CWriteByteData(i2c_handle, TCS34725_ENABLE, TCS34725_ENABLE_POWERON) < 0) {
        fprintf(stderr, "Failed to write to I2C register\n");
        gpioI2CWriteClose(i2c_handle);
        gpioTerminate();
        fclose(file);
        return EXIT_FAILURE;
    }

    if (gpioI2CWriteByteData(i2c_handle, TCS34725_ATIME, TCS34725_ATIME_154MS) < 0) {
        fprintf(stderr, "Failed to write to I2C register\n");
        gpioI2CWriteClose(i2c_handle);
        gpioTerminate();
        fclose(file);
        return EXIT_FAILURE;
    }

    while (!stop) {
        uint16_t clear, red, green, blue;
        clear = red = green = blue = 0;

        if (gpioI2CReadByteData(i2c_handle, TCS34725_CDATAL) < 0) {
            fprintf(stderr, "Failed to read from I2C register\n");
            continue;
        }
        clear = gpioI2CReadByteData(i2c_handle, TCS34725_CDATAH) << 8;
        clear |= gpioI2CReadByteData(i2c_handle, TCS34725_CDATAL);

        if (gpioI2CReadByteData(i2c_handle, TCS34725_RDATAL) < 0) {
            fprintf(stderr, "Failed to read from I2C register\n");
            continue;
        }
        red = gpioI2CReadByteData(i2c_handle, TCS34725_RDATAH) << 8;
        red |= gpioI2CReadByteData(i2c_handle, TCS34725_RDATAL);

        if (gpioI2CReadByteData(i2c_handle, TCS34725_GDATAL) < 0) {
            fprintf(stderr, "Failed to read from I2C register\n");
            continue;
        }
        green = gpioI2CReadByteData(i2c_handle, TCS34725_GDATAH) << 8;
        green |= gpioI2CReadByteData(i2c_handle, TCS34725_GDATAL);

        if (gpioI2CReadByteData(i2c_handle, TCS34725_BDATAL) < 0) {
            fprintf(stderr, "Failed to read from I2C register\n");
            continue;
