    fclose(file);

    return EXIT_SUCCESS;
}

#include <stdio.h>
#include <stdlib.h>
#include <signal.h>
#include <gpiod.h>

#define SUNRISE 1
#define DAYTIME 2
#define SUNSET 3
#define NIGHTTIME 4

static int current_phase = NIGHTTIME;
static int relay_pins[] = {17, 27, 22, 23}; // BCM GPIO17, GPIO27, GPIO22, GPIO23
static struct gpiod_chip *chip;
static struct gpiod_line_bulk lines;

void cleanup_and_exit() {
    gpiod_line_set_value_bulk(&lines, 0);
    gpiod_line_release_bulk(&lines);
    gpiod_chip_close(chip);
    exit(0);
}

void handle_signal(int signum) {
    cleanup_and_exit();
}

int main() {
    struct sigaction action;
    action.sa_handler = handle_signal;
    sigemptyset(&action.sa_mask);
    action.sa_flags = 0;
    sigaction(SIGINT, &action, NULL);
    sigaction(SIGTERM, &action, NULL);

    chip = gpiod_chip_open_by_name("gpiochip0");
    if (!chip) {
        fprintf(stderr, "Failed to open GPIO chip\n");
        return EXIT_FAILURE;
    }

    gpiod_line_bulk_init(&lines);
    for (int i = 0; i < sizeof(relay_pins) / sizeof(relay_pins[0]); i++) {
        struct gpiod_line *line = gpiod_chip_get_line(chip, relay_pins[i]);
        if (!line) {
            fprintf(stderr, "Failed to get line for GPIO %d\n", relay_pins[i]);
            cleanup_and_exit();
        }
        gpiod_line_request_output(line, "sunrise_sunset_simulator", 0);
        gpiod_line_bulk_add(&lines, line);
    }

    while (1) {
        switch (current_phase) {
            case SUNRISE:
                // Simulate sunrise by gradually increasing the duty cycle
                for (int i = 0; i < 100; i++) {
                    gpiod_line_set_value_bulk(&lines, i / 100.0);
                    sleep(1);
                }
                current_phase = DAYTIME;
                break;
            case DAYTIME:
                // Stay in daytime for 6 hours
                sleep(6 * 60 * 60);
                current_phase = SUNSET;
                break;
            case SUNSET:
                // Simulate sunset by gradually decreasing the duty cycle
                for (int i = 100; i >= 0; i--) {
                    gpiod_line_set_value_bulk(&lines, i / 100.0);
                    sleep(1);
                }
                current_phase = NIGHTTIME;
                break;
            case NIGHTTIME:
                // Stay in nighttime for 14.4 hours
                sleep(14.4 * 60 * 60);
                current_phase = SUNRISE;
                break;
        }
    }

    cleanup_and_exit();
    return 0;
}

