#define MPU6050_ADDRESS 0x68
#define SAMPLE_RATE_DIVIDER 0x19
#define GYRO_CONFIGURATION 0x1B
#define PWR_MGMT_1 0x6B
#define GYRO_XOUT_H 0x43
#define GYRO_SENSITIVITY 131.0

volatile sig_atomic_t stop_requested = 0;

void signal_handler(int signum) {
    stop_requested = 1;
}

int main() {
    FILE *log_file;
    int i2c_handle;
    uint8_t buffer[6];
    int16_t raw_values[3];
    double angular_velocities[3];
    struct timespec ts;
    int reinit_attempts = 0;

    if (gpioInitialise() < 0) {
        fprintf(stderr, "Failed to initialize pigpio\n");
        return EXIT_FAILURE;
    }

    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    if ((log_file = fopen("gyro_log.csv", "w")) == NULL) {
        fprintf(stderr, "Failed to open log file\n");
        gpioTerminate();
        return EXIT_FAILURE;
    }

    fprintf(log_file, "timestamp,X_degps,Y_degps,Z_degps\n");

    if ((i2c_handle = i2cOpen(1, MPU6050_ADDRESS, 0)) < 0) {
        fprintf(stderr, "Failed to open I2C bus\n");
        fclose(log_file);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    i2cWriteByteData(i2c_handle, PWR_MGMT_1, 0x00);
    i2cWriteByteData(i2c_handle, SAMPLE_RATE_DIVIDER, 0x07);
    i2cWriteByteData(i2c_handle, GYRO_CONFIGURATION, 0x00);

    while (!stop_requested) {
        if (i2cReadI2CBlockData(i2c_handle, GYRO_XOUT_H, buffer, 6) != 6) {
            if (++reinit_attempts > 3) {
                fprintf(stderr, "Failed to read from MPU6050\n");
                break;
            } else {
                i2cWriteByteData(i2c_handle, PWR_MGMT_1, 0x00);
                i2cWriteByteData(i2c_handle, SAMPLE_RATE_DIVIDER, 0x07);
                i2cWriteByteData(i2c_handle, GYRO_CONFIGURATION, 0x00);
                continue;
            }
        }

        reinit_attempts = 0;

        for (int i = 0; i < 3; i++) {
            raw_values[i] = (buffer[i * 2] << 8) | buffer[i * 2 + 1];
            angular_velocities[i] = raw_values[i] / GYRO_SENSITIVITY;
        }

        clock_gettime(CLOCK_REALTIME, &ts);
        fprintf(log_file, "%ld.%03ld,%f,%f,%f\n", ts.tv_sec, ts.tv_nsec / 1e6, angular_velocities[0], angular_velocities[1], angular_velocities[2]);

        usleep(10000);
    }

    fclose(log_file);
    i2cClose(i2c_handle);
    gpioTerminate();

    return EXIT_SUCCESS;
}

