static void signal_handler(int signum) {
    for (int i = 0; i < NUM_ZONES; i++) {
        gpioWrite(RELAY_PIN(i), 1); // Drive all relays HIGH
    }
    gpioTerminate(); // Terminate pigpio
    exit(signum);
}

int main() {
    int moisture[NUM_ZONES];
    FILE *log_file;
    time_t timestamp;

    signal(SIGINT, signal_handler); // Install signal handler

    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialization failed\n");
        return EXIT_FAILURE;
    }

    log_file = fopen("irrigation_log.txt", "w");
    if (!log_file) {
        fprintf(stderr, "Failed to open log file\n");
        gpioTerminate();
        return EXIT_FAILURE;
    }

    for (int i = 0; i < NUM_ZONES; i++) {
        if (gpioSetMode(RELAY_PIN(i), PI_OUTPUT) < 0) {
            fprintf(stderr, "Failed to set GPIO mode for relay %d\n", i);
            goto cleanup;
        }
        gpioWrite(RELAY_PIN(i), 1); // Initially drive all relays HIGH
    }

    while (1) {
        timestamp = time(NULL);
        for (int i = 0; i < NUM_ZONES; i++) {
            moisture[i] = rand() % 101; // Simulate moisture sensor reading
            if (moisture[i] < 30) {
                gpioWrite(RELAY_PIN(i), 0); // Drive relay LOW to activate zone
            } else {
                gpioWrite(RELAY_PIN(i), 1); // Drive relay HIGH to deactivate zone
            }
