        sleep(5); // Wait for 5 seconds
    }

cleanup:
    fclose(log_file);
    for (int i = 0; i < NUM_ZONES; i++) {
        gpioWrite(RELAY_PIN(i), 1); // Drive all relays HIGH
    }
    gpioTerminate(); // Terminate pigpio
    return EXIT_FAILURE;
}

