    uint8_t data_format_value = 0x0B;
    uint8_t power_ctl_value = 0x08;

    if (i2cWriteByteData(i2c_handle, data_format_reg, data_format_value) < 0) {
        fprintf(stderr, "Failed to write to DATA_FORMAT register\n");
        goto cleanup;
    }

    if (i2cWriteByteData(i2c_handle, power_ctl_reg, power_ctl_value) < 0) {
        fprintf(stderr, "Failed to write to POWER_CTL register\n");
        goto cleanup;
    }

    uint8_t reg = 0x32;
    int16_t x, y, z;
    int freefall_count = 0;
    time_t last_freefall_time = 0;

    while (!stop) {
        if (i2cReadByteData(i2c_handle, reg, (uint8_t*)&x, 2) < 0) {
            fprintf(stderr, "Failed to read X axis data\n");
            continue;
        }

        if (i2cReadByteData(i2c_handle, reg + 2, (uint8_t*)&y, 2) < 0) {
            fprintf(stderr, "Failed to read Y axis data\n");
            continue;
        }

        if (i2cReadByteData(i2c_handle, reg + 4, (uint8_t*)&z, 2) < 0) {
            fprintf(stderr, "Failed to read Z axis data\n");
            continue;
        }

        x = (int16_t)((x << 8) | (x >> 8));
        y = (int16_t)((y << 8) | (y >> 8));
        z = (int16_t)((z << 8) | (z >> 8));

        double ax = x / SCALE_FACTOR;
        double ay = y / SCALE_FACTOR;
        double az = z / SCALE_FACTOR;

        if (fabs(ax) < FREEFALL_THRESHOLD && fabs(ay) < FREEFALL_THRESHOLD && fabs(az) < FREEFALL_THRESHOLD) {
            freefall_count++;

            if (freefall_count == 1) {
                last_freefall_time = time(NULL);
            } else if (difftime(time(NULL), last_freefall_time) > FREEFALL_DURATION) {
                freefall_count = 0;
            } else if (freefall_count == 2) {
                gpioSetMode(GPIO_ALARM, PI_OUTPUT);
                gpioWrite(GPIO_ALARM, PI_HIGH);
                sleep(5);
                gpioWrite(GPIO_ALARM, PI_LOW);

                FILE *log_file = fopen(FREEFALL_LOG_FILE, "a");
                if (log_file == NULL) {
                    fprintf(stderr, "Failed to open log file\n");
                    continue;
                }

                char timestamp[20];
                strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", localtime(&last_freefall_time));
                fprintf(log_file, "%s,%0.3f,%0.3f,%0.3f\n", timestamp, ax, ay, az);
                fclose(log_file);

                freefall_count = 0;
            }
        } else {
            freefall_count = 0;
        }
    }

cleanup:
    i2cClose(i2c_handle);
    gpioTerminate();
    return EXIT_SUCCESS;
}

#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <unistd.h>
#include <signal.h>
#include <pigpio.h>
#include <pthread.h>

#define TRIG 4
#define ECHO 18
#define TRIG_PULSE_WIDTH 10
#define MAX_DISTANCE 23200
#define TIMEOUT 100000000 // 100 ms in nanoseconds
#define LOG_FILE "distance_log.txt"

volatile sig_atomic_t running = 1;
pthread_mutex_t mutex = PTHREAD_MUTEX_INITIALIZER;
uint32_t last_trigger = 0;
uint32_t last_echo = 0;

void stop(int signum) {
    running = 0;
}

void trigger_callback(int gpio, uint32_t tick, void *userdata) {
    pthread_mutex_lock(&mutex);
    last_trigger = tick;
    pthread_mutex_unlock(&mutex);
}

void echo_callback(int gpio, uint32_t tick, void *userdata) {
    pthread_mutex_lock(&mutex);
    last_echo = tick;
    pthread_mutex_unlock(&mutex);
}

int main() {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Failed to initialize pigpio\n");
        return EXIT_FAILURE;
    }

    signal(SIGINT, stop);

    if (gpioSetMode(TRIG, PI_OUTPUT) < 0) {
        fprintf(stderr, "Failed to set TRIG GPIO mode\n");
        gpioTerminate();
        return EXIT_FAILURE;
    }

    if (gpioSetMode(ECHO, PI_INPUT) < 0) {
        fprintf(stderr, "Failed to set ECHO GPIO mode\n");
        gpioTerminate();
        return EXIT_FAILURE;
    }

    if (gpioSetAlertFunc(ECHO, echo_callback, NULL) < 0) {
        fprintf(stderr, "Failed to set ECHO GPIO alert function\n");
        gpioTerminate();
        return EXIT_FAILURE;
    }

    FILE *log_file = fopen(LOG_FILE, "w");
    if (log_file == NULL) {
        fprintf(stderr, "Failed to open log file\n");
        gpioTerminate();
        return EXIT_FAILURE;
    }

    while (running) {
        gpioTrigger(TRIG, TRIG_PULSE_WIDTH, 0);

        pthread_mutex_lock(&mutex);
        uint32_t trigger = last_trigger;
        uint32_t echo = last_echo;
        pthread_mutex_unlock(&mutex);

        if (echo < trigger || echo - trigger > MAX_DISTANCE) {
            continue;
        }

        uint32_t duration = echo - trigger;
        uint64_t timestamp = gpioTickToNano(trigger);

        fprintf(log_file, "%llu,%d\n", timestamp, duration / 58);

        usleep(200000); // Wait for 200 ms
    }

    fclose(log_file);
    gpioTerminate();
    return EXIT_SUCCESS;
}

#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <signal.h>
#include <pigpio.h>
#include <errno.h>

#define I2C_BUS 1
#define I2C_ADDRESS 0x18
#define ACCEL_SENSITIVITY 16384.0
#define FREEFALL_THRESHOLD 0.2
#define IMPACT_THRESHOLD 1.5
#define BUZZER_GPIO 17
#define I2C_RETRIES 3

volatile sig_atomic_t stop = 0;

void handle_sigint(int signum) {
    stop = 1;
}

int main(int argc, char *argv[]) {
    float freefall_threshold = FREEFALL_THRESHOLD;
    float impact_threshold = IMPACT_THRESHOLD;
    int i2c_retries = I2C_RETRIES;

    if (argc > 1) {
        freefall_threshold = atof(argv[1]);
    }
    if (argc > 2) {
        impact_threshold = atof(argv[2]);
    }
    if (argc > 3) {
        i2c_retries = atoi(argv[3]);
    }

    if (gpioInitialise() < 0) {
        fprintf(stderr, "Failed to initialize pigpio: %s\n", strerror(errno));
        return EXIT_FAILURE;
    }

    struct sigaction action;
    memset(&action, 0, sizeof(action));
    action.sa_handler = handle_sigint;
    sigaction(SIGINT, &action, NULL);

    int i2c_handle = i2cOpen(I2C_BUS, I2C_ADDRESS, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Failed to open I2C bus: %s\n", strerror(errno));
        gpioTerminate();
        return EXIT_FAILURE;
    }

    uint8_t ctrl_reg1 = 0x77; // 100 Hz data rate
    uint8_t ctrl_reg4 = 0x00; // ±2g full scale
    if (i2cWriteByteData(i2c_handle, 0x20, ctrl_reg1) < 0 || i2cWriteByteData(i2c_handle, 0x23, ctrl_reg4) < 0) {
        fprintf(stderr, "Failed to write to LIS3DH: %s\n", strerror(errno));
        i2cClose(i2c_handle);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    gpioSetMode(BUZZER_GPIO, PI_OUTPUT);

    float last_accel[3] = {0, 0, 0};
    float current_accel[3] = {0, 0, 0};
    int buzzer_active = 0;

    while (!stop) {
        for (int i = 0; i < 3; i++) {
            int16_t accel_raw = i2cReadWordData(i2c_handle, 0x28 + 2 * i);
            if (accel_raw < 0) {
                fprintf(stderr, "Failed to read from LIS3DH: %s\n", strerror(errno));
                i2cClose(i2c_handle);
                gpioTerminate();
                return EXIT_FAILURE;
            }
            current_accel[i] = (float)accel_raw / ACCEL_SENSITIVITY;
        }

        float accel_magnitude = sqrt(current_accel[0] * current_accel[0] + current_accel[1] * current_accel[1] + current_accel[2] * current_accel[2]);

        if (accel_magnitude < freefall_threshold && buzzer_active) {
            buzzer_active = 0;
            gpioWrite(BUZZER_GPIO, PI_OFF);
        } else if (accel_magnitude > impact_threshold && !buzzer_active) {
            buzzer_active = 1;
            gpioWrite(BUZZER_GPIO, PI_ON);
            sleep(1);
            gpioWrite(BUZZER_GPIO, PI_OFF);
        }

        last_accel[0] = current_accel[0];
        last_accel[1] = current_accel[1];
        last_accel[2] = current_accel[2];
    }

    gpioWrite(BUZZER_GPIO, PI_OFF);
    gpioTerminate();
    i2cClose(i2c_handle);

    return EXIT_SUCCESS;
}

#include <stdio.h>
#include <stdlib.h>
#include <signal.h>
#include <pigpio.h>

#define MOTOR1_IN1 4
#define MOTOR1_IN2 17
#define MOTOR1_IN3 27
#define MOTOR1_IN4 22
#define MOTOR2_IN1 5
#define MOTOR2_IN2 6
#define MOTOR2_IN3 13
#define MOTOR2_IN4 19
#define STEPS_PER_REV 2048
#define STEP_DELAY 1000
#define STEPS_PER_MM 10

volatile sig_atomic_t stop = 0;

void handle_sigint(int signum) {
    stop = 1;
}

void set_motor_pins(int motor, int in1, int in2, int in3, int in4) {
    gpioSetMode(motor, in1, PI_OUTPUT);
    gpioSetMode(motor, in2, PI_OUTPUT);
    gpioSetMode(motor, in3, PI_OUTPUT);
    gpioSetMode(motor, in4, PI_OUTPUT);
}

void step_motor(int motor, int in1, int in2, int in3, int in4) {
    gpioWrite(motor, in1, PI_HIGH);
    gpioWrite(motor, in2, PI_LOW);
    gpioWrite(motor, in3, PI_LOW);
    gpioWrite(motor, in4, PI_LOW);
    gpioDelay(STEP_DELAY);
    gpioWrite(motor, in1, PI_LOW);
    gpioWrite(motor, in2, PI_HIGH);
    gpioWrite(motor, in3, PI_LOW);
    gpioWrite(motor, in4, PI_LOW);
    gpioDelay(STEP_DELAY);
    gpioWrite(motor, in1, PI_LOW);
    gpioWrite(motor, in2, PI_LOW);
    gpioWrite(motor, in3, PI_HIGH);
    gpioWrite(motor, in4, PI_LOW);
    gpioDelay(STEP_DELAY);
    gpioWrite(motor, in1, PI_LOW);
    gpioWrite(motor, in2, PI_LOW);
    gpioWrite(motor, in3, PI_LOW);
    gpioWrite(motor, in4, PI_HIGH);
    gpioDelay(STEP_DELAY);
}

int main() {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialization failed\n");
        return EXIT_FAILURE;
    }

    signal(SIGINT, handle_sigint);

    set_motor_pins(MOTOR1_IN1, MOTOR1_IN2, MOTOR1_IN3, MOTOR1_IN4);
    set_motor_pins(MOTOR2_IN1, MOTOR2_IN2, MOTOR2_IN3, MOTOR2_IN4);

    int steps = STEPS_PER_REV / STEPS_PER_MM;
    for (int i = 0; i < 4 && !stop; i++) {
        for (int j = 0; j < steps && !stop; j++) {
            step_motor(MOTOR1_IN1, MOTOR1_IN2, MOTOR1_IN3, MOTOR1_IN4);
            step_motor(MOTOR2_IN1, MOTOR2_IN2, MOTOR2_IN3, MOTOR2_IN4);
        }
        for (int j = 0; j < steps && !stop; j++) {
            step_motor(MOTOR1_IN1, MOTOR1_IN2, MOTOR1_IN3, MOTOR1_IN4);
            step_motor(MOTOR2_IN1, MOTOR2_IN2, MOTOR2_IN3, MOTOR2_IN4);
        }
    }

    gpioTerminate();
    return EXIT_SUCCESS;
}

#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <signal.h>
#include <time.h>
#include <pigpio.h>

#define DEFAULT_THRESHOLD 2.0
#define DEFAULT_ADDRESS 0x18
#define LOG_FILE "/var/log/high_acceleration.log"

static volatile sig_atomic_t stop = 0;
static int i2c_handle = -1;
static int lis3dh_address = DEFAULT_ADDRESS;
static float threshold = DEFAULT_THRESHOLD;

void sigint_handler(int signum) {
    stop = 1;
}

int main(int argc, char *argv[]) {
    int opt;
    while ((opt = getopt(argc, argv, "a:t:")) != -1) {
        switch (opt) {
            case 'a':
                lis3dh_address = (int)strtol(optarg, NULL, 16);
                if (lis3dh_address < 0x08 || lis3dh_address > 0x77) {
                    fprintf(stderr, "Invalid I2C address: %s\n", optarg);
                    return EXIT_FAILURE;
                }
                break;
            case 't':
                threshold = strtof(optarg, NULL);
                if (threshold <= 0) {
                    fprintf(stderr, "Invalid threshold: %s\n", optarg);
                    return EXIT_FAILURE;
                }
                break;
            default:
                fprintf(stderr, "Usage: %s [-a I2C_ADDRESS] [-t THRESHOLD]\n", argv[0]);
                return EXIT_FAILURE;
        }
    }

    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialization failed\n");
        return EXIT_FAILURE;
    }

    signal(SIGINT, sigint_handler);

    i2c_handle = i2cOpen(1, lis3dh_address, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Failed to open I2C device at address 0x%02X\n", lis3dh_address);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    if (i2cWriteByteData(i2c_handle, 0x20, 0x57) < 0) {
        fprintf(stderr, "Failed to write to CTRL_REG1\n");
        goto cleanup;
    }

    if (i2cWriteByteData(i2c_handle, 0x23, 0x88) < 0) {
        fprintf(stderr, "Failed to write to CTRL_REG4\n");
        goto cleanup;
    }

    FILE *log_file = fopen(LOG_FILE, "a");
    if (!log_file) {
        fprintf(stderr, "Failed to open log file\n");
        goto cleanup;
    }

    while (!stop) {
        uint8_t data[6];
        if (i2cReadI2CBlockData(i2c_handle, 0x28, data, 6) < 0) {
            fprintf(stderr, "Failed to read from LIS3DH\n");
            memset(data, 0, sizeof(data));
        }

        int16_t x = (data[1] << 8) | data[0];
        int16_t y = (data[3] << 8) | data[2];
        int16_t z = (data[5] << 8) | data[4];

        float g_x = x * 0.0009765625;
        float g_y = y * 0.0009765625;
        float g_z = z * 0.0009765625;

        if (fabs(g_x) > threshold || fabs(g_y) > threshold || fabs(g_z) > threshold) {
            time_t now = time(NULL);
            struct tm *t = localtime(&now);
            fprintf(log_file, "%s: X: %.2f, Y: %.2f, Z: %.2f\n", asctime(t), g_x, g_y, g_z);
            fflush(log_file);
            system("sudo shutdown -h now");
        }

        sleep(10);
    }

    fclose(log_file);

cleanup:
    i2cClose(i2c_handle);
    gpioTerminate();
    return EXIT_SUCCESS;
}

#include <stdio.h>
#include <stdlib.h>
#include <signal.h>
#include <stdbool.h>
#include <libgpiod.h>

#define LEFT_PIN 4
#define CENTER_PIN 17
#define RIGHT_PIN 27
#define ALERT_PIN 22

#define BUF_SIZE 5

gpiod_chip *chip;
gpiod_line *lines[4];
gpiod_line_event event;
uint8_t buffer[BUF_SIZE] = {0};
int buffer_head = 0;

void cleanup() {
    for (int i = 0; i < 4; i++) {
        gpiod_line_release(lines[i]);
    }
    gpiod_chip_close(chip);
}

void sig_handler(int signum) {
    cleanup();
    exit(signum);
}

void check_error(int error, const char *msg) {
    if (error < 0) {
        fprintf(stderr, "%s: %s\n", msg, strerror(-error));
        cleanup();
        exit(EXIT_FAILURE);
    }
}

int main() {
    struct sigaction action;
    action.sa_handler = sig_handler;
    sigemptyset(&action.sa_mask);
    action.sa_flags = 0;
    sigaction(SIGINT, &action, NULL);
    sigaction(SIGTERM, &action, NULL);

    chip = gpiod_chip_open("/dev/gpiochip0");
    check_error(chip ? 0 : -1, "Failed to open GPIO chip");

    lines[0] = gpiod_chip_get_line(chip, LEFT_PIN);
    lines[1] = gpiod_chip_get_line(chip, CENTER_PIN);
    lines[2] = gpiod_chip_get_line(chip, RIGHT_PIN);
    lines[3] = gpiod_chip_get_line(chip, ALERT_PIN);

    for (int i = 0; i < 4; i++) {
        check_error(lines[i] ? 0 : -1, "Failed to get line");
    }

    gpiod_line_request_input(lines[0], "line_sensor");
    gpiod_line_request_input(lines[1], "line_sensor");
    gpiod_line_request_input(lines[2], "line_sensor");
    gpiod_line_request_output(lines[3], "alert_led");

    while (true) {
        for (int i = 0; i < 3; i++) {
            gpiod_line_event_wait(lines[i], 0);
            gpiod_line_event_read(lines[i], &event);
            buffer[buffer_head] = event.level;
            buffer_head = (buffer_head + 1) % BUF_SIZE;
        }

        if (buffer[0] == 1 && buffer[1] == 1 && buffer[2] == 1 && buffer[3] == 1 && buffer[4] == 1) {
            gpiod_line_set_value(lines[3], 1);
            sleep(2);
            gpiod_line_set_value(lines[3], 0);
        }
    }

    cleanup();
    return 0;
}

