#define SI7210_ADDRESS 0x30
#define SI7210_REG_C1 0xC1
#define SI7210_REG_C0 0xC0
#define RELAY_GPIO 17
#define FIELD_THRESHOLD 500 // 5.0 mT
#define POLL_ATTEMPTS 50
#define I2C_BUS 1

volatile sig_atomic_t stop = 0;

void signal_handler(int signum) {
    stop = 1;
}

int main() {
    FILE *log_file;
    int i2c_handle;
    int relay_state = 0;
    int field_raw;
    int field_mT_x100;
    int poll_attempt;
    struct timespec sleep_time = {0, 100000000}; // 100 ms

    signal(SIGINT, signal_handler);

    if ((i2c_handle = i2cOpen(I2C_BUS, SI7210_ADDRESS, 0)) < 0) {
        printf("Failed to open I2C bus: %d\n", i2c_handle);
        return EXIT_FAILURE;
    }

    if (gpioInitialise() < 0) {
        printf("Failed to initialize pigpio\n");
        i2cClose(i2c_handle);
        return EXIT_FAILURE;
    }

    gpioSetMode(RELAY_GPIO, PI_OUTPUT);

    log_file = fopen("magnetic_events.txt", "w");
    if (log_file == NULL) {
        printf("Failed to open log file\n");
        gpioTerminate();
        i2cClose(i2c_handle);
        return EXIT_FAILURE;
    }

    while (!stop) {
        // Start a conversion
        if (i2cWriteByteData(i2c_handle, SI7210_REG_C1, 0x01) < 0) {
            printf("Failed to write to SI7210_REG_C1\n");
            continue;
        }

        // Poll until conversion is complete
        for (poll_attempt = 0; poll_attempt < POLL_ATTEMPTS; poll_attempt++) {
            if (i2cReadByteData(i2c_handle, SI7210_REG_C1) < 0) {
                printf("Failed to read from SI7210_REG_C1\n");
                continue;
            }

            if (i2cReadByteData(i2c_handle, SI7210_REG_C1) == 0) {
                break;
            }

            nanosleep(&sleep_time, NULL);
        }

        if (poll_attempt == POLL_ATTEMPTS) {
            printf("Timeout waiting for conversion to complete\n");
            continue;
        }

        // Read the raw field data
        if (i2cReadByteData(i2c_handle, SI7210_REG_C0) < 0) {
            printf("Failed to read from SI7210_REG_C0\n");
            continue;
        }

        if (i2cReadByteData(i2c_handle, SI7210_REG_C0 + 1) < 0) {
            printf("Failed to read from SI7210_REG_C0 + 1\n");
            continue;
        }

        field_raw = (i2cReadByteData(i2c_handle, SI7210_REG_C0 + 1) << 8) | i2cReadByteData(i2c_handle, SI7210_REG_C0);
        field_mT_x100 = field_raw * 25 / 1000;

        // Check if the field strength exceeds the threshold
        if (field_mT_x100 > FIELD_THRESHOLD * 100) {
            if (relay_state == 0) {
                gpioWrite(RELAY_GPIO, 1);
                relay_state = 1;
                fprintf(log_file, "%ld: Relay activated\n", time(NULL));
            }
        } else {
            if (relay_state == 1) {
                gpioWrite(RELAY_GPIO, 0);
                relay_state = 0;
                fprintf(log_file, "%ld: Relay deactivated\n", time(NULL));
            }
        }

        fprintf(log_file, "%ld: Field raw: %d, Field mT: %d\n", time(NULL), field_raw, field_mT_x100);
    }

    fclose(log_file);
    gpioTerminate();
    i2cClose(i2c_handle);

    return EXIT_SUCCESS;
}

