        exit(EXIT_FAILURE);
    }

    if (gpioSetMode(RELAY_PIN, PI_OUTPUT) < 0) {
        fprintf(stderr, "failed to set GPIO mode\n");
        exit(EXIT_FAILURE);
    }

    while (1) {
        if ((client_fd = accept(server_fd, (struct sockaddr *)&client_addr, &client_addr_len)) < 0) {
            perror("accept failed");
            continue;
        }

        bytes_read = read(client_fd, buffer, BUFFER_SIZE - 1);
        if (bytes_read < 0) {
            perror("read failed");
            close(client_fd);
            continue;
        }

        buffer[bytes_read] = '\0';

        if (strcasecmp(buffer, "ON") == 0) {
            if (relay_status == 0) {
                if (gpioWrite(RELAY_PIN, 1) < 0) {
                    fprintf(stderr, "failed to write GPIO\n");
                } else {
                    relay_status = 1;
                    time_t now = time(NULL);
                    char *time_str = ctime(&now);
                    time_str[strcspn(time_str, "\n")] = 0;
                    printf("Relay turned ON at %s\n", time_str);
                }
            }
        } else if (strcasecmp(buffer, "OFF") == 0) {
            if (relay_status == 1) {
                if (gpioWrite(RELAY_PIN, 0) < 0) {
                    fprintf(stderr, "failed to write GPIO\n");
                } else {
                    relay_status = 0;
                    time_t now = time(NULL);
                    char *time_str = ctime(&now);
                    time_str[strcspn(time_str, "\n")] = 0;
                    printf("Relay turned OFF at %s\n", time_str);
                }
            }
        } else {
            printf("Invalid command received: %s\n", buffer);
        }

        close(client_fd);
    }

    gpioTerminate();
    close(server_fd);

    return 0;
}

#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <unistd.h>
#include <signal.h>
#include <stdint.h>
#include <pigpio.h>

#define SLF3S_START_CMD {0x36, 0x08}
#define SLF3S_CRC_POLY 0x31
#define SLF3S_CRC_INIT 0xFF
#define SLF3S_SCALE_FACTOR 1.0/1500.0

volatile sig_atomic_t stop_requested = 0;

void signal_handler(int signum) {
    stop_requested = 1;
}

int main() {
    int i2c_handles[2];
    int i2c_addresses[2] = {0x08, 0x09};
    int gpio = 18;
    FILE *log_file;
    uint8_t start_cmd[2] = SLF3S_START_CMD;
    uint8_t read_buffer[3];
    int16_t raw_values[2];
    float flow_rates[2];
    int i;

    if (gpioInitialise() < 0) {
        fprintf(stderr, "Failed to initialize pigpio\n");
        return EXIT_FAILURE;
    }

    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    log_file = fopen("flow_log.txt", "a");
    if (!log_file) {
        fprintf(stderr, "Failed to open log file\n");
        gpioTerminate();
        return EXIT_FAILURE;
    }

    for (i = 0; i < 2; i++) {
        i2c_handles[i] = i2cOpen(1, i2c_addresses[i], 0);
        if (i2c_handles[i] < 0) {
            fprintf(stderr, "Failed to open I2C handle for sensor %d\n", i + 1);
            goto cleanup;
        }
        if (i2cWriteByteData(i2c_handles[i], 0, start_cmd[0]) < 0 ||
            i2cWriteByteData(i2c_handles[i], 1, start_cmd[1]) < 0) {
            fprintf(stderr, "Failed to send start command to sensor %d\n", i + 1);
            goto cleanup;
        }
    }

    gpioSetMode(gpio, PI_OUTPUT);
    gpioWrite(gpio, PI_LOW);

    while (!stop_requested) {
        for (i = 0; i < 2; i++) {
            if (i2cReadByteData(i2c_handles[i], 0, read_buffer, 3) < 0) {
                fprintf(stderr, "Failed to read data from sensor %d\n", i + 1);
                continue;
            }
            if (read_buffer[2] != ((uint8_t) (read_buffer[0] ^ read_buffer[1] ^ SLF3S_CRC_INIT) & 0xFF)) {
                fprintf(stderr, "CRC mismatch for sensor %d\n", i + 1);
                continue;
            }
            raw_values[i] = (read_buffer[0] << 8) | read_buffer[1];
            flow_rates[i] = raw_values[i] * SLF3S_SCALE_FACTOR;
        }

        if (flow_rates[0] < 5.0 && flow_rates[1] < 5.0) {
            gpioWrite(gpio, PI_HIGH);
        } else {
            gpioWrite(gpio, PI_LOW);
        }

        for (i = 0; i < 2; i++) {
            fprintf(log_file, "Sensor %d: %f ml/min\n", i + 1, flow_rates[i]);
        }
        fflush(log_file);

        usleep(100000);
    }

    printf("Exiting...\n");

cleanup:
    gpioWrite(gpio, PI_LOW);
    for (i = 0; i < 2; i++) {
        if (i2c_handles[i] >= 0) {
            i2cClose(i2c_handles[i]);
        }
    }
    fclose(log_file);
    gpioTerminate();

    return EXIT_SUCCESS;
}

#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <syslog.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

#define RAIN_SENSOR_GPIO 17
#define MOTOR_ENA_GPIO 22
#define MOTOR_IN1_GPIO 23
#define MOTOR_IN2_GPIO 24
#define POLL_INTERVAL 200000
#define MOTOR_RUN_DURATION 5000000
#define DRY_THRESHOLD 3

volatile sig_atomic_t running = 1;
int rain_sensor_fd = -1;
int motor_ena_fd = -1;
int motor_in1_fd = -1;
int motor_in2_fd = -1;
int dry_count = 0;

void signal_handler(int signum) {
    running = 0;
}

void log_message(int priority, const char *message) {
    syslog(priority, "%s", message);
}

void close_resources() {
    if (rain_sensor_fd != -1) {
        gpioTerminate();
    }
}

int main() {
    openlog("rain_window", LOG_PID, LOG_USER);

    if (gpioInitialise() < 0) {
        log_message(LOG_ERR, "Failed to initialize pigpio");
        return EXIT_FAILURE;
    }

    atexit(close_resources);

    struct sigaction action;
    memset(&action, 0, sizeof(struct sigaction));
    action.sa_handler = signal_handler;
    sigaction(SIGINT, &action, NULL);
    sigaction(SIGTERM, &action, NULL);

    log_message(LOG_INFO, "Starting rain window controller");

    rain_sensor_fd = gpioOpen(RAIN_SENSOR_GPIO, PI_INPUT, PI_PUD_UP);
    if (rain_sensor_fd < 0) {
        log_message(LOG_ERR, "Failed to open rain sensor GPIO");
        return EXIT_FAILURE;
    }

    motor_ena_fd = gpioOpen(MOTOR_ENA_GPIO, PI_OUTPUT, 0);
    if (motor_ena_fd < 0) {
        log_message(LOG_ERR, "Failed to open motor ENA GPIO");
        return EXIT_FAILURE;
    }

    motor_in1_fd = gpioOpen(MOTOR_IN1_GPIO, PI_OUTPUT, 0);
    if (motor_in1_fd < 0) {
        log_message(LOG_ERR, "Failed to open motor IN1 GPIO");
        return EXIT_FAILURE;
    }

    motor_in2_fd = gpioOpen(MOTOR_IN2_GPIO, PI_OUTPUT, 0);
    if (motor_in2_fd < 0) {
        log_message(LOG_ERR, "Failed to open motor IN2 GPIO");
        return EXIT_FAILURE;
    }

    while (running) {
        int level = gpioRead(rain_sensor_fd);
        if (level == PI_LOW) {
            dry_count = 0;
            log_message(LOG_INFO, "Rain detected, motor will not run");
        } else {
            dry_count++;
            if (dry_count >= DRY_THRESHOLD) {
                log_message(LOG_INFO, "Motor starting");
                gpioWrite(motor_ena_fd, PI_HIGH);
                gpioWrite(motor_in1_fd, PI_HIGH);
                gpioWrite(motor_in2_fd, PI_LOW);
                gpioDelay(MOTOR_RUN_DURATION);
                gpioWrite(motor_ena_fd, PI_LOW);
                gpioWrite(motor_in1_fd, PI_LOW);
                gpioWrite(motor_in2_fd, PI_LOW);
                log_message(LOG_INFO, "Motor stopped");
                dry_count = 0;
            }
        }
        gpioDelay(POLL_INTERVAL);
    }

    log_message(LOG_INFO, "Shutting down rain window controller");

    closelog();

    return EXIT_SUCCESS;
}

#include <stdio.h>
