#define DEBOUNCE_TIME 200000 // 200ms

volatile sig_atomic_t stop_requested = 0;

void sig_handler(int signum) {
    stop_requested = 1;
}

int main() {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialization failed\n");
        return 1;
    }

    signal(SIGINT, sig_handler);
    signal(SIGTERM, sig_handler);

    gpioSetMode(SERVO_PIN, PI_OUTPUT);
    gpioSetPullUpDown(BUTTON_PIN_1, PI_PUD_UP);
    gpioSetPullUpDown(BUTTON_PIN_2, PI_PUD_UP);

    while (!stop_requested) {
        if (gpioGetTickCount() - gpioGetEvtTime(BUTTON_PIN_1) > DEBOUNCE_TIME && gpioRead(BUTTON_PIN_1) == 0) {
            printf("Locking the door\n");
            if (gpioServo(SERVO_PIN, 2000) != 0) {
                fprintf(stderr, "Failed to set servo to locked position\n");
