        if (gpioGetTickCount() - gpioGetEvtTime(BUTTON_PIN_2) > DEBOUNCE_TIME && gpioRead(BUTTON_PIN_2) == 0) {
            printf("Unlocking the door\n");
            if (gpioServo(SERVO_PIN, 1000) != 0) {
                fprintf(stderr, "Failed to set servo to unlocked position\n");
