#define MOTION_PIN 4
#define FLOODLIGHT_PIN 17
#define LOG_FILE "security_log.txt"
#define ACTIVATION_DURATION 60

static int floodlight_on = 0;
static FILE *log_file = NULL;

void log_event(const char *event, const char *timestamp, int duration) {
    if (log_file) {
        fprintf(log_file, "%s: %s", event, timestamp);
        if (duration >= 0) {
            fprintf(log_file, " (Duration: %d seconds)\n", duration);
        } else {
            fprintf(log_file, "\n");
        }
        fflush(log_file);
    }
}

void sig_handler(int signum) {
    if (floodlight_on) {
        gpioWrite(FLOODLIGHT_PIN, 0);
        log_event("Deactivated", NULL, -1);
    }
    if (log_file) {
        fclose(log_file);
    }
    gpioTerminate();
    exit(0);
}

int main() {
    struct timespec sleep_time = {0, 100000000}; // 100 ms
    struct timespec remaining_time;
    struct tm *time_info;
    char timestamp[20];
    int motion_status, prev_motion_status = 0;
    int start_time, end_time, duration;

    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialization failed\n");
        return 1;
    }

    if ((log_file = fopen(LOG_FILE, "a")) == NULL) {
        fprintf(stderr, "Failed to open log file\n");
        gpioTerminate();
        return 1;
    }

    signal(SIGINT, sig_handler);
    signal(SIGTERM, sig_handler);

    gpioSetMode(MOTION_PIN, PI_INPUT);
    gpioSetMode(FLOODLIGHT_PIN, PI_OUTPUT);

    while (1) {
        motion_status = gpioRead(MOTION_PIN);

        if (motion_status == 1 && prev_motion_status == 0) {
            if (!floodlight_on) {
                gpioWrite(FLOODLIGHT_PIN, 1);
                floodlight_on = 1;
                time(&start_time);
                log_event("Activated", ctime_r(&start_time, timestamp), -1);
            }
        } else if (motion_status == 0 && prev_motion_status == 1) {
            if (floodlight_on) {
                gpioWrite(FLOODLIGHT_PIN, 0);
                floodlight_on = 0;
                time(&end_time);
                duration = end_time - start_time;
                log_event("Deactivated", ctime_r(&end_time, timestamp), duration);
            }
        }

        prev_motion_status = motion_status;

        nanosleep(&sleep_time, &remaining_time);
    }

    return 0;
}

