#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <unistd.h>
#include <sys/socket.h>
#include <sys/types.h>
#include <netinet/in.h>
#include <arpa/inet.h>
#include <syslog.h>
#include <time.h>
#include <gpiod.h>
#include <pthread.h>
#include <signal.h>
#include <stdarg.h>

#define GPIO_SERVO 17
#define GPIO_PIR 4
#define SERVO_MIN 1000
#define SERVO_MAX 2000
#define SERVO_FREQ 50
#define PIR_DEBOUNCE 2

static int running = 1;
static int sockfd;
static pthread_t pwm_thread;
static gpiod_line *servo_line;
static gpiod_line *pir_line;
static FILE *logfile;

void log_message(int priority, const char *format, ...) {
    va_list args;
    time_t now = time(NULL);
    struct tm *t = localtime(&now);
    char timestamp[20];
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%dT%H:%M:%S", t);
    fprintf(logfile, "[%s] ", timestamp);
    va_start(args, format);
    vfprintf(logfile, format, args);
    va_end(args);
    if (priority == LOG_USER) {
        vsyslog(priority, format, args);
    }
    fprintf(logfile, "\n");
    fflush(logfile);
}

void *pwm_thread_func(void *arg) {
    while (running) {
        gpiod_line_set_value(servo_line, 1);
        usleep(SERVO_MIN);
        gpiod_line_set_value(servo_line, 0);
        usleep(SERVO_MAX - SERVO_MIN);
    }
    return NULL;
}

void handle_sigint(int signum) {
    running = 0;
    pthread_cancel(pwm_thread);
    pthread_join(pwm_thread, NULL);
    gpiod_line_release(servo_line);
    gpiod_line_release(pir_line);
    close(sockfd);
    fclose(logfile);
    closelog();
    exit(0);
}

int main() {
    struct sigaction sa;
    sa.sa_handler = handle_sigint;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    sigaction(SIGINT, &sa, NULL);
    sigaction(SIGTERM, &sa, NULL);

    openlog("servo_pir", LOG_PID, LOG_USER);
    logfile = fopen("/var/log/security.log", "a");
    if (!logfile) {
        syslog(LOG_ERR, "Failed to open log file");
        exit(1);
    }

    struct sockaddr_in serv_addr;
    sockfd = socket(AF_INET, SOCK_STREAM, 0);
    if (sockfd < 0) {
        log_message(LOG_ERR, "Failed to create socket");
        exit(1);
    }
    memset(&serv_addr, '0', sizeof(serv_addr));
    serv_addr.sin_family = AF_INET;
    serv_addr.sin_addr.s_addr = htonl(INADDR_ANY);
    serv_addr.sin_port = htons(5000);
    if (bind(sockfd, (struct sockaddr *)&serv_addr, sizeof(serv_addr)) < 0) {
        log_message(LOG_ERR, "Failed to bind socket");
        exit(1);
    }
    if (listen(sockfd, 5) < 0) {
        log_message(LOG_ERR, "Failed to listen on socket");
        exit(1);
    }

    struct gpiod_chip *chip = gpiod_chip_open("/dev/gpiochip0");
    if (!chip) {
        log_message(LOG_ERR, "Failed to open GPIO chip");
        exit(1);
    }
    servo_line = gpiod_chip_get_line(chip, GPIO_SERVO);
    if (!servo_line) {
        log_message(LOG_ERR, "Failed to get servo GPIO line");
        exit(1);
    }
    if (gpiod_line_request_output(servo_line, "servo_pir", 0) < 0) {
        log_message(LOG_ERR, "Failed to request servo GPIO line as output");
        exit(1);
    }
    pir_line = gpiod_chip_get_line(chip, GPIO_PIR);
    if (!pir_line) {
        log_message(LOG_ERR, "Failed to get PIR GPIO line");
        exit(1);
    }
    if (gpiod_line_request_input(pir_line, "servo_pir") < 0) {
        log_message(LOG_ERR, "Failed to request PIR GPIO line as input");
        exit(1);
    }

    pthread_create(&pwm_thread, NULL, pwm_thread_func, NULL);

    while (running) {
        struct sockaddr_in cli_addr;
        socklen_t clilen = sizeof(cli_addr);
        int connfd = accept(sockfd, (struct sockaddr *)&cli_addr, &clilen);
        if (connfd < 0) {
            log_message(LOG_ERR, "Failed to accept connection");
            continue;
        }
        char buffer[256];
        int n = read(connfd, buffer, sizeof(buffer) - 1);
        if (n < 0) {
            log_message(LOG_ERR, "Failed to read from socket");
            close(connfd);
            continue;
        }
        buffer[n] = '\0';
        log_message(LOG_USER, "Received command: %s", buffer);
        if (strncmp(buffer, "SERVO ", 7) == 0) {
            int angle = atoi(buffer + 7);
            if (angle < 0 || angle > 180) {
                log_message(LOG_ERR, "Invalid angle: %d", angle);
                write(connfd, "ERROR\n", 6);
            } else {
                int pulse_width = SERVO_MIN + (SERVO_MAX - SERVO_MIN) * angle / 180;
                gpiod_line_set_value(servo_line, 0);
                usleep(pulse_width);
                gpiod_line_set_value(servo_line, 1);
                usleep(SERVO_FREQ * 1000 - pulse_width);
                write(connfd, "OK\n", 3);
            }
        } else if (strcmp(buffer, "PIR") == 0) {
            int value = gpiod_line_get_value(pir_line);
            write(connfd, value ? "PIR:1\n" : "PIR:0\n", value ? 7 : 6);
        } else {
            log_message(LOG_ERR, "Unknown command: %s", buffer);
            write(connfd, "ERROR\n", 6);
        }
        close(connfd);
    }

    return 0;
}

#include <stdio.h>
#include <stdlib.h>
#include <signal.h>
#include <time.h>
#include <pigpio.h>

#define BH1750_ADDRESS 0x23
#define BH1750_ONE_TIME_HIGH_RES_MODE 0x20
#define GROW_LIGHT_RELAY 23
#define LOG_FILE "grow_log.txt"

int i2c_handle;
FILE *log_file;

void cleanup(int signum) {
    fclose(log_file);
    gpioTerminate();
    exit(signum);
}

int main() {
    signal(SIGINT, cleanup);
    signal(SIGTERM, cleanup);

    if (gpioInitialise() < 0) {
        printf("Failed to initialize pigpio\n");
        return 1;
    }

    i2c_handle = i2cOpen(1, BH1750_ADDRESS, 0);
    if (i2c_handle < 0) {
        printf("Failed to open I2C device\n");
        return 1;
    }

    log_file = fopen(LOG_FILE, "w");
    if (log_file == NULL) {
        printf("Failed to open log file\n");
        return 1;
    }

    gpioSetMode(GROW_LIGHT_RELAY, PI_OUTPUT);
    gpioWrite(GROW_LIGHT_RELAY, PI_OFF);

    while (1) {
        uint8_t command = BH1750_ONE_TIME_HIGH_RES_MODE;
        if (i2cWriteByte(i2c_handle, command) < 0) {
            printf("Failed to write command to BH1750\n");
            continue;
        }

        time_t now;
        time(&now);
        fprintf(log_file, "%ld ", now);

        uint16_t raw;
        if (i2cReadDevice(i2c_handle, &raw, sizeof(raw)) < 0) {
            printf("Failed to read from BH1750\n");
            continue;
        }

        float lux = raw / 1.2;
        fprintf(log_file, "%.2f\n", lux);

        if (lux < 150) {
            gpioWrite(GROW_LIGHT_RELAY, PI_ON);
        } else {
            gpioWrite(GROW_LIGHT_RELAY, PI_OFF);
        }

        sleep(2);
    }

    return 0;
}

#include <stdio.h>
