#define DOUT_PIN 23
#define SCK_PIN 24
#define SOL_PIN 25
#define TARE_READINGS 10
#define MEASUREMENT_READINGS 5
#define MAX_RETRIES 3
#define DEFAULT_THRESHOLD 1000
#define DEFAULT_SCALE 1.0
#define DEFAULT_DURATION 200
#define POLL_INTERVAL 500

static volatile sig_atomic_t running = 1;
static int threshold = DEFAULT_THRESHOLD;
static float scale = DEFAULT_SCALE;
static int duration = DEFAULT_DURATION;

static void sig_handler(int signum) {
    running = 0;
}

static int hx711_read(gpiod_chip *chip, int dout, int sck) {
    int data = 0;
    for (int i = 0; i < 24; i++) {
        gpiod_set_line_value(sck, 1);
        usleep(1);
        data <<= 1;
        gpiod_set_line_value(sck, 0);
        usleep(1);
        if (gpiod_get_line_value(dout)) {
            data |= 1;
        }
    }
    gpiod_set_line_value(sck, 1);
    usleep(1);
    gpiod_set_line_value(sck, 0);
    return data;
}

static int hx711_average(gpiod_chip *chip, int dout, int sck, int readings) {
    int sum = 0;
    for (int i = 0; i < readings; i++) {
        sum += hx711_read(chip, dout, sck);
    }
    return sum / readings;
}

static void solenoid_trigger(gpiod_chip *chip, int sol) {
    gpiod_set_line_value(sol, 1);
    usleep(duration * 1000);
    gpiod_set_line_value(sol, 0);
}

int main(int argc, char *argv[]) {
    struct option long_options[] = {
        {"threshold", required_argument, 0, 't'},
        {"scale", required_argument, 0, 's'},
        {"duration", required_argument, 0, 'd'},
        {0, 0, 0, 0}
    };

    int opt;
    while ((opt = getopt_long(argc, argv, "t:s:d:", long_options, NULL)) != -1) {
        switch (opt) {
            case 't':
                threshold = atoi(optarg);
                break;
            case 's':
                scale = atof(optarg);
                break;
            case 'd':
                duration = atoi(optarg);
                break;
            default:
                fprintf(stderr, "Usage: %s [--threshold <grams>] [--scale <factor>] [--duration <ms>]\n", argv[0]);
                return EXIT_FAILURE;
        }
    }

    openlog("weight_monitor", LOG_PID, LOG_USER);
    signal(SIGINT, sig_handler);
    signal(SIGTERM, sig_handler);

    gpiod_chip *chip = gpiod_chip_open("/dev/gpiochip0");
    if (!chip) {
        syslog(LOG_ERR, "Failed to open GPIO chip");
        closelog();
        return EXIT_FAILURE;
    }

    gpiod_line_request req = {
        .consumer = "weight_monitor",
        .request_type = GPIOD_LINE_REQUEST_DIRECTION_INPUT,
        .flags = GPIOD_LINE_REQUEST_FLAG_BIAS_PULL_DOWN
    };

    gpiod_line *dout = gpiod_chip_get_line(chip, DOUT_PIN);
    gpiod_line *sck = gpiod_chip_get_line(chip, SCK_PIN);
    gpiod_line *sol = gpiod_chip_get_line(chip, SOL_PIN);

    if (!dout || !sck || !sol) {
        syslog(LOG_ERR, "Failed to get GPIO lines");
        gpiod_chip_close(chip);
        closelog();
        return EXIT_FAILURE;
    }

    if (gpiod_line_request(dout, &req) || gpiod_line_request(sck, &req) || gpiod_line_request(sol, &req)) {
        syslog(LOG_ERR, "Failed to request GPIO lines");
        gpiod_chip_close(chip);
        closelog();
        return EXIT_FAILURE;
    }

    int tare_offset = 0;
    for (int i = 0; i < TARE_READINGS; i++) {
        tare_offset += hx711_average(chip, dout, sck, MEASUREMENT_READINGS);
    }
    tare_offset /= TARE_READINGS;

    while (running) {
        int raw = hx711_average(chip, dout, sck, MEASUREMENT_READINGS) - tare_offset;
        int weight = raw / scale;
        if (weight > threshold) {
            solenoid_trigger(chip, sol);
        }
        syslog(LOG_INFO, "Weight: %d grams", weight);
        usleep(POLL_INTERVAL * 1000);
    }

    gpiod_line_release(dout);
    gpiod_line_release(sck);
    gpiod_line_release(sol);
    gpiod_chip_close(chip);
    closelog();
    return EXIT_SUCCESS;
}

