void signal_handler(int signum) {
    running = 0;
}

void message_callback(struct mosquitto *mosq, void *obj, const struct mosquitto_message *msg) {
    if (msg->payloadlen) {
        if (strncmp((char *)msg->payload, "ON", msg->payloadlen) == 0) {
            gpioWrite(GPIO_PIN, 1);
            syslog(LOG_INFO, "Received ON command, setting relay ON");
        } else if (strncmp((char *)msg->payload, "OFF", msg->payloadlen) == 0) {
            gpioWrite(GPIO_PIN, 0);
            syslog(LOG_INFO, "Received OFF command, setting relay OFF");
        } else {
            syslog(LOG_ERR, "Received invalid command: %s", (char *)msg->payload);
        }
    } else {
        syslog(LOG_ERR, "Received empty command");
    }
}

int main() {
    struct mosquitto *mosq = NULL;
    int rc = 0;

    openlog("mqtt_relay", LOG_PID, LOG_USER);

    if ((rc = gpioInitialise()) < 0) {
        syslog(LOG_ERR, "Failed to initialize pigpio: %s", gpioErrorText(rc));
        closelog();
        return EXIT_FAILURE;
    }

    gpioSetMode(GPIO_PIN, PI_OUTPUT);
    gpioWrite(GPIO_PIN, 0);

    mosquitto_lib_init();

    mosq = mosquitto_new(MQTT_CLIENT_ID, true, NULL);
    if (!mosq) {
        syslog(LOG_ERR, "Failed to create mosquitto client");
        gpioTerminate();
        closelog();
        return EXIT_FAILURE;
    }

    mosquitto_connect_callback_set(mosq, NULL);
    mosquitto_disconnect_callback_set(mosq, NULL);
    mosquitto_message_callback_set(mosq, message_callback);

    mosquitto_connect_callback_set(mosq, NULL);
    mosquitto_disconnect_callback_set(mosq, NULL);
    mosquitto_message_callback_set(mosq, message_callback);

    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    while (running) {
        rc = mosquitto_connect(mosq, MQTT_BROKER, MQTT_PORT, 60);
        if (rc != MOSQ_ERR_SUCCESS) {
            syslog(LOG_ERR, "Failed to connect to MQTT broker: %s", mosquitto_strerror(rc));
            sleep(5);
            continue;
        }

        rc = mosquitto_subscribe(mosq, NULL, MQTT_TOPIC, 0);
        if (rc != MOSQ_ERR_SUCCESS) {
            syslog(LOG_ERR, "Failed to subscribe to MQTT topic: %s", mosquitto_strerror(rc));
            sleep(5);
            continue;
        }

        syslog(LOG_INFO, "Connected to MQTT broker and subscribed to topic");

        while (running) {
            rc = mosquitto_loop(mosq, -1, 1);
            if (rc != MOSQ_ERR_SUCCESS) {
                syslog(LOG_ERR, "MQTT loop error: %s", mosquitto_strerror(rc));
                break;
            }
        }

        mosquitto_disconnect(mosq);
        sleep(5);
    }

    mosquitto_destroy(mosq);
    mosquitto_lib_cleanup();
    gpioTerminate();
    closelog();

    return EXIT_SUCCESS;
}

