#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <pigpio.h>
#include <errno.h>

#define I2C_BUS 1
#define I2C_ADDRESS 0x23
#define GPIO_RELAY 17
#define LUX_THRESHOLD_LOW 50
#define LUX_THRESHOLD_HIGH 200
#define LOG_FILE "chicken_coop_log.txt"

int main(int argc, char *argv[]) {
    FILE *log_file;
    int i2c_handle, lux;
    time_t now;
    struct tm *timeinfo;
    char buffer[80];

    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Failed to initialize pigpio: %s\n", strerror(errno));
        return EXIT_FAILURE;
    }

    // Open log file
    log_file = fopen(LOG_FILE, "a");
    if (log_file == NULL) {
        fprintf(stderr, "Failed to open log file: %s\n", strerror(errno));
        gpioTerminate();
        return EXIT_FAILURE;
    }

    // Open I2C bus
    i2c_handle = i2cOpen(I2C_BUS, I2C_ADDRESS, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Failed to open I2C bus: %s\n", strerror(errno));
        fclose(log_file);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    // Set up GPIO relay
    if (gpioSetMode(GPIO_RELAY, PI_OUTPUT) < 0) {
        fprintf(stderr, "Failed to set GPIO relay mode: %s\n", strerror(errno));
        i2cClose(i2c_handle);
        fclose(log_file);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    // Main loop
    while (1) {
        // Send command to BH1750 to start measurement
        if (i2cWriteByteData(i2c_handle, 0x21, 0) < 0) {
            fprintf(stderr, "Failed to write to I2C bus: %s\n", strerror(errno));
            lux = -1;
        } else {
            // Wait for at least 180 ms
            usleep(180000);

            // Read 2 bytes of data from BH1750
            uint16_t raw_lux;
            if (i2cReadByteData(i2c_handle, 0x23, (char *)&raw_lux, 2) < 0) {
                fprintf(stderr, "Failed to read from I2C bus: %s\n", strerror(errno));
                lux = -1;
            } else {
                // Convert raw data to lux
                lux = raw_lux / 1.2;
            }
        }

        // Log sensor reading
        now = time(NULL);
        timeinfo = localtime(&now);
        strftime(buffer, sizeof(buffer), "%Y-%m-%d %H:%M:%S: ", timeinfo);
        fprintf(log_file, "%s Lux = %d", buffer, lux);

        // Check if lux is below or above threshold
        if (lux < 0 || lux < LUX_THRESHOLD_LOW) {
            // Turn on relay
            gpioWrite(GPIO_RELAY, PI_HIGH);
            fprintf(log_file, ", Relay = ON\n");
        } else if (lux > LUX_THRESHOLD_HIGH) {
            // Turn off relay
            gpioWrite(GPIO_RELAY, PI_LOW);
            fprintf(log_file, ", Relay = OFF\n");
        } else {
            fprintf(log_file, ", Relay = %s\n", gpioRead(GPIO_RELAY) ? "ON" : "OFF");
        }

        // Flush log file
        fflush(log_file);

        // Wait for 5 seconds
        sleep(5);
    }

    // Clean up
    i2cClose(i2c_handle);
    fclose(log_file);
    gpioTerminate();
    return EXIT_SUCCESS;
}

#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <pigpio.h>

#define RELAY_PIN 17
#define TOUCH_PIN 4
#define DEBOUNCE_TIME 50 // ms
#define STATE_OFF 0
#define STATE_ON 1

volatile sig_atomic_t running = 1;
int relay_state = STATE_OFF;

void handle_sigint(int signum) {
    running = 0;
}

int main() {
    struct timespec sleep_time = {.tv_sec = 0, .tv_nsec = 10000000}; // 10 ms
    struct timespec debounce_delay = {.tv_sec = 0, .tv_nsec = DEBOUNCE_TIME * 1000000L}; // ms to ns

    if (gpioInitialise() < 0) {
        fprintf(stderr, "Failed to initialize pigpio\n");
        return EXIT_FAILURE;
    }

    if (gpioSetMode(RELAY_PIN, PI_OUTPUT) < 0) {
        fprintf(stderr, "Failed to set GPIO %d mode to output\n", RELAY_PIN);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    if (gpioSetMode(TOUCH_PIN, PI_INPUT) < 0) {
        fprintf(stderr, "Failed to set GPIO %d mode to input\n", TOUCH_PIN);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    signal(SIGINT, handle_sigint);

    while (running) {
        int touch_value = gpioRead(TOUCH_PIN);

        if (touch_value == PI_HIGH) {
            nanosleep(&debounce_delay, NULL);
            touch_value = gpioRead(TOUCH_PIN);

            if (touch_value == PI_HIGH) {
                relay_state = !relay_state;
                gpioWrite(RELAY_PIN, relay_state);
                time_t now = time(NULL);
                struct tm *timeinfo = localtime(&now);
                char buffer[20];
                strftime(buffer, sizeof(buffer), "%Y-%m-%dT%H:%M:%S", timeinfo);
                printf("%s: Relay is now %s\n", buffer, relay_state ? "ON" : "OFF");
            }
        }

        while (gpioRead(TOUCH_PIN) == PI_HIGH) {
            nanosleep(&sleep_time, NULL);
        }
    }

    gpioWrite(RELAY_PIN, STATE_OFF);
    gpioTerminate();
    printf("Exiting program\n");
    return EXIT_SUCCESS;
}

#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <pthread.h>
#include <pigpio.h>

#define FLOW_SENSOR_PIN 17
#define SOLENOID_PIN 27
#define PULSES_PER_LITER 450.0
#define LPM_THRESHOLD_HIGH 5.0
#define LPM_THRESHOLD_LOW 4.5
#define DEBOUNCE_TIMEOUT 1000
#define LOG_FILE_NAME "water_flow.log"

volatile uint32_t pulse_count = 0;
pthread_mutex_t pulse_mutex = PTHREAD_MUTEX_INITIALIZER;
FILE *log_file = NULL;

void flow_sensor_isr(int gpio, int level, uint32_t tick) {
    pthread_mutex_lock(&pulse_mutex);
    pulse_count++;
    pthread_mutex_unlock(&pulse_mutex);
}

void log_event(const char *message) {
    time_t now = time(NULL);
    struct tm *time_info = localtime(&now);
    char time_str[20];
    strftime(time_str, sizeof(time_str), "%Y-%m-%d %H:%M:%S", time_info);
    fprintf(log_file, "[%s] %s\n", time_str, message);
    fflush(log_file);
}

void signal_handler(int signum) {
    log_event("Received signal, reopening solenoid.");
    gpioWrite(SOLENOID_PIN, 1);
    fclose(log_file);
    pthread_mutex_destroy(&pulse_mutex);
    gpioTerminate();
    exit(0);
}

int main() {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Failed to initialize pigpio.\n");
        return 1;
    }

    if ((log_file = fopen(LOG_FILE_NAME, "a")) == NULL) {
        fprintf(stderr, "Failed to open log file.\n");
        gpioTerminate();
        return 1;
    }

    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    if (gpioSetMode(FLOW_SENSOR_PIN, PI_INPUT) < 0) {
        fprintf(stderr, "Failed to set mode for flow sensor pin.\n");
        goto cleanup;
    }

    if (gpioSetMode(SOLENOID_PIN, PI_OUTPUT) < 0) {
        fprintf(stderr, "Failed to set mode for solenoid pin.\n");
        goto cleanup;
    }

    gpioWrite(SOLENOID_PIN, 1);

    if (gpioSetISRFuncEx(FLOW_SENSOR_PIN, PI_EVENT_EDGE, DEBOUNCE_TIMEOUT, flow_sensor_isr) < 0) {
        fprintf(stderr, "Failed to set ISR for flow sensor pin.\n");
        goto cleanup;
    }

    log_event("System started.");

    while (1) {
        time_t now = time(NULL);
        struct tm *time_info = localtime(&now);
        char time_str[20];
        strftime(time_str, sizeof(time_str), "%Y-%m-%d %H:%M:%S", time_info);

        pthread_mutex_lock(&pulse_mutex);
        float lpm = (float)pulse_count / PULSES_PER_LITER * 60.0;
        pulse_count = 0;
        pthread_mutex_unlock(&pulse_mutex);

        fprintf(log_file, "[%s] LPM: %.2f\n", time_str, lpm);
        fflush(log_file);

        if (lpm > LPM_THRESHOLD_HIGH) {
            gpioWrite(SOLENOID_PIN, 0);
            log_event("Solenoid closed.");
        } else if (lpm < LPM_THRESHOLD_LOW) {
            gpioWrite(SOLENOID_PIN, 1);
            log_event("Solenoid reopened.");
        }

        sleep(1);
    }

cleanup:
    fclose(log_file);
    pthread_mutex_destroy(&pulse_mutex);
    gpioTerminate();
    return 1;
}

