        return EXIT_FAILURE;
    }

    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    gpioSetMode(RELAY_PIN, PI_OUTPUT);
    gpioSetMode(TOUCH_PIN, PI_INPUT);

    int relay_state = 0;
    int last_touch = 0;
    struct timespec ts;

    while (!stop) {
        int current_touch = gpioRead(TOUCH_PIN);
        if (current_touch == PI_HIGH && last_touch == PI_LOW) {
            clock_gettime(CLOCK_REALTIME, &ts);
            char time_str[20];
            strftime(time_str, sizeof(time_str), "%Y-%m-%d %H:%M:%S", localtime(&ts.tv_sec));
            printf("%s Relay: %s\n", time_str, relay_state ? "OFF" : "ON");
            gpioWrite(RELAY_PIN, relay_state ? PI_LOW : PI_HIGH);
            relay_state = !relay_state;
        }
        last_touch = current_touch;
        gpioDelay(debounce * 1000);
    }

    gpioWrite(RELAY_PIN, PI_LOW);
    gpioTerminate();
    return EXIT_SUCCESS;
}

#include <stdio.h>
#include <stdlib.h>
#include <signal.h>
#include <termios.h>
#include <unistd.h>
#include <pigpio.h>

#define GPIO_PIN 18
#define MIN_PULSE_WIDTH 500
#define MAX_PULSE_WIDTH 2500
#define DEFAULT_PULSE_WIDTH 1500
#define ANGLE_STEP 10

volatile sig_atomic_t stop = 0;
struct termios old_settings;

void handle_sigint(int signum) {
    stop = 1;
}

int main() {
    int angle = 90;
    int pulse_width = DEFAULT_PULSE_WIDTH;

    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialization failed\n");
        return EXIT_FAILURE;
    }

    if (gpioSetMode(GPIO_PIN, PI_OUTPUT) < 0) {
        fprintf(stderr, "failed to set GPIO mode\n");
        gpioTerminate();
        return EXIT_FAILURE;
    }

    if (gpioServo(GPIO_PIN, pulse_width) < 0) {
        fprintf(stderr, "failed to set servo pulse width\n");
        gpioTerminate();
        return EXIT_FAILURE;
    }

    struct termios new_settings;
    tcgetattr(STDIN_FILENO, &old_settings);
    new_settings = old_settings;
    new_settings.c_lflag &= ~(ICANON | ECHO);
    tcsetattr(STDIN_FILENO, TCSANOW, &new_settings);

    signal(SIGINT, handle_sigint);

    while (!stop) {
        char input;
        if (read(STDIN_FILENO, &input, 1) > 0) {
            switch (input) {
                case '+':
                    angle = (angle + ANGLE_STEP) % 181;
                    break;
                case '-':
                    angle = (angle - ANGLE_STEP + 181) % 181;
                    break;
                case 'q':
                    stop = 1;
                    break;
            }

            pulse_width = MIN_PULSE_WIDTH + (MAX_PULSE_WIDTH - MIN_PULSE_WIDTH) * angle / 180;
            if (pulse_width < MIN_PULSE_WIDTH || pulse_width > MAX_PULSE_WIDTH) {
                fprintf(stderr, "invalid pulse width\n");
                stop = 1;
            } else {
                if (gpioServo(GPIO_PIN, pulse_width) < 0) {
                    fprintf(stderr, "failed to set servo pulse width\n");
                    stop = 1;
                } else {
                    printf("Servo angle: %d°\n", angle);
                }
            }
        }
    }

    gpioServo(GPIO_PIN, 0);
    tcsetattr(STDIN_FILENO, TCSANOW, &old_settings);
    gpioTerminate();

    return EXIT_SUCCESS;
}

#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <unistd.h>
#include <signal.h>
#include <time.h>
#include <gpiod.h>

#define GPIO_PIN 17
#define DEBOUNCE_US 2000
#define SAMPLE_INTERVAL_S 5
#define LOG_FILE "motor_rpm.log"

static volatile sig_atomic_t running = 1;
static FILE *logFile = NULL;
static uint32_t pulseCount = 0;
static struct timespec lastPulseTime = {0, 0};

static void handleSignal(int signum) {
    running = 0;
}

static void logRPM(const struct timespec *now) {
    static struct timespec lastLogTime = {0, 0};
    if (clock_gettime(CLOCK_MONOTONIC, &lastLogTime) == -1) {
        perror("clock_gettime");
        exit(EXIT_FAILURE);
    }
    if (difftime(now->tv_sec, lastLogTime.tv_sec) >= SAMPLE_INTERVAL_S) {
        double rpm = (pulseCount / 5.0) * 60.0;
        char timestamp[26];
        strftime(timestamp, sizeof(timestamp), "%Y-%m-%dT%H:%M:%S", localtime(&lastLogTime.tv_sec));
        fprintf(logFile, "%s,%0.2f\n", timestamp, rpm);
        fflush(logFile);
        printf("Current RPM: %0.2f\n", rpm);
        pulseCount = 0;
        lastLogTime = *now;
    }
}

static void pulseHandler(struct gpiod_line_event event) {
    struct timespec now;
    if (clock_gettime(CLOCK_MONOTONIC, &now) == -1) {
        perror("clock_gettime");
        exit(EXIT_FAILURE);
    }
    if (difftime(now.tv_sec, lastPulseTime.tv_sec) >= 0 && now.tv_nsec - lastPulseTime.tv_nsec < DEBOUNCE_US * 1000) {
        return;
    }
    pulseCount++;
    lastPulseTime = now;
    logRPM(&now);
}

int main() {
    struct gpiod_chip *chip;
    struct gpiod_line *line;
    struct sigaction sa;
    struct gpiod_line_request_config config;
    struct gpiod_line_event event;
    struct timespec now;

    if (sigemptyset(&sa.sa_mask) == -1 || sigaddset(&sa.sa_mask, SIGINT) == -1 || sigaddset(&sa.sa_mask, SIGTERM) == -1) {
        perror("sigaction");
        exit(EXIT_FAILURE);
    }
    sa.sa_handler = handleSignal;
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) == -1 || sigaction(SIGTERM, &sa, NULL) == -1) {
        perror("sigaction");
        exit(EXIT_FAILURE);
    }

    if ((logFile = fopen(LOG_FILE, "a")) == NULL) {
        perror("fopen");
        exit(EXIT_FAILURE);
    }

    if ((chip = gpiod_chip_open("/dev/gpiochip0")) == NULL) {
        perror("gpiod_chip_open");
        exit(EXIT_FAILURE);
    }
    if ((line = gpiod_chip_get_line(chip, GPIO_PIN)) == NULL) {
        perror("gpiod_chip_get_line");
        exit(EXIT_FAILURE);
    }
    memset(&config, 0, sizeof(config));
    config.request_type = GPIOD_LINE_REQUEST_DIRECTION_INPUT;
    config.flags = GPIOD_LINE_REQUEST_FLAG_BIAS_PULL_UP;
    if (gpiod_line_request_input_flags(line, "motor_rpm", &config) == -1) {
        perror("gpiod_line_request_input_flags");
        exit(EXIT_FAILURE);
    }

    while (running) {
        if (gpiod_line_event_wait(line, &event) == -1) {
            perror("gpiod_line_event_wait");
            exit(EXIT_FAILURE);
        }
        pulseHandler(event);
    }

    fclose(logFile);
    gpiod_line_release(line);
    gpiod_chip_close(chip);
    return EXIT_SUCCESS;
}

#include <stdio.h>
#include <signal.h>
#include <stdbool.h>
#include <pigpio.h>

#define RELAY_PIN 17
#define TOUCH_PIN 4
#define TOUCH_TIMEOUT 10000 // 10 seconds

volatile sig_atomic_t stop_requested = false;

void signal_handler(int signum) {
    stop_requested = true;
}

int main() {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialization failed\n");
        return 1;
    }

    if (gpioSetMode(RELAY_PIN, PI_OUTPUT) < 0) {
        fprintf(stderr, "Failed to set mode for relay pin\n");
        gpioTerminate();
        return 1;
    }

    if (gpioSetMode(TOUCH_PIN, PI_INPUT) < 0) {
        fprintf(stderr, "Failed to set mode for touch pin\n");
        gpioTerminate();
        return 1;
    }

    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    uint32_t touch_start_time = 0;
    bool relay_state = false;

    while (!stop_requested) {
        int level = gpioRead(TOUCH_PIN);

        if (level == PI_BAD_GPIO) {
            fprintf(stderr, "Error reading touch pin\n");
            gpioTerminate();
            return 1;
        }

        if (level == PI_HIGH) {
            if (touch_start_time == 0) {
                touch_start_time = time(NULL);
            } else if (time(NULL) - touch_start_time > TOUCH_TIMEOUT) {
                gpioWrite(RELAY_PIN, PI_LOW);
                printf("Touch sensor timeout, relay forced OFF\n");
                touch_start_time = 0;
            }
        } else {
            if (touch_start_time != 0) {
                if (!relay_state) {
                    gpioWrite(RELAY_PIN, PI_HIGH);
                    printf("Touch detected, relay ON\n");
                } else {
                    gpioWrite(RELAY_PIN, PI_LOW);
                    printf("Touch released, relay OFF\n");
                }
                relay_state = !relay_state;
                touch_start_time = 0;
            }
        }

        usleep(50000); // 50 ms
    }

    gpioWrite(RELAY_PIN, PI_LOW);
    gpioTerminate();
    return 0;
}

#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <unistd.h>
#include <signal.h>
#include <time.h>
#include <pigpio.h>

#define GPIO_FLOW 24
#define GPIO_VALVE 18
#define GPIO_ENABLE 23
#define FLOW_PULSES_PER_LITER 450
#define KP 1.0
#define PWM_MIN 0
#define PWM_MAX 255
#define SAMPLE_INTERVAL_MS 100
#define LOG_FILE "flow_log.csv"

volatile int flow_count = 0;
double target_flow_rate = 0.0;
FILE *log_file = NULL;

void flow_isr(int gpio, int level, uint32_t tick) {
    flow_count++;
}

void shutdown(int signum) {
    gpioSetPWMdutycycle(GPIO_VALVE, 0);
    gpioWrite(GPIO_ENABLE, 0);
    fclose(log_file);
    gpioTerminate();
    exit(signum);
}

int main(int argc, char *argv[]) {
    int opt;
    while ((opt = getopt(argc, argv, "t:")) != -1) {
        switch (opt) {
            case 't':
                target_flow_rate = atof(optarg);
                if (target_flow_rate <= 0) {
                    fprintf(stderr, "Invalid target flow rate: %s\n", optarg);
                    return EXIT_FAILURE;
                }
                break;
            default:
                fprintf(stderr, "Usage: %s -t <target_flow_rate>\n", argv[0]);
                return EXIT_FAILURE;
        }
    }
    if (target_flow_rate == 0) {
        fprintf(stderr, "Target flow rate is required.\n");
        return EXIT_FAILURE;
    }

    if (gpioInitialise() < 0) {
        fprintf(stderr, "Failed to initialize pigpio.\n");
        return EXIT_FAILURE;
    }

    signal(SIGINT, shutdown);
    signal(SIGTERM, shutdown);

    if (gpioSetMode(GPIO_FLOW, PI_INPUT) < 0) {
        fprintf(stderr, "Failed to set GPIO %d mode to input.\n", GPIO_FLOW);
        return EXIT_FAILURE;
    }
    if (gpioSetMode(GPIO_VALVE, PI_OUTPUT) < 0) {
        fprintf(stderr, "Failed to set GPIO %d mode to output.\n", GPIO_VALVE);
        return EXIT_FAILURE;
    }
    if (gpioSetMode(GPIO_ENABLE, PI_OUTPUT) < 0) {
        fprintf(stderr, "Failed to set GPIO %d mode to output.\n", GPIO_ENABLE);
        return EXIT_FAILURE;
    }
    if (gpioSetPWMfrequency(GPIO_VALVE, 1000) < 0) {
        fprintf(stderr, "Failed to set PWM frequency.\n");
        return EXIT_FAILURE;
    }
    if (gpioSetPWMrange(GPIO_VALVE, PWM_MAX) < 0) {
        fprintf(stderr, "Failed to set PWM range.\n");
        return EXIT_FAILURE;
    }
    if (gpioSetPWMdutycycle(GPIO_VALVE, 0) < 0) {
        fprintf(stderr, "Failed to set PWM duty cycle.\n");
        return EXIT_FAILURE;
    }
    if (gpioWrite(GPIO_ENABLE, 1) < 0) {
        fprintf(stderr, "Failed to write GPIO %d.\n", GPIO_ENABLE);
        return EXIT_FAILURE;
    }
    if ((log_file = fopen(LOG_FILE, "w")) == NULL) {
        fprintf(stderr, "Failed to open log file.\n");
        return EXIT_FAILURE;
    }
    if (gpioSetISR(GPIO_FLOW, PI_RISING_EDGE, &flow_isr) < 0) {
        fprintf(stderr, "Failed to set ISR for GPIO %d.\n", GPIO_FLOW);
        return EXIT_FAILURE;
    }

    struct timespec sample_time = {0, 0};
    clock_gettime(CLOCK_MONOTONIC, &sample_time);
    uint32_t last_tick = sample_time.tv_nsec / 1000000;
    double integral_error = 0.0;
    while (1) {
        clock_gettime(CLOCK_MONOTONIC, &sample_time);
        uint32_t current_tick = sample_time.tv_nsec / 1000000;
        uint32_t elapsed_ms = current_tick - last_tick;
        last_tick = current_tick;

        double flow_rate = (double)flow_count * 1000.0 / (double)elapsed_ms * FLOW_PULSES_PER_LITER;
        flow_count = 0;

        double error = target_flow_rate - flow_rate;
        integral_error += error;
        double derivative_error = error - (integral_error / SAMPLE_INTERVAL_MS);
        double control_signal = KP * error + KP * integral_error / SAMPLE_INTERVAL_MS + KP * derivative_error / SAMPLE_INTERVAL_MS;

        int pwm_duty_cycle = (int)(control_signal + 0.5);
        pwm_duty_cycle = pwm_duty_cycle < PWM_MIN ? PWM_MIN : pwm_duty_cycle > PWM_MAX ? PWM_MAX : pwm_duty_cycle;
        if (gpioSetPWMdutycycle(GPIO_VALVE, pwm_duty_cycle) < 0) {
            fprintf(stderr, "Failed to set PWM duty cycle.\n");
            return EXIT_FAILURE;
        }

        fprintf(log_file, "%lu,%f,%d\n", sample_time.tv_nsec / 1000000, flow_rate, pwm_duty_cycle);
        fflush(log_file);

        nanosleep(&(struct timespec){0, SAMPLE_INTERVAL_MS * 1000000}, NULL);
    }

    return EXIT_SUCCESS;
}

#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <pigpio.h>

#define TAG_SIZE 10
#define TAG_MATCH {0x01, 0x02, 0x03, 0x04, 0x05, 0x06, 0x07, 0x08, 0x09, 0x0A}
#define LOG_FILE "/var/log/door_access.log"
#define LOCK_PIN_1 17
#define LOCK_PIN_2 27
#define BUTTON_PIN 22
#define SPI_CHANNEL 0
#define SPI_SPEED 100000
#define DEBOUNCE_TIME 50000
#define LOCK_TIME 5000000

volatile sig_atomic_t running = 1;

void sig_handler(int signum) {
    running = 0;
}

int main() {
    FILE *log_file;
    uint8_t tag[TAG_SIZE] = {0};
    uint8_t tag_match[TAG_SIZE] = TAG_MATCH;
    int lock_pin_1, lock_pin_2, button_pin, spi_channel;
    uint32_t spi_speed;
    uint8_t spi_data[TAG_SIZE + 1] = {0};

    if ((log_file = fopen(LOG_FILE, "a")) == NULL) {
        fprintf(stderr, "Failed to open log file\n");
        return EXIT_FAILURE;
    }

    if ((lock_pin_1 = gpioInitialise()) < 0) {
        fprintf(stderr, "Failed to initialize GPIO\n");
        fclose(log_file);
        return EXIT_FAILURE;
    }

    if ((lock_pin_2 = gpioInitialise()) < 0) {
        fprintf(stderr, "Failed to initialize GPIO\n");
        gpioTerminate();
        fclose(log_file);
        return EXIT_FAILURE;
    }

    if ((button_pin = gpioInitialise()) < 0) {
        fprintf(stderr, "Failed to initialize GPIO\n");
        gpioTerminate();
        fclose(log_file);
        return EXIT_FAILURE;
    }

    if ((spi_channel = spiOpen(SPI_CHANNEL, SPI_SPEED, 0)) < 0) {
        fprintf(stderr, "Failed to open SPI channel\n");
        gpioTerminate();
        fclose(log_file);
        return EXIT_FAILURE;
    }

    signal(SIGINT, sig_handler);
    signal(SIGTERM, sig_handler);

    while (running) {
        // Check for button press
        if (gpioRead(button_pin) == 0) {
            gpioDelay(DEBOUNCE_TIME);
            if (gpioRead(button_pin) == 0) {
                // Button pressed, check for valid tag
                if (memcmp(tag, tag_match, TAG_SIZE) == 0) {
                    // Valid tag, disengage locks
                    gpioWrite(lock_pin_1, 0);
                    gpioWrite(lock_pin_2, 0);
                    gpioDelay(LOCK_TIME);
                    gpioWrite(lock_pin_1, 1);
                    gpioWrite(lock_pin_2, 1);
                    // Log successful access
                    time_t now = time(NULL);
                    struct tm *t = localtime(&now);
                    fprintf(log_file, "%04d-%02d-%02dT%02d:%02d:%02d - Access granted\n",
                            t->tm_year + 1900, t->tm_mon + 1, t->tm_mday,
                            t->tm_hour, t->tm_min, t->tm_sec);
                    fflush(log_file);
                } else {
                    // Invalid tag, log attempt
                    time_t now = time(NULL);
                    struct tm *t = localtime(&now);
                    fprintf(log_file, "%04d-%02d-%02dT%02d:%02d:%02d - Invalid tag\n",
                            t->tm_year + 1900, t->tm_mon + 1, t->tm_mday,
                            t->tm_hour, t->tm_min, t->tm_sec);
                    fflush(log_file);
                }
                // Reset tag
                memset(tag, 0, TAG_SIZE);
            }
        }

        // Check for RFID tag
        spi_data[0] = 0x02; // Command to read tag
        if (spiXfer(spi_channel, spi_data, spi_data, TAG_SIZE + 1) < 0) {
            // SPI read failure, log attempt
            time_t now = time(NULL);
            struct tm *t = localtime(&now);
            fprintf(log_file, "%04d-%02d-%02dT%02d:%02d:%02d - RFID read failure\n",
                    t->tm_year + 1900, t->tm_mon + 1, t->tm_mday,
                    t->tm_hour, t->tm_min, t->tm_sec);
            fflush(log_file);
        } else if (spi_data[0] != 0x00) {
            // Tag read, log attempt
            time_t now = time(NULL);
            struct tm *t = localtime(&now);
            fprintf(log_file, "%04d-%02d-%02dT%02d:%02d:%02d - Tag read\n",
                    t->tm_year + 1900, t->tm_mon + 1, t->tm_mday,
                    t->tm_hour, t->tm_min, t->tm_sec);
            fflush(log_file);
            // Copy tag data
            memcpy(tag, spi_data + 1, TAG_SIZE);
        }

        // Check for button press
        if (gpioRead(button_pin) == 0) {
            gpioDelay(DEBOUNCE_TIME);
            if (gpioRead(button_pin) == 0) {
                // Button pressed, check for valid tag
                if (memcmp(tag, tag_match, TAG_SIZE) == 0) {
                    // Valid tag, disengage locks
                    gpioWrite(lock_pin_1, 0);
                    gpioWrite(lock_pin_2, 0);
                    gpioDelay(LOCK_TIME);
                    gpioWrite(lock_pin_1, 1);
                    gpioWrite(lock_pin_2, 1);
                    // Log successful access
                    time_t now = time(NULL);
                    struct tm *t = localtime(&now);
                    fprintf(log_file, "%04d-%02d-%02dT%02d:%02d:%02d - Access granted\n",
                            t->tm_year + 1900, t->tm_mon + 1, t->tm_mday,
                            t->tm_hour, t->tm_min, t->tm_sec);
                    fflush(log_file);
                } else {
                    // Invalid tag, log attempt
                    time_t now = time(NULL);
                    struct tm *t = localtime(&now);
                    fprintf(log_file, "%04d-%02d-%02dT%02d:%02d:%02d - Invalid tag\n",
                            t->tm_year + 1900, t->tm_mon + 1, t->tm_mday,
                            t->tm_hour, t->tm_min, t->tm_sec);
                    fflush(log_file);
                }
                // Reset tag
                memset(tag, 0, TAG_SIZE);
            }
        }
    }

    // Clean shutdown
    gpioTerminate();
    spiClose(spi_channel);
    fclose(log_file);

    return EXIT_SUCCESS;
}

