#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <signal.h>
#include <time.h>
#include <pigpio.h>

#define MPR121_I2C_ADDRESS 0x5A
#define MPR121_TOUCH_STATUS_0 0x00
#define MPR121_TOUCH_STATUS_1 0x01
#define MPR121_ELECTRODES 12
#define RELAY_GPIO 17

FILE *log_file;
int mpr121_i2c_handle;
int relay_state = 0;

void cleanup(int exit_code) {
    if (mpr121_i2c_handle >= 0) {
        gpio_i2c_close(mpr121_i2c_handle);
    }
    if (log_file) {
        fclose(log_file);
    }
    exit(exit_code);
}

void signal_handler(int signum) {
    cleanup(0);
}

void log_relay_state_change(int new_state) {
    time_t rawtime;
    struct tm *timeinfo;
    char buffer[80];

    time(&rawtime);
    timeinfo = localtime(&rawtime);

    strftime(buffer, sizeof(buffer), "%Y-%m-%d %H:%M:%S", timeinfo);
    fprintf(log_file, "%s: Relay state changed to %d\n", buffer, new_state);
    fflush(log_file);
}

int main() {
    struct sigaction action;
    action.sa_handler = signal_handler;
    sigemptyset(&action.sa_mask);
    action.sa_flags = 0;
    sigaction(SIGINT, &action, NULL);

    log_file = fopen("relay_log.txt", "a");
    if (!log_file) {
        fprintf(stderr, "Failed to open log file\n");
        return 1;
    }

    if (gpio_initialise() < 0) {
        fprintf(stderr, "Failed to initialize pigpio\n");
        cleanup(1);
    }

    mpr121_i2c_handle = gpio_i2c_open(1, MPR121_I2C_ADDRESS);
    if (mpr121_i2c_handle < 0) {
        fprintf(stderr, "Failed to open I2C handle for MPR121\n");
        cleanup(1);
    }

    // MPR121 initialization sequence here...

    while (1) {
        uint8_t touch_status_0 = gpio_i2c_read_byte_data(mpr121_i2c_handle, MPR121_TOUCH_STATUS_0);
        uint8_t touch_status_1 = gpio_i2c_read_byte_data(mpr121_i2c_handle, MPR121_TOUCH_STATUS_1);

        int any_touch = 0;
        for (int i = 0; i < MPR121_ELECTRODES; i++) {
            if ((touch_status_0 & (1 << i)) || (touch_status_1 & (1 << i))) {
                any_touch = 1;
                break;
            }
        }

        if (any_touch && !relay_state) {
            gpio_write(RELAY_GPIO, 1);
            log_relay_state_change(1);
            relay_state = 1;
        } else if (!any_touch && relay_state) {
            gpio_write(RELAY_GPIO, 0);
            log_relay_state_change(0);
            relay_state = 0;
        }

        gpio_delay(50000); // 50 ms delay
    }

    cleanup(0);
    return 0;
}

#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <gpiod.h>

#define GPIO_PIN_1 17
#define GPIO_PIN_2 18
#define VALVE_1_DURATION 500
#define VALVE_2_DURATION 1000
#define PAUSE_BETWEEN_VALVES_1 5000
#define PAUSE_BETWEEN_VALVES_2 10000

FILE *log_file;
struct gpiod_chip *chip;
struct gpiod_line *line1;
struct gpiod_line *line2;

void cleanup_and_exit(int exit_code) {
    if (line1) gpiod_line_release(line1);
    if (line2) gpiod_line_release(line2);
    if (chip) gpiod_chip_close(chip);
    if (log_file) fclose(log_file);
    exit(exit_code);
}

void log_event(const char *event) {
    time_t now = time(NULL);
    struct tm *t = localtime(&now);
    char timestamp[20];
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%dT%H:%M:%S", t);
    fprintf(log_file, "%s: %s\n", timestamp, event);
    fflush(log_file);
}

void activate_valve(int valve_pin, int duration) {
    struct timespec sleep_time = {duration / 1000, (duration % 1000) * 1000 * 1000};
    gpiod_line_set_value(line1, valve_pin == GPIO_PIN_1 ? GPIO_HIGH : GPIO_LOW);
    log_event(valve_pin == GPIO_PIN_1 ? "Valve 1 activated" : "Valve 2 activated");
    nanosleep(&sleep_time, NULL);
    gpiod_line_set_value(line1, GPIO_LOW);
    log_event(valve_pin == GPIO_PIN_1 ? "Valve 1 deactivated" : "Valve 2 deactivated");
}

void signal_handler(int signum) {
    cleanup_and_exit(EXIT_SUCCESS);
}

int main() {
    log_file = fopen("valve_log.txt", "a");
    if (!log_file) {
        fprintf(stderr, "Failed to open log file\n");
        return EXIT_FAILURE;
    }

    chip = gpiod_chip_open("/dev/gpiochip0");
    if (!chip) {
        fprintf(stderr, "Failed to open GPIO chip\n");
        cleanup_and_exit(EXIT_FAILURE);
    }

    line1 = gpiod_chip_get_line(chip, GPIO_PIN_1);
    if (!line1) {
        fprintf(stderr, "Failed to get line for GPIO %d\n", GPIO_PIN_1);
        cleanup_and_exit(EXIT_FAILURE);
    }

    line2 = gpiod_chip_get_line(chip, GPIO_PIN_2);
    if (!line2) {
        fprintf(stderr, "Failed to get line for GPIO %d\n", GPIO_PIN_2);
        cleanup_and_exit(EXIT_FAILURE);
    }

    if (gpiod_line_request_output(line1, "valve_control", GPIO_LOW) < 0) {
        fprintf(stderr, "Failed to request output for GPIO %d\n", GPIO_PIN_1);
        cleanup_and_exit(EXIT_FAILURE);
    }

    if (gpiod_line_request_output(line2, "valve_control", GPIO_LOW) < 0) {
        fprintf(stderr, "Failed to request output for GPIO %d\n", GPIO_PIN_2);
        cleanup_and_exit(EXIT_FAILURE);
    }

    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    while (1) {
        activate_valve(GPIO_PIN_1, VALVE_1_DURATION);
        nanosleep((const struct timespec[]){{PAUSE_BETWEEN_VALVES_1 / 1000, (PAUSE_BETWEEN_VALVES_1 % 1000) * 1000 * 1000}}, NULL);
        activate_valve(GPIO_PIN_2, VALVE_2_DURATION);
        nanosleep((const struct timespec[]){{PAUSE_BETWEEN_VALVES_2 / 1000, (PAUSE_BETWEEN_VALVES_2 % 1000) * 1000 * 1000}}, NULL);
    }

    cleanup_and_exit(EXIT_SUCCESS);
}

#include <stdio.h>
#include <stdlib.h>
#include <signal.h>
#include <pigpio.h>
#include <errno.h>

#define I2C_BUS 1
#define I2C_ADDRESS 0x5A
#define RELAY_PIN 17
#define TOUCH_THRESHOLD 0x10
#define RELEASE_THRESHOLD 0x0A
#define FILTER_CHARGE_TIME 0x20
#define ELECTRODE_CURRENT 0x01
#define ELE_EN 0x20

volatile sig_atomic_t stop = 0;

void signal_handler(int signum) {
    stop = 1;
}

int main() {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Failed to initialize pigpio: %s\n", strerror(errno));
        return EXIT_FAILURE;
    }

    if (signal(SIGINT, signal_handler) == SIG_ERR || signal(SIGTERM, signal_handler) == SIG_ERR) {
        fprintf(stderr, "Failed to set signal handler: %s\n", strerror(errno));
        gpioTerminate();
        return EXIT_FAILURE;
    }

    if (i2cOpen(I2C_BUS, I2C_ADDRESS, 0) < 0) {
        fprintf(stderr, "Failed to open I2C bus: %s\n", strerror(errno));
        gpioTerminate();
        return EXIT_FAILURE;
    }

    if (gpioSetMode(I2C_BUS, I2C_ADDRESS, RELAY_PIN, PI_OUTPUT) < 0) {
        fprintf(stderr, "Failed to set GPIO mode: %s\n", strerror(errno));
        i2cClose(I2C_BUS);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    uint8_t write_buf[2] = {0x00, 0x00};
    uint8_t read_buf[2] = {0x00, 0x00};
    uint8_t touch_status = 0;

    write_buf[0] = 0x2B; // ELE_CFG
    write_buf[1] = 0x00; // Disable all electrodes
    if (i2cWriteFile(I2C_BUS, I2C_ADDRESS, write_buf, 2) < 0) {
        fprintf(stderr, "Failed to write to I2C device: %s\n", strerror(errno));
        i2cClose(I2C_BUS);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    write_buf[0] = 0x41; // MHD_R
    write_buf[1] = 0x01; // 1ms debounce
    if (i2cWriteFile(I2C_BUS, I2C_ADDRESS, write_buf, 2) < 0) {
        fprintf(stderr, "Failed to write to I2C device: %s\n", strerror(errno));
        i2cClose(I2C_BUS);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    write_buf[0] = 0x4B; // NHD_R
    write_buf[1] = 0xFF; // 0ms to 350ms (0x00-0x0F)
    if (i2cWriteFile(I2C_BUS, I2C_ADDRESS, write_buf, 2) < 0) {
        fprintf(stderr, "Failed to write to I2C device: %s\n", strerror(errno));
        i2cClose(I2C_BUS);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    write_buf[0] = 0x5B; // NCL_R
    write_buf[1] = 0xFF; // 0ms to 2000ms (0x00-0x7F)
    if (i2cWriteFile(I2C_BUS, I2C_ADDRESS, write_buf, 2) < 0) {
        fprintf(stderr, "Failed to write to I2C device: %s\n", strerror(errno));
        i2cClose(I2C_BUS);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    write_buf[0] = 0x6B; // FDL_R
    write_buf[1] = 0x01; // 0ms to 500ms (0x00-0x3F)
    if (i2cWriteFile(I2C_BUS, I2C_ADDRESS, write_buf, 2) < 0) {
        fprintf(stderr, "Failed to write to I2C device: %s\n", strerror(errno));
        i2cClose(I2C_BUS);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    write_buf[0] = 0x2A; // ELE_CFG
    write_buf[1] = ELE_EN; // Enable all electrodes
    if (i2cWriteFile(I2C_BUS, I2C_ADDRESS, write_buf, 2) < 0) {
        fprintf(stderr, "Failed to write to I2C device: %s\n", strerror(errno));
        i2cClose(I2C_BUS);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    write_buf[0] = 0x1D; // TOUCH_THRESH
    write_buf[1] = TOUCH_THRESHOLD;
    if (i2cWriteFile(I2C_BUS, I2C_ADDRESS, write_buf, 2) < 0) {
        fprintf(stderr, "Failed to write to I2C device: %s\n", strerror(errno));
        i2cClose(I2C_BUS);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    write_buf[0] = 0x1B; // RELEASE_THRESH
    write_buf[1] = RELEASE_THRESHOLD;
    if (i2cWriteFile(I2C_BUS, I2C_ADDRESS, write_buf, 2) < 0) {
        fprintf(stderr, "Failed to write to I2C device: %s\n", strerror(errno));
        i2cClose(I2C_BUS);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    write_buf[0] = 0x1F; // FILTER_CONFIG
    write_buf[1] = FILTER_CHARGE_TIME;
    if (i2cWriteFile(I2C_BUS, I2C_ADDRESS, write_buf, 2) < 0) {
        fprintf(stderr, "Failed to write to I2C device: %s\n", strerror(errno));
        i2cClose(I2C_BUS);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    write_buf[0] = 0x20; // ELECTRODE_CONFIG
    write_buf[1] = ELECTRODE_CURRENT;
    if (i2cWriteFile(I2C_BUS, I2C_ADDRESS, write_buf, 2) < 0) {
        fprintf(stderr, "Failed to write to I2C device: %s\n", strerror(errno));
        i2cClose(I2C_BUS);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    while (!stop) {
        usleep(100000); // 100ms delay

        write_buf[0] = 0x00; // TOUCH_STATUS
        if (i2cWriteFile(I2C_BUS, I2C_ADDRESS, write_buf, 1) < 0) {
            fprintf(stderr, "Failed to write to I2C device: %s\n", strerror(errno));
            break;
        }

        if (i2cReadFile(I2C_BUS, I2C_ADDRESS, read_buf, 2) < 0) {
            fprintf(stderr, "Failed to read from I2C device: %s\n", strerror(errno));
            break;
        }

        touch_status = read_buf[0] | (read_buf[1] << 8);
        if (touch_status > 0) {
            gpioWrite(RELAY_PIN, PI_HIGH);
            printf("Touch detected: 0x%X\n", touch_status);
        } else {
            gpioWrite(RELAY_PIN, PI_LOW);
        }
    }

    i2cClose(I2C_BUS);
    gpioTerminate();
    return EXIT_SUCCESS;
}

