#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <pigpio.h>

#define MOTION_PIN 17
#define RELAY_PIN 18
#define RATE_LIMIT_SECONDS 2
#define RELAY_ON_TIME 500
#define LOG_FILE "door_events.log"

FILE *log_file;
time_t last_motion_time;

void log_event(const char *event) {
    time_t now = time(NULL);
    struct tm *timeinfo = localtime(&now);
    char timestamp[20];
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", timeinfo);
    fprintf(log_file, "%s: %s\n", timestamp, event);
    fflush(log_file);
}

void on_motion_detected(gpioContext ctx, uint8_t level, uint64_t tick) {
    time_t now = time(NULL);
    if (difftime(now, last_motion_time) < RATE_LIMIT_SECONDS) {
        log_event("Rate-limited motion detected");
        return;
    }
    last_motion_time = now;
    log_event("Motion detected");
    gpioWrite(RELAY_PIN, 1);
    usleep(RELAY_ON_TIME * 1000);
    gpioWrite(RELAY_PIN, 0);
    log_event("Door unlocked");
}

void on_exit(int signum) {
    fclose(log_file);
    gpioTerminate();
    exit(signum);
}

int main() {
    signal(SIGINT, on_exit);
    atexit(on_exit);

    if (gpioInitialise() < 0) {
        fprintf(stderr, "Failed to initialize pigpio\n");
        exit(1);
    }

    log_file = fopen(LOG_FILE, "a");
    if (!log_file) {
        fprintf(stderr, "Failed to open log file\n");
        exit(1);
    }

    gpioSetMode(MOTION_PIN, PI_INPUT);
    gpioSetPullUpDown(MOTION_PIN, PI_PUD_DOWN);
    gpioSetAlertFunc(MOTION_PIN, on_motion_detected);

    gpioSetMode(RELAY_PIN, PI_OUTPUT);
    gpioWrite(RELAY_PIN, 0);

    log_event("Program started");

    while (1) {
        gpioDelay(50 * 1000);
    }

    return 0;
}

#include <stdio.h>
#include <stdlib.h>
#include <signal.h>
#include <time.h>
#include <pigpio.h>

volatile sig_atomic_t shutdown = 0;

void handle_sigint(int signum) {
    shutdown = 1;
}

int main() {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialization failed\n");
        return EXIT_FAILURE;
    }

    signal(SIGINT, handle_sigint);

    int motor1 = 17;
    int motor2 = 27;

    gpioSetMode(motor1, PI_OUTPUT);
    gpioSetMode(motor2, PI_OUTPUT);

    srand((unsigned int) time(NULL));

    while (!shutdown) {
        int pattern_length = rand() % 11 + 5; // 5 to 15 steps
        for (int i = 0; i < pattern_length && !shutdown; i++) {
            int duty_cycle1 = rand() % 256;
            int duty_cycle2 = rand() % 256;
            gpioPWM(motor1, duty_cycle1);
            gpioPWM(motor2, duty_cycle2);
            gpioDelay(50 + rand() % 151); // 50 to 200 ms
        }
    }

    gpioPWM(motor1, 0);
    gpioPWM(motor2, 0);

    gpioTerminate();

    return EXIT_SUCCESS;
}

#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <signal.h>
#include <time.h>
#include <pigpio.h>

#define HX711_DOUT 4
#define HX711_SCK 17
#define SOL_PIN 27
#define CALIBRATION_FILE "calibration.txt"
#define LOG_FILE "weight_log.txt"
#define DEFAULT_SCALE 1.0
#define DEFAULT_OFFSET 0.0
#define CALIBRATION_SAMPLES 100
#define WEIGHT_THRESHOLD 10.0
#define READ_INTERVAL 500

volatile sig_atomic_t stop = 0;

void signal_handler(int signum) {
    stop = 1;
}

int main() {
    FILE *cal_file, *log_file;
    double scale_factor = DEFAULT_SCALE, offset = DEFAULT_OFFSET;
    long long raw_value;
    double weight;
    time_t timestamp;
    struct tm *timeinfo;
    char buffer[80];

    if ((cal_file = fopen(CALIBRATION_FILE, "r")) != NULL) {
        fscanf(cal_file, "%lf %lf", &scale_factor, &offset);
        fclose(cal_file);
    }

    if ((log_file = fopen(LOG_FILE, "a")) == NULL) {
        fprintf(stderr, "Error opening log file\n");
        return EXIT_FAILURE;
    }

    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialization failed\n");
        return EXIT_FAILURE;
    }

    signal(SIGINT, signal_handler);

    gpioSetMode(HX711_SCK, PI_OUTPUT);
    gpioSetMode(SOL_PIN, PI_OUTPUT);

    for (int i = 0; i < CALIBRATION_SAMPLES; i++) {
        raw_value = 0;
        for (int j = 0; j < 24; j++) {
            gpioWrite(HX711_SCK, PI_HIGH);
            gpioDelay(1);
            raw_value = (raw_value << 1) | gpioRead(HX711_DOUT);
            gpioDelay(1);
            gpioWrite(HX711_SCK, PI_LOW);
            gpioDelay(1);
        }
        gpioWrite(HX711_SCK, PI_HIGH);
        gpioDelay(1);
        gpioWrite(HX711_SCK, PI_LOW);
        gpioDelay(1);
        offset += raw_value;
    }
    offset /= CALIBRATION_SAMPLES;

    while (!stop) {
        raw_value = 0;
        for (int j = 0; j < 24; j++) {
            gpioWrite(HX711_SCK, PI_HIGH);
            gpioDelay(1);
            raw_value = (raw_value << 1) | gpioRead(HX711_DOUT);
            gpioDelay(1);
            gpioWrite(HX711_SCK, PI_LOW);
            gpioDelay(1);
        }
        gpioWrite(HX711_SCK, PI_HIGH);
        gpioDelay(1);
        gpioWrite(HX711_SCK, PI_LOW);
        gpioDelay(1);

        weight = (raw_value - offset) * scale_factor;

        if (weight > WEIGHT_THRESHOLD) {
            gpioWrite(SOL_PIN, PI_HIGH);
        } else {
            gpioWrite(SOL_PIN, PI_LOW);
        }

        time(&timestamp);
        timeinfo = localtime(&timestamp);
        strftime(buffer, sizeof(buffer), "%Y-%m-%d %H:%M:%S", timeinfo);
        fprintf(log_file, "%s %.2f kg\n", buffer, weight);

        sleep(READ_INTERVAL);
    }

    gpioTerminate();
    fclose(log_file);

    return EXIT_SUCCESS;
}

#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <unistd.h>
#include <signal.h>
#include <time.h>
#include <syslog.h>
#include <pigpio.h>

#define RAIN_SENSOR 4
#define MOTOR_IN1 17
#define MOTOR_IN2 18
#define MOTOR_PWM 27
#define RAIN_DETECTED_THRESHOLD 3
#define MOTOR_RUN_TIME 5
#define CHECK_INTERVAL 60
#define LOG_FILE "/var/log/window_control.log"

volatile sig_atomic_t stop = 0;

void signal_handler(int signum) {
    stop = 1;
}

int main() {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Failed to initialize GPIO\n");
        return EXIT_FAILURE;
    }

    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    openlog("window_control", LOG_PID, LOG_USER);

    int rain_count = 0;
    time_t last_check_time = time(NULL);
    int motor_running = 0;

    while (!stop) {
        if (time(NULL) - last_check_time >= CHECK_INTERVAL) {
            last_check_time = time(NULL);
            rain_count = 0;

            for (int i = 0; i < RAIN_DETECTED_THRESHOLD; i++) {
                if (gpioRead(RAIN_SENSOR) == 0) {
                    rain_count++;
                    sleep(0.05);
                }
            }

            if (rain_count >= RAIN_DETECTED_THRESHOLD) {
                if (!motor_running) {
                    syslog(LOG_INFO, "Rain detected, closing window");
                    gpioSetMode(MOTOR_IN1, PI_OUTPUT);
                    gpioSetMode(MOTOR_IN2, PI_OUTPUT);
                    gpioSetMode(MOTOR_PWM, PI_OUTPUT);
                    gpioWrite(MOTOR_IN1, 1);
                    gpioWrite(MOTOR_IN2, 0);
                    gpioHardwarePWM(MOTOR_PWM, 1000, 150);
                    sleep(MOTOR_RUN_TIME);
                    gpioWrite(MOTOR_IN1, 0);
                    gpioWrite(MOTOR_IN2, 0);
                    gpioHardwarePWM(MOTOR_PWM, 0, 0);
                    motor_running = 1;
                }
            } else {
                if (motor_running) {
                    syslog(LOG_INFO, "No rain, motor stopped");
                    gpioWrite(MOTOR_IN1, 0);
                    gpioWrite(MOTOR_IN2, 0);
                    gpioHardwarePWM(MOTOR_PWM, 0, 0);
                    motor_running = 0;
                }
            }
        }
    }

    closelog();
    gpioTerminate();
    return EXIT_SUCCESS;
}

#include <stdio.h>
#include <stdlib.h>
#include <signal.h>
#include <time.h>
#include <pigpio.h>

#define SCALE 2280.0f // This value should be adjusted based on the load cell used
#define THRESHOLD 100 // Threshold in grams
#define SOLENOID_PIN 17
#define LOADCELL_DT_PIN 23
#define LOADCELL_SCK_PIN 24
#define LOG_FILE "stock_events.txt"

volatile sig_atomic_t stop = 0;

void signal_handler(int signum) {
    stop = 1;
}

int main() {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialization failed\n");
        return EXIT_FAILURE;
    }

    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    FILE *log_file = fopen(LOG_FILE, "a");
    if (!log_file) {
        fprintf(stderr, "Failed to open log file\n");
        gpioTerminate();
        return EXIT_FAILURE;
    }

    int solenoid_pin = gpioOpen(SOLENOID_PIN, PI_OUTPUT);
    if (solenoid_pin < 0) {
        fprintf(stderr, "Failed to open solenoid pin\n");
        fclose(log_file);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    int dt_pin = gpioOpen(LOADCELL_DT_PIN, PI_INPUT);
    if (dt_pin < 0) {
        fprintf(stderr, "Failed to open data pin\n");
        gpioClose(solenoid_pin);
        fclose(log_file);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    int sck_pin = gpioOpen(LOADCELL_SCK_PIN, PI_OUTPUT);
    if (sck_pin < 0) {
        fprintf(stderr, "Failed to open clock pin\n");
        gpioClose(solenoid_pin);
        gpioClose(dt_pin);
        fclose(log_file);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    while (!stop) {
        int value = 0;
        for (int i = 0; i < 10; i++) {
            gpioWrite(sck_pin, PI_HIGH);
            gpioDelay(1);
            value = (value << 1) | gpioRead(dt_pin);
            gpioWrite(sck_pin, PI_LOW);
            gpioDelay(1);
        }

        float weight = value / SCALE;
        if (weight < THRESHOLD) {
            gpioWrite(solenoid_pin, PI_HIGH);
            gpioDelay(5000000); // 5 seconds
            gpioWrite(solenoid_pin, PI_LOW);

            time_t now = time(NULL);
            struct tm *t = localtime(&now);
            fprintf(log_file, "%d-%02d-%02d %02d:%02d:%02d - Ingredient ran out\n",
                    t->tm_year + 1900, t->tm_mon + 1, t->tm_mday,
                    t->tm_hour, t->tm_min, t->tm_sec);
            fflush(log_file);
        }

        gpioDelay(1000000); // 1 second
    }

    gpioClose(solenoid_pin);
    gpioClose(dt_pin);
    gpioClose(sck_pin);
    fclose(log_file);
    gpioTerminate();

    return EXIT_SUCCESS;
}

#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <signal.h>
#include <time.h>
#include <pigpio.h>

#define HX711_DOUT 4
#define HX711_SCK 17
#define SOL_PIN 27
#define CALIBRATION_FILE "calibration.txt"
#define SECURITY_LOG "security.log"

volatile sig_atomic_t stop = 0;

void sigint_handler(int signum) {
    stop = 1;
}

int read_hx711() {
    int data = 0;
    for (int i = 0; i < 24; i++) {
        gpio_set_mode(HX711_SCK, PI_OUTPUT);
        gpio_write(HX711_SCK, PI_LOW);
        gpio_delay(1);
        gpio_write(HX711_SCK, PI_HIGH);
        gpio_delay(1);
        data = (data << 1) | gpio_read(HX711_DOUT);
    }
    gpio_set_mode(HX711_SCK, PI_OUTPUT);
    gpio_write(HX711_SCK, PI_LOW);
    gpio_delay(1);
    return data;
}

int main() {
    FILE *calibration_file;
    float calibration_factor;
    struct timespec ts;
    char buffer[100];

    if (gpioInitialise() < 0) {
        printf("Failed to initialize pigpio\n");
        return 1;
    }

    signal(SIGINT, sigint_handler);

    if ((calibration_file = fopen(CALIBRATION_FILE, "r")) == NULL) {
        printf("Failed to open calibration file\n");
        return 1;
    }

    if (fscanf(calibration_file, "%f", &calibration_factor) != 1) {
        printf("Failed to read calibration factor\n");
        return 1;
    }

    fclose(calibration_file);

    while (!stop) {
        int raw = read_hx711();
        float weight = raw / calibration_factor;

        if (weight > 5.0) {
            clock_gettime(CLOCK_REALTIME, &ts);
            sprintf(buffer, "%ld.%09ld %f\n", ts.tv_sec, ts.tv_nsec, weight);
            FILE *security_log = fopen(SECURITY_LOG, "a");
            if (security_log == NULL) {
                printf("Failed to open security log\n");
                return 1;
            }
            fputs(buffer, security_log);
            fclose(security_log);

            gpio_set_mode(SOL_PIN, PI_OUTPUT);
            gpio_write(SOL_PIN, PI_HIGH);
            gpio_delay(5000000);
            gpio_write(SOL_PIN, PI_LOW);
        }
    }

    gpioTerminate();
    return 0;
}

#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <libgpiod.h>

#define SENSOR_GPIO 16
#define RELAY_GPIO 20
#define LOG_FILE "relay_events.log"

static gpiod_chip *chip;
static gpiod_line_bulk lines;
static FILE *log_file;

void cleanup_and_exit(int status) {
    if (log_file) fclose(log_file);
    if (chip) gpiod_chip_close(chip);
    exit(status);
}

void handle_signal(int signum) {
    cleanup_and_exit(EXIT_SUCCESS);
}

int main() {
    struct sigaction action;
    memset(&action, 0, sizeof(struct sigaction));
    action.sa_handler = handle_signal;
    sigaction(SIGINT, &action, NULL);
    sigaction(SIGTERM, &action, NULL);

    chip = gpiod_chip_open_by_name("gpiochip0");
    if (!chip) {
        fprintf(stderr, "Failed to open GPIO chip\n");
        cleanup_and_exit(EXIT_FAILURE);
    }

    lines.offsets[0] = SENSOR_GPIO;
    lines.offsets[1] = RELAY_GPIO;
    lines.count = 2;

    if (gpiod_chip_get_lines(chip, &lines) < 0) {
        fprintf(stderr, "Failed to get GPIO lines\n");
        cleanup_and_exit(EXIT_FAILURE);
    }

    if (gpiod_line_request_bulk(chip, &lines, "input", GPIOD_LINE_REQUEST_FLAG_BIAS_PULL_DOWN) < 0) {
        fprintf(stderr, "Failed to request GPIO lines as inputs\n");
        cleanup_and_exit(EXIT_FAILURE);
    }

    if (gpiod_line_request_bulk(chip, &lines + 1, "output", GPIOD_LINE_REQUEST_FLAG_BIAS_PULL_UP) < 0) {
        fprintf(stderr, "Failed to request GPIO lines as outputs\n");
        cleanup_and_exit(EXIT_FAILURE);
    }

    log_file = fopen(LOG_FILE, "a");
    if (!log_file) {
        fprintf(stderr, "Failed to open log file\n");
        cleanup_and_exit(EXIT_FAILURE);
    }

    int relay_state = 0;
    while (1) {
        if (gpiod_line_get_value(chip, SENSOR_GPIO) == 0) {
            relay_state = !relay_state;
            gpiod_line_set_value(chip, RELAY_GPIO, relay_state);
            time_t now = time(NULL);
            struct tm *timeinfo = localtime(&now);
            char timestamp[20];
            strftime(timestamp, sizeof(timestamp), "%Y-%m-%dT%H:%M:%S", timeinfo);
            fprintf(log_file, "%s: Relay state is now %d\n", timestamp, relay_state);
            fflush(log_file);
        }
    }

    cleanup_and_exit(EXIT_SUCCESS);
}

