#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <unistd.h>
#include <signal.h>
#include <libgpiod.h>

#define GPIO_PIN 18
#define CONFIG_FILE "watering.conf"

volatile sig_atomic_t stop_requested = 0;

void sig_handler(int signum) {
    stop_requested = 1;
}

int main() {
    struct gpiod_chip *chip;
    struct gpiod_line *line;
    struct sigaction action;
    char buffer[256];
    int duration;
    FILE *file;

    // Set up signal handler
    memset(&action, 0, sizeof(action));
    action.sa_handler = sig_handler;
    sigaction(SIGINT, &action, NULL);
    sigaction(SIGTERM, &action, NULL);

    // Open GPIO chip
    chip = gpiod_chip_open("/dev/gpiochip0");
    if (!chip) {
        fprintf(stderr, "Failed to open GPIO chip\n");
        return EXIT_FAILURE;
    }

    // Request GPIO line
    line = gpiod_chip_get_line(chip, GPIO_PIN);
    if (!line) {
        fprintf(stderr, "Failed to get GPIO line\n");
        gpiod_chip_close(chip);
        return EXIT_FAILURE;
    }

    // Set up GPIO line
    struct gpiod_line_request request = {
        .consumer = "watering_system",
        .request_type = GPIOD_LINE_REQUEST_OUTPUT,
        .flags = GPIOD_LINE_FLAG_ACTIVE_LOW,
        .default_value = 0,
    };
    if (gpiod_line_request(line, &request)) {
        fprintf(stderr, "Failed to request GPIO line\n");
        gpiod_chip_close(chip);
        gpiod_line_release(line);
        return EXIT_FAILURE;
    }

    // Read duration from config file
    file = fopen(CONFIG_FILE, "r");
    if (!file) {
        fprintf(stderr, "Failed to open config file\n");
        gpiod_chip_close(chip);
        gpiod_line_release(line);
        return EXIT_FAILURE;
    }
    if (fgets(buffer, sizeof(buffer), file) && sscanf(buffer, "duration=%d", &duration) == 1 && duration >= 1 && duration <= 3600) {
        printf("Configured duration: %d seconds\n", duration);
    } else {
        fprintf(stderr, "Invalid duration in config file\n");
        gpiod_chip_close(chip);
        gpiod_line_release(line);
        fclose(file);
        return EXIT_FAILURE;
    }
    fclose(file);

    // Turn valve on
    gpiod_line_set_value(line, 1);
    printf("Valve on\n");

    // Wait for duration
    sleep(duration);

    // Turn valve off
    gpiod_line_set_value(line, 0);
    printf("Valve off\n");

    // Release resources
    gpiod_line_release(line);
    gpiod_chip_close(chip);

    return EXIT_SUCCESS;
}

#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <pigpio.h>

#define BASE_SPEED 150
#define LEFT_HALF_SPEED (BASE_SPEED / 2)
#define RIGHT_HALF_SPEED (BASE_SPEED / 2)
#define SENSOR_PIN_1 4
#define SENSOR_PIN_2 17
#define SENSOR_PIN_3 27
#define MOTOR_PIN_1 22
#define MOTOR_PIN_2 23
#define MOTOR_PIN_3 24
#define MOTOR_PIN_4 25
#define PWM_FREQ 1000
#define LOG_FILE_NAME "trace_log.txt"

FILE *log_file;
int left_speed = BASE_SPEED;
int right_speed = BASE_SPEED;

void stop_motors() {
    gpioSetPWMdutycycle(MOTOR_PIN_1, 0);
    gpioSetPWMdutycycle(MOTOR_PIN_2, 0);
    gpioSetPWMdutycycle(MOTOR_PIN_3, 0);
    gpioSetPWMdutycycle(MOTOR_PIN_4, 0);
}

void cleanup(int signum) {
    stop_motors();
    fclose(log_file);
    gpioTerminate();
    exit(signum);
}

void log_cycle(int sensor_1, int sensor_2, int sensor_3) {
    time_t rawtime;
    struct tm *timeinfo;
    char buffer[20];

    time(&rawtime);
    timeinfo = localtime(&rawtime);
    strftime(buffer, sizeof(buffer), "%Y-%m-%dT%H:%M:%S", timeinfo);

    fprintf(log_file, "%s, %d, %d, %d, %d, %d\n", buffer, sensor_1, sensor_2, sensor_3, left_speed, right_speed);
}

int main() {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Failed to initialize pigpio\n");
        return EXIT_FAILURE;
    }

    signal(SIGINT, cleanup);

    log_file = fopen(LOG_FILE_NAME, "w");
    if (log_file == NULL) {
        fprintf(stderr, "Failed to open log file\n");
        cleanup(EXIT_FAILURE);
    }

    gpioSetMode(SENSOR_PIN_1, PI_INPUT);
    gpioSetMode(SENSOR_PIN_2, PI_INPUT);
    gpioSetMode(SENSOR_PIN_3, PI_INPUT);
    gpioSetMode(MOTOR_PIN_1, PI_OUTPUT);
    gpioSetMode(MOTOR_PIN_2, PI_OUTPUT);
    gpioSetMode(MOTOR_PIN_3, PI_OUTPUT);
    gpioSetMode(MOTOR_PIN_4, PI_OUTPUT);

    gpioSetPWMfrequency(MOTOR_PIN_1, PWM_FREQ);
    gpioSetPWMfrequency(MOTOR_PIN_2, PWM_FREQ);
    gpioSetPWMfrequency(MOTOR_PIN_3, PWM_FREQ);
    gpioSetPWMfrequency(MOTOR_PIN_4, PWM_FREQ);

    while (1) {
        int sensor_1 = gpioRead(SENSOR_PIN_1);
        int sensor_2 = gpioRead(SENSOR_PIN_2);
        int sensor_3 = gpioRead(SENSOR_PIN_3);

        log_cycle(sensor_1, sensor_2, sensor_3);

        if (sensor_1 == 0 && sensor_2 == 0 && sensor_3 == 0) {
            stop_motors();
        } else if (sensor_1 == 0 && sensor_2 == 0) {
            gpioSetPWMdutycycle(MOTOR_PIN_1, left_speed);
            gpioSetPWMdutycycle(MOTOR_PIN_2, 0);
            gpioSetPWMdutycycle(MOTOR_PIN_3, right_speed);
            gpioSetPWMdutycycle(MOTOR_PIN_4, 0);
        } else if (sensor_1 == 0) {
            gpioSetPWMdutycycle(MOTOR_PIN_1, left_speed);
            gpioSetPWMdutycycle(MOTOR_PIN_2, 0);
            gpioSetPWMdutycycle(MOTOR_PIN_3, BASE_SPEED);
            gpioSetPWMdutycycle(MOTOR_PIN_4, 0);
        } else if (sensor_3 == 0) {
            gpioSetPWMdutycycle(MOTOR_PIN_1, 0);
            gpioSetPWMdutycycle(MOTOR_PIN_2, 0);
            gpioSetPWMdutycycle(MOTOR_PIN_3, right_speed);
            gpioSetPWMdutycycle(MOTOR_PIN_4, 0);
        } else {
            gpioSetPWMdutycycle(MOTOR_PIN_1, BASE_SPEED);
            gpioSetPWMdutycycle(MOTOR_PIN_2, 0);
            gpioSetPWMdutycycle(MOTOR_PIN_3, BASE_SPEED);
            gpioSetPWMdutycycle(MOTOR_PIN_4, 0);
        }

        usleep(10000);
    }

    return EXIT_SUCCESS;
}

#include <stdio.h>
#include <stdlib.h>
#include <signal.h>
#include <pigpio.h>

#define SERVO_PIN 18
#define LOCK_BUTTON_PIN 21
#define UNLOCK_BUTTON_PIN 22
#define DEBOUNCE_TIME 100
#define LOCK_PULSE_WIDTH 1000
#define UNLOCK_PULSE_WIDTH 2000
#define SERVO_MIN_PULSE_WIDTH 500
#define SERVO_MAX_PULSE_WIDTH 2500

volatile sig_atomic_t stop = 0;

void signal_handler(int signum) {
    stop = 1;
}

int main() {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Failed to initialize pigpio library\n");
        return EXIT_FAILURE;
    }

    signal(SIGINT, signal_handler);

    if (gpioSetMode(SERVO_PIN, PI_OUTPUT) < 0) {
        fprintf(stderr, "Failed to set GPIO%d mode to output\n", SERVO_PIN);
        goto cleanup;
    }

    if (gpioSetPullUpDown(LOCK_BUTTON_PIN, PI_PUD_UP) < 0) {
        fprintf(stderr, "Failed to set GPIO%d pull-up/down\n", LOCK_BUTTON_PIN);
        goto cleanup;
    }

    if (gpioSetPullUpDown(UNLOCK_BUTTON_PIN, PI_PUD_UP) < 0) {
        fprintf(stderr, "Failed to set GPIO%d pull-up/down\n", UNLOCK_BUTTON_PIN);
        goto cleanup;
    }

    while (!stop) {
        if (gpioRead(LOCK_BUTTON_PIN) == 0) {
            gpioServo(SERVO_PIN, LOCK_PULSE_WIDTH);
            gpioDelay(DEBOUNCE_TIME * 1000);
        }

        if (gpioRead(UNLOCK_BUTTON_PIN) == 0) {
            gpioServo(SERVO_PIN, UNLOCK_PULSE_WIDTH);
            gpioDelay(DEBOUNCE_TIME * 1000);
        }

        gpioServo(SERVO_PIN, 0); // Constrain the servo pulse width to the safe range
    }

    printf("Exiting...\n");

cleanup:
    gpioTerminate();
    return EXIT_FAILURE;
}

#include <stdio.h>
#include <stdlib.h>
#include <signal.h>
#include <gpiod.h>

#define MOTOR1_PIN 17
#define MOTOR2_PIN 27
#define MOTOR_DURATION1 200
#define MOTOR_DURATION2 300

static gpiod_chip *chip;
static gpiod_line *motor1_line;
static gpiod_line *motor2_line;

void cleanup_and_exit(int exit_code) {
    if (motor1_line) {
        gpiod_line_release(motor1_line);
    }
    if (motor2_line) {
        gpiod_line_release(motor2_line);
    }
    if (chip) {
        gpiod_chip_close(chip);
    }
    exit(exit_code);
}

void handle_signal(int signum) {
    printf("Received signal %d, stopping motors...\n", signum);
    cleanup_and_exit(EXIT_SUCCESS);
}

int main() {
    struct sigaction sa;
    sa.sa_handler = handle_signal;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;

    if (sigaction(SIGINT, &sa, NULL) == -1) {
        perror("Failed to register SIGINT handler");
        return EXIT_FAILURE;
    }
    if (sigaction(SIGTERM, &sa, NULL) == -1) {
        perror("Failed to register SIGTERM handler");
        return EXIT_FAILURE;
    }

    chip = gpiod_chip_open("/dev/gpiochip0");
    if (!chip) {
        perror("Failed to open GPIO chip");
        return EXIT_FAILURE;
    }

    motor1_line = gpiod_chip_get_line(chip, MOTOR1_PIN);
    if (!motor1_line) {
        perror("Failed to get motor 1 line");
        cleanup_and_exit(EXIT_FAILURE);
    }

    motor2_line = gpiod_chip_get_line(chip, MOTOR2_PIN);
    if (!motor2_line) {
        perror("Failed to get motor 2 line");
        cleanup_and_exit(EXIT_FAILURE);
    }

    if (gpiod_line_request_output(motor1_line, "motor1", 0) < 0) {
        perror("Failed to request motor 1 line as output");
        cleanup_and_exit(EXIT_FAILURE);
    }

    if (gpiod_line_request_output(motor2_line, "motor2", 0) < 0) {
        perror("Failed to request motor 2 line as output");
        cleanup_and_exit(EXIT_FAILURE);
    }

    while (1) {
        if (gpiod_line_set_value(motor1_line, 1) < 0) {
            perror("Failed to set motor 1 line value");
            cleanup_and_exit(EXIT_FAILURE);
        }
        usleep(MOTOR_DURATION1 * 1000);
        if (gpiod_line_set_value(motor1_line, 0) < 0) {
            perror("Failed to set motor 1 line value");
            cleanup_and_exit(EXIT_FAILURE);
        }

        if (gpiod_line_set_value(motor2_line, 1) < 0) {
            perror("Failed to set motor 2 line value");
            cleanup_and_exit(EXIT_FAILURE);
        }
        usleep(MOTOR_DURATION2 * 1000);
        if (gpiod_line_set_value(motor2_line, 0) < 0) {
            perror("Failed to set motor 2 line value");
            cleanup_and_exit(EXIT_FAILURE);
        }
    }

    cleanup_and_exit(EXIT_SUCCESS);
}

