    if (line) {
        gpiod_line_release(line);
    }
    if (chip) {
        gpiod_chip_close(chip);
    }
    if (sub_sock) {
        zsock_destroy(&sub_sock);
    }
    if (pub_sock) {
        zsock_destroy(&pub_sock);
    }
}

static void handle_sigint(int signum) {
    cleanup();
    exit(0);
}

int main(int argc, char *argv[]) {
    if (argc != 2) {
        fprintf(stderr, "Usage: %s <mode>\n", argv[0]);
        return EXIT_FAILURE;
    }

    const char *mode = argv[1];
    if (strcmp(mode, SOUND_SENSOR_MODE) == 0) {
        // Sound sensor mode
        chip = gpiod_chip_open_by_name("gpiochip0");
        if (!chip) {
            fprintf(stderr, "Failed to open GPIO chip\n");
            return EXIT_FAILURE;
        }

        line = gpiod_chip_get_line(chip, GPIO17);
        if (!line) {
            fprintf(stderr, "Failed to get GPIO line\n");
            return EXIT_FAILURE;
        }

        if (gpiod_line_request_input(line, "sound_sensor") < 0) {
            fprintf(stderr, "Failed to request GPIO line as input\n");
            return EXIT_FAILURE;
        }

        pub_sock = zsock_new_pub("tcp://*:5555");
        if (!pub_sock) {
            fprintf(stderr, "Failed to create publisher socket\n");
            return EXIT_FAILURE;
        }

        zmq_msg_t msg;
        zmq_msg_init_size(&msg, 1);
        char *data = zmq_msg_data(&msg);

        while (1) {
            if (gpiod_line_get_value(line) == 0) {
                *data = '1';
                zmq_msg_send(&msg, pub_sock, ZMQ_SNDMORE);
                zmq_msg_set_data(&msg, "SOUND_ALERT", 12);
                zmq_msg_send(&msg, pub_sock, 0);
            } else {
                *data = '0';
                zmq_msg_send(&msg, pub_sock, ZMQ_SNDMORE);
                zmq_msg_set_data(&msg, "SOUND_ALERT", 12);
                zmq_msg_send(&msg, pub_sock, 0);
            }
            usleep(10000);
        }
    } else if (strcmp(mode, ALARM_NODE_MODE) == 0) {
        // Alarm node mode
        sub_sock = zsock_new_sub("tcp://localhost:5555", "SOUND_ALERTS");
        if (!sub_sock) {
            fprintf(stderr, "Failed to create subscriber socket\n");
            return EXIT_FAILURE;
        }

        chip = gpiod_chip_open_by_name("gpiochip0");
        if (!chip) {
            fprintf(stderr, "Failed to open GPIO chip\n");
            return EXIT_FAILURE;
        }

        line = gpiod_chip_get_line(chip, GPIO27);
        if (!line) {
            fprintf(stderr, "Failed to get GPIO line\n");
            return EXIT_FAILURE;
        }

        if (gpiod_line_request_output(line, "alarm_led", 0) < 0) {
            fprintf(stderr, "Failed to request GPIO line as output\n");
            return EXIT_FAILURE;
        }

        zmq_msg_t msg;
        while (1) {
            zmq_msg_init(&msg);
            zmq_msg_recv(&msg, sub_sock, 0);
            gpiod_line_set_value(line, 1);
            usleep(1000000);
            gpiod_line_set_value(line, 0);
        }
    } else {
        fprintf(stderr, "Invalid mode: %s\n", mode);
        return EXIT_FAILURE;
    }

    atexit(cleanup);
    signal(SIGINT, handle_sigint);
    signal(SIGTERM, handle_sigint);

    while (1) {
        sleep(1);
    }

    return EXIT_SUCCESS;
}

#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <stdbool.h>
#include <signal.h>
#include <syslog.h>
#include <unistd.h>
#include <pigpio.h>
#include <mosquitto.h>

#define GPIO_PIN 17
#define PULSE_BUFFER_SIZE 1000
#define NEC_HEADER_MARK 9000
#define NEC_HEADER_SPACE 4500
#define NEC_BIT_MARK 560
#define NEC_ONE_SPACE 1690
#define NEC_ZERO_SPACE 560
#define NEC_REPEAT_SPACE 1120
#define NEC_BIT_LENGTH 24
#define NEC_ADDRESS_LENGTH 16
#define NEC_COMMAND_LENGTH 8

volatile sig_atomic_t running = true;

void handle_sigint(int signum) {
    running = false;
}

void handle_sigterm(int signum) {
    running = false;
}

void alert_callback(uint32_t gpio, uint32_t level, uint32_t tick) {
    static uint32_t last_tick = 0;
    static uint32_t pulse_buffer[PULSE_BUFFER_SIZE];
    static uint8_t pulse_count = 0;
    uint32_t duration = tick - last_tick;
    last_tick = tick;

    if (level == 0) {
        if (pulse_count < PULSE_BUFFER_SIZE) {
            pulse_buffer[pulse_count++] = duration;
        }
    } else {
        if (pulse_count > 0) {
            pulse_count = 0;
        }
    }
}

bool decode_nec(uint32_t *address, uint32_t *command) {
    uint8_t bit_count = 0;
    uint32_t bit_mask = 1 << (NEC_BIT_LENGTH - 1);
    uint32_t address_value = 0;
    uint32_t command_value = 0;

    for (uint8_t i = 0; i < PULSE_BUFFER_SIZE; i++) {
        uint32_t duration = pulse_buffer[i];

        if (duration > NEC_BIT_MARK) {
            if (duration < NEC_ONE_SPACE) {
                command_value |= bit_mask;
            } else if (duration > NEC_ONE_SPACE && duration < NEC_REPEAT_SPACE) {
                address_value |= bit_mask;
            } else {
                return false;
            }

            bit_mask >>= 1;
            bit_count++;

            if (bit_count == NEC_BIT_LENGTH) {
                *address = address_value;
                *command = command_value;
                return true;
            }
        }
    }

    return false;
}

void publish_mqtt(uint32_t address, uint32_t command) {
    mosquitto *mqtt_client = mosquitto_new(NULL, true, NULL);
    if (!mqtt_client) {
        syslog(LOG_ERR, "Failed to create MQTT client");
        return;
    }

    char json[128];
    snprintf(json, sizeof(json), "{\"address\":%u,\"command\":%u}", address, command);

    if (mosquitto_publish(mqtt_client, NULL, "ir/decoded", strlen(json), json, 0, false) != MOSQ_ERR_SUCCESS) {
        syslog(LOG_ERR, "Failed to publish MQTT message");
    }

    mosquitto_destroy(mqtt_client);
}

int main() {
    openlog("ir_decoder", LOG_PID, LOG_USER);

    if (gpioInitialise() < 0) {
        syslog(LOG_ERR, "Failed to initialize pigpio");
        closelog();
        return EXIT_FAILURE;
    }

    struct sigaction sigint_action = { .sa_handler = handle_sigint };
    struct sigaction sigterm_action = { .sa_handler = handle_sigterm };
    sigaction(SIGINT, &sigint_action, NULL);
    sigaction(SIGTERM, &sigterm_action, NULL);

    if (gpioSetAlertFunc(GPIO_PIN, alert_callback) < 0) {
        syslog(LOG_ERR, "Failed to set alert function for GPIO %d", GPIO_PIN);
        gpioTerminate();
        closelog();
        return EXIT_FAILURE;
    }

    mosquitto_lib_init();

    while (running) {
        uint32_t address, command;

        if (decode_nec(&address, &command)) {
            syslog(LOG_INFO, "Decoded address: %u, command: %u", address, command);
            publish_mqtt(address, command);
        }

        usleep(1000);
    }

    mosquitto_lib_cleanup();
    gpioTerminate();
    closelog();

    return EXIT_SUCCESS;
}

#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <unistd.h>
#include <fcntl.h>
#include <sys/ioctl.h>
#include <linux/i2c-dev.h>
#include <sys/socket.h>
#include <netinet/in.h>
#include <arpa/inet.h>
#include <signal.h>
#include <time.h>

#define MULTICAST_ADDR "239.255.255.250"
#define MULTICAST_PORT 5005
#define SENSOR_COUNT 4

volatile sig_atomic_t exit_flag = 0;

void signal_handler(int signum) {
    exit_flag = 1;
}

int main() {
    struct sigaction action;
    memset(&action, 0, sizeof(action));
    action.sa_handler = signal_handler;
    sigaction(SIGINT, &action, NULL);
    sigaction(SIGTERM, &action, NULL);

    int i2c_fd[SENSOR_COUNT];
    int udp_fd;
    struct sockaddr_in udp_addr;
    char buffer[256];
    int lux[SENSOR_COUNT];
    int sensor_id[SENSOR_COUNT] = {1, 2, 3, 4};

    for (int i = 0; i < SENSOR_COUNT; i++) {
        i2c_fd[i] = open("/dev/i2c-1", O_RDWR);
        if (i2c_fd[i] < 0) {
            perror("Failed to open I2C device");
            return EXIT_FAILURE;
        }
        if (ioctl(i2c_fd[i], I2C_SLAVE, 0x23 + i) < 0) {
            perror("Failed to set I2C slave address");
            return EXIT_FAILURE;
        }
        if (write(i2c_fd[i], "\x20", 1) != 1) {
            perror("Failed to write to I2C device");
            return EXIT_FAILURE;
        }
        usleep(180000);
        if (read(i2c_fd[i], buffer, 2) != 2) {
            perror("Failed to read from I2C device");
            return EXIT_FAILURE;
        }
        lux[i] = ((buffer[0] << 8) | buffer[1]) / 1.2;
    }

    udp_fd = socket(AF_INET, SOCK_DGRAM, 0);
    if (udp_fd < 0) {
        perror("Failed to create UDP socket");
        return EXIT_FAILURE;
    }
    memset(&udp_addr, 0, sizeof(udp_addr));
    udp_addr.sin_family = AF_INET;
    udp_addr.sin_addr.s_addr = inet_addr(MULTICAST_ADDR);
    udp_addr.sin_port = htons(MULTICAST_PORT);

    while (!exit_flag) {
        for (int i = 0; i < SENSOR_COUNT; i++) {
            sprintf(buffer, "%d,%d", sensor_id[i], lux[i]);
            if (sendto(udp_fd, buffer, strlen(buffer), 0, (struct sockaddr *)&udp_addr, sizeof(udp_addr)) < 0) {
                perror("Failed to send UDP packet");
                return EXIT_FAILURE;
            }
        }
        sleep(1);
    }

    for (int i = 0; i < SENSOR_COUNT; i++) {
        close(i2c_fd[i]);
    }
    close(udp_fd);

    return EXIT_SUCCESS;
}

#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <string.h>
#include <unistd.h>
#include <fcntl.h>
#include <sys/ioctl.h>
#include <linux/i2c-dev.h>
#include <signal.h>
#include <time.h>

#define I2C_BUS "/dev/i2c-1"
#define SENSOR_ADDRESS 0x28
#define FLOW_SENSOR_REG 0x00
#define FLOW_SENSOR_MASK 0x3FFF
#define FLOW_SENSOR_OFFSET 3277
#define FLOW_SENSOR_CONVERSION 0.1
#define RETRY_COUNT 3
#define RETRY_DELAY 100

static int i2c_fd = -1;
static FILE *log_file = NULL;

void sigint_handler(int signum) {
    if (i2c_fd != -1) {
        close(i2c_fd);
    }
    if (log_file != NULL) {
        fclose(log_file);
    }
    exit(0);
}

int main() {
    struct sigaction sigint_action;
    memset(&sigint_action, 0, sizeof(sigint_action));
    sigint_action.sa_handler = sigint_handler;
    sigaction(SIGINT, &sigint_action, NULL);

    i2c_fd = open(I2C_BUS, O_RDWR);
    if (i2c_fd < 0) {
        perror("Failed to open I2C bus");
        return 1;
    }

    if (ioctl(i2c_fd, I2C_SLAVE, SENSOR_ADDRESS) < 0) {
        perror("Failed to set I2C slave address");
        close(i2c_fd);
        return 1;
    }

    log_file = fopen("airflow_log.txt", "w");
    if (log_file == NULL) {
        perror("Failed to open log file");
        close(i2c_fd);
        return 1;
    }

    uint16_t raw_flow;
    double flow;
    struct timespec ts;
    while (1) {
        for (int retry = 0; retry < RETRY_COUNT; ++retry) {
            if (write(i2c_fd, &FLOW_SENSOR_REG, 0) < 0) {
                perror("Failed to write to I2C device");
                continue;
            }

            if (read(i2c_fd, &raw_flow, 2) < 0) {
                perror("Failed to read from I2C device");
                continue;
            }

            raw_flow &= FLOW_SENSOR_MASK;
            flow = (raw_flow - FLOW_SENSOR_OFFSET) * FLOW_SENSOR_CONVERSION;
            clock_gettime(CLOCK_REALTIME, &ts);
            fprintf(log_file, "%ld.%09ld: %.2f SLPM\n", ts.tv_sec, ts.tv_nsec, flow);
            fflush(log_file);
            break;
        }

        sleep(1);
    }

    fclose(log_file);
    close(i2c_fd);
    return 0;
}

#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <string.h>
#include <unistd.h>
#include <fcntl.h>
#include <sys/ioctl.h>
#include <linux/i2c-dev.h>
#include <time.h>

#define I2C_BUS "/dev/i2c-1"
#define AS7341_ADDRESS 0x39
#define WHO_AM_I 0x24
#define ENABLE 0x80
#define CFG6 0xAF
#define SP_EN 0x01
#define F1 0x60
#define F8 0x73
#define LUX_SCALE 14
#define RATIO_SCALE 9
#define CHAN_SCALE 10
#define K1T 0x0040
#define B1T 0x01F2
#define M1T 0x01BE
#define K2T 0x0080
#define B2T 0x0218
#define M2T 0x02D1
#define CPLT 0x40
#define ERROR 0x20
#define PON 0x01

FILE *log_file;

int i2c_write(int file, uint8_t *buf, int len) {
    int ret = write(file, buf, len);
    if (ret != len) {
        perror("Failed to write to the i2c bus");
        return -1;
    }
    return 0;
}

int i2c_read(int file, uint8_t *buf, int len) {
    int ret = read(file, buf, len);
    if (ret != len) {
        perror("Failed to read from the i2c bus");
        return -1;
    }
    return 0;
}

int main() {
    int file;
    uint8_t buf[2];
    uint16_t data;
    int lux, ratio, chan;
    struct timespec ts;

    file = open(I2C_BUS, O_RDWR);
    if (file < 0) {
        perror("Failed to open the i2c bus");
        return -1;
    }

    if (ioctl(file, I2C_SLAVE, AS7341_ADDRESS) < 0) {
        perror("Failed to acquire bus access and/or talk to slave");
        return -1;
    }

    buf[0] = WHO_AM_I;
    if (i2c_write(file, buf, 1) < 0) return -1;
    if (i2c_read(file, buf, 1) < 0) return -1;
    if (buf[0] != 0x19) {
        printf("Device not found\n");
        return -1;
    }

    buf[0] = ENABLE;
    buf[1] = PON;
    if (i2c_write(file, buf, 2) < 0) return -1;

    buf[0] = CFG6;
    buf[1] = SP_EN;
    if (i2c_write(file, buf, 2) < 0) return -1;

    log_file = fopen("spectral_log.csv", "w");
    if (log_file == NULL) {
        perror("Failed to open log file");
        return -1;
    }

    while (1) {
        buf[0] = F1;
        if (i2c_write(file, buf, 1) < 0) return -1;
        if (i2c_read(file, buf, 2) < 0) return -1;
        data = (buf[0] << 8) | buf[1];
        chan = data >> CHAN_SCALE;

        buf[0] = F8;
        if (i2c_write(file, buf, 1) < 0) return -1;
        if (i2c_read(file, buf, 2) < 0) return -1;
        data = (buf[0] << 8) | buf[1];
        ratio = data >> RATIO_SCALE;

        buf[0] = CPLT;
        if (i2c_write(file, buf, 1) < 0) return -1;
        if (i2c_read(file, buf, 2) < 0) return -1;
        data = (buf[0] << 8) | buf[1];
        lux = data >> LUX_SCALE;

        clock_gettime(CLOCK_REALTIME, &ts);
        fprintf(log_file, "%ld.%09ld,%d,%d,%d\n", ts.tv_sec, ts.tv_nsec, chan, ratio, lux);

        sleep(5);
    }

    fclose(log_file);
    close(file);
    return 0;
}

#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <unistd.h>
#include <fcntl.h>
#include <signal.h>
#include <sys/ioctl.h>
#include <linux/i2c-dev.h>
#include <time.h>
#include <libgen.h>
#include <getopt.h>

#define I2C_ADDRESS 0x37
#define I2C_FILE "/dev/i2c-1"
#define DEFAULT_INTERVAL 1
#define DEFAULT_FILENAME "seismic_data.csv"
#define RETRIES 3
#define BACKOFF 10e-3
#define SENSITIVITY 0.000244

int i2c_fd;
FILE *csv_fd;
int interval;
char *filename;
unsigned char i2c_address;

void cleanup(int signum) {
    fclose(csv_fd);
    close(i2c_fd);
    exit(signum);
}

int i2c_write(unsigned char reg, unsigned char data) {
    int retries = RETRIES;
    while (retries--) {
        if (ioctl(i2c_fd, I2C_SLAVE, i2c_address) < 0) {
            return -1;
        }
        if (write(i2c_fd, &reg, 1) != 1 || write(i2c_fd, &data, 1) != 1) {
            usleep(BACKOFF * 1e6);
            continue;
        }
        return 0;
    }
    return -1;
}

int i2c_read(unsigned char reg, unsigned char *data, int len) {
    int retries = RETRIES;
    while (retries--) {
        if (ioctl(i2c_fd, I2C_SLAVE, i2c_address) < 0) {
            return -1;
        }
        if (write(i2c_fd, &reg, 1) != 1 || read(i2c_fd, data, len) != len) {
            usleep(BACKOFF * 1e6);
            continue;
        }
        return 0;
    }
    return -1;
}

int main(int argc, char *argv[]) {
    struct option long_options[] = {
        {"address", required_argument, 0, 'a'},
        {"interval", required_argument, 0, 'i'},
        {"filename", required_argument, 0, 'f'},
        {0, 0, 0, 0}
    };

    i2c_address = I2C_ADDRESS;
    interval = DEFAULT_INTERVAL;
    filename = DEFAULT_FILENAME;

    int opt;
    while ((opt = getopt_long(argc, argv, "a:i:f:", long_options, NULL)) != -1) {
        switch (opt) {
            case 'a':
                i2c_address = (unsigned char)strtol(optarg, NULL, 0);
                break;
            case 'i':
                interval = (int)strtol(optarg, NULL, 0);
                break;
            case 'f':
                filename = optarg;
                break;
            default:
                fprintf(stderr, "Usage: %s [-a address] [-i interval] [-f filename]\n", basename(argv[0]));
                return EXIT_FAILURE;
        }
    }

    if ((i2c_fd = open(I2C_FILE, O_RDWR)) < 0) {
        perror("Failed to open the i2c bus");
        return EXIT_FAILURE;
    }

    if ((csv_fd = fopen(filename, "w")) == NULL) {
        perror("Failed to open the CSV file");
        return EXIT_FAILURE;
    }

    signal(SIGINT, cleanup);
    signal(SIGTERM, cleanup);

    fprintf(csv_fd, "timestamp,x_g,y_g,z_g\n");

    while (1) {
        unsigned char data[6];
        if (i2c_read(0x28, data, 6) < 0) {
            fprintf(stderr, "Failed to read from the sensor\n");
            continue;
        }

        int16_t x = (data[1] << 8) | data[0];
        int16_t y = (data[3] << 8) | data[2];
        int16_t z = (data[5] << 8) | data[4];

        double x_g = x * SENSITIVITY;
        double y_g = y * SENSITIVITY;
        double z_g = z * SENSITIVITY;

        time_t now = time(NULL);
        struct tm *timeinfo = localtime(&now);
        char timestamp[20];
        strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", timeinfo);

        fprintf(csv_fd, "%s,%f,%f,%f\n", timestamp, x_g, y_g, z_g);

        sleep(interval);
    }

    return EXIT_SUCCESS;
}

#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <unistd.h>
#include <fcntl.h>
#include <sys/ioctl.h>
#include <sys/socket.h>
#include <netinet/in.h>
#include <arpa/inet.h>
#include <signal.h>
#include <libgpiod.h>

#define I2C_SLAVE 0x0703
#define BH1750_POWER_ON 0x01
#define BH1750_CONTINUOUS_HIGH_RES_MODE 0x10
#define BH1750_DEFAULT_ADDRESS 0x23
#define MULTICAST_ADDR "239.255.255.250"
#define MULTICAST_PORT 5000
#define UDP_TTL 1

static int i2c_fd = -1;
static int sock_fd = -1;

static void cleanup(int signum) {
    if (i2c_fd != -1) close(i2c_fd);
    if (sock_fd != -1) close(sock_fd);
    exit(signum);
}

static int write_i2c(int fd, uint8_t *data, size_t len) {
    ssize_t bytes_written = write(fd, data, len);
    if (bytes_written != len) {
        perror("Failed to write to I2C device");
        return -1;
    }
    return 0;
}

static int read_i2c(int fd, uint8_t *data, size_t len) {
    ssize_t bytes_read = read(fd, data, len);
    if (bytes_read != len) {
        perror("Failed to read from I2C device");
        return -1;
    }
    return 0;
}

static int init_i2c() {
    i2c_fd = open("/dev/i2c-1", O_RDWR);
    if (i2c_fd < 0) {
        perror("Failed to open I2C device");
        return -1;
    }

    if (ioctl(i2c_fd, I2C_SLAVE, BH1750_DEFAULT_ADDRESS) < 0) {
        perror("Failed to set I2C slave address");
        close(i2c_fd);
        return -1;
    }

    uint8_t power_on_cmd = BH1750_POWER_ON;
    if (write_i2c(i2c_fd, &power_on_cmd, 1) < 0) {
        close(i2c_fd);
        return -1;
    }

    uint8_t mode_cmd = BH1750_CONTINUOUS_HIGH_RES_MODE;
    if (write_i2c(i2c_fd, &mode_cmd, 1) < 0) {
        close(i2c_fd);
        return -1;
    }

    return 0;
}

static int init_udp() {
    struct sockaddr_in addr;
    memset(&addr, 0, sizeof(addr));
    addr.sin_family = AF_INET;
    addr.sin_addr.s_addr = inet_addr(MULTICAST_ADDR);
    addr.sin_port = htons(MULTICAST_PORT);

    sock_fd = socket(AF_INET, SOCK_DGRAM, 0);
    if (sock_fd < 0) {
        perror("Failed to create UDP socket");
        return -1;
    }

    if (setsockopt(sock_fd, IPPROTO_IP, IP_MULTICAST_TTL, &UDP_TTL, sizeof(UDP_TTL)) < 0) {
        perror("Failed to set UDP TTL");
        close(sock_fd);
        return -1;
    }

    if (bind(sock_fd, (struct sockaddr *)&addr, sizeof(addr)) < 0) {
        perror("Failed to bind UDP socket");
        close(sock_fd);
        return -1;
    }

    return 0;
}

static void read_sensor() {
    uint8_t raw_data[2];
    if (read_i2c(i2c_fd, raw_data, 2) < 0) {
        return;
    }

    uint16_t raw = (raw_data[0] << 8) | raw_data[1];
    float lux = raw / 1.2;

    char buffer[32];
    sprintf(buffer, "%.2f", lux);

    if (sendto(sock_fd, buffer, strlen(buffer), 0, NULL, 0) < 0) {
        perror("Failed to send UDP packet");
    }
}

int main() {
    signal(SIGINT, cleanup);
    signal(SIGTERM, cleanup);

    if (init_i2c() < 0 || init_udp() < 0) {
        cleanup(1);
    }

    while (1) {
        read_sensor();
        sleep(1);
    }

    return 0;
}

#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <unistd.h>
#include <fcntl.h>
#include <errno.h>
#include <termios.h>
#include <signal.h>
#include <pigpio.h>

#define BAUDRATE B921600
#define UART "/dev/ttyS0"
#define MAGIC_WORD_1 0x0204
#define MAGIC_WORD_2 0x0306
#define MAGIC_WORD_3 0x0805
#define MAGIC_WORD_4 0x0709
#define TLV_TYPE 0x01
#define TLV_LENGTH 0x08
#define OBJECT_INDEX_OFFSET 0x02
#define RANGE_OFFSET 0x04
#define VELOCITY_OFFSET 0x06

volatile sig_atomic_t stop = 0;

void signal_handler(int signum) {
    stop = 1;
}

int main() {
    int uart_fd;
    struct termios options;
    FILE *csv_file;
    uint8_t buffer[256];
    uint8_t magic_word[4] = {MAGIC_WORD_1, MAGIC_WORD_2, MAGIC_WORD_3, MAGIC_WORD_4};
    uint8_t *p = buffer;
    uint8_t *end = buffer + sizeof(buffer);
    uint8_t *magic = magic_word;
    uint8_t object_index, range, velocity;
    uint32_t timestamp;
    int i;

    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialization failed\n");
        return EXIT_FAILURE;
    }

    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    uart_fd = open(UART, O_RDWR | O_NOCTTY | O_NDELAY);
    if (uart_fd < 0) {
        fprintf(stderr, "failed to open UART: %s\n", strerror(errno));
        gpioTerminate();
        return EXIT_FAILURE;
    }

    tcgetattr(uart_fd, &options);
    cfsetispeed(&options, BAUDRATE);
    cfsetospeed(&options, BAUDRATE);
    options.c_cflag |= (CLOCAL | CREAD);
    options.c_cflag &= ~CSIZE;
    options.c_cflag |= CS8;
    options.c_cflag &= ~PARENB;
    options.c_cflag &= ~CSTOPB;
    options.c_iflag &= ~(IXON | IXOFF | IXANY);
    options.c_iflag &= ~(INLCR | IGNCR | ICRNL);
    options.c_oflag &= ~OPOST;
    tcsetattr(uart_fd, TCSANOW, &options);

    csv_file = fopen("radar_data.csv", "w");
    if (!csv_file) {
        fprintf(stderr, "failed to open CSV file: %s\n", strerror(errno));
        gpioTerminate();
        close(uart_fd);
        return EXIT_FAILURE;
    }

    fprintf(csv_file, "timestamp,object_index,range_m,velocity_mps\n");

    while (!stop) {
        int n = read(uart_fd, buffer, sizeof(buffer));
        if (n < 0) {
            fprintf(stderr, "failed to read UART: %s\n", strerror(errno));
            break;
        }

        for (p = buffer; p < buffer + n; ++p) {
            if (*p == *magic) {
                ++magic;
                if (magic == magic_word + sizeof(magic_word)) {
                    magic = magic_word;
                    if (p - buffer >= TLV_LENGTH) {
                        object_index = buffer[OBJECT_INDEX_OFFSET];
                        range = buffer[RANGE_OFFSET];
                        velocity = buffer[VELOCITY_OFFSET];
                        timestamp = (uint32_t)time(NULL);
                        fprintf(csv_file, "%u,%u,%u,%u\n", timestamp, object_index, range, velocity);
                    }
                }
            } else {
                magic = magic_word;
            }
        }
    }

    fclose(csv_file);
    close(uart_fd);
    gpioTerminate();

    return EXIT_SUCCESS;
}

#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <fcntl.h>
#include <termios.h>
#include <unistd.h>
#include <errno.h>
#include <sys/select.h>
#include <signal.h>
#include <time.h>

#define UART "/dev/serial0"
#define BAUDRATE B115200
#define INTERBYTE_TIMEOUT 0.5
#define SELECT_TIMEOUT 2
#define MAX_LINE_LENGTH 256

volatile sig_atomic_t running = 1;

void handle_sigint(int signum) {
    running = 0;
}

int main() {
    struct termios options;
    int uart_fd, bytes_read, line_length;
    char line_buffer[MAX_LINE_LENGTH];
    char *line_end;
    struct timespec ts;

    // Open UART
    uart_fd = open(UART, O_RDONLY | O_NOCTTY | O_NDELAY);
    if (uart_fd == -1) {
        perror("Failed to open UART");
        return EXIT_FAILURE;
    }

    // Configure UART
    tcgetattr(uart_fd, &options);
    cfsetispeed(&options, BAUDRATE);
    cfsetospeed(&options, BAUDRATE);
    options.c_cflag |= (CLOCAL | CREAD);
    options.c_cflag &= ~PARENB;
    options.c_cflag &= ~CSTOPB;
    options.c_cflag &= ~CSIZE;
    options.c_cflag |= CS8;
    options.c_lflag &= ~(ICANON | ECHO | ECHOE | ISIG);
    options.c_iflag &= ~(IXON | IXOFF | IXANY);
    options.c_oflag &= ~OPOST;
    options.c_cc[VTIME] = 0;
    options.c_cc[VMIN] = 0;
    tcsetattr(uart_fd, TCSANOW, &options);

    // Set up signal handler
    signal(SIGINT, handle_sigint);
    signal(SIGTERM, handle_sigint);

    // Main loop
    while (running) {
        fd_set read_fds;
        struct timeval tv;
        int ret;

        // Set up select
        FD_ZERO(&read_fds);
        FD_SET(uart_fd, &read_fds);
        tv.tv_sec = SELECT_TIMEOUT;
        tv.tv_usec = 0;

        // Wait for data
        ret = select(uart_fd + 1, &read_fds, NULL, NULL, &tv);
        if (ret == -1) {
            perror("select");
            break;
        } else if (ret == 0) {
            continue;
        }

        // Read data
        line_length = 0;
        while ((bytes_read = read(uart_fd, line_buffer + line_length, MAX_LINE_LENGTH - line_length - 1)) > 0) {
            line_length += bytes_read;
            if ((line_end = strchr(line_buffer, '\n')) != NULL) {
                *line_end = '\0';
                printf("Timestamp: %s, Range: %s meters\n", strtok(line_buffer, ","), strtok(NULL, ","));
                memmove(line_buffer, line_end + 1, strlen(line_end + 1) + 1);
                line_length = strlen(line_buffer);
            }
        }
        if (bytes_read == -1) {
            perror("read");
            break;
        }
    }

    // Clean up
    close(uart_fd);
    return EXIT_SUCCESS;
}

#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <signal.h>
#include <time.h>
#include <pigpio.h>

#define SENSOR_GPIO_1 4
#define SENSOR_GPIO_2 17
#define SENSOR_GPIO_3 27
#define SERIAL_PORT "/dev/ttyAMA0"
#define BAUD_RATE 115200
#define SERIAL_FLAGS (0)
#define SERIAL_TIMEOUT (0)
#define PERIOD 100 // 10 Hz

void close_serial(int pi, int serial_fd) {
    if (serial_fd >= 0) {
        serialClose(pi, serial_fd);
    }
}

void close_pigpio(int pi) {
    if (pi >= 0) {
        gpioTerminate();
    }
}

void handle_signal(int signal) {
    printf("Signal %d received, exiting...\n", signal);
    exit(1);
}

int main() {
    int pi = -1;
    int serial_fd = -1;
    int sensor_1, sensor_2, sensor_3;
    struct timespec ts = {0, PERIOD * 1000 * 1000};

    signal(SIGINT, handle_signal);
    signal(SIGTERM, handle_signal);

    if ((pi = gpioInitialise()) < 0) {
        fprintf(stderr, "pigpio initialization failed\n");
        goto cleanup;
    }

    if ((serial_fd = serialOpen(SERIAL_PORT, BAUD_RATE)) < 0) {
        fprintf(stderr, "Failed to open serial port\n");
        goto cleanup;
    }

    if (gpioSetMode(pi, SENSOR_GPIO_1, PI_INPUT) < 0) {
        fprintf(stderr, "Failed to set mode for GPIO %d\n", SENSOR_GPIO_1);
        goto cleanup;
    }

    if (gpioSetMode(pi, SENSOR_GPIO_2, PI_INPUT) < 0) {
        fprintf(stderr, "Failed to set mode for GPIO %d\n", SENSOR_GPIO_2);
        goto cleanup;
    }

    if (gpioSetMode(pi, SENSOR_GPIO_3, PI_INPUT) < 0) {
        fprintf(stderr, "Failed to set mode for GPIO %d\n", SENSOR_GPIO_3);
        goto cleanup;
    }

    while (1) {
        sensor_1 = gpioRead(pi, SENSOR_GPIO_1);
        sensor_2 = gpioRead(pi, SENSOR_GPIO_2);
        sensor_3 = gpioRead(pi, SENSOR_GPIO_3);

        if (sensor_1 < 0 || sensor_2 < 0 || sensor_3 < 0) {
            fprintf(stderr, "Failed to read sensor values\n");
            continue;
        }

        printf("Sensor 1: %d, Sensor 2: %d, Sensor 3: %d\n", sensor_1, sensor_2, sensor_3);

        if (sensor_1 == 0 && sensor_2 == 0 && sensor_3 == 0) {
            if (serialWrite(pi, serial_fd, "EMERGENCY STOP!\n", strlen("EMERGENCY STOP!\n")) < 0) {
                fprintf(stderr, "Failed to write to serial port\n");
                continue;
            }
        }

        nanosleep(&ts, NULL);
    }

cleanup:
    close_serial(pi, serial_fd);
    close_pigpio(pi);
    return 1;
}
